COLLDATA("nasai","ur",[[4498,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم انصار کے ایک آدمی کی زمین کے پاس سے گزرے جسے آپ جانتے تھے کہ وہ ضرورت مند ہے، پھر فرمایا: \"یہ زمین کس کی ہے؟\" اس نے کہا: فلاں کی ہے، اس نے مجھے کرائے پر دی ہے، آپ نے فرمایا: \"اگر اس نے اسے اپنے بھائی کو عطیہ کے طور پردے دی ہوتی (تو اچھا ہوتا)\"، تب رافع بن خدیج رضی اللہ عنہ نے انصار کے پاس آ کر کہا بولے: رسول اللہ صلی اللہ علیہ وسلم نے تمہیں ایک ایسی چیز سے روکا ہے جو تمہارے لیے نفع بخش تھی، لیکن رسول اللہ صلی اللہ علیہ وسلم کی اطاعت تمہارے لیے سب سے زیادہ مفید اور نفع بخش ہے۔\nرافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ ہماری طرف رسول اللہ صلی اللہ علیہ وسلم نکل کر آئے تو ہمیں ایک ایسی چیز سے روک دیا جو ہمارے لیے نفع بخش اور مفید تھی، لیکن رسول اللہ صلی اللہ علیہ وسلم کا حکم ہمارے لیے زیادہ بہتر ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی کوئی زمین ہو تو وہ خود اس میں کھیتی کرے یا اسے چھوڑ دے یا اسے (کسی کو) دیدے\"۔ اور اس بات کی دلیل کہ یہ حدیث طاؤس نے (رافع رضی اللہ عنہ سے خود) نہیں سنی ہے آنے والی حدیث ہے۔\nجابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی کوئی زمین ہو تو وہ اس میں کھیتی کرے یا اپنے بھائی سے اس میں (بلا کرایہ لیے)کھیتی کرائے لیکن اسے اپنے بھائی کو کرائیے پر نہ دے\"۔\nرافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ و مزابنہ سے منع فرمایا ہے۔ اسے قاسم بن محمد نے بھی رافع بن خدیج رضی اللہ عنہ سے روایت کیا ہے۔\nعثمان بن مرہ کہتے ہیں کہ میں نے قاسم سے زمین کرائے پر دینے کے سلسلے میں پوچھا تو وہ بولے: رافع بن خدیج نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین کرائے پر اٹھانے سے منع فرمایا ہے ۱؎۔ اس حدیث کی روایت میں سعید بن مسیب پر اختلاف واقع ہوا ہے۔\n§وضاحت\n۱؎: یعنی: خود اس زمین سے پیدا ہونے والے غلہ کے بدلے کرایہ اٹھانے سے منع فرمایا، کیونکہ خود رافع رضی اللہ عنہ نے سونا چاندی کے بدلے کرایہ پر دینے کا فتوی دیا ہے۔ نیز مرفوعاً بھی روایت کی ہے :(دیکھئیے حدیث رقم ۳۹۲۱، و ۳۹۲۹ )۔\nابوجعفر خطمی جن کا نام عمیر بن یزید ہے، کہتے ہیں کہ میرے چچا نے مجھے اور اپنے ایک بچے کو سعید بن مسیب کے پاس بٹائی پر زمین دینے کے بارے میں مسئلہ پوچھنے کے لیے بھیجا، تو انہوں نے کہا: ابن عمر رضی اللہ عنہما اس میں کوئی حرج نہیں سمجھتے تھے یہاں تک کہ انہیں رافع بن خدیج رضی اللہ عنہ سے مروی حدیث پہنچی تو وہ ان سے ملے۔ رافع رضی اللہ عنہ نے کہا: نبی اکرم صلی اللہ علیہ وسلم بنی حارثہ کے پاس آئے تو ایک کھیتی کو دیکھ کر فرمایا: \"ظہیر کی کھیتی کس قدر اچھی ہے!\" لوگوں نے عرض کیا: یہ (کھیتی) ظہیر کی نہیں ہے۔ آپ نے فرمایا: \"کیا یہ ظہیر کی زمین نہیں ہے؟\" لوگوں نے کہا: کیوں نہیں! لیکن انہوں نے اسے بٹائی پر اٹھا رکھا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی کھیتی لے لو اور اس پر آنے والی خرچ اسے دے دو\"، تو ہم نے اپنی کھیتی لے لی اور ان کا خرچہ انہیں لوٹا دیا۔ اسے طارق بن عبدالرحمٰن نے بھی سعید بن مسیب سے روایت کیا اور اس میں طارق سے روایت کرنے میں اختلاف ہوا ہے۔\nام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان شخص کا خون حلال نہیں مگر تین صورتوں میں: ایک تو شادی شدہ زانی کو رجم کیا جائے گا، دوسرے وہ شخص جس نے کسی شخص کو جان بوجھ کر قتل کیا تو اسے قتل کیا جائے گا، تیسرے وہ شخص جو اللہ اور اس کے رسول سے لڑتے ہوئے اسلام سے مرتد ہو جائے، تو اسے سولی دی جائے گی، یا جلا وطن کر دیا جائے گا\"۔\n§وضاحت\n۱؎: «من الإسلام» کا ٹکڑا سنن أبی داود میں نہیں ہے، اسی بنا پر امام خطابی نے اس حدیث کا مصداق مسلم محاربین :(جنگجوؤں ) اور باغیوں کو قرار دیا ہے، جن کی سزاؤں کا بیان حدیث نمبر ۴۰۲۹ کے حاشیہ میں گزر چکا ہے، تینوں سزاؤں میں :(امام کو اختیار دینے کی بات کافر محاربین کے بارے میں ہے ) ۲؎: گویا محاربین اسلام کے سلسلہ میں اختیار ہے کہ امام انہیں قتل کرے، سولی دے یا جلا وطن کرے۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تجارتی قافلے سے آگے جا کر ملنے سے منع فرمایا۔\nأَخْبَرَنَا إِسْحَاق بْنُ إِبْرَاهِيمَ، قَالَ: قُلْتُ: لِأَبِي أُسَامَةَ، أَحَدَّثَكُمْ عُبَيْدُ اللَّهِ، عَنْ نَافِعٍ، عَنْ ابْنِ عُمَرَ، قَالَ: \"نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ تَلَقِّي الْجَلْبِ حَتَّى يَدْخُلَ بِهَا السُّوقَ\"؟. فَأَقَرَّ بِهِ أَبُو أُسَامَةَ، وَقَالَ: نَعَمْ.\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ آگے جا کر قافلے سے ملا جائے یہاں تک کہ وہ خود بازار آئے (اور وہاں کا نرخ(بھاؤ) معلوم کر لے)۔ ابواسامہ نے اس کی تصدیق کی اور کہا: جی ہاں۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ کوئی تاجر منڈی سے باہر جا کر تجارتی قافلے کو ملے۔","f2":"تفصیل کے لیے دیکھئے: حدیث: ۴۴۹۶، فائدہ: ۱۔"}],[4499,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے «حقل» سے منع فرمایا۔\n§وضاحت\n۱؎: «حقل» کی تفصیل اوپر گزر چکی ہے مقصد تہائی اور چوتھائی کے بٹائی دینے کا معاملہ ہے۔","الألباني: صحيح لغيره"],[4500,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا کہ کوئی آگے جا کر تجارتی قافلے سے ملے، اور کوئی شہری کسی دیہاتی کا سامان بیچے،(راوی طاؤس کہتے ہیں:) میں نے ابن عباس سے کہا: اس قول \"کوئی شہری دیہاتی کا سامان نہ بیچے\" کا کیا مطلب ہے؟ انہوں نے کہا: یعنی شہری دلال نہ بنے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ کوئی تاجر منڈی اور بازار سے باہر ہی تجارتی قافلے کو ملے یا کوئی شہری کسی دیہاتی کا مال بیچے۔ (راویٔ حدیث جنابِ طائوس نے کہا کہ) میں نے حضرت ابن عباس رضی اللہ عنہ سے پوچھا: شہری کو دیہاتی کا مال بیچنے سے روکنے کا کیا مطلب ہے؟ انہوں نے فرمایا: وہ اس کا دلال نہ بنے۔","f2":"’’دلال نہ بنے‘‘ یعنی کمیشن لے کر اس کی چیز نے بیچے کیونکہ اس طرح مہنگالی ہو گی۔ کمیشن کی رقم بھی تو اس چیز کی قیمت میں شامل ہو گی۔ ہاں، اگر وہ ازراہ ہمدردی دیہاتی کا سامان بیچے تاکہ اسے اپنی سادگی کی بنا پر کوئی نقصان نہ ہو اور اس سے کمیشن وصول نہ کرے تو کوئی حرج نہیں کیونکہ اس طرح مہنگائی کا خطرہ نہیں۔ کمیشن ہی مہنگائی کا سبب ہے دلال کو آج کل کمیشن ایجنٹ کہا جاتا ہے۔"}],[4501,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آگے جا کر تجارتی قافلے سے نہ ملو، جو اس سے جا کر ملا اور اس سے کوئی چیز خرید لی، جب اس کا مالک بازار آئے تو اسے اختیار ہو گا\" ۱؎۔\n§وضاحت\n۱؎: چاہے تو پہلی قیمت پر جو باہر نکل کر لگائی تھی فروخت کر دے یا بازار کی قیمت پر۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: ’’تجارتی قافلوں کو منڈی سے باہر جا کر نہ ملو۔ اگر کوئی تاجر منڈی سے باہر جا کر ملے گا اور قافلے سے کوئی چیز خریدے گا تو جب قافلہ بازار میں پہنچے گا، مالک کو اختیار ہو گا کہ وہ سودا واپس کر لے۔‘‘","f2":"’’واپس کر لے‘‘ کیونکہ تاجر نے اس سے دھوکا کیا ہے اور دھوکا شریعت میں جائز نہیں، لہٰذا وہ بیع فسخ ہو سکتی ہے بشرطیکہ مالک کو یہ محسوس ہو کہ مجھے دھوکا دے کر مال بازار سے کم قیمت پر خریدا گیا ہے۔"}],[4502,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی شہری کسی دیہاتی کا مال ہرگز نہ بیچے، اور نہ بھاؤ پر بھاؤ بڑھانے کا کام کرو، اور نہ آدمی اپنے (مسلمان) بھائی کے بھاؤ پر بھاؤ لگائے، اور نہ (مسلمان) بھائی کی شادی کے پیغام پر پیغام بھیجے اور نہ عورت اپنی سوکن کی طلاق کا مطالبہ کرے تاکہ جو اس کے برتن میں ہے اسے بھی اپنے لیے انڈیل لے (یعنی جو اس کی قسمت میں تھا وہ اسے مل جائے) بلکہ (بلا مطالبہ و شرط) نکاح کرے، کیونکہ اسے وہی ملے گا جو اس کی قسمت میں اللہ تعالی نے لکھا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شہری کسی دیہاتی کا مال فروخت نہ کرے، دھوکے سے بھائو نہ بڑھائو، کوئی شخص اپنے مسلمان بھائی کے بھائو پر بھائو نہ کرے اور نہ اس کے پیغام نکاح پر پیغام بھیجے اور نہ کوئی عورت اپنی (سوکن) بہن کی طلاق کا مطالبہ کرے تاکہ اس کے برتن کو انڈیل دے بلکہ اسے چاہیے کہ وہ بھی نکاح کرے جو اس کی قسمت میں اللہ تعالیٰ نے لکھا ہے، اسے مل جائے گا۔‘‘","f2":"(۱) مصنف رحمہ اللہ نے جو باب قائم کیا ہے اس کا مطلب یہ ہے کہ کسی بھی مسلمان کو یہ حق نہیں پہنچتا کہ وہ دوسرے مسلمان بھائی کے سودے پر سودا کرے۔ یہ بات یاد رہنا چاہیے کہ سودے میں خرید و فروخت، دونوں چیزیں ہی آتی ہیں۔ تفصیل اس طرح ہے کہ کوئی شخص خریدار سے یہ کہے کہ اس سے یہ چیز نہ خرید۔ میں تجھے اس سے سستی دیتا ہوں اور نہ کوئی بیچنے والے سے یہ کہے کہ اسے نہ بیچ، میں یہ چیز اس سے زیادہ قیمت میں تجھ سے خرید لوں گا۔ یہ دونوں کام حرام ہیں۔ (۲) یہ حدیث مبارکہ اس سے بھی روکتی ہے کہ کسی دیہاتی شخص کی چیز کوئی شہری بیچے، اس لیے کہ شہری کے لیے حرام ہے کہ وہ دیہاتی سے کہے کہ تو اپنا مال میرے پاس رکھ دے جب قیمت زیادہ ہو جائے گی، میں تیری چیز مہنگے داموں بیچ دوں گا۔ ہاں، اگر دیہاتی شخص کو منڈی وغیرہ کے بھائو کا کوئی علم نہیں یا یہ خطرہ ہے کہ خیردار اسے ’’پینڈو‘‘ سمجھتے ہوئے دھوکا دے کر اس کی چیز سستے داموں اس سے خرید لے گا او اسے لاعلمی کی وجہ سے اپنی چیز کی اصل اور مناسب قیمت بھی نہیں ملے گی اور کوئی شہری ازراہِ ہمدردی اس کا سودا، کما حقہ، مناسب قیمت کے عوض بیچ دے تو یہ عمل قابل تعریف ہے اور ایسا شخص عنداللہ اجر و ثواب کا حق دار ہے۔ ممانعت وہاں ہے جہاں شہری اپنا اُلو سیدھا کرنے کے چکر میں ہو، یدہاتی کی خیر خواہی سرے سے مطلوب ہی نہ ہو۔ (۳) یہ حدیث مبارکہ بیع نجش کی حرمت کی بھی دلیل ہے۔ بیع نجش کی صورت یہ ہوتی ہے کہ ایک شخص کا مقصد چیز خریدنا بالکل نہیں ہوتا لیکن دو سودا کرنے والوں کے پاس آ کر وہ بکنے والی چیز کی زیادہ قیمت لگا دیتا ہے تاکہ خریدار دھوکا کھا جائے اور ایک کم قیمت چیز، زیادہ قیمت میں خرید لے۔ ایسے عموماً دکانداروں کے ’’پالتو‘‘ ایجنٹ ہی ہوتے ہیں، وہ اپنی اس ناجائز حرکت اور غیر شرعی کام کے باقاعدہ پیسے لیتے ہیں۔ خلاصۂ کلام یہ ہے کہ ہر وہ صورت ناجائز اور حرام ہے جس سے دوسرے مسلمان کو نقصان پہنچانا مقصود ہو اور وہ صورت جائز اور ممدوح ہے جس میں دوسرے مسلمان کی خیر خواہی مطلوب ہو اور اس سے شریعت کا کوئی تقاضا بھی مجروح نہ ہوتا ہو۔ و اللہ اعلم۔ (۴) یہ حدیث مبارکہ اس اہم اصول کی بھی صریح دلیل ہے کہ شریعت نے ہر اس سبب اور ذریعے کو قطعی طور پر جڑ سے اکھاڑ پھینکا ہے جو باہمی بغض و عناد کی طرف لے جانے والا ہو یا بخیلی، حسد اور کینے وغیرہ تک پہنچا دینے والا ہو۔ الغرض! شریعت مطہرہ نے ہر وہ دروازہ مسدود کر دیا ہے جو مذکورہ یا ان جیسی دیگر اشیاء کی طرف کھلتا ہو۔ (۵) ’‘’برتن انڈیل دے‘‘ یعنی اس کو نکاح کے فوائد سے محروم کر دے۔ باقی دیکھئے روایت: ۴۴۹۶۔"}],[4503,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی اپنے (مسلمان) بھائی کی بیع پر بیع نہ کرے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شخص اپنے (مسلمان) بھائی کے سودے پر سودا نہ کرے۔‘‘"}],[4504,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی اپنے بھائی کی بیع پر بیع نہ کرے یہاں تک کہ وہ اسے خرید لے یا چھوڑ دے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شخص اپنے بھائی کی بیع پر بیع نہ کرے حتی کہ وہ خرید لے یا چھوڑ دے۔‘‘","f2":"تفصیل کے لیے دیکھئے، حدیث: ۴۴۹۶، فائدہ: ۴۔"}],[4505,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے «حقل» (تہائی، چوتھائی پر بیع)، اور یہی مزابنہ ہے، سے منع فرمایا۔ ہشام نے معاویہ کی مخالفت کی ہے، انہوں نے اسے «عن یحیی عن ابی سلمہ عن جابر» کی سند سے روایت کیا ہے۔\nجابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بیع مزابنہ اور مخاضرہ سے منع فرمایا ہے۔ اور کہا مخاضرہ: پھل کو پکنے سے پہلے بیچنا اور مخابرہ (درخت کی) انگور کو خشک انگور کے اتنے اتنے صاع کے بدلے بیچنا ہے۔ اس میں عمرو بن ابی سلمہ نے یحیی کی مخالفت کی ہے، انہوں نے اسے اپنے باپ ابوسلمہ سے، اور ابوسلمہ نے، ابوہریرہ رضی اللہ عنہ کی حدیث سے روایت کیا ہے۔\nانس رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے ایک انصاری لڑکی کو اس کے ایک زیور کی لالچ میں قتل کر دیا، پھر اسے ایک کنوئیں میں پھینک دیا اور اس کا سر پتھر سے کچل دیا۔ تو نبی اکرم صلی اللہ علیہ وسلم نے حکم دیا کہ \"اسے پتھروں سے اس طرح مارا جائے کہ وہ ہلاک ہو جائے\"۔\nجریر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام بھاگ جائے تو اس کی نماز قبول نہیں ہو گی، اور اگر وہ مر گیا تو وہ کفر کی حالت میں مرا\"۔ اور جریر رضی اللہ عنہ کا ایک غلام بھاگ گیا تو آپ نے اسے پکڑا اور اس کی گردن اڑا دی۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرضی بھاؤ پر بھاؤ بڑھانے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: «نجش»: ایک چیز کا خریدنا مقصود نہ ہو لیکن دوسرے کو ٹھگانے کے لیے قیمت بڑھا دینا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم ن حیلے کے ساتھ بھائو بڑھانے سے منع فرمایا ہے۔","f2":"دیکھئے حدیث: ۴۴۹۶، فائدہ: ۳۔"}],[4506,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"آدمی اپنے (کسی مسلمان) بھائی کی بیع پر بیع نہ کرے، اور نہ کوئی شہری کسی دیہاتی کا سامان بیچے، اور نہ بھاؤ پر بھاؤ بڑھانے کا کام کرے، اور نہ آدمی اپنے بھائی کی بیع پر اضافہ کرے (کہ میں اس سامان کا تو اتنا اتنا مزید دوں گا) اور نہ کوئی عورت سوکن کی طلاق کا مطالبہ کرے تاکہ جو اس کے برتن میں ہے اسے اپنے برتن میں انڈیل لے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’کوئی آدمی اپنے (مسلمان) بھائی کے سودے پر سودا نہ کرے۔ کوئی شہری کسی دیہاتی کا مال نہ بیچے۔ بھائو بڑھانے کا حیلہ نہ کرو۔ کوئی شخص اپنے بھائی کے طے شدہ سودے سے زیادہ کا لالچ نہ دے اور کوئی عورت اپنی سوکن کی طلاق کا مطالبہ نہ کرے تاکہ اس کے برتن کو انڈیل دے۔‘‘"}],[4507,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کوئی شہری کسی دیہاتی کا سامان نہ بیچے، اور نہ کوئی فرضی بھاؤ پر بھاؤ بڑھانے کا کام کرے، اور نہ آدمی اپنے بھائی کی بیع پر اضافہ کرے، اور نہ عورت اپنی سوکن کی طلاق کا مطالبہ کرے تاکہ جو اس کے برتن میں ہے اسے اپنے میں انڈیل لے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شہری کسی دیہاتی کا مال نہ بیچے۔ بھائو نہ بڑھائو۔ کوئی شخص اپنے بھائی کے طے شدہ سودے پر اضافے کا لالچ نہ دے اور کوئی عورت اپنی سوکن کی طلاق کا مطالبہ نہ کرے تاکہ اس کے برتن کو انڈیل دے۔‘‘","f2":"’’اضافے کا لالچ نہ دے‘‘ یعنی ایک شخص سودا طے کر چکا ہے۔ اب کوئی اور شخص دکان دار کو زیادہ قیمت کا لالچ دے کر سابقہ سودا منسوخ کرنے اور اپنے ساتھ نیا سودا کرنے کی ترغیب دے، یہ منع ہے کیونکہ اس میں پہلے شخص کی حق تلفی ہے جو سودا کر چکا ہے۔ ایسی صورت میں دوسرا سودا معتبر نہیں ہو گا بلکہ کالعدم ہو گا۔"}],[4508,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک پیالا اور ایک کمبل نیلام کیا۔\n§وضاحت\n۱؎: انس رضی اللہ عنہ کی یہ حدیث سند کے لحاظ سے ضعیف ہے، مگر خرید و فروخت کے معاملات میں حرمت کی جو بنیاد ہے بیع مزایدہ :(نیلام ) پر صادق نہیں آتی، کیونکہ اس معاملہ میں بیچنے والے کی رائے کسی بھاؤ پر حتمی اور آخری نہیں اس لیے دوسرے خریدار کو بھاؤ بڑھا کر سودا کرنے میں کوئی حرج نہیں۔","الألباني: ضعيف",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ن ایک پیالہ اور ایک ٹاٹ نیلامی کے ذریعے سے بیچا تھا۔","f2":"(۱) اس کی تفصیل یہ ہے کہ ایک انصاری آدمی آپ کے پاس کچھ مانگنے آیا۔ آپ نے فرمایا: کیا تمہارے گھر میں کوئی چیز (موجود) ہے؟‘‘ اس نے کہا: ہاں، ایک کمبل ہے۔ ہم آدھا اوڑھ لیتے ہیں اور آدھا نیچے بچھاتے ہیں۔ اور ایک پیالہ ہے جس میں پانی پیتے ہیں۔ آپ نے فرمایا: ’’دونوں چیزیں میرے پاس لے آئو۔‘‘ وہ شخص دونوں چیزیں لے آتا تو نبی صلی اللہ علیہ وسلم نے دو درہم میں بیچ کر رقم اس انصاری کو دے دی اور فرمایا: ایک درہم کا کھانے پینے کا سامان خرید کر گھر والوں کو دے دو اور دوسرے درہم کا کلہاڑا خرید کر میرے پاس لے آئو۔‘‘ اس شخص نے اسی طرح کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس (کلہاڑے) میں اپنے ہاتھ مبارک سے دستہ ٹھونک دیا اور فرمایا: ’’جائو، لکڑیاں کاٹو اور بیچوں۔ پندہ دن تک میں تمہیں نہ دیکھوں۔‘‘ وہ شخص چلا گیا، لکڑیاں کاٹتا اور فروخت کرتا رہا۔ اس کے بعد پھر وہ آپ کی خدمت میں حاضر ہوا تو اس کے پاس دس درہم (جمع ہو چکے) تھے۔ آپ نے فرمایا: ’’کچھ رقم سے کھانے پینے کی چیزیں خرید لو اور کچھ رقم کا کپڑا خرید لو۔‘‘ پھر آپ نے فرمایا: ’’یہ (محنت مزدوری کر کے کمانا) تیرے لیے اس سے بہت بہتر ہے کہ تو قیامت کے دن آئے اور (لوگوں سے) مانگنے کی وجہ سے تیرا چہرہ داغ دار ہو … الخ۔ (سنن ابی داود، الزکاۃ، حدیث: ۱۶۴۱، و سنن ابن ماجہ، التجارات، حدیث: ۲۱۹۸) (۲) ’’نیلامی کے ذریعے بیچا‘‘ اسی مذکورہ حدیث میں یہ بھی ہے کہ آپ نے فرمایا: ’’انہیں کون خریدے گا؟‘‘ ایک شخص نے کہا: میں ایک درہم میں خریدتا ہوں۔ آپ نے فرمایا: ’’اس سے زیادہ کون دے گا؟‘‘ ایک دوسرے شخص نے کہا: میں دو درہم میں خریدتا ہوں۔ آپ نے اسے بیچ دیا۔ (سنن ابی داود، الزکاۃ، حدیث: ۱۶۴۱، و سنن ابن ماجہ: التجارات، حدیث: ۲۱۹۸) ایسی بیع کو نیلامی کی بیع کہا جاتا ہے جس میں بیچنے والا پہلی پیش کش پر راضی نہیں ہوتا، لہٰذا وہ نئے شخص سے نئے بھائو کا مطالبہ کرتا ہے، خواہ اسے دس مرتبہ ایسا کرنا پڑے۔ جس شخص کے بھائو کو وہ پسند کرے گا، اسے بیچ دے گا۔ اس بیع میں اصولی طور پر کوئی خرابی نہیں کیونکہ بیچنے والے نے پہلے خریدار کا بھائو رد کر دیا، لہٰذا نئے خریدار کے لیے نیا بھائو لگانا جائز ہے۔ بھائو پر بھائو اس وقت منع ہے جب خریدار اور بیچنے والا آپس میں بھائو کی بحت کر رہے ہوں اور رد و قبول کا فیصلہ نہ ہوا ہو، یا بھائو طے ہو گیا ہو اور دونوں نے قبول کر لیا ہو۔ نیلامی میں یہ خرابی نہیں، لہٰذا یہ بیع جائز ہے، البتہ اس سے مہنگائی پیدا ہونے کا امکان ہے کیونکہ بسا اوقات خریدار حضرات ضد میں بھائو بڑھانا شرع کر دیتے ہیں، اس لیے بلا ضرورت یہ طریقہ اختیار نہیں کرنا چاہیے۔ رسول اللہ صلی اللہ علیہ وسلم نے تو اس فقیر کے مفاد کی خاطر یہ طریقہ اختیار فرمایا تھا۔ یہ بیع اس وقت ہی ہونی چاہیے جب چیز فروخت کرنا مقصود ہو۔ اگر مقصد چیز فروخت کرنا نہ ہو بلکہ نیلامی صرف قیمت بڑھانے کے لیے ہو تو پھر نیلامی کی بیع ناجائز ہے۔ ہاں، اگر نیلامی سے مہنگائی نہ بڑھتی ہو تو اس بیع میں کوئی حرج نہیں۔"}],[4509,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: زمانہ جاہلیت میں منابذہ، ملامسہ، یا کنکری پھینک کر خرید و فروخت کا عام رواج تھا، ان سارے معاملات میں دھوکا، اور مال وقیمت کی تحدید و تعیین نہیں ہوتی تھی، اس لیے یہ معاملات جھگڑے کا سبب ہوتے ہیں یا کسی فریق کے سخت گھاٹے میں پڑ جانے سے اسے سخت تکلیف ہوتی ہے، اس لیے ان سے شریعت اسلامیہ نے منع کر دیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ سے منع فرمایا ہے۔","f2":"(۱) بیع ملامسہ حرام ہے کیونکہ اس میں نرا دھوکا ہی دھوکا ہے، جبکہ شرعاً اور اخلاقاً کسی کو دھوکا دینا قطعی طور پر ناجائز ہے۔ (۲) حدیث سے یہ بھی معلوم ہوتا ہے کہ بیع منابذہ بھی حرام ہے۔ اس کی وجہ بھی وہی ہے جو اوپر بیان ہو چکی ہے۔ (۳) اس حدیث مبارکہ سے یہ لطیف سا اشارہ بھی نکلتا ہے کہ ایام جاہلیت میں لوگوں کے مابین جو ناجائز معاملات رواج پذیر تھے اور ان کی وجہ سے ان میں باہمی کش مکش اور قطع تعلقی کی فضا بنی رہتی تھی، شارع علیہ السلام اس بات کے بے حد حریص تھے کہ اپنی امت کو ایسے تمام معاملات سے دور کر دیں جو ان کے باہمی تعلقات کے بگاڑ کا سبب بن سکتے تھے اور جس کی وجہ سے ان کے مابین منافرت اور بغض و عناد پیدا ہو سکتے تھے۔ بیع ملامسہ و منابذہ اور دیگر ممنوع بیوع بھی اسی قبیل سے ہیں۔ لیکن باوجود ایں ہمہ، روپے پیسے اور مال و دولت کی حرص و ہوس نے لوگوں کی اکثریت کو اندھا کر دیا ہے، دولت اکٹھی کرنے ہی کو اصل مقصد حیات سمجھ لیا گیا ہے اور اس میں حلال و حرام کی بھی تمیز نہیں کی جاتی۔"}],[4510,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع ملامسہ سے منع فرمایا، اور وہ یہ ہے کہ آدمی کپڑے کو چھو لے اسے اندر سے دیکھے بغیر (اور بیع ہو جائے) اور منابذہ سے منع فرمایا، اور منابذہ یہ ہے کہ آدمی اپنا کپڑا دوسرے کی طرف بیع کے ساتھ پھینکے اس سے پہلے کہ وہ اسے الٹ پلٹ کر دیکھے ۱؎۔\n§وضاحت\n۱؎: دور جاہلیت میں اس طرح کپڑا چھو کر یا پھینک کر بغیر دیکھے بیع کر لیتے اور ایجاب و قبول نہ ہوتا، اس سے منع کیا گیا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ سے منع فرمایا۔ ملامسہ یہ ہے کہ کپڑے کو چھوا جائے، کھول کر نہ دیکھا جائے۔ اور منابذہ یہ ہے کہ بیچنے والا کپڑے کو خریدار کی طرف پھینک دے اور سودا ہو جائے بغیر اس کے کہ وہ اس کپڑے کو الٹ پلٹ کر دیکھے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں اہل جاہلیت دھوکے والے سودے کرتے تھے۔ آپ نے ان سب کو ممنوع قرار دے دیا۔ یہ ملامسہ اور منابذہ بھی اسی قسم کے جاہلی سودے تھے جن میں صاف دھوکا ہوتا تھا، مثلاً: بیچنے والا خریدنے والے کو کہتا کہ جس کپڑے کو تمہارا ہاتھ لگ گیا، وہ اتنے میں تجھے فروخت، خواہ کسی کپڑے کو ہاتھ لگ جاتا، خواہ وہ اندر سے بالکل پھٹا ہوتا۔ صرف ہاتھ لگنے سے بیع پکی ہو جاتی تھی۔ کھول کر دیکھنے کی اجاز ت نہیں ہوتی تھی اور بعد میں وہ واپس بھی نہیں ہو سکتا تھا۔ اسے ملامسہ کہتے تھے۔ اسی طرح بیچنے والا خریدنے والے کی طرف کوئی چیز (کپڑا یا کچھ اور) پھینکتا، اتنے سے وہ سودا پکا ہو جاتا۔ اس چیز کو پرکھنے اور جانچنے کی اجازت نہیں ہوتی تھی۔ بعد میں وہ چیز بھی واپس نہیں ہو سکتی تھی، خواہ وہ کتنی ہی عیب دار کیوں نہ ہوتی۔ اسے منابذہ کہتے تھے۔ ظاہر ہے شریعت اس قسم کے مبہم سودے اور دھوکے بازی کو کیسے جائز قرار دے سکتی تھی، لہٰذا سختی کے ساتھ ان سے روک دیا گیا۔ منابذہ کی ایک اور تفسیر بھی کی گئی ہے کہ خریدار کنکری پھینکتا، کنکری جس چیز پر جا گرتی، اس کا سودا ہو جاتا تھا بغیر تحقیق کیے کہ وہ چیز کیسی ہے۔"}],[4511,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع ملامسہ اور منابذہ سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ قسم کی بیوع سے منع فرمایا۔"}],[4512,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو قسم کی بیع ملامسہ اور منابذہ سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے دو قسم کے سودوں ملامسہ اور منابذہ سے منع فرمایا۔"}],[4513,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع منابذہ اور ملامسہ سے منع فرمایا، ملامسہ یہ ہے کہ دو آدمی رات کو دو کپڑوں کی بیع کریں، ہر ایک دوسرے کا کپڑا چھو لے۔ منابذہ یہ ہے کہ ایک آدمی دوسرے آدمی کی طرف کپڑا پھینکے اور دوسرا اس کی طرف کپڑا پھینکے اور اسی بنیاد پر بیع کر لیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منابذہ اور ملامسہ سے منع فرمایا۔ ملامسہ یہ ہے کہ دو آدمی رات کے اندھیرے میں دو کپڑوں کا اس طرح سودا کریں کہ ان میں سے ہر ایک دوسرے کے کپڑے کو ہاتھ سے چھوئے۔ اور منابذہ یہ ہے کہ ایک آدمی دوسرے کی طرف کپڑا پھینکے اور دوسرا اس کی طرف کپڑا پھینکے۔ بس اتنے میں سودا ہو جائے۔","f2":"کپڑا تو بطور مثال ذکر کیا گیا ہے ورنہ کوئی بھی چیز اس طریقے سے بیچی جائے یا خریدی جائے، اسے ملامسہ اور منابذہ کہا جائے گا۔ یہ بھی ضروری نہیں کہ دونوں طرف ایک ہی جنس کی چیزیں ہوں جیسا کہ تفسیر میں ذکر کیا گیا ہے بلکہ نقدی کے ساتھ سودا ہو، تب بھی یہی حکم ہے۔ مقصود یہ ہے کہ جس سودے میں بھی ابہام ہو یا دھوکا دہی کا امکان ہو، وہ منع ہے کیونکہ اس قسم کا سودا بعد میں لڑائی جھگڑے کا سبب بنتا ہے، نیز اس کی بنیاد خود غرضی اور دھوکا دہی پر ہے اور یہ دونوں انسانیت اور اسلام کے خلاف ہیں۔"}],[4514,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ سے منع فرمایا۔ اور ملامسہ یہ ہے کہ کپڑے کو چھولے اس کی طرف دیکھے نہیں، اور منابذہ سے منع فرمایا، منابذہ یہ ہے کہ آدمی کپڑا دوسرے آدمی کی طرف پھینکے اور وہ اسے الٹ کر نہ دیکھے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ملامسہ اور منابذہ سے منع فرمایا۔ ملامسہ یہ ہے کہ کپڑے کو صرف چھوا جائے۔ (اچھی طرح کھول کر) دیکھا نہ جائے۔ اور منابذہ یہ ہے کہ ایک شخص دوسرے کی طرف کپڑا وغیرہ پھینکے لیکن الٹ پلٹ کرنے کی اجازت نہ ہو۔"}],[4515,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو قسم کے لباس اور دو قسم کی بیع سے منع فرمایا ہے، رہی دو قسم کی بیع تو وہ ملامسہ اور منابذہ ہیں۔ منابذہ یہ ہے کہ وہ کہے: جب میں اس کپڑے کو پھینکوں تو بیع واجب ہو گئی، اور ملامسہ یہ ہے کہ وہ اسے اپنے ہاتھ سے چھولے اور جب چھولے تو اسے پھیلائے نہیں اور نہ اسے الٹ پلٹ کرے تو بیع واجب ہو گئی۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو قسم کے لباس اور دو قسم کے سودوں سے منع فرمایا ہے۔ سودے تو ملامسہ اور منابذہ ہیں۔ منابذہ یہ ہے کہ بیچنے والا کہتے کہ جب میں یہ کپڑا پھینک دوں گا، بیع پکی ہو جائے گی۔ اور ملامسہ یہ ہے کہ خردینے والا کپڑے کو صرف ہاتھ سے چھوڑ اور اسے کھول کر الٹ پلٹ کر نہ دیکھے۔ جب چھو لیا تو سودا پکا ہو گا۔"}],[4516,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو قسم کے لباس سے منع فرمایا، اور ہمیں دو قسم کی بیع منابذہ اور ملامسہ سے روکا، اور یہ دونوں ایسی بیع ہیں جنہیں زمانہ جاہلیت میں لوگ کرتے تھے۔","الألباني: صحيح لغيره",{"u2":"حضرت سالم کے والد محترم (حضرت عبداللہ بن عمر رضی اللہ عنہ) نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے دو قسم کے لباس سے منع فرمایا۔ او رسول اللہ صلی اللہ علیہ وسلم نے ہمیں دو قسم کے سودوں سے منع فرمایا: ملامسہ اور منابذہ۔ اور یہ چند سودے تھے جو دور جاہلیت میں لوگ کیا کرتے تھے۔"}],[4517,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دو طرح کی بیع سے منع فرمایا، رہی دونوں بیع تو وہ منابذہ اور ملامسہ ہیں اور ملامسہ یہ ہے کہ ایک آدمی دوسرے آدمی سے کہے: میں تمہارے کپڑے سے اپنا کپڑا بیچ رہا ہوں اور ان میں کوئی دوسرے کے کپڑے کو نہ دیکھے بلکہ صرف اسے چھولے، رہی منابذہ تو وہ یہ ہے کہ وہ کہے: جو میرے پاس ہے میں اسے پھینک رہا ہوں اور جو تمہارے پاس ہے اسے تم پھینکو تاکہ ان میں سے ایک دوسرے کی چیز خرید لے حالانکہ ان میں سے کوئی بھی یہ نہیں جانتا کہ دوسرے کے پاس کتنا اور کس قسم کا کپڑا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دو قسم کی بیوع سے منع فرمایا۔ اور وہ ملامسہ اور منابذہ ہیں۔ انہوں نے فرمایا کہ ملامسہ یہ ہے کہ ایک آدمی دوسرے آدمی سے کہے: میں تجھے اپنا کپڑا تیرے کپڑے کے عوض بیچتا ہوں اور ان میں سے کوئی بھی دوسرے کے کپڑے کو نہ دیکھے بلکہ صرف چھوڑے۔ اور منابذہ یہ ہے کہ ایک شخص دوسرے سے کہے: میں اپنی چیز پھینکتا ہوں، تو اپنی چیز پھینک تاکہ ان میں سے ہر ایک دوسرے سے اس کی چیز خردیے اور ان میں سے کسی کو معلوم نہ ہو کہ دوسرے کے پاس کیا ہے اور کتنا ہے۔","f2":"ملامسہ اور منابذہ کی تفسیریں مختلف ہو سکتی ہیں مگر ان میں ایک چیز مشترک ہے کہ چھونے اور پھینکنے کے علاوہ مزید تسلی و تشفی کی گنجائش نہیں ہوتی۔ یہ ابہام ہی دراصل اس قسم کی بیوع کے منع ہونے کی وجہ ہے جبکہ اس کے ساتھ ساتھ ان تمام صورتوں میں دھوکا دہی کا جذبہ بھی پایا جاتا ہے۔"}],[4518,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کنکری کی بیع اور دھوکے کی بیع سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: کنکری کی بیع کا مطلب یہ ہے کہ آدمی کہے: میں تمہاری طرف جب کنکری پھینک دوں تو بیع ہو گئی، یہ ممنوع اس لیے ہے کہ کنکری پھینکنے تک کی جو مدت بیع کے اثبات کے لیے رکھی گئی ہے وہ مجہول ہے، یا پھر یوں کہے کہ میں کنکری پھینکتا ہوں جس مال پر کنکری گرے وہی بیچنا ہے تو یہ بھی صحیح نہیں، کیونکہ اس صورت میں بھی مال مجہول ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کنکریوں والی بیع اور ہر دھوکے والی بیع سے منع فرمایا ہے۔","f2":"(۱) بَیْعِ الْحِصَاۃِ، لفظ بَیْعٌ، بَاعَ یَبِیْعُ کا مصدر ہے اور اَلْحِصَاۃُ جمع ہے اَلْحِصٰی کی۔ یہ مصدر کی اضافت اپنے مفعول کی طرف ہرگز نہیں بلکہ مصدر کی اضافت نوع کی طرف ہے، اس لیے باب کے معنی ہیں: ’’کنکریوں والی بیع‘‘ اس کی کئی صورتیں ہوا کرتی تھیں، مثلاً: بائع مشتری سے کہتا کہ تو کنکری مار، وہ جس کپڑے کو یا دوسری اشیائ، جو وہ بیچنا چاہتا، کو کنکری جا لگے گی تو اتنی رقم میں وہ چیز تیری۔ اس میں نہ تو واپسی کا کوئی اختیار ہوتا اور نہ خیارِ مجلس ہی ہوتا اور نہ کپڑے وغیرہ کے کسی نقص اور عیب کی بابت کچھ معلوم ہوتا، اس لیے یہ بیع دراصل غرر اور دھوکے ہی کی بیع تھی جسے شریعت نے حرام قرار دیا ہے۔\nایک صورت یہ ہوتی کہ بائع مشتری سے کہتا کہ کنکری پھینکو جہاں تک وہ پہنچے گی وہاں تک اپنی زمین تجھے اتنی رقم کے عوض بیچوں گا۔ یہ مجہول چیز کی بیع ہے، اس لیے ناجائز ہے۔\nیہ صورت بھی ہوتی تھی کہ بیچنے والا شخص مٹھی میں کنکریاں بند کر لیتا اور ککہتا کہ جتنی کنکریاں میری مٹھی سے نکلیں گی، اتنی چیزیں مبیع سے میری ہوں گی۔ یا وہ کوئی سودا فروخت کرتا اور کنکریاں مٹھی میں بند کر کے کہتا کہ میری مٹھی میں جتنی کنکریاں ہوں گی اتنے ہی درہم یا دینار لوں گا، یعنی جو بھی طے ہوتا۔ کبھی وہ لوگ اس طرح بھی کیا کرتے کہ خرید و فروخت کرنے والوں میں سے کوئی ایک اپنے ہاتھ میں کنکریاں لیتا اور کہتا کہ جب بھی کنکریاں گریں گی، بیع واجب ہو جائے گی۔\nکبھی وہ لوگ سودا کرتے اور کنکری پھینکنے ہی کو بیع کا واجب ہونا قرار دیتے۔ یہ تمام اقوال امام نووی اور امام ابو العباس قرطبی رحمہ اللہ نے (شرح صحیح مسلم، البیوع، باب بطلان بیع الحصاۃ و البیع الذی فیہ الغرر: ۱۰/۲۲۰ میں) بیان فرمائے ہیں۔\n(۲) حدیث کے آخر میں ہر دھوکے والی بیع سے منع کر دیا گیا ہے، مثلاً: پانی کے اندر موجود مچھلی یا فضا کے اندر اڑتے پرندے کی بیع جسے ابھی تک شکار نہیں کیا گیا۔ اللہ جانے وہ شکار ہو سکے یا نہ، اسی طرح بھاگے ہوئے غلام کی بیع۔ نہ معلوم وہ مل سکے یا نہ۔ جو چیز ابھی پیدا ہی نہیں ہوئی، اس کی بیع بھی اسی کے تحت آتی ہے وغیرہ وغیرہ، البتہ اگر تھوڑا بہت ابہام ہو جس سے بچنا ممکن نہیں تو اس کی گنجائش ہے، مثلاً: ماہانہ یا یومیہ کرائے پر کوئی چیز لینا، حالانکہ سب مہینے، اسی طرح سب دن برابر نہیں ہوتے۔ ان میں کمی بیشی ہوتی رہتی ہے لیکن یہ مجبوری ہے، لہٰذا بلاتکلف جائز ہے، نیز ان میں دھوکا دہی کا تصور نہیں جو کہ منع کی اصل بنیاد ہے۔"}],[4519,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تک پختگی ظاہر نہ ہو جائے پھلوں کی بیع نہ کرو\"، آپ نے بیچنے اور خریدنے والے دونوں کو (اس سے) منع فرمایا ۱؎۔\n§وضاحت\n۱؎: پھلوں کی پختگی ظاہر ہونے سے پہلے اگر ان کو درخت پر بیچ دیا گیا تو بہت ممکن ہے کہ پختگی ظاہر ہونے سے پہلے آندھی طوفان آئے اور سارے یا اکثر پھل برباد ہو جائیں اور خریدار کا نقصان ہو جائے، اور پختگی ظاہر ہونے کے بعد اگر آندھی طوفان آئے بھی تو کم پھل برباد ہوں گے، نیز پختہ پھل اگر گر بھی گئے تو خریدار کی قیمت بھر پیسہ نکل آئے گا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پھلو کا سودا نہ کرو حتی کہ ان کی صلاحیت معلوم ہو جائے۔ آپ نے بیچنے والے کو بھی روکا اور خریدنے والے کو بھی۔‘‘","f2":"(۱) پھل سے مقصود تو اسے پکنے کے بعد کھانا ہے نہ کہ کچے کو۔ اگر کچا پھل خریدا جائے گا تو پکنے تک اس پر کئی آفتیں آ سکتی ہیں۔ وہ سوکھ سکتا ہے، اسے کیڑا لگ سکتا ہے وغیرہ وغیرہ، لہٰذا کل کلاں کو تنازع پیدا ہو سکتا ہے ک جناب پھل تو ضائع ہو گیا۔ رقم کس چیز کی دوں؟ اس قسم کے سودے میں رقم عموماً پھل کی کٹائی کے وقت ہی دی جاتی ہے، لہٰذا ان تنازعات کے پیش نظر اس قسم کی بیع سے منع فرما دیا گیا جیسا کہ حضرت زید بن ثابت رضی اللہ عنہ نے یہ بات صراحتاً فرمائی ہے، البتہ تنازع کا خطرہ نہ ہو، مثلاً: کچا پھل ہی توڑ کر استعمال کرنا ہو، جیسے کچے آم اچار کے لیے تو کوئی حرج نہیں کیونکہ یہ کچا بھی پکے کے قائم مقام ہے۔ اس کے نقصان کا بھی کوئی خطرہ نہیں۔ اسی طرح غلے والی فصل کو پکنے سے پہلے نہیں بیچا جا سکتا مگر چارے والی فصل کو کچا ہی بیچا جا سکتا ہے کیونکہ اسے کچا ہی کاٹنا ہوتا ہے۔ (۲) یہاں پھل پکنے سے مراد اس کی وہ کیفیت ہے جس کے بعد اس پر آفت کا احتمال نہیں رہتا، نہ یہ کہ وہ بالکل کھانے والی حالت میں ہو، مثلاً: آم جب جسامت میں پورا ہو جاتا ہے تو اسے توڑ کر کچھ مسالا لگایا جاتا ہے جس سے وہ پک جاتا ہے اور کھانے کے قابل ہو جاتا ہے۔ تو ایسی کیفیت میں آموں کی خرید و فروخت درست ہے اگرچہ وہ کھانے کے قابل تو مسالا لگانے سے ہوں گے۔ یہی مطلب ہے ان کی صلاحیت ظاہر ہونے کا۔ گویا پھل آفت سے محفوظ ہو تو پکنے سے پہلے بھی فروخت ہو سکتا ہے۔"}],[4520,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پختگی ظاہر ہونے سے پہلے پھل بیچنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت سالم کے والد محترم (حضرت عبداللہ بن عمر رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پھل کی فروخت سے روکا حتی کہ اس کی صلاحیت ظاہر ہو جائے۔"}],[4521,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پھل نہ بیچو جب تک اس کی پختگی ظاہر نہ ہو جائے، اور نہ (کھجور کے) درخت کے پھل کا اندازہ کر کے (درخت سے توڑی ہوئی) کھجوروں کو بیچو\"۔ ابن شہاب زہری کہتے ہیں: مجھ سے سالم بن عبداللہ نے اپنے والد عبداللہ بن عمر رضی اللہ عنہما سے روایت کرتے ہوئے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس جیسی صورت سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پھل کا سودا نہ کرو حتی کہ اس کی صلاحیت ظاہر ہو جائے اور تازہ پھل (تازہ کھجوریں) خشک کھجورں کے عوض نہ خریدو۔‘‘\nابن شہاب (امام زہری) نے کہا کہ مجھے حدیث بیان کی سالم بن عبداللہ نے اپنے والد محترم حضرت عبداللہ بن عمر رضی اللہ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا … پھر اسی (حدیث ابوہریرہ) کی مثل پوری حدیث بیان فرمائی۔","f2":"(۱) امام محمد بن مسلم بن شہاب زہری رحمہ اللہ یہ حدیث تین اساتذہ، یعنی حضرت سعید بن مسیب، ابو سلمہ اور حضرت سالم سے بیان فرماتے ہیں لیکن پہلے دونوں استاد (سعید بن مسیب اور ابو سلمہ) حضرت ابوہریرہ رضی اللہ عنہ سے بیان کرتے ہیں اور وہ رسول اللہ صلی اللہ علیہ وسلم سے جبکہ استاد سالم رحمہ اللہ یہ حدیث اپنے والد محترم حضرت عبداللہ بن عمر رضی اللہ عنہ سے اور وہ رسول اللہ صلی اللہ علیہ وسلم سے بیان فرماتے ہیں۔ مطلب یہ ہے کہ ابن شہاب دونوں سندوں سے یہ روایت موصولاً بیان فرماتے ہیں۔ پہلی صورت میں حدیث مسند ابوہریرہ ہے اور دوسری صورت میں مسند عبداللہ بن عمر رضی اللہ عنہم۔ (۲) ’’تازہ کھجوریں خشک کھجوروں کے عوض نہ خریدو‘‘ کیونکہ جب دونوں طرف ایک جنس ہو تو کمی بیشی درست نہیں ہوتی بلکہ اس صورت میں برابری ضروری ہے مگر خشک اور تازہ کھجوروں میں برابری ممکن نہیں کیونکہ تازہ کھجوریں خشک ہو کر وزن میں کم ہو جاتی ہے، لہٰذا انہیں الگ الگ خریدا اور بیچا جائے۔"}],[4522,"طاؤس کہتے ہیں کہ میں نے عبداللہ بن عمر رضی اللہ عنہما کو کہتے ہوئے سنا: ہمارے درمیان رسول اللہ صلی اللہ علیہ وسلم نے کھڑے ہو کر فرمایا: \"پھل مت بیچو یہاں تک کہ اس کی پختگی ظاہر ہو جائے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہم میں خطبہ دینے کے لیے کھڑے ہوئے اور فرمایا: ’’پھل نہ بیچو حتی کہ اس کی صلاحیت ظاہر ہو جائے۔‘‘حضرت جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مخابرہ، مزابنہ اور محاقلہ سے منع فرمایا۔ اور اس بات سے کہ پھلوں کو ان کی صلاحیت ظاہر ہونے سے پہلے فروخت کیا جائے یا تازہ پھل کو خشک پھل کے عوض بیچا جائے بلکہ ان کو دینار و درہم (روپے پیسے) کے عوض بیچا جائے، البتہ آپ نے عطیہ کے درختوں میں اس بیع کی اجازت عطا فرمائی ہے۔"}],[4523,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بیع مخابرہ، مزابنہ، محاقلہ سے، اور پکنے سے پہلے پھل بیچنے سے منع فرمایا، اور پھلوں کو درہم و دینار کے سوا کسی اور چیز کے بدلے بیچنے سے منع فرمایا، اور بیع عرایا میں رخصت دی۔\n§وضاحت\n۱؎: «مخابرہ»: بیل میں لگی ہوئی انگور کو کشمش :(توڑی ہوئی خشک انگور ) سے بیچنا، یا کھیت کو اس طرح بٹائی پر دینا کہ پیداوار کٹنے کے وقت کھیت کا مالک یہ کہے کہ فلاں حصے میں جو پیداوار ہے وہ میں لوں گا، ایسا اکثر ہوتا ہے کہ ایک ہی کھیت کے مختلف حصوں میں مختلف انداز سے اچھی یا خراب پیداوار ہوتی ہے، اور کھیت کا مالک اچھی والی پیداوار لینا چاہتا ہے، یہ جھگڑے فساد یا دوسرے فریق کے نقصان کا سبب ہے، اس لیے بٹائی کے اس معاملہ سے روکا گیا، ہاں مطلق پیداوار کے آدھے یا تہائی پر بٹائی کا معاملہ صحیح ہے، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر میں کیا تھا۔ ۲؎ «مزابنہ»: درخت پر لگے ہوئے پھل کو توڑے ہوئے پھل کے معینہ مقدار سے بیچنے کو «مزابنہ» کہتے ہیں۔ «محاقلہ»: کھیت میں لگی ہوئی فصل کا اندازہ کر کے اسے غلّہ سے بیچنا۔ «عرایا»: «عرایا» یہ ہے کہ باغ کا مالک ایک یا دو درخت کے پھل کسی مسکین کو کھانے کے لیے مفت دیدے اور باغ کے اندر اس کے آنے جانے سے تکلیف ہو تو مالک اس درخت کے پھلوں کا اندازہ کر کے مسکین سے خرید لے اور اس کے بدلے تازہ تر یا خشک کھجور اس کے حوالے کر دے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبد اللہ رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مخابرہ، مزابنہ اور محاقلہ سے منع فرمایا۔ اور اس بات سے کہ پھلوں کو ان کی صلاحیت ظاہر ہونے سے پہلے فروخت کیا جائے یا تازہ پھل کو خشک پھل کے عوض بیچا جائے بلکہ ان کو دینار درہم (روپے پیسے) کے عوض بیچا جائے، البتہ آپ نھے عطیہ کے درختوں میں اس بیع کی اجازت عطا فرمائی ہے۔"}],[4524,"جابر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بیع مخابرہ، مزابنہ، محاقلہ اور کھانے کے لائق ہونے سے پہلے درخت پر لگے پھلوں کو بیچنے سے منع فرما، یا سوائے بیع عرایا کے ۱؎۔\n§وضاحت\n۱؎: بیع عرایا کا استثناء بیع مزابنہ سے ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مخابرہ، محاقلہ اور پکنے سے پہلے پھل بیچنے سے منع فرمایا ہے، البتہ عطیہ کے درختوں میں مزابنہ کی اجازت عطا فرمائی ہے۔","f2":"مخابرہ زمین بٹائی پر دینا، مزابنہ: تازہ درخت پر لگے ہوئے پھل کی بیع خشک پھل کے بدلے، محاقلہ: غلے والی کھیتی کی خشک غلے کے عوض خرید و فروخت، تفصیل، حدیث نمبر:۳۹۱۰ وغیرہ میں دیکھیے۔"}],[4525,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجور بیچنے سے منع فرمایا جب تک کہ وہ کھانے کے لائق نہ ہو جائے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کھجوروں کی بیع سے منع فرمایا حتی کہ وہ کھانے کے قابل ہو جائیں۔"}],[4526,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پھلوں کو بیچنے سے منع فرمایا یہاں تک کہ وہ خوش رنگ ہو جائیں، عرض کیا گیا: اللہ کے رسول! یہ خوش رنگ ہونا کیا ہے؟ آپ نے فرمایا: \"یہاں تک کہ لال ہو جائیں\" اور فرمایا: \"دیکھو! اگر اللہ تعالی پھلوں کو روک دے (پکنے سے پہلے گر جائیں) تو تم میں کوئی اپنے بھائی کا مال کس چیز کے بدلے لے گا\" ۱؎۔\n§وضاحت\n۱؎: یہ ممانعت اس صورت میں ہے جب خریدار سے توڑنے کی شرط نہ لگائی گئی ہو، اگر فوری طور پر توڑ لینے کی شرط لگائی ہو تو اب یہ خریدار کی وجہ سے ہے کہ وہی اپنی قیمت کے بدلے اسی سودے پر راضی ہو گیا۔ اب بیچنے والے کا اس میں کوئی عمل دخل نہیں ہے، اور نہ ہی پھلوں کے کسی آفت کے شکار ہونے کا خطرہ ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پھل پکنے سے پہلے ان کو بیچنے سے منع فرمایا۔ پوچھا گیا: اے اللہ کے رسول! پکنے کا کیا مطلب ہے؟ آپ نے فرمایا: ’’وہ سرخ ہو جائیں (پکنے کے قریب ہو جائیں اور کسی قسم کی آفت کا احتمال نہ رہے۔ ‘‘) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بتاؤ اگر اللہ تعالیٰ پھل روک لے تو تم میں سے کوئی کس بنا پر اپنے بھائی سے رقم لے گا؟ ‘‘","f2":"1) اس باب سے مئولف رحمہ اللہ کا مقصد یہ مسئلہ بیان کرنا ہے کہ فوراََ کاٹ لینے کی شرط پر، پکنے سے پہلے پھلوں کی خریدہ فروخت جائز ہے لیکن اس صورت میں جب اس انتفاع ممکن ہو۔ امام شافعی، ہیں۔2) ہمارے ہاں جو یہ رواج ہے کہ لوگ اپنے باغ کا پھل کئی سال کے لیے بیچ دیتے ہیں تو یہ عمل اس حدیث کی رو ناجائز اور حرام ہے۔ جب موجود پھل، جو ابھی تک کھانے کے قابل نہیں ہوا، اس کی خرید و فروخت ممنوع ہے تو آئندہ سال یا کئی سالوں کا ٹھیکہ، جو کہ بالکل معدوم پھلوں کا ہوتا ہے، کیسے جائز ہو سکتا ہے۔ اس ممانعت کی وجہ بالکل واضح ہے کہ اس میں نرا دھوکا ہی دھوکا ہے، نیز یہ مجہول چیز کی بیع ہے جو کہ شرعاََ ناجائز ہے۔ مزید بر آں یہ بھی کہ یہ ایک ایسی چیز کی بیع ہے جو بیچنے والے کے پاس نہیں ہے جبکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’جو چیز تیرے پاس نہیں وہ مت بیچ۔3)‘‘ ’’سرخ ہو جائیں‘‘ یعنی پھل رنگ بدلنا شروع کر دیں، خواہ وہ سرخ ہونے لگیں یا زرد۔ اس سے معلوم ہوا کہ پکنے سے مراد مکمل پکنا نہیں بلکہ آفت سے محفوظ ہونا ہے ورنہ صرف رنگ بدلنے سے تو پھل مکمل پک نہیں جاتا۔ ہاں، پکنا شروع ہو جاتا ہے۔ گویا پکنے کا آغاز کافی ہے۔4) ’’کس بنا پر رقم لے گا؟‘‘ گویا اگر اس نے فوراََ پھل کاٹ لینا ہو تو رقم لے سکتا ہے کیونکہ آپ نے پھل پکنے سے رک جانے کی صورت میں رقم لینے سے روکا ہے۔ اگر فورََا کاٹ لیے جائیں تو پکنے کا مسئلہ ہی نہیں بنتا۔ باب پر اسی استد لال ہے اور یہی صحیح ہے۔"}],[4527,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم نے اپنے (مسلمان) بھائی سے پھل بیچے پھر اچانک ان پر کوئی آفت آ گئی تو تمہارے لیے جائز نہیں کہ تم اس سے کچھ لو، آخر تم کس چیز کے بدلے میں ناحق اپنے (مسلمان) بھائی کا مال لو گے\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے معلوم ہوا کہ اس طرح کے حادثہ میں بیچنے والے کے اوپر لازم ہے کہ خریدار کا جتنا نقصان :(خسارہ ) ہوا ہے اتنے کی وہ بھر پائی کر دے ورنہ وہ مسلمان بھائی کا مال کھا لینے کا مرتکب گردانا جائے گا، اور یہ اس صورت میں ہے جب پھل ابھی پکے نہ ہوئے ہوں، یا بیچنے والے نے ابھی خریدار کو مکمل قبضہ نہ دیا ہو، ورنہ پھل کے پک جانے اور قبضہ دے دینے کے بعد بیچنے والے کی ذمہ داری ختم ہو جاتی ہے، اس طرح کا معاملہ ایک آدمی کے ساتھ پیش آیا تو آپ صلی اللہ علیہ وسلم نے بیچنے والے سے بھر پائی کرانے کی بجائے عام لوگوں سے خریدار پر صدقہ و خیرات کرنے کی اپیل کی جیسا کہ حدیث نمبر: ۴۵۳۴ میں آ رہا ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تو اپنے (مسلمان) بھائی کو پھل بیچے، بعد میں پھل پر کوئی گہانی آفت آ جائے تو تیرے لیے اس کی قیمت لینا حلال نہیں۔ تو کس بنا پر اپنے بھائی کا مال نا حق لے گا؟ ‘‘","f2":"1)مقصود یہ ہے کہ اگر پھل کسی نا گہانی آسمانی یا زمینی آفت وغیرہ کا شکار ہو جائے تو بیچنے والے کو چاہیے کہ وہ اس آفت کی تلافی کرے۔ بہتر تو یہ ہے کہ ساری رقم ہی واپس کر دے ورنہ حتی المقدور بھر پور تعاون کرے، بصورت دیگر وہ اپنے مسلمان بھائی کا مال با طل طریقے سے کھانے کا مصداق قرار پائے گا۔2) اس حدیث سے ہر قسم کے پھلوں کی خرید و فروخت کا جواز ثابت ہو رہا ہے، خودہ وہ جس مرحلے میں بھی ہوں، حالانکہ گزشتہ احادیث سے کچے، یعنی ایسے پھلوں کی خرید و فروخت ممنوع قرار پائی ہے جو کھانے کے قابل نہ ہوں، تو اس کا جواب یہ ہے کہ مذکورہ حدیث سے بھی وہی پھل مراد ہیں جو کھانے کے قابل ہوں، انہی کی خرید و فروخت جائزہ ہو گی، ہاں ضرورت کے تحت اگر کچے پھلوں کی ضرورت ہو تو پھر اسی وقت کاٹنے کی شرط لازمی ہے، و گرنہ اس کی اجازت نہیں، جمہور اہل علم کی رائے یہی ہے۔3) کسی بھی مسلمان کے لیے دوسرے مسلمان بھائی کا مال نا حق اور باطل طریقے سے کھانا منع ہے۔ قرآن و حدیث کے دیگر دلائل کے علاوہ یہ حدیث بھی اس کی صریح دلیل ہے۔4) انسانیت اور اسلام کا تقاضا بھی یہی ہے کہ جو پھل آسمانی آفت سے ضائع ہو گیا، اس کی قیمت وصول نہ کی جائے کیونکہ اگر یہ پھل مالک کے ہاں آسمانی آفت سے ضائع ہو جاتا تو پھر بھی تو اسے برداشت کرنا ہی پڑتا۔ اب بھی برداشت کرنا چاہیے۔ اگر وہ خریدار سے اس پھل کی قیمت وصول کر لے گا تو یہ نا حق اور نا جائز ہو گا۔ امام حمد اور محدثین اسی کے قائل ہیں کہ نا گہانی آفافت کا نقصان معاف کرنا ضروری ہے۔ دیگر حضرات نے اسے مستحب قرار دیا ہے کیونکہ طے شدہ سودے سے دستبردار ہونے پر کسی کو مجبور نہیں کیا جا سکتا۔ لیکن ظاہر حدیث اس کے خلاف ہے کیونکہ انسانیت اور اسلامی اخوت کا تقاضا ہر اصول سے مقدم ہے۔ ان اصولی حضرات نے اپنے اصول کو قائم رکھنے کے لیے حدیث کی دوراز کار تاو یلات کی ہیں جو ان کی مجبوری ہے لیکن انسانیت اور اخوت اس حدیث پر عمل کرنے ہی میں ہے۔"}],[4528,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے پھل بیچے پھر ان پر کوئی آفت آ گئی تو وہ اپنے بھائی سے (کچھ) نہ لے، آخر تم کس چیز کے بدلے میں اپنے مسلمان بھائی کا مال کھاؤ گے\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن اللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص پھل بیچے، پھر اس کو کوئی آفت پہنچ جائے اور وہ ضائع ہو جائے تو وہ اپنے بھائی سے اس کی قیمت نہ لے۔‘‘ اور آپ نے الفظ فرمایا، وہ کس بنا پر اپنے مسلمان بھائی کا مال کھائے گا؟","f2":"آپ نے لفظ فرمایا۔ مطلب ہے کہ آپ نے فرمایا: اپنے (مسلمان) بھائی سے کوئی چیز نہ لے۔ ‘‘"}],[4529,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے آفتوں کا نقصان دلوایا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ نے فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم نے نا گہانی آفات سے پہنچنے والے نقصانات کی تلافی کا حکم فرمایا ہے۔"}],[4530,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں ایک شخص کے پھلوں پر جسے اس نے خرید رکھا تھا کوئی آفت آ گئی، چنانچہ اس پر بہت سارا قرض ہو گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے خیرات دو\"، تو لوگوں نے اسے خیرات دی، لیکن خیرات اتنی اکٹھا نہ ہوئی جس سے اس کے تمام قرض کی ادائیگی ہو جاتی تو آپ نے (اس کے قرض خواہوں سے) کہا: \"جو پا گئے ہو وہ لے لو، اس کے علاوہ اب کچھ اور دینا لینا نہیں ہے\" ۱؎۔\n§وضاحت\n۱؎: یہ گویا مصیبت میں تمہاری طرف سے اس کے ساتھ رعایت و مدد ہے۔ اس واقعہ میں پھلوں پر آفت آنے کا معاملہ پھلوں کے پک جانے کے بعد بیچنے پر ہوا تھا، اس لیے نبی اکرم صلی اللہ علیہ وسلم نے بیچنے والے سے بھر پائی کرانے کے بجائے عام لوگوں سے خیرات دینے کی اپیل کی، اس حدیث کا مطلب یہ نہیں ہے کہ قرض خواہ بقیہ قرض سے ہاتھ دھو لیں، بلکہ اس کا مطلب یہ ہے کہ جب حاکم موجودہ مال کو قرض خواہوں کے درمیان بقدر حصہ تقسیم کر دے پھر بھی اس شخص کے ذمہ قرض خواہوں کا قرض باقی رہ جائے تو ایسی صورت میں قرض خواہ اسے تنگ کرنے، قید کرنے اور قرض کی ادائیگی پر مزید اصرار کرنے کے بجائے اسے مال کی فراہمی تک مہلت دے۔ حدیث کا مفہوم یہی ہے اور قرآن کی اس آیت «وإن کان ذوعسرۃ فنظرۃ إلی میسرۃ» کے مطابق بھی ہے کیونکہ کسی کے مفلس :(دیوالیہ ) ہو جانے سے قرض خواہوں کے حقوق ضائع نہیں ہوتے، رہی اس حدیث کی یہ بات کہ \" اس کے علاوہ اب تم کو کچھ نہیں ملے گا \" تو یہ اس آدمی کے ساتھ خاص ہو سکتا ہے، کیونکہ اصولی بات وہی ہے جو اوپر گزری۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ایک آدمی کا پھل ضائع ہو گیا جو اس نے خریدا تھا۔ اس طرح وہ بہت مقروض ہو گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس پر صدقہ کرو۔‘‘ لوگوں نے اس پر صدقہ کیا لیکن اس کا پورا قرض ادا نہیں ہو سکتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے (اس کے قرض خواہوں سے) فرمایا: ’’جو تمھیں ملے وہ لے لو۔ اس کے علاوہ تمھیں کچھ نہیں ملے گا۔‘‘","f2":"1)جس شخص کا خریدا ہوا پھل بوجہ آفت ضائع ہو گیا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اس پر نہ صرف صدقہ کرنے کا حکم دیا بلکہ موجود مال کے علاوہ اس مزید کچھ لینے سے بھی روک دیا۔ حدیث کی رو سے ایسا کرنا جائز ہے۔ 2)رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ بلکہ پوری امت پر انتہائی مہربان تھے۔ یہی وجہ ہے کہ آپ ان کے معاملات کی اصلاح اور ان کی تدبیر فرماتے رہتے، فقراء اور محتاجوں کی بھر پور مدد کرتے۔ آپ کے ہاں اگر کچھ مال وغیرہ ہوتا تو وہ ضرورت مندوں کو دیتے اور کچھ پاس نہ ہوتا تو خوش حال صحابہ اکرم رضی اللہ عنہم سے تعاون اور صدقہ خیرات کرنے کا حکم فرماتے۔3) اس حدیث سے یہ مسئلہ بھی معلوم ہوا کہ جس شخص کا مال یا پھل وغیرہ کسی ارضی یا سماوی آفت سے تباہ ہو جائیں، اس کے لیے بقدر ضرورت سوال کرنا درست ہے۔ اس سے زیادہ کو سوال کرنا جائز نہیں، نیز کنگال اور آفت زدہ شخص سے اس کے ذمہ قرض کا مطالبہ کیا جائے نہ اسے قید میں ڈالا جائے اور نہ ہمہ وقت اس کے تعاقب ہی رہا جائے۔ امام مالک، شافعی اور جمہور اہل علم کا یہی قول ہے لیکن ضروری ہے تنگ دست شخص لوگوں سے قرض لے کر ضائع کرنے والا نہ ہو۔4) ظاہر یہ ہے کہ یہ پھل کچا خریدا گیا ہو گا۔ پکنے سے پہلے آفت آ گئی۔ اس وقت تک آپ نے ابھی کچے پھل کے سودے سے منع نہیں فرمایا ہو گا۔ یا ممکن ہے پھل تو وقت ہی پر خردا گیا ہو مگر آفت آتے دیر نہیں لگتی۔ بارش اور آندھی وغیرہ بھی تو پھل کو ضائع کر دیتی ہے۔ نقصان کی معافی کا حکم بھی تو ایسے ہی پھل کے بارے میں ہو گا جو وقت پر خریدا گیا مگر پھر بھی نقصان ہو گیا۔"}],[4531,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کئی سال تک کے لیے پھل بیچنے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: کیونکہ اس کی کوئی ضمانت نہیں کہ اگلے سالوں میں پھل آئیں گے یا نہیں، اور پھل نہ آنے کی صورت میں خریدار کا گھاٹا ہی گھاٹا ہے اس طرح کی بیع کو \" بیع غرر \" یعنی دھوکے کی بیع کہا جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم نے کئی سال کے لیے پھل بیچنے سے منع فرمایا ہے۔","f2":"کسی باغ یا مخصوص درختوں کے پھل کئی سال کے لیے پیشگی فروخت کرنا شرعاََ نا جائز اور حرام ہے۔ اس کی وجہ یہ ہے کہ اس میں سراسر دھوکا ہے، نیز یہ ایک مجہول چیز کی بیع ہے۔ مزید بر آں یہ کہ بائع ایک ایسی چیز کا سودا کر رہا ہے جس کا کوئی وجود نہیں اور خریدار بھی ایک ایسی چیز خرید رہا ہے جو معدوم ہے، پھر اس کی کوئی ضمانت بھی نہیں ہوتی کہ واقعی پیداوار ہو گی، لہٰذا فروخت کس چیز کی؟ لیکن اس حدیث سے بیع الصفات مستثنیٰ ہے۔ اس میں چیز کی جنس اور مدت کا تعین ہوتا ہے۔ وزن یا مقدار بھی معلوم ہوتی ہے۔ اور یکمشت رقم کی ادائیگی کر دی جاتی ہے۔ اسے بیع سلم یا سلف بھی کہتے ہیں۔ احادیث کی روشنی میں یہ جائز ہے۔ اس طریقے سے اختلاف اور دھوکے نوبت نہیں آتی۔"}],[4532,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے درخت کے پھل (کھجور) توڑے ہوئے پھلوں (کھجور) سے بیچنے سے منع فرمایا۔ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: مجھ سے زید بن ثابت رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع عرایا میں اجازت عطا فرمائی ۱؎۔\n§وضاحت\n۱؎: عرایا: عریا کی شکل یہ ہوتی تھی کہ باغ کا مالک کسی غریب ومسکین کو درختوں کے درمیان سے کوئی درخت صدقہ کر دیتا تھا، تو ایسے میں اگر مسکین اور اس کے بال بچوں کے باغ میں باربار آنے جانے سے مالک کو تکلیف ہوتی ہو تو اس کو یہ اجازت دی گئی کہ اس درخت پر لگے پھل :(تر کھجور ) کے بدلے توڑی ہوئی کھجور کا اندازہ لگا کر دیدے، یہ ضرورت کے تحت خاص اجازت ہے۔ عام حالات میں اس طرح کی بیع جائز نہیں۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت سالم کے والد محترم (حضرت عبد اللہ بن عمر رضی اللہ عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے خشک کھجوروں کے بدلے درخت پر لگی ہوئی کھجوروں کے سودے سے منع فرمایا ہے۔\nحضرت عبد اللہ بن عمر رضی اللہ عنہ نے فرمایا: مجھے حضرت زیدبن ثابت رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے عطیے کے درختوں میں اس سودے کی رخصت دی ہے۔","f2":") تازہ اور خشک کھجور کی آپس میں خرید و فروخت ممنوع ہے کیونکہ تازہ کھجور خشک ہونے کے بعد کم ہو جائے گی اور ہم جنس چیز میں کمی بیشی جائز نہیں۔ ہاں بیع عرایا میں تازہ کھجور کا خشک کھجور کے ساتھ سودا کرنا درست ہے، اس لیے کہ میں فریقین، یعنی عطیہ دینے اور قبول کرنے والوں کے لیے مشکلات پیدا ہو جائیں گی کیونکہ عطیہ کرنے والے، عطیہ نہ کرنے پر مجبور ہو جائیں گے۔2) یہ حدیث اس بات پر دلالت کرتی ہے کہ جب ایک ہی جنس کا تازہ پھل خشک ہو کر وزن میں کم ہو جاتا ہو تو اس جنس کے خشک اور تر (تازہ) پھل کی باہمی بیع حرام ہے اگر چہ سودا کرتے وقت دونوں (پھل) وزن اور کیل (ماپ) میں برابر ہی ہوں۔ اس کی وجہ یہ کہ ہے تساوی، یعنی باہمی برابری کا اعتبار اس وقت معبتر اور صحیح ہوتا ہے جب وہ اشیاء حالت کمال کو پہنچ کر بھی برابر ہی رہیں اور ادھر یہ بات نہیں کیونکہ کھجور جب خشک ہو جاتی ہے تو اس وزن بہر صورت تازہ حالت کی نسبت کم ہو جاتا ہے اور پھر اس تعین بھی نا ممکن ہے کہ وزن کتنا کم ہوتا ہے، البتہ امام ابو حنیفہ رحمہ اللہ وزن اور ماپ برابر برابر ہونے کی صورت میں خشک اور تازہ کھجور کے باہمی سودے کو جائز قرار دیتے ہیں جبکہ صاحبین (امام صاحب کے شاگردان امام محمد بن حسن اور امام ابو یوسف اس مسئلے میں اپنے استاد محترم کی مخالفت کرتے ہیں اور اس مسئلے میں مما نعت کی بابت وارد صحیح احادیث کی بنیاد پر انھوں نے حدیث رسول کو قبول اور اپنے استاد صاحب کی بات کو رد کر دیا ہے۔ مزید تفصیل کے لیے دیکھیے:\n3)اس قسم کی بیع کو مزابنہ کہا جاتا ہے۔ یہ عموماََ تو منع ہے مگر عریہ (عطیہ میں دیے گئے درخت) میں غرباء کی سہولت کے لیے رخصت دی گئی ہے جیسا کہ تفصیل فائدہ نمبرا میں بیان ہو چکی ہے۔\nمزید تفصیل کے لیے دیکھیے حدیث نمبر 3910"}],[4533,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع مزابنہ سے منع فرمایا، اور مزابنہ یہ ہے کہ درخت میں موجود پھل کو متعین توڑے ہوئے پھلوں سے بیچنا اس طور پر کہ زیادہ ہوا تو بھی میرا (یعنی کا) اور کم ہوا تو بھی میرے ذمہ۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا۔ اور مزابنہ یہ ہے کہ درخت پر لگا ہوا پھل (کھجور) معین وزن (یا ماپ) کی خشک کھجوروں کے بدلے بیچا جائے کہ اگر کھجور کا پھل زیادہ ہوا تو اس کا فائدہ بھی مجھے ہے اور اگر پھل کم ہوا تو اس کا نقصان بھی مجھے ہو گا۔","f2":"’’کہ اگر کھجور کا پھل‘‘ یہ جملہ پھل کے خریدار کی زبانی ہے کیونکہ ہے اس کا فائدہ نقصان اسی کو ہے۔"}],[4534,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع مزابنہ سے منع فرمایا، مزانبہ درخت پر لگے کھجور کو توڑے ہوئے کھجور سے ناپ کر بیچنا، اور بیل پر لگے تازہ انگور کو توڑے ہوئے انگور (کشمش) سے ناپ کر بیچنا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا ہے۔ اور مزابنہ ہے کہ تازہ کھجوریں (درخت پر گلی ہوئیں) تولی ماپی ہوئی خشک کھجوروں کے بدلے اور درخت پر لگے ہوئے انگور ماپے ہوئے منقی کے بدلے بیچے جائیں۔","f2":"مزابنہ کے منع ہونے کی وجہ یہ کہ کسی ایک فریق کو نقصان کا احتمال ہے۔ ممکن ہے درخت سے کم کھجوریں اتریں، ویسے بھی کھجوریں خشک ہو کر کم ہو جاتی ہیں۔"}],[4535,"عثمان بن مرہ کہتے ہیں کہ میں نے قاسم سے بٹائی پر کھیت دینے کے بارے میں پوچھا تو انہوں نے رافع بن خدیج رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ اور مزابنہ سے منع فرمایا ہے۔ ابوعبدالرحمٰن نسائی نے دوسری مرتبہ (روایت کرتے ہوئے) کہا۔\nرافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ اور مزابنہ سے منع فرمایا ہے۔ ۱؎ اور فرمایا: \"کھیتی تین طرح کے لوگ کرتے ہیں: ایک وہ شخص جس کی اپنی ذاتی زمین ہو تو وہ اس میں کھیتی کرتا ہے، دوسرا وہ شخص جسے عاریۃً (بلامعاوضہ) زمین دے دی گئی ہو تو وہ دی ہوئی زمین میں کھیتی کرتا ہے۔ تیسرا وہ شخص جس نے سونا چاندی (نقد) دے کر زمین کرایہ پر لی ہو\"۔ اس حدیث کو اسرائیل نے طارق سے روایت کرتے ہوئے دونوں ٹکڑوں کو الگ الگ کر دیا ہے، پہلے ٹکڑے ۲؎ کو مرسلاً (بطور کلام نبی اکرم صلی اللہ علیہ وسلم) روایت کیا اور دوسرے ٹکڑے کو سعید بن مسیب کا قول بتایا ہے۔\n§وضاحت\n۱؎: محاقلہ سے مراد یہاں مزارعہ :(بٹائی ) پر دینا ہے اور مزابنہ سے مراد: درخت پر لگے کھجور یا انگور کا اندازہ کر کے اسے خشک کھجور یا انگور کے بدلے بیچنا ہے۔ ۲؎: پہلی بات سے مراد «نہی رسول اللہ صلی اللہ علیہ وسلم عن المحاقلۃ والمزابنۃ» ہے اور آخری بات سے مراد «إنما یزرع ثلاثۃ، الی آخرہ» ہے۔ یعنی: پہلی روایت میں آخری ٹکڑے کو درج کر کے اس کو مرفوع بنا دیا ہے، حالانکہ یہ سعید بن مسیب کا اپنا قول ہے، اسرائیل کی روایت جسے انہوں نے طارق سے روایت کیا ہے، دونوں ٹکڑوں کو چھانٹ کر الگ الگ کر دیا ہے۔\nرافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ اور مزانبہ سے منع فرمایا۔","الألباني: صحيح الإسناد",{"u2":"حضرت رافع خدیج رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھیت میں اگی ہوئی فصل کی بیع خشک غلے سے اور درخت پر لگے ہوئے پھل کی بیع خشک پھل کے ساتھ کرنے سے منع فرمایا ہے۔"}],[4536,"تابعی سعید بن مسیب کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ سے منع فرمایا ہے۔ سعید بن مسیب نے کہا، پھر راوی (اسرائیل) نے دوسری بات کو اسی طرح بیان کیا (یعنی دوسرا قول ابن المسیب کا ہے)، اسے طارق سے سفیان ثوری نے بھی روایت کیا ہے۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ مجھ سے زید بن ثابت رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع عرایا میں اجازت دی ہے۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابث رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عطیہ کے درختوں میں مزابنہ کی اجازت دی ہے۔"}],[4537,"انس رضی اللہ عنہ بیان کرتے ہیں کہ ایک یہودی نے ایک انصاری لڑکی کو اس کے زیور کی لالچ میں قتل کر کے، اسے کنوئیں میں پھینک دیا اور اوپر سے اس کا سر پتھروں سے کچل دیا، تو نبی اکرم صلی اللہ علیہ وسلم نے حکم دیا کہ \"اسے پتھروں سے اس طرح مارا جائے کہ وہ مر جائے\"۔\nزید بن ثابت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع عرایا میں خشک کھجور کو تر کھجور سے بیچنے کی اجازت دی ہے۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عطیہ کے درختوں میں رخصت عطا فرمائی کہ ان پر لگا ہوا پھل خشک یا تازہ کھجوروں کے عوض بیچایا خریدار جا سکتا ہے۔"}],[4538,"زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عاریت والی بیع میں اجازت دی کہ (اس کی تازہ کھجوروں کو) اندازہ کر کے (توڑی ہوئی) کھجوروں کے بدلے بیچی (جا سکتی) ہے۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رخصت عطا فرمائی کہ عطیہ کے درختوں کا پھل اندازا ان کے برابر خشک کھجوروں کے عوض بیچایا خریدا جا سکتا ہے۔","f2":"عرایا عریہ کی جمع ہے۔ عریہ اس درخت کو کہتے ہیں جسے باغ والا کسی غریب شخص کو پھل کھانے کے لیے دے دے۔ درخت اصل مالک ہی کا رہتا ہے۔ اس ایک درخت کی دیکھ بھال وغیرہ کے لیے غریب شخص کو بار بار باغ میں جانا پڑے گا۔ اس سے اس غریب شخص یا باغ والے کے لیے مشکلات پیدا ہو سکتی ہیں، لہٰذا شریعت نے اجازت دی کہ وہ باغ والا اس درخت پر لگے ہوئے پھل کے عوض اس غریب شخص کو اندازا اتنی خشک یا تازہ کھجوریں دے دے اور درخت واپس لے لے۔ یہ ہے تو مزابنہ کی صورت جو عموماََ ممنوع ہے مگر شریعت لوگوں کی مجبوریوں کا بھی لحاظ رکھتی ہے، اس لیے غریب کے مفاد کی خاطر تھوڑی مقدار (پانچ وسق، یعنی پندرہ بیس من) میں اس بیع کی اجازت دی لیکن اس سے زائد تھارتی مقاصد کے لیے یہ بیع جائز نہیں۔ (مزید تفصیلات کے لیے دیکھیے، فوائد و مسائل حدیث: ۳۹۱۰)"}],[4539,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ مجھ سے زید بن ثابت رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع عریہ کی اجازت دی کہ اس (کی تازہ کھجوروں کو) اندازہ لگا کر کے خشک کھجوروں کے بدلے بیچی (جا سکتی) ہے۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عطیہ کے درخت کے پھل کے بارے میں رخصت عطا فرمائی کہ اسے اندازا پھل کے برابر خشک کھجوروں کے عوض بیچا جا سکتا ہے۔"}],[4540,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ان سے زید بن ثابت رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے عاریت والی بیع میں اجازت دی کہ وہ توڑی ہوئی تازہ اور سوکھی کھجور سے بیچی جا سکتی ہے۔ اس کے علاوہ کسی اور چیز میں رخصت نہیں دی۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اجازت عطا فرمائی کہ عطیہ کے درختوں کا پھل خشک یا تازہ کھجوروں کے عوض بیچا جا سکتا ہے، البتہ آپ نے اس علاوہ (اس کی عام) اجازت نہیں دی۔"}],[4541,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے عاریت والی بیع میں (یہ) اجازت دی کہ پانچ وسق یا پانچ وسق سے کم کھجور اندازہ لگا کر کے بیچی جائے ۱؎۔\n§وضاحت\n۱؎: یعنی اوپر جو عاریت والی بیع میں یہ اجازت موجود ہے کہ درخت پر لگی کھجور کو توڑی ہوئی تازہ اور سوکھی کھجور کے بدلے بیچ سکتے ہیں، یہ ایک ضرورت کے تحت اجازت ہے، اور بات ضرورت کی ہے تو پانچ وسق سے یہ ضرورت پوری ہو جاتی ہے، اس لیے صرف پانچ وسق تک کی اجازت ہے۔","الألباني: صحيح",{"u2":"حضرت ابو ہر یرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے عطیہ کے درختوں کے بارے میں رخصت عطا فرمائی کہ ان کا پھل اندازا اس کے برابر کھجوروں پانچ و سق سے کم تک بیچا جا سکتا ہے۔","f2":"1)وسق ساٹھ صاع کا ہوتا ہے۔ اور صاع ایک پیمانہ ہوتا تھا جو تقریباََ سوا دو یا اڑھائی کلو کا ہوتا تھا۔ اس لحاظ سے و سق پندرہ یا اٹھارہ من کا ہو گا۔ گویا پندرہ بیس من تک (پرانے سیر کے حساب سے) اس بیع کی اجازت ہے کیونکہ اتنی کھجوریں کھانے کے لیے رکھی جاتی ہیں۔ یہ رخصت چونکہ غرباء کی مجبوری کے پیش نظر ہے، اس لیے زیادہ مقدار میں اس کی اجازت نہیں۔2) ’’پانچ و سق یا پانچ و سق سے کم‘‘ مقصد یہ ہے کہ پانچ و سق سے زائد میں اس رخصت سے فائدہ نہ اٹھایا جائے۔"}],[4542,"سہیل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پھل بیچنے سے منع فرمایا جب تک کہ پک نہ جائیں اور بیع عرایا میں اجازت دی کہ اندازہ لگا کر کے بیچا جائے، تاکہ کچی کھجور والے تازہ کھجور کھا سکیں۔","الألباني: صحيح ق دون قوله حتى يبدو صلاحه",{"u2":"حضرت سہل بن ابی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پکنے سے پہلے پھل کی فروخت سے روکا ہے۔ اور عطیہ کے درختوں کے بارے میں اجازت عطا فرمائی ہے کہ ان کا پھل اندازا اس کے برابر خشک پھل کے عوض فروخت کر دیا جاتے تا کہ ان درختوں والے غریب لوگ (جلدی تازہ کھجوریں کھا سکیں۔\nفائدہ: ’’تازہ کھجوریں کھا سکیں‘‘ کیو نکہ درخت والی کھجوریں تو دیر سے حاصل ہونا شروع ہوں گی۔ غریب کے لیے انتظار مشکل ہے۔"}],[4543,"رافع بن خدیج اور سہل بن ابی حثمہ رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع مزابنہ سے منع فرمایا، یعنی: درخت کے پھل کو توڑے ہوئے پھل سے بیچنا، سوائے اصحاب عرایا کے، آپ نے انہیں اس کی اجازت دی۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج اور حضرت سہل بن رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا، یعنی درخت پر لگی ہوئی کھجوروں کا سودا خشک کھجوروں سے کیا جائے، البتہ آپ نے عطیہ والے درختوں کے مالکوں کو (پانچ و سق تک) اس بیع کی اجازت دی۔"}],[4544,"صحابہ کرام رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تخمینہ (اندازہ) لگا کر کے عاریت والی بیع کی اجازت دی۔","الألباني: صحيح",{"u2":"حضرت بشیر بن یسار نے بہت سے صحابہ کرام رضی اللہ عنہم سے بیان کیا کہ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے عطیہ کے درختوں کے پھل کو اندازا ان کے برابر خشک کھجوروں کے عوض فروخت کرنے کی اجازت دی ہے۔"}],[4545,"سعد بن ابی وقاص رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے تازہ کھجوروں کے بدلے خشک کھجور بیچنے کے بارے میں پوچھا گیا تو آپ نے اپنے اردگرد موجود لوگوں سے سوال کیا: جب تازہ کھجور سوکھ جاتی ہے تو کیا کم ہو جاتی ہے؟ انہوں نے کہا: ہاں، تو آپ نے اس سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: اگر کسی کے پاس خشک کھجوریں ہوں اور وہ تازہ کھجوریں کھانا چاہتا ہے تو ایک دوسرے کے بدلے برابر یا کم و بیش کے حساب سے خرید و فروخت کرنے کی بجائے خشک کھجوروں کو پیسوں سے فروخت کر دے، پھر ان پیسوں سے تازہ کھجوریں خرید لے، ایک حدیث میں اس کی صراحت ہے :(دیکھئیے نمبر ۴۵۵۷ )۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ عنہ بیان کرتے ہیں کہ خریدنے یا بیچنے کے بارے میں پوچھا گیا تو آپ نے اپنے ارد گرد بیٹھے ہوئے حاضرین سے فرمایا: ’’انھوں نے کہا: ہاں پھر آپ نے ایسے سودے سے منع فرما دیا۔","f2":"1) چونکہ تازہ کھجور خشک ہونے کے بعد کم ہو جاتی ہے، اس لیے ایک فریق کو نقصان اٹھانا پڑتا ہے۔ یہ سود ہی کی ایک صورت ہے، لہٰذا رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرما دیا۔2) اس حدیث مبارکہ سے یہ اہم بات بھی معلوم ہوتی ہے کہ شارع علیہ السلام محض اشیاء کی حرمت بیان نہیں فرماتے تھے بلکہ بسا اوقات حرمت کی وجہ بھی بیان فرما دیتے تھے تا کہ لوگ علی وجہ البصیرت ممنوعہ چیز سے رک جائیں، نیز انھیں ممنوعہ چیز سے رک جائیں، نیز انھیں ممنوعہ چیز کی بابت مکمل طور پر انشراح صدر ہو جیسا کہ مذکورہ مسئلے میں آپ نے حاضرین ہی سے پوچھا: ’’کیا خشک ہو کر تازہ کھجور کا وزن کم ہو جاتا ہے؟‘‘ انھوں نے جواب دیا: جی ہاں۔ یقینا! اس حقیقت کا علم رسول اللہ صلی اللہ علیہ وسلم کو بھی تھا لیکن آپ نے ان سے پوچھا تا کہ ان کے سامنے حرمت کی وجہ بالکل واضح ہو جائے۔3) لوگوں کے مال کسی بھی باطل طریقے سے کھانا حرام ہے، ارشاد باری تعالیٰ ہے: ’’اے لوگو جو ایمان لائے ہو! اپنے مال آپس میں باطل اور ناحق طریقے سے نہ کھاؤ۔‘‘"}],[4546,"سعد بن مالک (سعد بن ابی وقاص) رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے سوکھی کھجور کے بدلے تازہ کھجور بیچنے کے متعلق سوال کیا گیا؟ تو آپ نے فرمایا: \"کیا تازہ کھجور سوکھنے پر کم ہو جائے گی؟\" لوگوں نے کہا: جی ہاں، تو آپ نے اس سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت سعد بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے خشک کھجوروں کے عوض تازہ کھجوریں خرید نے بیچنے کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’کیا تازہ کھجوریں خشک ہو کر کم ہو جاتی ہیں؟‘‘ جی ہاں، پھر آپ نے اس سودے سے منع فرما دیا۔"}],[4547,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بے ناپی کھجور کے ڈھیر کو ناپی ہوئی کھجور سے بیچنے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: یعنی: دونوں کھجوریں خشک ہوں جن کو برابر برابر کے حساب سے بیچ سکتے ہیں، مگر دونوں کی ناپ معلوم ہونی چاہیئے، کیونکہ ایسی چیزوں کی خرید و فروخت میں کم و بیش ہونا جائز نہیں۔","الألباني: صحيح",{"u2":"حضرت جابر بن اللہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ کھجوروں کے اس ڈھیر کا سواد، جس کا وزن معلوم نہ ہو، مقررہ وزن کی کھجوروں کے ساتھ کیا جائے۔","f2":"1) امام نسائی رحمہ اللہ نے جو باب قائم کیا ہے اس مقصد یہ مسئلہ بیان کرنا ہے کہ کھجوروں وغیرہ کا ایسا ڈھیر جس کی مقدار، یعنی اس کا وزن یا ماپ معلوم نہ ہو تو اسے معلوم مقدار والے ڈھیر کے عوض نہیں بیچا جا سکتا کیونکہ اس طرح ایک فریق کی حق تلفی ہو گی اور شرعاََ یہ حرام ہے، نیز معلوم ہوا کہ ایک ہی جنس کی دو چیزوں کی خرید و فروخت کمی بیشی کے ساتھ نہیں ہو سکتی بلکہ اس میں تساوی ہاتھوں ہاتھ لینے دینے کی شرط ضروری ہے۔ 2)اس حدیث مبارکہ کے مفہوم سے یہ اشارہ بھی نکلتا ہے کہ اگر دونوں ڈھیروں کی جنس مختلف ہو تو نا معلوم ماپ یا وزن والی ڈھیری کا سودا، معلوم و معین ماپ یا وزن والی ڈھیری سے کر دیا جائے تو یہ درست بیع ہو گی۔ اشارۃ النص سے اس کی تائید ہو رہی ہے۔ 3)عرب لوگ اس دور کھجوروں کو تولنے کی بجائے ماپا کرتے تھے جبکہ آج کل لوگ وزن کرتے ہیں۔ یہی وجہ ہے عربی میں اصل لفظ ’’کیل‘‘ استعمال کیا گیا ہے جس کے معنی ماپنے کے ہیں۔"}],[4548,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اناج کا ڈھیر اناج کے ڈھیر سے نہیں بیچا جائے گا ۱؎، اور نہ ہی اناج کا ڈھیر ناپے اناج سے ۲؎۔\n§وضاحت\n۱؎: کیونکہ دونوں کی مقدار معلوم نہیں، تو ہو سکتا ہے کہ ایک زیادہ ہو اور ایک کم، جب کہ تفاضل :(کمی زیادتی ) جائز نہیں۔ ۲؎: کیونکہ گرچہ ایک ڈھیر کی مقدار معلوم ہے مگر دوسرے کی معلوم نہیں، تو ہو سکتا ہے کہ کمی زیادتی ہو جائے، جو جائز نہیں، یہ اس صورت میں ہے جب دونوں ڈھیروں کی جنس ایک ہو۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبد اللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’غلے کا ایک ڈھیر دوسرے ڈھیر کے عوض یا مین وزن کے غلے کے عوض خریدا بیچا نہ جائے۔‘‘","f2":"یہ ممانعت تب ہے جب دونوں طرف ایک ہی جنس کا غلہ ہو کیونکہ اس صورت میں کمی بیشی سے لینا دینا منع ہے۔ اگر جنس بدل جائے، مثلاََ: ایک طرف گندم اور دوسری طرف کھجور وغیرہ ہو تو کمی بیشی جائز ہے، نیز اس وقت نپی تلی اور غیر معین غلے کی خرید و فروخت میں بھی کوئی حرج نہیں۔ لیکن شرط یہ ہے کہ یہ سودا ہاتھوں ہاتھ ہو۔ ادھار درست نہیں۔"}],[4549,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع مزابنہ سے منع فرمایا ہے \"مزابنہ یہ ہے کہ آدمی اپنے باغ میں لگے پھل کو بیچے، اگر وہ کھجور ہو تو نپی ہوئی کھجور سے بیچے، اور اگر انگور ہو تو اسے نپے ہوئے خشک انگور (منقی یا کشمش) سے بیچے، اور اگر کھڑی کھیتی (فصل) ہو تو اسے نپے ہوئے اناج سے بیچے\"۔ آپ نے ان تمام اقسام کی بیع سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مزابنہ سے منع فرمایا ہے۔ وہ یہ ہے کہ (کوئی شخص) اپنے باغ کا پھل (مثلاََ) تازہ کھجوریں خشک تولی ہوئی کھجوروں کے عوض بیچے۔ اسی طرح انگوروں کو تولے ہوئے منقیٰ کے عوض بیچے اور اگر کھیتی ہو تو اسے معین غلے کے عوض بیچے۔ آپ نے ان تمام صورتوں سے منع فرما دیا۔","f2":"ان بیوع کو مزابنہ اور محاقلہ کہا جاتا ہے۔ حرمت کی وجہ حدیث نمبر: ۴۵۲۳۸ میں گزر چکی ہے۔ (مزید تفصیل کے لیے دیکھیے فوائد مسائل، حدیث: ۳۹۱۰)"}],[4550,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع مخابرہ، مزابنہ اور محاقلہ سے منع فرمایا، اور کھانے کے لائق ہونے سے پہلے کھجور کو بیچنے سے، اور اسے سوائے دینار اور درہم کے کسی اور چیز سے بیچنے سے (منع فرمایا)۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مخابرہ، مزابنہ اور محاقلہ سے منع فرمایا۔ اور پھل کھانے کے قابل ہونے سے پہلے اس کی بیع سے بھی روکا۔ مزابنہ اور محاقلہ کی بجائے ان کو الگ الگ دینار اور در ہم (روپے پیسے) سے خریدا بیچا جائے۔"}],[4551,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کھجور کے بیچنے سے یہاں تک کہ وہ خوش رنگ ہو جائے، اور بالی کے بیچنے سے یہاں تک کہ وہ سفید پڑ جائے (یعنی پک جائے) اور آفت سے محفوظ ہو جائے۔ آپ نے بیچنے اور خریدنے والے دونوں کو روکا ۱؎۔\n§وضاحت\n۱؎: اس طرح کی بیع میں بھی وہی بات ہے جو پھلوں کے پکنے سے پہلے ان کی بیع میں ہے، یعنی ہو سکتا ہے کہ کھیتی پکنے سے کسی آسمانی آفت کا شکار ہو جائے، تو خریدار کا گھاٹا ہی گھاٹا ہو گا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ درخت کے پھل کی بیع کی جائے حتی کہ وہ رنگ بدل جائے۔ اور سٹے کی بیع کی جائے کہ وہ سفید ہو جائے اور آفت سے محفوظ ہو جائے۔ آپ نے بیچنے والے کو بھی روکا اور خرید نے والے کو بھی۔","f2":"منع کی وجہ پیچھے بیان ہو چکی ہے کہ اس میں خریدار کو نقصان کا احتمال ہے کیونکہ رنگ بدلنے سے پہلے پھل اور فصل کے بارے میں کوئی یقینی پیش گوئی نہیں کی جا سکتی۔ ناگہانی آفات کا بھی احتمال رہتا ہے۔ پھل اور فصل کی اصل صورت حال رنگ بدلنے کے بعد ہی واضح ہوتی ہے، اس لیے اس پہلے خریدنا منع ہے، نیز نقصان کی صورت میں تنازعات پیدا ہوں گے۔ بیچنے والا رقم کا تقاضا کرے گا۔ خریدار اپنا عذر پیش کرے گا، لہٰذا اس بکھیڑے میں پڑنے کا کیا فائدہ؟ (تفصیلات ملا حظہ فرمائیں، حدیث: ۴۵۲۳، ۴۵۳۰ میں)"}],[4552,"ایک صحابی رسول رضی اللہ عنہ نے کہا کہ اللہ کے رسول! ہم «صیحانی» (نامی کھجور) اور «عذق» (نامی کھجور) ردی کھجور کے بدلے نہیں پاتے جب تک کہ ہم زیادہ نہ دیں، تو آپ نے فرمایا: \"اسے درہم سے بیچ دو پھر اس سے :(«صیحانی» اور «عذق» کو) خرید لو\"۔","الألباني: صحيح لغيره",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی سے منقول ہے، انھوں نے کہا: اے اللہ کے رسول! ہمیں صیحانی اور عذق کھجوریں ردی اور ملی جلی کھجوروں کے برابر نہیں مل سکتیں جب تک کہ ہم زیادہ نہ دیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنی ردی کھجوریں چاندی (رقم) کے عوض بیچ اور پھر اس (رقم) کے ساتھ (عمدہ کھجوریں) خرید۔‘‘","f2":"1)اس روایت کا مندرجہ بالا باب سے کوئی تعلق نہیں بلکہ اس کا تعلق آئندہ باب سے ہے۔ سنن نسائی میں کئی مقامات پر ایسے ہوا ہے، کیوں؟ اللہ تعالیٰ بہتر جانتا ہے۔ ممکن ہے امام صاحب آئندہ باب کی طرف اشارہ فرما رہے ہوں یا کسی کاتب کے تصرف سے اس طرح ہو گیا ہو۔ 2)مسئلہ یہ ہے کہ کیاردی کھجوریں زیادہ مقدار میں دے کر اعلیٰ کھجوریں تھوڑی مقدار میں لینا جائز ہے؟ جائز نہیں کیونکہ جب دونوں طرف جنس ایک ہو تو کمی بیشی سود کا سبب ہے، لہٰذا دونوں کو الگ الگ رقم کے عوض خریدا بیچا جائے۔ یہ نہیں کہا جا سکتا کہ فرق کیا پڑا؟ صرف رقم کا واسطہ آ گیا۔ کھجوریں تو پھر بھی دو کلو کے بدلے ایک کلو ہی ملیں۔ (مثلاََ) کیونکہ زیر بحث مسئلے میں تو واقعتا کوئی فرق نہیں پڑا مگر بہت سے دیگر مسائل میں ہم جنس چیزوں کی کمی بیشی کے ساتھ بیع میں بہت سے مفاسد پیدا ہوتے ہیں۔ اصول اصول ہوتا ہے۔ جب مسئلے کا آسانن حل موجود ہے تو اصول توڑنے کا کیا فائدہ؟ 3)صیحانی اور عذق بہترین قسم کی کھجوریں تھیں۔"}],[4553,"ابو سعید خدری اور ابوہریرہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو خیبر کا عامل بنایا، وہ «جنیب» (نامی عمدہ قسم کی) کھجور لے کر آیا تو آپ نے فرمایا: \"کیا خیبر کی ساری کھجوریں اسی طرح ہیں؟\" وہ بولا: نہیں، اللہ کی قسم! ہم یہ کھجور دو صاع کے بدلے ایک صاع یا تین صاع کے بدلے دو صاع لیتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہ کرو، گھٹیا اور ردی کھجوروں کو درہم (پیسوں) سے بیچ دو، پھر درہم سے «جنیب» خرید لو\" ۱؎۔\n§وضاحت\n۱؎: یہی معاملہ ہر طرح کے پھلوں اور غلوں میں کرنا چاہیئے، اگر کسی کو گھٹیا اور ردی قسم کے بدلے اچھے قسم کا پھل یا غلہ چاہیئے تو وہ قیمت سے خریدے، بدلے میں نہیں۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری اور حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر میں (کھجوروں کی وصولی کے سلسلے میں) ایک آدمی مقرر فرمایا۔ وہ جنیب (عمدہ) کھجوریں لے کر آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا خیبر کی تمام کھجوریں ایسی (اعلیٰ) ہوتی ہیں؟‘‘ اس نے کہا: نہیں، اے اللہ کے رسول! ہم ملی جلی اور ردی کھجوروں کے دو صاع دے کر اس کا ایک صاع اور تین صاع دے کر اس قسم کے دو صاع خریدتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایسے نہ کرو۔ ردی اور ملی جلی کھجوروں کو رقم کے ساتھ الگ بیچو اور پھر رقم کے ساتھ جنیب کھجوریں خریدو۔‘‘","f2":"1)کھجور کے عوض کھجور کا کمی بیشی کے ساتھ سودا کرنا، حرام ہے خواہ کھجور کی ایک قسم کتنی ہی عمدہ و اعلیٰ اور دوسری کتنی ہی ردی ہو۔2) یہ حدیث صراحناََ دلالت کرتی ہے کہ سودی کاروبار کرنا قطعاََ حرام ہے ایسا کیا ہوا سواد صحیح نہیں ہو گا۔ 3)بعض معاملات میں حرام کام کامرتکب اس وقت تک معذور سمجھائے گا جب تک اسے اس کام کی حرمت کا علم نہ ہو۔ یہ یادر ہے کہ عذر بالجہل مطلقاََ قابل قبول نہیں، تاہم بعض معاملات، جن کا شریعت مطہرہ اور عرفِ عام لحاظ رکھیں، ان میں ایسا عذر قابل قبول ہو گا۔4) اس حدیث مبارکہ سے خود ساختہ صوفیوں کے اس خشک زہد کارد ہوتا ہے جو اچھی اشیاء کے استعمال سے گریز کرتے اور اپنے باطل زعم میں اسے تقویٰ سمجھتے ہیں، اپنے آپ کو مشقت میں مبتلا کر کے اسے نفس کشی کا نام دیتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم سے بڑا عابدو زاہد بھلا کون ہو سکتا ہے؟ لیکن اس کے باوجود انھوں نے اپنے استعمال کے لیے، ردی کھجور کے عوض اچھی اور عمدہ کھجور پسند کی ہے اور اسے خریدا ہے۔5) امام اور دینی و مذہبی ذمہ دار شخص کو خصوصی طور پر دین کے معاملات کو اہمیت دینی چاہیے۔ جن لوگوں کو ان کا علم نہ ہو انھیں تعلیلم دینی چاہیے اور انھیں نا جائز و حرام امور سے متنبہ کر کے جائز و مباح اور حلال امور کی طرف ان کی راہنمائی کونی چاہیے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابی کی رہنمائی فرماتے ہوئے اسے حرام کام سے ہٹا کر حلال کی طرف راستہ دکھایا۔6) یہ حدیث ربوابالفضل کی حرمت کی صریح دلیل ہے۔ 7)شکوک و شبہات میں مبتلا شخص کی تلاش حق میں اس وقت تک مدد کرنی چاہیے جب تک کہ اس کے لیے حق واضح نہ ہو جائے۔8)جنیب اعلیٰ قسم کی کھجور تھی اور ’’جمع، ردی کھجور جس میں گٹھلی نہیں ہوتی تھی۔ یا جمع سے مراد ملی جلی کھجوریں ہیں۔ کوئی کسی قسم کی کوئی کسی قسم کی جیسا کہ صدقہ و عشر میں عام ہوتا ہے۔ چونکہ خیبر میں بھی قسم کی کھجوروں سے حصہ وصول کیا گیا تھا، لہٰذا وہ ملی جلی تھیں۔"}],[4554,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس «ریان» (نامی عمدہ) کھجوریں لائی گئیں اور آپ کی «بعل» نامی (گھٹیا قسم کی) سوکھی کھجور تھی تو آپ نے فرمایا: \"تمہارے پاس یہ کھجوریں کہاں سے آئیں؟\" لوگوں نے کہا: ہم نے اپنی دو صاع کھجوروں کے بدلے اسے ایک صاع خریدی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہ کرو، اس لیے کہ یہ چیز صحیح نہیں، البتہ تم اپنی کھجوریں بیچ دو اور پھر اس نقدی سے اپنی ضرورت کی دوسری کھجوریں خریدو\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس موٹی تازی کھجوریں لائی گئیں جبکہ رسول اللہ صلی اللہ علیہ وسلم کی کھجوریں خودر و قسم کی تھیں کہاں سے مل گئیں؟ لوگوں نے کہا: ہم نے اپنی کھجوروں کے دو صاع دے کر یہ ایک صاع کے حساب سے خریدی ہیں۔ آپ نے فرمایا: ’’ایسے نہ کرو۔ یہ درست نہیں بلکہ اپنی کھجوریں الگ رقم کے عوض فروخت کرو اور پھر اپنی ضرورت کے مطابق ان کو الگ رقم کے ساتھ خریدو۔‘‘","f2":"’’موٹی تازی کھجوریں‘‘ مراد درختوں کی کھجوریں ہیں جن کو پانی وافر ملتا تھا۔ ظاہر ہے وہ ایسی ہی ہوں گی اور جن درختوں کو پانی نہیں ملتا، وہ زمین کے پانی ہی سے اپنی خوراک حاصل کرتے ہیں۔ ظاہر ہے ان کی کھجوریں خشک ہی ہوں گی۔"}],[4555,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ردی کھجوریں ملتی تھیں تو ہم دو صاع دے کر ایک صاع (اچھی کھجوریں)خرید لیتے تھے، یہ بات رسول اللہ صلی اللہ علیہ وسلم کو معلوم ہوئی تو آپ نے فرمایا: \"کھجور کے دو صاع ایک صاع کے بدلے، گیہوں کے دو صاع ایک صاع کے بدلے اور دو درہم ایک درہم کے بدلے نہ لیے جائیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ نے فرمایا: ہمیں رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ملی جلی کھجوریں دی جاتی تھیں۔ ہم ان کے دو صاع دے کر عمدہ کھجوریں دی جاتی تھیں۔ ہم ان کے دو صاع دے کر عمدہ کھجور کا ایک صاع لے لیتے تھے۔ یہ بات رسول اللہ صلی اللہ علیہ وسلم تک پہنچی تو آپ نے فرمایا: ’’کھجور کے ایک صاع کے بدلے دو صاع نہیں لیے جا سکتے اور نہ گندم کے ایک صاع کے بدلے دو صاع لیے جا سکتے ہیں۔ اور نہ ایک در ہم کا سودا دو در ہم سے ہو سکتا ہے۔‘‘"}],[4556,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم لوگ دو صاع ردی کھجوروں کے بدلے ایک صاع (عمدہ قسم کی کھجوریں) لیتے تھے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ایک صاع کھجور کے بدلے دو صاع کھجور، ایک صاع گیہوں کے بدلے دو صاع گی ہوں، اور ایک درہم کے بدلے دو درہم لینا جائز نہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ بیان کرتے ہیں کہ ہم ردی کھجوروں کے دو صاع دے کر ایک صاع عمدہ کھجور لے لیا کرتے تھے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’دو صاع کھجور کا سودا ایک صاع کے بدلے نہیں ہو سکتا۔ نہ دو در ہم کو ایک در ہم کے بدلے فروخت کیا جا سکتا ہے۔‘‘"}],[4557,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ بلال رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس برنی نامی کھجور لائے، تو آپ نے فرمایا: \"یہ کیا ہے؟\" وہ بولے: یہ میں نے ایک صاع دو صاع دے کر خریدی ہیں۔ آپ نے فرمایا: \"افسوس! یہ تو عین سود ہے، اس کے نزدیک مت جانا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے مروی ہے کہ حضرت بلال رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے اپس برنی کھجوریں لے کر آئے۔ آپ نے فرمایا: ’’یہ کیسے؟‘‘ وہ کہنے لگے: میں نے عام کھجوروں کے دو صاع دے کر یہ ایک صاع لی ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اوہو! اوہو! یہ تو عین سود ہے۔ اس کے قریب مت جانا۔‘‘","f2":"1)کھجور کو کھجور کے بدلے میں، کمی بیشی کے ساتھ بیچنا حرام ہے، نیز اس حدیث سے معلوم ہوا کہ حاکم وقت کو اپنی رعایا اور متعلقہ لوگوں کے حالات سے باخبر رہنا چاہیے، اسے ان کے مفادات کا خیال رکھنا چاہیے اور ان کی طرف خاص توجہ دینی چاہیے۔2) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ امام اور ذمہ دار شخص جب کوئی ایسی بات سنے جو شرعاََ جائز ہو یا ایسی چیز اور معاملہ دیکھے جو شرعاََ حرام ہو تو اسے حرام کام کرنے والوں کو نہ صرف روکنا چاہیے بلکہ حق کی طرف ان کی رہنمائی بھی کرنی چاہیے۔3) یہ حدیث مبارکہ اس اہم مسئلے کی صریح دلیل ہے کہ خبر واحد شرعی حجت ہے۔ 4)’’عین سود‘‘ یعنی خالص سود کیونکہ دونوں طرف ایک ہی جنس ہو تو سودے میں کمی بیشی سود ہے۔"}],[4558,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونا، چاندی کے بدلے سود ہے، سوائے اس کے کہ نقدا نقد ہو، کھجور کھجور کے بدلے سود ہے، سوائے اس کے کہ نقدا نقد ہو، گی ہوں گیہوں کے بدلے سود ہے، سوائے اس کے کہ نقدا نقد ہو، جو جو کے بدلے سود ہے، سوائے اس کے کہ نقدا نقد ہو\" ۱؎۔\n§وضاحت\n۱؎: اس روایت میں چار ہی چیزوں کا ذکر ہے لیکن ابوسعید رضی اللہ عنہ کی جو صحیحین میں وارد حدیث میں دو چیزوں چاندی اور نمک کا اضافہ ہے، اس طرح ان چھ چیزوں میں «تفاضل» :(کمی بیشی ) اور «نسیئہ» :(ادھار ) جائز نہیں ہے، اگر ایک ہاتھ سے دے اور دوسرے ہاتھ سے لے تو جائز اور صحیح ہے اور اگر ایک طرف سے بھی ادھار ہو تو یہ سود ہو جائے گا۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سونے کا سودا چاندی کے ساتھ سود ہے الا یہ کہ نقد سود نہیں۔ گندم کا سودا گندم کے ساتھ سود ہے الا یہ کہ نقد ہو۔ اور جو کا سودا جو کے ساتھ سود ہے الا یہ کہ سودا نقد ہو۔‘‘","f2":"1)اس حدیث میں وہ سود بیان کیا گیا ہے جس کا تعلق خرید و فروخت سے ہوتا ہے۔ سود کی دوسری قسم وہ ہے جس کا تعلق لین دین، یعنی تھوڑی چیز قرض دے کر زیادہ چیز لینے کی شرط لگانا۔ اسے قرض کا سود کہتے ہیں۔ خرید و فروخت میں سود یہ ہے کہ دونوں طرف ایک ہی جنس ہو مگر ان میں کمی بیشی کی جائے یا ادھار ہو، سودا نقد نہ ہو، جیسے مندرجہ بالا روایت میں مثالیں دے کر واضح کر دیا گیا ہے، یا پھر جنس تو مختلف ہو مگر سودا ادھار ہو، جیسے کہ پہلی مثال میں صراحت ہے کہ سونا چاندی کے عوض بھی سود ہے جبکہ سودا نقد نہ ہو کیونکہ چیزوں اور جنسوں کے بھاؤ بدلتے رہتے ہیں، لہٰذا جب دونوں طرف ایک ہی جنس ہو یا مختلف جنسیں ہوں، ادھار قطعاََ نہیں ہونا چاہیے، البتہ اگر اجناس مختلف ہوں تو کمی بیشی جائز ہے۔ اگر سودا روپے پیسے کے ساتھ کسی جنس کا ہو، مثلاََ: کھجور، گندم، جو وغیرہ کا تو اس میں ادھار بھی جائز ہے۔2) ’’مگر نقد‘‘ عربی میں لفظ ہیں: یعنی دونوں یہ کہیں تو لازماََ سودا نقد ہوگا، اس لیے لازم معنی کیا گیا ہے۔"}],[4559,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھجور کے بدلے کھجور، گیہوں کے بدلے گی ہوں، جَو کے بدلے جَو اور نمک کے بدلے نمک میں خرید و فروخت نقدا نقد ہے، جس نے زیادہ دیا، یا زیادہ لیا تو اس نے سود لیا، سوائے اس کے کہ جنس بدل جائے\" ۱؎۔\n§وضاحت\n۱؎: سود صرف انہی چار چیزوں میں کمی زیادتی میں نہیں ہے، بلکہ اگلی حدیث میں دو اور چیزوں کا تذکرہ ہے، نیز صرف انہی چھ کی بیع میں تفاضل سود نہیں ہے بلکہ یہ دنیا کی ہر چیز میں موجود ہے سوائے ان چیزوں کے جن کو شریعت نے مستثنی کر دیا ہے جیسے: جانور، پس ایک اونٹ کے بدلے دو اونٹ بیچ سکتے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کھجور کا سودا کھجور کے ساتھ، گندم کا گندم کے ساتھ، جو کا جو کے ساتھ اور نمک کا نمک کے ساتھ سودا نقد (اور برابر) ہونا چاہیے۔ جو زیادہ دے یا زیادہ لے، اس نے سود کا لین دین کیا۔ الا یہ کہ جنسیں بدل جائیں۔‘‘","f2":"1)امام نسائی رحمہ اللہ کا مقصد یہ ہے کہ کھجور کا کھجور کے عوض سودا جائز ہے بشر طیکہ دونوں طرف سے نقد بہ نقد اور برابری ہو۔2) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ حدیث میں مذکورہ اشیاء کی ایک دوسرے کے عوض بیع جائز ہے بشر طیکہ وہ اشیاء برابر مقدار میں ہوں، سودا نقد ہو اور اسی مجلس میں دونوں فریق چیز کو اپنے اپنے قبضے میں لے لیں۔3) سود لینے سے، صرف لینے والا ہی گناہ گار نہیں ہوتا بلکہ دینے والا بھی مجرم ہوتا ہے، لہٰذا سود لینے والے اور دینے والے دونوں کو اس بچنا چاہیے۔ 4)حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ جنس بدل جائے تو کمی بیشی جائز ہے۔ امام نو وی رحمہ اللہ فرماتے ہیں کہ جنس کے مختلف ہونے کی صورت میں بھی تقابض (دونوں فریقوں کا چیز قبضے میں لینا) ضروری اور و اجب ہے۔ اس پر تقریباََ تمام اہل علم کا اتفاق ہے۔5) ’’جنسیں بدل جائیں‘‘ مثلاََ: کھجور کا سودا گندم کے ساتھ، گندم کا جو کے ساتھ، جو کا نمک کے ساتھ۔ ایسی صورت میں کمی بیشی جائز ہے، مثلاََ: دوکلو گندم دے کر نصف کلو کھجور لے تو کوئی حرج نہیں، البتہ سودا نقد ہونا چاہیے۔"}],[4560,"مسلم بن یسار اور عبداللہ بن عتیک کہتے ہیں کہ ایک دن عبادہ بن صامت اور معاویہ رضی اللہ عنہما اکٹھا ہوئے، عبادہ رضی اللہ عنہ نے لوگوں سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سونے کو سونے کے بدلے، چاندی کو چاندی کے بدلے، گیہوں کو گیہوں کے بدلے، جَو کو جَو کے بدلے اور کھجور کو کھجور کے بدلے (ان میں سے ایک نے کہا: نمک کو نمک کے بدلے، دوسرے نے یہ نہیں کہا) بیچنے سے منع کیا، مگر برابر برابر اور نقدا نقد، اور ہمیں حکم دیا کہ ہم سونا چاندی کے بدلے، چاندی سونے کے بدلے، گیہوں جو کے بدلے، جَو گیہوں کے بدلے نقداً نقد بیچیں جیسے بھی ہم چاہیں ۱؎ ان (دونوں تابعی راویوں) میں سے ایک نے یہ بھی کہا: \"جس نے زیادہ دیا یا زیادہ لیا تو اس نے سود لیا\"۔\n§وضاحت\n۱؎: یعنی کمی زیادتی کے ساتھ بیچ سکتے ہیں جب جنس مختلف ہو۔","الألباني: صحيح",{"u2":"حضرت مسلم بن یسار اور عبد اللہ بن عتیک سے روایت ہے کہ ایک منزل میں حضرت عبادہ بن صامت اور حضرت معاویہ رضی اللہ عنہ جمع ہوئے تو حضرت عبادہ رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سونے کے بدلے سونے، چاندی کے بدلے چاندی، گندم کے بدلے گندم، جو کے بدلے جو، کھجوروں کے بدلے کھجوریں… ان دونوں استادوں (مسلم بن یسار اور عبد اللہ بن عتیک) میں سے ایک نے (یہ بھی) کہا، جبکہ دوسرے نے یہ الفاظ نہیں کہے… اور نمک کے بدلے نمک کے سودے سے منع فرمایا الا یہ کہ وہ دونوں برابر ار نقد ہوں، البتہ ہمیں اجازت عطا فرمائی کہ ہم سونے کو چاندی جو سونے کے بدلے، گندم کو جو کے بدلے اور جو کو گندم کے بدلے جیسے چاہیں کم و بیش خریدو فروخت کر سکتے ہیں بشر طیکہ سودا نقد ہو۔ (جنس ایک ہونے کی صورت میں) جو شخص زیادہ دے یا زیادہ لے، اس نے سودی لین دین کیا۔","f2":"1)گندم کے بدلے گندم بیچنی شرعاََ جائز ہے بشر طیکہ دونوں طرف سے گندم برابر ہو، نیز فریقین اسے اسی مجلس میں اپنے اپنے قبضے میں بھی لے لیں۔2) اس حدیث مبارکہ مختلف طرق (سندیں) دیکھنے سے بات اچھی طرح واضح ہو جاتی ہے کہ صحابہ کرام رضی اللہ عنہم نے رسول اللہ صلی اللہ علیہ وسلم سے جو عہد وفا باندھا تھا اسے نہ صرف نبھایا بلکہ وفا کا حق ادا کر دیا۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ پر جو بیعت کی تھی اس کے تقاضے پورے کیے، خواہ اس ایفائے عہد سے ان کے کسی امیر کو تکلیف پہنچنے کا اندیشہ ہو یا گواری محسوس ہوتی ہو۔ حضرت عبادہ بن صامت رضی اللہ عنہ بھی انھی جلیل القدر عظماء میں سے تھے جنھوں نے نبی صلی اللہ علیہ وسلم سے اس بات پر بیعت کی تھی کہ وہ اللہ تعالیٰ کے دین کے معالے میں کسی ملامت گر کی ملامت کی پروا نہیں کریں گے۔ سیدنا عبادہ بن صامت رضی اللہ عنہ کے حدیث بیان کرنے کی اصل وجہ یہ ہے کہ ایک غزوے میں لوگوں کو بہت سی غنیمتیں حاصل ہوئیں۔ غنیمتوں میں چاندی کے برتن بھی تھے۔ اس وقت ان لوگوں کے امیر حضرت معاویہ رضی اللہ عنہ تھے اور انھوں نے ایک شخص کو حکم دیا کہ ان لوگوں کو، وہ چاندی کے برتن جو بطور غنیمت ملے تھے، وہ برتن بیچ دے اور لوگوں کو بیت المال سے جو عطایا ملتے تھے جب وہ ملیں گے تو اس وقت ان چاندی کے برتنوں کی قیمت ان سے وصولی کر لی جائے گی۔ لوگوں نے دھڑا دھڑ یہ سودا کرنا شروع کر دیا۔ سیدنا عبادہ بن صامت تک یہ بات پہنچی تو وہ اٹھ کھڑے ہوئے اور لوگوں کو رسول اللہ صلی اللہ علیہ وسلم کی مذکورہ حدیث سنا دی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے سونے چاندی کی بیع ادھار پر کرنے سے منع فرمایا ہے۔ ان کی خریدو فروخت نقد کی صورت میں ہو سکتی ہے ورنہ نہیں۔ یہ سن کر لوگوں نے چاندی کے جو برتن ان سے خرید لیے تھے واپس کر دیے اور سودا ختم کر دیا۔ سیدنا معاویہ رضی اللہ عنہ کو جب یہ بات معلوم ہوئی تو انھوں نے لوگوں کو خطبہ دیا اور فرمایا لوگوں کو کیا ہوگیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم سے ایسی احادیث بیان کرتے ہیں جو ہم نے آپ سے نہیں سنی ہوتیں، حالانکہ ہم بھی رسول اللہ صلی اللہ علیہ وسلم کی صحبت میں رہے ہیں۔ سیدنا عبادہ بن صامت رضی اللہ عنہ یہ بات سن کر پھر کھڑے ہو گئے اور وہی حدیث مبارکہ دوبارہ سنا دی جو انھوں نے پہلے سنائی تھی اور اس کے ساتھ ساتھ یہ بھی فرما دیا کہ ہم نے جو کچھ رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے وہ ضرور بیان کریں گے، خواہ وہ معاویہ رضی اللہ عنہ کو کتنا ہی نا گوار گزرے یا فرمایا کہ اس سے معاویہ رضی اللہ عنہ اپنی ذلت محسوس کریں اور ساتھ ہی حضرت عبادہ رضی اللہ عنہ نے یہ فرمایا کہ یہ مسئلہ بیان کرنے کی وجہ سے اگر میں حضرت معاویہ رضی اللہ عنہ کے لشکر میں ایک رات بھی نہ رہ سکوں تو مجھے اس کی قطعاََ کوئی پروا نہیں۔ میں نے جو کچھ رسول اللہ صلی اللہ علیہ وسلم سے سن رکھا ہے، وہ ضرور بیان کروں گا، خواہ آج کا کوئی حکمران اسے پسند کرے یا نہ کرے۔ تفصیل کے لیے دیکھیے: اس تفصیل سے یہ بھی واضح ہوتا ہے کہ صحابہ کرام رضی اللہ عنہم کی جیتی جاگتی تصویر تھے۔ قاضی عیاض رحمہ اللہ فرماتے ہیں کہ اللہ تعالیٰ نے علمائے حق پر جو بھاری ذمہ داری عائد کی ہے اس کا تقاضا ہے کہ وہ لوگوں کے سامنے حق کھل کر بیان کریں، حق کو قطعاََ نہ چھپائیں، نیز عدل و انصاف کے تقاضے پورے کرنے والیل بن جائیں اور دنیا میں بن کر رہیں۔3) اس حدیث سے معلوم ہوا کہ سنن کی تبلیغ کا خصوصی اہتمام کیا جائے علم رسول پھیلا یا جائے چاہے کوئی بڑے سے بڑے بڑا شخص اس کو نا پسند ہی کرتا ہو۔ حق بات برملا اور سب کے سامنے کہنی چاہیے۔4) حدیث مبارکہ سے مذکورہ اشیاء کی باہمی خرید و فروخت کا جواز بھی نکلتا ہے۔ ہم جنس اشیاء میں برابری اور تقابض کی شرط ہے۔ لیکن اگر جنس مختلف ہو جائے تو ان میں کمی بیشی تو جائز ہے لیکن سودے کا ہاتھوں ہاتھ ہونا شرط ہے۔5) اس حدیث مبارکہ سے ان لوگوں کا رد ہوتا ہے جو گندم اور جو، کو ایک ہی جنس شمار کرتے ہیں۔ یہ دونوں ایک جنس نہیں بلکہ دو مختلف جنسیں ہیں۔ رسول اللہ صلی اللہ علیہ وسلم کے مذکورہ الفاظ اس کی صریح دلیل ہیں، آپ نے فرمایا: ’’گندم کے عوض جو اور جو کے عوض گندم بیچ سکتے ہو جس طرح چاہو بشر طیکہ سودا نقدبہ نقد ہو، یعنی ادھار کسی طرف سے نہ ہو۔6)‘‘ مذکورہ چھ چیزوں میں کمی بیشی تو واقعی سود ہے، البتہ اس بات میں اختلاف ہے کہ ان چھ کے علاوہ دوسری کون سی اشیاء میں کمی بیشی سود میں شمار ہو گی۔ امام ابو حنیفہ رحمہ اللہ نے تمام مکیلات و موزونات (جن چیزیں کھانے اور خوراک کے کام آتی ہیں) اس حکم کے تحت داخل ہیں بشر طیکہ ان کو ذخیرہ کیا جا سکے۔ امام شافعی رحمہ اللہ نے دونوں قیود کو ملحوظ رکھا ہے، یعنی وہ مکیلہ و موزون بھی ہوں خوراک بھی ہوں۔ اہل ظرہر کا موقف ہے کہ سود صرف ان مذکورہ چھ چیزوں میں منحصر ہے۔ ان کے علاوہ کسی بھی چیز میں کمی بیشی سود شمار نہیں ہو گی، مگر یہ بات عقلی طور پر قابل قبول نہیں کیونکہ شریعت کے احکام کسی نہ کسی مقصد کی خاطر لاگو ہوتے ہیں۔ مذکورہ چیزوں کی بیع کمی بیشی کے ساتھ روکنے میں ایک مقصد سادگی اور قناعت پسندی بھی ہے۔ ظاہر ہے اچھی گندم نا قص گندم کے مقابلے میں ملنے سے تو رہی۔ کوئی شخص بھی ردی کھجوروں کے مقابلے میں اعلیٰ قسم کی کھجوریں نہیں دے گا۔ مذکور قسم کی بیع سے روکنے کا یہ کا فائدہ گا کہ لوگ اپنے پاس موجود گندم، جو کھجوروں پر ہی قناعت کریں گے اور ذائقے کی تلاش میں سر گرداں نہیں ہوں گے۔ اس سے مہنگائی ختم ہو گی۔ عموما لوگوں کے پاس جنس ہی ہوتی ہے۔ پیسے کم ہی ہوتے ہیں، لہٰذا وہ اعلیٰ سے اعلیٰ کے حصول کے چکر میں نہیں پڑیں گے اور سادگی اور قناعت کا دور دورہ ہو گا۔ معاشرہ افرا تفری سے محفوظ رہے گا۔ اس مقصد کو پیش نظر رکھا جائے تو امام مالک رحمہ اللہ کی بات زیادہ قرین قیاس ہے کہ یہ حکم ان تمام چیزوں کے بارے میں ہے جو بطور خوراک استعمال ہوتی ہوں اور ان کو ذخیرہ بھی کیا جا سکے۔ جبکہ اہل ظاہر کا مسلک اس حدیث سے بھی رد ہوتا ہے جس میں بیل پر لگے انگوروں کی بیع معین منقیٰ سے کرنا ممنوع قرار دیا گیا ہے۔ ایسی بیع میں بھی کمی بیشی کا خطرہ ہو سکتا ہے، حالانکہ منقیٰ یا انگور اس حدیث میں مذکور چھ چیزوں میں داخل نہیں۔ امام ابو حنیفہ رحمہ اللہ کے مسلک کی رو سے ہوہا، پیتل وغیرہ بھی اس حکم میں آ جائیں گے، حالانکہ یہ چیزیں بذات خود فروخت ہونے کی بجائے عموما ان کی مصنوعات ہی فروخت ہوتی ہیں اور مصنوعات میں یہ حکم جاری کرنا تقریباََ نا ممکن ہے کیونکہ وہاں سودا صرف مادے کا نہیں بلکہ کار یگری اور مہارت کا بھی ہوتا ہے۔7) ’’ایک منزل میں‘‘ ان الفاظ ظاہرََا گھر بھی مراد ہو سکتا ہے۔ اور سفر کی منزل بھی، بھی، یہ دوسرا معنی ہی زیادہ مناسب معلوم ہوتا ہے جیسا کہ صحیح مسلم کی مذکورہ بالا تفصیلی حدیث: ۵۸۷ اسے معلوم ہوتا ہے کہ یہ واقعہ دشمنوں کے ساتھ ایک لڑائی کے موقع پر پیش آیا اور وہ یقینا سفر میں تھے۔"}],[4561,"مسلم بن یسار اور عبداللہ بن عبید (ابن عتیک) (ان کو ابن ہرمز بھی کہا جاتا ہے) بیان کرتے ہیں کہ عبادہ بن صامت اور معاویہ رضی اللہ عنہما ایک جگہ اکٹھا ہوئے، عبادہ رضی اللہ عنہ نے لوگوں سے حدیث بیان کی کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے سونا سونے کے بدلے، چاندی چاندی کے بدلے، کھجور کھجور کے بدلے، گیہوں گی ہوں کے بدلے اور «جَو جَو» کے بدلے (ان دونوں راویوں میں سے ایک نے کہا:) نمک نمک کے بدلے، (دوسرے نے یہ نہیں کہا) بیچنے سے منع کیا مگر برابر برابر، نقدا نقد (ان میں سے ایک نے کہا:) جس نے زیادہ دیا یا زیادہ طلب کیا، اس نے سود لیا، (اسے دوسرے (راوی) نے نہیں کہا) اور ہمیں حکم دیا کہ ہم سونا چاندی کے بدلے، چاندی سونے کے بدلے، گیہوں جَو کے بدلے اور جَو گیہوں کے بدلے بیچیں، نقدا نقد جس طرح چاہیں۔","الألباني: صحيح",{"u2":"حضرت مسلم بن یسار اور حضرت عبادہ بن صامت معاویہ رضی اللہ عنہ ایک جگہ اکٹھے تھے تو حضرت عبادہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سونا سونے کے بدلے، چاندی کے بدلے، کھجوریں کھجوروں کے بدلے، گندم گندم کے بدلے، جو جوکے بدلے بیچنے سے منع فرمایا۔ ایک استاد نے، نمک نمک کے بدلے، کے الفاظ بیان کیے، جبکہ دوسرے نے یہ الفاظ نہیں بیان کیے الا یہ کہ وہ (دونوں طرف سے مقدار میں) برابر ہوں (اور نقد سودا ہو)۔ جس نے زیادہ دیا یا زیادہ لی، اس نے سودی لین دین کیا۔ یہ الفاظ (زیادہ دیا یا زیادہ لیا) بھی ایک ہی استاد نے بیان کیے تھے، دوسرے نے نہیں کیے، البتہ آپ نے ہمیں اجازت دی کہ ہم سونے کو چاندی کے بدلے یا چاندی کو سونے کے بدلے اور گندم کو جوکے بدلے اور جو کو گندم کے بدلے جیسے چاہیں کم و بیش بیچ خرید سکتے ہیں بشر طیکہ سود ا نقد ہو۔","f2":"سونے اور چاندی کو اللہ تعالیٰ نے تجارت کے لیے پیدا فرمایا ہے۔ اور یہ قیمت بنتے ہیں۔ جب سونے کے مقابلے میں سونا یا چاندی کے مقابلے میں چاندی ہو تو ان میں کمی بیشی منع ہے، لہٰذا جو چیزیں قیمت بنتی ہوں، ان میں بھی کمی بیشی منع ہو گی، مثلاََ: کرنسی نوٹ، بانڈ اور سر ٹیفکیٹ وغیرہ۔ سو روپے کا بانڈ یا سر ٹیفکیٹ سو روپے سے زائد میں خریدا یا بیچا نہیں جا سکتا ورنہ بن جائے۔ اگر لوہے تابنے کے سکے بنائے جائیں یا لوہے تانبے کو بطور قیمت استعمال کیا جائے تو ان کی بیع یا تبادلے میں بھی کمی بیشی منع ہو گی، مثلاََ: سو روپے کا کرنسی نوٹ تبادلے میں سو روپوں کے سکوں کے برابر تصور کیا جائے گا۔ کمی بیشی منع ہو گی۔ آج کل مروجہ شیئرز (حصص) بھی اپنی اصل مالیت سے کم و بیش فروخت نہیں کیے جا سکتے۔"}],[4562,"مسلم بن یسار اور عبداللہ بن عبید کہتے ہیں کہ عبادہ بن صامت اور معاویہ رضی اللہ عنہما ایک جگہ اکٹھا ہوئے تو عبادہ رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ ہم سونا سونے کے بدلے، چاندی چاندی کے بدلے، گیہوں گیہوں کے بدلے، «جَو جَو» کے بدلے اور کھجور کھجور کے بدلے بیچیں مگر نقدا نقد اور برابر برابر(ان دونوں راویوں میں سے کسی ایک نے کہا:) اور نمک نمک کے بدلے، (یہ دوسرے نے نہیں کہا اور پھر ان میں سے ایک نے کہا:) جس نے زیادہ دیا یا زیادہ کا مطالبہ کیا تو اس نے سود کا کام کیا، (یہ دوسرے نے نہیں کہا) اور آپ نے ہمیں حکم دیا کہ ہم سونا چاندی سے، چاندی سونے سے، گیہوں جَو سے اور جَو گیہوں سے نقدا نقد بیچیں، جس طرح چاہیں (یعنی کم و زیادتی)۔ جب یہ حدیث معاویہ رضی اللہ عنہ کو پہنچی تو انہوں نے کھڑے ہو کر کہا: کیا بات ہے آخر لوگ رسول اللہ صلی اللہ علیہ وسلم سے ایسی حدیثیں بیان کرتے ہیں جو ہم نے نہیں سنیں حالانکہ ہم بھی آپ کی صحبت میں رہے، یہ بات عبادہ بن صامت رضی اللہ عنہ کو پہنچی تو وہ کھڑے ہوئے اور دوبارہ حدیث بیان کی اور بولے: ہم تو اسے ضرور بیان کریں گے جو ہم نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے گرچہ معاویہ رضی اللہ عنہ کو یہ ناپسند ہو۔ قتادہ نے اس حدیث کو اس کے برعکس مسلم بن یسار سے، انہوں نے ابوالاشعث سے انہوں نے عبادہ رضی اللہ عنہ سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت اور حضرت معاویہ رضی اللہ عنہ ایک منزل میں اکٹھے ہوئے تو حضرت عبادہ رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ ہم سونا سونے کے بدلے، چاندی چاندی کے بدلے، گندم گندم کے بدلے، جو جو کے بدلے، کھجوریں کھجوروں کے بدلے… دونوں میں سے ایک استاد نے یہ الفاظ (جن میں نمک کا ذکر ہے) بیان کیے تھے جبکہ دوسرے نے بیان نہیں کیے… اور نمک نمک کے بدلے بیچیں مگر جبکہ دونوں ایک دوسرے کے برابر ہوں (اور بیع نقد ہو)۔ جو شخص زیادہ دے گا یا لے گا، اس نے سودی کاروبار کیا … یہ الفاظ (جو شخص زیادہ دے گا یالے گا اس نے سودی کارو بار) بھی دونوں میں سے ایک استاد نے بیان کیے تھے، دوسرے نے بیان نہیں کیے … البتہ آپ نے ہمیں اجازت دی کہ ہم سونے کو چاندی کے بدلے، چاندی کو سونے کے بدلے، گندم کو جو کے بدلے اور جو گندم کے بدلے جیسے چاہیں بیچیں بشر طیکہ سودا نقد ہو۔ یہ حدیث حضرت معاویہ رضی اللہ عنہ کو پہنچی تو وہ کہنے لگے: عجیب بات ہے کہ کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم سے ایسی احادیث بیان کرتے ہیں جو ہم نے تو نہیں سنیں اگرچہ ہم بھی آپ کے ساتھ رہے ہیں۔ یہ بات حضرت عبادہ بن صامت رضی اللہ عنہ کو پہنچی تو کھڑے ہو کر دوبارہ حدیث پڑھی اور فرمانے لگے: ہم نے جو بات رسول اللہ صلی اللہ علیہ وسلم کی زبان مبارک سے سنی ہے، ضرور بیان کریں گے اگرچہ معاویہ (رضی اللہ عنہ) اسے ناپسند ہی کرے۔\n(امام نسائی رحمہ اللہ فرماتے ہیں کہ) قتادہ نے اس (محمد بن سیرین) کی مخالفت کی ہے۔ انھوں نے یہ روایت سے بیان کی ہے۔","f2":"1)مذکورہ روایت میں سلمہ بن علقمہ کے دو استاد ہیں: ایک محمد بن سیرین اور دوسرے قتادہ۔ محمد بن سیرین نے جب یہ روایت بیان کی تو فرمایا: [عَنْ مُسْلِمِ بْنِ یَسَارٍ عَنْ عُبَادَۃَ بْنِ الصَّامِتِ] اور جب قتادہ نے یہ روایت بیان کی تو فرمایا: [عَنْ مُسْلِمِ بْنِ یَسَارٍ عَنْ اَبِی الْأَشْعَثِ الصَّنْعَانِیِّ عَنْ عُبَادَۃَ بْنِ الصَّامِتِ] مطلب یہ ہے کہ قتادہ نے مسلم بن یسار اور حضرت عبادہ رضی اللہ عنہ کے درمیان ابو الاشعث صنعانی کا واسطہ بھی بیان کیا ہے جیسا کہ اگلی روایت: ۴۵۶۷ کی سند سے واضح ہوتا ہے۔ (۲) حضرت عبادہ بن صامت رضی اللہ عنہ بیعت عقبہ کے نقباء میں سے ہیں۔ انصار کے اولیں مسلمانوں میں شامل ہیں۔ رسول اللہ صلی اللہ علیہ وسلم کے زیر سایہ ان کا دور تعلیم و تربیت حضرت معاویہ رضی اللہ عنہ سے بہت زیادہ ہے۔ حضرت معاویہ رضی اللہ عنہ تو صلح حدیبیہ کے بعد اگلے سال ۷ ہجری میں مسلمان ہوئے۔ انھیں ان کی نسبت آپ سے فیض حاصل کرنے کا موقع کم ملا ہے، لہٰذا کوئی تعجب کی بات نہیں کہ حضرت معاویہ رضی اللہ عنہ نے یہ فرمان رسول اللہ صلی اللہ علیہ وسلم کی زبان مبارک سے نہ سنا ہو۔ یہ فرمان حضرت ابوہریرہ، حضرت عمر اور دیگر صحابہ کرام رضی اللہ عنہم سے بھی مروی ہے۔ اور بلا شک وشبہ صحیح ہے۔"}],[4563,"عبادہ بن صامت رضی اللہ عنہ سے روایت ہے (وہ بدری صحابی ہیں، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی تھی کہ وہ اللہ کے معاملے میں کسی ملامت کرنے والے کی ملامت سے نہ ڈریں گے) کہ وہ خطاب کرنے کے لیے کھڑے ہوئے اور کہا: لوگو! تم نے خرید و فروخت سے متعلق بعض ایسی چیزیں ایجاد کر لی ہیں کہ میں نہیں جانتا کہ وہ کیا ہیں؟ سنو! سونا سونے کے بدلے، برابر برابر وزن کا ہو، ڈلا ہو یا سکہ، چاندی چاندی کے بدلے برابر برابر وزن ڈالا ہو یا سکہ، اور کوئی حرج نہیں(یعنی) چاندی کو سونے سے نقدا نقد بیچنے میں جب کہ چاندی زیادہ ہو، البتہ اس میں «نسیئہ» (ادھار) درست نہیں، سنو! گیہوں گیہوں کے بدلے، اور «جَو جَو» کے بدلے برابر برابر ہو، البتہ جَو گیہوں کے بدلے نقدا نقد بیچنے میں کوئی حرج نہیں جب جَو زیادہ ہو لیکن «نسیئہ» (ادھار) درست نہیں، سنو! کھجور کھجور کے بدلے برابر برابر ہو یہاں تک کہ انہوں نے ذکر کیا کہ نمک (نمک کے بدلے) برابر برابر ہو، جس نے زیادہ دیا، یا زیادہ کا مطالبہ کیا تو اس نے سود لیا۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت ہے، وہ بدری صحابی تھے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے بیعت کی تھی کہ ہم اللہ تعالیٰ (کی شریعت) کے بارے میں کسی ملامت کرنے والے کی ملامت کا خوف نہیں رکھیں گے۔ تو حضرت عبادہ رضی اللہ عنہ خطبہ دینے کے لیے کھڑے ہوئے اور فرمایا: اے لوگو! تم نے کچھ ایسی خرید و فروخت کی صورتیں شروع کر لی ہیں کہ میں نہیں جانتا وہ کیا ہیں؟ خبردار! سونا سونے کے بدلے تول کر برابر دیا جائے ڈلی ہو یا سکہ، چاندی چاندی کے بدلے تول کر برابر دی جائے ڈلی ہو یا سکہ، البتہ چاندی سونے کے بدلے ہو تو کوئی حرج نہیں کہ چاندی زیادہ ہو جبکہ سودا نقد ہو۔ ادھار درست نہیں۔ خبردارا! گندم گندم کے بدلے اور جو جو کے بدلے ماپ کر برابر دیے جائیں، البتہ جو کو گندم کے بدلے نقد فروخت کیا جائے تو کوئی حرج نہیں کہ جو زیادہ ہوں لیکن ادھار درست نہیں۔ خبردار! کھجور کھجور کے عوض ماپ کر برابر دی جائے حتیٰ کہ آپ نے نمک کا بھی ذکر فرمایا کہ وہ بھی ماپ کر برابر دیا جائے۔ جو شخص زیادہ دے یا زیادہ لے، اس نے سودی لین دین کیا۔"}],[4564,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونا سونے کے بدلے، ڈلا ہو یا سکہ، برابر برابر ہو، چاندی چاندی کے بدلے ڈالا ہو یا سکہ، برابر برابر ہو، نمک نمک کے بدلے، کھجور کھجور کے بدلے، گیہوں گیہوں کے بدلے اور «جَو جَو» کے بدلے برابر برابر اور یکساں ہو، لہٰذا جو زیادہ دے یا زیادہ کا مطالبہ کرے تو اس نے سود لیا\"۔ یہ الفاظ محمد بن المثنی کے ہیں، ابراہیم بن یعقوب نے \"جَو جَو کے بدلے\" کا ذکر نہیں کیا۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سونا سونے کے بدلے تول کر عین برابر دیا جائے، ڈلی ہو سکہ۔ چاندی چاندی کے برابر تول کر عین برابر دی جائے، ڈلی ہو یا سکہ۔ اسی طرح نمک نمک کے برابر، کھجور کھجور کے برابر، گندم گندم کے برابر اور جو جو کے برابر خریدے بیچے جائیں۔ جو شخص زیادہ دے یا زیادہ لے، اس نے سودی کاروبار کیا۔ مذکورہ الفاظ محمد بن مثنیٰ کے ہیں، یعقوب نے ’’جو جو کے برابر‘‘ والے الفاظ ذکر نہیں کیے۔","f2":"(۱) امام نسائی رحمہ اللہ نے یہ روایت دو استادوں سے بیان کی، ایک محمد بن مثنیٰ اور دوسرے یعقوب بن ابراہیم۔ دونوں استاد ساری روایت ایک جیسی بیان کرتے ہیں لیکن یہ جملہ وَالشَّعِیرُ بِالشَّعِیرِ صرف استاد محمد بن مثنیٰ بیان کرتے ہیں، دوسرے استاد نے یہ جملہ بیان نہیں کیا۔ (۲) مذکورہ روایت بیان کرنے والے ایک استاد کا نام سنن نسائی میں یعقوب بن ابراہیم بیان کیا گیا ہے۔ سنن النسائی (المجتبیٰ) کے تمام نسخوں میں یہی نام مذکور ہے لیکن یہ غلط ہے۔ درست نام ’’ابراہیم بن یعقوب الجوزجانی‘‘ ہے لیکن یہ بات یاد رہے کہ امام نسائی رحمہ اللہ کے ایک استاد یعقوب بن ابراہیم الدورقی بھی ہیں لیکن مذکورہ روایت ان کی بیان کردہ نہیں بلکہ یہ ابراہیم بن یعقوب الجوزجانی کی بیان کردہ ہے۔ یہ تمام تر وضاحت حافظ مزی رحمہ اللہ نے تحفۃ الاشراف میں بیان کی ہے۔ دیکھیے: (تحفۃالاشراف: ۴/ ۴۵۰) مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی للاتبوبی: ۳۴/ ۳۶۲)"}],[4565,"سلیمان بن علی سے روایت ہے کہ بازار میں ان کے پاس سے ابوالمتوکل کا گزر ہوا، تو کچھ لوگ ان کے پاس گئے، ان لوگوں میں میں بھی تھا، ہم نے کہا: ہم آپ کے پاس آئے ہیں تاکہ آپ سے بیع صرف ۱؎ کے بارے میں پوچھیں، تو انہوں نے کہا: میں نے ابو سعید خدری رضی اللہ عنہ کو (کہتے) سنا، (اس پر) ایک شخص نے ان سے کہا: آپ کے اور رسول اللہ صلی اللہ علیہ وسلم کے درمیان ابوسعید رضی اللہ عنہ کے علاوہ اور کوئی نہیں ہے؟ انہوں نے کہا: میرے اور آپ صلی اللہ علیہ وسلم کے درمیان ان (ابوسعید رضی اللہ عنہ) کے علاوہ کوئی نہیں ہے۔ انہوں نے کہا: سونا سونے کے بدلے اور چاندی چاندی کے بدلے اور گیہوں گیہوں کے بدلے، «جَو جَو» کے بدلے، کھجور کھجور کے بدلے، نمک نمک کے بدلے برابر برابر ہو، اب جو اس میں زیادہ دے یا زیادہ کا مطالبہ کرے تو اس نے سود کا کام کیا، اور سود لینے اور دینے والے(جرم میں) دونوں برابر ہیں۔\n§وضاحت\n۱؎: سونا چاندی کو سونا چاندی کے بدلے نقدا بیچنا بیع صرف ہے، اور اسی کو «بیع اثمان» بھی کہتے ہیں۔","الألباني: صحيح",{"u2":"حضرت سلیمان بن علی سے روایت ہے کہ حضرت ابو المتوکل ہمارے پاس سے بازار میں گزرے۔ بہت سے لوگ ان کی طرف اٹھے۔ ان میں میں بھی شامل تھا۔ ہم نے کہا کہ ہم آپ سے سونے چاندی کے تبادلے کے بارے میں پوچھنے آئے ہیں۔ وہ فرمانے لگے: میں نے حضرت ابو سعید خدری رضی اللہ عنہ سے سنا۔ اتنے میں ایک آدمی نے کہا: کیا آپ کے اور رسول اللہ صلی اللہ علیہ وسلم کے درمیان حضرت ابو سعید خدری رضی اللہ عنہ کے علاوہ اور کوئی واسطہ نہیں؟ تو ابوالمتوکل نے کہا: نہیں، میرے اور آپ کے درمیان ان کے علاوہ اور کوئی نہیں۔ انھوں نے فرمایا: سونا سونے کے بدلے، چاندی چاندی کے بدلے، گندم گندم کے بدلے، جو جو کے بدلے، کھجور کھجور کے بدلے اور نمک نمک کے بدلے عین برابر سودا کیا جائے۔ جس نے زیادہ دیا یا زیادہ لیا، اس نے سودی کاروبار کیا۔ لینے دینے والا برابر کے گناہ گار ہیں۔"}],[4566,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"سونا ایک پلڑا دوسرے پلڑے کے برابر ہو\"، تو معاویہ رضی اللہ عنہ نے کہا: یہ بات تو میرے سمجھ میں نہیں آتی، تو عبادہ رضی اللہ عنہ نے کہا: اللہ کی قسم! مجھے پروا نہیں اگر میں اس سر زمین میں نہ رہوں جہاں معاویہ رضی اللہ عنہ رہیں، میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے۔","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’سونا سونے کے بدلے بالکل برابر وزن کے ساتھ بیچا جائے۔‘‘\n(راوی حدیث) یعقوب نے الکفۃ بالکفۃ کے الفاظ ذکر نہیں کیے (بلکہ اس کے بدلے کوئی اور الفاظ کہے جیسا کہ تفصیلی روایات سے معلوم ہوتا ہے)۔ حضرت معاویہ رضی اللہ عنہ کہنے لگے: یہ کوئی معتبر نہیں کہہ رہے۔ حضرت عبادہ رضی اللہ عنہ فرمانے لگے: اللہ کی قسم! مجھے کوئی پرواہ نہیں کہ میں اس علاقے میں نہ رہوں جس میں معاویہ رہتے ہوں۔ میں گواہی دیتا ہوں کہ میں نے (خود) رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا ہے۔","f2":"’’معتبر بات نہیں کہہ رہے‘‘ حضرت معاویہ رضی اللہ عنہ نے یہ بات اپنے علم کے مطابق کہی لیکن چونکہ انداز مناسب نہیں تھا، اس لیے حضرت عبادہ بن صامت رضی اللہ عنہ نے اظہار ناراضی فرمایا۔ اور یہ ان کا حق بھی بنتا ہے۔ رَضِیَ اللّٰہُ عَنْھُمْ وَأَرْضَاھُمْ۔"}],[4567,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دینار کے بدلے دینار اور درہم کے بدلے درہم ہو تو ان دونوں میں کمی زیادتی نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دینار کا سودا دینار سے کرنا ہو اور درہم کا درہم سے تو کمی بیشی جائز نہیں۔‘‘","f2":"پرانے زمانے میں دینار سونے سے بنایا جاتا تھا اور درہم چاندی سے۔ جو حکم سونے کا وہی دینار کا اور جو حکم چاندی کا، وہی درہم کا۔"}],[4568,"عمر رضی اللہ عنہ کہتے ہیں کہ دینار کے بدلے دینار، درہم کے بدلے درہم کی بیع میں کمی زیادتی جائز نہیں، یہ ہم سے نبی اکرم صلی اللہ علیہ وسلم کا عہد ہے۔\n§وضاحت\n۱؎: یعنی آپ نے اس کا ہمیں حکم دیا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عمر رضی اللہ عنہ نے فرمایا: دینار کا سودا دینار سے ہو یا درہم کا درہم سے تو کمی بیشی جائز نہیں ہو سکتی۔ ہمارے پیارے نبی مکرم صلی اللہ علیہ وسلم کی طرف سے ہمیں یہ تاکید ہے۔"}],[4569,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونے کے بدلے سونا، برابر برابر اور یکساں ہو گا، اور چاندی کے بدلے چاندی برابر برابر اور یکساں ہو گی، جس نے زیادہ دیا یا زیادہ کا مطالبہ کیا تو اس نے سود کا کام کیا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سونا سونے کے بدلے میں تول کر برابر دیا جائے اور چاندی چاندی کے بدلے تول کر برابر دی جائے۔ جو شخص زیادہ دے یا زیادہ لے، اس نے سود کا لین دین کیا۔‘‘"}],[4570,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سونا سونے کے بدلے نہ بیچو مگر برابر برابر، اور ان میں سے ایک کا دوسرے پر اضافہ نہ کرو، اور چاندی کے بدلے چاندی مت بیچو مگر برابر برابر اور ان میں سے کسی کو نقد کے بدلے ادھار نہ بیچو\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سونا سونے کے بدلے نہ بیچو مگر برابر۔ کسی ایک کو دوسرے سے زیادہ نہ کرو۔ اور چاندی چاندی کے بدلے نہ بیچو مگر برابر اور ان میں سے کسی غائب کا نقد سے سودا نہ کرو۔‘‘","f2":"’’سودا نہ کرو‘‘ یعنی ادھار سودا جائز نہیں کیونکہ سونے چاندی کا بھاؤ اور باہمی تناسب بدلتا رہتا ہے۔ ایسی صورت میں جھگڑے کا امکان ہے۔ شریعت تنازع کو پسند نہیں کرتی۔"}],[4571,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میری آنکھوں نے دیکھا اور میرے کانوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ نے سونے کے بدلے سونا اور چاندی کے بدلے چاندی بیچنے سے روکا ہے، سوائے اس کے کہ وہ برابر ہوں، اور (ان میں سے) کسی نقد کے بدلے ادھار نہ بیچو، اور نہ ہی ان میں سے ایک کا دوسرے پر اضافہ کرو۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ نے فرمایا: میری آنکھوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا اور میرے کانوں نے آپ کے منہ مبارک سے سنا: ’’آپ نے سونے کی سونے کے بدلے اور چاندی کی چاندی کے بدلے خرید و فروخت سے منع فرمایا مگر جب (دونوں طرف سے) برابر ہوں۔ اور فرمایا کہ تم ان میں سے موجود کا غیر موجود سے سودا نہ کرو اور کسی ایک کو دوسرے سے زائد نہ کرو۔‘‘"}],[4572,"عطاء بن یسار سے روایت ہے کہ معاویہ رضی اللہ عنہ نے پینے کا برتن جو سونے یا چاندی کا تھا اس سے زائد وزن کے بدلے بیچا تو ابو الدرداء رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس طرح کی بیع سے منع فرماتے ہوئے سنا، سوائے اس کے کہ وہ برابر برابر ہوں۔","الألباني: صحيح",{"u2":"حضرت عطاء بن یسار سے منقول ہے کہ حضرت معاویہ رضی اللہ عنہ نے سونے یا چاندی کا ایک برتن اس کے وزن سے زیادہ سونے یا چاندی کے عوض خریدا۔ حضرت ابوالدردائ رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس جیسے سودے سے منع فرماتے سنا الا یہ کہ دونوں کا وزن برابر ہو۔","f2":"(۱) سونے کی خرید و فروخت سونے یا چاندی کی چاندی کے عوض درست ہے بشرطیکہ دونوں طرف سے برابری ہو اور سودا نقد بہ نقد ہو۔ اگر ایسا نہیں تو وہ بیع فاسد اور حرام ہے۔ (۲) ’’برتن‘‘ عربی میں لفظ سِقَایَۃً استعمال کیا گیا ہے، یعنی پانی وغیرہ پینے کا برتن۔ ویسے شریعت اسلامیہ میں سونے یا چاندی کے برتن میں کھانے پینے سے روکا گیا ہے۔ ممکن ہے انھوں نے زینت اور آرائش کے لیے خریدا ہو، یا کوئی اور مقصد بھی ہو سکتا ہے، المختصر وہ پینے کے لیے نہیں خرید سکتے۔ (۳)’’وزن سے زیادہ‘‘ کیونکہ برتن میں سونے کے علاوہ اس کے بنانے کی اجرت بھی تو شامل ہے لیکن شریعت میں سونے کے بدلے سونے کی بیع میں کمی بیشی منع ہے، لہٰذا اس مسئلے کا حل یہ ہے کہ اگر سونے کا برتن سونے کے ساتھ ہی خریدنا ہے تو برتن کے برابر سونا دیا جائے اور اجرت الگ چاندی وغیرہ کی صورت میں دی جائے، یا ایسے برتن کا سودا چاندی کے ساتھ کیا جائے اور چاندی کے برتن کا سونے سے تاکہ اجرت بھی وصول ہو جائے اور شرعی ضابطہ بھی برقرار رہے۔ سونے اور چاندی کی باہم بیع میں کمی بیشی کی کوئی حد مقرر نہیں، اس لیے اجرت کو بھی قیمت میں آسانی سے شامل کیا جا سکتا ہے۔ آج کل کرنسی نوٹوں نے ایسے مسائل حل کر دیے ہیں۔"}],[4573,"فضالہ بن عبید رضی اللہ عنہ کہتے ہیں کہ خیبر کے دن میں نے ایک ہار جس میں سونا اور نگینے لگے ہوئے تھے، بارہ دینار میں خریدا، پھر میں نے انہیں الگ کیا تو اس میں لگا ہوا سونا بارہ دینار سے زیادہ کا تھا، اس کا ذکر نبی اکرم صلی اللہ علیہ وسلم سے کیا گیا تو آپ نے فرمایا: \"جب تک الگ کر لیا جائے اسے نہ بیچا جائے\"۔","الألباني: صحيح",{"u2":"حضرت فضالہ بن عبید رضی اللہ عنہ سے روایت ہے کہ میں نے خیبر کے دن ایک ہار بارہ دینار کا خریدا جس میں سونے کے علاوہ موتی اور منکے بھی تھے۔ جب میں نے سونے اور موتی منکوں کو الگ الگ کیا تو اس سے بارہ دینار سے زائد سونا نکل آیا۔ یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی گئی تو آپ نے فرمایا: ’’اس قسم کی چیز کو نہ بیچا جائے حتی کہ سونے وغیرہ کو الگ الگ کر لیا جائے۔‘‘","f2":"(۱) مؤلف رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصد سونے کے ایسے ہار کی سونے کے عوض خرید و فروخت کا مسئلہ بیان کرنا ہے جس میں سونے کے علاوہ موتی، نگینے اور منکے وغیرہ بھی ہون۔ اس کا حکم یہ ہے کہ سونے کے ایسے ہار کی سونے کے عوض خرید و فروخت اس وقت تک حرام ہے جب تک اسے الگ الگ کر کے سونے کا وزن معلوم نہ کر لیا جائے۔ جب سونے کا وزن معلوم ہو جائے تو پھر اس سونے کے برابر سونا دیا جائے اور موتی نگینے اور منکے وغیرہ الگ کر کے ان کی قیمت دی جائے، یا جو بھی معاملہ طے ہو، اس کے مطابق کیا جائے۔ (۲) اگر تو ہار وغیرہ اس قسم کا ہو کہ اسے خراب کیے بغیر سونے کو موتیوں سے الگ کیا جا سکتا ہو تو الگ کرنے کے بعد ہر چیز کا الگ الگ سودا کیا جائے تاکہ سود کے شبہ سے حتی الامکان بچاؤ ہو سکے۔ اور اگر الگ الگ کرنے سے ہار خراب ہوتا ہو تو پھر سونے کے ہار کو چاندی، یعنی درہم کے عوض خریدا جائے اور چاندی کے ہار کو سونے، یعنی دینار کے عوض خریدا جائے جیسا کہ حدیث نمبر ۴۵۷۶ میں گزر چکا ہے۔ آج کل قیمت کرنسی نوٹوں کی صورت میں دی جاتی ہے، لہٰذا کوئی مسئلہ پیدا ہی نہیں ہونا چاہیے، اور نہ الگ کرنے کی ضرورت ہے۔ بعض حضرات نے ایسے ہار کو الگ الگ کیے بغیر کسی بھی صورت میں بیچنے کی نفی کی ہے اور ظاہر الفاظ کو پیش کیا ہے مگر یہ تکلیف مالا یطاق ہے۔ اس طرح تو زیورات کا بیچنا ایک لا یَنْحَل مسلہ ہوگا۔ الفاظ کے ساتھ ساتھ شریعت کے مقاصد کو بھی نگاہ میں رکھنا چاہیے ورنہ کبھی کبھی مضحکہ خیز نتائج حاصل ہو جاتے ہیں۔"}],[4574,"فضالہ بن عبید رضی اللہ عنہ کہتے ہیں کہ مجھے خیبر کے دن ایک ہار ملا جس میں سونا اور نگینے تھے، میں نے اسے بیچنا چاہا، اس کا تذکرہ نبی اکرم صلی اللہ علیہ وسلم سے کیا گیا تو آپ نے فرمایا: \"ایک کو دوسرے سے الگ کر دو پھر بیچو\"۔","الألباني: صحيح",{"u2":"حضرت فضالہ بن عبید رضی اللہ عنہ سے مروی ہے کہ جنگ خیبر کے دن مجھے ایک ایسا ہار ملا جس میں سونے کے علاوہ موتی اور منکے بھی تھے۔ میں نے اسے بیچنے کا ارادہ کیا۔ یہ بات نبی اکرم صلی اللہ علیہ وسلم سے ذکر کی گئی تو آپ نے فرمایا: ’’اس کے اجزا الگ الگ کر کے بیچ۔‘‘"}],[4575,"ابومنہال کہتے ہیں کہ شریک نے کچھ چاندی ادھار بیچی، پھر میرے پاس کر مجھے بتایا تو میں نے کہا: یہ درست نہیں، انہوں نے کہا: اللہ کی قسم! میں نے تو اسے بازار میں بیچا ہے، لیکن کسی نے اسے غلط نہیں کہا، چنانچہ میں براء بن عازب رضی اللہ عنہما کے پاس آ کر ان سے پوچھا تو انہوں نے کہا: مدینے میں رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس آئے اور ہم اسی طرح سے بیچا کرتے تھے، تو آپ نے فرمایا: \"جب تک نقدا نقد ہو تو کوئی حرج نہیں، لیکن ادھار ہو تو یہ سود ہے\"، پھر انہوں نے مجھ سے کہا: زید بن ارقم رضی اللہ عنہ کے پاس جاؤ، میں نے ان کے پاس جا کر معلوم کیا تو انہوں نے بھی اسی جیسا بتایا۔","الألباني: صحيح",{"u2":"حضرت ابومنہال سے روایت ہے کہ میرے ایک شریک نے چاندی کا سودا ادھار کر لیا، پھر وہ میرے پاس آیا اور مجھے بتایا۔ میں نے کہا: یہ تو درست نہیں۔ وہ کہنے لگا: اللہ کی قسم! میں نے یہ سودا بازار میں کیا ہے اور کسی نے بھی اس پر اعتراض نہیں کیا۔ میں حضرت براء بن عازب رضی اللہ عنہ کے پاس آیا اور ان سے پوچھا تو انھوں نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم ہمارے ہاں مدینہ منورہ تشریف لائے تو ہم اس قسم کی بیع کیا کرتے تھے۔ آپ نے فرمایا: ’’جو (خرید و فروخت) نقد ہو، اس میں کوئی حرج نہیں اور جو ادھار ہو، وہ سود ہے۔‘‘ پھر انھوں نے مجھے کہا: حضرت زید بن ارقم رضی اللہ عنہ سے جا کر پوچھو۔ میں ان کے پاس گیا اور پوچھا تو انھوں نے بھی اسی طرح فرمایا۔"}],[4576,"ابومنہال کہتے ہیں کہ میں نے براء بن عازب اور زید بن ارقم رضی اللہ عنہما سے پوچھا تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم دونوں تاجر تھے، ہم نے آپ سے بیع صرف (اثمان کی خرید و فروخت) کے بارے میں پوچھا، تو آپ نے فرمایا: \"اگر وہ نقدا نقد ہو تو کوئی حرج نہیں اور اگر ادھار ہو تو یہ صحیح نہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو منہال سے روایت ہے کہ میں نے حضرت براء بن عازب اور زید بن ارقم رضی اللہ عنہ سے یہ مسئلہ پوچھا تو انھوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں تجارت کیا کرتے تھے۔ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے سونے چاندی کے تبادلے کے بارے میں پوچھا تو آپ نے فرمایا: ’’اگر یہ تبادلہ نقد ہو تو کوئی حرج نہیں اور اگر ادھار ہو تو پھر یہ جائز نہیں۔‘‘","f2":"سونے چاندی کے تبادلے سے مراد سونا دے کر چاندی لینا اور چاندی دے کر سونا لینا ہے۔ دوسرے لفظوں میں دینار کے بدلے درہم لینا یا درہم کے بدلے دینار لینا ہے۔ اصل بات یہ ہے کہ سونے چاندی کے باہمی تناسب میں کمی بیشی ہوتی رہتی ہے اور بھاؤ بدلنے رہتے ہیں، اس لیے نقد تبادلہ تو جائز ہے مگر ادھار جائز نہیں کیونکہ ممکن ہے ادائیگی تک بھاؤ میں فرق پڑ جائے، پھر تنازع کا امکان پیدا ہو جائے گا۔"}],[4577,"ابومنہال کہتے ہیں کہ میں نے بیع صرف کے بارے میں براء بن عازب رضی اللہ عنہما سے پوچھا، تو انہوں نے کہا: زید بن ارقم رضی اللہ عنہ سے معلوم کر لو، وہ مجھ سے بہتر ہیں اور زیادہ جاننے والے ہیں۔ چنانچہ میں نے زید رضی اللہ عنہ سے پوچھا تو انہوں نے کہا: براء رضی اللہ عنہ سے معلوم کرو وہ مجھ سے بہتر ہیں اور زیادہ جاننے والے ہیں، تو ان دونوں نے کہا: \"رسول اللہ صلی اللہ علیہ وسلم نے سونے کے بدلے چاندی ادھار بیچنے سے روکا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو منہال نے فرمایا: میں نے حضرت براء بن عازب رضی اللہ عنہ سے سونے اور چاندی کے تبادلے کے بارے میں پوچھا تو وہ فرمانے لگے: حضرت زید بن ارقم رضی اللہ عنہ سے پوچھو۔ وہ مجھ سے بہتر اور زیادہ علم والے ہیں۔ میں نے حضرت زید رضی اللہ عنہ سے پوچھا۔ وہ فرمانے لگے: حضرت براء سے پوچھو۔ وہ مجھ سے بہتر اور زیادہ علم والے ہیں۔ پھر ان دونوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سونے چاندی کے ادھار تبادلے سے منع فرمایا ہے۔","f2":"(۱) اس حدیث مبارکہ سے معلوم ہوا کہ ایک صاحب علم کو فتویٰ دیتے وقت اپنے سے بڑے یا دیگر اصحاب العلم سے ضرور مشورہ کرنا چاہیے، نیز ان سے مدد لے اور تعاون حاصل کرے تاکہ بعد ازاں کسی قسم کی پریشانی لاحق نہ ہو جیسا کہ حضرت براء بن عازب رضی اللہ عنہ سے یہی مسئلہ پوچھنے کی تلقین فرمائی۔ اہل علم کی یہی شان ہوا کرتی ہے۔ (۲) ’’وہ مجھ سے بہتر ہیں۔‘‘ یہ صحابہ کرام رضی اللہ عنہم کی کسر نفسی اور تواضع ہے کہ دوسرے کو اپنے سے بہتر اور بڑا عالم خیال کرتے تھے۔ کاش! آج علماء وفضلاء اور اہل علم میں یہ عظیم جذبہ پیدا ہو جائے اور خودنمائی وخود پسندی کی بیماری سے ’’صحت یاب ہو جائیں۔‘‘ آمین! اہل علم کو یہی رویہ اپنانا چاہیے، اس میں برکت اور احترام ہے۔"}],[4578,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چاندی کے بدلے چاندی اور سونے کے بدلے سونا بیچنے سے منع فرمایا، مگر برابر برابر، اور ہمیں حکم دیا کہ چاندی کے بدلے سونا جیسے چاہیں خریدیں اور سونے کے بدلے چاندی جیسے چاہیں ۱؎۔\n§وضاحت\n۱؎: یعنی کمی و زیادتی کے ساتھ بشرطیکہ نقدا ہو ادھار نہ ہو۔","الألباني: صحيح",{"u2":"حضرت ابوبکر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چاندی چاندی کے بدلے اور سونا سونے کے بدلے لینے سے منع کیا ہے الا یہ کہ وہ (باہم) برابر ہوں، البتہ ہمیں اجازت دی کہ ہم چاندی کے بدلے سونا یا سونے کے بدلے چاندی جس طرح چاہیں، کم و بیش لے سکتے ہیں۔","f2":"ایسی بیع جس میں سونا چاندی کے بدلے یا سونا سونے کے بدلے خریدا بیچا جائے یا اس کے برعکس، یعنی چاندی سونے کے بدلے یا چاندی کے بدلے خریدی بیچی جائے، بیع الصرف کہلاتی ہے۔ اس میں نقد ادائیگی اور برابری ضروری ہے جبکہ مختلف اشیاء کے باہمی تبادلے میں برابری کی شرط نہیں، البتہ نقد ادائیگی، اس میں بھی ضروری ہے۔"}],[4579,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ ہم چاندی کے بدلے چاندی بیچیں مگر نقدا نقد اور برابر برابر، اور سونے کے بدلے سونا بیچیں مگر نقدا نقد اور برابر برابر، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چاندی کے بدلے سونا اور سونے کے بدلے چاندی جیسے چاہو بیچو\" ۱؎۔\n§وضاحت\n۱؎: یعنی کمی و زیادتی کے ساتھ بشرطیکہ نقداً ہو۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں چاندی کو چاندی کے عوض بیچنے سے منع فرمایا مگر جب وہ آپس میں برابر اور نقد ہو۔ اسی طرح سونے کو سونے کے عوض بیچنے سے منع فرمایا الکا یہ کہ وہ آپس میں برابر اور نقد ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سونے کو چاندی کے عوض جیسے چاہو (کم و بیش) خرید و بیچو اور چاندی کو سونے کے بدلے جیسے چاہو (کم و بیش) خرید و بیچو۔‘‘"}],[4580,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ مجھ سے اسامہ بن زید رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سود تو صرف ادھار میں ہے\"۱؎۔\n§وضاحت\n۱؎: یعنی: سونا سونے کے بدلے اور چاندی چاندی کے بدلے، یا اسی طرح ہم جنس غلہ جات کی نقداً خرید و فروخت میں اگر کمی بیشی ہو تو سود نہیں ہے، سود تو اسی وقت ہے جب معاملہ ادھار کا ہو، امام نووی نیز دیگر علماء کہتے ہیں کہ اہل اسلام کا اس بات پر اجماع ہے کہ اس حدیث کے ظاہر پر عمل نہیں ہے، کچھ لوگ اسے منسوخ کہتے ہیں اور کچھ تاویل کرتے ہیں کہ اس سے مراد یہ ہے کہ اجناس مختلفہ میں سود صرف ادھار کی صورت میں ہے، پچھلی حدیثوں میں صراحت ہے کہ تفاضل میں سود ہے، اس لیے حدیث کو منسوخ ماننا ضروری ہے، یا اسامہ رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم سے باہم مختلف اجناس کی خرید و فروخت کے بارے میں پوچھا تو آپ نے فرمایا کہ اس میں کوئی حرج نہیں اگر نقداً ہو، سود تو ادھار میں ہے۔ اس حدیث کو منسوخ ماننا، یا یہ تاویل اس لیے بھی ضروری ہے کہ ابن عباس رضی اللہ عنہما وغیرھم کو تفاضل والی حدیث پہنچ گئی تو انہوں نے اس حدیث کے مطابق فتوی دینے سے رجوع کر لیا :(کما حققہ العلماء )۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ مجھے حضرت اسامہ بن زید رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سود صرف ادھار میں ہے۔‘‘","f2":"یاد رہے یہ تب ہے جب دونوں طرف جنس مختلف ہو، مثلاً: سونا چاندی کے بدلے یا چاندی سونے کے بدلے ورنہ اگر جنس ایک ہو تو کمی بیشی بھی سود ہے جیسا کہ روایات میں صراحتاً ثابت ہے۔"}],[4581,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما سے کہا: آپ جو یہ باتیں کہتے ہیں، کیا آپ نے انہیں کتاب اللہ (قرآن) میں پایا ہے یا رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ تو انہوں نے کہا: نہ تو میں نے انہیں کتاب اللہ (قرآن) میں پایا ہے اور نہ ہی انہیں رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، لیکن اسامہ بن زید رضی اللہ عنہما نے مجھ سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سود تو صرف ادھار میں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو صالح سے روایت ہے کہ میں نے حضرت ابو سعید خدری رضی اللہ عنہ کو فرماتے سنا کہ میں نے حضرت ابن عباس رضی اللہ عنہ سے کہا: یہ جو آپ کہہ رہے ہیں کیا آپ نے اسے کتاب اللہ میں پایا ہے یا رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ انھوں نے فرمای: نہ میں نے یہ بات اللہ عزوجل کی کتاب میں پائی ہے نہ رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے بلکہ مجھے تو حضرت اسامہ بن زید رضی اللہ عنہ نے بتلایا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سود صرف ادھار میں ہے۔‘‘","f2":"(۱) چاندی کو سونے کے عوض یا سونے کو چاندی کے عوض خریدا بیچا جا سکتا ہے بشرطیکہ فریقین (دونوں) کی طرف سے نقد ادائیگی ہو۔ (۲) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ عالم دین کو، دینی مسئلے کی بابت دوسرے عالم دین سے دلیل کے ساتھ بات کرنی چاہیے اور ہر شخص کو یہ حق حاصل ہے کہ وہ عالم دین سے معلوم کرے کہ آپ نے جو مسئلہ بیان فرمایا ہے یہ قرآن مجید میں ہے یا حدیث رسول سے ثابت ہے (کیونکہ احکام شریعت کا اصل ماخذ قرآن وسنت ہے)۔ مزید برآں مسئول عنہ (جس سے ایسا سوال کیا جائے) کو اس قسم کے سوال، یعنی دلیل طلب کرنے کو اپنی ’’شان میں گستاخی‘‘ نہیں سمجھنا چاہیے بلکہ بلا تاخیر جواب دے دینا چاہیے جیسا کہ حضرت ابو سعید خدری رضی اللہ عنہ کے پوچھنے پر سیدنا عبداللہ بن عباس رضی اللہ عنہ نے فوراً جواب دیا کہ مجھے اسامہ بن زید رضی اللہ عنہ نے یہ خبر دی ہے۔ (۳) یہ حدیث مبارکہ اس بات کی طرف رہنمائی کرتی ہے کہ عالم دین کا فرض ہے کہ وہ اجتماعیت سے ہٹے ہوئے شخص کو اجتماعیت کی طرف لائے اور یہ فریضہ کتاب وسنت کے دلائل کے ذریعے سے سرانجام دیا جانا چاہیے۔ (۴) ’’یہ جو آپ کہہ رہے ہیں‘‘ دراصل حضرت ابن عباس رضی اللہ عنہ کو حضرت اسامہ بن زید رضی اللہ عنہ کی روایت سے یہ غلط فہمی ہوگئی تھی کہ سونے کو سونے کے بدلے اور چاندی کو چاندی کے بدلے کم و بیش بھی خریدا بیچا جا سکتا ہے، بشرطیکہ ادھار نہ ہو، حالانکہ یہ حدیث ایک مخصوص صورت کے بارے میں ہے، یعنی جب طرفین کی جنس مختلف ہو، مثلاً: چاندی سونے کے بدلے ہو جیسا کہ اس کی طرف اوپر والی حدیث(۴۵۸۴) میں اشارہ ہو چکا ہے۔ کسی ایک روایت سے ایسے معنی اخذ نہیں کیے جا سکتے جو دیگر صریح، مفصل اور کثیر روایات کے خلاف ہوں۔ بعض احادیث مختصر ہوتی ہیں۔ ان کے معنی سمجھنے کے لیے دیگر تفصیلی روایات کی طرف رجوع کرنا پڑتا ہے۔"}],[4582,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں بقیع میں اونٹ بیچتا، چنانچہ میں دینار سے بیچتا تھا اور درہم لیتا تھا، پھر میں ام المؤمنین حفصہ رضی اللہ عنہا کے گھر نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، تو میں نے عرض کیا: اللہ کے رسول! میں آپ سے کچھ معلوم کرنا چاہتا ہوں، میں بقیع میں اونٹ بیچتا ہوں تو دینار سے بیچتا اور درہم لیتا ہوں؟ آپ نے فرمایا: \"کوئی حرج نہیں، اگر تم اسی دن کے بھاؤ سے لے لو جب تک کہ جدا نہ ہو اور تمہارے درمیان ایک دوسرے کا کچھ باقی نہ ہو\"۔","الألباني: ضعيف",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں بقیع میں اونٹوں کا کاروبار کیا کرتا تھا۔ (کبھی) سودا دیناروں سے کرتا تو درہم وصول کر لیتا تھا۔ میں (اپنی بہن) حفصہ رضی اللہ عنہا کے گھر میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ میں نے کہا: اے اللہ کے رسول! میں آپ سے پوچھنا چاہتا ہوں کہ میں بقیع میں اونٹوں کا سودا کرتا ہوں۔ سودا دیناروں سے کرتا ہوں اور ان کی جگہ درہم وصول کرل یتا ہوں۔ آپ نے فرمایا: ’’اس دن کے بھاؤ کے مطابق ہو تو کوئی حرج نہیں، بشرطیکہ ایک دوسرے سے جدا ہوتے وقت کوئی لین دین باقی نہ ہو۔‘ـ‘","f2":"دینار سونے کا ہوتا تھا اور درہم چاندی کا۔ جب سونے اور چاندی کی بیع جائز ہے تو دینار کی جگہ اس کی قیمت کے مطابق درہم وصول کیے جا سکتے ہیں اور درہموں کی جگہ دینار وصول کیے جا سکتے ہیں۔ آج کل مختلف ممالک کی کرنسیوں کی یہی حیثیت ہے۔ سودا روپوں میں ہو تو ان کی جگہ روپوں کی قیمت کے مطابق ڈالر یا ریال یا پونڈ وصول کیے جا سکتے ہیں لیکن اسی وقت، بعد میں نہیں، کیونکہ کرنسی کی قیمت میں اتار چڑھاؤ رہتا ہے۔ جس کرنسی میں سودا طے ہوا ہے، وہ اصل ہوگی باقی کرنسیاں ادائیگی کے وقت کے لحاظ سے وصول کی جائیں گی۔"}],[4583,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں چاندی کے بدلے سونا یا سونے کے بدلے چاندی بیچتا تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میں نے آپ کو اس کی خبر دی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم اپنے ساتھی سے بیچو تو اس سے الگ نہ ہو جب تک تمہارے اور اس کے درمیان کوئی چیز باقی رہے (یعنی حساب بے باق کر کے الگ ہو)۔","الألباني: ضعيف",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں سونے کا چاندی کے ساتھ اور چاندی کا سونے کے ساتھ سودا کیا کرتا تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ کو یہ بات بتلائی تو آپ نے فرمایا: ’’جب تو اپنے ساتھی سے (اس قسم کا) سودا کرے تو اس سے ایسی حالت میں جدا نہ ہو کہ تیرے اور اس کے درمیان کوئی شبہات والی چیز باقی ہو۔‘‘","f2":"’’شبہات والی چیز باقی ہو۔‘‘ یعنی نقد ادائیگی ہونی چاہیے، ادھار نہ ہو جیسا کہ پیچھے تفصیل سے گزرا۔"}],[4584,"سعید بن جبیر سے روایت ہے کہ وہ اس چیز کو ناپسند کرتے تھے کہ وہ درہم ٹھیرا کر دینار اور دینار ٹھیرا کر درہم لیں ۱؎۔\n§وضاحت\n۱؎: سعید بن جبیر سے اسی سند سے نمبر ۴۵۹۲ پر جو روایت ہے وہی زیادہ صحیح ہے۔","الألباني: صحيح مقطوع",{"u2":"حضرت سعید بن جبیر کے بارے میں مروی ہے کہ وہ دراہم کی جگہ دینار اور دینار کی جگہ دراہم لینا پسند نہیں کرتے تھے۔","f2":"ان کے ناپسند کرنے کی کوئی معقول وجہ نہیں جب کہ نبی صلی اللہ علیہ وسلم سے صراحتاً اس کا جواز ثابت ہے۔ ہاں، قرض کی صورت میں ان کے قول کی معقول وجہ ہو سکتی ہے جیسا کہ آگے آرہا ہے۔"}],[4585,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ وہ اس میں کوئی حرج نہیں سمجھتے تھے یعنی دینار طے کر کے کر درہم لینے اور درہم طے کر کے کر دینار لینے میں۔","الألباني: صحيح موقوف",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ وہ دینار کی جگہ درہم اور درہم کی جگہ دینار لینے میں کوئی حرج نہیں سمجھتے تھے۔"}],[4586,"ابراہیم نخعی سے روایت ہے کہ درہم طے کر کے کر دینار لینے کو وہ ناپسند کرتے تھے جب وہ قرض کے طور پر ہوں۔","الألباني: صحيح مقطوع",{"u2":"حضرت ابراہیم نخعی درہم کی جگہ دینار لینے میں کوئی حرج نہیں سمجھتے تھے مگر جب وہ قرض کے ہوں۔","f2":"یہ اس لیے کہ قرض کی صورت میں امکان ہے کہ قرض خواہ قیمت کی صورت میں کچھ مفاد حاصل کرے گا اور جب قرض سے کوئی مفاد حاصل کیا جائے گا تو وہ سود بن جاتا ہے لیکن یہ صرف ایک امکان ہے۔ اس کی وجہ سے دراہم کی جگہ دینار لینے سے منع نہیں کیا جا سکتا بشرطیکہ کوئی مفاد حاصل نہ کیا جائے جیسا کہ آئندہ حدیث میں ذکر ہے۔"}],[4587,"سعید بن جبیر سے روایت ہے کہ وہ اس میں کوئی حرج نہیں سمجھتے تھے خواہ قرض کے طور پر ہو۔","الألباني: صحيح مقطوع",{"u2":"حضرت سعید بن جبیر سے منقول ہے کہ وہ (دراہم کی جگہ دینار اور دینار کی جگہ دراہم لینے میں کوئی حرج نہیں سمجھتے تھے اگرچہ وہ قرض کے ہی کیوں نہ ہوں۔"}],[4588,"اس سند سے بھی سعید بن جبیر سے اسی طرح مروی ہے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: میں نے اس مقام میں اسے اسی طرح پایا ۱؎۔\n§وضاحت\n۱؎: یعنی سعید کی پہلی روایت سے متضاد، اس سے گویا وہ ضعف کی طرف اشارہ کرنا چاہتے ہیں۔","الألباني: صحيح مقطوع",{"u2":"حضرت سعید بن جبیر سے اسی قسم کا قول منقول ہے۔\nابو عبدالرحمن (امام نسائی رحمہ اللہ) بیان کرتے ہیں کہ اس جگہ میں نے ایسا ہی پایا ہے۔","f2":"التعلیقات السلفیہ میں ہے کہ شاید امام نسائی رحمہ اللہ اس قول کا ضعف ظاہر فرما رہے ہیں کیونکہ اس سے پہلے روایت نمبر ۴۵۸۸ میں تو گزرا ہے کہ وہ عا م حالات میں بھی دراہم کی جگہ دینار اور دینار کی جگہ دراہم لینا پسند نہیں فرماتے تھے چہ جائیکہ وہ قرض کی صورت میں یہ جائز قرار دیں۔ واللہ اعلم۔ صاحب ذخیرۃ العقبی فرماتے ہیں کہ یہ سند تین احادیث پہلے گزر چکی ہے۔ اس جگہ دینار اور دیناروں کی جگہ درہم لینا ناپسند کرتے تھے جبکہ اس روایت میں ہے کہ وہ اس میں کوئی حرج نہیں سمجھتے تھے اگرچہ وہ قرض ہی کے کیوں نہ ہوں۔ شارح فرماتے ہیں کہ وہ روایت جس میں اس طرح کرنے میں کوئی حرج نہیں سمجھا گیا، سابقہ روایت کی نسبت زیادہ راجح ہے۔ اس کی وجہ یہ ہے کہ یہ روایت، امام سفیان ثوری رحمہ اللہ کی بیان کردہ روایت کے موافق ہے جس میں عدم کراہت کا بیان ہے۔ واللہ اعلم! دیکھیے: (ذخیرۃ العقبی، شرح سنن النسائی للاتیوبی: ۳۵/ ۲۰)"}],[4589,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر عرض کیا: ٹھہریے! میں آپ سے کچھ پوچھنا چاہتا ہوں؟ میں بقیع میں دینار کے بدلے اونٹ بیچتا ہوں اور درہم لیتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اسی دن کے بھاؤ سے لو تو کوئی حرج نہیں جب تک کہ تم ایک دوسرے سے الگ نہ ہو اور تمہارے درمیان ایک دوسرے پر کچھ باقی ہو\"۔","الألباني: ضعيف",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی کہ ذرا سنیے! میں پوچھنا چاہتا ہوں کہ میں مقام بقیع میں دیناروں کے ساتھ اونٹ کی قیمت طے کرتا ہوں، پھر میں دیناروں کی بجائے دراہم لے لیتا ہوں۔ (کیا یہ جائز ہے؟) آپ نے فرمایا: ’’تو اس دن کے بھاؤ کے حساب سے لے لے تو کوئی حرج نہیں بشرطیکہ جدا ہوتے وقت تمہارا آپس میں کچھ لین دین باقی نہ ہو۔‘ـ‘","f2":"مزید تفصیل کے لیے دیکھیے، حدیث: ۴۵۸۶ کا فائدہ۔"}],[4590,"جابر رضی اللہ عنہ کہتے ہیں کہ جب نبی اکرم صلی اللہ علیہ وسلم مدینہ آئے تو آپ نے ترازو منگا کر اس سے مجھے تول کر دیا اور مجھے اس سے کچھ زیادہ دیا ۱؎۔\n§وضاحت\n۱؎: اگر بغیر شرط کے خریداری :(یا قرض دار ) اپنی طرف سے قیمت میں زیادہ کر دے تو اس کو علماء نے مستحب قرار دیا ہے، اور اس کو خفیہ صدقہ سے تعبیر کیا ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ جب نبی اکرم صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے تو آپ نے ترازو منگوایا۔ مجھے (اونٹ کی قیمت) تول کر دی اور کچھ زیادہ دی۔","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم نے حضرت جابر رضی اللہ عنہ سے دوران سفر میں ایک اونٹ خریدا تھا۔ قیمت چالیس درہم طے پائی تھی۔ ادائیگی مدینہ منورہ آکر کی گئی۔ (۲) ’’ترازو منگوایا‘‘ اس دور میں عرب میں درہم اور دینار کے سکے موجود تھے لیکن بہت کم بلکہ عام سونے، چاندی سے سودے ہوتے تھے اور تول کر سونا چاندی دیتے تھے۔ (۳) ’’زیادہ دی‘‘ کسی کو اس کے حق سے کچھ زائد دینا اچھی اور مستحب بات ہے، خواہ وہ قرض ہی ہو۔ سود تب بنتا ہے جب زیادہ کی شرط ہو یا قرض خواہ اس کا مطالبہ کرے یا کم از کم خواہش رکھے۔ اگر مقروض اپنی خوشی سے اس کے قرض کے علاوہ اس سے زیادہ بھی دے دے تو یہ اچھی بات ہے کیونکہ پورا پورا دینے میں تول کی کمی بھی ممکن ہے، اس لیے زیادہ دے تاکہ کمی کا احتمال نہ رہے۔ تولتے وقت زیادہ دینا اعلیٰ ظرفی ہے۔"}],[4591,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا قرض دیا اور مجھے مزید دیا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے قیمت ادا کی اور زائد بھی دیا۔"}],[4592,"سوید بن قیس رضی اللہ عنہ کہتے ہیں کہ میں اور مخرفہ عبدی رضی اللہ عنہ مقام ہجر سے کپڑا لائے، ہم منی میں تھے کہ ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم آ گئے، وہاں ایک تولنے والا تھا جو اجرت پر تول رہا تھا، تو آپ نے ہم سے پاجامہ خریدا اور تولنے والے سے فرمایا: \"جھکتا ہوا تولو\"۔","الألباني: صحيح",{"u2":"حضرت سوید بن قیس رضی اللہ عنہ بیان کرتے ہیں کہ میں اور مخرمہ عبدی علاقہ ہجر سے (بیچنے کے لیے) کپڑے لائے۔ رسول اللہ صلی اللہ علیہ وسلم مقام منیٰ میں ہمارے پاس تشریف لائے اور ایک تولنے والا اجرت پر تول رہا تھا۔ آپ نے ہم سے ایک شلوار خریدی، پھر تولنے والے سے فرمایا: ’’(قیمت) تول اور جھکا کر دے۔‘‘","f2":"(۱) سودا دیتے وقت کچھ نہ کچھ زیادہ دینا چاہیے، یعنی تولتے وقت ترازو جھکتا ہونا چاہیے۔ باہمی خیر خواہی، ہمدردی اور اسلامی بھائی چارے کا تقاضا یہی ہے چہ جائیکہ ڈنڈی ماری جائے، یہ حرام ہے۔ اس طرح برکت اٹھ جاتی ہے۔ اَعَاذَنَا اللّٰہُ مِنْہُ۔ (۲) حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ کپڑے کی تجارت شرعاً جائز ہے اور یہ حلال روزی کمانے کا بہترین ذریعہ بھی ہے، نیز دوسرے ممالک سے مال منگوانے کی مشروعیت پر بھی دلالت کرتی ہے، یعنی درآمد و برآمد کا کاروبار، شرعاً درست ہے۔ (۳) یہ حدیث مبارکہ جس طرح جھکتا تول کر دینے کے استحباب پر دلالت کرتی ہے بعینہٖ اسی طرح کم تول کر دینے کی کراہت اور اس کے غیر مشروع ہونے پر بھی دلالت کرتی ہے کیونکہ اس طرح انسان کی حق تلفی ہوتی ہے جو کبیرہ گناہ ہے۔ (۴) ’’اجرت پر تول رہا تھا۔‘‘ یعنی قیمت میں سونا چاندی تول رہا تھا اور وہ تولنے کے پیسے لیتا تھا۔ اس سے خریدار کو ادائیگی کی سہولت ہوتی تھی کیونکہ قیمت کا تول خریدار کے ذمہ ہوتا ہے جبکہ سامانِ فروخت کا تول بیچنے والے کے ذمے۔ یہ معنی بھی ہو سکتے ہیں کہ تولنے والا قیمت تول تول کر لے رہا تھا۔ اس صورت میں بیچنے والوں نے اسے مقرر کیا ہوگا۔ (۵) ’’شلوار خریدی‘‘ ظاہر ہے پہننے کے لیے خریدی ہوگی، تاہم یہ بھی ممکن ہے کہ گھر کے کسی اور فرد کے لیے خریدی ہو۔ آپ سے شلوار کی تعریف ثابت ہے کہ یہ پردے والا لباس ہے۔ (۶) ’’جھکا کر دے‘‘ تاکہ کمی کا احتمال نہ رہے۔ اور یہ حکم وزن کے علاوہ ماپ اور پیمائش میں بھی لاگو ہوتا ہے۔ دینے والے کو چاہیے کہ ان میں بھی کچھ زائد ہی دے۔"}],[4593,"ابوصفوان رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے ہجرت سے قبل پاجامے بیچے تو آپ نے میرے لیے جھکتی ہوئی تول تولی۔","الألباني: صحيح",{"u2":"حضرت ابوصفوان رضی اللہ عنہ بیان کرتے ہیں کہ میں نے ہجرت سے پہلے رسول اللہ صلی اللہ علیہ وسلم کو ایک شلوار بیچی۔ آپ نے مجھے قیمت تولتے وقت جھکا کر (زیادہ) دی۔"}],[4594,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" «مکیال» (ناپنے کا آلہ) مدینے والوں کا معتبر ہے اور وزن اہل مکہ کا معتبر ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ماپ مدینے والوں کے مطابق ہونا چاہیے اور وزن مکے والوں کے مطابق۔‘‘\nیہ الفاظ اسحاق کے ہیں۔","f2":"(۱) اس روایت میں امام نسائی رحمہ اللہ کے دو استاد ہیں: ایک اسحاق بن ابراہیم اور دوسرے محمد بن اسماعیل۔ روایت کے مذکورہ الفاظ استاد اسحاق (بن راہویہ) کے ہیں۔ دوسرے استاد محمد بن اسماعیل (ابن علیہ) کے بیان کردہ الفاظ ان سے قدرے مختلف ہیں۔ (۲) عرب میں باقاعدہ حکومت نہیں تھی کہ ایک ہی وزن اور ایک ہی ماپ رائج ہو بلکہ مختلف وزن اور ماپ رائج تھے۔ شریعت میں زکاۃ، عشر، کفارات و دیگر ضروریات کے احکام نازل ہوئے تو وزن اور ماپ معین کرنا ضروری تھا۔ رسول اللہ صلی اللہ علیہ وسلم ایک منظم حکومت بھی وجود میں لا چکے تھے، لہٰذا انتظامی لحاظ سے بھی وزن اور ماپ کے پیمانے معین کرنا ضروری تھے، اس لیے آپ نے وزن مکے والوں کا اور ماپ مدینے والوں کا سرکاری اور شڑعی طور پر معین فرما دیا۔ اس دور میں وزن عموماً سونے چاندی اور دیگر دھاتوں کا ہوتا تھا۔ غلے میں ماپ رائج تھا۔ مدینہ منورہ کے لوگ زمیندار تھے۔ وہاں غلہ وافر ہوتا تھا، اس لیے آپ نے ماپ، یعنی مد، صاع اور وسق وغیرہ مدینہ منورہ کے رائج فرمائے۔ مکے والوں کے ہاں دس درہم سات دینار کے وزن کے برابر ہوتے تھے اور دینار ساڑھے چار ماشے کا ہوتا تھا۔ اب زکاۃ ودیت وغیرہ میں یہی وزن معتبر ہوگا۔ اور عشر وصدقۃ الفطر اور کفارات میں مدینے والوں کا مد وصاع معتبر ہوگا۔ مدینے والوں کا صاع معتبر ہوگا۔ مدینے والوں کا صاع چار مد کا ہوتا تھا۔ وزن میں یہ ۳/۵۱ رطل کے برابر تھا۔ مد اور صاع برتن تھے جن میں وہ غلہ اور کھجوریں ڈال کر ماپا کرتے تھے۔ آج کل غلے اور کھجوروں کا وزن کیا جاتا ہے، اس لیے مد اور صاع کے وزن میں اختلاف ہو گیا ہے۔ ویسے بھی ایک ہی برتن میں ڈالی جانے والی اشیاء کا وزن ایک نہیں ہو سکتا بلکہ ہر ایک کا وزن الگ الگ ہوگا، مثلاً: پانی، دودھ، پارہ، شربت، کھجور، گندم، چینی وغیرہ اپنا الگ الگ وزن رکھتے ہیں۔ درہم، دینار اور مد وصاع بعد میں بھی بدلتے رہے ہیں۔ مختلف حکومتوں نے اپنے اپنے حساب سے کمی بیشی کی مگر شریعت میں آپ کے دور کے درہم، دینار اور مد و صاع ہی وزن اور ماپ میں معتبر ہوں گے، مثلاً: کوفی صاع مدینے کے صاع سے بڑا تھا، لیکن صدقۃ الفطر وغیرہ میں مدینے کا صاع ہی چلے گا۔"}],[4595,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے غلہ خریدا تو وہ اسے اس وقت تک نہ بیچے جب تک اسے مکمل طور پر اپنی تحویل میں نہ لے لے\" ۱؎۔\n§وضاحت\n۱؎: خرید و فروخت میں شریعت اسلامیہ کا بنیادی اصول یہ ہے کہ خریدی ہوئی چیز کو خریدار جب تک بیچنے والے سے مکمل طور پر اپنی تحویل میں نہ لے لے دوسرے سے نہ بیچے، اور یہ تحویل و تملک اور قبضہ ہر چیز پر اسی چیز کے حساب سے ہو گا، نیز اس سلسلے میں ہر علاقہ کے عرف :(رسم رواج ) کا اعتبار بھی ہو گا کہ وہاں کس چیز پر کیسے قبضہ مانا جاتا ہے، البتہ منقولہ چیزوں کے سلسلے میں شریعت نے ایک عام اصول برائے مکمل قبضہ یہ بتایا ہے کہ اس چیز کو بیچنے والے کی جگہ سے خریدار اپنی جگہ میں منتقل کر لے، یا ناپنے والی چیز کو ناپ لے اور تولنے والی چیز کو تول لے، اور اندازہ والی چیز کی جگہ بدل لے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی غلہ (غذائی جنس) خریدے، وہ کسی کو فروخت نہ کرے حتی کہ اسے (پورا پورا) اپنے قبضے میں لے لے۔‘‘","f2":"(۱) جب کوئی شخص غذائی اجناس خریدے تو اسے اس وقت تک آگے نہیں بیچ سکتا جب تک وہ اسے مکمل طور پر اپنے قبضے میں نہ لے لے۔ اگر وہ مکیل چیز ہے تو اس کا ماپ پورا کرے اور اگر وہ موزون ہے تو اس کا وزن پورا کر لے۔ اگر ماپے تو لے اور قبضے میں لیے بغیر ہی بیچے گا تو شرعاً یہ کام ناجائز اور احرام ہوگا۔ باب کے تحت درج تمام احادیث اس مسئلے کی پوری پوری وضاحت کر رہی ہیں جبکہ ہمارے ہاں آج کل یہ وبا عام ہے کہ تاجر لوگ عموماً سودے پر سودا کیے جاتے ہیں جبکہ اصل چیز (مبیع) ایک ہی جگہ کسی سٹور وغیرہ میں پڑی رہتی ہے، کوئی خریدار اسے دیکھتا ہے نہ اس کا وزن یا کیل (ماپ تول) ہی معلوم کرتا ہے بلکہ اسے آگے سے آگے فروخت کیا جاتا ہے، اس طرح وہ اپنے پیسوں ہی پر نفع پہ نفع لیے جاتے ہیں، چيز کو دیکھنے تک کی زحمت گوارا نہیں کرتے اور نہ انھیں یہ معلوم ہوتا ہے کہ مبیع چیز درست حالت میں ہے یا خراب ہو چکی ہے؟ غرض کسی کو کچھ علم نہیں ہوتا لیکن چیز آگے بک رہی ہوتی ہے بالآخر اس کا نتیجہ یہ نکلتا ہے کہ آخری خریدار کو نقصان ہوتا ہے اور یہی چیز باہمی جھگڑے فساد کا باعث بنتی ہے۔ شریعت مطہرہ کا حکم بالکل واضح اور دو ٹوک ہے کہ جب کوئی شخص غذائی جنس، یعنی غلہ وغیرہ خریدے تو اسے چاہیے کہ اس چیز کو وہاں سے اٹھا کر اپنے قبضے میں کر لے، اور کسی دوسری جگہ اسے فروخت کر دے۔ (۲) اس حدیث میں یہ حکم صرف غلے کے بارے میں ہے۔ امام نسائی کا ذہن بھی یہی معلوم ہوتا ہے۔ امام مالک رحمہ اللہ کا مسلک بھی یہی ہے کہ فروخت کے لیے قبضے کی شرط صرف غلے میں ہے۔ امام شافعی رحمہ اللہ ہر چیز میں فروخت سے پہلے قبضہ ضروری خیال کرتے ہیں۔ امام ابوحنیفہ اور امام احمد رحمہ اللہ زمین ومکان کے علاوہ تمام اشیاء میں اس حکم کو رائج فرماتے ہیں۔ گویا انھوں نے منقولہ وغیرہ منقول اشیاء میں فرق کیا ہے کہ منقولہ میں قبضہ ضروری ہے۔ باقی رہی جائیداد غیر منقولہ تو اس کو کون سا اٹھایا یا منتقل کیا جا سکتا ہے کہ اس پر قبضے کی قید ضروری ہو۔ (۳) بیچنے سے پہلے قبضے کی قید لگانے کا ایک مقصد تو یہ ہے کہ قبضے میں لینے سے مال کی جانچ پڑتال ہو جائے، اس کی اصل کیفیت معلوم ہو جائے، نیز خریدار چیز کے خریدنے کے بعد کچھ محنت بھی کرے، مثلاً: وہ غلہ وہاں سے اٹھا کر اپنی دکان میں لے جائے۔ اگر وہ ڈھیر تو لا نہیں گیا تھا تو اس کو تولے تاکہ یہ محنت اس منافع کا جواز بن سکے جو وہ بیچ کر حاصل کرے گا۔ اگر کسی نے کوئی چیز خرید کر اسی جگہ پڑی کی پڑی بیچ دی تو گویا اس نے پیسہ لگانے کے علاوہ کوئی اور کام نہیں کیا اور تھوڑا پیسہ لگا کر زیادہ پیسہ کمایا۔ یہ سود کے مشابہ ہے۔ کسی کو پیسہ دیا، پھر کچھ عرصے کے بعد زیادہ لے لیا۔ اسلام بلا محنت کمائی کو جوا اور سود قرار دیتا ہے۔ حلال کی کمائی وہی ہے جو محنت اور کام کے عوض ہو۔ رقم پر سود لینا، بانڈ خرید کر یا کسی اور طریقے سے (قرعہ اندازی کے ذریعے سے) انعام حاصل کرنا یہ سب حرام ہیں کیونکہ محنت سے خالی ہیں۔"}],[4596,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے غلہ خریدا تو اسے اس وقت تک نہ بیچے جب تک اس کو اپنی تحویل میں نہ لے لے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے غلہ خریدا وہ اسے نہ بیچے حتی کہ اپنے قبضے میں لے لے۔‘‘"}],[4597,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اناج خریدے تو اسے اس وقت تک نہ بیچے جب تک اسے ناپ نہ لے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص غلہ خرید لے، وہ اسے آگے نہ بیچے حتی کہ اسے تول لے۔‘‘","f2":"تولنا بھی قبضے میں لینے کی صورت ہے۔"}],[4598,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی طرح سے سنا، (اس سے پہلی والی روایت میں «حتى يقبضه» کے الفاظ ہیں)۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے فرمایا: میں نے نبی اکرم صلی اللہ علیہ وسلم سے سنا۔ باقی روایت اسی طرح ہے۔ (اس میں یہ ہے) حتی کہ اسے قبضے میں لے لے۔"}],[4599,"طاؤس کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما کو کہتے ہوئے سنا: ناپ تول کر لینے سے جس چیز کے پہلے بیچنے سے رسول اللہ صلی اللہ علیہ وسلم نے روکا وہ غلہ ہے۱؎۔\n§وضاحت\n۱؎: غلہ تو ہے ہی، غلہ کی طرح منتقل کی جانے والی، ناپنے اور تولے جانے والی دیگر چیزوں کے بارے میں بھی یہی حکم ہو گا، جیسا کہ خود ابن عباس رضی اللہ عنہما کا خیال ہے، دیکھئیے اگلی روایت۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ جس چیز سے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا وہ یہ ہے کہ غلہ قبضے میں لینے سے پہلے بیچا جائے۔"}],[4600,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی گیہوں خریدے تو اسے نہ بیچے جب تک اس کو اپنی تحویل میں نہ لے لے\"۔ ابن عباس رضی اللہ عنہما کہتے ہیں: میرا خیال ہے کہ ہر چیز گیہوں ہی کی طرح ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص غلہ خریدے، وہ اسے فروخت نہ کرے حتی کہ اسے قبضے میں لے۔‘‘ حضرت ابن عباس رضی اللہ عنہ نے فرمایا: میرا خیال ہے کہ ہر چیز کا حکم غلے کی طرح ہے۔","f2":"حضرت ابن عباس رضی اللہ عنہ کا یہ خیال صحیح ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے ایک روایت میں عموم کے الفاظ آتے ہیں کہ تو کوئی چیز بھی نہ بیچ حتی کہ اسے قبضے میں لے۔ سنن ابوداود میں حضرت زید بن ثابت رضی اللہ عنہ سے مروی حدیث میں ہے: [اِنَّ رَسُولَ اللّٰہِ نَھٰی اَنْ تُبَاعَ السِّلَعُ حَیْثُ تُبْتَاعُ حَتّٰی یَحُوزَھَا التُّجَّارُ اِلٰی رِحَالِھِمْ] ’’بلا شبہ رسول اللہ صلی اللہ علیہ وسلم نے خریدنے کی جگہ ہی پر مال کو بیچنے سے منع فرمایا ہے حتی کہ تاجر اسے اپنی منزل (دو کانوں اور سٹوروں وغیرہ) پر لے جائیں۔‘‘ (سنن ابی داود، البیوع، حدیث: ۳۴۹۹) یہ حدیث مبارکہ حضرت عبداللہ بن عباس رضی اللہ عنہ کے تفقہ فی الدین کی بڑی واضح اور صریح دلیل ہے۔"}],[4601,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اناج (غلہ) مت بیچو جب تک اسے خرید نہ لو اور ناپ نہ لو\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی غلہ نہ بیچ حتی کہ تو اسے خرید کر قبضے میں کر لے۔‘‘"}],[4602,"اس سند سے بھی حکیم بن حزام رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے یہ حدیث روایت کی ہے۔","الألباني: صحيح",{"u2":"ایک اور طریق سے حضرت حکیم بن حزام رضی اللہ عنہ ہی نبی اکرم صلی اللہ علیہ وسلم سے ایسی ہی حدیث بیان فرماتے ہیں۔"}],[4603,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ میں نے صدقے کے اناج میں سے خریدا تو اسے اپنی تحویل میں لینے سے پہلے ہی مجھے اس میں نفع ملا، میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر آپ سے اس کا ذکر کیا، تو آپ نے فرمایا: \"جب تک تحویل میں نہ لے لو اسے مت بیچو\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ بیان کرتے ہیں کہ میں صدقے کے غلے میں سے کچھ غلہ خریدا۔ قبضے میں لینے سے پہلے ہی مجھے اس میں منافع ملنے لگا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور آپ سے یہ بات عرض کی۔ آپ نے فرمایا: ’’قبضے میں لینے سے پہلے نہ بیچ۔‘‘"}],[4604,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا کہ کوئی ناپ کر خریدا ہوا اناج بیچے جب تک کہ اسے پورا پورا اپنی تحویل میں نہ لے لے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا کہ کوئی شخص ماپ کر خریدے ہوئے غلے کو قبضے میں لینے سے پہلے بیچے۔","f2":"’’ ماپ کر خریدے ہوئے غلے‘‘ کیونکہ پہلی دفعہ تو بیچنے والے نے تولا ہوگا جیسا کہ عرف ہے۔ اب خریدار بھی اسے ماپ لے۔ اس باب کا مقصد یہ ہے کہ بیچنے والے کے ماپنے کو کافی نہیں سمجھنا چاہیے، بلکہ خود بھی ماپنا چاہیے تاکہ اعتماد سے آگے بیچ سکے۔ حدیث میں باب کا یہ مقصد نہیں کہ اگر غلہ بغیر ماپے خریدا گیا ہو تو اسے قبضے میں لیے بغیر بیچنا جائز ہے۔ یہ اس لیے کہ دیگر روایات میں قبضے کی شرط عام ہے۔"}],[4605,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اناج خریدتے تھے، پھر آپ ایک شخص کو ہمارے پاس بھیجتے جو ہمیں حکم دیتا کہ اسے اس جگہ سے کسی دوسری جگہ منتقل کر لے جہاں سے ہم نے خریدا ہے قبل اس کے کہ ہم اسے فروخت کریں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے مبارک زمانے میں ہم غلہ خریدتے تھے تو آپ ہمارے پاس اس شخص کو بھیجتے تھے جو ہمیں حکم دیتا تھا کہ اسے آگے بیچنے سے پہلے اس جگہ سے کسی اور جگہ منتقل کیا جائے جہاں پر خریدا گیا تھا۔","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم نے اس طرح بیع کرنے سے منع فرمایا ہے بلکہ اس مقصد کے لیے آپ نے آدمی بھی متعین کیے تھے جو لوگوں کو خریدی ہوئی چیز پہلی جگہ سے منتقل کیے بغیر فروخت کرنے سے روکتے تھے۔ (۲) اس حدیث سے یہ مسئلہ بھی معلوم ہوتا ہے کہ کسی چیز کے ڈھیر کی اندازاً بیع جائز ہے، خواہ اس کے درست وزن یا مقدار کا علم نہ بھی ہو، تاہم یہ ضروری ہے کہ اس میں نہ تو ملاوٹ ہو اور نہ کوئی اور خرابی ہی ہو۔ (۳) یہ حدیث مبارکہ اس مسئلے پر بھی دلالت کرتی ہے کہ فساد اور حرام بیوع کرنے والوں کی اصلاح اور اس ضمن میں ان کی تادیب ضروری ہے جیسا کہ حدیث: ۴۶۱۲ میں ہے کہ اس قسم کی خرید و فروخت کرنے والوں کی پٹائی کی جاتی تھی۔ اور یہ رسول اللہ صلی اللہ علیہ وسلم کے زریں دور کی بات ہے۔ (۴) ’’کسی اور جگہ منتقل کیا جائے۔‘‘ تاکہ قبضہ محقق ہو جائے، نیز کچھ محنت بھی ہو جائے تاکہ منافع حاصل کرنے کا جواز بن سکے۔ (مزید دیکھیے حدیث: ۴۵۹۹۔ فائدہ۲)"}],[4606,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں بازار کی اونچی جگہ پر ڈھیر خریدا کرتے تھے تو آپ نے انہیں اسے اسی جگہ بیچنے سے روکا جب تک کہ وہ اسے منتقل نہ کر لیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے دور میں بازار کے آخر میں غلہ بغیر ماپے خریدا کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کو اسی جگہ بیچنے سے منع فرما دیا حتی کہ اسے منتقل کر لیں۔"}],[4607,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں لوگ سواروں سے اناج (غلہ) خریدتے تھے تو آپ نے انہیں اسی جگہ بیچنے سے روکا جہاں انہوں نے اسے خریدا تھا، یہاں تک کہ وہ اسے غلہ منڈی منتقل کر لیں۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں لوگ تجارتی قافلوں سے غلہ کریدتے تھے۔ آپ نے انھیں منع فرمایا کہ اسی جگہ اسے فروخت کریں جہاں وہ خریدا گیا تھا کہ وہ اسے غلہ منڈی میں منتقل کر لیں۔"}],[4608,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کی پٹائی اس بات پر ہوتی تھی کہ جب وہ اناج اندازہ لگا کر خریدیں تو اسے گھر تک لانے سے پہلے ہی فروخت کر دیں۔","الألباني: صحيح",{"u2":"حضرت سالم کے والد محترم (حضرت عبداللہ بن عمر رضی اللہ عنہ) نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے مبارک دور میں دیکھا کہ جو لوگ ماپے بغیر غلہ خرید کر وہیں بیچ یتے تھے، ان کو (سرکاری عمال کی طرف سے) سزا دی جاتی تھی حتی کہ وہ اسے اپنی دکانوں پر لے جائیں۔"}],[4609,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے کچھ مدت تک کے لیے ادھار اناج خریدا اور اس کے پاس اپنی زرہ رہن رکھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے غلہ ادھار خریدا اور اپنی زرہ اس کے پاس گروی رکھی۔","f2":"ضمانت کے طور پر جو چیز حق دار کے پاس رکھی جائے کہ جب قیمت ادا کروں گا، مجھے میری چیز واپس مل جائے گی، اسے گروی رکھنا کہا جاتا ہے۔ جائز مقصد کے لیے کوئی چیز گروی رکھنے میں کوئی خرابی یا قباحت نہیں، لہٰذا شرعاً یہ جائز ہے۔ حالت اقامت ہو یا سفر۔ قرآن میں مید سفر کی قید اتفاقی ہے، البتہ گروی رکھی ہوئی چیز سے فائدہ اٹھانا ناجائز ہے، ورنہ یہ سود بن جائے گا۔ الا یہ کہ گروی رکھی ہوئی چیز پر خرچ کرنا پڑتا ہو تو خرچ کر کے فائدہ اٹھایا جا سکتا ہے، مثلاً جانور گروی رکھا گیا ہو تو اسے گھاس اور چارہ وغیرہ ڈال کر اس پر سواری کر سکتا ہے اور بس۔ زیادہ فائدہ اٹھائے تو رقم میں کمی کرے، مثلاً: زمین گروی رکھی ہے تو اس کا کرایہ قرض سے منہا کرنا ضروری ہے، ورنہ یہ سود بن جائے گا۔ بہتر ہے ایسی چیز گروی رکھے جس پر خرچ کرنے کی ضرورت نہ ہو، جیسے زیور وغیرہ تاکہ وہ فائدہ نہ اٹھا سکے۔"}],[4610,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جو کی ایک روٹی اور بودار چربی لے گئے، اور آپ نے اپنی زرہ مدینے کے ایک یہودی کے پاس گروی رکھ دی تھی اور اپنے گھر والوں کے لیے اس سے جَو لیے تھے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جوکی روٹی اور باسی چربی لے کر گئے۔ آپ کی حالت یہ تھی کہ آپ نے مدینہ منورہ میں ایک یہودی کے پاس اپنی زرہ گروی رکھی ہوئی تھی کیونکہ آپ نے اپنے گھر والوں کے لیے اس سے کچھ جو لیے تھے۔","f2":"1)مذکورہ حدیث میں مقررہ مدت تک چیز ادھار لینے کے عوض گروی چیز کی مشروعیت کا بیان ہے، یعنی کوئی چیز گروی میں دینا جائز ہے۔ لیکن اس میں یہ شرط ہے کہ اگر گروی رکھی ہوئی چیز پر کسی قسم کو خرچہ نہیں آرہا تو اس سے فائدہ اٹھانا درست نہیں بلکہ اس کی حیثیت امانت کی سی ہوگی جب ادھار چکا دیا جائے گا، چیز اصل مالک کو، اصلی حالت میں واپس ہو جائے گی۔2) کافروں کے ساتھ معاملات اور خرید و فروخت کرنا (جبکہ وہ حربی نہ ہوں) جائز ہے بشر طیکہ وہ اصل چیز جس کا معاملہ کیا جا رہا ہے، شرعاََ نا جائز اور حرام نہ ہو، نیز معاملہ کرنے میں کسی قسم کے شر فساد کا خطرہ بھی نہ ہو بالخصوص میل جول کے نتیجے میں اسلامی عقیدے پر قطعاََ کوئی زدنہ پڑتی ہو، ورنہ ہر قسم کا معاملہ کرنا حرام اور نائزہ ہو گا۔ یہی حکم ذمیوں کے ساتھ معاملات کرنے کا ہے۔ اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ ذمیوں کے مام ان کے ہاتھ معاملات کرنے کا ہے۔3) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ ذمیوں کے مال ان کے ہاتھ اور قبضے میں ہونے چاہئیں، یعنی اسلامی حکومت میں ان کے حق ملکیت کو تسلیم کیا جائے گا۔ 4)ادھار کا لین دین اور خرید و فروخت جائز ہے۔ شرعاََ اس میں کوئی قباحت نہیں بشر طیکہ دینی تقاضے مجروح نہ کیے جائیں۔5) جنگی ہتھیار اپنے پاس رکھنا اور ان کی اعلیٰ پیمانے تیاری بالکل درست عمل ہے۔ یہ تو کل علی اللہ کے منافی نہیں، جیسے جدید ترین میزائل، ایٹم بم اور دیگر آلات حرب کی تیاری۔6) یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کو تواضع، زہد اور آپ کی ازواج مطہرات رضی اللہ عنہم کی فضیلت پر دلالت کرتی ہے کہ انھوں نے عظمت و عریمت کی راہ اختیار کی اور ہر قسم کی مشکلات پر صبر و شکر کیا آپ صلی اللہ علیہ وسلم کا ساتھ خوب خوب نبھایا۔7) یہ زرہ رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد حضرت ابو بکر رضی اللہ عنہ نے غلتے کی قیمت دے کر یہودی سے واپس لی۔8) حضرت انس رضی اللہ عنہ کا مقصد رسول اللہ صلی اللہ علیہ وسلم کی سادگی اور تنگ حالی بیان کرنا ہے مگر یہ تنگ حالی آپ نے خود اپنے آپ پر طاری کر رکھی تھی تا کہ آپ اپنے رب کے لیے صبر و شکر کر سکیں۔ آپ اور آپ کے اہل خانہ باوجود سال بھر کا غلہ رکھنے کے اس کو فقراء و مساکین پر سخاوت کر دیتے تھے اور خود تنگی و ترشی سے گزارا کیا کرتے تھے۔ 9)’’باسی چربی‘‘ یعنی وہ پرانی چربی تھیْ اس کا ذائقہ یا بو کچھ حد تک بدل چکی تھی۔ یہ نہین کہ اس سے بدبو آتی تھی کیونکہ ایسی چیز استعمال کرنا تو شرعاََ بھی معنی ہے طبی طور پر بھی۔ فطرت سلیمہ اس سے نفرت کرتی ہے۔ اور رسول اللہ صلی اللہ علیہ وسلم تو انتہائی نفیس اور پاکیزہ شخصیت تھے۔ 10)باب کا مقصد ایک غلط فہمی کا ازالہ کرنا ہے کہ شاید گروں کے جواز کے لیے سفر میں ہونا شرط ہے لیکن اس حدیث سے معلوم ہو گیا کہ گروی کے لیے سفر شرط نہیں۔"}],[4611,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ادھار اور بیع ایک ساتھ جائز نہیں ۱؎، اور نہ ہی ایک بیع میں دو شرطیں درست ہیں ۲؎، اور نہ اس چیز کی بیع درست ہے جو سرے سے تمہارے پاس ہو ہی نہ\" ۳؎۔\n§وضاحت\n۱؎: اس کی صورت یہ ہے کہ بیچنے والا خریدار کے ہاتھ آٹھ سو کا سامان ایک ہزار روپے کے بدلے اس شرط پر بیچے کہ بیچنے والا خریدار کو ایک ہزار روپے بطور قرض دے گا :(دیکھئیے باب رقم ۷۰ ) گویا بیع کی اگر یہ شکل نہ ہوتی تو بیچنے والا خریدار کو قرض نہ دیتا اور اگر قرض کا وجود نہ ہوتا تو خریدار یہ سامان نہ خریدتا۔ ۲؎: مثلاً کوئی کہے کہ یہ غلام میں نے تجھ سے ایک ہزار نقد اور دو ہزار ادھار میں بیچا :(دیکھئیے باب رقم ۷۲ ) یہ ایسی بیع ہے جو دو شرطں ہیں یا مثلاً کوئی یوں کہے کہ میں نے تم سے اپنا یہ کپڑا اتنے اتنے میں اس شرط پر بیچا کہ اس کا دھلوانا اور سلوانا میرے ذمہ ہے۔ ۳؎: بیچنے والے کے پاس جو چیز موجود نہیں ہے اسے بیچنے سے اس لیے روک دیا گیا ہے کہ اس میں دھوکہ دھڑی کا خطرہ ہے جیسے کوئی شخص اپنے بھاگے ہوئے غلام یا اونٹ بیچے جب کہ ان دونوں کے واپسی کی ضمانت بیچنے والا نہیں دے سکتا البتہ ایسی چیز کی بیع جو اپنی صفت کے اعتبار سے خریدار کے لیے بالکل واضح ہو جائز ہے کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے بیع سلم کی اجازت دی ہے باوجود یہ کہ بیچی جانے والی چیز بیچنے والے کے پاس بروقت موجود نہیں ہوتی۔ :(کیونکہ چیز کے سامنے آنے کے بعد اختلاف اور جھگڑا پیدا ہو سکتا ہے )۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبد اللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک دوسرے سے مشروط) قرض اور بیع جائز نہیں۔ اور بیع میں دو شرطیں جائز نہیں اور جو چیز تیرے پاس نہیں، اس کی بیع بھی جائز نہیں۔‘‘","f2":"1) ایسی چیز جو فروخت کرنے والے پاس نہ ہو اس کا فروخت کرنا شرعاََ نا جائز اور حرام ہے۔ ہمارے ہاں اکثر دکاندار حضرات، اپنی ’’گاہکی‘‘ پکی کرنے کے لیے اس قسم کی قبیح حرکات کا ارتکاب عام طور پر کرتے رہتے ہیں، حالانکہ شریعتِ مطہرہ نے اس قسم کے ’’تعاون‘‘ کو نائز قرار دیا ہے۔ بعض دکاندار اس سے بھی ایک قدم آگے چلے جاتے ہیں۔ وہ اس طرح کہ جو چیز ان کے پاس نہیں ہوتی آنے والے سے اس کی قیمت لے لیتے ہیں اور چند دن بعد چیز لا دینے کا وعدہ کر لیتے ہیں۔ یہ پہلی صورت سے بھی زیادہ خطر ناک صورت ہے، اس لیے کہ یہ معلوم ہی نہیں کہ مطلوبہ چیز ملے گی یا نہیں؟ اگر ملے گی تو گاہک کو پسند آئے گی یا نہیں؟ یہ بھی معلوم نہیں۔ پسند آ جانے کی صورت میں قیمت کی کمی بیشی کا معاملہ کھڑا ہو سکتا ہے۔ بنا بریں شریعت مطہرہ کی ہدایات کے مطابق ایسی ہر بیع سے بچنا چاہیے جو شر فساد کا ذریعہ بن سکتی ہو۔ 2(یہ حدیث مبارکہ ایسی بیع سے روکتی ہے جو قرض لینے یا دینے کی شرط پر کی جائے، نیز یہ حدیث مبارکہ ایسی بیع کو بھی حرام ٹھہراتی ہے جسے دو شرطوں کے ساتھ معلق کر دیا جائے۔ 3(’’قرض اور بیع‘‘ اس کا مطلب یہ ہے کہ قرض بیع کی شرط پر ہو۔ اور وہ اس طرح کہ ایک شخص دوسرے سے کہے میں تجھے تب قرض دوں گا کہ یو مجھ سے فلاں چیز اتنے کی خریدے۔ یا بیع قرض شرط پر ہو، اور وہ اس طرح کہ ایک شخص دوسرے سے کہے کہ میں تجھ سے فلاں چیز خریدتا ہوں اس شرط پر کہ تو مجھے قرض دے۔ ان صورتوں میں چونکہ قرض سے مفاد حاصل کیا جا رہا ہے اور یہ سود ہے، اس لیے ان صورتوں سے منع فرما دیا گیا۔4(’’بیع میں دو شرطیں‘‘ اس کی صورت یہ ہے کہ ایک شخص دوسرے سے کہے: میں تجھے فلاں چیزا نقد دس روپے میں اور ادھار بارہ روپے میں دیتا ہوں اور معاملہ کسی ایک شرط پر طے نہ ہو تو یہ سود ہے، البتہ کسی ایک شرط پر معاملہ طر ہو جائے، مثلا: گاہک ادھار بارہ روپے میں لے جائے یا نقد دس روپے میں لے جائے تو کوئی حرج نہیں کیونکہ اب ایک شرط رہ گئی، دو نہ رہیں۔ نقد اور ادھار بھاؤ میں فرق فطری ہے جیسے تھوک اور پر چون بھاؤ میں فرق، لہٰذا اس میں کوئی حرج نہیں، نیز یکمشت ادائیگی اور قسطوں والی ادائیگی میں فرق بھی اسی طرح ہے۔ 5(’’جو چیز تیرے پاس نہیں‘‘ مثلاََ: غلام بھاگ گیا ہے تو اس کو پکڑنے سے پہلے اسے بیچا نہیں جا سکتا۔ اسی طرح کسی کی چیز بھی نہیں بیچی جا سکتی۔ اسی طرح غلہ وغیرہ قبضے میں لینے سے پہلے بیچنا منع ہے، البتہ اگر کوئی چیز بذات خود معین نہ ہو بلکہ اس کی صفات معین کر لی جائیں تو چیز موجود نہ ہونے کے باوجود اس کی بیع ہو سکتی ہے، مثلاََ کسی سے کہا جائے کہ میں گندم کی کٹائی کے موقع پر تجھ سے فلاں قسم کی بیس من گندم اتنے بھاؤ سے لوں گا اور رقم بھی اسے ادا کر دے، خواہ اس کے پاس گندم یا گندم کا کھیت موجود نہ ہو بلکہ خواہ اس کے پاس سرے سے زمین ہی نہ ہو کیونکہ وہ بازار سے گندم خرید کر مہیا کر سکتا ہے، البتہ اگر کہا جائے کہ فلاں کھیت کی گندم خریدتا ہوں جبکہ اس کھیت میں گندم ابھی پکی نہ ہو یا اس کھیت میں گندم بیجی ہی نہ گئی ہو تو یہ بیع درست نہیں کیونکہ یقین سے نہیں کہا جا سکتا کہ اس کھیت سے گندم پیدا ہو گی۔ اگر پیدا ہو گی کیسی پیدا ہو گی؟ ابہام والی بیع درست نہیں، جیسے اڑتے میعن پرندے کی بیع یا پانی میں تیرتی معین مچھلی کی بیع درست نہیں۔ ابہام کے علاوہ ان میں ’’پاس نہ ہونے والی‘‘ خرابی بھی ہے۔"}],[4612,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس چیز کا بیچنا آدمی کے لیے جائز نہیں جس کا وہ مالک نہ ہو\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا متحرم (حضرت عبد اللہ بن عمر رضی اللہ عنہ) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آدمی جس چیز کا مالک نہیں، اس کی بیع نہیں کر سکتا۔‘‘","f2":"کسی کی چیز کوئی اور شخص نہیں بیچ سکتا۔ اگر بیچے تو ایسی بیع نہیں ہو گی، چیز اصل مالک کی رہے گی، لہٰذا خریدار کو چاہیے کہ خریدنے سے پہلے یقین حاصل کرلیل کہ بیچنے والا شخص واقعتا مالک ہے، ورنہ خریدار کی رقم ضائع ہو سکتی ہے کیونکہ وہ چیز تو اصل مالک ہی کو ملے گی۔ خریدار کو بیچنے والے سے رقم واپس مل گئی تو مل گئی ورنہ ضائع ہے کیونکہ اصل مالک سے رقم کا مطالبہ نہیں کیا جا سکے گا۔"}],[4613,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے سوال کیا: اللہ کے رسول! میرے پاس آدمی آتا ہے اور وہ مجھ سے ایسی چیز خریدنا چاہتا ہے جو میرے پاس نہیں ہوتی۔ کیا میں اس سے اس چیز کو بیچ دوں اور پھر وہ چیز اسے بازار سے خرید کر دے دوں؟ آپ نے فرمایا: \"جو چیز تمہارے پاس نہ ہو اسے مت بیچو\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کے رسول! میرے پاس ایک آدمی آتا ہے اور مجھ سے ایسی چیز بیچنے کا مطالبہ کرتا ہے جو میرے پاس نہیں ہوتی۔ میں اس سے اس کا سودا کر لیتا ہوں، پھر میں اسے بازار سے خرید کر لا دیتا ہوں۔ آپ نے فرمایا: ’’جو چیز تیرے پاس نہیں، اس کا سودا نہ کر۔‘‘","f2":"’’سودا نہ کر‘‘ کیونکہ ممکن ہے وہ چیز تجھے بازار سے نہ ملے یا تیرے طے شدہ بھاؤ سے مہنگی ملے، پھر تنازع پیدا ہو سکتا ہے۔ ویسے اگر کسی معین چیز کا سودا نہ ہو بلکہ عام چیز جو بازار سے ملتی ہے اور خریدار کو علم ہو کہ یہ چیز اس کے پاس نہیں، بازار سے لا کر دے گا تو ان شاء اللہ اس کا سودا کرنے میں کوئی حرج نہیں جیسا کہ سابقہ حدیث میں وضاحت بیع سلم یا سلف کی بحث میں آئے گی۔"}],[4614,"عبداللہ بن ابی مجالد کہتے ہیں کہ میں نے ابن ابی اوفی سے بیع سلم کے متعلق پوچھا تو انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم، ابوبکر اور عمر رضی اللہ عنہما کے زمانے میں گی ہوں، جَو اور کھجور میں ایسے لوگوں سے بیع سلم کرتے تھے کہ مجھے نہیں معلوم، آیا ان کے یہاں یہ چیزیں ہوتی بھی تھیں یا نہیں۔ اور ابن ابزی نے(سوال کرنے پر) اسی طرح کہا۔\n§وضاحت\n۱؎: «سلف» یا «سلم» یہ ہے کہ خریدار بیچنے والے کو سامان کی قیمت پیشگی دے دے اور سامان کی ادائیگی کے لیے ایک میعاد مقرر کر لے، ساتھ ہی سامان کا وزن وصف اور نوعیت وغیرہ متعین ہو۔ :(اگلی حدیث دیکھیں )","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن ابو مجالد سے روایت ہے کہ میں حضرت ابن ابی اوفٰی رضی اللہ عنہ سے بیع سلف (یا سلم) کے بارے میں پوچھا تو انھوں نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم اور حضرت ابو بکر اور حضرت عمر رضی اللہ عنہ کے زمانے میں گندم، جو اور کھجور میں ایسے لوگوں کے ساتھ بیع سلف کیا کرتے تھے جن کے متعلق مجھے علم نہیں ہوتا تھا کہ ان کے پاس (غلہ یا زمین) ہے یا نہیں۔ حضرت ابن ابزٰی رضی اللہ عنہ نے بھی ایسے ہی فرمایا۔","f2":"(1)بیع سلم جائز ہے۔ رسول صلی اللہ علیہ وسلم،سیدنا ابوبکر اور سیدنا عمر فاروق رضی اللہ عنہما کے زریں دور میں بیع سلم ہو کرتی تھی۔ دیگر صحابہ کرام رضی اللہ عنہم بھی یہ بیع کیا کرتے تھے۔ (2)بیع کرتے وقت جو چیز موجو د ہی نہ ہو اس میں بیع سلم ہو سکتی ہے تاہم یہ ضروری ہے کہ ادائیگی کے وقت وہ چیز بہر صورت مو جو د ہو۔3)ذمی اوردیگر غیر مسلم لوگوں کے ساتھ جس طر ح عام تجارت اور خرید و فروخت کرنا جائز ہے، اسی طر ح ان کے ساتھ بیع سلم کرنا بھی درست ہے۔4) بیع سلم یاسلف ایک ہی چیز ہے کہ خریدار بائع کو رقم پہلے دےدے اور اس سے غلہ (جوکچھ خریدنا مقصود ہو) کی مقدار،جنس ونوع اور بھاو طے کرلے اورغلے کی ادائیگی کا وقت متعین کر لے،خواہ ابھی تک وہ غلہ منڈی میں نہ ا ٓیاہو یا بیچا بھی نہ گیا ہو۔ سال دوسال پہلے بھی رقم دی جاسکتی ہے۔ اس قسم کی بیع لو گو ں کی مجبوری ہے کیونکہ زمیندار کا شتکاروں کو فصل کے اخراجات کے لیے رقم کی پیشگی ضرورت ہوتی ہے، لہٰذا اس بیع کو جائز رکھا گیا۔ جو شخص جس سے سودا ہوا ہے، کاشتکار بھی ہو سکتا ہے غیرکاشتکار بھی کیو نکہ وہ خریدکر بھی مہیا کر سکتا ہے۔ اس مسئلے کی کچھ تفصیل حدیث نمبر 4615، فائدہ نمبر 5اور حدیث نمبر4617 میں بیان ہوچکی ہے۔"}],[4615,"جریر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام بھاگ جائے تو اس کی نماز قبول نہیں ہو گی یہاں تک کہ وہ اپنے مالک کے پاس لوٹ آئے\" ۱؎۔\n§وضاحت\n۱؎: اس کی نماز قبول نہیں ہو گی، یعنی اس کا اجر و ثواب نہیں ملے گا، البتہ دینا میں اس پر سے نماز کی فرضیت ساقط ہو جائے گی۔\nابن ابی مجالد بیان کرتے ہیں کہ ابوبردہ اور عبداللہ بن شداد میں سلم کے سلسلے میں بحث ہو گئی تو انہوں نے مجھے ابن ابی اوفی رضی اللہ عنہ کے پاس بھیجا، میں نے ان سے پوچھا تو انہوں نے کہا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اور ابوبکر و عمر رضی اللہ عنہما کے زمانے میں گیہوں، جَو، کشمش اور کھجور میں بیع سلم کیا کرتے تھے، ایسے لوگوں سے جن کے پاس ہم یہ چیزیں نہیں پاتے اور (ابن ابی المجالد کہتے ہیں کہ میں نے ابن ابزی سے پوچھا تو انہوں نے اسی طرح کہا۔","الألباني: صحيح",{"u2":"حضرت ابن ابی مجالد سے روایت ہے کہ حضرت ابو بردہ اور حضرت عبد اللہ بن شداد کا بیع سلم کی بابت اختلاف ہو گیا۔ انھوں نے مجھے حضرت ابن ابی اوفٰی رضی اللہ عنہ کے پاس بھیجا۔ میں نے ان سے پوچھا تو انھوں نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں حضرت ابو بکر اور حضرت عمر رضی اللہ عنہ کے زمانے میں گندم، جو، منقٰی اور کھجوروں میں ایسے لوگوں سے بیع سلم کیا کرتے تھے جن کے پاس ہمارے خیال کے مطابق یہ چیزیں نہیں ہوتی تھیں، پھر میں نے حضرت ابن ابزٰی رضی اللہ عنہ سے پوچھا تو انھوں نے بھی ایسا ہی فرمایا۔"}],[4616,"ابوالمنہال کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ آئے تو لوگ کھجور میں دو تین سال کے لیے بیع سلم کرتے تھے، آپ نے انہیں روک دیا، اور فرمایا: \"جو بیع سلم کرے تو مقررہ ناپ، مقررہ وزن میں مقررہ مدت تک کے لیے کرے\" ۱؎۔\n§وضاحت\n۱؎: ناپ وزن اور اس میں یہ تعیین و تحدید اس لیے ہے تاکہ جھگڑے اور اختلاف پیدا ہونے والی بات نہ رہ جائے، اگر مدت نہ معلوم ہو اور وزن اور ناپ نہ متعین ہو تو بیع سلف صحیح نہ ہو گی۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے اور وہ (لوگ) دو دو، تین تین سال کے لیے کھجوروں میں بیع سلف کیا کرتے تھے۔ آپ نے ان کو روک دیا فرمایا: ’’جو شخص بیع سلف کرے تو وہ معین ماپ یا معین وزن میں معین مدت تک کے لیے کرے۔‘‘","f2":"معین ماپ سے مراد غلے یا پھل کی مقدار ہے جس کی بیع کی جا رہی ہے۔ اور معین وزن سے مراد سونے چاندی کی مقدار ہے جو بطور قیمت دیا جا رہا ہے، یعنی بھاؤ کر کے مقرر کر لیا جائے۔ معین مدت سے مرادوہ وقت ہے جب غلے یا پھل کی ادائیگی طے ہوئی ہے۔ گویا ہر چیز واضح کر لی جائے۔ کسی چیز میں ابہام نہ رہے تا کہ تنازع کا امکان ختم ہو جائے اس صورت میں بیع سلم یا سلف جائز ہے، خواہ ایک سال سے زائد مدت کے لیے کی جائے۔"}],[4617,"ابورافع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے اونٹ کے بچے میں بیع سلم کی، وہ شخص اپنے نوجوان اونٹ کا تقاضا کرتا ہوا آیا تو آپ نے ایک شخص سے کہا: \"جاؤ، اس کے لیے نوجوان اونٹ خرید دو\"، اس نے آپ کے پاس آ کر کہا: مجھے تو سوائے بہترین، «رباعی» (جو ساتویں برس میں لگ چکا ہو) نوجوان اونٹ کے کوئی نہیں ملا، آپ نے فرمایا: \"اسے وہی دے دو، اس لیے کہ بہترین مسلمان وہ ہے جو قرض ادا کرنے میں بہتر ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابو رافع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی سے ایک جوان اونٹ قرض لیا۔ وہ شخص آپ سے اپنے اونٹ کی واپسی کا مطالبہ کرنے آیا۔ آپ نے ایک آدمی سے کہا: ’’جاؤ، اس کو ایک جوان اونٹ خرید دو۔‘‘ وہ واپس آ کر کہنے لگا: مجھے تو رباعی اونٹ مل رہا ہے جو اس کے اونٹ سے بہت بہتر ہے۔ آپ نے فرمایا: ’’یہی دے دو۔ بہترین مسلمان وہ ہے جو (قرض وغیرہ کی) ادائیگی میں اچھا ہو۔‘‘","f2":"1(اکثر اہل علم کے نزدیک جانور اور حیوان بطور قرض لیا جا سکتا ہے۔2(اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوا کہ قرض کی ادائیگی کے وقت بہتر اور اعلیٰ چیز دینا افضل اور احسن عمل ہے بشر طیکہ قرض حاصل کرنے کے موقع پر اس قسم کو کوئی شرط نہ لگائی گئی ہو۔ اگر قرض دینے والا اس قسم کی کوئی شرط لگائے گا تو یہ بالا تفاق حرام ہے۔ جمہور اہل علم کا یہی قول ہے۔3(یہ حدیث مبارکہ اس بات پر بھی صریح دلالت کرتی ہے کہ جب قرض کی ادائیگی کا وقت آ جائے تو قرض خواہ واپسی کا مطالبہ کر سکتا ہے، نیز یہ مسئلہ بھی ثابت ہوتا ہے کہ مقروض کو کسی قسم کے لیت و لعل اور ٹال مٹول سے کام نہیں لینا چاہیے بلکہ قرض کی بر وقت ادائیگی کو یقینی بنانے کی بھر پور کوشش کرنی چاہیے۔ 4(رسول اللہ صلی اللہ علیہ وسلم عام طور پر ضرورت مند محتاجوں اور سائلوں کی خاطر قرض لیا کرتے تھے۔ اس سے معلوم ہوتا ہے کہ نیکی اور اطاعت کے امور میں تعاون کی خاطر قرض اٹھانا جائز ہے، نیز تمام مباح امور کے لیے قرض لینا دینا درست ہے۔5(یہ حدیث مبارکہ اس مسئلے کے اثبات پر بھی دلالت کرتی ہے کہ امام وقت، یعنی مسلمانوں کا خلیفہ اور حکمران، محتاج رعایا اور ضرورت مند عوام کی خاطر قرض اٹھا سکتا ہے اور اس کی ادائیگی بیت المال میں جمع ہونے والے والی زکاۃ صدقات کی رقم سے ہوگی۔ اس سلسلے میں ضروری اور اہم بات یہ ہے کہ اس قسم کے قرض کی رقم صرف ضرورت مند لوگوں اور جائز امور پر چرچ ہونی چاہیے۔ ایسی رقم سے آج کے حکمران کو اللے تللے اور عیاشیاں کرتے ہیں یہ سراسر نائز اور حرام ہے۔ اس قسم کے قرض کی ادائیگی نہ تو بیت المال کے ذمے ہو گی اور نہ قومی خزانے کے ذمے، بلکہ عیاشی کرنے والے حکمرانوں ہی کی ذاتی رقم سے قرض ادا کرنا ضروری ہو گا۔ 6(قرض کی ادائیگی میں وکالت، یعنی کسی کو وکیل بنانا جائز سے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو فرمایا تھا کہ تو جا کر اس کا قرض ادا کر دے۔7(جانور قرض پر لیا جا سکتا ہے۔ وقت مقررہ پر اس جیسا جانور واپس کر دیا جائے جیسے کسی سے رقم ادھار یا قرض لے کر مقررہ وقت پر واپس کر دی جاتی ہے۔ جمہور اہل علم اسی کے قائل ہیں مگر امام ابو حنیفہ رحمہ اللہ کے نزدیک یہ جائز نہیں کیونکہ یہ قرض نہیں، بیع ہے۔ اور حیوان کی حیوان کے بدلے ادھار بیع درست نہیں جیسا کہ ایک صریح حدیث (۴۶۲۴) میں ہے۔ وہ اس حدیث کو منسوخ سمجھتے ہیں۔ لیکن یہ ایک حدیث نہیں، اس قسم کی کئی احادیث ہیں جن میں جانور قرض لینے اور بعد میں ادا کرنے کا ذکر ہے۔ دراصل شریعت لوگوں کی مجبوریوں کا بھی لحاظ رکھتی ہے۔ اگر کوئی اصول لوگوں کے لیے مشکل کا باعث بنے تو وہ اصول قابل لحاظ نہیں رہتا۔ بلی کے جوٹھے کو احناف بھی پاک کہتے ہیں، حالانکہ وہ حرام جانور ہے۔ پلید چوہے کھاتی ہے۔ اسی طرح اگر ضرورت پڑجائے تو جانور فرض پر لیا جا سکتا ہے اور وقت مقررہ پر اس جیسا جانور واپس کر دیا جائے، نیز یہ نہی والی روایت کا مفہوم بھی قطعی نہیں۔ امام شافعی رحمہ اللہ نے اس حدیث کا مطلب یہ بتایا کہ حیوان کی حیوان کے بدلے بیع اس وقت منع ہے جب ادھار دونوں طرف سے ہو۔ اگر ادھار ایک طرف سے ہو تو کوئی حرج نہیں۔ مذکورہ بالا صورت میں بھی ادھار ایک طرف سے ہی ہے۔"}],[4618,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے ذمہ ایک شخص کا ایک جوان اونٹ باقی تھا، وہ آپ کے پاس تقاضا کرتا ہوا آیا تو آپ نے (صحابہ سے)فرمایا: \"اسے دے دو\"، انہیں اس سے زیادہ عمر کے ہی اونٹ ملے تو آپ نے فرمایا: \"اسی کو دے دو\"، اس نے کہا: آپ نے پورا پورا ادا کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سب سے بہتر وہ ہے جو قرض کی ادائیگی میں بہتر ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہر یرہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم سے ایک خاص عمر کا اونٹ واپس لینا تھا۔ وہ لینے آیا تو آپ نے فرمایا: ’’اس کو دے دو۔‘‘ لوگوں نے تلاش کیا تو اس کے اونٹ سے بڑی عمر کا اونٹ ملا۔ آپ نے فرمایا: ’’یہی دے دو۔‘‘ اس نے (بطور تشکر) کہا: آپ نے مجھے زیادہ دے دیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے بہترین لوگ وہ ہیں جو (دوسروں کے حقوق کی) ادائیگی میں اچھے ہوں۔‘‘","f2":"’’خاص عمر کا اونٹ‘‘ اس نے آپ سے دو انتا اونٹ لینا تھا۔ آپ نے اسے رباعی اونٹ دیا جسے ہماری زبان میں ’’چوگا‘‘ کہتے ہیں جس کا رباعی دانت نیا نکلنے لگے۔ رباعی چھ سال کے اونٹ کو کہتے ہیں اور دو دانتا (جسے ہماری زبان میں ’’دوندا‘‘ کہتے ہیں) چار سال کے اونٹ کو۔ گویا آپ نے کافی بہتر اور قیمتی اونٹ نہیں بشر طیکہ کوئی ایسی شرط نہ لگائی گئی ہو۔ جانوروں میں عین برابری ممکن بھی نہیں۔ یہ نہیں ہو سکتا کہ جیسا جانور لیا گیا تھا، بالکل ویسا ہی جس میں بال برابر بھی فرق نہ ہو، دیا جائے، لہٰذا دینے والا بہتر دینے کی کوشش کرے۔ خوشی سے زائد یا بہتر دینے کو سود نہیں کہیں گے بلکہ یہ حسن خلق ہے۔"}],[4619,"عرباض بن ساریہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے ایک جوان اونٹ بیچا تو میں آپ کے پاس اس کا تقاضا کرنے آیا، آپ نے فرمایا:\"میں تو تمہیں بختی (عمدہ قسم کا اونٹ) دوں گا\"، پھر آپ نے مجھے ادا کیا تو بہت اچھا ادا کیا، اور آپ کے پاس ایک اعرابی (دیہاتی) اپنا جوان اونٹ مانگتے ہوئے آیا تو آپ نے فرمایا: \"اسے جوان اونٹ دے دو\"، تو اس دن ان لوگوں نے اسے ایک بڑا (مکمل) اونٹ دیا، اس نے کہا: یہ تو میرے اونٹ سے بہتر ہے، آپ نے فرمایا:\"تم میں بہتر وہ ہے جو بہتر طرح سے قرض ادا کرے\"۔","الألباني: صحيح",{"u2":"حضرت عرباض بن ساریہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک جوان اونٹ دیا تھا۔ میں اس کی ادائیگی کے سلسلے میں آپ کے پاس حاضر ہوا تو آپ نے فرمایا: ’’ہاں۔ ضرور میں تجھے اس کی جگہ ایک (بہترین) بختی اونٹنی دوں گا۔‘‘ پھر آپ نے مجھے وہ دی اور بہت اچھی دی۔ اسی طرح آپ کے پاس ایک اعرابی اپنا ایک خاص عمر کا اونٹ لینے آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس کو کوئی اونٹ دے دو۔‘‘ لوگوں نے اس کو پوری عمر کا اونٹ دے دیا۔ وہ اعرابی کہنے لگا: یہ تو میرے اونٹ سے بہت بہتر ہے۔ آپ نے فرمایا: ’’تم میں سے بہترین شخص وہ ہے جو ادائیگی میں بہترین ہے۔‘‘","f2":"’’بختی‘‘ یہ ایک اچھی قسم کے اونٹ ہوتے تھے۔ مقصد یہ تھا کہ تجھے تیرے اونٹ سے بہتر اور عمدہ اونٹنی دوں گا۔ اونٹنی کے لحاظ سے مذکر اونٹ کے برابر ہوتب بھی قیمتی شمار ہوتی ہے۔"}],[4620,"سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ذی روح کے بدلے ذی روح کو ادھار بیچنے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: یہ ممانعت اس صورت میں ہے جب ادھار کی صورت طرفین سے ہو اور اگر کسی ایک جانب سے ہو تو بیع جائز ہے :(دیکھئیے: صحیح بخاری کتاب البیوع باب ۱۰۸ )۔","الألباني: صحيح",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حیوان کے بدلے حیوان کی ادھار بیع سے منع فرمایا۔","f2":"پچھلے باب کی روایات حیوان قرض لینے کے بارے میں تھیں ادوہ جائز ہے۔ یہ باب اور یہ حدیث حیوان کی بیع کے بارے میں ہے۔ قرض تو ہوتا ہی ادھار ہے، البتہ بیع نقد بھی ہو سکتی ہے ادھار بھی۔ حیوان کی بیع حیوان کے ساتھ نقد تو درست ہے، خواہ کمی بیشی ہی ہو، مثلاََ: ایک طرف ایک جانور ہے اور دوسری طرف دو یا تین تو کوئی حرج نہیں جیسا کہ آئندہ باب میں صراحت ہے لیکن حیوان کی بیع حیوان کے بدلے میں ہو تو ادھار درست نہیں۔ جن لوگوں نے پچھلے باب کی حدیثوں میں بیان کردہ قرض کی صورت کو بیع قرار دیا ہے انھیں اس روایت کی تاویل کرنا پڑے گی جیسا کہ امام شافع رحمہ اللہ نے فرمایا ہے کہ حیوان کی بیع حیوان کے بدلے اس وقت منع ہے جب دونوں طرف ادھار ہو جیسا کہ میں ہوتا ہے۔ اگر ادھار ایک طرف ہو تو بیع جائز ہے۔ اس تاویل سے پچھلے باب کی روایات اس حدیث کے خلاف نہیں ر ہیں گی لیکن صحیح یہ ہے کہ ادھار بیع تو ہر صورت میں منع ہے۔ ادھار ایک طرف ہو یا دونوںطرف، البتہ حیوان کا قرض جائز ہے۔ گویا بیع اور قرض کے حکم میں فرق ہے۔ اس طریقے سے نہ تو حدیث کی تاویل کرنی پڑے گی اور نہ سابقہ احادیث کا انکار۔ اور یہی طریقہ صحیح ہے۔ بیع اور قرض میں فرق صرف حیوان کے مسئلے ہی میں نہیں دیگر اشیاء میں بھی جاری و ساری ہے۔"}],[4621,"جابر رضی اللہ عنہ کہتے ہیں کہ ایک غلام آیا تو اس نے رسول اللہ صلی اللہ علیہ وسلم سے ہجرت پر بیعت کی، آپ کو یہ علم نہیں تھا کہ یہ غلام ہے، اتنے میں اسے ڈھونڈتا ہوا اس کا مالک آ پہنچا تو آپ نے فرمایا: \"اسے میرے ہاتھ بیچ دو\"، چنانچہ آپ نے اسے دو کالے غلاموں کے بدلے خرید لیا، پھر آپ نے اس کے بعد کسی سے بیعت نہیں لی جب تک کہ اس سے پوچھ نہ لیتے کہ وہ غلام ہے؟۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک غلام آیا اور اس نے رسول اللہ صلی اللہ علیہ وسلم سے ہجرت پر بیعت کی۔ نبی اکرم صلی اللہ علیہ وسلم کو یہ علم نہیں تھا کہ وہ غلام ہے۔ اتنے میں اس کا مالک اسے لینے آ گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’یہ مجھے بیچ دے۔‘‘ آپ نے دو کالے غلام دے کر اسے خرید لیا۔ اس کے بعد آپ نے کسی سے بیعت نہیں لی حتی کہ پوچھ لیتے کہ وہ غلام تو نہیں۔","f2":"1- یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کے مکارم اخلاق اور آپ کے احسان عظیم پر واضح دلالت کرتی ہے۔ یہی وجہ ہے کہ آپ نے غلام واپس نہ کیا، حالانکہ اس کا مالک پہنچ گیا۔ آپ نے غلام کا مقصد، یعنی ارادئہ ہجرت پورا فرما دیا۔ اسے اپنی رفاقت میں رہنے سے محروم نہ کیا اور دو غلاموں کے بدلے اسے خرید لیا۔2- اس حدیث سے یہ مسئلہ بھی معلوم ہوا کہ ایک غلام کی دو غلاموں کے عوض بیع (خرید و فروخت) جائز ہے، خواہ ان کی قیمت ایک جیسی ہو یا مختلف۔ اس بات پر اہل علم کا اجماع ہے لیکن شرط یہ ہے کہ بیع نقد ہو۔ دونوں طرف سے ادھار نہ ہو۔ تمام حیوانات کا یہی حکم ہے، چاہے ایک غلام دو غلاموں کے عوض ہو یا ایک اونٹ دو کے بدلے۔3- اس حدیث مبارکہ سے یہ بھی ثابت ہوتا ہے کہ انسانوں میں اصل حریت اور آزادی ہی ہے، یہی وجہ ہے کہ آنے والے غلام سے رسول اللہ صلی اللہ علیہ وسلم نے اس کے آزاد یا غلام ہونے کی بابت نہیں پوچھا بلکہ مذکورہ اصول کے مطابق بیعت فرمالی۔4- یہ حدیث مبارکہ اس اہم مسئلے کی بھی صریح دلیل ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس علمِ غیب ہر گز نہیں تھا۔ اگر آپ کو غیب کا علم ہوتا تو فورََا معلوم ہو جاتا کہ آنے والا شخص غلام ہے، نیز یہ بھی ضرور معلوم ہو جاتا کہ اس کا مالک بھی اس کے پیچھے پیچھے آ رہا ہے۔ مزید آں یہ بھی کہ آپ آئندہ بھی بیعت کے لیے آنے والے کسی شخص سے نہ پوچھتے کہ تو آزاد ہے یا غلام؟ رسول اللہ صلی اللہ علیہ وسلم کو صرف اس بات کا علم ہوتا جو آپ کو اللہ تعالیٰ بتا دیتا تھا۔5- معلوم ہوا حیوانات کی باہمی خریداری اور تبادلے میں کمی بیشی جائز ہے کیونکہ حیوانات کی حیثیت میں بسا اوقات فرق ہوتا ہے، گویا وہ الگ الگ جنس ہیں اور جب جنسیں مختلف ہوں تو کمی بیشی جائز ہوتی ہے۔ ایک اونٹ پندرہ ہزار کامل سکتا ہے تو ایک اونٹ کئی لاکھ کا بھی ملتا ہے، لہٰذا جانوروں کو یوں سمجھا گیا جیسے وہ الگ الگ جنس کے ہوں۔ شریعت اپنے احکام میں لوگوں کی مجبوریوں کا بھی لحاظ رکھتی ہے، خواہ کوئی فرعی اصول بدلنا پڑے، عدم حرج بنیادی اصول ہے۔"}],[4622,"عبداللہ بن عباس رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حمل والے جانور کے حمل کی بیع سلم کرنا سود ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم فرمایا: ’’حمل کے حمل کی بیع سلف سود ہے۔‘‘","f2":"اس قسم کی بیوع جاہلیت میں عام تھیں۔ ایک آدمی کے پاس حاملہ اونٹنی ہوتی۔ کوئی اس سے سودا کرتا کہ اس اونٹنی کے پیٹ میں جو حمل ہے، وہ پیدا ہونے کے بعد، پھر جوان ہونے کے بعد وہ حاملہ ہو کر بچہ جنے گی، اس بچے کی اتنی قیمت میں تجھے ابھی دیتا ہوں۔ وہ بچہ میرا ہو گا۔ یہ ہے ’’حمل کے حمل کی بیع سلف‘‘ یہ نا جائز ہے کیونکہ یہ معلوم نہیں موجودہ حمل مئونث ہی ہے؟ وہ صحیح پیدا ہو گا یا عیب دار؟ وہ اپنے حمل تک زندہ رہے گی؟ پھر حاملہ ہو گی؟ اور پھر بچہ جن سکے گی؟ جب ان میں سے کوئی بات بھی معلوم نہیں تو سودا کس چیز کا؟ اسے دھو کے اور غرر کی بیع بھی کہتے ہیں، نیز وہ بیچنے والے کے پاس موجود بھی نہیں۔ گویا یہ کئی لحاظ سے منع ہے۔ اس بیع کا ایک مفہوم یہ بھی ہو سکتا ہے کہ کوئی چیز فروخت کی جائے اور قیمت کی ادائیگی کے لیے حمل کے حمل کی پیدائش کو وقت مقرر کر لیا جائے یا رقم پہلے دے دی جائے اور چیز فروخت کی جائے قیمت حمل کے حمل پیدائش کو قرار دیا جائے۔ یہ سب صورتیں منع ہیں کیونکہ یہ مجہول مدت ہے۔ پتا نہیں؟ اور آئے گی تو کب؟ ادائیگی کی مدت واضح اور معلوم ہونی چاہیے، مثلاََ: تاریخ، مہینہ یا سال گندم کٹائی یا سردیوں کا آغاز وغیرہ ہے۔"}],[4623,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے حاملہ کے حمل کو بیچنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے حمل کے حمل کی بیع سے منع فرمایا ہے۔"}],[4624,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بیع مخابرہ اور مزابنہ، محاقلہ سے اور ان پھلوں کو بیچنے سے منع فرمایا ہے جو ابھی کھانے کے قابل نہ ہوئے ہوں، سوائے بیع عرایا کے ۱؎۔ یونس بن عبید نے اس کی متابعت کی ہے۔\n§وضاحت\n۱؎: مخابرہ: زمین کو آدھی یا تہائی یا چوتھائی پیداوار پر بٹائی پر دینا، کہتے ہیں: مخابرہ \" خیبر \" سے ماخوذ ہے، یعنی خیبر کی زمینوں کے ساتھ جو معاملہ کیا گیا اس کو \" مخابرہ \" کہتے ہیں۔ حالانکہ خیبر میں جو معاملہ کیا گیا وہ جائز ہے، اسی لیے تو وہ معاملہ کیا گیا، مؤلف نے حدیث نمبر ۳۹۱۴ میں مخابرہ کی تعریف یہ کی ہے کہ \" انگور جو ابھی بیلوں میں ہو کو اس انگور کے بدلے بیچنا جس کو توڑ لیا گیا ہو، یہی سب سے مناسب تعریف ہے جو \" مزابنہ \" اور \" محاقلہ \" سے مناسبت رکھتی ہے۔ مزابنہ: درخت پر لگے ہوئے پھل کو توڑے ہوئے پھل کے بدلے معینہ مقدار سے بیچنے کو مزابنہ کہتے ہیں۔ محاقلہ: کھیت میں لگی ہوئی فصل کا اندازہ کر کے اسے غلّہ سے بیچنا۔ عرایا: عرایا یہ ہے کہ مالک کا باغ ایک یا دو درخت کے پھل کسی مسکین و غریب کو کھانے کے لیے مفت دیدے، اور اس کے آنے جانے سے تکلیف ہو تو مالک اس درخت کے پھلوں کا اندازہ کر کے مسکین و فقیر سے خرید لے اور اس کے بدلے تر یا خشک پھل اس کے حوالے کر دے۔\nانس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ان لوگوں کی آنکھیں پھوڑ دیں کیونکہ ان لوگوں نے چرواہوں کی آنکھیں پھوڑ دی تھیں۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے حاملہ کے حمل کو بیچنے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎: یہ بیع زمانہ جاہلیت میں رائج تھی، آدمی اس شرط پر اونٹ خریدتا تھا کہ جب اونٹنی بچہ جنے گی پھر بچے کا بچہ ہو گا تب وہ اس اونٹ کے پیسے دے گا تو ایسی خرید و فروخت سے روک دیا گیا ہے، کیونکہ اس میں دھوکہ ہے، یہ بیع غرر :(دھوکہ والی بیع ) کی قبیل سے ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے حمل کے حمل کی بیع سے منع فرمایا ہے۔","f2":"حدیث:۴۶۲۶ کے فائدے میں اس کے مفہوم کی بابت تفصیلی کلام ہو چکا ہے، تا ہم اس جگہ ایک اہم مسئلے کی طرف اشارہ کرنا مقصود ہے، وہ یہ کہ کسی مجہول یا مبہم مدت کو ادھار کی ادائیگی کی مدت ہر گزنہ ٹھہرایا جائے بلکہ ادھار کی ادائیگی کی مدت کا بالکل واضح تعین ہونا چاہیے۔ اس کے باوجود بھی اگر مقروض شخص وقت مقرارہ پر ادائیگی نہ کر سکے تو مزید مہلت مانگ لے۔ اور قرض خواہ کو بھی چاہیے کہ آسانی تک مہلت دے دے کیونکہ یہ بہت افضل عمل ہے۔ اس کی افضیلت کا اندازہ رسول اللہ صلی اللہ علیہ وسلم کی اس حدیث مبارکہ سے لگائیں جس میں آپ نے فرمایا ہے: ’’جو شخص کسی کو قرض دے اسے روزانہ اپنے قرض کے برابر صدقہ کرنے کا اجرو ثواب ملتا ہے۔ اور پھر جو شخص مقررہ وقت پر بھی قرض کی ادائیگی نہ کر سکے اور قرض خواہ مقروض کو مزید مہلت دے دے تو اسے روزانہ اپنے دیے ہوئے قرض کی نسبت دگنا مال صدقہ کرنے کا اجرو ثواب ملتا ہے۔‘‘ دیکھیے لیکن اس صورت میں مقروض کو سہولت سے نائز فائدہ اٹھاتے ہوئے ادائیگی قرض سے بے فکر بے بیاز نہیں ہونا چاہیے بلکہ اسے جلد از جلد قرض ادا کرنے کی کوشش چاہیے اور اپنے محسن، یعنی قرض خواہ کے لیے پر خلوص دعائیں کرتے رہنا چاہیے۔"}],[4625,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حاملہ کے حمل کی بیع سے منع فرمایا اور یہ ایسی بیع تھی جو جاہلیت کے لوگ کیا کرتے تھے، ایک شخص اونٹ خریدتا اور پیسے دینے کا وعدہ اس وقت تک کے لیے کرتا جب وہ اونٹنی جنے اور پھر اس کا بچہ جنے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (حمل کے حمل) کی بیع سے منع فرمایا اور یہ ایک قسم کی بیع تھی جو جاہلیت والے آپس میں کرتے تھے۔ کوئی آدمی اونٹنی خریدتا کہ اس کی قیمت اس وقت دوں گا جب یہ اونٹنی (مادہ) بچہ جنے اور پھر اس کے پھر اس کے پیٹ والی اونٹنی (بڑی ہو کر) بچہ جنے۔","f2":"حضرت عبد اللہ ابن عمر رضی اللہ عنہ کی بیان کردہ تفسیر سے واضح طور پر معلوم ہو رہا ہے کہ ادائیگی کی مدت مجہول ہے۔ مزید بر آں یہ معلوم ہی نہیں کہ اونٹنی مئونث جنے گی یا مذکر؟ مادہ بچہ جننے کی صورت میں پھر یہ معلوم نہیں کہ وہ مئونث بڑی بھی ہو گی یا نہیں؟ اگر بڑی ہو گئی تو آگے حاملہ ہو گی یا نہیں؟ پھر نہ معلوم بچہ ہو گا یا نہ ہو گا؟ (تفصیل حدیث نمبر ۴۶۲۶ میں گزر چکی ہے) لہٰذا یہ بیع منع ہے۔"}],[4626,"جابر رضی اللہ عنہ کہتے ہیں کہ بعض لوگوں کے پاس ضرورت سے زائد زمینیں تھیں جنہیں وہ آدھا، تہائی اور چوتھائی پر اٹھاتے تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی کوئی زمین ہو تو اس میں کھیتی کرے یا اس میں (بلا کرایہ لیے) کھیتی کرائے یا بلا کھیتی کرائے روکے رکھے\"۔ مطر بن طہمان نے اوزاعی کی موافقت(متابعت) کی ہے۔\nجابر رضی اللہ عنہما کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے خطاب فرمایا اور کہا: \"جس کی کوئی زمین ہو تو اس میں کھیتی کرے یا کسی سے اس میں (بلا کرایہ لیے) کھیتی کرائے اور اسے کرائیے پر نہ دے\"۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ اور مزابنہ سے منع فرمایا۔ محمد بن عمرو نے عمر بن ابی سلمہ اور یحیی دونوں کی مخالفت کی ہے، انہوں نے اسے ابوسلمہ سے اور ابوسلمہ نے ابو سعید خدری رضی اللہ عنہ سے روایت کیا ہے۔\nجابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کئی سال کی بیع کرنے سے منع فرمایا ہے۔\n§وضاحت\n۱؎: باغ کے پھل کئی سال کے لیے بیچنا، یہ بھی بیع غرر :(دھوکہ والی خرید و فروخت ) کی قبیل سے ہے، اس میں خریدار کے لیے دھوکہ ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کئی سال کے سودے سے منع فرمایا۔","f2":"کئی سال کا سودا اس لیے منع ہے کہ وہ چیز جس کا سودا کیا جا رہا ہے، موجود ہی نہیں۔ جب کسی معین چیز کا سودا کیا جارہا ہو، مثلاً: اس درخت یا اس باغ کا پھل تو پھل کا موجود ہونا ضروری ہے کیونکہ ہو سکتا ہے یہ درخت یا یہ باغ تباہ ہو جائے، پھر اس کا پھل کہاں سے آئے گا؟ البتہ اگر سودا غیر معین چیز کا ہو، مثلاً: ۲۰ من کھجور یا گندم وغیرہ تو سودا جائز ہے، خواہ ابھی گندم کاشت بھیہ نہ کی گئی ہو کیونکہ مجموعی طور پر دنیا یا منڈی سے کوئی چیز ناپید نہیں ہو سکتی، لہٰذا ایک کھیت سے نہ ہوئی تو دوسرے سے ہو جائے گی۔"}],[4627,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ اور مزابنہ سے منع فرمایا ہے۔ اسود بن علاء نے ان سب کی مخالفت کی ہے، اور حدیثوں روایت کی ہے: \"عن ابی سلمۃ عن رافع بن خدیج\"۔\nجابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کئی سال کی بیع کرنے سے منع فرمایا۔","الألباني: حسن صحيح الإسناد",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کئی سال تک کے لیے سودے سے منع فرمایا ہے۔"}],[4628,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس دو قطری چادریں تھیں، جب آپ بیٹھتے اور ان میں پسینہ آتا تو وہ بھاری ہو جاتیں، ایک یہودی کا شام سے کپڑا آیا تو میں نے عرض کیا: اگر آپ اس کے پاس کسی کو بھیج کر تاوقت سہولت (قیمت ادا کرنے کے وعدہ پر) دو کپڑے خرید لیتے تو بہتر ہوتا، چنانچہ آپ نے اس کے پاس ایک شخص کو بھیجا، اس (یہودی) نے کہا: مجھے معلوم ہے محمد کیا چاہتے ہیں، وہ تو میرا مال ہضم کرنا چاہتے ہیں، یا یہ دونوں چادروں کو ہضم کرنا چاہتے ہیں، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس نے جھوٹ کہا، اسے معلوم ہے کہ میں سب سے زیادہ اللہ سے ڈرنے والا ہوں اور سب سے زیادہ امانت کا ادا کرنے والا ہوں\" ۱؎۔\n§وضاحت\n۱؎: آپ صلی اللہ علیہ وسلم نے اس طرح کی بیع پر اعتراض نہیں کیا، بلکہ اس یہودی کے پاس اس کے لیے آدمی بھیجا، اسی سے باب پر استدلال ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے جسم مبارک پر قطر بستی کی نبی ہوئی دو موٹی چادریں تھیں۔ جب آپ بیٹھتے تو ان میں پسینہ آ جاتا جس سے وہ بوجھل ہو جاتیں۔ فلاں یہودی کے ہاں شام سے کپڑے آئے تو میں نے کہا: اگر آپ اس کو پیغام بھیج کر دو کپڑے ادھار خرید لیں کہ جب سہولت ہوگی تو رقم دے دوں گا (تو اچھی بات ہے)۔ آپ نے اسے پیغام بھیجا تو وہ کہنے لگا: میں جانتا ہوں (حضرت) محمد(صلی اللہ علیہ وسلم) کا کیا ارادہ ہے؟ وہ میری رقم دبانا چاہتے ہیں یا یہ چادریں مفت میں لینا چاہتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ جھوٹ بولتا ہے۔ اس کو دل میں یقین ہے کہ میں سب لوگوں سے بڑھ کر اللہ تعالیٰ سے ڈرنے والا اور سب سے بڑھ کر امانت ادا کرنے والا ہوں۔‘‘","f2":"1-معلوم ہوا معین مدت تک ادھار سودا لینا جائز ہے۔ اگر ایسا کرنا، جائز نہ ہوتا تو رسول اللہ صلی اللہ علیہ وسلم ہر گز یہ کام نہ کرتے اور وہ بھی خبیث الفطرت یہودی سے۔ 2-یہ حدیث مبارکہ نبی اکرم صلی اللہ علیہ وسلم کی سادگی اور آپ کی کسمپر سانہ گزارنے پر بھی دلالت کرتی ہے، حالانکہ اللہ تعالیٰ نے رسول اللہ صلی اللہ علیہ وسلم کو یہ اختیار دیا تھا کہ آپ چاہیں تو آپ کو بادشاہ نبی بنا دیا جائے اور اگر چاہیں تو ’’عبد‘‘ بنایا جائے۔ اس پیش کش کے باوجود رسول اللہ صلی اللہ علیہ وسلم نے عبد، یعنی اللہ کے درکا فقیر نبی بننے ہی کو ترجیح دی۔ یہ اس لیے کہ آپ کے لیے اللہ تعالیٰ کے ہاں، آخرت میں جو کچھ ہے وہ اس سے کہیں زیادہ بہتر اور باقی رہنے والا ہے۔ اسی باعث رسول اللہ صلی اللہ علیہ وسلم نے دنیوی مال و متاع اور بادشاہت کو ذرہ برابر حیثیت نہیں دی۔ 3-یہ حدیث اس بات کی واضح دلیل ہے کہ اللہ کے رسول صلی اللہ علیہ وسلم تمام مخلوق کی نسبت اللہ سے زیادہ ڈاتے تھے، اس لیے آپ کے طریقے سے ہٹ کر خوف الٰہی کے خود ساختہ طریقے مردود ہیں اور ایسا دعوی کرنے والا انسان جھوٹا ہے، نیز آپ تمام لوگوں کے مقابلے میں زیادہ باوفا اور ایفائے عہد کرنے والے اور سب سے بڑھ کر امانتیں ادا کرنے والے تھے،4- آپ کا یہودیوں کے ساتھ معاملات اور لین دین کرنا، جبکہ وہ واضح طور پر رشوت اور حرام خور لوگ تھے، اس بات کی دلیل ہے کہ جس کے پاس حرام مال ہو اس کے ساتھ معاملہ کرنا درست ہے بشر طیکہ جس مال کا معاملہ ہو رہا ہے وہ حرام نہ ہو۔ 5-’’جب سہولت ہو گی‘‘ گویا آپ نے کوئی مدت مقرر نہ فرمائی تھی جبکہ باب میں معین مدت کا ذکر ہے، لہٰذا باب یوں ہونا چاہیے ’’غیر معینہ مدت ک بیع‘‘ اور سنن کبری میں یہ باب اسی طرح ہے تا کہ حدیث باب کے مطابق بن سکے۔ 6-’’قطر بستی‘‘ یہ بحرین کے علاقے کی ایک بستی تھی جہاں بہترین کپڑے تیار ہوتے تھے۔ 7-اگر باب کا عنوان یہی رہے جوہے تو حدیث سے مناسبت اس طرح ہو گی کہ سہولت کا وقت ان کے ہاں متعین تھا، مثلاً: جب کٹائی کا وقت ہو اور کھجوریں گھروں میں آئیں وغیرہ۔ یہ بھی تعین ہی ہے۔8- ’’میں جانتا ہوں‘‘ یعنی اس صرف ادھار سے بچنے کے لیے یہ جھوٹ گھڑا ہے ورنہ اس کے دل میں بھی یہ بات نہیں تھی۔"}],[4629,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سلف اور بیع ایک ساتھ کرنے، ایک بیع میں دو شرطیں لگانے، اور اس چیز کے نفع لینے سے منع فرمایا جس کے تاوان کا وہ ذمے دار (ضامن) نہ ہو ۱؎۔\n§وضاحت\n۱؎: یعنی اس چیز کو بیچنا جو ابھی پہلے بیچنے والے سے خریدار کے قبضے میں آئی بھی نہ ہو، اور نہ ہی اس کے اوصاف :(وزن، ناپ اور نوعیت ) معلوم ہو۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبد اللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قرض کی شرط پر بیع، ایک سودے میں دو سودوں اور غیر مقبوضہ چیز کے منافع سے منع فرمایا۔","f2":"’’غیر مقبوضہ چیز کے منافع‘‘ یعنی غیر مقبوضہ چیز کو بیچ کر اس سے نفع حاصل کرنا۔ اصل منع تو بیچنا ہے۔ دارصل نفع کمانے کے لیے ہی بیچا جاتا ہے، اس لیے منافع کا ذکر کیا۔ یہ مطلب نہیں کہ نقصان اٹھا کر بیچنا جائز ہے۔ (باقی تفصیلات کے لیے دیکھیے، حدیث: ۴۶۱۵)"}],[4630,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سلف (قرض) اور بیع ایک ساتھ جائز نہیں، اور نہ ایک بیع میں دو شرطیں، اور نہ ہی ایسی چیز کا نفع جس کے تاوان کی ذمے داری نہ ہو\"۔\n§وضاحت\n۱؎: اور دونوں میں سے کسی ایک پر بات طے نہ ہو، اور اگر کسی ایک پر بات طے ہو جائے تو پھر بیع حلال اور جائز ہے۔","الألباني: حسن صحيح",{"u2":"حضرت عبد اللہ بن عمرو رضی اللہ عنہا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قرض کی شرط پر بیع، ایک بیع میں دو شرطیں اور غیر مقبوضہ چیز کا منافع حلال نہیں۔‘‘"}],[4631,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سلف (قرض) اور بیع ایک ساتھ کرنے سے، ایک ہی بیع میں دو شرطیں لگانے سے، اور اس چیز کے بیچنے سے جو تمہارے پاس موجود نہ ہو اور ایسی چیز کے نفع سے جس کے تاوان کی ذمہ داری نہ ہو، (ان سب سے) منع فرمایا۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے قرض کی شرط پر بیع، ایک بیع میں دو شرطوں اور غیر موجود چیز کی بیع اور غیر مقبوضہ چیز کے منافع سے منع فرمایا ہے۔","f2":"تمام تفصیلات دیکھنے کے لیے حدیث نمبر 4616‘4633 ملاحطہ فرمائیں۔"}],[4632,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک بیع میں دو بیع کرنے سے منع فرمایا ہے۔\n§وضاحت\n۱؎: اور دونوں میں کسی بات پر اتفاق نہ ہو سکا ہو، اگر کسی ایک پر اتفاق ہو گیا تو پھر یہ بیع حلال اور جائز ہے۔","الألباني: حسن صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک سودے میں دو سودوں سے منع فرمایا۔","f2":"ایک سودے میں دو سودوں کی ایک تفسیر تو مصنف رحمہ اللہ نے خود فرمائی ہے۔ اس کی کچھ بحث حدیث ۴۶۱۵ میں بیان ہو چکی ہے کہ اگر ادھار یا نقد ایک سودے پر بات طے ہو جائے تو نقد و ادھار قیمت کے فرق میں کوئی حرج نہیں کیونکہ یہ فرق فطری ہے، البتہ اگر کوئی ایک سودا طے نہ ہو، فلاں چیز بیچتا ہوں بشر طیکہ تو مجھے فلاں چیز بیچے۔ یہ جائز نہیں کیونکہ دوسری چیز کی فروخت کی شرط لگا کرنا جائز فائدہ اٹھایا جا رہا ہے۔ علامہ ابن قیم رحمہ اللہ نے ’’ایک بیع میں دو بیع‘‘ کی تفسیر یہ کی ہے کہ (بائع مشتری کو کہے:) میں تجھے فلاں چیز ادھار سو روپے کی دیتا ہوں اور تجھ سے ابھی نقد اسی روپے کی لیتا ہوں۔ اور پگر اسے چیز کی بجائے ۸۰ روپے دے دے اور سال کے بعد سو روپے وصول کر لے۔ ظاہرہے یہ ایک بیع میں دو سودے ہو رہے ہیں۔ اور یہ صریح سود ہے۔ ایسی بیع فاسد ہو گی کیونکہ یہ در حقیقت بیع ہے ہی نہیں۔ نہ کوئی چیز بیچی یا خریدی جا رہی ہے بلکہ اسی روپے دے کر سال کے بعد سو روپے لیے جا رہے ہیں جو صریح سود ہے۔ عصر حاضر میں بھی بعض لوگ اس طرح کرتے ہیں۔ بیع کا لفظ تو صرف دھوکا دینے کے لیے بولا جا رہا ہے۔ ایسی صورت میں وہ اسی روپے ہی واپس کرے گا۔ اگر یہ سو روپے واپس لے گا تو یہ سود ہو گا۔ یہ آخری دو صورتیں اس حدیث (ایک سودے میں دو سودے) کی بہترین تفسیر ہیں اور یہ دونوں منع ہیں، البتہ پہلی صورت نقد و ادھار والی صحیح ہے۔ اگر سود ایک صورت میں طے ہو جائے تو ادھار اور نقد قیمت میں فرق ہو سکتا ہے کیونکہ یہ ایک بیع ہے، دو نہیں، لہٰذا یہ صورت اس حدیث کی صحیح تفسیر نہیں۔ ابہام باقی رہے، کوئی اور صورت طے نہ ہو تو اسے اس حدیث کے تحت لایا جا سکتا ہے۔"}],[4633,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے محاقلہ و مزابنہ اور مخابرہ نامی بیع سے اور غیر متعین اور غیر معلوم مقدار کے استثناء ۱؎ سے منع فرمایا ہے۔ (آگے آنے والی) ہمام بن یحیی کی روایت میں گویا یہ دلیل ہے کہ عطاء نے جابر رضی اللہ عنہ سے ان کی یہ حدیث نہیں سنی ہے ۲؎ جو انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے کہ جس کے پاس زمین ہو تو وہ اس میں کھیتی کرے۔\n§وضاحت\n۱؎: بیچی ہوئی چیز میں سے بلا تعیین و تحدید کچھ لینے کی شرط رکھنا یا سارے باغ یا کھیت کو بیچ دینا اور اس میں سے غیر معلوم مقدار نکال لینا۔ ۲؎: جابر بن عبداللہ رضی اللہ عنہما سے عطاء کی یہ روایت صحیح بخاری میں موجود ہے :(دیکھئیے حدیث نمبر ۳۹۰۵ تخریج ) سندھی فرماتے ہیں: مؤلف نے «کالدلیل» کہا ہے :(«الدلیل» نہیں کہا ہے ) جو اس بات کی دلیل ہے کہ یہ بات مؤکد نہیں ہے۔ نیز یہ ممکن ہے کہ عطاء نے سلیمان سے سننے کے بعد پھر جابر رضی اللہ عنہ سے جا کر یہ حدیث سنی ہو۔ ایسا بہت ہوتا ہے۔\nجابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بیع محاقلہ، مزابنہ، مخابرہ سے اور بیع میں استثناء کرنے سے سوائے اس کے کہ مقدار معلوم ہو منع فرمایا ہے۔\n§وضاحت\n۱؎: یعنی درخت کے پھل بیچتے وقت کچھ غیر معلوم پھل الگ کرنے سے منع فرمایا، اگر الگ کئے ہوئے پھلوں کی مقدار طے ہو تو یہ معاملہ جائز ہے، لیکن یہ مقدار اتنی بھی نہ ہو کہ بیچے ہوئے پھل کی مقدار انتہائی کم رہ جائے، جس سے خریدار کو گھاٹا ہو۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے محاقلہ، مزابنہ، مخابرہ اور سودے میں استثنا سے منع فرمایا ہے الا یہ کہ وہ استثنا معلوم ہو۔","f2":"محاقلہ، مزابنہ اور مخابرہ کی تشریح پیچھے گزر چکی ہے۔ (دیکھیے، حدیث: ۳۹۱۰) بیع میں استثنا کا مطلب یہ ہے کہ بیچنے والا کہے: میں تجھے اس باغ کا پھل اتنے میں بیچتا ہوں مگر دس درختوں کا پھل میرا ہو گا۔ لیکن وہ یہ نہیں بتاتا کہ کون سے دس درختوں کا پھل اس کا ہو گا؟ اس صورت میں استثنا مجہول ہو گا جو تنازع اور اختلاف کا سبب بن سکتا ہے، لہٰذا یہ منع ہے۔ ہاں، اگر وہ دس درخت متعین کر لیے جائیں تو یہ معلوم استثنا ہے۔ اس میں کسی تنازع کا کوئی خطرہ نہیں، اس لیے یہ استثنا جائز ہے۔ اسی طرح بیچنے والا کہے کہ اتنے من پھل باغ میں سے لوں گا یا اتنے مالٹے تو یہ بھی معلوم استثنا ہے اور جائز ہے۔"}],[4634,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ، مزابنہ، مخابرہ، معاومہ (کئی سالوں کی بیع) اور بیع میں الگ کرنے سے منع فرمایا اور بیع عرایا(عاریت والی بیع) میں رخصت دی۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم محاقلہ، مزابنہ، مخابرہ، معاومہ اور بیع میں استثنا سے منع فرمایا، البتہ عطیے کے درختوں میں مزابنہ (موجود پھل کی بیع خشک پھل کے ساتھ) کی رخصت دی ہے۔","f2":"معاومہ سے مراد کئی سال کا سودا کرنا ہے۔ (تفصیل دیکھیے، حدیث: ۴۶۳۰) باقی بحث کے لیے ملا حظہ فرمائیں حدیث: ۳۹۱۰، ۴۵۴۲."}],[4635,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی کوئی کھجور کے درخت کی پیوند کاری کرے پھر اس درخت کو بیچے تو درخت کا پھل پیوند کاری کرنے والے کا ہو گا، سوائے اس کے کہ خریدنے والا پھل کی شرط لگا لے\" ۱؎۔\n§وضاحت\n۱؎: یہ معاملہ ہر قسم کی کھیتی کے بیچنے میں ہو گا، کیونکہ کھیتی میں بیچنے والا خرچ کیا ہوتا ہے، کھجور میں تو تابیر :(پیوند کاری ) سے پہلے بیچنے والے کا کچھ خرچ نہیں ہوتا ہے اس لیے تابیر :(پیوند کاری ) کی شرط لگائی گئی ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کھجور کے درختوں کو پیوند لگائے، پھروہ درخت بیچ دے تو ان کا پھل پیوند لگانے والے کو ملے گا، الا یہ کہ خریدنے والا شرط لگائے۔‘‘","f2":"1۔ مقصد یہ ہے کہ اگر کھجوروں کے درخت ایسی حالت میں بیچے جائیں کہ ان پر پھل لگ چکا ہو اور موجود بھی ہو تو وہ پھل بائع کا ہوگا، تا ہم اگر خریدار یہ شرط کر لے کہ درختوں پر لگا ہوا پھل بھی میرا ہو گا اور بیچنے والا یہ شرط مان لے تو اس صورت میں پھل مشترَی کا ہوگا۔ اور یہ بیع بالکل درست ہو گی۔ اگر خریدار پھلوں کی شرط نہیں لگائے گا تو وہ پھل بیچنے والے کے ہوں گے۔2۔اس حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ کھجوروں اور درختوں کی پیوند کاری کی جا سکتی ہے۔ یہ درست عمل ہے۔ شرعاً اس میں کوئی قباحت اور خرابی نہیں ہے۔3۔ ایسی شرط جو معاہدے کے منافی نہ ہو، اس کے متعین کر لینے سے بیع فاسد نہیں ہو گی اور نہ یہ چیز اس حدیث مبارکہ کے حکم میں داخل ہوگی جس میں بیع اور شرط سے منع کیا گیا ہے، معلوم ہوا کہ درختوں کی بیع پھل کے بغیر بھی ہو سکتی ہے۔"}],[4636,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی تابیر (پیوند کاری) ہو جانے کے بعد (کھجور کا) درخت خریدے تو اس کا پھل بائع کا ہو گا سوائے اس کے کہ خریدار شرط لگا دے، اور جو غلام بیچے اور اس کے پاس مال ہو تو اس کا مال بائع کا ہو گا سوائے اس کے کہ خریدار شرط لگا دے\"۔","الألباني: صحيح",{"u2":"حضرت سالم کے والد محترم (حضرت عبد اللہ بن عمر رضی اللہ عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص پیوند لگانے کے بعد درخت بیچے تو اس کا پھل بیچنے والے کو ملے گا الا یہ کہ خرید نے والا شرط لگالے۔ اسی طرح جو شخص ایسا غلام فروخت کرے جس کے پاس مال ہو تو اس کا مالہ بیچنے والے کو ملے گا مگر یہ کہ خرید نے والا لگالے۔‘‘","f2":"’’اس کا مال بیچنے والے کو ملے گا‘‘ کیونکہ مالک نے غلام بیچا ہے نہ کہ مال۔ غلام کا مال درصل مالک کا ہوتا ہے۔ غلام خود مالک نہیں ہوتا، خواہ مالک نے غلام کو کاروبار کی اجازت بھی دے رکھی ہو۔ باب میں لفظ استثنا استعمال کیا گیا ہے، مراد شرط لگانا ہے۔"}],[4637,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھا، میرا اونٹ تھک کر چلنے سے عاجز آ گیا، تو میں نے چاہا کہ اسے چھوڑ دوں، اتنے میں رسول اللہ صلی اللہ علیہ وسلم مجھ سے آ ملے، آپ نے اس کے لیے دعا کی اور اسے تھپتھپایا، اب وہ ایسا چلا کہ اس طرح کبھی نہ چلا تھا، آپ نے فرمایا:\"اسے ایک اوقیہ (۴۰ درہم) میں مجھ سے بیچ دو\"، میں نے کہا: نہیں (بلکہ وہ آپ ہی کا ہے)، آپ نے فرمایا: \"اسے مجھ سے بیچ دو\" تو میں نے ایک اوقیہ میں اسے آپ کے ہاتھ بیچ دیا اور مدینے تک اس پر سوار ہو کر جانے کی شرط لگائی ۱؎، جب ہم مدینہ پہنچے تو میں اونٹ لے کر آپ کے پاس آیا اور اس کی قیمت چاہی، پھر میں لوٹا تو آپ نے مجھے بلا بھیجا، اور فرمایا: \"کیا تم سمجھتے ہو کہ میں نے کم قیمت لگائی تاکہ میں تمہارا اونٹ لے سکوں، لو اپنا اونٹ بھی لے لو اور اپنے درہم بھی\"۔\n§وضاحت\n۱؎: یہ جائز شرط تھی اس لیے نبی اکرم صلی اللہ علیہ وسلم نے اس پر معاملہ کر لیا، یہی باب سے مناسبت ہے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ میں ایک سفر میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھا۔ میرا اونٹ چلنے سے عاجز آ گیا۔ میں نے سوچا، اسے (وہیں) چھوڑ دوں۔ اتنے میں رسول اللہ صلی اللہ علیہ وسلم مجھے پیچھے سے آ ملے۔ آپ نے اس کے لیے دعا بھی فرمائی اور اسے مارا بھی۔ پھر تو وہ ایسے چلنے لگا کہ (ساری زندگی) کبھی ایسا نہیں چلا تھا، پھر آپ نے فرمایا: ’’یہ اونٹ ایک اوقیہ (چالیس در ہم) میں مجھے بیچ دے۔‘‘ تو میں نے وہ اونٹ آپ کو ایک اوقیے میں بیچ دیا اور میں نے مدینہ منورہ تک سوار ہو کر جانے کی شرط لگالی۔ جب ہم مدینہ منورہ پہنچے، میں آپ کے پاس اونٹ لے کر حاضر ہوا اور آپ سے قیمت طلب کی۔ میں قیمت لے کر واپس جانے لگا تو آپ نے مجھے واپس بلا بھیجا اور فرمایا: ’’کیا تو سمجھتا ہے کہ میں نے تیرا اونٹ لینے کے لیے تجھے کم قیمت دی ہے؟ اپنا اونٹ بھی لے جا اور قیمت بھی۔‘‘","f2":"مندرجہ ذیل فوائد و مسائل کا مطالعہ کرتے ہوئے یہ اہم بات ضرور یا درہنی چاہیے کہ اس باب کے تحت مذکور حدیث حدیثِ جابر کے نام سے معروف ہے۔ اس کے بہت سے طرق ہیں، لہٰذا ان طرق کے لحاظ سے الفاظ کی کمی بیشی اور تفصیل واجمال سب کا لحاظ رکھتے ہوئے یہ فوائد و مسائل تحریر کیے گئے ہیں۔\nفوائد و مسائل: 1۔سودا کرتے ہوئے اگر ایسی شرط لگائی جائے جو مقصودِ عقد کے منافی نہ ہو تو اس صورت میں بیع اور شرط جائز ہو گی، خواہ اس شرط سے خرید نے یا بیچنے والے کو اضافی فائدہ حاصل ہوتا ہو۔ جس شخص کے پاس کوئی چیز ہو اس سے اس چیز کا سواد کرنا جائز ہے، نیز یہ حدیث سفر میں سودا کرنے کے جواز پر بھی دلالت کرتی ہے اور یہ کہ خرید و فروخت کے وقت، خریدار چیز کی قیمت بتا سکتا ہے کہ میں تمھاری چیز اتنی رقم میں خریدوں گا، یا تم مجھے اپنی فلاں چیز اتنی رقم کے عوض دے دو، اسی طرح سودا پکا ہونے سے پہلے، بیع (سودے) کی قیمت کم و بیش کرنے، کرانے کی بابت بحث کرنا درست ہے، البتہ یہ ناجائز ہے کہ کسی چیز کی قیمت، جائز حدود سے کم و بیش کرنے، کرانے کی بابت بحث کرنا درست ہے، البتہ یہ نا جائز ہے کہ کسی چیز کی قیمت، جائز حدود سے کم کرانے کے لیے اپنا اثر ور سوخ اور منصب و اختیار استعمال کیا جائے اور مالک کو نقصان پہنچایا جائے۔ اس حدیث مبارکہ سے یہ اہم مسئلہ بھی ثابت ہوتا ہے کہ صحت بیع (سودا درست ہونے) کے لیے مبیع قبضے میں لینا شرط نہیں جیسا کہ خود رسول اللہ صلی اللہ علیہ وسلم نے سودا کر کے مبیع، یعنی اونٹ اپنے قبضے میں نہیں لیا بلکہ وہ مدینے تک سواری کے لیے حضرت جابر رضی اللہ تعالٰی عنہ کے پاس ہی رہا، البتہ یہ ضروری ہے کہ اس خریدی ہوئی چیز کو قبضے میں لینے سے پہلے آگے فروخت نہ کیا جائے ایسا کرنا شرعاً نا جائز اور حرام ہے۔ عمر اور مرتبے میں بڑی شخصیت کو جائز معاملے میں ’’نہیں‘‘ کہا جا سکتا ہے جیسا کہ سیدنا جابر رضی اللہ تعالٰی عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے کے جواب میں پہلے کہا: یہ بے ادبی یا گستاخی نہیں۔ یہ حدیث اس مسئلے پر بھی دلالت کرتی ہے کہ نیک اور صالح عمل کا اظہار کرنا جبکہ وہ افراط تفریط اور فخر و ریا، نیز اپنی بڑائی بیان کرنے کی غرض سے نہ ہو شرعاً مباح اور جائز ہے۔ اگر ایسا کرنے کا مقصد اپنی نیکی اور پارسائی کا اظہار ہو یا بطور فخر ایسا کیا جائے تو یہ نا جائز اور انتہائی قبیح عمل ہے۔ اس سے احتراز کرنا ضروری اور واجب ہے۔ اس حدیث مبارکہ سے، بوقت ضرورت جانوروں کو مارنے کا جواز نکلتا ہے۔ اگرچہ جانور غیر مکلف ہیں، تا ہم ان کی ’’اصلاح‘‘ کے لیے انھین ’’سزا‘‘ دی جا سکتی ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے بذاتِ خود، اپنے دستِ مبارکہ سے اونٹ کو مارا تھا۔ یہ یاد رہے کہ یہ طریقہ اس وقت استعمال کیا جائے جب جانور تھکاوٹ کی وجہ سے نہیں بلکہ اپنی ضد کی وجہ سے تنگ کر رہا ہو۔ حاکم وقت، یا دیگر ذمہ داران کو اپنے ماتحت اشخاص کے حالات کا جائزہ لیتے رہنا چاہیے۔ ان کی مالی معاونت کرنی چاہیے، نیز ہر وقت احساس کے جذبے سے معمور رہنا چاہیے جیسا کہ رسول اکرم صلی اللہ علیہ وسلم نے حضرت جابر کے ساتھ۔ قرض کی ادائیگی کر دو۔ ثمن کا وزن کرنا مشتری کے ذمے ہے۔ یہ بھی معلوم ہوتا ہے کہ ادھار چیز خریدنا شرعاً درست اور جائز ہے۔ ضرورت کے وقت چو پائے مسجد کے صحن میں داخل کیے جا سکتے ہیں۔ اسی طرح دیگر سازو سامان بھی مسجد کے صحن میں رکھا جا سکتا ہے۔ اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ کسی شخص کا عطیہ قبول کرنے سے پہلے، اس پر رد کیا جا سکتا ہے۔ اس کی دلیل یہ ہے کہ حضرت جابر رضی اللہ تعالٰی عنہ نے اپنے اونٹ کی بابت کہا: اے اللہ کے رسول! یہ آپ کا ہے لیکن آپ نے فرمایا: ’’نہیں (میں بلا قیمت قبول نہیں کرتا) بلکہ یہ اونٹ مجھے بیچ دو۔‘‘ اس حدیث مبارکہ سے یہ اہم مسئلہ بھی ثابت ہوتا ہے کہ صحابہ کرام رسول اللہ صلی اللہ علیہ وسلم کے تبرات کی حفاظت کا خاص اہتمام فرمایا کرتے تھے جیسا کہ سیدنا جابر رضی اللہ تعالٰی عنہ نے فرمایا: ’’رسول اللہ صلی اللہ علیہ وسلم کی جانب سے زیادہ دیا ہوا قیراط مجھ سے کبھی جدا نہیں ہوا، میں نے اسے ایک تھیلی میں ڈال دیا۔ لیکن اس سلسلے میں یہ بات ضرور یاد رکھنی چاہے کہ تبرکات مستند ذریعے سے ثابت ہوں، خود ساختہ نہ ہوں، نیز تبرکات کے نا قلین بھی ثقہ ہوں، غیر معتبر لوگوں کے قصے کہانیوں پر بلا تحقیق اعتماد نہیں کرنا چاہیے۔ حضرت جابر رضی اللہ تعالٰی عنہ کی فضیلت بھی اس حدیث سے واضح ہوتی ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی فرماں برداری کرتے ہوئے، ذاتی ضرورت کے باوجود اونٹ آپ کو بیچ دیا۔ اس حدیث سے رسول اللہ صلی اللہ علیہ وسلم کے معجزے کا ثبوت بھی ملتا ہے۔ یاد رہے معجزے میں قدرت الٰہی کار فرما ہوتی ہے۔ اس میں انسانی اختیار نہیں ہوتا۔ اس حدیث سے رسول اللہ صلی اللہ علیہ وسلم کے حسن اخلاق کا اثبات بھی بھی ہوتا ہے۔ آپ نے سیدنا جابر رضی اللہ تعالٰی عنہ کو نہ صرف یہ کہ طے شدہ قیمت سے قیراط زیادہ دیا بلکہ وہ اونٹ بھی واپس کر دیا۔ ’’شرط لگالی‘‘ گویا ایسی شرط بیع کے پکا ہونے کے منافی نہیں۔ امام احمد رحمہ اللہ اسی کے قائل ہیں۔ احناف اس شرط کو مقتضائے عقد کے خلاف سمجھتے ہیں۔ ان کے نزدیک یہ شرط نہیں تھی بلکہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے ان کے لیے رعایت تھی۔ کسی راوی نے غلطی سے شرط کہہ دیا لیکن احناف کی یہ توجیہ محدثین کے فیصلے کے خلاف ہے۔ اکثر راوی شرط بیان کرتے ہیں۔"}],[4638,"جابر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنے سینچائی کرنے والے اونٹ پر بیٹھ کر جہاد کیا، پھر انہوں نے لمبی حدیث بیان کی، پھر ایک چیز کا تذکرہ کیا جس کا مطلب یہ ہے کہ اونٹ تھک گیا تو اسے نبی اکرم صلی اللہ علیہ وسلم نے ڈانٹا تو وہ تیز ہو گیا یہاں تک کہ سارے لشکر سے آگے نکل گیا، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جابر! تمہارا اونٹ تو لگ رہا ہے کہ بہت تیز ہو گیا ہے\"، میں نے عرض کیا: آپ کے ذریعہ سے ہونے والی برکت سے اللہ کے رسول! آپ نے فرمایا: \"اسے، میرے ہاتھ بیچ دو۔ البتہ تم (مدینہ) پہنچنے تک اس پر سوار ہو سکتے ہو\"، چنانچہ میں نے اسے بیچ دیا حالانکہ مجھے اس کی سخت ضرورت تھی۔ لیکن مجھے آپ سے شرم آئی۔ جب ہم غزوہ سے فارغ ہوئے اور (مدینے کے) قریب ہوئے تو میں نے آپ سے جلدی سے آگے جانے کی اجازت مانگی، میں نے عرض کیا: اللہ کے رسول! میں نے ابھی جلد شادی کی ہے، آپ نے فرمایا: \"کنواری سے شادی کی ہے یا بیوہ سے؟\" میں نے عرض کیا: بیوہ سے، اللہ کے رسول! والد صاحب عبداللہ بن عمرو رضی اللہ عنہما مارے گئے اور انہوں نے کنواری لڑکیاں چھوڑی ہیں، تو مجھے برا معلوم ہوا کہ میں ان کے پاس ان جیسی (کنواری لڑکی) لے کر آؤں، لہٰذا میں نے بیوہ سے شادی کی ہے جو انہیں تعلیم و تربیت دے گی، تو آپ نے مجھے اجازت دے دی اور مجھ سے فرمایا: \"اپنی بیوی کے پاس شام کو جانا\"، جب میں مدینے پہنچا تو میں نے اپنے ماموں کو اونٹ بیچنے کی اطلاع دی، تو انہوں نے مجھے ملامت کی، جب رسول اللہ صلی اللہ علیہ وسلم پہنچے تو میں صبح کو اونٹ لے کر آپ کے پاس گیا، تو آپ نے مجھے اونٹ کی قیمت ادا کی اور اونٹ بھی دے دیا اور (مال غنیمت میں سے) ایک حصہ سب لوگوں کے برابر دیا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ مٰں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ اپنے پانی والے اونٹ پر ایک جنگ میں گیا، پھر انھوں نے لمبی حدیث بیان کی جس کا مفہوم یہ ہے کہ (واپسی کے دور ان میں) اونٹ تھک کر رک گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے اس کو ڈانٹا تو وہ اتنا تیز ہو گیا کہ سب لشکر سے آگے نکل گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جابر! میں دیکھ رہا ہوں کہ تیرا اونٹ بہت تیز ہو گیا ہے۔ آپ نے فرمایا: ’’یہ مجھے بیچ دے۔ تجھے (مدینہ منورہ تک) سوار ہو کر جانے کی اجازت ہو گی۔‘‘ میں نے آپ کو بیچ دیاجبکہ مجھے اس کی سخت ضرورت تھی۔ لیکن مجھے شرم محسوس ہوئی (کہ آپ کو انکار کروں)۔ غزوے کی تکمیل کے بعد جب ہم مدینہ منورہ کے قریب پہنچے تو میں آپ سے جلدی جانے کی اجازت طلب کی۔ میں نے کہا: اللہ کے رسول! میں نے نئی نئی شادی کی ہے۔ آپ نے فرمایا: ’’کنواری سے یا شوہر دیدہ سے؟‘‘ میں نے کہا: اللہ کے رسول! شوہر دیدہ سے۔ وجہ یہ ہے کہ (میرے والد) حضرت عبد الہ بن عمرو رضی اللہ تعالٰی عنہ شہید ہو گئے اور وہ چھوٹی چھوٹی کنواری بیٹیاں چھوڑ گئے۔ میں نا پسند کیا کہ میں ان جیسی (نو جوان لڑکی) لے آؤں، اس لیے میں نے ایک شوہر دیدہ (بیوہ یا مطلقہ) سے شادی کی جوان کو علم و ادب سکھائے۔ خیر! آپ نے مجھے اجازت دے دی۔ آپ نے فرمایا: ’’شام کے وقت گھر پہنچ جانا۔‘‘ جب میں آیا تو میں نے اپنے ماموں کو اونٹ کے فروخت کرنے کا بتایا۔ انھوں نے مجھے ملامت کی۔ جب رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے تو میں آپ کے پاس صبح کے وقت اونٹ لے کر گیا۔ آپ نے مجھے اونٹ کی قیمت بھی دی، اونٹ بھی دیا اور لوگوں کے برابر حصہ بھی دیا۔","f2":"فوائد و مسائل:1۔’’شام کے وقت گھر پہنچ جانا‘‘ یعنی رات کو گھر نہ جانا کیونکہ لمبے سفر کے بعد رات کے وقت گھر واپسی منع ہے کیونکہ غالب گمان یہ ہے کہ بیوی سادہ حالت میں ہو گی، صفائی وغیرہ نہ کی ہو گی، غسل بھی نہ کیا ہو گا۔ دیر کے بعد واپسی ہو تو جماع کی خواہش قدرتی بات ہے اور یہ حالت جماع کے لیے مناسب نہیں، لہٰذا شام سے پہلے گھر جائے تا کہ رات بیوی کو غسل، صفائی اور زینت کا موقع مل جائے۔ مرد زیادہ خوش ہو گا۔ اس حدیث کے تفصیلی فوائد سابقہ حدیث: ۴۶۴۱ کے تحت ذکر ہو چکے ہیں، وہاں ملا حظہ فرمائیں۔"}],[4639,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھا، میں ایک اونٹ پر سوار تھا۔ آپ نے فرمایا: \"کیا وجہ ہے کہ تم سب سے پیچھے میں ہو؟\" میں نے عرض کیا: میرا اونٹ تھک گیا ہے، آپ نے اس کی دم کو پکڑا اور اسے ڈانٹا، اب حال یہ تھا کہ میں سب سے آگے تھا، (ایسا نہ ہو کہ لوگوں کے اونٹ سے آگے بڑھ جائے اس لیے) مجھے اس کے سر سے ڈر ہو رہا تھا، تو جب ہم مدینے سے قریب ہوئے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اونٹ کا کیا ہوا؟ اسے میرے ہاتھ بیچ دو\"، میں نے عرض کیا: نہیں، بلکہ وہ آپ ہی کا ہے، اللہ کے رسول! آپ نے فرمایا: \"نہیں، اسے میرے ہاتھ بیچ دو\"، میں نے عرض کیا: نہیں، بلکہ وہ آپ ہی کا ہے، آپ نے کہا: \"نہیں، بلکہ اسے میرے ہاتھ بیچ دو، میں نے اسے ایک اوقیہ میں لے لیا، تم اس پر سوار ہو اور جب مدینہ پہنچ جاؤ تو اسے ہمارے پاس لے آنا\"، جب میں مدینے پہنچا تو اسے لے کر آپ کے پاس آیا، آپ نے بلال رضی اللہ عنہ سے فرمایا: \"بلال! انہیں ایک اوقیہ (چاندی) دے دو اور ایک قیراط مزید دے دو\"، میں نے عرض کیا: یہ تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے زیادہ دیا ہے، (یہ سوچ کر کہ) وہ مجھ سے کبھی جدا نہ ہو، تو میں نے اسے ایک تھیلی میں رکھا، پھر وہ قیراط میرے پاس برابر رہا یہاں تک کہ حرہ کے دن ۱؎ اہل شام آئے اور ہم سے لوٹ لے گئے جو لے گئے۔\n§وضاحت\n۱؎: یہ واقعہ ۶۳؁ھ میں پیش آیا تھا، اس میں یزید کے لشکر نے مدینے پر چڑھائی کی تھی۔ حرہ کالے پتھروں والی زمین کو کہتے ہیں جو مدینے کے مشرقی اور مغربی علاقہ کی زمین ہے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبد اللہ رضی اللہ عنہ نے فرمایا: میں ایک سفر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا۔ میں ایک اونٹ پر سوار تھا۔ آپ نے فرمایا: ’’کیا بات ہے تو سب سے آخر میں ہے؟‘‘ میں نے کہا: میرا اونٹ چلنے سے عاجز آ چکا ہے۔ آپ نے اس کی دم پکڑ کر اسے ڈانٹا۔ پھر تو وہ اتنا آگے چلا گیا کہ مجھے اس کا سر سنبھالنا مشکل ہو رہا تھا۔ جب ہم مدینہ منورہ کے قریب ہوئے تو آپ نے فرمایا: ’’تیرے اونٹ کا کیا حال ہے؟ یہ مجھے بیچ دے۔‘‘ میں نے کہا: یہ ویسے ہی آپ کا ہے۔ (بیچنے کی کیا ضرورت ہے؟) آپ نے فرمایا: ’’نہیں مجھے بیچ دے۔‘‘ میں نے کہا: نہیں، بلکہ یہ ویسے ہی آپ کا ہے۔ آپ نے فرمایا: ’’نہیں بلکہ مجھے بیچ دے۔ میں نے یہ ایک اوقیے میں لے لیا۔ ہاں تو سوار رہ، پھر جب تو مدینے پہنچ جائے تو اسے میرے پاس لے آنا۔‘‘ پھر جب میں مدینہ منورہ میں آیا تو میں اونٹ لے کر آپ کے پاس گیا۔ آپ نے حضرت بلال رضی اللہ تعالٰی عنہ سے فرمایا: ’’بلال! اس کو تو ایک اوقیہ (چالیس در ہم) تول دے او ایک قیراط اس کو زائد دے دے۔‘‘ میں نے کہا: یہ قیراط رسول اللہ صلی اللہ علیہ وسلم نے مجھے زائد دیا ہے، یہ کبھی بھی مجھ سے جدا نہیں ہو گا۔ میں نے اسے ایک تھیلی میں ڈال لیا۔ وہ ہمیشہ میرے پاس رہا حتی کہ حرہ والے دن شام والے آئے تو انھوں نے ہم سے جو چاہا، لوٹ لیا۔","f2":"فوائد و مسائل:1۔ ’’قیراط‘‘ دینار کا بیسواں حصہ یا جدیدد اعشاری نظام کے مطابق ۱.۲۵۵ ملی گرام کا ہوتا ہے۔ ’’جدا نہیں ہو گا‘‘ رسول اللہ صلی اللہ علیہ وسلم کا تبرک تھا۔ ’’حرہ والے دن‘‘ یہ یزید کے دور کی بات ہے۔ مدینے والوں نے حضرت حسین رضی اللہ تعالٰی عنہ کی شہادت کے بعد یزید کی بیعت توڑ دی تھی۔ یزید نے سزا دینے کے لیے شام سے لشکر بھیجا۔ اہل مدینہ سے حرہ کے پتھر یلے میدان میں لڑائی ہوئی۔ مدینے والوں کو شکست ہوئی۔ شامی لشکر نے خوب خون ریزی کی۔ اور مدینہ منورہ میں لوٹ مار کی۔ صحابہ تک کی توہین کی۔ اسی غدر میں حضرت جابر رضی اللہ تعالٰی عنہ سے بھی ان وحشیوں نے وہ ’’تبرک‘‘ لوٹ لیا۔"}],[4640,"جابر رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے پایا کہ میں اپنے سینچنے والے اونٹ پر سوار تھا، میں نے عرض کیا: افسوس! ہمارے پاس ہمیشہ پانی سینچنے والا اونٹ ہی رہتا ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جابر! کیا تم اسے میرے ہاتھ بیچو گے؟\" میں نے عرض کیا: یہ تو آپ ہی کا ہے، اللہ کے رسول! آپ نے فرمایا: \"اے اللہ! اس کی مغفرت کر، اس پر رحم فرما، میں نے تو اسے اتنے اتنے دام پر لے لیا ہے، اور مدینے تک اس پر سوار ہو کر جانے کی تمہیں اجازت دی ہے\"، جب میں مدینے آیا تو اسے تیار کر کے آپ کی خدمت میں حاضر ہوا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلال! انہیں اس کی قیمت دے دو\"، جب میں لوٹنے لگا تو آپ نے مجھے بلایا، مجھے اندیشہ ہوا کہ آپ اسے لوٹائیں گے، آپ نے فرمایا: \"یہ تمہارا ہے\"۔","الألباني: ضعيف الإسناد منكر المتن",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم مجھے ملے تو میں اپنے ایک پانی بھرنے والے بد مزاج اونٹ پر سوار تھا۔ میں نے (افسوس کرتے ہوئے) کہا: افسوس! پانی کا نکما اونٹ ہمیشہ ہمارے پاس رہتا ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اے جابر! کیا تو مجھے یہ اونٹ فروخت کرے گا؟ ’’میں نے کہا: اے اللہ کے رسول! یہ ویسے ہی آپ کی خدمت میں پیش ہے۔ آپ نے دعا دی: ’’اے اللہ! اس کو معاف فرما۔ اس پر رحم فرما۔‘‘ پھر فرمایا: ’’میں یہ اتنے اتنے میں خرید لیا۔ ویسے میں مدینہ منورہ تک اس کی سواری کی تجھے اجازت دیتا ہوں۔‘‘ جب میں مدینہ منورہ پہنچا تو میں نے اس اونٹ کو تیار کیا اور آپ کے پاس لے گیا۔ آپ نے فرمایا: ’’بلال! اس کی اس اونٹ کی قیمت دے دو۔‘‘ جب میں واپس مڑا تو مجھے بلایا۔ مجھے خطرہ ہوا کہ آپ اونٹ واپس فرما دیں گے۔ آپ نے فرمایا: ’’یہ اونٹ تیرا ہی ہے۔‘‘"}],[4641,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جا رہے تھے، میں سینچائی کرنے والے ایک اونٹ پر سوار تھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اسے میرے ہاتھ اتنے اتنے میں بیچو گے؟ اللہ تمہیں معاف کرے\"، میں نے عرض کیا: ہاں، اللہ کے نبی! وہ آپ کا ہی ہے، آپ نے فرمایا: \"کیا تم اسے میرے ہاتھ اتنے اور اتنے میں بیچو گے؟ اللہ تمہیں معاف کرے\"، میں نے عرض کیا: ہاں، اللہ کے نبی! وہ آپ ہی کا ہے، آپ نے فرمایا: \"کیا تم اسے میرے ہاتھ اتنے اور اتنے میں بیچو گے؟ اللہ تمہیں معاف کرے\"، میں نے عرض کیا: ہاں، وہ آپ ہی کا ہے۔ ابونضرہ کہتے ہیں: یہ مسلمانوں کا تکیہ کلام تھا کہ جب کسی سے کہتے: ایسا ایسا کرو تو کہتے: «واللہ یغفر لک»۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہے تھے۔ میں اپنے پانی ڈھونے والے اونٹ پر سوار تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا تو اپنا یہ اونٹ مجھے اتنے اتنے میں فروخت کرے گا؟ اللہ تعالیٰ تیری مغفرت فرمائے۔‘‘ میں نے کہا: اللہ کے نبی! وہ آپ کا ہی ہے۔ پھر فرمایا: ’’مجھے اتنے اتنے میں فروخت کرے گا؟ اللہ تعالیٰ تیری مغفرت فرمائے۔‘‘ میں نے کہا: اللہ کے نبی! یقینا یہ آپ کا ہی ہے۔ آپ نے پھر فرمایا: ’’تو یہ اونٹ مجھے اتنے میں فروخت کرے گا؟ اللہ تعالیٰ تجھے معاف فرمائے۔‘‘ میں کہا: جی ہاں۔ وہ آپ کا ہی ہے۔ راوی ابو نضرہ نے کہا کہ (اللہ تجھے معاف کرے) ایک کلمہ ہے جو مسلمان عموماً کہتے تھے۔ یو یہ کام کر لے، اللہ تجھے معاف کرے۔","f2":"فوائد و مسائل:1۔ آپ کا بار بار فرمانا دراصل اس کو زیادہ دعا دینے کے لیے تھا اور شفقت کے طور پر بھی۔ یہ جملہ دعائیہ ہے۔ مسلمانوں کی یہ عادت تھی کہ جب کوئی شخص دوسرے کو کسی بات کا حکم دیتا یا اس سے کوئی معاملہ کرتا تو اس وقت یہ دعائیہ جملے بولا کرتا تھا۔ یہ حضرت جابر رضی اللہ تعالٰی عنہ کے لیے فضیلت کی بات ہے۔ ایک ہی واقعہ اسانید کے ساتھ بیان کرنے کا مقصد یہ ہوتا ہے کہ تمام تفصیلات و جزئیات اوضح ہو جاتی ہیں اور لفظی فرق کا پتا بھی چل جاتا ہے۔ جب روایات میں لفظی فرق ہو تو کسی ایک فریق کا لفظ سے استد لال کرنا کمزور ہو جاتا ہے، جیسے اس حدیث میں اختلاف ہے کہ مدینہ منورہ تک استد لال کی شرط حضرت جابر رضی اللہ تعالٰی عنہ نے بیع میں لگائی تھی یا رسول اللہ صلی اللہ علیہ وسلم نے ان کو یہ رعایت فرمائی تھی لہٰذا شرط پر استد لال کمزور ہو جائے گا، البتہ امام بخاری جیسے عظیم محدث نے فیصلہ فرمایا ہے کہ شرط لگانے کے الفاظ زیادہ اور قوی ہیں، اس لیے ترجیح اسی کو ہو گی۔"}],[4642,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے بریرہ رضی اللہ عنہا کو خریدا تو ان کے گھر والوں نے ولاء (وراثت) کی شرط لگائی، میں نے اس کا ذکر نبی اکرم صلی اللہ علیہ وسلم سے کیا، تو آپ نے فرمایا: \"اسے آزاد کر دو، کیونکہ ولاء (وراثت) اس کا حق ہے جس نے درہم (روپیہ) دیا ہے\"، چنانچہ میں نے انہیں آزاد کر دیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے انہیں بلایا اور انہیں ان کے شوہر کے بارے میں اختیار دیا ۱؎ تو بریرہ رضی اللہ عنہا نے اپنے شوہر کی زوجیت میں نہ رہنے کو ترجیح دی، حالانکہ ان کے شوہر آزاد تھے ۲؎۔\n§وضاحت\n۱؎: یعنی چاہیں تو اس شوہر کی زوجیت میں رہیں جن سے غلامی میں نکاح ہوا تھا، اور چاہیں تو ان کی زوجیت میں نہ رہیں۔ ۲؎: صحیح واقعہ یہ ہے کہ وہ اس وقت غلام تھے، اسی لیے تو بریرہ رضی اللہ عنہا کو اختیار دیا گیا، اگر وہ آزاد ہوتے تو بریرہ رضی اللہ عنہا کو اختیار دیا ہی نہیں جاتا، :(دیکھئیے حدیث رقم ۲۶۱۵ و ۳۴۷۹ ) اس حدیث کی باب سے مناسبت یہ ہے کہ آپ صلی اللہ علیہ وسلم نے ولاء والی شرط کو باطل قرار دے کر باقی معاملہ :(بریرہ کی بیع کو ) صحیح قرار دیا۔","الألباني: صحيح دون قوله وكان زوجها حرا فإنه شاذ والمحفوظ أنه كان عبدا",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے بریرہ کو (اس کے مالکان سے) خریدا تو اس کے مالکان نے اس کے ولا کی اپنے لیے شرط لگالی۔ میں نے یہ بات نبی اکرم صلی اللہ علیہ وسلم سے ذکر کی تو آپ نے فرمایا: ’’اسے آزاد کر دے۔ ولا اسی کی ہوتی ہے جو پیسے دیتا (غلام کو خریدتا) ہے۔‘‘ حضرت عائشہ رضی اللہ عنہا نے فرمایا: میں نے اسے آزاد کر دیا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے بلایا اور اسے اپنے خاوند کے (پاس رہنے یا نہ رہنے کے) بارے میں اختیار دیا۔ اس نے خاوند سے اپنی جدائی کو پسند کیا۔ اس کا خاوند آزاد تھا۔","f2":"فوائد و مسائل:1۔ اگر کوئی شخص بیع کرتے وقت ایسی شرط لگاتا ہے جو شرعاً درست نہ ہو تو اس صورت میں بیع کرنا درست ہو گا جبکہ وہ شرط جو اخلاف شریعت ہو، باطل ہو گی، لہٰذا اس شرط کو کا لعدم سمجھا جائے گا اور اس کا کوئی لحاظ نہیں ہو گا جیسا کہ سیدہ بریرہ رضی اللہ عنہا کے معاملے میں رسول اللہ صلی اللہ علیہ وسلم نے پوری وضاحت کے ساتھ یہ مسئلہ بیان فرمایا ہے۔ اس حدیث کے بہت سے طرق ہیں اور مختلف روایت میں مختلف الفاظ مذکور ہیں۔ اس کی وجہ یہ ہے کہ حدیث بیان کرنے والے راویوں نے کہیں تفصیلی روایت بیان کی ہے اور کہیں اختصار سے کام لیا ہے اور یہ سب کچھ ضرورت کے مطابق کیا گیا ہے۔ روائہ حدیث کے اس قسم کے تصرف کو تمام محدثین عظام نے من و عن قبول کیا ہے اور حق بھی یہی ہے۔ اس کا فائدہ یہ ہوتا ہے کہ احادیث سے مختلف احکام و مسائل اخذ کرنے میں آسانی ہوتی ہے۔ (لہٰذا یہاں بھی مذکور و حدیث سے علماء نے متعدد مسائل استنباط کیے ہیں جو درج ذیل ہیں۔ مکاتبت جازء ہے۔ مکاتبت اس عہد و پیمان کو کہا جاتا ہے جو مالک اور اس کے غلام یا لونڈی کے درمیان، متعین رقم یک مشت دینا اور اس کی قسطیں کرنا، دونوں طرح جائز ہے۔ لونڈی یا غلام کی مکاتبت کی رقم دوسرا شخص دے سکتا ہے۔ اگر کوئی دوسرا شخص مکاتبت کی طے شدہ رقم ادا کر دے اور لونڈی و غلام کو آزاد کر دے تو وہ آزاد ہو جائیں گے، البتہ اس صورت میں اس لونڈی یا غلام کے دار آزاد رکے مابین، آزاد کرنے والا ہو گا نہ کہ پہلا مالک۔ اس ربط و تعلق کو کہتے ہیں جو آزاد کرنے والے اور آزاد کردہ کے مابین، آزاد کرنے کی وجہ سے ہوتا ہے۔ یہ تعلق نہ تو بیچا جا سکتا ہے اور نہ کسی ہبہ ہی کیا جا سکتا ہے۔ یہ تعلق بالکل اسی طرح کا ہوتا ہے جیسا کہ باپ اور بیٹے کے درمیان والا تعلق ہوتا ہے جو نہ بیچا جا سکتا ہے اور نہ کسی کو ہبہ ہی کیا جا سکتا ہے۔ اس تعلق کا فائدہ یہ ہے کہ اگر آزاد کردہ شخص کے عصبہ اور ذوی الفروض (جن کا حصہ میراث مقر ہے) نہ ہوں تو اس کی تمام جائداد کا مالک آزاد کرنے والا ہوتا ہے۔ اگر کوئی لونڈی یا غلام اپنی مکاتبت کی رقم کی ادائیگی کے لیے دستِ سوال دراز کرے تو یہ سوال کرنا درست ہے اور سلسلے میں اس کی مدد بھی کرنی چاہیے، نیز اس حدیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ مستحق آدمی کا اپنی جائز ضرورت یا ضروریات پوری کرنے کی خاطر سوال کرنا درست ہے۔ اس حدیث مبارکہ سے باہمی مشاورت کی مشروعیت ثابت ہوتی ہے خصوصاً میاں بیوی کی باہمی مشاورت کا اثبات ہوتا ہے، نیز اگر بیوی خاوند سے کسی مسئلے میں مشورہ طلب کرے تو کے لیے ضروری ہے کہ اسے درست مشورہ دے۔ اگر لونڈی یا غلام اپنی مکاتبت کی طے شدہ رقم ادا نہ کر سکتے ہوں تو انھیں بیچا جا سکتا ہے۔ اس ی دلیل رسول اللہ صلی اللہ علیہ وسلم کے الفاظ مبارک ہیں، یعنی اسے خریدو اور آزاد کر دو۔ دیکھیے: اگر میاں بیوی دونوں غلام ہوں تو ان میں سے کسی ایک کو فروخت کیا جا سکتا ہے۔ اور یہ ضروری نہیں کہ دونوں اکٹھے ہی بیچے جائیں۔ اس حدیث بریرہ سے یہ بھی معلوم ہوتا ہے کہ جس لونڈی یا غلام کے پاس مال وغیرہ نہ ہو، اس مکاتبت کرنا، یعنی اسے مکاتب بنایا درست ہے، خواہ اس کے پاس مال کمانے کے وسائل ہوں یا نہ ہوں۔ مکاتب لونڈی یا غلام اس وقت تک آزاد نہیں ہوں گے جب تک مکاتبت کے بابت طے شدہ ساری رقم ادا نہ کردیں۔ جب تک ان کے ذمے ایک در اہم بھی باقی ہے وہ غلام ہی رہیں گے اوسی اصل کے مطابق ان پر دیگر احکام جاری ہوں گے، یعنی نکاح، طلاق اور حدود وغیرہ کے احکام غلاموں والے ہی ان پر لاگو ہوں گے۔ اس حدیث مبارکہ سے یہ مسئلہ بھی ظابت ہوتا ہے کہ شادی شدہ لونڈی کی فروخت اور آزادی نہ طلاق ہو گی اور نہ فسخ نکاح ہی، اس لیے کہ سیدہ بریرہ رضی اللہ عنہ کو بعد ازاں اختیار دیا گیا تھا کہ چاہے تو وہ اپنے خاوند مغیث کے نکاح میں رہے اور چاہے تو اس سے الگ ہوجائے۔ اس اختیار کے بعد انھوں نے اپنے خاوند سے علیحدگی کو اختیار کیا۔ لونڈی سے اس کا مالک جماع کر سکتا ہے، تا ہم اگر وہ کسی کی بیوی ہو تو پھر جائز نہیں، نیز لونڈی کو محض بیچ دینے سے، اس کے ساتھ جماع کرنا حلال نہ ہو گا۔ سیدہ بریرہ کو خاوند کے پاس رہنے یا نہ رہنے کا اختیار دینا اس بات کی صریح دلیل ہے کہ ابھی تک خاوند کے ساتھ ان کا تعلق باقی تھا۔ اگر کوئی تعلق باقی نہ رہتا تو پھر اختیار کس چیز کا تھا؟ اگر بوقت سوال، سائل مجبور نہیں ہے تو سوال کر سکتا ہے، یعنی مستقبل کی منصوبہ بندی کرتے ہوئے وقت ضرورت کے آنے سے پہلے بھی اس ضرورت کی بابت سوال ہو سکتا ہے۔ شادی شدہ عورت سے مدد اور مالی تعاون مانگا جا سکتا ہے جیسا کہ سیدہ بریرہ رضی اللہ عنہا نے سیدہ عائشہ رضی اللہ عنہا سے اپنی مکاتبت کی بابت مالء تعاون مانگا تھااور انھوں نے اس کی درخواست قبول فرمالء تھی اور بریرہ کو خرید کر اسے آزاد کر دیا تھا۔ شادی شدہ خاتون، اپنے مال میں خاوند کی اجازت کے بغیر تصرف کر سکتی ہے بشر طیکہ وہ تصرف کسی جائز ضرورت کی خاطر ہو۔ طلب اجر کی خاطر مال خرچ کرنا بلکہ زائد از ضرورت خرچ کرنا درست ہے جیسا کہ حضرت عائشہ رضی اللہ عنہا نے حضرت بریرہ رضی اللہ عنہا کی مکاتبت کی ساری رقم جو نو قسطوں کی نو سال میں ادائیگی کی صورت میں طے ہوئے تھی، یکمشت ادا کر دی اور انھیں اسی وقت آزاد کر دیا۔ غلام اور لونڈی کے لیے اپنی آزادی کی خاطر محنت اور کوشش کرنا جائز ہے، خواہ اس مقصد کے لیے اسے کسی ایسے شخص سے سوال کرنا پڑے جو اسے خرید کر آزاد بھی کر دے۔ ایسا کرنے سے اس مالک کا اگر چہ نقصان بھی ہوتا ہو تو بھی کوئی حرج نہیں۔ یہ اس لیے کہ شارع صلی اللہ علیہ وسلم نے غلام کی آزادی کو سراہا اور اس عظیم نیکی کا شوق بھی دلایا ہے، اس لیے اس کی ہر ممکن کوشش کرنی چاہیے۔ اگر کوئی شخص لونڈی یا غلام بیچے لیکن یہ شرط لگالے کہ یہ میری خدمت کرتا رہے گا تو یہ شرط باطل ہو گی۔ اگر مکاتب اپنی قسط کی رقم اس مال سے ادا کرے جو اس پر صدقہ کیا گیا ہوتو اس میں کوئی حرج نہیں، مالک کو ایسی رقم قبول کرنے سے تامل نہیں کرنا چاہیے اگر چہ وقت مقررہ سے قبل ہی وہ رقم کی ادائیگی کر رہا ہو۔ مکاتب دراصل غلام ہی ہوتا ہے جب تک کہ وہ تمام رقم ادا نہ کر دے اور غلام پر صدقہ کر نا درست ہے۔ جب صدقہ اصل محل تک پہنچ جائے تو وہ مالدار شخص کے استعمال کے لیے جائز ہو جاتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کو جب یہ معلوم ہوا کہ سیدہ بریرہ رضی اللہ عنہا کے مالک ایسی شرط لگا رہے ہیں جو شرعاً درست نہیں تو آپ نے خطبہ ارشاد فرمایا اور کسی کا نام لیے بغیر مسئلے کی وضاحت فرمائی اور ایسی ہر شرط کو باطل قرار دیا جو قرآن و حدیث کے منافی ہو۔ اس سے معلوم ہوا جب کوئی اہم شرعی معاملہ در پیش ہو تو کھڑے ہو کر خطبہ دینا مشروع ہے۔ جس شخص سے کوئی غیر شرعی اور منکر کام سر زد ہو تو اس صورت میں غلط کام کرنے والے شخص کا نام لیے بغیر ہی اس کی اصلاح کی جائے۔ اس طرح کرنا مستحب اور پسندیدہ عمل ہے نہ کہ کسی کو شرمندہ اور رسوا کرنا۔ اس حدیث سے یہ مسئلہ بھی معلوم ہوتا ہے کہ اجنبی عورتیں کسی شخص کے گھر میں آ سکتی ہیں، خواہ گھر کا مالک مرد اپنے گھر میں موجود ہو یا نہ ہو۔ رسول اللہ صلی اللہ علیہ وسلم کے لیے صدقہ مطلقاً حرام ہے۔ آپ پر نہ صدقہ کیا جا سکتا ہے اور نہ آپ صدقے کا مال کھا ہی سکتے ہیں۔ ہاں، اگر صدقہ کسی مستحق پر کر دیا جائے اور وہ نبی صلی اللہ علیہ وسلم کو بطور ہد یہ پیش کر دے تو یہ درست ہے۔ غنی مالدار شخص کے لیے جائز ہے کہ وہ محتاج و فقیر کا دیا ہوا ہد یہ قبول کر لے، نیز معلوم ہوا کہ صدقے اور ہدیے کا حکم الگ الگ ہے۔ اگر کسی شخص کو اپنے ہاں کسی شخص کے کھانے سے خوشی ہو تو وہ شخص بلا اجازت بھی اس کے گھر کا حکم واضح ہو تا ہو یا اس سے کوئی شبہ رفع ہوتا ہو اس حدیث مبارکہ سے یہ بھی معلوم ہوتا ہے کہ اگر کسی پر تھوڑی چیز صدقہ کی جائے تو اس کو قبول کر لینا چاہیے۔ اس پر ناراضی کا اظہار نہیں کرنا چاہیے۔ اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ مومن کو خوش کرنا مستحب اور پسندیدہ عمل ہے۔ صحیح احادیث کی روشنی میں ایسا کرنا اللہ تعالیٰ کے ہاں محبوب عمل ہے۔ یہ حدیث مبارکہ حضرت بریرہ رضی اللہ عنہا کے حسن ادب پر بھی دلالت کرتی ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی سفارش واضح انداز میں رد نہیں کی بلکہ یہ کہا ہے کہ مجھے اپنے خاوند مغث کی حاجت نہیں۔ سفارش کرنے والے کو یقینا اس کی جائز سفارش کرنے کا اجرو ثواب مل جاتا ہے، خواہ اس کی سفارش قبول ہو یا رد کر دی جائے۔ اس حدیث سے یہ بھی معلوم ہوتا ہے کہ فرطِ محبت انسان کے لیے بڑی آزمائش کا سبب بنتی ہے۔ بسا اوقات اسے بڑی دشواریوں کا سامنا کرنا پڑتا ہے جیسا کہ حضرت بریرہ رضی اللہ عنہا کے خاوند حضرت مغیث رضی اللہ تعالٰی عنہ کی حالت سے اندازہ ہوتا ہے کہ وہ مدینے کی گلیوں میں ان کے پیچھے پیچھے ہوتے تھے،ؤ۔ دو باہم نفرت کرنے والوں کے مابین صلح صفائی کرانا مستحب ہے، خواہ وہ دونوں میاں بیوی ہی ہوں۔ میاں بیوی ہونے کی صورت میں یہ ذمہ داری اور بڑھ جاتی ہے تاکہ بچے والدین کی باہمی نفرت و اختلاف کے اثرات سے محفوظ رہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے حضرت بریرہ کو حضرت مغیث رضی اللہ تعالٰی عنہ کی بابت سفارش کرتے ہوئے یہ بھی فرمایا تھا: وہ تیرے بچے کا باپ ہے۔‘‘ بچے کی نسبت اس کی ماں کی طرف کرنا بھی جائز ہے۔ شوہر دیدہ خاتون کو مجبور نہیں کرنا چاہیے، خواہ وہ آزاد کردہ ہی کیوں نہ ہو۔ نکاح فسخ ہونے کی صورت میں رجوع نہیں ہو سکتا لیکن نیا نکاح ہو سکتا ہے۔ اگر کوئی عورت اپنے خاوند سے نفرت کرتی ہو تو اس کے س پرست کو چاہیے کہ وہ اس عورت کو خاوند کے ساتھ رہنے پر مجبور نہ کرے اور اگر معاملہ اس کے بر عکس ہو کہ عورت اپنے خاوندسے محبت کرتی ہو تو سر پرست اس کے اور اس کے خاوند کے درمیان جدائی اور تفریق نہ ڈالے۔ شارحینِ حدیث نے اس حدیث مبارکہ سے کم و بیش ڈیڑھ سو (۱۵۰) فوائد و مسائل کا استنباط کیا ہے لیکن ہم نے بغرض اختصار مذکورہ بالا فوائد و مسائل ہی پر اکتفا کیا ہے۔ مزید تفصیل کے لیے ملا حظہ فرمایے: اس روایت پر مزید بحث کے لیے دیکھیے، احادیث ۳۴۷۷تا۳۴۸۴۔"}],[4643,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے غلامی سے آزاد کرنے کے لیے بریرہ رضی اللہ عنہا کو خریدنا چاہا، لوگوں نے ان کے ولاء (وراثت) کی شرط لگائی، انہوں نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں خرید کر آزاد کر دو، کیونکہ ولاء (وراثت) کا حق اسی کا ہے جو آزاد کرے\"، اور رسول اللہ صلی اللہ علیہ وسلم کے پاس گوشت لایا گیا تو کہا گیا: یہ تو بریرہ پر کیا گیا صدقہ ہے؟ آپ نے فرمایا: \"یہ ان کے لیے صدقہ ہے اور ہمارے لیے تحفہ (ہدیہ) ہے\"، اور انہیں (بریرہ کو) اختیار دیا گیا (شوہر کے ساتھ رہنے اور نہ رہنے کا)۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ انھوں نے بریرہ کو آزاد کرنے کے لیے اسے خریدنے کا ارادہ کیا لیکن اس کے مالکوں نے اپنے لیے ولا کی شرط لگالی۔ انھوں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو اسے خرید کر آزاد کر دے۔ بلاشبہ ولا اسی کی ہوتی ہے جو (غلام کو) آزاد کرتا ہے۔‘‘ (یہ واقعہ بھی ہوا کہ) رسول اللہ صلی اللہ علیہ وسلم کے پاس گوشت لایا گیا اور بتلایا گیا کہ یہ گوشت بریرہ پر صدقہ کیا گیا ہے (اور اس نے ہمیں بھیجا ہے)۔ آپ نے فرمایا: ’’صدقہ اس کے لیے ہے۔ ہمارے لیے تحفہ ہی ہے۔‘‘ اور اسے (خاوند کے بارے میں) اختیار دیا گیا۔"}],[4644,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا نے لونڈی خریدنا چاہی تاکہ اسے آزاد کریں، تو اس کے گھر والوں (مالکان) نے کہا: ہم اسے آپ سے اس شرط پر بیچیں گے کہ ولاء (حق وراثت) ہمارا ہو گا، عائشہ رضی اللہ عنہا نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"تم اس وجہ سے مت رک جانا، کیونکہ ولاء (وراثت) تو اس کے لیے ہے جو آزاد کرے\"۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ حضرت عائشہ رضی اللہ عنہا نے ایک لونڈی کو خریدنے کا ارادہ کیا۔ ان کا ارادہ اسے آزاد کرنے کا تھا۔ اس لونڈی کے مالکان نے کہا: ہم لونڈی بیچ دیتے ہیں مگر ولا کا حق ہمیں حاصل ہو گا۔ حضرت عائشہ رضی اللہ عنہا نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی تو آپ نے فرمایا: ’’یہ شرط بیع میں رکاوٹ نہیں ہونی چاہیے۔ ولا اسی کو ملتی ہے جو (غلام کو) آزاد کرتا ہے۔‘‘"}],[4645,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تقسیم ہونے سے پہلے مال غنیمت بیچنے، حاملہ عورتوں ۱؎ کے ساتھ بچہ کی پیدائش سے پہلے جماع کرنے اور ہر دانت والے درندے کے گوشت (کھانے) سے منع فرمایا۔\n§وضاحت\n۱؎: مال غنیمت میں ملی ہوئی لونڈیاں مراد ہیں، اگر وہ حاملہ ہوں تو ان کو پانے والے مجاہد ان کے بچہ جننے کے بعد ہی ان سے مباشرت کر سکتے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مال غنیمت کی تقسیم سے پہلے اس کا سواد کرنے سے منع فرمایا۔ اور (اسی طرح نئی خریدی ہوئی) حاملہ لونڈیوں کے ساتھ جماع کرنے سے منع فرمایا حتی کہ وہ اپنے پیٹ کا بچہ جن دیں، نیز آپ نے ہر کچلی والے درندے کا گوشت کھانے سے منع فرمایا۔","f2":"فوائد و مسائل: 1۔’’مالِ غنیمت کی تقسم‘‘جاہلیت میں رواج تھا کہ جنگ میں حصہ لینے والا شخص کسی دوسرے شخص سے کہتا کہ مجھے مالِ غنیمت میں سے جو حصہ ملے گا، میں تجھے اتنے میں فروخت کرتا ہوں، حالانکہ نہ وہ ابھی تک اپنے حصے کا مالک بنا ہوتا تھا اور نہ یہ علم ہی ہوتا تھا کہ اس کے حصے میں کیا آئے گا۔ ظاہر ہے کہ شریعت مجہول اور غیر مملوک چیز کی فروخت کی اجازت قطعاً نہیں دیتی۔ ’’حاملہ لونڈی‘‘ یعنی جس لونڈی کو اس کے سابقہ خاوند یا مالک سے حمل ٹھہر چکا ہو۔ وہ جنگ میں کسی ہاتھ لگ جائے یا کوئی شخص اسے خردیلے تو جب تک بچہ پیدا نہیں ہو جاتا، نئے مالک کے لیے اس سے جماع کرنا حرام ہے کیونکہ وہ حمل کسی اور شخص کا ہے۔ اس کو اس میں دخل اندازی کا حق نہیں۔ ’’کچلی نو کیلے دانت کو کہتے ہیں جو درمیان والے چار دانتوں کے دونوں اطراف ایک ایک ہوتا ہے۔ یہاں اس سے مراد شکاری جانور ہے جسے ہم درندہ کہتے ہیں کیونکہ درندے میں یہ دانت لازماً ہوتے ہیں جبکہ غیر شکاری میں یہ دانت نہیں ہوتے۔ شکاری جانور کی حرمت کی وجہ پیچھے گزر چکی ہے۔"}],[4646,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"شفعہ کا حق ہر چیز میں ہے، زمین ہو یا کوئی احاطہٰ (باغ وغیرہ)، کسی حصہ دار کے لیے جائز نہیں کہ اپنے دوسرے حصہ دار کی اجازت کے بغیر اپنا حصہ بیچے، اگر اس نے بیچ دیا تو وہ (دوسرا حصہ دار) اس کا زیادہ حقدار ہو گا یہاں تک کہ وہ خود اس کی اجازت دیدے\"۔\n§وضاحت\n۱؎: «شفعہ»: زمین، باغ گھر وغیرہ میں ایسی ساجھے داری کو کہتے ہیں جس میں کسی فریق کا حصہ متعین نہ ہو کہ ہمارا حصہ یہاں سے یہاں تک ہے اور دوسرے کا حصہ یہاں سے یہاں تک ہے بس مطلق ملکیت میں سب کی ساجھے داری ہو، ایسا ساجھے دار اگر اپنا حصہ بیچنا چاہتا ہے تو دوسرے شریک کو پہلے بتائے، اگر وہ اسی قیمت پر لینے پر راضی ہو جائے تو اسی کا حق ہے، اگر جازت دیدے تب دوسرے سے بیچنا جائز ہو گا، اور اگر اس کی اجازت کے بغیر بیچ دیا تو وہ اس بیع کو قاضی منسوخ کرا سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’شفعہ ہر مشترکہ چیز میں ہو سکتا ہے۔ وہ گھر ہو یا باغ (اور کھیت)۔ کسی ایک شریک کو جائز نہیں (مشترکہ چیز میں اپنا حصہ) فروخت کرے حتی کہ اپنے شریک (ساتھی یا ساتھیوں) کو مطلع کرے۔ اگر وہ بلا اطلاع فروخت کر دے تو شریک اس کو لینے کا حق دار ہو گا الا یہ کہ اسے اطلاع کرنے کے بعد بیچے۔‘‘","f2":"فوائد و مسائل:1۔ امام نسائی رحمہ اللہ نے جو باب قائم کیا ہے اس کا مقصد مشترکہ چیز کی بیع کا حکم بیان کرنا ہے۔ اگر کوئی شریک اپنا بیچنا چاہے تو اس کے لیے ضروری ہے کہ دیگر شرکاء سے اس کی اجازت لے۔ اگر کوئی شخص اپنے شریک کی اجازت کے بغیر اپنا حصہ فروخت کر دے تو اس کے شریک کو یہ حق حاصل ہے کہ وہ اس رقم کے عوض جو اس حصے کی لگ چکی ہو یہ حصہ لے لے۔ اس کا حق دیگر تمام لوگوں سے زیادہ اور فائق ہے۔ یہ حدیث مبارکہ شریک کے لیے شفعے کے ثبوت کی صریح دلیل ہے۔ اہل علم کا اس پر اتفاق ہے۔ شریعت مطہرہ کے اصول و ضوابط لوگوں کی خیر خواہی پر مبنی ہیں۔ ایک چیز میں مختلف شرکاء باہمی مشاورت اور دوسرے کو اعتماد میں لینے کے بعد ہی کوئی اقدام کر سکتے ہیں۔ مشترکہ چیز میں بلا مشاورت تصرف کرنے والے کا تصرف معتبر نہیں ہو گا۔ شفعہ سے مراد وہ حق ہے جو ایک شریک کو دوسرے شریک کے حصے پر ہوتا ہے۔ وہ اس طرح کہ اس کی فروخت کی صورت میں وہ اسے خردنے کا دوسروں سے بڑھ کو حق دار ہو گا۔ لیکن یہ حق مشترکہ چیز ہی میں ہے۔ جب کوئی چیز تقسیم ہو جائے، حد بندی ہو جائے، راستے تک الگ الگ ہو جائیں اور کچھ بھی اشتراک سکتا۔ یہ مسئلہ تفصیلاً پیچھے بیان ہو چکا ہے۔ ’’ہر مشترکہ چیز‘‘ بعض فقہاء نے اشیائے منقولہ کو شفعہ سے خارج کیا ہے مگر اس کی کوئی عقلی تو جیہ سمجھ میں نہیں آتی۔ جن وجوہ کی بنا پر شفعہ مشروع کیا گیا ہے وہ منقولہ یا منقولہ جائیداد میں برابر پائی جاتی ہیں۔ اس روایت سے ثابت ہوا کہ مشترکہ چیز ساری کی ساری بھی بیچی جا سکتی ہے اور اس کے کچھ مخصوص حصے بھی، یعنی کوئی شریک صرف اپنا حصہ بھی فروخت کر سکتا ہے، خواہ شریک کو بیچے یا اس کی اجاازت سے کسی اور کو۔ باب کا مقصد بھی یہی ہے۔"}],[4647,"صحابی رسول عمارہ بن خزیمہ کے چچا (خزیمہ بن ثابت رضی اللہ عنہ) بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک اعرابی (دیہاتی) سے ایک گھوڑا خریدا، اور اس سے پیچھے پیچھے آنے کو کہا تاکہ وہ اپنے گھوڑے کی قیمت لے لے، نبی اکرم صلی اللہ علیہ وسلم آگے بڑھ گئے اور اعرابی سست رفتاری سے چلا، لوگ اعرابی سے پوچھنے لگے اور گھوڑا خریدنے کے لیے (بڑھ بڑھ کر قیمتیں لگانے لگے) انہیں یہ معلوم نہ تھا کہ نبی اکرم صلی اللہ علیہ وسلم اسے خرید چکے ہیں، یہاں تک کہ ان میں سے کسی نے اس سے زیادہ قیمت لگا دی جتنے پر آپ نے اس سے خریدا تھا، اعرابی نے نبی اکرم صلی اللہ علیہ وسلم کو پکارا، اگر آپ اس گھوڑے کو خریدیں تو ٹھیک ورنہ میں اسے بیچ دوں، آپ نے جب اس کی پکار سنی تو ٹھہر گئے اور فرمایا: \"کیا میں نے اسے تم سے خریدا نہیں ہے؟\" اس نے کہا: نہیں، اللہ کی قسم! میں نے اسے آپ سے بیچا نہیں ہے، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں اسے تم سے خرید چکا ہوں\" ۱؎، اب لوگ نبی اکرم صلی اللہ علیہ وسلم اور اعرابی کے اردگرد اکٹھا ہونے لگے، دونوں تکرار کر رہے تھے، اعرابی کہنے لگا: \"گواہ لائیے جو گواہی دے کہ میں اسے آپ سے بیچ چکا ہوں\"، خزیمہ بن ثابت رضی اللہ عنہ نے کہا: میں گواہی دیتا ہوں کہ تم اسے بیچ چکے ہو، نبی اکرم صلی اللہ علیہ وسلم خزیمہ رضی اللہ عنہ کی طرف متوجہ ہوئے اور فرمایا: \"تم گواہی کیسے دے رہے ہو\"؟ انہوں نے کہا: آپ کے سچا ہونے پر یقین ہونے کی وجہ سے ۲؎، اللہ کے رسول! تو رسول اللہ صلی اللہ علیہ وسلم نے خزیمہ رضی اللہ عنہ کی گواہی کو دو آدمیوں کی گواہی کے برابر قرار دیا۔\n§وضاحت\n۱؎: اگر اس خرید و فروخت میں گواہوں کا انتظام کیا گیا ہوتا تو وہ دیہاتی آپ صلی اللہ علیہ وسلم سے گواہ طلب ہی نہیں کرتا، اس نے سوچا کہ گواہ نہ ہونے کا فائدہ اٹھا کر زیادہ قیمت پر بیچ دوں گا، پتہ چلا کہ خرید و فروخت میں گواہی کا ضروری نہیں، ورنہ آپ ضرور اس کا انتظام کرتے۔ ۲؎: چونکہ آپ سچے ہیں اس لیے آپ کا یہ دعوی ہی میرے لیے کافی ہے کہ آپ خرید چکے ہیں۔","الألباني: صحيح",{"u2":"حضرت عمارہ بن خزیمہ کے چچا محترم سے روایتک ہے، اور وہ نبی اکرم صلی اللہ علیہ وسلم کے صحابہ تھے، کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک اعرابی سے ایک گھوڑا خرید اور آپ اسے اپنے ساتھ لے گئے تا کہ وہ اپنے گھوڑے کی قیمت وصول کرے۔ نبی اکرم صلی اللہ علیہ وسلم ذرا تیز چل رہے تھے جبکہ وہ اعرابی آہستہ آہستہ آ رہا تھا۔ لوگ اس اعرابی کو روک کر اس سے گھوڑے کا سودا کرنے لگے۔ ان کو یہ علم نہیں تھا کہ نبی اکرم صلی اللہ علیہ وسلم اس گھوڑے کو خرید چکے ہیں، حتی کہ کسی نے اس بھاؤ سے زیادہ بھاؤ لگا دیا جس پر آپ کا سودا طے ہوا تھا۔ اعرابی نے نبی اکرم صلی اللہ علیہ وسلم کو بلندد آواز سے پکار کر کہا: اگر آپ نے یہ گھوڑا خریدنا ہے تو خرید لیں ورنہ میں بیچنے لگا ہوں۔ آپ نے اس ی آواز سنی تو رک گئے اور فرمایا: ’’میں تجھ سے خرید نہیں چکا؟‘‘ اس نے کہا: نہیں اللہ کی قسم! میں نے تو آپ کو یہ نہیں بیچا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’میں تو اسے تجھ سے خرید چکا ہوں۔‘‘ لوگ نبی اکرم صلی اللہ علیہ وسلم اور اعرابی کے ارد گرد جمع ہونے لگے۔ وہ دونوں آپس میں تکرار کر رہے تھے۔ اعرابی کہنے لگا: کوئی گھواہ پیش کریں جو گواہی دے کہ میں نے آپ کو یہ گھوڑا بیچا ہے۔ حضرت خزیمہ بن ثابت رضی اللہ تعالٰی عنہ کہنے لگے: میں گواہی دیتا ہوں کہ تو نے یہ گھوڑا آپ کو بیچا ہے۔ (خیر! وہ معاملہ طے ہو گیا، بعد میں)آپ حضرت خزیمہ رضی اللہ تعالٰی عنہ کی طرف متوجہ ہوئے اور فرمایا: ’’تم کس طرح گواہی دیتے ہو؟‘‘ انھوں نے کہا: اے اللہ کے رسول! آپ کی تصدیق کی بنا پر۔ تب رسول اللہ صلی اللہ علیہ وسلم نے حضرت خزیمہ رضی اللہ تعالٰی عنہ کی گواہی دو آدمیوں کے برابر قرار دے دی۔","f2":"فوائد و مسائل: امام صاحب رحمہ اللہ کامقصد یہ ہے کہ سودے پر یا سودا کرتے وقت گواہ بھی بنائے جائیں تو اس کی گنجائش ہے۔ اس استد الال پر ایک اعتراض وارد ہوتا ہے قرآن کریم میں اللہ تعالیٰ نے ارشاد فرمایا ہے: ’’اور جب تم با ہم خریدہ فروخت کر تو گواہ بنالو۔‘‘ اس جگہ لفظ فرمایا گیا ہے اور یہ امر کا صیغہ ہے جبکہ امر و جواب یہ ہے کہ جب قرینہ صارفہ (امر و جوب سے استحباب وغیرہ کی طرف پھیرنے والی دلیل) آ جائے تو پھر وجوب ختم ہو جاتا ہے جیسا کہ مذکورہ حدیث میں اعرابی اور اور نبی اکرم صلی اللہ علیہ وسلم کے واقعہ سے ظاہر ہوتا ہے۔ گواہ بنانا مستحب ہے، ضروری نہیں، تاہم ادھار سودا ہو یا قرض ہو یا سودے وغیرہ میں نسیان و تنازع کا خدشہ ہو تو گواہ بنانا، تحریر تیار کرنا مئوکد چیز ہے۔ سیدنا خزیمہ رضی اللہ تعالٰی عنہ کی فضیلت و منقبت ثابت ہوتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی گواہی کو دو مسلمان مردوں کو گواہی کے برابر قرار دیا۔ یہ حدیث مبارکہ رسول اللہ صلی اللہ علیہ وسلم کی کسرنفسی اور انتہائی تواضع پر واضح دلیل ہے کہ آپ اپنے دینوی کام کاج بذات خود سر انجام دیتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کی اس تواضع میں امت کے لیے بہت بڑا سبق ہے کہ اپنے کام خود کرنا ہی عظمت اور بڑائی ہے نہ کہ دوسروں سے کرانا اور ان پر انحصار کرنا۔"}],[4648,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"بیچنے اور خریدنے والے میں اختلاف ہو جائے اور ان میں سے کسی کے پاس گواہ نہ ہو تو اس کی بات کا اعتبار ہو گا جو صاحب مال (بیچنے والا) ہے ۱؎ (اور خریدار کو اسی قیمت پر لینا ہو گا) یا پھر دونوں بیع ترک کر دیں\" ۲؎۔\n§وضاحت\n۱؎: مگر قسم کھانے کے بعد، جیسا کہ دیگر روایات سے معلوم ہوتا ہے۔ ۲؎: خریدنے اور بیچنے والے کے درمیان قیمت کی تعیین میں اگر اختلاف ہو جائے اور ان کے درمیان کوئی گواہ موجود نہ ہو تو ایسی صورت میں بیچنے والا قسم کھا کر کہے گا کہ میں نے اس سامان کو اتنے میں نہیں بلکہ اتنے میں بیچا ہے اب خریدار اس کی قسم اور قیمت کی تعیین پر راضی ہے تو بہتر ورنہ بیع کا معاملہ ہی ختم کر دیا جائے گا۔","الألباني: صحيح",{"u2":"۴۶۵۲- حضرت عبد اللہ (بن مسعود رضی اللہ تعالٰی عنہ) بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب خریدنے اور بیچنے والے کا (قیمت وغیرہ میں) اختلاف ہو جائے اور ان میں سے کسی پاس ثبوت نہ ہو تو معتبر بات وہ ہو گی جو سامان کا مالک کہے یا وہ سودا ختم کر دیں۔‘‘","f2":"بھاؤ بتانا بیچنے والے کا حق ہے۔ خریدنے والے کو منظور ہو تو ٹھیک ہے ورنہ بیع نہیں ہو گی۔ اگر اختلاف ہو جائے کہ خریدنے والے کے نزدیک کم قیمت پر سودا طے ہوا ہے اور بیچنے والا کہتا ہے کہ زیادہ قیمت پر سودا طے ہوا تھا، اگر کوئی گواہ موجود ہو تو اس کی گواہی پر فیصلہ ہو گا و گرنہ دریں صورت بائع ہی کی بات معتبر ہو گی۔ اب خریدار کی مرضی ہے کہ اس مطابق سودا لے لے یا پھر بیع فسخ ہو جائے گی۔ یہی قول حدیث کے مطابق ہے۔ اختلاف کے وقت طرفین کی طرف سے حدیث میں جو قسمیں اٹھانے والی بات ہے تو وہ سندًا ضعیف ہے، لہٰذا اس پر عمل کی ضرورت نہیں۔ دیکھیے: ویسے بھی جب تک خرید نے بیچنے والے اپنی مجلس میں موجود ر ہیں، کوئی فریق بھی سودے کی واپسی کا مطالبہ کر سکتا ہے جسے ماننا دوسرے فریق کے لیے لازم ہو گا جیسا کہ پیچھے گزر چکا ہے۔ (دیکھیے، حدیث: ۴۴۶۲)"}],[4649,"عبدالملک بن عبید کہتے ہیں کہ ہم ابوعبیدہ بن عبداللہ بن مسعود کے پاس حاضر ہوئے، ان کے پاس دو آدمی آئے جنہوں نے ایک سامان کی خرید و فروخت کر رکھی تھی، ان میں سے ایک نے کہا: میں نے اسے اتنے اور اتنے میں لیا ہے، دوسرے نے کہا: میں نے اسے اتنے اور اتنے میں بیچا ہے تو ابوعبیدہ نے کہا: ابن مسعود رضی اللہ عنہ کے پاس بھی ایسا ہی مقدمہ آیا تو انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، آپ کے پاس ایسا ہی مقدمہ آیا۔ تو آپ صلی اللہ علیہ وسلم نے بائع کو قسم کھانے کا حکم دیا پھر (فرمایا: خریدار) کو اختیار ہے، چاہے تو اسے لے اور چاہے تو چھوڑ دے۔","الألباني: صحيح",{"u2":"حضرت عبد الملک بن عبید سے روایت ہے کہ ہم حضرت ابو عبید بن عبد اللہ بن مسعود کی مجلس میں حاضر تھے کہ ان کے پاس دو آدمی آئے۔ انھوں نے آپس میں کسی سامان کا سودا کیا تھا۔ ایک کہہ رہا تھا: میں نے اتنے میں لیا۔ دوسرا کہہ رہا تھا: میں نے اتنے کا بیچا۔ حضرت ابو عبیدہ فرمانے لگے: حضرت ابن مسعود رضی اللہ تعالٰی عنہ کے پاس ایسا مسئلہ پیش ہوا تھا تو انھوں نے فرمایا تھا: میں قسم کا مقدمہ لایا گیا۔ آپ نے حکم دیا کہ بیچنے والے سے قسم لی جائے، پھر خریدنے والے کو اختیار ہو گا، چاہے اس بھاؤ میں لے لے یا پھر سودا چھوڑ دے۔"}],[4650,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے ادھار اناج (غلہ) خریدا اور اسے اپنی ایک زرہ بطور رہن دی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک یہودی سے ادھار غلہ خریدا تھا اور بطور ضمانت اپنی زرہ اس کو گروی میں دی تھی۔"}],[4651,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی وفات ہوئی اور آپ کی زرہ ایک یہودی کے پاس گھر والوں کی خاطر تیس صاع جَو کے بدلے رہن (گروی) رکھی ہوئی تھی۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اللہ کو پیارے ہوئے تو آپ کی زرہ ایک یہودی کے پاس گروی رکھی ہوئی تھی کیونکہ آپ نے اس سے اپنے اہل و عیال کے لیے تیس صاع غلہ (جو) ادھار لیے تھے۔","f2":"اس حدیث کی تفصیلی بحث پیچھے گزر چکی ہے۔ دیکھیے: (حدیث: ۴۶۱۴) امام صاحب کا مقصود یہ ہے کہ غیر مسلم لوگوں سے تجارتی روابط رکھے جا سکتے ہیں۔ ان سے لین دین اور سودے کیے جا سکتے ہیں۔ اگرچہ باب میں صرف اہل کتاب کا ذکر ہے مگر مراد سب مسلم وغیر مسلم ہیں۔ اہل کتاب، یہودیوں اور عیسائیوں کو کہا جاتا ہے کیونکہ ان پر آسمانی کتابیں تورات اور انجیل اتاری گئی تھیں۔"}],[4652,"جابر رضی اللہ عنہ کہتے ہیں کہ بنی عذرہ کے ایک شخص نے اپنا ایک غلام بطور مدبر آزاد (یعنی مرنے کے بعد آزاد ہونے کی شرط پر) کر دیا، یہ بات رسول اللہ صلی اللہ علیہ وسلم کو معلوم ہوئی، تو آپ نے فرمایا: \"کیا تمہارے پاس اس کے علاوہ کوئی مال ہے؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"اس غلام کو مجھ سے کون خریدے گا؟\" چنانچہ اسے نعیم بن عبداللہ عدوی رضی اللہ عنہ نے آٹھ سو درہم میں خرید لیا، رسول اللہ صلی اللہ علیہ وسلم ان (دراہم) کو لے کر آئے اور اسے ادا کر دیا، پھر فرمایا: \"اپنی ذات سے شروع کرو اور اس پر صدقہ کرو، پھر کچھ بچ جائے تو وہ تمہارے گھر والوں کا ہے، تمہارے گھر والوں سے بچ جائے تو تمہارے رشتے داروں کے لیے ہے اور اگر تمہارے رشتے داروں سے بھی بچ جائے تو اس طرح اور اس طرح\"، اپنے سامنے، اپنے دائیں اور بائیں اشارہ کرتے ہوئے۔\n§وضاحت\n۱؎: «مدبر»: وہ غلام ہے جس کا مالک اس سے کہے کہ تم میرے مرنے کے بعد آزاد ہو۔ اگر «مدبّر» کرنے والا مالک محتاج ہو جائے تو اس«مدبّر» غلام کو بیچا جا سکتا ہے، جیسا کہ اس حدیث سے ثابت ہوتا ہے، دیگر روایات سے پتہ چلتا ہے کہ وہ آدمی محتاج تھا اور اس پر قرض تھا، امام بخاری اور مؤلف نیز دیگر علماء مطلق طور پر «مدبّر» کے بیچنے کو جائز مانتے ہیں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے مروی ہے کہ بنو عذرہ کے ایک آدمی نے اپنا ایک غلام مدبر کیا۔ یہ بات رسول اللہ صلی اللہ علیہ وسلم کو پہنچی تو آپ نے فرمایا: ’’کیا تیرے پاس اس کے علاوہ کوئی اور مال ہے؟‘‘ اس نے کہا: نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کون شخص مجھ سے یہ (غلام) خریدتا ہے؟‘‘ حضرت نعیم بن عبد اللہ عدوی رضی اللہ تعالٰی عنہ نے اسے آٹھ سو در ہم مٰں خرید لیا۔ وہ رقم رسول اللہ صلی اللہ علیہ وسلم کے پاس لے کر آئے۔ آپ نے وہ اس کے سپرد کر دی اور فرمایا: ’’پہلے اپنے آپ پر خرچ کر، پھر اگر کچھ بچ جائے تو وہ تیرے اہل و عیال کے لیے ہے، پھر اگر تیرے اہل و عیال سے کچھ بچ جائے تو تیرے رشتہ داروں کا حق ہے، البتہ اگر تیرے رشتہ داروں سے بھی کچھ بچ جائے تو ایسے ایسے اور ایسے، یعنی اپنے آگے، اپنے دائیں اور اپنے بائیں (اللہ کے راستے میں خرچ کر)۔‘‘","f2":"1۔ اس مسئلے میں اہل علم کا اختلاف ہے کہ مدبر کو بیچا جا سکتا ہے یا نہیں؟ امام شافع رحمہ اللہ اور اہل الحدیث (محدثین کرام کی جماعت) اس کو جائز قرار دیتے ہیں۔ مذکورہ احادیث اس کی واضح دلیل ہیں۔ یہ حدیث مبارکہ اس بات پر دلالت کرتی ہے کہ نفلی صدقے میں افضل یہ ہے کہ اسے خیر و بھلائی کی مختلف نواع میں تقسیم کیا جائے، یعنی جو مصلحت کا تقاضا ہو، ادھر ہی خرچ کرنا چاہیے۔ کوئی خاص جہت معین نہیں کرنی چاہیے کہ صدقہ کرنے والا یہ کہے میں صرف فلاں مد ہی میں خرچ کروں گا اس کے علاوہ کہیں بھی خرچ نہیں کروں گا، خواہ اس کی ضرورت ہی ہو۔ امیر و حاکم کو یہ اختیار حاصل ہے کہ لوگون کے ذمے سے قرض چکانے کے لیے ان کے مال فروخت کر کے ان کے قرض ادا کر دے اور باقی رقم ان کی دیگر ضرور یات پوری کرنے کے لیے ان کے سپرد کر دے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے کیا تھا۔ شرعی حکمران کو یہ حق حاصل ہے کہ وہ کم عقل اور نادان شخص پر پابندی لگا دے کہ وہ اپنا مال فروخت نہیں کر سکتا، نیز اسے یہ اختیار بھی حاصل کہ ایسے شخص کے اپے مال میں کیے ہوئے تصرف کو کا لعدم کر دے۔"}],[4653,"جابر رضی اللہ عنہ سے روایت ہے کہ ابومذکور نامی انصاری نے ایک یعقوب نامی غلام کو مدبر کے طور پر آزاد کیا، اس کے پاس اس کے علاوہ کوئی اور مال نہ تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے بلا کر فرمایا: \"اسے کون خریدے گا؟\" اسے نعیم ابن عبداللہ رضی اللہ عنہ نے آٹھ سو درہم میں خریدا، آپ نے اس (انصاری) کو وہ(درہم) دے کر فرمایا: \"تم میں جب کوئی محتاج ہو تو پہلے اپنی ذات سے شروع کرے، پھر اگر بچے تو اپنے گھر والوں پر، پھر اگر بچے تو اپنے رشتے داروں پر، اور اگر پھر بھی بچ رہے تو ادھر ادھر\" (یعنی دوسرے فقراء پر خرچ کرے)۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے کہ انصار میں سے ایک آدمی نے جسے ابو مذکور کہا جاتا تھا، اپنا ایک غلام مدبر کیا۔ اس غلام کا نام یعقوب تھا۔ اس آدمی کے پاس کوئی اور مال نہیں تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کو بلایا اور فرمایا: ’’اس غلام کو کون خریدے گا؟‘‘ حضرت نعیم بن عبد اللہ رضی اللہ تعالٰی عنہ نے اسے آٹھ سو در ہم میں خرید لیا۔ آپ نے وہ در ہم اس کے سپرد کیے اور فرمایا: ’’جب تم میں سے کوئی آدمی فقیر ہو تو اپنے بال بچوں پر خرچ کرے۔ مزید اگر کچھ بچے تو اپنے قریبی اور رشتہ داروں پر خرچ کرے، پھر اگر بچ جائے تو پھر ادھر ادھر (فی سبیل اللہ صدقہ کرے)۔‘‘"}],[4654,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مدبر (غلام) کو بیچ دیا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک مدبر بیچ دیا تھا۔"}],[4655,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ بریرہ رضی اللہ عنہا عائشہ رضی اللہ عنہا کے پاس آئیں، اپنی کتابت کے سلسلے میں ان کی مدد چاہتی تھیں، ان سے عائشہ رضی اللہ عنہا نے کہا: تم اپنے گھر والوں (مالکوں) کے پاس لوٹ جاؤ، اب اگر وہ پسند کریں کہ میں تمہاری مکاتبت (کی رقم) ادا کر دوں اور تمہارا ولاء (حق وراثت) میرے لیے ہو گا تو میں ادا کر دوں گی، بریرہ رضی اللہ عنہا نے اس کا تذکرہ اپنے گھر والوں سے کیا تو انہوں نے انکار کیا اور کہا: اگر وہ تمہارے ساتھ بھلائی کرنا چاہتی ہیں تو کریں البتہ تمہارا ولاء (ترکہ) ہمارے لیے ہو گا، عائشہ رضی اللہ عنہا نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"انہیں خرید لو ۲؎ اور آزاد کر دو\"۔ ولاء (وراثت) تو اسی کا ہے جس نے آزاد کیا، پھر آپ نے فرمایا: \"کیا حال ہے ان لوگوں کا جو ایسی شرطیں لگاتے ہیں جو اللہ کی کتاب (قرآن) میں نہیں ہیں، لہٰذا اگر کوئی ایسی شرط لگائے جو اللہ کی کتاب (قرآن) میں نہ ہو، تو وہ پوری نہ ہو گی گرچہ سو شرطیں لگائی گئی ہوں، اللہ کی شرط قبول کرنے اور اعتماد کرنے کے لائق ہے\"۔\n§وضاحت\n۱؎: «مکاتب»: وہ غلام ہے جس کا مالک اس سے کہے کہ اگر تم اتنی اتنی رقم اتنی مدت میں، یا جب بھی کما کر ادا کر دے تو تم آزاد ہو۔ ۲؎: بریرہ رضی اللہ عنہا نے چونکہ ابھی تک «مکاتبت» :(معاہدہ آزادی ) کی کوئی قسط ادا نہیں کی تھی، اس لیے عائشہ رضی اللہ عنہا نے کل رقم ادا کر کے انہیں خرید لیا، یہی باب سے مناسبت ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ بریرہ عائشہ کے پاس آئی۔ وہ اپنی کتابت کے بارے میں ان سے کچھ مدد کی طلب گار تھی۔ حضرت عائشہ رضی اللہ عنہا نے اسے فرمایا: اپنے مالکوں کے پاس جا، اگر وہ راضی ہوں کہ میں تیری طرف سے کتابت کی پوری رقم یکمشت ادا کر دوں اور تو میری طرف سے آزاد ہو جائے تو میں تیار ہوں۔ بریرہ نے یہ بات اپنے مالکان سے ذکر کی تو انھوں نے انکار کر دیا۔ اور کہنے لگے: اگر وہ تجھے آزاد کر کے ثواب حاصل کرنا چاہتی ہیں تو بڑی خوشی سے کرین لیکن ولا کا حق ہمارا ہو گا۔ حضرت عائشہ رضی اللہ عنہا نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خرید کر آزاد کر دے۔ ولا کا حق اسی کا ہے جو آزاد کرے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے (خطبے میں) فرمایا: ’’ان لوگوں کا کیا حال ہے جو ایسی شرطیں لگاتے ہیں جو کتاب اللہ کی رو سے جائز نہیں۔ جو شخص بھی ایسی شرط لگاتا ہے، جو کتاب اللہ کی رو سے جائز نہیں، وہ شرط اس کے حق میں نہیں مانی جائے گی، خواہ سو دفعہ شرط لگا لے۔ اللہ تعالیٰ کی نافذ کردہ شرط (حکم) زیادہ معتبر اور منصبوط ہے۔‘‘","f2":"1۔ یہ روایت اور اس پر بحث تفصیلاً گزر چکی ہے۔ (دیکھیے حدیث: ۳۴۸۱) یہاں بحث طلب مسئلہ یہ ہے کہ کیا مکاتب غلام بیچا جا سکتا ہے؟ مکاتب اس غلام کو کہتے ہیںجس سے اس کا مالک طے کر لے کہ تو اتنی رقم اتنی قسطوں میں (یا یکمشت) اتنے عرصے تک ادا کر دے تو تجھے آزادی مل جائے گی۔ ظاہر ہے یہ ایک معاہدہ ہے جسے توڑا نہیں جا سکتا الا یہ کہ وہ غلام راضی ہو جسے اس معاہدے کا مفاد ہے۔ اور واضح بات ہے کہ وہ تبھی راضی ہو گا اگر اسے فوری آزادی کا یقین دلا دیا جائے۔ ایسی صورت میں جب معاہدے سے بڑھ کر غلام کو مفاد حاصل ہو رہا ہو اور دونوں فریق راضی ہوں تو اسے فوری آزادی کے لیے بیچنے میں کوئی حرج نہیں جیسا کہ مندرجہ بالا روایات میں ذکر ہے۔ ہاں، مالکان اپنے مفاد کی خاطر اس کی مرضی کے بغیر اسے کسی دوسرے کو نہیں بیچ سکتے کیونکہ یہ غدر اور وعدہ خلافی ہے جس میں حکومت مدا خلت کر سکتی ہے۔ اس روایت کے مفصل فوائد و مسائل کے لیے ملا حظہ فرما ئیں فوائد و مسائل، حدیث: ۴۶۴۶"}],[4656,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میرے پاس بریرہ رضی اللہ عنہا نے آ کر کہا: عائشہ! میں نے نو اوقیہ کے بدلے اپنے گھر والوں (مالکوں) سے مکاتبت کر لی ہے کہ ہر سال ایک اوقیہ دوں گی تو آپ میری مدد کریں۔ (اس وقت) انہوں نے اپنی کتابت میں سے کچھ بھی ادا نہ کیا تھا۔ ان سے عائشہ رضی اللہ عنہا نے کہا اور ان میں دلچسپی لے رہی تھیں: جاؤ اپنے لوگوں (مالکوں) کے پاس اگر وہ پسند کریں کہ میں انہیں یہ رقم ادا کر دوں اور تمہارا ولاء (حق وراثت) میرے لیے ہو گا تو میں ایسا کروں، بریرہ رضی اللہ عنہا اپنے لوگوں (مالکوں) کے پاس گئیں اور ان کے سامنے یہ بات پیش کی، تو انہوں نے انکار کیا اور کہا: اگر وہ تمہارے ساتھ بھلائی کرنا چاہتی ہیں تو کریں لیکن وہ ولاء (ترکہ) ہمارا ہو گا، اس کا ذکر عائشہ نے رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"یہ چیز تمہیں ان سے مانع نہ رکھے، خریدو اور آزاد کر دو، ولاء (ترکہ) تو اسی کا ہے جس نے آزاد کیا\"، چنانچہ انہوں نے ایسا ہی کیا، رسول اللہ صلی اللہ علیہ وسلم لوگوں میں کھڑے ہوئے اور حمد و ثنا کے بعد فرمایا:\"امابعد، لوگوں کا کیا حال ہے، وہ ایسی شرطیں لگاتے ہیں جو اللہ کی کتاب (قرآن) میں نہیں ہوتیں، جو ایسی شرط لگائے گا جو اللہ کی کتاب (قرآن) میں نہیں ہے تو وہ باطل ہے گرچہ وہ سو شرطیں ہوں، اللہ تعالی کا فیصلہ زیادہ قابل قبول اور اللہ تعالی کی شرط زیادہ لائق بھروسہ ہے، ولاء (حق وراثت) اسی کا ہے جس نے آزاد کیا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ بریرہ میرے پاس آئی اور کہنے لگی: اے عائشہ! میں نے اپنے مالکان سے نو اوقیے پر آزادی کا معاہدہ کیا ہے۔ ہر سال ایک اوقیہ دینا ہو گا، لہٰذا میری مدد فرمایئے۔ ابھی تک اس نے اپنی کتابت کی رقم سے کچھ بھی ادا نہیں کیا تھا۔ حضرت عائشہ رضی اللہ عنہا نے چاہا کہ وہ اسے آزاد کر دیں، اس لیے انھوں نے اس کہا: اپنے مالکوں کے پاس جاؤ اگر وہ پسند کریں میں ان کو یہ (ان کی رقم) یکمشت ادا کردوں اور تیری ولا لوں گی تو میں ایسا کرنے کو تیار ہوں۔ حضرت بریرہ رضی اللہ عنہا اپنے مالکوں کے پاس گئی اور یہ بات انھیں پیش کی۔ انھوں نے انکار کیا اور کہنے لگے: اگر وہ ثواب حاصل کرنے کے لیے تجھے آزاد کرنا چاہیں تو کر دیں لیکن ولا ہماری ہو گی۔ حضرت عائشہ رضی اللہ عنہا نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی۔ آپ نے فرمایا: ’’ان اس بات کی وجہ انکار نہ کرنا بلکہ خرید کر آزاد کر دو۔ ولا اسی کی ہوتی ہے جو آزاد کرے۔‘‘ انھوں نے ایسے ہی کیا۔ پھر رسول اللہ صلی اللہ علیہ وسلم لوگوں میں خطبہ دینے کے لیے کھڑے ہوئے۔ آپ نے اللہ تعالیٰ کی حمد و ثنا بیان فرمائی، پھر فرمایا: ’’اما بعد! کیا وجہ ہے کہ لوگ سودے کرتے وقت ایسی شرطیں لگاتے ہیں جو کتاب اللہ کی رو سے جائز نہیں؟ جو شخص بھی ایسی شرط لگائے گا جو کتاب اللہ کی رو سے جائز نہ ہو تو وہ باطل اور مردود ہو گی اگرچہ سو دفعہ لگائی گئی ہو۔ اللہ تعالیٰ کا فیصلہ ہی صحیح ہے اور اللہ تعالیٰ کی جائز کردہ شرطیں ہی معتبر ہیں۔ یاد رکھو! ولا اسی کی ہو گی جو آزاد کرے گا۔‘‘","f2":"اس کی تفصیل کے لیے دیکھیے، فوائد و مسائل، حدیث: ۴۶۴۶."}],[4657,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ولاء (وراثت) کو بیچنے اور اسے ہبہ کرنے سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: اگر کسی نے غلام کو آزاد کیا تو اس غلام کے مرنے پر اگر اس کے عصبہ وارث نہ ہوں، تو آزاد کرنے والا عصبہ ہو گا، اور عصبہ والا ترکے کا حقدار ہو گا اسی کو ولاء کہتے ہیں۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن عمر رضی اللہ عنہا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ولا کے بیچنے اور ہبہ کرنے سے منع فرمایا ہے۔","f2":"’’ولا‘‘ وہ تعلق اور رشتہ ہے جو آزاد کرنے والے اور آزاد شدہ غلام کے درمیان آزادی سے قائم ہوتا ہے۔ ظاہر ہے رشتے اور تعلقات نہ بیچے جا سکتے ہیں نہ کسی عطیتاً دیے جا سکتے ہیں۔ بسا اوقات اس تعلق کی وجہ سے آزاد کرنے والے کو آزاد شدہ غلام کی وراثت بھی حاصل ہو جاتی ہے، اس لیے جاہل لوگ یہ شتہ بیچ دیا کرتے تھے کہ وارثت تو سنبھال لینا، مجھے اتنی رقم فوراً دے دے۔ شریعت نے اس زر پرستی سے منع فرمایا کہ رشتے بیچنے یا تحفتاً دینے کی چیز نہیں۔"}],[4658,"عمرو بن دینار کہتے ہیں کہ طاؤس اس بات کو ناپسند کرتے تھے کہ آدمی اپنی زمین سونے، چاندی کے بدلے کرائے پر اٹھائے۔ البتہ (پیداوار کی) تہائی یا چوتھائی کے بدلے بٹائی پر دینے میں کوئی حرج نہیں سمجھتے تھے۔ تو ان سے مجاہد نے کہا: رافع بن خدیج کے لڑکے (اسید) کے پاس جاؤ اور ان سے ان کی حدیث سنو، انہوں نے کہا: اللہ کی قسم اگر مجھے معلوم ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے روکا ہے تو میں ایسا نہ کرتا لیکن مجھ سے ایک ایسے شخص نے بیان کیا جو ان سے بڑا عالم ہے یعنی ابن عباس رضی اللہ عنہما نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے تو بس اتنا فرمایا تھا: \"تم میں سے کوئی اپنے بھائی کو اپنی زمین دیدے یہ اس سے بہتر ہے کہ وہ اس پر ایک متعین محصول (لگان) وصول کرے\"۔ اس حدیث میں عطاء کے سلسلہ میں اختلاف واقع ہے، عبدالملک بن میسرہ کہتے ہیں: «عن عطاء، عن رافع»(عطا سے روایت ہے وہ رافع سے روایت کرتے ہیں) (جیسا کہ حدیث رقم ۳۹۰۳ میں ہے) اور یہ بات اوپر کی روایت میں گزر چکی ہے اور عبدالملک بن ابی سلیمان («عن رافع» کے بجائے) «عن عطاء عن جابر» کہتے ہیں (ان کی روایت آگے آ رہی ہے)۔\nعبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ولاء (حق وراثت) بیچنے اور اسے ہبہ کرنے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ولا کو بیچنے اور ہبہ کرنے سے منع فرمایا ہے۔"}],[4659,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی کوئی زمین ہو تو وہ خود اس میں کھیتی کرے اور اگر وہ اس سے عاجز ہو تو اپنے کسی مسلمان بھائی کو دیدے اور اس سے اس میں بٹائی پر کھیتی نہ کرائے\"۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ولاء بیچنے اور اسے ہبہ کرنے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ولا کو بیچنے اور ہبہ کرنے سے منع فرمایا ہے۔"}],[4660,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی کوئی زمین ہو تو وہ خود اس میں کھیتی کرے یا اسے اپنے بھائی کو دیدے اور اسے بٹائی پر نہ دے\"۔ عبدالرحمٰن بن عمرو اوزاعی نے عبدالملک بن ابی سلیمان کی متابعت کی ہے (یہ متابعت آگے آ رہی ہے)۔\nجابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پانی بیچنے سے منع فرمایا ہے ۱؎۔\n§وضاحت\n۱؎: مراد نہر اور چشمے وغیرہ کا پانی جو کسی کی ذاتی ملکیت میں نہ ہو، اور اگر پانی پر کسی کا کسی طرح کا خرچ آیا ہو تو ایسے پانی کا بیچنا منع نہیں ہے، جیسے راستوں میں ٹھنڈا پانی، مینرل واٹر وغیرہ بیچنا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پانی بیچنے سے منع فرمایا ہے۔","f2":"1۔ پانی، انسانوں اور جانوروں کی بنیادی ضرورت ہے۔ اس کے بغیر بقا ممکن نہیں، پھر اللہ تعالیٰ نے وافر پانی مفت مہیا فرمایا ہے۔ اگر پانی اپنی پیاس سے زائد ہو تو پیاسے کو مفت دینا فرض ہے اور اگر اپنے وضو اور غسل وغیرہ کی ضروریات سے زائد ہو تو غسل اور وضو وغیرہ کے لیے مفت دینا ضروری ہے۔ ہاں، کارو باری مقاصد کے لیے پانی مطلوب ہے تو بیچا جا سکتا ہے، مثلاً: زرعی ضروریات یا برف وغیرہ بنانے کے لیے۔ اسی طرح اگر پانی کے حصول میں اخراجات کرنے پڑتے ہوں یا محنت کرنا پڑتی ہو، مثلاً: دور سے ٹھا کر یا لاد کر لایا گیا ہو وغیرہ تو بھی اپنے اخراجات اور محنت کے مطابق معاوضہ وصول کیا جا سکتا ہے۔ یہ پانی کی قیمت نہیں ہوتی بلکہ اخراجات اور محنت کا معاوضہ ہوتا ہے اور اس میں کوئی حرج بھی نہیں، البتہ کسی پیاسے انسان یا حیوان کو پانی پینے سے نہیں روکا جا سکتا۔"}],[4661,"ایاس بن عمر (یا ابن عبد) رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو پانی بیچنے سے منع فرماتے ہوئے سنا۔ قتیبہ کہتے ہیں: مجھے ان (سفیان) سے ایک مرتبہ ابومنہال کے بعض کلمات سمجھ میں نہیں آئے جیسا میں نے چاہا۔","الألباني: صحيح",{"u2":"حضرت ایاس بن عمر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو پانی کی فروخت سے منع فرماتے سنا۔\nاستادقتیبہ نے کہا کہ میں اس (استاد سفیان بن عیینہ) سے ابو منہال کے بعض حراف اس طرح نہیں سمجھ سکا جس طرح میں چاہتا تھا۔","f2":"اس کا مطلب یہ ہے کہ کو جب سفیان نے حدیث کی تو اسے ابو منہال کی حدیث کے بعض الفاظ کی اس طرح سمجھ نہ آ سکی جس طرح وہ چاہتے تھے شاید وہاں بھیڑ وغیرہ ہو اور یہ استاد سے کچھ فاصلے پر ہوں یا کوئی اور وجہ بھی ہو سکتی ہے۔واللہ اعلم"}],[4662,"ایاس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فاضل پانی کے بیچنے سے منع فرمایا ہے، وہط کے نگراں نے وہط کا فاضل پانی بیچا تو عبداللہ بن عمرو رضی اللہ عنہما نے اسے ناپسند کیا۔","الألباني: صحيح",{"u2":"حضرت ایاس سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زائد پانی بیچنے سے منع فرمایا ہے۔ (حضرت عمر و بن عاص رضی اللہ تعالٰی عنہ کی زمین) وہط کے ناظم نے وہط کا زائد پانی بیچا تو حضرت عبد اللہ بن عمر و رضی اللہ عنہ نے اسے ناپسند فرمایا۔","f2":"مفت ملنے والے پانی مثلاً: بارش، چشمے اور نہر کا پانی اگر کسی زرعی زمین سے زائد ہوتو اس کو بیچنا منع ہے۔ ہاں، جو پانی خریدا گیا ہو، مثلاً: ٹیوب ویل کا پانی یا جانوروں پر لاد کر لایا گیا پانی، ایسے پانی کو اسی حساب سے بیچ دیا جائے تو کوئی حرج نہیں۔ یہ اس پانی کی بیع نہیں ہوتی بلکہ یہ دراصل ٹیوب ویل یا جانوروں کے اخراجات ہوتے ہیں یا انسانی محنت کا معاوضہ ہوتا ہے مگر عرفاً اسے پانی کی قیمت کہہ دیا جاتا ہے۔ اس میں کوئی حرج نہیں۔ یہ ایک بستی یا ایک زمین کا نام ہے جو حضرت عبد اللہ بن عمرو کو ورثتاً ملی تھی۔"}],[4663,"ابومنہال نے خبر دی ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے صحابی ایاس بن عبد رضی اللہ عنہ نے کہا: فاضل پانی مت بیچو، اس لیے کہ نبی اکرم صلی اللہ علیہ وسلم نے فاضل پانی بیچنے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"صحابی رسول حضرت ایاس بن عبد رضی اللہ تعالٰی عنہ بیان کرتے ہیں زائد پانی نہ بیچو کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے فالتو پانی بیچنے سے منع فرمایا ہے۔","f2":"جس طرح اللہ تعالیٰ نے پانی مفت اور و افر مہیا فرمایا ہے، اسی طرح ہمیں بھی چاہیے کہ اپنی ضرورت سے زائد پانی لوگوں کو مفت لے جانے دیں، خصوصاً کسی پیاسے انسان یا حیوان کو کسی صورت بھی پانی استعمال کرنے سے روکنا جائز نہیں۔"}],[4664,"ابن وعلہ مصری سے روایت ہے کہ انہوں نے ابن عباس رضی اللہ عنہما سے انگور کے رس کے بارے میں سوال کیا تو انہوں نے کہا: ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کو شراب کی مشکیں تحفہ میں دیں تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"کیا تمہیں علم ہوا ہے کہ اللہ تعالی نے اسے حرام قرار دیا ہے؟\" پھر اس نے کانا پھوسی کی - میں اس بات کو اچھی طرح نہیں سمجھ سکا تو میں نے اس کی بغل کے آدمی سے پوچھا تو نبی اکرم صلی اللہ علیہ وسلم نے اس سے کہا: \"تم نے اس سے کیا کانا پھوسی کی؟\"، وہ بولا: میں نے اس سے کہا کہ وہ اسے بیچ دے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس ذات نے اس کا پینا حرام کیا ہے، اس نے اس کا بیچنا بھی حرام کیا ہے\"، تو اس آدمی نے دونوں مشکوں کا منہ کھول دیا یہاں تک کہ جو کچھ اس میں تھا بہہ گیا۔","الألباني: صحيح",{"u2":"حضرت ابن وعلہ مصری سے روایت ہے کہ انھوں نے حضرت ابن عباس رضی اللہ عنہ سے انگور کے نچوڑے ہوئے جوس کے بارے میں پوچھا تو حضرت ابن عباس رضی اللہ عنہ نے فرمایا: ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں اونٹ پر لدی ہوئی شراب کے دو مشکیزے بطور تحفہ پیش کیے۔ نبی اکرم صلی اللہ علیہ وسلم نے اسے فرمایا: ’’تجھے علم نہیں کہ اللہ عزو جل نے شراب حرام فرما دی ہے؟‘‘ اس سے آستہ سے کچھ کہا اور جو کچھ اس نے کہا، اسے میں اس طرح نہیں سمجھ سکا جس طرح میں چاہتا تھا، لہٰذا میں نے (اس کی بابت حاضرین میں سے کسی سے) نبی اکرم صلی اللہ علیہ وسلم نے اس پوچھا: ’’تو نے آہستہ سے اس کو کیا کہا ہے؟‘‘ اس نے کہا: میں اسے شراب فروخت کرنے کہا ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جس ذات نے شراب کو حرام قرار دیا ہے، اس نے اس کو بیچنا بھی حرام کیا ہے۔‘‘ اس شخص نے دونوں مشکیزوں کے منہ کھول دیے حتی کہ جو کچھ شراب اس میں تھی بہہ گئی۔","f2":"1۔ شراب کی خرید و فروخت شرعی طور پر نا جائش اور حرام ہے۔ اس بات پر مات مسلمہ کا اجماع ہے۔ معلوم ہوا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں جو اس نے تحفتاً شراب پیش کی تھی، وہ سابقہ اباحت کی بنا پر ہی تھی۔اسے اس کی حرمت کا علم نہیں تھا اسی لیے آپ صلی اللہ علیہ وسلم نے اس کا مئواخذہ نہیں فرمایا۔ معلوم ہوا جو انسان کسی حرام کا ارتکاب کرے یا حرام چیز کو حلال سمجھتا ہو، اور اس حوالے سے اسے واقعی شرعی حکم معلوم نہ ہو تو اسے باخبر کرنا ضروری ہو گا۔ ایسی معصیت اور گناہ کے ارتکاب پر وہ قابل عتاب و عقاب بھی نہیں ہو گا۔ یہ حدیث مبارکہ دلیل ہے کہ ایک انسان دوسرے انسان سے اس بعض رازوں کی بابت پوچھ سکتا ہے۔ بعد ازاں اگر ان رازوں کو پوشیدہ رکھنا ضروری ہو تو پوشیدہ رکھے ورنہ انھین ذکر اور ظاہر بھی کیا جا سکتا ہے۔ حضرت ابن عباس رضی اللہ عنہ کے جواب کا مطلب ہے کہ انگور کا جوس شراب بنانے کے لیے ہی استعمال ہوتا ہے۔ اس کا کوئی اور مصرف نہیں، لہٰذا انگور کا جوس نکالنا اور شراب بنانے والوں کو بیچنا منع ہے، البتہ اگر وہ جوس کسی حلال مصرف میں استعمال ہو سکے تو اسے بنانا اور بیچنا جائز ہے بشر طیکہ یقین ہو کہ اس سے شراب نہیں بنائی جائے گی۔ شریعت کا یہ اصول ہے کہ جو چیز حرام ہے، اس کا کاروبار، خرید فروخت، لین دین ہر چیز منع ہے، مثلاً: شراب، مردار، بت، خنز وغیرہ، البتہ جو چیز کسی پر حرام ہے، کسی کے لیے حلا تو اس کا کاروبار، خرید و فروخت، لین دین سب جائز ہے حتی کہ جس شخص پر حرام ہے، وہ بھی اس کا لین دین کر سکتا ہے، جیسے سونا، ریشم وغیرہ۔ یہ مردوں کے لیے پہننا حرام ہے، رکھنا حرام نہیں، لہٰذا ان کا کاروبار اور لین مرد بھی کر سکتے ہیں۔ اس کا تحفہ بھی دیا جا سکتا ہے۔"}],[4665,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب سود سے متعلق آیات نازل ہوئیں تو رسول اللہ صلی اللہ علیہ وسلم منبر پر کھڑے ہوئے اور لوگوں کے سامنے ان کی تلاوت کی، پھر شراب کی تجارت حرام قرار دی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہ فرماتی ہیں کہ جب سود کی (حرمت کی) آیاتر اتریں تو رسول اللہ صلی اللہ علیہ وسلم منبر پر تشریف فرما ہوئے اور یہ آیات لوگوں کو پڑھ کر سنائیں، پھر آپ نے شراب کی تجارت کو بھی حرام قرار دیا۔","f2":"1۔اس حدیث مبارکہ سے شراب کی حرمت کے ساتھ ساتھ اس کی تجارت کی حرمت بھی واضح ہوتی ہے۔ مزید بر آں یہ کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے سود کے ساتھ ملا کر بیان کیا جس کے بارے میں اللہ تعالیٰ کا ارشاد گرامی ہے: ’’اگر اللہ لوگ سودی لین دین سے باز نہ آؤ گے تو پھر اللہ اور اس کے رسول طرف سے ایک (بڑی خوفناک) جنگ کا اعلان سن لو۔‘‘ سود کی حرمت کا شراب کی تجارت کی حرمت سے تعلق یہ ہے کہ یہ دونوں حرام کا ذریعہ بنتے ہیں۔ سود ظلم کا ذریعہ بن سکتا ہے۔ اسی طرح شراب کی تجارت شراب پینے کا سبب بن سکتی ہے کیونکہ جب تک شراب کی تیاری، خرید و فروخت، لین دین مکمل طور پر ممنوع قرار نہیں دیا جاتا، اس وقت تک معاشرہ شراب پینے کی لعنت سے نہیں بچ سکتا۔ آپ نے سود کی حرمت سے یہ نتیجہ اخذ فرمایا کہ حرام کا ذریعہ بھی حرام ہوتا ہے، لہٰذا آپ نے شراب کی تجارت حرام فرما دی۔"}],[4666,"ابومسعود عقبہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت، زانیہ عورت کی کمائی اور نجومی کی آمدنی سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود عقبہ بن عمرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت،زاینہ کی اجرت اور (غیب کی خبریں بتانے والے) کاہن کی شیرینی اور کمائی (نذر و نیاز) سے منع فرمایا ہے۔","f2":"تفصیلی بحث کے لیے ملا حظہ فرمائیں، فوائد حدیث: ۴۲۹۵۔"}],[4667,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کئی چیزوں کو حرام قرار دیا، کتے کی قیمت کو (بھی)۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بہت سی چیزوں کو حرام قرار دیتے ہوئے فرمایا: ’’اور کتے کی قیمت (بھی حرام ہے)۔‘‘"}],[4668,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے، اور بلی کی قیمت سے منع فرمایا سوائے شکاری کتے کے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ حدیث منکر ہے ۱؎۔\n§وضاحت\n۱؎: کیونکہ ثقہ راویوں کی روایت میں «إلا کلب صید» کا ذکر نہیں ہے، اس کے رواۃ \" حجاج \" مختلط، اور \" ابوالزبیر \" مدلس ہیں، اور روایت عنعنہ سے کی ہے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے اور بلی کی قیمت سے منع فرمایا، البتہ شکاری کتے کو مستثنیٰ فرمایا۔\nابوعبدالرحمن (امام نسائی رحمہ اللہ) فرماتے ہیں کہ یہ حدیث منکر ہے۔","f2":"امام نسائی رحمہ اللہ نے فرمایا: یہ حدیث منکر ہے، یعنی صحیح احادیث کے خلاف ہے، نیز اس کے راوی بھی ضعیف ہیں۔ سنن ترمذی میں بھی حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے اسی مفہوم کی حدیث آتی ہے لیکن وہ بھی ضعیف ہے۔ محدثین نے اس استثنا کو صحیح قرار نہیں دیا۔ ویسے بھی اگر یہ استثنا رکھ لیا جائے تو کتے کی قیمت کی حرمت ختم ہو جائے گی کیونکہ ہر کتا شکاری بن سکتا ہے۔ گویا اس استثنا کو تسلیم کرنے سے اصل حکم بالکلیہ ختم ہو جائے گا، لہٰذا یہ استثنا عقلاً بھی صحیح نہیں۔ تفصیلی بحث پیچھے حدیث نمبر ۴۲۹۷ میں گزر چکی ہے۔"}],[4669,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ انہوں نے فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا اور آپ مکہ میں تھے: اللہ اور اس کے رسول نے شراب، مردار، سور اور بتوں کے بیچنے سے منع فرمایا۔ عرض کیا گیا: اللہ کے رسول! مردے کی چربی کے بارے میں کیا خیال ہے؟ اس سے تو کشتیاں چکنی کی جاتی ہیں، کھالوں میں استعمال ہوتا ہے اور لوگ اس سے چراغ جلاتے ہیں، آپ نے فرمایا: \"نہیں، وہ حرام ہے\"، اس وقت آپ نے یہ بھی فرمایا: \"اللہ تعالی یہودیوں کو ہلاک و برباد کرے، اللہ تعالی نے ان پر چربی حرام کی تھی، انہوں نے اسے پگھلایا، پھر بیچا اور اس کی قیمت کھائی\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی فتح مکہ کے سال مکہ مکرمہ میں فرماتے سنا: ’’اللہ تعالیٰ اور اس کے رسول(صلی اللہ علیہ وسلم) نے شراب، مردار، خنزیر اور بتوں کی خرید و فروخت حرام قرار دی ہے۔‘‘ آپ سے پوچھا گیا: اللہ کے رسول! ذرا مردار کی چربی کے بارے میں ارشاد فرمائیں؟ اس کے ساتھ کشتیاں لیپ کی جاتی ہیں۔ اور یہ چمڑے کو ملی جاتی ہے اور لوگ اس سے روشنی حاصل کرتے ہیں۔ آپ نے فرمایا: ’’نہیں، یہ حرام ہے۔‘‘ اس وقت رسول اللہ صلی اللہ علیہ وسلم نے یہ بھی فرمایا: ’’اللہ تعالیٰ یہودیوں پر لعنت فرمائے کہ اللہ عزوجل نے جب ان پر چربی حرام فرما دی تو انھوں نے اسے پگھلا کر بیچا اور اس کی قیمت کھائی۔‘‘","f2":"فوائد ومسائل: (۱) مقصد یہ ہے کہ جیسے خنزیر حرام ہے ایسے ہی اس کی خرید و فروخت بھی حرام ہے، نیز اگر کوئی فرد یا قوم کسی ممنوع اور حرام چیز کو حلال کرنے کی خاطر کسی قسم کا حیلہ بہانہ تراشے اور پھر اس پر عمل پیرا ہو جائے تو اللہ تعالیٰ کے ہاں وہ لعنتی ہے کیونکہ اس طرح وہ ان یہودیوں کی راہ پر چلا ہے جنھوں نے اللہ عزوجل کی حرمتوں کو پامال کرنے کے لیے حیلے بہانے گھڑ لیے تھے اور اللہ کے ہاں مغضوب علیہ اور لعنتی قرار پائے تھے۔ (۲) خنزیر مطلقاً حرام ہے۔ اس کی کوئی چیز بھی استعمال نہیں ہو سکتی، لہٰذا اس کی بیع ہر حال میں حرام ہے۔ اس کی کوئی چیز بھی فروخت نہیں ہو سکتی حتی کہ اس کی کھال بھی دباغت سے پاک نہیں ہو سکتی۔ (مزید دیکھیے، حدیث: ۴۲۶۱)"}],[4670,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اونٹ سے جفتی کرانے پر اجرت لینے سے، پانی بیچنے اور زمین کو بٹائی پر دینے سے ۱؎ یعنی آدمی اپنی زمین اور پانی کو بیچ دے تو ان سب سے آپ صلی اللہ علیہ وسلم نے منع فرمایا۔\n§وضاحت\n۱؎: اس بٹائی سے مراد وہ معاملہ ہے جس میں زمین والا زمین کے کسی خاص حصے کی پیداوار لینا چاہے، کیونکہ آدھے پر بٹائی کا معاملہ آپ صلی اللہ علیہ وسلم نے خود اہل خیبر سے کیا تھا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اونٹ کی جفتی، (زائد) پانی اور کاشت کاری کے لیے زمین کی فروخت سے منع فرمایا کہ ایک آدمی اپنی زمین اور اس کا پانی کسی کو بیچ دے۔ نبی اکرم صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے۔","f2":"فوائد ومسائل: (۱) ’’اونٹ کی جفتی کی بیع‘‘ سے مراد جفتی کا معاوضہ ہے کیونکہ یہ اس کا فطری تقاضا ہے، لہٰذا نہ اجرت جائز ہے اور نہ نر کو روکنا جائز ہے۔ ہاں، جفتی کے بعد کوئی شخص خوشی سے نر کے مالک کو کچھ دے دے تو اس کی گنجائش ہے۔ ایسی چیز بھی کود کھانے کی بجائے نر کے مصرف ہی میں لے آئے۔ بعض فقہاء کے نزدیک یہ نہی تنزیہی ہے۔ (۲) ’’زمین کی فروخت‘‘ سے مراد بٹائی یا ٹھیکہ ہے۔ اس کی تفصیلی بحث پیچھے حدیث نمبر ۳۸۹۳ میں گزر چکی ہے۔ بٹائی اور ٹھیکے میں اگر کوئی ظالمانہ شرط نہ ہو تو ان میں کوئی حرج نہیں۔"}],[4671,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نر کو مادہ پر چھوڑنے کی اجرت لینے سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نر کی جفتی کی اجرت سے منع فرمایا ہے"}],[4672,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ بنی کلاب کی شاخ بنی صعق کا ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے نر کو مادہ پر چھوڑنے کی اجرت لینے کے بارے میں سوال کیا، تو آپ نے اسے اس سے منع فرمایا، اس نے کہا: ہمیں تو اس کی وجہ سے تحفے ملتے ہیں۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ نے فرمایا: بنو کلاب کے ایک (چھوٹے) قبیلے بنو صعق کا ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے نر کی جفتی کی اجرت کے بارے میں پوچھا۔ آپ نے اسے اس سے منع فرمایا۔ اس نے کہا: بسا اوقات اس (جفتی) پر ہم خوشی سے کچھ دے دیتے ہیں (تو آپ نے اس کی رخصت فرما دی)۔"}],[4673,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے پچھنا لگانے کی کمائی سے، کتے کی قیمت سے اور نر کو مادہ پر چھوڑنے کی اجرت سے منع فرمایا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سنگی لگانے والے کی کمائی، کتے کی فروخت اور نر کی جفتی کی اجرت سے منع فرمایا ہے۔"}],[4674,"طارق کہتے ہیں کہ میں نے سعید بن مسیب کو کہتے سنا: تین قسم کی زمینوں کے علاوہ میں کھیتی درست نہیں: وہ زمین جو کسی کی اپنی ملکیت ہو، یا وہ اسے عطیہ دی گئی ہو، یا وہ زمین جسے آدمی سونے چاندی کے بدلے کرائے پر لی ہو۔ زہری نے صرف پہلی بات سعید بن سعید سے مرسلاً روایت کی۔\nابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نر کو مادہ پر چھوڑنے کی اجرت سے منع فرمایا۔","الألباني: صحيح مقطوع",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نر کی جفتی کی اجرت سے منع فرمایا۔"}],[4675,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کتے کی قیمت سے اور نر کو مادہ پر چھوڑنے کی اجرت سے منع فرمایا۔","الألباني: صحيح لغيره",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نر کی جفتی کی اجرت سے منع فرمایا۔"}],[4676,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص (سامان خریدنے کے بعد) مفلس ہو گیا، پھر بیچنے والے کو اس کے پاس اپنا مال بعینہ ملا تو دوسروں کی بہ نسبت وہ اس مال کا زیادہ حقدار ہے\" ۱؎۔\n§وضاحت\n۱؎: اس باب کی احادیث کی روشنی میں علماء نے کچھ شرائط کے ساتھ ایسے شخص کو اپنے سامان کا زیادہ حقدار ٹھہرایا ہے جو یہ سامان کسی ایسے شخص کے پاس بعینہٖ پائے جس کا دیوالیہ ہو گیا ہو، وہ شرائط یہ ہیں: :(الف ) سامان خریدار کے پاس بعینہٖ موجود ہو۔ :(ب ) پایا جانے والا سامان اس کے قرض کی ادائیگی کے لیے کافی نہ ہو۔ :(ج ) سامان کی قیمت میں سے کچھ بھی نہ لیا گیا ہو۔ :(د ) کوئی ایسی رکاوٹ حائل نہ ہو جس سے وہ سامان لوٹایا ہی نہ جا سکے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص مفلس قرار دیا جائے، پھر کوئی شخص اپنا سامان اس کے پاس بعینہٖ پا لے تو وہ اس سامان کا دوسروں سے زیادہ حق دار ہے۔‘‘","f2":"مفلس وہ شخص ہوتا ہے جس پر اتنا قرض چڑھ جائے کہ وہ ادائیگی کے قابل نہ ہو۔ ہماری زبان میں اسے دیوالیہ کہتے ہیں۔ اس شخص پر یہ پابندی لگا دی جاتی ہے کہ تو اپنے مال میں تصرف نہیں کر سکتا بلکہ اس کا مال فروخت کر کے جو کچھ میسر ہوتا ہے، وہ قرض خواہوں میں تقسیم کر دیا جاتا ہے۔ اور باقی قرض اسے معاف ہو جاتا ہے، مثلاً: اگر اس پر دس ہزار روپے قرض ہیں مگر اس کا مال کل پانچ ہزار روپے میں فروخت ہو تو اس کے قرض خواہوں میں ان کے قرض کا نصف نصف دیا جائے گا اور باقی معاف ہوگا۔ اس حدیث میں ایک استثنا کیا گیا ہے کہ اگر کوئی کسی کی کوئی چیز بعینہٖ اس کے پاس ہو، خواہ وہ اسے عاریتاً دی گئی ہو یا بیچی گئی ہو اور اس نے ابھی تک اس کی قیمت میں سے کچھ بھی ادا نہ کیا ہو تو وہ چیز پوری کی پوری اس کے مالک کو دے دی جائے گی۔ وہ چیز فروخت کر کے تمام قرض خواہوں میں تقسیم نہیں ہو گی، البتہ اگر اس نے اس کی قیمت میں سے کچھ ادا کر دیا ہو تو پھر وہ باقی سامان کے ساتھ فروخت ہوگی۔ اور اس کے مالک کو بھی دوسرے قرض خواہوں کے ساتھ ملا کر ان کے تناسب سے ادائیگی کی جائے گی، مثلاً: اگر ان کو ان کے قرض کا نصف دیا جا رہا ہو تو اسے بھی اس کے قرض کا نصف ہی دیا جائے گا۔ جمہور اہل علما س استثنا کو مانتے ہیں مگر احناف نے استثنا کو تسلیم نہیں کیا کیونکہ اس سے دوسرے قرض خواہوں کی حق تلفی ہوگی کہ ان کو تو ان کے قرض کا مثلاً نصف ملا لیکن یہ شخص اپنی چیز پوری کی پوری لے گیا۔ ان کے نزدیک یہ چیز بھی باقی سامان کے ساتھ فروخت ہوگی اور اس شخص کو بھی دوسرے قرض خواہوں کے تناسب سے ادائیگی کی جائے گی۔ احناف کی یہ بات درست نہیں کیونکہ اس شخص کو دوسرے قرض خواہوں پر یہ فضیلت حاصل ہے کہ اس کی چیز بعینہٖ مفلس کے پاس موجود ہے جبکہ دیگر لوگوں کا مال تلف ہو چکا ہے۔ اب یہ قطعاً درست نہیں کہ مالک کے ہوتے ہوئے اس کی چیز بیچ دی جائے اور اسے نہ دی جائے۔ یوں سمجھئے کہ وہ بیع کالعدم ہوگئی کیونکہ ابھی کوئی ادائیگی نہیں ہوئی، لہٰذا چیز اصل مالک کو واپس مل گئی۔"}],[4677,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایسے شخص کے بارے میں جو مفلس ہو جائے اور اس کے پاس بعینہ کسی کا سامان موجود ہو اور وہ اسے پہچان لے فرمایا: \"اس سامان کا مستحق وہ ہے جس نے اسے اس کے ہاتھ بیچا تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مفلس آدمی کے بارے میں فرمایا: ’’جب اس کے پاس کسی کا سامان بعینہٖ پایا جائے اور اس میں کوئی شک نہ رہے تو وہ اس کے اصل مالک کو دے دیا جائے گا جس نے اسے بیچا تھا۔ (بشرطیکہ قیمت سے کچھ ادائیگی نہ ہوئی ہو)۔‘‘"}],[4678,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک شخص کے پھلوں پر جو اس نے خریدے تھے آفت آ گئی اور اس کا قرض بہت زیادہ ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر صدقہ کرو\"، چنانچہ لوگوں نے اس پر صدقہ کیا، اس کی مقدار اتنی نہ ہو سکی کہ اس کا قرض پورا ہوتا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو تمہیں ملے لے لو، اس کے علاوہ تمہارے لیے کچھ نہیں\" ۱؎۔\n§وضاحت\n۱؎: جب حاکم موجودہ مال کو قرض خواہوں کے مابین بقدر حصہ تقسیم کر دے پھر بھی اس شخص کے ذمہ قرض خواہوں کا قرض باقی رہ جائے تو ایسی صورت میں قرض خواہ اسے تنگ کرنے، قید کرنے اور قرض کی ادائیگی پر مزید اصرار کرنے کے بجائے اسے مال کی فراہمی تک مہلت دے۔ حدیث کا مفہوم یہی ہے اور قرآن کی اس آیت «وإن کان ذوعسرۃ فنظرۃ إلی میسرۃ» کے مطابق بھی ہے کیونکہ کسی کے مفلس ہو جانے سے قرض خواہوں کے حقوق ضائع نہیں ہوتے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ایک آدمی کے ان پھلوں کا نقصان ہوگیا جو اس نے خریدے تھے۔ اس طرح اس پر بہت قرض چڑھ گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس پر صدقہ کرو۔‘‘ لوگوں نے اس پر صدقہ کیا مگر اس سے اس کا پورا قرض ادا نہیں ہو سکتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے (اس کے قرض خواہوں سے) فرمایا: ’’جو ملتا ہے لے لو، تمھیں اور کچھ نہیں ملے گا۔‘‘","f2":"کسی کے مفلس ہونے کا فیصلہ حکومت کرتی ہے۔ افلاس کے احکام اس وقت لاگو ہوں گے جب حکومنت اس کے افلاس کا باقاعدہ اعلان کر دے۔ کوئی شخص بذات خود اپنے آپ کو مفلس قرار نہیں دے سکتا۔"}],[4679,"اسید بن حضیر بن سماک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ کیا کہ اگر کوئی کسی شخص کے ہاتھ میں اپنی (چوری کی ہوئی) چیز پائے اور اس پر چوری کا الزام نہ ہو تو چاہے تو اتنی قیمت ادا کر کے اس سے لے لے جتنے میں اس نے اسے خریدا ہے اور چاہے تو چور کا پیچھا کرے، یہی فیصلہ ابوبکر اور عمر رضی اللہ عنہما نے (بھی) کیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت اسید بن حضیر بن سماک رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ جب کوئی آدمی اپنی چیز ایسے شخص کے ہاتھ میں پائے جو مشکوک اور متہم نہ ہو، اگر وہ چاہے تو اس سے وہ چیز اتنی رقم دے کر جتنی کی اس نے خریدی ہے لے لے۔ اور اگر چاہے تو (اصل) چور کا پیچھا کرے۔ حضرت ابوبکر اور حضرت عمر رضی اللہ عنہ نے بھی یہی فیصلہ فرمایا۔","f2":"(۱) ’’اپنی چیز‘‘ جو چوری ہو چکی تھی یا کسی نے چھین لی تھی۔‘‘ (۲)’’مشکوک اور متہم نہ ہو‘‘ گویا وہ خود چور نہیں بلکہ اس نے چور سے خریدی ہے۔ ضروری نہیں کہ اسے اس کے چور ہونے کا علم ہو، البتہ اگر کسی کے چور ہونے کا علم ہو تو پھر اس سے کوئی چیز خریدنا ناجائز ہے کیونکہ غالب گمان یہی ہے کہ وہ چیز چوری کی ہو گی۔ (۳)’’اتنی رقم دے کر جتنی کی اس نے خریدی ہے لے لے۔‘‘ یہ نیکی کی تلقین ہے ورنہ وہ اس چیز کا اصل مالک ہے لیکن چونکہ دوسرے شخص کا بھی کوئی قصور نہیں، لہٰذا اس کی رقم بھی ضائع نہیں ہونی چاہیے۔ اگر اس کا قصور ثابت ہو، مثلاً: اس نے جاننے کے باوجود کہ یہ چیز چوری کی ہے، اس چیز کو خریدا ہو تو اسے تاوان ڈالا جا سکتا ہے۔ آئندہ حدیث میں اس حدیث کے خلاف حکم ہے کہ اصل مالک اپنی چیز لے جائے گا۔ خریدار بیچنے والے سے اپنی رقم وصول کرے گا۔ یہ روایت اصول کے مطابق ہے مگر خلفائے راشدین کا فیصلہ پہلی حدیث پر ہے۔ گویا حالات کے مطابق فیصلہ کیا جائے گا۔ اگر دوسرا شخص بالکل بے گناہ ہو تو پہلی حدیث کے مطابق فیصلہ کیا جائے گا، مثلاً: بیچنے والے کا علم نہیں ہو سکتا یا وہ بھاگ گیا ہو یا وہ مر چکا ہو وغیرہ۔ اور اگر اس کا بھی قصور ہو، مثلاً: اسے علم تھا کہ یہ چیز چوری کی ہے یا بیچنے والے سے رقم مل سکتی ہے تو پھر دوسری حدیث کے مطابق فیصلہ ہوگا۔ گویا دونوں احادیث کا محل ومقام الگ الگ ہے۔ واللہ اعلم! (۴)یہ اہم بات یاد رکھنی چاہیے کہ اس حدیث کی سند میں امام نسائی رحمہ اللہ سے سہو ہوا ہے کہ انھوں نے صحابی کا نام ’’اسید بن حضیر بن سماک‘‘ بیان کیا ہے جو کہ بالکل غلط ہے۔ درست نام ہے: ’’اسید بن ظہیر‘‘ اس غلطی پر امام مزی رحمہ اللہ نے اپنی معروف تالیف ’’تہذیب الکمال‘‘ میں تنبیہ فرمائی ہے۔ دیکھیے: (تھذیب الکمال: ۲: ۲۶۴، ۲۶۵) یہ صحابی اسید بن ظہیر ہی ہیں کیونکہ حضرت اسید بن حفیر رضی اللہ تعالٰی عنہ تو حضرت عمر بن خطاب رضی اللہ تعالٰی عنہ کے دور خلافت میں فوت ہوئے ہیں اور ان کی نماز جنازہ بھی امیرالمومنین حضرت عمر رضی اللہ تعالٰی عنہ نے پڑھائی ہے۔ ذرا سوچئے کہ جو شخص حضرت عمر رضی اللہ تعالٰی عنہ کے زمانہ مبارک میں فوت ہو جائے، بھلا وہ سیدنا معاویہ رضی اللہ تعالٰی عنہ کا زمانہ کس طرح پا سکتا ہے؟"}],[4680,"بنی حارثہ کے ایک فرد اسید بن حضیر انصاری رضی اللہ عنہ کہتے ہیں کہ وہ یمامہ کے گورنر تھے، مروان نے ان کو لکھا کہ معاویہ رضی اللہ عنہ نے انہیں لکھا ہے کہ جس کی کوئی چیز چوری ہو جائے تو وہی اس کا زیادہ حقدار ہے، جہاں بھی اسے پائے، پھر مروان نے یہ بات مجھے لکھی تو میں نے مروان کو لکھا کہ نبی اکرم صلی اللہ علیہ وسلم نے فیصلہ کیا کہ چوری کرنے والے سے ایک ایسے شخص نے کوئی چیز خریدی جس پر چوری کا الزام نہ ہو تو اس چیز کے مالک کو اختیار دیا جائے گا چاہے تو وہ اس کی قیمت دے کر اسے لے لے (جتنی قیمت اس نے چور کو دی ہے) اور اگر چاہے تو چور کا پیچھا کرے، یہی فیصلہ ابوبکر، عمر اور عثمان رضی اللہ عنہم نے کیا، پھر مروان نے میری یہ تحریر معاویہ رضی اللہ عنہ کے پاس بھیجی، معاویہ رضی اللہ عنہ نے مروان کو لکھا: تمہیں اور اسید کو حق نہیں کہ تم دونوں مجھ پر حکم چلاؤ بلکہ تمہارا والی اور امیر ہونے کی وجہ سے میں تم کو حکم کروں گا، لہٰذا جو حکم میں نے تمہیں دیا ہے، اس پر عمل کرو، مروان نے معاویہ رضی اللہ عنہ کی تحریر (میرے پاس) بھیجی تو میں نے کہا: جب تک میں حاکم ہوں ان کے حکم کے مطابق فیصلہ نہیں کروں گا ۱؎۔\n§وضاحت\n۱؎: یعنی: فیصلہ رسول اللہ صلی اللہ علیہ وسلم کے حکم کے مطابق کروں گا، معاویہ رضی اللہ عنہ کے حکم کے مطابق نہیں۔","الألباني: صحيح",{"u2":"حضرت اسید بن ظہیر انصاری رضی اللہ تعالٰی عنہ جو کہ یمامہ کے گورنر تھے، نے بتایا کہ مجھے حضرت مروان نے لکھا کہ حضرت معاویہ رضی اللہ تعالٰی عنہ نے مجھے لکھا ہے کہ جس آدمی کی کوئی چیز چوری ہو جائے، وہ جہاں بھی اسے پا لے اس کا زیادہ حق دار ہے۔ میں نے ان کو لکھا کہ نبی اکرم صلی اللہ علیہ وسلم نے فیصلہ فرمایا تھا کہ جب چور سے خریدنے والا شخص مشکوک اور متہم نہ ہو تو اس چیز کے مالک کو اختیار ہے، چاہے تو قیمت دے کر وہ چیز لے لے اور چاہے تو چور کا پیچھا کرے، پھر حضرت ابوبکر، عمر اور عثمان رضی اللہ عنہم نے بھی یہی فیصلہ دیا۔ حضرت مروان نے میرا خط حضرت معاویہ رضی اللہ تعالٰی عنہ کی خدمت میں بھیج دیا۔ حضرت معاویہ رضی اللہ تعالٰی عنہ نے مروان کو لکھا کہ تم یا اسید مجھ پر فیصلہ نافذ نہیں کر سکتے بلکہ میں اپنی حدود خلافت میں فیصلہ نافذ کرنے کا مجاز ہوں، اس لیے تم میرے حکم کے مطابق فیصلہ کرو۔ حضرت مروان نے حضرت معاویہ رضی اللہ تعالٰی عنہ کا خط مجھے بھیج دیا۔ میں نے کہا: جب تک میں گورنر ہوں میں تو حضرت معاویہ رضی اللہ تعالٰی عنہ کے اس قول کے مطابق فیصلہ نہیں کروں گا۔","f2":"(۱) حضرت اسید اور حضرت معاویہ رضی اللہ تعالٰی عنہ دونوں صحابی ہیں۔ حضرت مروان نبی صلی اللہ علیہ وسلم کے دور میں موجود تھے، مسلمان تھے مگر اپنے والد کے ساتھ طائف میں رہتے تھے۔ حضرت عثمان رضی اللہ تعالٰی عنہ کے دور میں مدینہ منورہ آئے، لہٰذا وہ تابعی ہیں۔ علم سے خاص شغف تھا۔ راویان حدیث میں شمار ہے۔ معتبر اور ثقہ راوی ہیں۔ تمام حدیث کی کتابوں میں ان کی روایات موجود ہیں۔ رحمہ اللہ (۲) حضرت معاویہ رضی اللہ تعالٰی عنہ ان حدیث سے واقف نہین تھے جو حضرت اسید رضی اللہ تعالٰی عنہ نے بیان فرمائی، اس لیے ان کو یقین نہ آیا، البتہ انھیں تحقیق کرنا چاہیے تھی۔ اسی لیے حضرت اسید رضی اللہ تعالٰی عنہ ان سے ناراض ہوئے اور ان کے قول کے مطابق فیصلہ کرنے سے انکار فرمایا۔ اگرچہ وہ خلیفہ تھے اور حضرت اسید اور حضرت مروان گونر تھے مگر شریعت کی ہدایات کے ہوتے ہوئے کسی کی ہدایت واجب الاتباع نہیں۔ مومن اسی کردار کا حامل ہوتا ہے۔"}],[4681,"سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی اپنے سامان کا زیادہ حقدار ہے جب کسی کے پاس پائے، اور بیچنے والا جس کے پاس چیز پائی گئی ہے وہ اپنے بیچنے والے کا پیچھا کرے\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آدمی اپنے عین (اصل) مال کا زیادہ حق دار ہے جب (اور جہاں) بھی اسے پا لے۔ خریدنے والا خود بیچنے والے کا پیچھا کرے۔‘‘","f2":"عین، یعنی اصل مال سے مراد وہ مال ہے جو چوری ہوگیا یا کسی نے چھین لیا، پھر وہ کسی اور آدمی کے پاس مل گیا۔ اس حدیث کی رو سے اصل مالک اپنا مالک دوسرے شخص سے بلا معاوضہ لے لے گا۔ دوسرا شخص اپنی رقم کا مطالبہ بیچنے والے سے کرے گا نہ کہ اصل مالک سے کیونکہ وہ تو اس کا ذاتی مال ہے۔ (تفصیلی بحث کے لیے دیکھیے، حدیث: ۴۶۸۳)"}],[4682,"سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی عورت کی شادی دو ولیوں نے کر دی تو وہ ان میں پہلے شوہر کی ہو گی، اور جس نے کوئی چیز دو آدمیوں سے بیچی تو وہ چیز ان میں سے پہلے کی ہو گی۔\n§وضاحت\n۱؎: پہلے ولی کے ذریعے ہونے والے نکاح کا اعتبار ہو گا۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس عورت کا نکاح دو ولی (الگ الگ) جگہ کر دیں، وہ اس خاوند کی ہوگی جس سے پہلے نکاح ہوا۔ اور اگر کسی شخص نے ایک چیز دو آدمیوں کو (الگ الگ) بیچ دی تو وہ چیز اس کو ملے گی جس کو پہلے بیچی گئی ہے۔‘‘","f2":"(۱) ایک دفعہ بیچنے کے بعد پہلا مالک، مالک نہیں رہتا بلکہ خریدنے والا مالک بن جاتا ہے۔ اگر پہلا مالک دوسری جگہ بیچے گا تو کسی کی چیز بیچے گا، لہٰذا دوسری بیع معتبر نہیں ہوگی۔ اسی طرح چور یا ڈاکو کسی کی چیز بیچے تو وہ بیع معتبر نہیں ہوگی بلکہ وہ چیز اصل مالک کی رہے گی۔ اگر اصل مالک چیز تک پہنچ جائے تو وہ اسے بلا معاوضہ لے سکتا ہے۔ (دیکھیے فوائد ومسائل، حدیث: ۴۶۸۳) نکاح والے مسئلے میں بھی جب ایک ولی نے نکاح کر دیا تو دوسرے ولی کا تصرف غیر معتبر ہے۔ (۲) اس حدیث کی عنوان کے ساتھ مناسبت نہیں ہے۔ مؤلف رحمہ اللہ کو اس حدیث کے لیے مستقل طور پر الگ ترجمۃ الباب قائم کرنا چاہیے تھا جس کے ساتھ حدیث کی مطابقت واضح ہوتی ہے۔"}],[4683,"عبداللہ بن ابی ربیعہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے مجھ سے چالیس ہزار قرض لیے، پھر آپ کے پاس مال آیا تو آپ نے مجھے ادا کر دئیے، اور فرمایا: \"اللہ تعالی تمہیں، تمہارے گھر والوں اور تمہارے مال میں برکت عطا فرمائے، قرض کا بدلہ تو شکریہ ادا کرنا اور قرض ادا کرنا ہی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ابو ربیعہ رضی اللہ تعالٰی عنہ نے فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم نے مجھ سے چالیس ہزار (درہم) قرض لیے، پھر آپ کے پاس کہیں سے مال آیا۔ آپ نے میرا قرض میرے سپرد کیا اور فرمایا: ’’اللہ تعالیٰ تیرے اہل ومال میں برکت فرمائے۔ قرض کا بدلہ تعریف اور ادائیگی ہے۔‘‘","f2":"(۱) ضرورت کے تحت قرض لینا جائز ہے۔ لیکن اس کی ادائیگی کی فکر بھی رہنی چاہیے، وسعت ہونے یا وقت مقررہ آنے پر فوراً ادائیگی کرنی چاہیے۔ اس بارے میں ہمیشہ احسان ہی سے کام لیا جائے، یعنی بروقت اور مکمل ادائیگی، اچھے انداز میں کی جائے۔ اگر کوئی شخص اپنے ذمے قرض سے، قرض خواہ کے مطالبے کے بغیر زیادہ ادائیگی کر دے تو یہ بہترین ادائیگی کے ساتھ ساتھ احسان بھی ہے۔ صاحب ثروت لوگوں کو اس کا خاص خیال رکھنا چاہیے۔ (۲) مقروض کو چاہیے کہ ادائیگی کے وقت بالخصوص اور عام اوقات میں بالعموم قرض خواہ کے لیے دعائیں کرتا رہے۔ قرض خواہ کو دعائیں دینا اور اس کا شکریہ ادا کرنا بھی احسن انداز سے ادائیگی میں شامل ہے، خصوصاً اس کے اہل وعیال اور مال ومتاع اور کاروبار میں برکت کی دعا دینا مسنون عمل ہے۔ (۳)ضرورت کے وقت قرض لینا جائز ہے، خصوصاً قومی ضروریات کے لیے۔ رسول اللہ صلی اللہ علیہ وسلم کا یہ قرض بھی قومی ضرورت کے لیے تھا نہ کہ ذاتی ضرورت کے لیے۔ مذمت بلا ضرورت قرض لینے کی ہے یا جب قرض لیتے وقت ادائیگی کی نیت نہ ہو۔"}],[4684,"محمد بن جحش رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے، آپ نے اپنا سر آسمان کی طرف اٹھایا، پھر ہاتھ اپنی پیشانی پر رکھا، پھر فرمایا: \"سبحان اللہ! کتنی سختی نازل ہوئی ہے؟\" ہم لوگ خاموش رہے اور ڈر گئے، جب دوسرا دن ہوا تو میں نے آپ سے پوچھا: اللہ کے رسول! وہ کیا سختی ہے جو نازل ہوئی؟ آپ نے فرمایا: \"قسم اس ذات کی، جس کے ہاتھ میں میری جان ہے! اگر ایک شخص اللہ کی راہ میں قتل کیا جائے پھر زندہ کیا جائے، پھر قتل کیا جائے پھر زندہ کیا جائے، پھر قتل کیا جائے اور اس پر قرض ہو تو وہ جنت میں داخل نہ ہو گا جب تک اس کا قرض ادا نہ ہو جائے\" ۱؎۔\n§وضاحت\n۱؎: یا قرض خواہ قرض نہ ادا کرنے پر اپنی رضا مندی کا اظہار کر دے، تو بھی وہ عفو و مغفرت کا مستحق ہو گا۔","الألباني: حسن",{"u2":"حضرت محمد بن جحش رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے کہ آپ نے اپنا سر آسمان کی طرف اٹھایا۔ پھر اپنی ہتھیلی اپنی پیشانی پر رکھی، پھر فرمایا: ’’سبحان اللہ! کس قدر سخت حکم اترا ہے؟‘‘ ہم خاموش رہے لیکن گھبرا گئے۔ اگلے دن میں نے پوچھا: اے اللہ کے رسول! وہ کیا سخت حکم تھا؟ آپ نے فرمایا: ’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر کوئی آدمی اللہ تعالیٰ کے راستے میں شہید کیا جائے، پھر اسے زندہ کیا جائے، پھر شہید کیا جائے، پھر زندہ کیا جائے، پھر شہید کیا جائے جبکہ اس کے ذمے قرض واجب الادا ہو تو وہ جنت میں داخل نہیں ہوگا حتیٰ کہ اس کے ذمے واجب الادا قرض اس کی طرف سے ادا کر دیا جائے۔‘‘","f2":"(۱) امام نسائی رحمہ اللہ کا مقصد قرض کی بابت شریعت کی سخت ترین وعید بیان کرنا ہے، یعنی جو آدمی قرض لے اور پھر اسے ادا کیے بغیر مر جائے تو اس کے لیے آخرت کے مراحل انتہائی مشکل ہوں گے بلکہ اس کے لیے جنت کا داخلہ بھی بند کر دیا جاتا ہے، لہٰذا قرض لینے سے ممکن حد تک بچنے کی کوشش کرنی چاہیے اور اگر قرض لینا ناگزیر ہو تو پھر اس کی جلد از جلد واپسی اور ادائیگی یقینی بنائی جائے۔ (۲) شہید فوت ہوتے ہی جنت میں پہنچ جاتا ہے اور جنت میں اڑتا پھرتا ہے، تاہم قرض رکاوٹ بن جاتا ہے حتی کہ قرض ادا کر دیا جائے۔ یا قرض خواہ راضی ہو جائے۔ اپنے آپ راضی ہو جائے یا اللہ تعالیٰ اسے راضی فرما دے۔"}],[4685,"سمرہ رضی اللہ عنہ کہتے ہیں کہ ہم لوگ ایک جنازے میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھے، آپ نے تین مرتبہ فرمایا: \"کیا فلاں گھرانے کا کوئی شخص یہاں ہے؟\" چنانچہ ایک شخص کھڑا ہوا تو اس سے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"پہلی دو مرتبہ میں کون سی چیز رکاوٹ تھی کہ تم نے میرا جواب نہ دیا، سنو! میں نے تمہیں صرف بھلائی کے لیے پکارا تھا، فلاں شخص ان میں کا ایک آدمی جو مر گیا تھا - اپنے قرض کی وجہ سے (جنت میں جانے سے) رکا ہوا ہے\" ۱؎۔\n§وضاحت\n۱؎: اس لیے اس کے قرض کی ادائیگی کا انتظام کرو یا قرض خواہ کو راضی کر لو۔","الألباني: صحيح",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ایک جنازے میں تھے۔ آپ نے تین دفعہ فرمایا: ’’کیا یہاں فلاں خاندان کا کوئی فرد ہے؟‘‘ آخر ایک آدمی کھڑا ہوا۔ آپ نے اسے فرمایا: ’’پہلی دو دفعہ تجھے کون سی چیز جواب دینے سے مانع تھی؟ میں نے تجھے ایک اچھے مقصد کے لیے بلایا تھا۔ اس قبیلے کا فلاں شخص جو فوت ہوگیا تھا، وہ اپنے قرض کی وجہ سے گرفتار ہے۔‘‘","f2":"’’گرفتار ہے‘‘ یا جنت میں جانے سے رکا ہوا ہے۔ آپ کا مقصد یہ تھا کہ اس کی طرف سے اس کا قرض جلدی ادا کیا جائے تاکہ وہ رہا ہو سکے یا جنت میں داخل ہو سکے۔"}],[4686,"عمران بن حذیفہ کہتے ہیں کہ ام المؤمنین میمونہ رضی اللہ عنہا قرض لیا کرتی تھیں اور کثرت سے لیا کرتی تھیں، تو ان کے گھر والوں نے اس سلسلے میں ان سے گفتگو کی اور ان کو برا بھلا کہا اور ان پر غصہ ہوئے تو وہ بولیں: میں قرض لینا نہیں چھوڑوں گی، میں نے اپنے خلیل اور محبوب صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"جو بھی کوئی قرض لیتا ہے اور اللہ کو معلوم ہوتا ہے کہ وہ قرض ادا کرنے کی فکر میں ہے تو اللہ تعالی اس کا قرض دنیا میں ادا کر دیتا ہے\"۔","الألباني: صحيح دون قوله في الدنيا",{"u2":"حضرت عمران بن حذیفہ سے روایت ہے کہ حضرت میمونہ رضی اللہ عنہا قرض لیا کرتی تھیں اور زیادہ لیا کرتی تھیں۔ ان کے رشتہ داروں نے اس بارے میں ان پر اعتراض کیا، ملامت کی اور ناراض ہوئے۔ وہ فرمانے لگیں: میں قرض لینا نہیں چھوڑوں گی کیونکہ میں نے اپنے پیارے محبوب خاوند صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’جو شخص بھی قرض لیتا ہے، جس کے بارے اللہ تعالیٰ کو علم ہو کہ وہ ادائیگی کی نیت رکھتا ہے تو اللہ تعالیٰ دنیا ہی میں اس کا قرض اس کی طرف سے ادا کرا دے گا۔‘‘","f2":"’’ادا کر دے گا‘‘ یعنی اسے ادائیگی کی توفیق طا فرمائے گا یا اپنے کسی نیک بندے کے دل میں القا فرما دے گا کہ اس کی طرف سے قرض ادا کر دے۔"}],[4687,"عبیداللہ بن عبداللہ بن عتبہ سے روایت ہے کہ ام المؤمنین میمونہ رضی اللہ عنہا نے قرض لیا، ان سے کہا گیا: ام المؤمنین! آپ قرض لے رہی ہیں حالانکہ آپ کے پاس ادا کرنے کے لیے کچھ نہیں ہے؟، عرض کیا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"جس نے کوئی قرض لیا اور وہ اسے ادا کرنے کی فکر میں ہو تو اللہ تعالی اس کی مدد فرماتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبیداللہ بن عبداللہ بن عتبہ سے روایت ہے کہ حضرت میمونہ رضی اللہ عنہا نبی اکرم صلی اللہ علیہ وسلم کی زوجہ مہترمہ نے ایک دفعہ قرض لیا۔ ان سے کہا گیا اے ام المومنین! آپ قرض لیتی ہیں جبکہ آپ کے واپسی کے لیے کچھ بھی نہیں؟ وہ فرمانے لگیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص قرض لے جبکہ وہ ادائیگی کا ارادہ رکھتا ہو، اللہ تعالیٰ اس کی مدد فرماتا ہے۔‘‘"}],[4688,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم میں سے کوئی شخص مالدار کی حوالگی میں دیا جائے تو چاہیئے کہ اس کی حوالگی قبول کرے ۱؎، اور مالدار کا ٹال مٹول کرنا ظلم ہے\"۔\n§وضاحت\n۱؎: اپنے ذمہ کا قرض دوسرے کے ذمہ کر دینا یہی حوالہ ہے، مثلاً زید عمرو کا مقروض ہے پھر زید عمرو کا سامنا بکر سے یہ کہہ کر کرا دے کہ اب میرے ذمہ کے قرض کی ادائیگی بکر کے سر ہے اور بکر اسے تسلیم بھی کر لے تو عمرو کو یہ حوالگی قبول کر لینی چاہیئے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی (قرض خواہ) کو کسی مال دار شخص کے پیچھے لگایا جائے تو اسے پیچھے لگ جانا چاہیے۔ (اگر اسے کسی مال دار شخص سے اپنا قرض وصول کرنے کی پیش کش کی جائے تو وہ یہ پیش کش قبول کر لے)۔ ظلم یہ ہے کہ مالدار شخص ٹال مٹول (ادائیگی میں تاخیر) کرے۔‘‘","f2":"(۱) مقصد یہ ہے کہ اگر مال دار شخص ادائیگی قرض میں تاخیر کرے تو یہ ناجائز اور حرام ہے۔ اگر مقروض شخص، مال دار نہیں تو اس کا قرض کی ادائیگی میں تاخیر کرنا ظلم نہیں ہوگا، لہٰذا ایسے مقروض کو بے عزت کرنا یا اسے سزا دینا درست نہیں ہوگا بلکہ اس کے ساتھ نرمی اور مہلت دینے والا سلوک کرنا مطلوب ہے۔ یہ بھی یاد رہے کہ اگر مقروض شخص ہے تو مال دار لیکن اس کا مال اس کی دسترس میں نہیں تو اس صورت میں اس کا لیت ولعل ظلم نہیں سمجھا جائے گا اور نہ اس کے ساتھ مال دار مقروض والا معاملہ ہی کیا جائے گا۔ (۲) کبھی مقروض اتنی وسعت نہیں رکھتا کہ خود ادائیگی کرے، لہٰذا اگر وہ قرض خواہ سے گزارش کرے کہ آپ اپنا قرض فلاں شخص سے وصول کرل یں۔ وہ میری طرف سے ادائیگی کرے گا۔ اور وہ شخص بھی اقرار کرے کہ میں ادائیگی کر دوں گا تو اخلاق کریمانہ کا تقاضا ہے کہ اس غریب آدمی کی جان چھوڑ دی جائے۔ اور وسرے شخص سے، جو مالدار بھی ہے اور ادائیگی کا اقرار بھی کرتا ہے، قرض وصول کرلیا جائے۔ اس عمل کو عربی زبان میں حوالہ کہتے ہے، جمہور اہل علم کی رائے یہی ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائی: ۳۵/ ۳۰۰، ۳۰۱) (۳)’’ظلم یہ ہے‘‘ یعنی غریب آدمی میں ادائیگی کی طاقت نہ ہو اور وہ ٹال مٹول کرے تو یہ ممکن ہے مگر ایک مالدار شخص قرض کی واپسی میں بلا وجہ تاخیر کرے اور آج کل کرتا رہے تو یہ ظلم ہے جس کی سزا اسے دی جا سکتی ہے، تاہم استطاعت نہ رکھنے والا شخص تاخیر کرے یا منت سماجت کرے تو اس پر زیادتی نہیں کرنی چاہیے کیونکہ وہ مجبور ہے اور شریعت ہر معقول عذر اور حقیقی مجبوری کا لحاظ کرتی ہے اور بہرحال مجبور شخص کے ساتھ تعاون اور اس کی حمایت کرتی ہے۔"}],[4689,"شرید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قرض ادا کرنے میں مالدار کے ٹال مٹول کرنے سے اس کی عزت اور اس کی سزا حلال ہو جاتی ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی اس کی برائی کر سکتا ہے اور حاکم اسے سزا دے سکتا ہے۔","الألباني: حسن",{"u2":"حضرت شرید رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ادائیگی کی گنجائش رکھنے والا شخص ادائیگی میں ٹال مٹول کرے تو اس کی بے عزتی کی جا سکتی ہے اور اسے سزا بھی دی جا سکتی ہے۔‘‘","f2":"بے عزتی تو قرض خواہ کرے گا کہ اسے لوگوں کے سامنے دلیل کرے اور سزا حکومت دے گی کہ اسے قید کر دے۔"}],[4690,"شرید رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مالدار کے ٹال مٹول کرنے سے اس کی عزت اور اس کی سزا حلال ہو جاتی ہے\"۔","الألباني: حسن",{"u2":"حضرت شرید رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مالدار شخص (ادائیگی میں حیلے بہانے کرے تو اس کی بے عزتی کرنا اور اسے سزا دینا جائز اور حلال ہے۔‘‘"}],[4691,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مالدار کا ٹال مٹول کرنا ظلم ہے، اگر تم میں سے کوئی مالدار آدمی کی حوالگی میں دیا جائے تو چاہیئے کہ اس کی حوالگی قبول کر لے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صاحب استطاعت شخص کا ادائیگی سے ٹال مٹول کرنا ظلم ہے۔ اور جب کسی (قرض خواہ) کو کسی مالدار شخص کے سپرد کیا جائے تو اسے چاہیے کہ وہ ادائیگی کے لیے اس سے رجوع کرے۔‘‘","f2":"حوالہ کی تفصیل حدیث نمبر ۴۶۹۲ میں بیان ہو چکی ہے۔ مقصد یہ ہے کہ قرض ایک شخص سے دوسرے شخص کی طرف منتقل ہو سکتا ہے۔ اسی لیے جمہور اہل علم محدثین کرام وفقہائے عظام اصل مقروض کو حوالہ کے بعد بری الذمہ سمجھتے ہیں، خواہ دوسرا شخص بھی ادائیگی نہ کر سکے کیونکہ قرض دوسرے کی طرف منتقل ہوگیا، دلائل کے اعتبار سے یہی بات راجح ہے۔فائدہ: حوالہ کی تفصیل حدیث نمبر ۴۶۹۲ میں بیان ہو چکی ہے۔ مقصد یہ ہے کہ قرض ایک شخص سے دوسرے شخص کی طرف منتقل ہو سکتا ہے۔ اسی لیے جمہور اہل علم محدثین کرام وفقہائے عظام اصل مقروض کو حوالہ کے بعد بری الذمہ سمجھتے ہیں، خواہ دوسرا شخص بھی ادائیگی نہ کر سکے کیونکہ قرض دوسرے کی طرف منتقل ہوگیا، دلائل کے اعتبار سے یہی بات راجح ہے۔"}],[4692,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ انصار کا ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں لایا گیا تاکہ آپ اس کا جنازہ پڑھائیں، آپ نے فرمایا: \"تمہارے اس ساتھی پر قرض ہے\"، ابوقتادہ نے کہا: میں اس کی ضمانت لیتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پورا ادا کرو گے؟\" کہا: \"جی ہاں\"۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک انصاری شخص کا جنازہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں لایا گیا کہ آپ اس کا جنازہ پڑھائیں۔ آپ نے فرمایا: ’’تمھارے اس ساتھی کے ذمے تو قرض ہے۔‘‘ ابوقتادہ نے کہا: اس کی ادائیگی کا میں ذمہ دار بنتا ہوں۔ آپ نے فرمایا: ’’پورا ادا کرو گے؟‘‘ میں نے کہا: پورا (ادا کروں گا)۔","f2":"(۱) ابتدا میں آپ کا طرز عمل یہی تھا کہ اگر میت کے ذمے قرض ہوتا اور اس کے ترکے میں اس کے مطابق مال نہ ہوتا تو آپ بذات خود جنازہ نہ پڑھتے، صحابہ کرام رضی اللہ عنہم سے فرما دیتے کہ تم پڑھ لو۔ پھر جب بیت المال میں وسعت ہوگئی تو آپ نے اعلان فرما دیا کہ جو شخص مقروض فوت ہو جائے تو اس کا قرض حکومت ادا کرے گی۔ گویا حکومت کی ذمہ داری میں یہ چیز بھی شامل ہے۔ (۲) میت کے قرض کی کفالت جمہور اہل علم کے نزدیک صحیح ہے۔ وہ کفیل نہ تو بعد میں انکار کر سکتا ہے نہ میت کے مال سے وصول کر سکتا ہے۔ امام ابوحنیفہ رحمہ اللہ میت کی طرف سے کفالت کو جائز نہیں سمجھتے اگر اس نے مال نہ چھوڑا ہو، حالانکہ اگر کوئی شخص ثواب کی نیت سے میت کا قرض ادا کرنے کی ذمہ داری اٹھائے تو اس میں کیا حرج ہے؟"}],[4693,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں بہتر لوگ وہ ہیں جو قرض اچھی طرح ادا کرتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے بہترین وہ لوگ ہیں جو ادائیگی کرنے میں اچھے ہوں۔‘‘"}],[4694,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک آدمی نے کبھی کوئی بھلائی کا کام نہیں کیا تھا لیکن وہ لوگوں کو قرض دیا کرتا، پھر اپنے قاصد سے کہتا: جو قرض آسانی سے واپس ملے اسے لے لو اور جس میں دشواری پیش آئے، اسے چھوڑ دو اور معاف کر دو، شاید اللہ تعالی ہماری غلطیوں کو معاف کر دے، جب وہ مر گیا تو اللہ تعالی نے اس سے کہا: کیا تم نے کبھی کوئی خیر کا کام کیا؟ اس نے کہا: نہیں، سوائے اس کے کہ میرے پاس ایک لڑکا تھا، میں لوگوں کو قرض دیتا تھا جب میں اس لڑکے کو تقاضا کرنے کے لیے بھیجتا تو اس سے کہتا کہ جو آسانی سے ملے اسے لے لینا اور جس میں دشواری ہو، اسے چھوڑ دینا اور معاف کر دینا، شاید اللہ تعالی ہمیں معاف کر دے، اللہ تعالی نے فرمایا: میں نے تمہیں معاف کر دیا\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک آدمی نے کبھی نیکی نہیں کی تھی۔ وہ لوگوں سے لین دین کیا کرتا تھا۔ وہ اپنے کارندے سے کہتا تھا کہ جو آسانی سے مہیا ہو سکے، لے لینا اور جس میں مقروض کو تنگی ہو، وہ چھوڑ دینا بلکہ معاف کر دینا۔ امید ہے اللہ تعالیٰ بھی ہمیں معاف کرے گا، پھر جب وہ فوت ہوگیا تو اللہ تعالیٰ نے اسے فرمایا: کیا تو نے کبھی کوئی نیکی کی ہے؟ اس نے کہا: نہیں، مگر میرا ایک غلام تھا اور میں لوگوں سے لین دین کیا کرتا تھا۔ جب میں اسے وصولی کے لیے بھیجتا تھا تو میں اسے کہتا تھا: جو آسانی سے مل جائے، لے لینا اور جس میں دینے والے کو تنگی ہو، چھوڑ دینا اور معاف کر دینا۔ شاید اللہ تعالیٰ ہمیں معاف فرما دے۔ اللہ تعالیٰ نے فرمایا: جا میں نے تجھے معاف کر دیا۔‘‘","f2":"(۱) جو شخص اللہ عزوجل کے بندوں کے ساتھ حسن معاملہ اور شفقت ونرمی کا مظاہرہ کرتا ہے تو اللہ عزوجل بھی اس کے ساتھ یہی معاملہ فرمائے گا، اور اس کا بدلہ جنت کی صورت میں دے گا۔ (۲) یہ حدیث مبارکہ اس اہم مسئلے پر بھی دلالت کرتی ہے کہ سابقہ شریعت بھی ہمارے لیے، ہماری اپنی شریعت ہی کی طرح واجب العمل اور واجب الطاعۃ ہے الا یہ کہ قرآن وحدیث کی تردید کر دیں۔ اس مسئلے کی بابت اگرچہ اہل علم کا اختلاف ہے، تاہم اہل علم کا صحیح قول ہے یہی ہے۔ امام بخاری، امام مسلم اور امام نسائیM وغیرہ کا مسلک یہی ہے۔ (۳)اس حدیث مبارکہ سے جہاں تنگ دست شخص کو مہلت دینے کی فضیلت ثابت ہوتی ہے وہاں مفلس و قلاش شخص کے ذمہ تمام یا کچھ قرض معاف کر دینے کی فضیلت بھی ثابت ہوتی ہے۔ {وَفِی ذٰلِکَ فَلْیَتَنَافَسِ الْمُتَنَافِسُونَ} (المطففین۸۳: ۲۶) (۴) خالص اللہ تعالیٰ کی رضا حاصل کرنے کے لیے کی جانے والی معمولی سی نیکی بھی بہت سے گناہوں کے مٹا دینے کا سبب بن سکتی ہے۔ (۵) غلام کو وکیل بنانے اور معاملات میں تصرف کرنے کا اختیار دینا جائز ہے۔ (۶) اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہوتا ہے کہ اگر کوئی انسان خود نیکی کا کام نہ کرے بلکہ کسی اور سے کرائے تو اس کام کرنے والے کے ساتھ ساتھ کرانے والے کو بھی پورا اجر ملے گا۔ (۷) شریعت مطہرہ نے یہ ہدایات اس لیے دی ہیں کہ ان پر عمل پیرا ہونے والے شخص کو بے شمار فوائد حاصل ہوتے ہیں۔ یہ بالکل واضح بات ہے کہ خوش اخلاقی بہت بڑی نیکی ہے، نیز یہ بھی حقیقت ہے کہ خوش اخلاق تاجر کے کاروبار میں بہت برکت ہوتی ہے۔"}],[4695,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ایک شخص لوگوں کو قرض دیتا تھا، جب کسی مفلس (دیوالیہ) کی پریشانی دیکھتا تو اپنے آدمی سے کہتا: اسے معاف کر دو، شاید اللہ تعالی ہمیں معاف فرمائے، پھر جب وہ اللہ تعالی سے ملا تو اللہ تعالی نے اسے معاف کر دیا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ایک آدمی لوگوں سے لین دین کیا کرتا تھا۔ جب وہ کسی تنگ دست کی تنگ دستی دیکھتا تو اپنے نوکر سے کہتا تھا کہ اسے معاف کر دو شاید اللہ تعالیٰ ہمیں معاف کر دے۔ پھر (وفات کے بعد) وہ شخص اللہ تعالیٰ کے سامنے حاضر ہوا تو اللہ تعالیٰ نے اسے معاف فرما دیا۔‘‘"}],[4696,"عثمان بن عفان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے ایک شخص کو جنت میں داخل کر دیا جو خریدتے، بیچتے، (قرض) دیتے اور تقاضا کرتے ہوئے نرمی سے کام لیتا تھا\"۔","الألباني: حسن",{"u2":"حضرت عثمان بن عفان رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے ایک آدمی کو اس بنا پر جنت میں داخل کر دیا کہ وہ خریدتے، بیچتے، ادا کرتے اور طلب کرتے وقت نرم رویہ رکھتا تھا۔‘‘","f2":"یہ حدیث مبارکہ بھی بلند اور کریمانہ اخلاق اپنانے اور لین دین میں اختلافات ختم کرنے کی ترغیب دیتی ہے۔ انسانوں کے ساتھ تنگی ترشی والا معاملہ نہیں کرنا چاہیے اور نہ ان کے لیے مصیبت اور عذاب ہی بننا چاہیے بلکہ مہربانی اور درگزر سے کام لینا چاہیے۔"}],[4697,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ عمار، سعد اور میں نے بدر کے دن حصہ داری کی، چنانچہ سعد دو قیدی لے کر آئے، ہم اور عمار کچھ بھی نہیں لائے۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں عمار اور سعد بدر کے دن شریک بنے۔ حضرت سعد رضی اللہ تعالٰی عنہ دو قیدی لائے۔ میں اور عمار کچھ نہ لائے۔","f2":"’’شریک بنے‘‘ اس شراکت کا مطلب یہ ہے کہ ہمیں جو کچھ ملے گا، وہ برابر تقسیم کر لیں گے۔ اس شراکت میں کوئی حرج نہیں کہ دو تین آدمی مل کر کام کریں اور پھر حاصل ہونے والی آمدنی میں برابر کے شریک بن جائیں۔ اگرچہ سب لوگ ایک جیسا کام نہیں کرتے مگر شراکت میں مسامحت ہوتی ہے۔ فقہاء کی اصطلاح میں ایسی شراکت کو شرکۃ الابدان کہتے ہیں۔"}],[4698,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ایک غلام میں اپنا حصہ آزاد کر دیا تو جتنا حصہ باقی ہے وہ بھی اسی کے مال سے آزاد ہو گا بشرطیکہ اس کے پاس غلام کی (بقیہ) قیمت بھر مال ہو\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث کا تعلق اگلے باب سے ہے، کاتبوں کی غلطی سے یہ اس باب میں درج ہو گیا۔","الألباني: صحيح",{"u2":"حضرت سالم کے والد محترم (حضرت عبداللہ بن عمر رضی اللہ تعالٰی عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی غلام میں اپنا حصہ آزاد کر دے تو باقی حصے کی آزادی بھی اس کے مال سے ہوگی بشرطیکہ اس کے پاس اتنا مال ہو جو اس غلام کی قیمت کے برابر ہو۔‘‘","f2":"اس روایت کی مناسبت اگلے باب سے ہے، الا یہ کہ اس باب کے معنی یہ ہوں کہ شراکت مال، یعنی روپے پیسے کے علاوہ اور چیزوں میں بھی ہو سکتی ہے، مثلاً: غلام۔ پھر یہ حدیث اگلے باب سے متعلق بھی ہو سکتی ہے۔"}],[4699,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی غلام میں اپنا حصہ آزاد کیا اور اس کے پاس غلام کی (بقیہ) قیمت کے برابر مال ہو تو وہ اس کے مال سے آزاد ہو جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی غلام میں اپنا حصہ آزاد کر دے اور اس کے پاس اتنا مال ہو جو اس غلام کے باقی حصے کی قیمت بن سکے تو وہ غلام (پورے کا پورا) اس کے مال سے آزاد ہوگا۔‘‘"}],[4700,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں اگر کسی کے پاس کوئی زمین یا کھجور کا درخت ہو تو اسے نہ بیچے جب تک کہ اپنے حصہ دار و شریک سے نہ پوچھ لے\" ۱؎۔\n§وضاحت\n۱؎: اس سے ثابت ہوا کہ درخت یا باغ میں حصہ داری جائز ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’۔تم میں سے جس شخص کے پاس زمین یا کھجوروں کے درخت ہوں تو وہ انھیں نہ بیچے حتی کہ اپنے شریک پر پیش کرے (اپنے شریک کو خریدنے کی پیش کش کرے)۔‘‘","f2":"’’اپنے شریک پر‘‘ یہیں پر باب سے تعلق ہے کہ شریک تبھی بنے گا اگر دونوں اس کے مشترکہ مالک ہوں گے۔ اس مسئلے کی مزید تفصیل اور وضاحت جاننے کے لیے دیکھیے، حدیث: ۴۶۵۰ کے فوائد ومسائل۔"}],[4701,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہر مشترک مال جو تقسیم نہ ہوا ہو جیسے زمین یا باغ، میں شفعہ کا حکم دیا، اس کے لیے صحیح نہیں کہ وہ اسے بیچے جب تک کہ حصہ دار سے اجازت نہ لے لے، اگر وہ (شریک) چاہے تو اسے لے لے اور اگر چاہے تو چھوڑ دے، اور اگر اس (شریک) سے اس کی اجازت لیے بغیر بیچ دیا تو وہ اس کا زیادہ حقدار ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہر مشترک چیز میں حق شفعہ قرار دیا ہے بشرطیکہ وہ تقسیم نہ ہوئی ہو۔ گھر ہو یا کھیت ہو یا باغ۔ کسی ایک شریک کو اپنا حصہ بیچنے کی اجازت نہیں حتی کہ اپنے شریک کو مطلع کرے۔ چاہے وہ لے لے، چاہے نہ لے۔ لیکن اگر اسے اطلاع کیے بغیر بیچ ڈالا تو شریک اس کا زیادہ حق دار ہوگا۔‘‘","f2":"تفصیل کے لیے دیکھیے، حدیث: ۴۶۵۰ کے فوائد ومسائل۔"}],[4702,"ابورافع رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پڑوسی اپنے پڑوس کا زیادہ حقدار ہے\"۔\n§وضاحت\n۱؎: شفعہ وہ استحقاق ہے جس کے ذریعہ شریک اپنے شریک کا وہ حصہ جو دوسرے کی ملکیت میں جا چکا ہے قیمت ادا کر کے حاصل کر سکے، لیکن اس میں شرط یہ ہے کہ دونوں کی جائیداد اس طرح مشترک ہو کہ دونوں کے حصے کی تعیین نہ ہو، اور دونوں کا راستہ بھی ایک ہو، دیکھئیے حدیث رقم ۴۷۰۸۔","الألباني: صحيح",{"u2":"حضرت ابو رافع رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پڑوسی اپنے قرب کی وجہ سے زیادہ حق رکھتا ہے۔‘‘","f2":"سنن اور مسند احمد میں حضرت جابر رضی اللہ تعالٰی عنہ سے اسی مفہوم کی روایت ہے۔ اس میں یہ شرط بھی ہے ’’بشرطیکہ ان کا راستہ ایک ہو۔‘‘ (مسند احمد: ۳/ ۳۰۳، وسنن ابی داود، الاجارۃ، حدیث: ۳۵۱۸) گویا پڑوسی کو بھی شفعہ کا حق ہے اگر وہر استے وغیرہ میں شریک ہو۔ اس طرح تمام روایات پر عمل ہو جائے گا۔ بعض حضرات نے صرف پڑوسی کو بھی شفعہ کا حق دیا ہے، خواہ وہ کسی لحاظ سے بھی شریک نہ ہو لیکن اس سے صحیحین کی متفقہ روایات کی خلاف ورزی ہوگی جن میں تقسیم اور راستے الگ الگ ہونے کے بعد شفعہ کی صراحتاً نفی کی گئی ہے۔ (مثلاً: دیکھیے، حدیث: ۴۷۰۸) شاہ ولی اللہ رحمہ اللہ نے شفعہ کی دو قسمیں قرار دی ہیں: شفعہ واجب اور شفعہ مستحب۔ شفعہ واجب تو شریک کے لیے ہی ہے، خواہ اصل چیز میں شریک ہو یا راستے وغیرہ میں۔ صرف پڑوسی جو کسی بھی لحاظ سے شریک نہ ہو، وہ شفعہ مستحب کا حق دار ہے، یعنی اچھی بات ہے کہ فروخت کرنے سے پہلے پڑوسی سے بھی پوچھ لیا جائے، ضروری نہیں۔ وہ عدالت میں دعویٰ بھی نہیں کر سکتا اور اس کے کہنے سے بیع فسخ بھی نہیں ہو سکتی جبکہ شریک سے پوچھ لینا ضروری ہے ورنہ عدالت میں یہ دعویٰ کر کے بیع فسخ کروا سکتا ہے۔ یہ تطبیق بھی مناسب ہے۔ واللہ اعلم (باقی تفصیل دیکھیے، حدیث: ۴۶۵۰)"}],[4703,"شرید رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے کہا: اللہ کے رسول! میری زمین ہے، جس میں کسی کی حصہ داری اور شرکت نہیں اور نہ ہی پڑوس کے سوا کسی کا حصہ ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پڑوسی اپنے پڑوسی کا زیادہ حقدار ہے\"۔","الألباني: صحيح",{"u2":"حضرت شرید رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نے کہا: اے اللہ کے رسول! میری زمین میں کوئی شخص شریک نہیں، نہ کسی کا حصہ ہے، البتہ پڑوس ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پڑوسی بھی قرب کی وجہ سے حق دار ہے۔‘‘","f2":"(۱)ہمسائے کو بوجہ ہمسائیگی دوسرے لوگوں کی نسبت زیادہ حق حاصل ہے کہ جب کوئی شخص اپنی زمین یا مکان و دکان وغیرہ بیچنا چاہے تو فروخت کرنے سے پہلے اپنے ہمسائے سے پوچھ لے کہ اگر وہ خریدنا چاہے توخرید لے۔ مالک جائیداد اگر ہمسائے سے پوچھے بغیر ہی کسی دوسرے شخص کے ہاتھ اپنی جائیداد فروخت کر دے تو قانونی اور شرعی طور پر ہمسائے کو محض حق ہمسائیگی کی بنا پر شفعہ کرنے کا کوئی حق نہیں۔ صحیح بخاری میں اس مسئلے کی صراحت موجود ہے۔ دیکھیے: (صحیح البخاری، البیوع، باب بیع الشریک من شریکہ، حدیث: ۲۲۱۳) (۲)یہ اہم مسئلہ بھی یاد رہنا چاہیے کہ حق شفعہ صرف غیر منقولہ جائیداد، مثلاً: زمین، مکان، باغ اور دکان وغیرہ میں ہے۔ منقولہ جائیداد میں کسی کو شفعے کا کوئی حق نہیں۔ مزید براں یہ بھی کہ جو مال تقسیم نہ کیا جا سکے اس میں بھی کوئی شفعہ نہیں۔ واللہ اعلم۔ (۳) ’’حق دار ہے۔‘‘ بشرطیکہ راستہ ایک ہو۔ یا استحباب مراد ہے جیسے شاہ ولی اللہ رحمہ اللہ نے فرمایا۔"}],[4704,"ابوسلمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر وہ مال جو تقسیم نہ ہوا ہو، اس میں شفعہ کا حق ہے۔ لہٰذا جب حد بندی ہو جائے اور راستہ متعین ہو جائے تو اس میں شفعہ کا حق نہیں\" ۱؎۔\n§وضاحت\n۱؎: حق شفعہ کے سلسلہ میں مناسب اور صحیح بات یہ ہے کہ یہ حق ایسے دو پڑوسیوں کو حاصل ہو گا جن کے مابین پانی، راستہ وغیرہ مشتر کہوں، دوسری صورت میں یہ حق حاصل نہیں ہو گا۔","الألباني: صحيح",{"u2":"حضرت ابو سلمہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’شفعہ ہر اس مال میں ہے جو تقسیم نہ ہوا ہو۔ جب الگ الگ حد بندی ہو جائے اور راستے بھی الگ الگ ہو جائیں تو شفعہ باقی نہیں رہتا۔‘‘","f2":"امام مالک، امام شافعی اور محدثین اسی کے قائل ہیں، البتہ احناف صرف پڑوسی کے لیے بھی شفعہ کے قائل ہیں۔ اس حدیث میں وہ تاویل کرتے ہیں کہ یہاں شفعہ کی شرکت کی نفی ہے نہ کہ شفعہ جوار کی، حالانکہ صراحت کے ساتھ ہر شفعہ کی نفی کی گئی ہے۔"}],[4705,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے شفعہ اور پڑوس کے حق کا حکم دیا۔","الألباني: صحيح لغيره",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے شفعہ اور پڑوس کے حق کو برقرار رکھا ہے۔","f2":"گویا پڑوس کا حق شفعہ کے علاوہ ہے، جیسے کہ حضرت شاہ ولی اللہ رحمہ اللہ کی تحقیق نفیس میں بیان ہوا ہے۔ بہت سی احادیث میں پڑوس کے حق کا خیال رکھنے کی تاکید وارد ہے، لہٰذا اس روایت سے پڑوسی کے لیے شفعہ کا حق ثابت نہیں ہو سکتا۔ تفصیل پیچھے گزر چکی ہے۔ شریک کے لیے شفعہ اور پڑوسی کے لیے جوار۔"}],[4706,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ جاہلیت کے زمانے کا پہلا قسامہ یہ تھا کہ بنی ہاشم کا ایک شخص تھا، قریش یعنی اس کی شاخ میں سے کسی قبیلے کے ایک شخص نے اسے نوکری پر رکھا، وہ اس کے ساتھ اس کے اونٹوں میں گیا، اس کے پاس سے بنی ہاشم کے ایک شخص کا گزر ہوا جس کے توش دان کی رسی ٹوٹ گئی تھی، وہ بولا: میری مدد کرو ایک رسی سے جس سے میں اپنے توش دان کا منہ باندھ سکوں تاکہ (اس میں سے سامان گرنے سے) اونٹ نہ بدکے، چنانچہ اس نے اسے توش دان کا منہ باندھنے کے لیے رسی دی، جب انہوں نے قیام کیا اور ایک اونٹ کے علاوہ سبھی اونٹ باندھ دیے گئے تو جس نے نوکر رکھا تھا، اس نے کہا: اس اونٹ کا کیا معاملہ ہے، تمام اونٹوں میں اسے کیوں نہیں باندھا گیا؟ اس نے کہا: اس کے لیے کوئی رسی نہیں ہے، اس نے کہا: اس کی رسی کہاں گئی؟ وہ بولا: میرے پاس سے بنی ہاشم کا ایک شخص گزرا جس کے توش دان کا منہ باندھنے کی رسی ٹوٹ گئی تھی، اس نے مجھ سے مدد چاہی اور کہا: مجھے توش دان کا منہ باندھنے کے لیے ایک رسی دے دو تاکہ اونٹ نہ بدکے، میں نے اسے رسی دے دی، یہ سن کر اس نے ایک لاٹھی نوکر کو ماری، اسی میں اس کی موت تھی (یعنی یہی چیز بعد میں اس کے مرنے کا سبب بنی) اس کے پاس سے یمن والوں میں سے ایک شخص کا گزر ہوا، اس نے کہا: کیا تم حج کو جا رہے ہو؟ اس نے کہا: جا نہیں رہا ہوں لیکن شاید جاؤں، اس نے کہا: کیا تم (اس موقع سے) کسی بھی وقت میرا یہ پیغام پہنچا دو گے؟ اس نے کہا: ہاں، کہا: جب تم حج کو جاؤ تو پکار کر کہنا: اے قریش کے لوگو! جب وہ آ جائیں تو پکارنا! اے ہاشم کے لوگو! جب وہ آ جائیں تو ابوطالب کے بارے میں پوچھنا پھر انہیں بتانا کہ فلاں شخص نے مجھے ایک رسی کے سلسلے میں مار ڈالا ہے اور (یہ کہہ کر) نوکر مر گیا، پھر جب وہ شخص آیا جس نے نوکری پر اسے رکھا تھا تو اس کے پاس ابوطالب گئے اور بولے: ہمارے آدمی کا کیا ہوا؟ وہ بولا: وہ بیمار ہو گیا، میں نے اس کی اچھی طرح خدمت کی پھر وہ مر گیا، میں راستے میں اترا اور اسے دفن کر دیا۔ ابوطالب بولے: تمہاری طرف سے وہ اس چیز کا حقدار تھا، وہ کچھ عرصے تک رکے رہے پھر وہ یمنی آیا جسے اس نے وصیت کی تھی کہ جب موسم حج آیا تو وہ اس کا پیغام پہنچا دے۔ اس نے کہا: اے قریش کے لوگو! لوگوں نے کہا: یہ قریش ہیں، اس نے کہا: اے بنی ہاشم کے لوگو! لوگوں نے کہا: یہ بنی ہاشم ہیں، اس نے کہا: ابوطالب کہاں ہیں؟ کسی نے کہا: ابوطالب یہ ہیں۔ وہ بولا: مجھ سے فلاں نے کہا ہے کہ میں آپ تک یہ پیغام پہنچا دوں کہ فلاں نے اسے ایک رسی کی وجہ سے مار ڈالا، چنانچہ ابوطالب اس کے پاس آئے اور بولے: تم تین میں سے کوئی ایک کام کرو، اگر تم چاہو تو سو اونٹ دے دو، اس لیے کہ تم نے ہمارے آدمی کو غلطی سے مار ڈالا ہے ۱؎ اور اگر چاہو تو تمہاری قوم کے پچاس آدمی قسم کھائیں کہ تم نے اسے نہیں مارا، اگر تم ان دونوں باتوں سے انکار کرتے ہو تو ہم تمہیں اس کے بدلے قتل کریں گے، وہ اپنی قوم کے پاس آیا اور ان سے اس کا ذکر کیا تو انہوں نے کہا: ہم قسم کھائیں گے، پھر بنی ہاشم کی ایک عورت ابوطالب کے پاس آئی جو اس قبیلے کے ایک شخص کی زوجیت میں تھی، اس شخص سے اس کا ایک لڑکا تھا، وہ بولی: ابوطالب! میں چاہتی ہوں کہ آپ ان پچاس میں سے میرے اس بیٹے کو بخش دیں اور اس سے قسم نہ لیں، ابوطالب نے ایسا ہی کیا، پھر ان کے پاس ان میں کا ایک شخص آیا اور بولا: ابوطالب! آپ سو اونٹوں کی جگہ پچاس آدمیوں سے قسم لینا چاہتے ہو؟ ہر شخص کے حصے میں دو اونٹ پڑیں گے، تو لیجئیے دو اونٹ اور مجھ سے قسم مت لیجئیے جیسا کہ آپ اوروں سے قسم لیں گے، ابوطالب نے دونوں اونٹ قبول کر لیے، پھر اڑتالیس آدمی آئے اور انہوں نے قسم کھائی۔ ابن عباس رضی اللہ عنہما کہتے ہیں: قسم اس ذات کی جس کے قبضہ میں میری جان ہے! ابھی سال بھی نہ گزرا تھا کہ ان اڑتالیس میں سے ایک بھی آنکھ جھپکنے والی نہیں رہی (یعنی سب مر گئے) ۲؎۔\n§وضاحت\n۱؎: نامعلوم قتل کی صورت میں مشتبہ افراد یا بستی والوں سے قسم لینے کو قسامہ کہا جاتا ہے۔ ۲؎: ابن عباس رضی اللہ عنہما نے ان سب کے مر جانے کی خبر قسم کھا کر دی باوجود یہ کہ یہ اس وقت پیدا ہی نہیں ہوئے تھے۔ اس سلسلہ میں تین باتیں کہی جاتی ہیں: یہ خبر ان تک تواتر کے ساتھ پہنچی ہو گی، کسی ثقہ شخص کے ذریعہ پہنچی ہو گی، یہ بھی احتمال ہے کہ اس واقعہ کی خبر انہیں نبی اکرم صلی اللہ علیہ وسلم نے دی ہو گی۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: جاہلیت میں سب سے پہلی قسامت اس طرح ہوئی کہ بنو ہاشم میں سے ایک آدمی کو کسی دوسرے قبیلے کے ایک قریشی نے اجرت پر اپنے پاس رکھا۔ وہ نوکر اس قریشی کے ساتھ اس کے اونٹوں میں گیا۔ اتفاقاً بنو ہاشم کا ایک آدمی اس کے پاس سے گزرا۔ اس کے بورے کے منہ کی رسی ٹوٹ چکی تھی۔ اس نے ہاشمی نوکر سے کہا: مجھے ایک رسی دو جس سے میں اپنے بورے کا منہ باندھ لوں تاکہ اونٹ نہ گھبرائیں۔ اس نوکر نے اسے ایک اونٹ کی گھٹنا باندھنے والی رسی دے دی تاکہ وہ اپنے بورے کا منہ باندھ لے۔ جب وہ آگے جا کر کسی منزل میں اترے اور اونٹوں کے گھٹنے باندھے گئے تو ایک اونٹ کھلا رہ گیا۔ مالک نے کہا: کیا وجہ ہے کہ اس ایک اونٹ کا گھٹنا نہیں باندھا گیا؟ اس نے کہا: اس کی رسی نہیں۔ اس نے کہا: اس کی رسی کھر گئی؟ اس نے بتایا کہ میرے پاس بنو ہاشم کا ایک آدمی گزرا تھا۔ اس کے بورے کے منہ والی رسی ٹوٹ چکی تھی۔ اس نے مجھ سے مدد طلب کی اور کہا کہ مجھے ایک رسی دے جس کے ساتھ میں اپنے بورے کا منہ باندھ لوں تاکہ اونٹ نہ گھبرائیں۔ میں نے اس کو دے دی۔ مالک نے (غصے میں) اس کی طرف زور سے لاٹھی پھینکی جو اس کی موت کا باعث بن گئی۔ (وہ قریب المرگ تھا کہ) اتنے میں ادھر سے ایک یمنی آدمی گزرا۔ اس (ہاشمی نوکر) نے یمنی سے کہا: کیا تو موسم حج میں (مکہ مکرمہ) جاتا ہے؟ اس نے کہا: عام تو نہیں جاتا، کبھی کبھار جاتا ہوں۔ اس نے کہا: کیا تو اپنی ساری عمر میں کسی بھی وقت میرا یہ پیغام پہنچائے گا؟ اس نے کہا: ضرور۔ اس نے کہا: جب تو موسم حج میں جائے تو اعلان کرنا: اے قریشیو! جب وہ آجائیں تو بنو ہاشم کے بارے میں پوچھنا اور اسے بتانا کہ فلاں شخص نے مجھے ایک رسی کی وجہ سے قتل کر دیا ہے۔ (اتنی بات کہہ کر) وہ نوکر مر گیا۔ جب وہ شخص واپس (مکے) آیا جس نے اسے نوکر رکھا تھا تو ابو طالب اس کے پاس گئے اور پوچھا: ہمارے آدمی کا کیا بنا؟ اس نے کہا: وہ (راستے میں) بیمار ہوگیا تھا۔ میں نے اس کی خوب تیمارداری کی مگر وہ فوت ہوگیا۔ میں نے پڑاؤ کیا اور اس کا کفن دفن کیا۔ وہ کہنے لگے: واقعی وہ تجھ سے اسی سلوک کا اہل تھا۔ پھر کچھ عرصہ گزرا تو وہ یمنی شخص جسے اس نوکر نے وصیت کی تھی کہ یہ پیغام پہنچائے، موسم حج میں آگیا۔ اس نے اعلان کیا: اے قریشیو! لوگوں نے کہا: یہ قریشی ہیں۔ پھر اس نے کہا: اے ہاشمیو! لوگوں نے کہا: یہ ہاشمی ہیں۔ اس نے کہا: ابو طالب کہاں ہیں؟ کسی نے کہا: یہ ابو طالب ہیں۔ اس نے کہا: مجھے فلاں شخص نے کہا تھا کہ میں تجھے یہ پیغام پہنچا دوں کہ فلاں شخص نے اسے ایک رسی کی بنا پر قتل کیا ہے۔ تب ابو طالب اس (قاتل) کے پاس ائے اور کہا: ہماری طرف سے تین باتوں میں سے کوئی ایک قبول کر لے: اگر تو چاہے تو سو اونٹ بطور دیت ادا کر کیونکہ تو نے ہمارا آدمی خطاً (غلطی سے) قتل کیا ہے۔ اگر تو چاہے تو تیری قوم کے پچاس آدمی قسم کھائیں کہ تو نے اسے قتل نہیں کیا۔ اگر تو ان دونوں باتوں کو تسلیم نہیں کرے گا تو ہم تجھے اس کے بدلے قتل کر دیں گے۔ وہ اپنی قوم کے پاس گیا اور ان سے یہ ساری بات ذکر کی۔ انھوں نے کہا: ہم قسمیں کھائیں گے۔ بنو ہاشم کی ایک عورت جو اس قبیلے کے ایک آدمی کے نکاح میں تھی اور اس سے اس کی اولاد بھی تھی، ابو طالب کے پاس آئی اور کہنے لگی: ابو طالب! میں چاہتی ہوں کہ تو میرے بیٹے کو پچاس آدمیوں پر پڑنے والی قسم معاف کر دے اور اس سے قسم نہ لے۔ ابو طالب مان گئے۔ اس قبیلے میں سے ایک اور آدمی آیا اور کہنے لگا: ابو طالب! تو سو اونٹوں کے عوض پچاس آدمیوں سے قسمیں لینا چاہتا ہے۔ اس لحاظ سے ہر آدمی کو دو اونٹ پڑتے ہیں۔ یہ دو اونٹ میری طرف سے قبول کر لے اور جب قسمیں لی جائیں تو میری قسم نہ لی جائے۔ ابو طالب نے دو اونٹ لے لیے۔ باقی ارٹتالیس آدمی آئے اور انھوں نے قسمیں کھائیں۔ حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! ابھی پورا سال بھی نہیں گزرا تھا کہ ان اڑتالیس آدمیوں میں سے کوئی ایک آنکھ حرکت کرتی ہو۔ (سارے کے سارے مر گئے)۔","f2":"(۱) اسلام سے پہلے تمام اصول وضوابط اور شریعتیں منسوخ ہو چکی ہیں، تاہم جو اصول وضوابط اور احکام رسول اللہ صلی اللہ علیہ وسلم نے باقی رکھے ہیں، وہ اب بھی باقی ہیں، ایسے احکام کی حیثیت اسلامی احکام ہی کی ہے۔ یہ اسی طرح واجب اطاعت ہیں جس طرح قرآن وحدیث کے دیگر احکام ہیں۔ (۲) جھوٹی قسم کھانا کبیرہ گناہ ہے۔ اس کا وبال، قسم کھانے والے پر بہر صورت پڑتا ہے (جیسا کہ اس حدیث میں مذکور لوگوں پر پڑا) خواہ یہ وبال دنیا میں پڑ جائے یا آخرت میں، الا یہ کہ ایسا شخص سچی توبہ کر لے۔ (۳)کسی شخص کو ناحق قتل کرنا ہلاک کر دینے والا کبیرہ گناہ ہے۔ یہ جرم اس قدر سنگین ہے کہ زمانہ جاہلیت میں بھی لوگ اس کی شناعت کے قائل تھے۔ اور اس کی روک تھام کے لیے ہر طرح کوششیں کی جاتی تھیں، تاہم کمزور، طاقتور سے بدلہ نہیں لے سکتا تھا۔ دین اسلام نے نہ صرف اس جرم کی قباحت کو بیان کیا بلکہ اسے روکنے کے لیے ترغیب و ترہیب کے ساتھ ساتھ قانون بھی مقرر فرمایا۔ اس کی شناعت کی بابت ارشاد باری تعالیٰ ہے:\n{مَنْ قَتَلَ نَفْسًا بِغَیْرِ نَفْسٍ اَوْ فَسَادٍ فِی الْاَرْضِ فَکَاَنَّمَا قَتَلَ النَّاسَ جَمِیْعًا وَ مَنْ اَحْیَاہَا فَکَاَنَّمَآ اَحْیَا النَّاسَ جَمِیْعًا} (المآئدۃ: ۳۲)\n’’جس شخص نے کسی ایک جان کو، کسی جان کے بدلے کے بغیر یا زمین میں فساد مچانے کے بغیر قتل کیا تو گویا اس نے تمام لوگوں (ساری نسل انسانی) کو قتل کیا اور جس نے اسے (ایک جان کو) زندہ کیا تو گویا اس نے تمام لوگوں کو زندہ کیا۔‘‘ نیز ارشاد ربانی ہے:\n{وَ مَنْ یَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُہٗ جَہَنَّمُ خٰلِدًا فِیْہَا وَ غَضِبَ اللّٰہُ عَلَیْہِ وَ لَعَنَہٗ وَ اَعَدَّلَہٗ عَذَابًا عَظِیْمًاo} (النسآئ: ۹۳)\n’’اور جو شخص کسی مومن کو جان بوجھ کر قتل کرے تو اس کی سزا جہنم ہے۔ وہ اس میں ہمیشہ رہے گا۔ اللہ اس پر غضب ناک ہوا اور اس پر لعنت کی۔ اور اس نے اس کے لیے بہت بڑا عذاب تیار کر رکھا ہے۔‘‘\nایک شخص کے ناحق قتل کو پوری انسانیت کا قتل قرار دینے والا دین، شر وفساد کے پھیلانے کی کس طرح حوصلہ افزائی کر سکتا ہے؟ مسلمانوں کے خلاف میڈیا میں جو زہر اگلا جاتا ہے وہ یہود وہنود کی سازش ہے۔ بدقسمتی سے ہمارے کچھ نام نہاد مسلمان بھی اس باطل پروپیگنڈے کا شکار ہو چکے ہیں اور کافروں کے آلہ کاربن کر اسلام کے روشن چہرے کو داغ دار کرنے کی مذموم کوشش کر رہے ہیں۔ (۴) قسامت قسم کی ایک خاص صورت ہے اور وہ یہ ہے کہ جب کوئی شخص کسی علاقے میں مقتول پایا جائے لیکن اس کے قاتل کا پتا نہ چلے یا کچھ لوگوں پر شک ہو کہ وہ قتل میں ملوث ہیں مگر کوئی ثبوت نہ ہو تو مدعین سے پچاس قسمیں لی جائیں گی۔ اگر وہ نہ دیں تو مدعی، علیہم کے پچاس معتبر آدمیوں سے قسم لی جائے کہ نہ ہم نے اسے قتل کیا ہے نہ ہی قاتل کو جانتے ہیں۔ ایسی صورت میں اس علاقے کے لوگ قتل کے الزام سے بری ہو جائیں گے۔ مذکورہ واقعے میں بھی قاتل تسلیم نہیں کر رہا تھا۔ اور موقع کی گواہی نہیں تھی، صرف زبانی پیغام تھا، لہٰذا وہ مشکوک ہوگیا اور اس سے قسمیں لی گئیں۔ مدعین قسمیں اس لیے نہیں اٹھا سکتے تھے کہ انھوں نے دیکھا نہیں تھا۔ (۵) قسامت اگرچہ جاہلیت کا رواج تھا مگر چونکہ صحیح تھا، اس لیے شریعت اسلامیہ نے اسے برقرار رکھا۔ یہ اب بھی مشروع ہے۔ (۶) ’’اونٹوں میں گیا‘‘ یعنی اس کے ساتھ سفر پر گیا۔ ساتھ اونٹ بھی تھے۔ (۷) ’’اونٹ نہ گھبرائیں‘‘ بورے کی چیزوں کے گرنے کی وجہ سے اونٹ ڈرتے تھے۔ (۸) ’’اسی سلوک کا اہل تھا‘‘ کیونکہ وہ ایک معزز قبیلے سے تعلق رکھتا تھا۔ (۹) ’’خطاً قتل کیا ہے‘‘ کیونکہ اس کا مقصد قتل کرنا نہیں تھا بلکہ ویسے لاٹھی مارنا تھا، تاہم وہ کسی نازک جگہ پر لگی جو اس کی موت کا سبب بن گئی۔ قتل خطا میں قصاص نہیں لیا جا سکتا بلکہ دیت وصول کی جائے گی۔ (۱۰) ’’قسمیں کھائیں‘‘ یعنی جھوٹی، کیونکہ وہ جانتے تھے کہ ہمارے آدمی سے قتل ہوا ہے لیکن دیت سے بچنے کے لیے جھوٹی قسمیں کھائیں۔ یاد رہے قتل خطا میں دیت قاتل کے قبیلے کو بھرنا پڑتی ہے۔ (۱۱) ’’کوئی ایک آنکھ حرکت کرتی ہو۔‘‘ یعنی ان میں سے کوئی بھی زندہ نہ رہا۔ زندہ آدمی کی آنکھ ہی حرکت کرتی ہے۔ حضرت ابن عباس رضی اللہ عنہ کو یہ واقعہ شاید رسول اللہ صلی اللہ علیہ وسلم نے خود بتایا ہو، تبھی تو وہ قسم کھا کر اس زور دار طریقے سے بیان فرما رہے ہیں۔ (۱۴) ضروری نہیں کہ ہر جھوٹی قسم کا انجام یہی ہو۔ کبھی کبھار ایسا ہو جاتا ہے جب اللہ تعالیٰ اپنے بندوں کو کوئی نشانی دکھانا چاہے۔ رسول اللہ صلی اللہ علیہ وسلم کی بعثت سے قبل بہت سے ایسے خلاف عادت واقعات ہوئے تھے۔ (۱۳) یہ حدیث حرم کی عظمت وحرمت پر بھی واضح دلالت کرتی ہے اور یہ کہ جس کسی نے بھی حرم یا حدودِ حرم میں معاصی وغیرہ کا ارتکاب کیا، اس پر اللہ تعالیٰ کے عذاب کا کوڑا برسا اور وہ نشانِ عبرت بن گیا۔"}],[4707,"ایک انصاری صحابی رسول رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قسامہ کو اسی حالت پر باقی رکھا جس پر وہ جاہلیت میں تھا۔","الألباني: صحيح الإسناد",{"u2":"رسول اللہ صلی اللہ علیہ وسلم کے ایک انصاری صحابی رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قسامت کو برقرار رکھا ہے جیسے کہ وہ جاہلیت میں رائج تھی۔","f2":"اسلام نے جاہلیت کی صرف بری رسموں کو ختم کیا ہے، ہر رسم کو نہیں۔ آپ صلی اللہ علیہ وسلم کے برقرار رکھنے سے اب یہ رسم کے طور پر قابل عمل نہیں بلکہ اسے شرعی حکم کا درجہ حاصل ہے۔"}],[4708,"کچھ صحابہ سے روایت ہے کہ قسامہ جاہلیت میں جاری تھا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اسی حالت پر باقی رکھا جس پر وہ جاہلیت میں تھا، اور انصار کے کچھ لوگوں کے درمیان ایک مقتول کے سلسلے میں اسی کا فیصلہ کیا جس کے بارے میں ان کا دعوی تھا کہ اس کا خون خیبر کے یہودیوں پر ہے۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) معمر نے ان دونوں (یونس اور اوزاعی) کے برخلاف یہ حدیث (مرسلاً) روایت کی ہے۔","الألباني: صحيح الإسناد",{"u2":"رسول اللہ صلی اللہ علیہ وسلم کے بہت سے صحابہ سے روایت ہے کہ قسامت جاہلیت میں رائج تھی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے اسی طرح برقرار رکھا جس طرح یہ جاہلیت میں تھی اور آپ نے ایک مقتول کے بارے میں قسامت کا فیصلہ بھی کیا تھا جس کے قتل کا الزام انصار نے خیبر کے یہودیوں پر لگایا تھا۔\nمعمر نے ان دونوں کی مخالفت کی ہے۔","f2":"قسامت والی اس روایت کو امام زہری سے بیان کرنے والے تین راوی، یونس، اوزاعی اور معمر ہیں۔ مخالفت یہ ہے کہ یونس بن یزید اور امام اوزاعی نے جب یہ روایت امام زہری سے بیان کی تو انھوں نے اسے موصول بیان کیا ہے، یعنی ان کی سند میں صحابی رسول ہی رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے ہیں جبکہ امام معمر بن راشد نے اپنی سند میں سعید بن مسیب تابعی کے واسطے سے رسولا للہ صلی اللہ علیہ وسلم کی بابت روایت ذکر کی ہے۔ اس طرح یہ حدیث مرسل بنتی ہے، یعنی ایک تابعی فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس طرح کیا تھا۔ اس مخالفت کے باوجود حدیث مذکور کی صحت پر کوئی اثر نہیں پڑتا کیونکہ وہ دونوں ثقہ اور حافظ ہیں، لہٰذا وہ مقدم ہیں۔"}],[4709,"سعید بن مسیب کہتے ہیں کہ قسامہ جاہلیت میں رائج تھا، پھر اسے رسول اللہ صلی اللہ علیہ وسلم نے اس انصاری کے سلسلے میں باقی رکھا جو یہودیوں کے کنویں میں مرا ہوا پایا گیا تو انصار نے کہا: ہمارے آدمیوں کا قتل یہودیوں نے کیا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن مسیب رحمہ اللہ بیان کرتے ہیں کہ قسامت جاہلیت میں تھی، پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے ایک انصاری کے بارے میں برقرار رکھا جو یہودیوں کے ایک کنویں میں مقتول پائے گئے تھے۔ انصار نے دعویٰ کر دیا تھا کہ یہودیوں نے ہمارے آدمی کو قتل کیا ہے۔"}],[4710,"سہل بن ابی حثمہ رضی اللہ عنہ بیان کرتے ہیں کہ عبداللہ بن سہل اور محیصہ رضی اللہ عنہما (رزق کی) تنگی کی وجہ سے خیبر کی طرف نکلے تو محیصہ کے پاس کسی نے آ کر بتایا کہ عبداللہ بن سہل کا قتل ہو گیا ہے، اور انہیں ایک کنویں میں یا چشمے میں ڈال دیا گیا ہے، یہ سن کر وہ (محیصہ) یہودیوں کے پاس گئے اور کہا: اللہ کی قسم! تم ہی نے انہیں قتل کیا ہے۔ وہ بولے: اللہ کی قسم! انہیں ہم نے قتل نہیں کیا۔ پھر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے اس کا ذکر کیا، پھر وہ، حویصہ (ان کے بڑے بھائی) اور عبدالرحمٰن بن سہل رضی اللہ عنہما ساتھ آئے تو محیصہ رضی اللہ عنہ نے گفتگو کرنا چاہی (وہی خیبر میں ان کے ساتھ تھے) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑے کا لحاظ کرو، بڑے کا لحاظ کرو\"، اور حویصہ رضی اللہ عنہ نے گفتگو کی پھر محیصہ رضی اللہ عنہ نے کی، رسول اللہ صلی اللہ علیہ وسلم نے (اس سلسلے میں) فرمایا: \"یا تو وہ تمہارے ساتھی کی دیت ادا کریں یا، پھر ان سے جنگ کے لیے کہہ دیا جائے\"، اور یہ بات رسول اللہ صلی اللہ علیہ وسلم نے انہیں لکھ بھیجی، تو انہوں نے لکھا: اللہ کی قسم! ہم نے انہیں قتل نہیں کیا، رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبدالرحمٰن (رضی اللہ عنہم) سے فرمایا: \"تمہیں قسم کھانا ہو گی ۲؎ اور پھر تمہیں اپنے آدمی کے خون کا حق ہو گا\"، وہ بولے: نہیں، آپ نے فرمایا: \"تو پھر یہودی قسم کھائیں گے\"، وہ بولے: وہ تو مسلمان نہیں ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس (یعنی بیت المال) سے ان کی دیت ادا کی اور ان کے پاس سو اونٹ بھیجے یہاں تک کہ وہ ان کے گھر میں داخل ہو گئے، سہل رضی اللہ عنہ نے کہا: ان میں سے ایک سرخ اونٹنی نے مجھے لات ماری تھی۔\n§وضاحت\n۱؎: یعنی: قسامہ میں پہلے مقتول کے ورثاء سے کہا جائے گا کہ تم لوگ قسم کھا لو تو تم کو قتل کی دیت دے دی جائے گی، اور جب ورثاء قسم سے انکار کر دیں گے تب مدعا علیہم سے قسم کھانے کو کہا جائے گا اب اگر وہ بھی قسم کھا لیں گے تو دیت بیت المال سے دلائی جائے گی جیسا کہ آپ صلی اللہ علیہ وسلم نے اس معاملہ میں کیا تھا۔ ۲؎: اسی جملہ کی باب سے مناسبت ہے۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ نے بتایا کہ عبداللہ بن سہل اور محیصہ بھوک اور مشقت کے ستائے ہوئے خیبر کی طرف گئے۔ محیصہ کسی کام سے واپس آئے تو انھیں بتایا گیا کہ عبداللہ بن سہل کو قتل کر کے کنویں یا چشمے میں پھینک دیا گیا ہے۔ وہ یہودیوں کے پاس گئے اور کہا: اللہ کی قسم! تم نے اسے قتل کیا ہے۔ انھوں نے کہا: اللہ کی قسم! ہم نے اسے قتل نہیں کیا۔ پھر وہ مدینہ منورہ واپس آئے اور رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہو کر پوری بات آپ سے ذکر کی۔ پھر وہ خود، ان کے بڑے بھائی حویصہ اور (مقتول کے بھائی) عبدالرحمن بن سہل تینوں آئے۔ محیصہ بات کرنے لگے کیونکہ وہ خیبر میں (مقتول کے ساتھ) تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو بات کرنے دو۔‘‘ تب حویصہ بات کی۔ پھر محیصہ نے بھی بات چیت کی۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کی بابت فرمایا: ’’یا تو یہودی تمھارے مقتول کی دیت دیں گے یا انھیں جنگ لڑنا ہوگی۔‘‘ نبی اکرم صلی اللہ علیہ وسلم نے اس کی بابت یہودیوں کو خط لکھا۔ انھوں نے (جواباً) لکھا: اللہ کی قسم! ہم نے اسے قتل نہیں کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبدالرحمن سے فرمایا: ’’کیا تم (پچاس) قسمیں کھا کر اپنے مقتول کے بدلے کے حق دار بنتے ہو؟‘‘ انھوں نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر یہودی تمھارے سامنے (پچاس) قسمیں کھا لیں؟‘‘ انھوں نے کہا: وہ تو مسلمان نہیں (جھوٹی قسمیں کھا جائیں گے)۔ تب رسول اللہ صلی اللہ علیہ وسلم نے اس مقتول کی دایت اپنی طرف (بیت المال) سے ادا کر دی اور ان کو سو اونٹنیاں بھیج دیں۔ حتیٰ کہ ان کے گھر میں داخل کی گئیں۔ حضرت سہل نے فرمایا: ان میں سے ایک سرخ اونٹنی نے مجھے لات بھی ماری تھی۔","f2":"(۱) یہ حدیث مبارکہ قسامت کی مشروعیت کی صریح دلیل ہے۔ مسئلہ اب بھی اسی طرح ہے۔ جمہور اہل علم اسی کے قائل ہیں۔ (۲)اس حدیث سے معلوم ہوا کہ اہم معاملے میں بڑی عمر والے ہی کو مقدم کیا جائے۔ پہلے اسے بات کرنے کا موقع دیا جائے بشرطیکہ اس میں اس کی اہلیت ہو۔ ہاں اگر بڑی عمر والا ایسی صلاحیت سے عاری ہو تو پھر چھوٹے کی بات کا اعتبار ہوگا۔ (۳) قسامت میں قتل ثابت کرنے کے لیے بالجزم اور پختہ قسمیں کھانا ضروری ہے، مقتول شخص کو قتل ہوتے دیکھا ہو یا پھر کسی پختہ ذریعے سے قاتل کی اطلاع ملی ہو۔ اس کے علاوہ، محض گمان کی بنیاد پر قتل ثابت نہین ہوگا۔ (۴) عبداللہ بن سہل اور محیصہ آپس میں چچا زاد بھائی تھے۔ خیبر میں ان کی زمین تھی جو خیبر کی غنیمت سے ملی تھی۔ (۵) ’’حق دار بنتے ہو‘‘ بعض روایات میں پہلے یہودیوں سے قسم لینے کا ذکر ہے کیونکہ وہ مدعی علیہ تھے اور قسم مدعی علیہ کا حق ہے۔ اس حدیث میں مدعیان سے پہلے قسم لینے کا ذکر ہے۔ قسامت میں دوسری صورت کے مطابق ہی عمل ہوگا، اسی قسم کی روایات کو ترجیح حاصل ہے، اگرچہ عام معاملات میں مدعی کے ذمے دلیل اور مدعی علیہ پر قسم ہوتی ہے۔ واللہ اعلم"}],[4711,"سہل بن ابی حثمہ رضی اللہ عنہ کہتے ہیں کہ ان سے ان کے قبیلہ کے کچھ بڑوں نے بیان کیا کہ عبداللہ بن سہل اور محیصہ رضی اللہ عنہ تنگ حالی کی وجہ سے خیبر کی طرف نکلے، محیصہ رضی اللہ عنہ کے پاس کسی نے آ کر بتایا کہ عبداللہ بن سہل رضی اللہ عنہ مارے گئے، انہیں ایک کنویں یا چشمے میں پھینک دیا گیا ہے۔ محیصہ یہودیوں کے پاس آئے اور کہا: اللہ کی قسم! تم لوگوں نے اسے قتل کیا ہے، انہوں نے کہا: اللہ کی قسم! ہم نے انہیں قتل نہیں کیا، پھر وہ اپنے قبیلے کے پاس آئے اور ان سے اس کا تذکرہ کیا۔ پھر وہ، ان کے بھائی حویصہ (حویصہ ان سے بڑے تھے) اور عبدالرحمٰن بن سہل چلے۔ (اور رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے) تو محیصہ نے بات کرنی چاہی (وہی خیبر میں گئے) تھے تو رسول اللہ صلی اللہ علیہ وسلم نے محیصہ سے فرمایا: \"بڑے کا لحاظ کرو، بڑے کا لحاظ کرو\"۔ آپ کی مراد عمر میں بڑے ہونے سے تھی، چنانچہ حویصہ نے گفتگو کی پھر محیصہ نے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یا تو وہ تمہارے آدمی کی دیت دیں یا پھر ان سے جنگ کے لیے کہہ دیا جائے\"، رسول اللہ صلی اللہ علیہ وسلم نے انہیں اس بارے میں لکھ بھیجا تو ان لوگوں نے لکھا: اللہ کی قسم! ہم نے انہیں قتل نہیں کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبدالرحمٰن (رضی اللہ عنہم) سے کہا: \"کیا تم قسم کھاؤ گے اور اپنے آدمی کے خون کے حقدار بنو گے؟\" وہ بولے: نہیں، آپ نے فرمایا: \"تو پھر یہودی قسم کھائیں گے\"۔ وہ بولے: وہ تو مسلمان نہیں ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے ان کی دیت ادا کی اور سو اونٹنیاں ان کے پاس بھیجیں یہاں تک کہ وہ ان کے گھروں میں داخل ہو گئیں۔ سہل کہتے ہیں: ان میں سے ایک سرخ اونٹنی نے مجھے لات مار دی۔","الألباني: صحيح",{"u2":"حضرت ابو لیلیٰ بن عبداللہ سے روایت ہے کہ مجھے سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ اور میری قوم کے بزرگوں نے بتایا کہ عبداللہ بن سہل اور محیصہ رضی اللہ عنہ فاقوں کے مارے ہوئے خیبر کو گئے۔ محیصہ کام سے واپس آئے تو انھیں بتایا گیا کہ عبداللہ بن سہل کو قتل کر کے کنویں یا چشمے میں پھینک دیا گیا ہے۔ وہ یہودیوں کے پاس گئے اور کہا: اللہ کی قسم! تم نے اسے قتل کیا ہے۔ انھوں نے کہا: اللہ کی قسم! ہم نے اسے قتل نہیں کیا۔ وہ مدینہ منورہ اپنی قوم کے پاس آئے تو سارا واقعہ ان سے بیان کیا۔ پھر وہ خود، ان کے بڑے بھائی حویصہ اور عبدالرحمن بن سہل رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ محیصہ بات کرنے لگے کیونکہ خیبر میں وہی تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو پہلے بات کرنے دو۔‘‘ آپ کا مقصد تھا جو عمر میں بڑا ہے۔ حویصہ نے پہلے بات کی۔ پھر محیصہ نے بھی بات کی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یا تو وہ تمھارے مقتول کی دیت دیں گے ورنہ ان سے اعلان جنگ کر دیا جائے گا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے اس کی بابت ان (یہودیوں) کو خط لکھا۔ انھوں نے جواب میں لکھا: اللہ کی قسم! ہم نے اسے قتل نہیں کیا۔ تب رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبدالرحمن سے فرمایا: ’’تم (پچاس) قسمیں کھا کر اپنے مقتول کے خون کے حق دار بنتے ہو؟‘‘ انھوں نے کہا: آپ نے فرمایا: ’’پھر یہودی تمھارے سامنے قسمیں اٹھائیں گے۔‘‘ انھوں نے کہا: وہ تو مسلمان نہیں ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے مقتول کی دیت ادا فرما دی اور ان کے پاس سو اونٹنیاں بھیج دیں حتیٰ کہ وہ ان کے گھر میں داخل کی گئیں۔ حضرت سہل نے کہا: ان میں سے ایک سرخ اونٹنی نے مجھے لات ماری تھی۔"}],[4712,"سہل بن ابی حثمہ رضی اللہ عنہ اور رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ عبداللہ بن سہل بن زید اور محیصہ بن مسعود رضی اللہ عنہما نکلے، جب خیبر پہنچے تو کسی مقام پر وہ الگ الگ ہو گئے، پھر اچانک محیصہ کو عبداللہ بن سہل مقتول ملے، انہوں نے عبداللہ کو دفن کیا، پھر وہ، حویصہ بن مسعود اور عبدالرحمٰن بن سہل رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، عبدالرحمٰن ان میں سب سے چھوٹے تھے، پھر اپنے دونوں ساتھیوں سے پہلے عبدالرحمٰن بولنے لگے، تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"عمر میں جو بڑا ہے اس کا لحاظ کرو\" تو وہ خاموش ہو گئے اور ان کے دونوں ساتھی گفتگو کرنے لگے، پھر عبدالرحمٰن نے بھی ان کے ساتھ گفتگو کی، چنانچہ ان لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے عبداللہ بن سہل کے قتل کا تذکرہ کیا، تو آپ نے ان سے فرمایا: \"کیا تم پچاس قسمیں کھاؤ گے، پھر اپنے ساتھی کے خون کے حقدار بنو گے\" (یا کہا: اپنے قاتل کے) انہوں نے کہا: ہم کیوں کر قسم کھائیں گے جب کہ ہم وہاں موجود نہیں تھے، آپ نے فرمایا: \"تو پھر یہودی پچاس قسمیں کھا کر تمہارا شک دور کریں گے\"، انہوں نے کہا: ان کی قسمیں ہم کیوں کر قبول کر سکتے ہیں وہ تو کافر لوگ ہیں، جب یہ چیز رسول اللہ صلی اللہ علیہ وسلم نے دیکھی تو آپ نے ان کی دیت خود سے انہیں دے دی۔","الألباني: صحيح",{"u2":"حضرت سہل ابن ابی حثمہ اور حضرت رافع بن خدیج رضی اللہ عنہ نے فرمایا: حضرات عبداللہ بن سہل اور محیصہ بن مسعود رضی اللہ عنہ سفر کو نکلے حتیٰ کہ جب وہ خیبر پہنچے تو وہاں اپنے اپنے کام میں الگ الگ ہوگئے۔ پھر اچانک محیصہ نے عبداللہ بن سہل کو مقتول پایا۔ ان کو دفن کرنے کے بعد وہ خود، حویصہ بن مسعود اور عبدالرحمن بن سہل جو کہ سب سے چھوٹے تھے، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ عبدالرحمن (مقتول کا بھائی ہونے کے ناتے) اپنے دونوںساتھیوں سے پہلے بات کرنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: ’’عمر کے لحاظ سے بڑے کو پہلے بات کرنے دو۔‘‘ وہ چپ ہو گئے اور دیگر دو ساتھیوں نے باتیں کیں۔ پھر اس نے بھی ان کے ساتھ ساتھ باتیں کیں۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے عبداللہ بن سہل کے قتل کا معاملہ پیش کیا۔ آپ نے ان سے فرمایا: ’’کیا تم پچاس قسمیں کھا کر اپنے مقتول کے خون کے (بدلے) یا قاتل کے مستحق بنتے ہو؟‘‘ انھوں نے کہا: ہم کیسے قسم کھائیں جب کہ ہم تو مقع پر حاضر نہیں تھے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پھر یہودی پچاس قسمیں اٹھا کر بری ہو جائیں گے۔‘‘ انھوں نے کہا: ہم کافروں کی قسمیں کس طرح قبول کر لیں؟ جب رسول اللہ صلی اللہ علیہ وسلم نے یہ صورت حال دیکھی تو آپ نے (اپنی طرف سے) مقتول کی دیت دے دی۔","f2":"’’دیت دے دی‘‘ بیے گناہ مسلمان مقتول کا خوان رائیگاں نہیں ہوتا، اس لیے آپ نے بیت المال سے دیت ادا فرما دی۔ اس طرح جھگڑا ختم ہوگیا۔ یہ رسول اللہ صلی اللہ علیہ وسلم کی کامل بصیرت اور معاملہ فہمی تھی ورنہ وہ دیت کے حق دار نہیں تھے کیونکہ وہ خود قسمیں کھانے کے لیے تیار نہیں تھے اور مدعی علیہم کی قسموں کو مانتے نہ تھے۔"}],[4713,"سہل بن ابی حثمہ اور رافع بن خدیج رضی اللہ عنہما کہتے ہیں کہ محیصہ بن مسعود اور عبداللہ بن سہل رضی اللہ عنہما اپنی کسی ضرورت کے پیش نظر خیبر آئے، پھر وہ باغ میں الگ الگ ہو گئے، عبداللہ بن سہل کا قتل ہو گیا، تو ان کے بھائی عبدالرحمٰن بن سہل اور چچا زاد بھائی حویصہ اور محیصہ (رضی اللہ عنہم) رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، عبدالرحمٰن نے اپنے بھائی کے معاملے میں گفتگو کی حالانکہ وہ ان میں سب سے چھوٹے تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑوں کا لحاظ کرو، سب سے بڑا پہلے بات شروع کرے\"، چنانچہ ان دونوں نے اپنے آدمی کے بارے میں بات کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، آپ نے ایک ایسی بات کہی جس کا مفہوم یوں تھا: \"تم میں سے پچاس لوگ قسم کھائیں گے\"، انہوں نے کہا: اللہ کے رسول! ایک ایسا معاملہ جہاں ہم موجود نہ تھے، اس کے بارے میں کیوں کر قسم کھائیں؟ آپ نے فرمایا: \"تو پھر یہودی اپنے پچاس لوگوں کو قسم کھلا کر تمہارے شک کو دور کریں گے\"، وہ بولے: اللہ کے رسول! وہ تو کافر لوگ ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے ان کی دیت ادا کی۔ سہل رضی اللہ عنہ کہتے ہیں: جب میں ان کے «مربد» (باڑھ) میں داخل ہوا تو ان اونٹوں میں سے ایک اونٹنی نے مجھے لات مار دی۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ اور حضرت رافع بن خدیج رضی اللہ عنہ بیان کرتے ہیں کہ محیصہ بن مسعود اور عبداللہ بن سہل رضی اللہ عنہ اپنے کسی کام سے خیبر گئے اور کھجوروں کے درختوں میں الگ الگ ہوگئے۔ حضرت عبداللہ بن سہل قتل کر دیے گئے۔ ان کا بھائی عبدالرحمن بن سہل اور اس کے چچا زاد بھائی حویصہ اور محیصہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ عبدالرحمن نے اپنے بھائی کے بارے میں بات شروع کی جبکہ وہ ان تینوں میں سے چھوٹے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو بات کرنی چاہیے۔‘‘ پھر ان دو بھائیوں نے اپنے مقتول کے بارے میں بات کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے پچاس آدمی قسمیں اٹھائیں۔‘‘\nانھوں نے کہا: اے اللہ کے رسول! ہم تو موقع پر موجود نہیں تھے۔ ہم کیسے قسمیں اٹھائیں؟ آپ نے فرمایا: ’’پھر یہودی پچاس قسمیں دے کر تم سے بری ہو جائیں گے۔‘‘ وہ کہنے لگے: اے اللہ کے رسول! وہ کافر لوگ ہیں۔ (ان کی قسموں کا کیا اعتبار؟) تو رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے مقتول کی دیت ادا کر دی۔ حضرت سہل رضی اللہ تعالٰی عنہ نے فرمایا: میں ان کے اونٹوں کے باڑے میں داخل ہوا تو ان اونٹوں میں سے ایک اونٹنی نے مجھے لات ماری۔"}],[4714,"سہل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے کہ عبداللہ بن سہل، محیصہ بن مسعود بن زید خیبر رضی اللہ عنہما گئے، ان دنوں صلح چل رہی تھی، وہ اپنی ضرورتوں کے لیے الگ الگ ہو گئے، پھر محیصہ رضی اللہ عنہ عبداللہ بن سہل رضی اللہ عنہ کے پاس آئے (دیکھا کہ) وہ مقتول ہو کر اپنے خون میں لوٹ رہے تھے، تو انہیں دفن کیا اور مدینے آئے، پھر عبدالرحمٰن بن سہل، حویصہ اور محیصہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، تو عبدالرحمٰن نے بات کی وہ عمر میں سب سے چھوٹے تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑے کا لحاظ کرو\"، چنانچہ وہ خاموش ہو گئے، پھر ان دونوں نے بات کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اپنے پچاس آدمیوں کو قسم کھلاؤ گے تاکہ اپنے آدمی (کے خون بہا) یا اپنے قاتل (خون) کے حقدار بنو؟\" انہوں نے عرض کیا: اللہ کے رسول! ہم کیوں کر قسم کھائیں گے حالانکہ نہ ہم وہاں موجود تھے اور نہ ہی ہم نے دیکھا۔ آپ نے فرمایا: \"یہودی پچاس قسمیں کھا کر تمہارا شک دور کریں گے\"، وہ بولے: اللہ کے رسول! ہم کافروں کی قسم کا اعتبار کیوں کر کریں گے، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے ان کی دیت ادا کی۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ عبداللہ بن سہل اور محیصہ بن مسعود رضی اللہ عنہ خیبر گئے۔ ان دنوں (یہود خیبر سے) صلح تھی۔ وہ اپنے اپنے کام میں ادھر ادھر ہوگئے۔ پھر محیصہ، عبداللہ بن سہل کی طرف آئے تو وہ اپنے خون میں لتھڑے ہوئے مقتول پڑے تھے۔ انھوں نے انھیں دفن کیا۔ پھر وہ مدینہ منورہ آئے اور عبدالرحمن بن سہل، حویصہ اور محیصہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے۔ عبدالرحمن جو عمر میں ان سب سے چھوٹے تھے، بات کرنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو بات کرنے دو۔‘‘ وہ خاموش ہوگئے اور دوسرے دو بھائیوں نے بات چیت کی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا تم پچاس قسمیں اٹھا کر اپنے مقتول کے خون کے حق دار بنتے ہو؟‘‘ وہ کہنے لگے: اے اللہ کے رسول! ہم کیسے قسمیں کھائیں جبکہ ہم تو موقع پر موجود ہی نہ تھے اور نہ ہم نے کسی کو دیکھا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پھر یہودی پچاس قسمیں کھا کر تم سے بری ہو جائیں گے۔‘‘ انھوں نے کہا: اے اللہ کے رسول! ہم کافر لوگوں سے کیسے قسمیں اٹھوائیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے مقتول کی دیت اپنی طرف سے ادا فرما دی۔"}],[4715,"سہل بن ابی حثمہ رضی اللہ عنہ کہتے ہیں کہ عبداللہ بن سہل اور محیصہ بن مسعود بن زید رضی اللہ عنہما خیبر کی طرف چلے، اس وقت صلح چل رہی تھی، محیصہ اپنے کام کے لیے جدا ہو گئے، پھر وہ عبداللہ بن سہل رضی اللہ عنہ کے پاس آئے تو دیکھا کہ ان کا قتل ہو گیا ہے اور وہ مقتول ہو کر اپنے خون میں لوٹ پوٹ رہے تھے، انہیں دفن کیا اور مدینے آئے، عبدالرحمٰن بن سہل اور مسعود کے بیٹے حویصہ اور محیصہ (رضی اللہ عنہم) رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، عبدالرحمٰن بن سہل رضی اللہ عنہ بات کرنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"بڑوں کا لحاظ کرو\"، وہ لوگوں میں سب سے چھوٹے تھے، تو وہ چپ ہو گئے، پھر انہوں(حویصہ اور محیصہ) نے بات کی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اپنے پچاس آدمیوں کو قسم کھلاؤ گے تاکہ تم اپنے قاتل (کے خون)، یا اپنے آدمی کے خون (بہا) کے حقدار بنو\"، ان لوگوں نے کہا: اللہ کے رسول! ہم قسم کیوں کر کھائیں گے، نہ تو ہم وہاں موجود تھے اور نہ ہم نے انہیں دیکھا، آپ نے فرمایا: \"تو کیا پچاس یہودیوں کی قسموں سے تمہارا شک دور ہو جائے گا؟\" وہ بولے: اللہ کے رسول! ہم کافروں کی قسم کا اعتبار کیوں کر کریں، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے ان کی دیت ادا کی۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ عبداللہ بن سہل اور محیصہ بن مسعود بن زید خیبر گئے۔ اور ان دنوں (یہود خیبر سے) صلح تھی۔ وہ اپنے اپنے کام میں الگ ہو گئے۔ پھر محیصہ، عبداللہ بن سہل کی طرف آئے تو انھیں خون میں لت پت پایا۔ خیر! انھوں نے انھیں دفن کیا۔ پھر وہ مدینہ منورہ پہنچے اور حضرت عبدالرحمن بن سہل اور اپنے بھائی حویصہ بن مسعود کو لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ (مقتول کے بھائی) عبدالرحمن جو سب سے چھوٹے تھے، بات کرنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: ’’بڑے کو بات کرنے دو۔‘‘ وہ چپ ہوگئے۔ دوسرے دو حضرات نے بات چیت کی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا تم پچاس قسمیں کھا کر اپنے ساتھی یا قاتل کے حق دار بنتے ہو؟‘‘ وہ کہنے لگے: اے اللہ کے رسول! ہم کیسے قسمیں کھائیں جب کہ ہم موقع پر موجود نہیں تھے اور نہ ہم نے کسی (قاتل) کو دیکھا ہے؟ آپ نے فرمایا: ’’پھر یہودی پچاس قسمیں کھا کر بری ہو جائیں گے۔‘‘ انھوں نے کہا: اے اللہ کے رسول! ہم کافر لوگوں کی قسمیں کیسے قبول کریں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت اپنی طرف سے ادا فرما دی۔","f2":"’’اپنی طرف سے‘‘ یعنی بیت المال سے، کیونکہ بیت المال آپ کے ماتحت تھا۔"}],[4716,"سہل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے کہ عبداللہ بن سہل انصاری اور محیصہ بن مسعود رضی اللہ عنہما خیبر کی طرف نکلے پھر اپنی ضرورتوں کے لیے الگ الگ ہو گئے اور عبداللہ بن سہل انصاری رضی اللہ عنہ کا قتل ہو گیا۔ چنانچہ محیصہ، مقتول کے بھائی عبدالرحمٰن اور حویصہ بن مسعود رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو عبدالرحمٰن بات کرنے لگے۔ تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"بڑوں کا لحاظ کرو، بڑوں کا لحاظ کرو\"۔ پھر محیصہ اور حویصہ رضی اللہ عنہما نے گفتگو کی اور عبداللہ بن سہل رضی اللہ عنہ کا معاملہ بیان کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں پچاس قسمیں کھانی ہوں گی، پھر تم اپنے قاتل کے (خون کے) حقدار بنو گے\"، وہ بولے: ہم قسم کیوں کر کھائیں، نہ ہم موجود تھے اور نہ ہم نے دیکھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تو پھر یہودی پچاس قسمیں کھا کر تمہارے شک کو دور کریں گے\"۔ وہ بولے: ہم کافروں کی قسمیں کیسے قبول کریں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان کی دیت ادا کی۔ بشیر کہتے ہیں: مجھ سے سہل بن ابی حثمہ رضی اللہ عنہ نے کہا: دیت میں دی گئی ان اونٹنیوں میں سے ایک اونٹنی نے ہمارے «مربد» (باڑھ) میں مجھے لات ماری۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ عبداللہ بن سہل انصاری اور محیصہ بن مسعود دونوں خیبر گئے۔ وہاں وہ اپنے اپنے کام میں ادھر ادھر ہوگئے تو عبداللہ بن سہل انصاری قتل کر دیے گئے۔ پھر محیصہ، مقتول کا بھائی عبدالرحمن اور حویصہ بن مسعود رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ عبدالرحمن بات شروع کرنے لگے تو نبی اکرم صلی اللہ علیہ وسلم نے انھیں فرمایا: ’’بڑے کو پہلے بات کرنے دو۔‘‘ تو محیصہ اور حویصہ نے بات شروع کی اور عبداللہ بن سہل کے قتل کا واقعہ بیان کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم پچاس قسمیں کھا کر اپنے قاتل کا مواخذہ کر سکتے ہو؟‘‘ وہ کہنے لگے: ہم کیسے قسمیں کھائیں ہم تو وہاں موجود نہیں تھے اور نہ ہم نے واقعہ دیکھا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پھر یہودی پچاس قسمیں کھا کر بری ہو جائیں گے۔‘‘ انھوں نے کہا: اے اللہ کے رسول! ہم کافر لوگوں کی قسمیں کیسے قبول کریں! پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت خود ادا فرما دی۔ حضرت سہل نے فرمایا: ہمارے باڑے میں ان اونٹوں میں سے ایک اونٹنی نے مجھے لات بھی ماری تھی۔"}],[4717,"سہل بن ابی حثمہ رضی اللہ عنہ کہتے ہیں کہ عبداللہ بن سہل رضی اللہ عنہ مقتول پائے گئے، تو ان کے بھائی اور ان کے چچا حویصہ اور محیصہ رضی اللہ عنہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، عبدالرحمٰن رضی اللہ عنہ بات کرنے لگے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑوں کا لحاظ کرو، بڑوں کا لحاظ کرو\"، ان دونوں نے کہا: اللہ کے رسول! ہم نے خیبر کے ایک کنویں میں عبداللہ بن سہل کو مقتول پایا ہے، آپ نے فرمایا: \"تمہارا شک کس پر ہے؟\" انہوں نے کہا: ہمارا شک یہودیوں پر ہے، آپ نے فرمایا: \"کیا تم پچاس قسمیں کھاؤ گے کہ یہودیوں نے ہی انہیں قتل کیا ہے؟\"، انہوں نے کہا: جسے ہم نے دیکھا نہیں، اس پر قسم کیسے کھائیں؟ آپ نے فرمایا: \"تو پھر یہودیوں کی پچاس قسمیں کہ انہوں نے عبداللہ بن سہل کو قتل نہیں کیا ہے، تمہارے شک کو دور کریں گی؟\" وہ بولے: ہم ان کی قسموں پر کیسے رضامند ہوں جبکہ وہ مشرک ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے ان کی دیت ادا کی۔ مالک بن انس نے اسے مرسلاً روایت کیا ہے (یعنی سہل بن ابی حثمہ کا ذکر نہیں کیا ہے)۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ نے فرمایا: حضرت عبداللہ بن سہل مقتول پائے گئے۔ ان کا بھائی اور اس کے دو چچے حویصہ اور محیصہ، اور وہ دونوں عبداللہ بن سہل کے بھی چچے تھے، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پیش ہوئے۔ (ان کا بھائی) عبدالرحمن بات کرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو بات کرنے دو۔‘‘ انھوں نے کہا: اے اللہ کے رسول! ہم نے عبداللہ بن سہل کو خیبر کے ایک کنویں میں مقتول پایا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم کن پر الزام لگاتے ہو؟‘‘ انھوں نے کہا: ہم یہودیوں پر الزام لگاتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم پچاس قسمیں کھاتے ہو کہ یہودیوں نے اسے قتل کیا ہے؟‘‘ وہ کہنے لگے: ہم ایسی چیز کی قسم کیسے کھا سکتے ہیں جو ہم نے نہیں دیکھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پھر یہودی پچاس قسمیں کھا کر کہ ہم نے اسے قتل نہیں کیا، بری ہو جائیں گے۔‘‘ وہ کہنے لگے: ہم ان مشرکوں کی قسمیں کیسے تسلیم کر لیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے دیت اپنی طرف سے ادا فرما دی۔\nمالک بن انس نے یہ روایت مرسل بیان کی ہے۔","f2":"’’مالک بن انس نے یہ روایت مرسل بیان کی‘‘ امام مالک رحمہ اللہ یہ روایت دو اساتذہ سے بیان کرتے ہیں: ابو لیلیٰ اور یحییٰ بن سعید سے۔ جب وہ یحییٰ بن سعید سے بیان کرتے ہیں تو مرسل بیان کرتے ہیں، یعنی سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ کا واسطہ ذکر نہیں کرتے۔ جب ابو لیلیٰ سے بیان کرتے ہیں تو موصول بیان کرتے ہیں، اس لیے امام مالک کی یہ روایت شواہد ومتابعات کی بنا پر صحیح ہے۔ یحییٰ بن سعید کی روایت (۴۷۲۲) آئندہ آرہی ہے جبکہ ابو لیلیٰ سے مروی روایت اس سے قبل (ہدیث: ۴۷۱۴) گزر چکی ہے۔"}],[4718,"بشیر بن یسار بیان کرتے ہیں کہ عبداللہ بن سہل انصاری اور محیصہ بن مسعود رضی اللہ عنہما خیبر کی طرف نکلے، پھر وہ اپنی ضرورتوں کے لیے الگ الگ ہو گئے اور عبداللہ بن سہل رضی اللہ عنہ کا قتل ہو گیا، محیصہ رضی اللہ عنہ آئے تو وہ اور ان کے بھائی حویصہ اور عبدالرحمٰن بن سہل رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، عبدالرحمٰن رضی اللہ عنہ مقتول کے بھائی ہونے کی وجہ سے بات کرنے لگے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑوں کا لحاظ کرو، بڑوں کا لحاظ کرو\"، چنانچہ حویصہ اور محیصہ رضی اللہ عنہما نے بات کی اور عبداللہ بن سہل کا واقعہ بیان کیا تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"کیا تم پچاس قسمیں کھاؤ گے کہ اپنے آدمی یا اپنے قاتل کے خون کے حقدار بنو؟\"۔ مالک کہتے ہیں: یحیی نے کہا: بشیر نے یہ بھی بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے ان کی دیت ادا کی۔ سعید بن طائی نے ان راویوں کے برعکس بیان کیا ہے ۱؎۔\n§وضاحت\n۱؎: سعید بن طائی کی روایت میں مقتول کے اولیاء سے قسم کھانے کے بجائے گواہ پیش کرنے، پھر مدعی علیہم سے قسم کھلانے کا ذکر ہے۔ امام بخاری نے اسی روایت کو ترجیح دی ہے، :(دیات ۲۲ ) بقول امام ابن حجر: بعض رواۃ نے گواہی کا تذکرہ نہیں کیا ہے اور بعض نے کیا ہے، بس اتنی سی بات ہے، حقیقت میں نبی اکرم صلی اللہ علیہ وسلم نے پہلے گواہی طلب کی اور گواہی نہ ہونے پر قسم کی بات کہی، اور جب مدعی یہ بھی نہیں پیش کر سکے تو مدعا علیہم سے قسم کی بات کی، اس بات کی تائید عبداللہ بن عمرو رضی اللہ عنہما کی اگلی روایت سے بھی ہو رہی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت بشیر بن یسار نے بتایا کہ عبداللہ بن سہل انصاری اور محیصہ بن مسعود رضی اللہ عنہ خیبر گئے اور اپنے اپنے کاموں میں ادھر ادھر ہوگئے تو عبداللہ بن سہل قتل کر دیے گئے۔ محیصہ مدینہ منورہ آئے اور اپنے بھائی حویصہ اور (مقتول کے بھائی) عبدالرحمن بن سہل سمیت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے (مقتول عبداللہ کے) بھائی ہونے کی وجہ سے عبدالرحمن بات کرنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو پہلے بات کرنے دو۔‘‘ پھر حویصہ اور محیصہ نے آپ سے بات چیت کی اور عبداللہ بن سہل کا مسئلہ پیش کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: ’’تم پچاس قسمیں کھا کر اپنے مقتول کے خون یا اپنے قاتل کے مستحق بنتے ہو‘‘","f2":"امام مالک رحمہ اللہ بیان کرتے ہیں کہ یحییٰ بن سعید نے کہا: بشیر بن یسار نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے انھیں اپنے پاس (بیت المال) سے دیت ادا فرما دی۔\nسعید بن عبید الطائی نے ان (بشیر بن یسار سے روایت کرنے والوں) کی مخالفت کی ہے۔\nفائدہ: اس کی وضاحت یہ ہے کہ بشیر بن یسار سے بیان کرنے والے دیگر روائِ حدیث نے صرف قسمیں لینے کا ذکر کیا ہے گواہوں کا نہیں جبکہ سعید بن عبید طائی نے (حدیث: ۴۷۲۳ میں) جب بشیر بن یسار سے بیان کیا تو دیگر راویوں کے برعکس یہ کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے مدعیوں، یعنی حویصہ، محیصہ اور عبدالرحمن کے دعویٰ کرنے پر ان سے فرمایا تھا: ’’تم اپنے اس دعویٰ پر کہ ہمارے آدمی کو یہودیوں نے قتل کیا ہے، گواہ پیش کرو۔‘‘ انھوں نے کہا کہ ہمارے پاس گواہ نہیں ہیں۔ بعد ازاں آپ نے ان سے قسموں کی بات کی۔ اس کی تفصیل آئندہ روایت میں ملاحظہ کریں۔"}],[4719,"بشیر بن یسار سے روایت ہے کہ سہل بن ابی حثمہ نامی ایک انصاری شخص نے ان سے بیان کیا کہ ان کے قبیلہ کے کچھ لوگ خیبر کی طرف چلے، پھر وہ الگ الگ ہو گئے، تو انہیں اپنا ایک آدمی مرا ہوا ملا، انہوں نے ان لوگوں سے جن کے پاس مقتول کو پایا، کہا: ہمارے آدمی کو تم نے قتل کیا ہے، انہوں نے کہا: نہ تو ہم نے قتل کیا ہے اور نہ ہمیں قاتل کا پتا ہے، تو وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس گئے اور عرض کیا: اللہ کے نبی! ہم خیبر گئے تھے، وہاں ہم نے اپنا ایک آدمی مقتول پایا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑوں کا لحاظ کرو، بڑوں کا لحاظ کرو\" ۱؎، پھر آپ نے ان سے فرمایا: \"تمہیں قاتل کے خلاف گواہ پیش کرنا ہو گا\"، وہ بولے: ہمارے پاس گواہ تو نہیں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو وہ قسم کھائیں گے\"، وہ بولے: ہمیں یہودیوں کی قسمیں منظور نہیں، پھر رسول اللہ صلی اللہ علیہ وسلم کو گراں گزرا کہ ان کا خون بیکار جائے، تو آپ نے انہیں صدقے کے سو اونٹ کی دیت ادا کی۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) عمرو بن شعیب نے ان (یعنی اوپر مذکور رواۃ) کی مخالفت کی ہے ۲؎۔\n§وضاحت\n۱؎: یہاں پر یہ ذکر نہیں ہے کہ عمر میں چھوٹے آدمی :(عبدالرحمٰن مقتول کے بھائی ) نے رسول اللہ صلی اللہ علیہ وسلم سے بات شروع کی تو آپ نے ادب سکھایا کہ بڑوں کو بات کرنی چاہیئے اور چھوٹوں کو خاموش رہنا چاہیئے۔ ملاحظہ ہو: سابقہ احادیث۔ ۲؎: عمرو بن شعیب نے اپنی روایت میں عبداللہ بن سہل کے بجائے ابن محیصہ الاصغر کو مقتول کہا ہے، اور یہ کہا ہے کہ مدعیان سے شہادت طلب کرنے کے بعد اسے نہ پیش کر پانے کی صورت میں ان سے قسم کھانے کو کہا گیا۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ نے بتایا کہ میری قوم کے کچھ آدمی خیبر گئے۔ وہاں وہ الگ الگ ہو گئے۔ انھوں نے اپنے میں سے ایک شخص کو مقتل پایا تو ان لوگوں سے، جن کے پاس اس کی لاش پائی گئی تھی، کہا: تم نے ہمارے آدمی کو قتل کیا ہے؟ انھوں نے کہا: ہم نے اسے قتل نہیں کیا اور نہ ہم اس کے قاتل کو جانتے ہیں۔ پھر وہ اللہ کے نبی صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اے اللہ کے نبی! ہم خیبر گئے تھے۔ وہاں ہم نے اپنے ایک آدمی کو مقتول پایا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے کو بات کرنے دو۔‘‘ آپ نے ان سے فرمایا: ’’تم اپنے مقتول کے قاتل کے بارے میں گواہی گواہ پیش کرو۔‘‘ وہ کہنے لگے: ہمارے پاس تو کوئی گواہ نہیں۔ آپ نے فرمایا: ’’پھر وہ تمہارے سامنے قسمیں کھائیں گے (اور بری ہو جائیں گے)۔‘‘ وہ کہنے لگے: ہم تو یہودیوں کی قسم کا اعتبار نہیں کرتے۔ رسول اللہ صلی اللہ علیہ وسلم نے پسند نہ فرمایا کہ اس کا خون بلا معاوضہ رہے، لہٰذا آپ نے صدقے کے اونٹوں میں سے سو اونٹ دیت کے طور پر دے دیے۔\nعمرو بن شعیب نے ان (حدیث بیان کرنے والے باقی تمام رواۃ) کی مخالفت کی ہے۔","f2":"(۱) اس مخالفت کی وضاحت یہ ہے کہ یہ حدیث بیان کرنے والے باقی تمام راوی یہ بیان کرتے ہیں کہ مقتول عبداللہ بن سہل ہیں جوکہ محیصہ کے چچا زاد بھائی ہیں جبکہ عمرو بن شعیب کہتے ہیں (جیسا کہ آئندہ حدیث میں ہے) کہ مقتول محیصہ کا چھوٹا بیٹا ہے، یعنی عبداللہ بن سہل مقتول نہیں۔ دوسری مخالفت یہ ہے کہ دیگر تمام راویوں کے برعکس انھوں نے یہ روایت اپنے پردادا حضرت عبداللہ بن عمرو رضی اللہ عنہ سے بیان کی ہے جبکہ تمام رواۃ نے حضرت سہل بن ابی حثمہ رضی اللہ تعالٰی عنہ سے بیان کی ہے۔ تیسری مخالفت یہ ہے کہ یہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دیت یہودیوں پر تقسیم کر دی تھی ور ان کے ساتھ تعاون کرتے ہوئے نصف دیت، یعنی پچاس اونٹ اپنے ذمے لیے تھے جبکہ تمام راوی کہتے ہیں کہ پوری کی پوری دیت، یعنی سو اونٹ اور اونٹنیاں رسول اللہ نے اپنی طرف سے (بیت المال سے) ادا فرمائی تھی۔ اس حدیث میں بیان کی گئی تفصیل درست نہیں بلکہ جو تفصیل دیگر راویوں نے بیان کی ہے وہی درست اور صحیح ہے۔ اس روایت میں صحیح روایات اور بہت سے ثقہ راویوں کی مخالفت کی گئی ہے، اس لیے یہ روایت شاذ، یعنی ضعیف ہے جبکہ اس کے مقابلے میں دوسری روایات محفوظ، یعنی صحیح ہیں۔ واللہ اعلم۔ (۲)گواہی کا ذکر صرف سعید بن عبید طائی کی روایت میں ہے۔ دیگر رواۃ نے گواہی کا ذکر نہیں کیا۔ تفصیلی روایات، جو کہ بخاری ومسلم کی ہیں، میں یہی ذکر ہے کہ آپ نے پہلے مدعین سے قسمیں اٹھانے کا مطالبہ کیا۔ ان کے انکار پر مدعی علیہم سے قسموں کا ماطلبہ کیا۔ اس لحاظ سے گواہی کا ذکر سعید بن عبید طائی کا شذوذ معلوم ہوتا ہے۔ ممکن ہے [خَالَفَھُمْ سَعِیْدُ بْنُ عُبَیْدِ نِ الطَّائِیُّ] سے امام نسائی رحمہ اللہ کا مقصد اسی طرف اشارہ کرنا ہو۔"}],[4720,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ محیصہ کے چھوٹے بیٹے کا خیبر کے دروازوں کے پاس قتل ہو گیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"دو گواہ لاؤ کہ کس نے قتل کیا ہے، میں اسے اس کی رسی سمیت تمہارے حوالے کروں گا\"، وہ بولے: اللہ کے رسول! ہمیں گواہ کہاں سے ملیں گے؟ وہ تو انہیں کے دروازے پر قتل ہوا ہے، آپ نے فرمایا: \"تو پھر تمہیں پچاس قسمیں کھانی ہوں گی\"، وہ بولے: اللہ کے رسول! جسے میں نہیں جانتا اس پر قسم کیوں کر کھاؤں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تو تم ان سے پچاس قسمیں لے لو\"، وہ بولے: اللہ کے رسول! ہم ان سے قسمیں کیسے لے سکتے ہیں وہ تو یہودی ہیں، تو آپ نے اس کی دیت یہودیوں پر تقسیم کی اور آدھی دیت دے کر ان کی مدد کی۔\n§وضاحت\n۱؎: امام نسائی نے اس روایت پر نقد یہ کہہ کر کیا کہ عمرو بن شعیب نے ان رواة کی مخالفت کی، اس کی تفصیل یہ ہے کہ اوپر گزری روایتوں سے اس روایت میں تین جگہ مخالفت ہے: اس میں مقتول کا نام عبداللہ بن سہل کے بجائے ابن محیصہ ہے، اور مدعی سے قسم سے پہلے گواہ پیش کرنے کی بات ہے،، نیز اس میں یہ ہے کہ آدھی دیت یہودیوں پر مقرر کی، دوسری شق کی تائید کہیں نہ کہیں سے ہو جاتی ہے لیکن بقیہ دو باتیں بالکل شاذ ہیں۔ اس حدیث کے راوی عبید اللہ بن اخنس، بقول ابن حبان: روایت میں بہت غلطیاں کرتے تھے۔","الألباني: شاذ",{"u2":"حضرت عمرو بن شعیب کے پردادا محترم (حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ محیصہ کا چھوٹا بیٹا خیبر کے دروازوں پر مقتول پایا گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس کے قاتل کے دو عینی گواہ لاؤ، میں اسے اس کی رسی سمیت (گرفتار کر کے) تیرے سپرد کر دوں گا۔‘‘ وہ کہنے لگا: اے اللہ کے رسول! میں دو گواہ کہاں سے لاؤں؟ وہ تو ان یہودیوں کے دروازوں کے سامنے مارا گیا ہے۔ آپ نے فرمایا: ’’اچھا تو قسامت کی پچاس (قسمیں) کھا لے۔‘‘ اس نے کہا: اے اللہ کے رسول! میں اس بات پر کس طرح قسمیں کھاؤں جو میں جانتا نہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پھر تم ان سے قسامت کی پچاس قسمیں لے لو۔‘‘ وہ کہنے لگا: اے اللہ کے رسول! ہم ان سے کیسے قسمیں لیں، وہ تو یہودی ہیں (جھوٹے مشہور ہیں)؟ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت یہودیوں پر تقسیم کر دی اور نصف دیت میں آپ نے ان سے تعاون فرمایا۔","f2":"محقق کتاب نے اس روایت کو سند کو حسن قرار دیا ہے لیکن راجح بات یہ ہے کہ یہ روایت شاذ (ضعیف کی ایک قسم) ہے۔ مزید سابقہ حدیث کی وضاحت ملاحظہ فرمائیے۔"}],[4721,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان کا خون بہانا جائز تین صورتوں کے علاوہ جائز نہیں ہے: جان کے بدلے جان ۱؎، جس کا نکاح ہو چکا ہو وہ زنا کرے، جو دین چھوڑ دے اور اس سے پھر جائے\"۔\n§وضاحت\n۱؎: اسی لفظ سے \" قصاص \" کا حکم ثابت ہوتا ہے۔ شرط یہ ہے کہ جان ناحق لی گئی ہو۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی مسلمان آدمی کا خون بہانا جائز نہیں، البتہ تین جرموں میں اسے قتل کیا جا سکتا ہے: اس نے کسی کو مار دیا ہو تو اسے اس کے بدلے میں قتل کیا جائے گا یا شادی شدک شخص زنا کرے یا جو شخص دین اسلام چھوڑ کر مسلمانوں کی جماعت سے الگ ہو جائے۔‘‘","f2":"(۱) اسلام نے قصاص مشروع قرار دیا ہے، البتہ ورثاء مقتول معافی پر راضی ہو جائیں تو دیت ادا کرنی ہوگی، لیکن صرف یہ قتل عمد میں ہوتا ہے، قتل خطا میں نہیں۔ قتل خطا یہ ہے کہ گولی تو چلائی گئی کسی جانور پر مگر اچانک کوئی شخص آگے آگیا اور گولی اسے لگ گئی یا یہ سمجھ کر گولی چلائی گئی کہ یہ کوئی جانور ہے، گولی معلوم ہوا کہ یہ تو انسان ہے۔ ایسی صورت میں قصاص نہیں ہوگا، البتہ دیت دینا ضروری ہے کیونکہ مسلمانوں کا خون رائیگاں نہیں ہو سکتا۔ (۲) قصاص کا ڈر قاتل کو قتل سے روکتا ہے، نیز قصاص لینے سے ناحق خون ریزی سے بچت ہوتی ہے۔ لڑائی نہیں پھیلتی۔ (۳)قصاص کا عام قانون یہی ہے جو حدیث مبارکہ میں بیان کیا گیا ہے، تاہم اگر کوئی شخص کسی پر ناجائز طور پر قاتلہ حملے کرے اور پھر دفاع میں حملہ آور مارا جائے تو ایسے شخص سے بھی قصاص نہیں لیا جائے گا۔"}],[4722,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں قتل کر دیا گیا، قاتل کو نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا، تو آپ نے اسے مقتول کے ولی کے حوالے کر دیا ۱؎، قاتل نے کہا: اللہ کے رسول! میرا ارادہ قتل کا نہ تھا، آپ نے مقتول کے ولی سے فرمایا: \"سنو! اگر وہ سچ کہہ رہا ہے اور تم نے اسے قتل کر دیا تو تم بھی جہنم میں جاؤ گے\"، تو اس نے اسے چھوڑ دیا۔ وہ شخص رسی سے بندھا ہوا تھا، وہ اپنی رسی گھسیٹتا ہوا نکلا تو اس کا نام ذوالنسعۃ (رسی والا) پڑ گیا۔\n§وضاحت\n۱؎: اس لیے حوالہ کر دیا کہ وہ اس کو قصاص میں قتل کر دیں، اسی سے قصاص کی مشروعیت ثابت ہوتی ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے دور میں ایک آدمی قتل ہوگیا۔ قاتل کو پکڑ کر نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں پیش کیا گیا۔ آپ نے اسے مقتول کے وارث کے سپرد کر دیا۔ قاتل کہنے لگا: اے اللہ کے رسول! اللہ کی قسم! میرا ارادہ اسے قتل کرنے کا نہیں تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے مقتول کے وارث سے فرمایا: ’’اگر یہ سچا ہوا اور تو نے اسے قتل کر دیا تو تو آگ میں جائے گا۔‘‘ اس نے اسے چھوڑ دیا۔ وہ قاتل چمڑے کی رسی سے بندھا ہوا تھا۔ وہ اسی طرح اپنی رسی کو گھسیٹتا ہوا نکلا تو اس کا نام ہی ذوالنسعہ (تندی یا رسی والا) پڑ گیا۔","f2":"(۱) مقتول کے وارث کو چاہیے کہ وہ قصاص لینے میں جلدی نہ کرے بلکہ معاف کر دے۔ اگرچہ قصاص لینا جائز ہے، تاہم معاف کرنا بہت بڑی نیکی ہے۔ ممکن ہے قاتل بے گناہ ہو یا اس نے جان بوجھ کر قتل نہ کیا ہو وغیرہ۔ (۲)اس حدیث سے یہ اشارہ بھی نکلتا ہے کہ اگر کسی شخص کو اس کے کسی پیشے یا کسی اور خصوصیت کی وجہ سے کوئی لقب دیا جائے اور وہ اسے برا نہ سمجھے تو اس کا جواز ہے جیسا کہ حدیث میں مذکور شخص کو حضرات صحابہ کرام رضی اللہ عنہم ذوالنسعہ (رسی یا تندی والا) کہا کرتے تھے، یعنی اس کے گلے وغیرہ میں پڑی رسی کی وجہ سے اس کا لقب ہی ذوالنسعہ پڑ گیا۔ (۳) ’’سپرد کر دیا‘‘ شریعت کی رو سے قصاص کا حق مقتول کے ورثاء کو ہے۔ وہ چاہیں تو قتل کریں، چاہیں معاف کر دیں، اس لیے آپ نے قاتل کو مقتول کے ولی کے سپرد کر دیا۔ یہ ضروری نہیں کہ حکومت خود قتل کرے، تاہم جج کے فیصلے سے پہلے از خود ہی قاتل کو قتل کرنا درست نہیں کیونکہ یہ قانون کو ہاتھ میں لینے والی بات ہے، البتہ جب قاضی قاتل حوالے کرے تو پھر اسے قتل کرنا جائز ہے۔ (۴) ’’آگ میں جائے گا۔‘‘ کیونکہ جان بوجھ کر قتل کرنے والے ہی کو قصاصاً قتل کیا جا سکتا ہے۔ قاتل کے بیان کے مطابق اس سے یہ قتل عمداً سرزد نہیں ہوا تھا، لہٰذا وہ قتل کا مستحق نہیں تھا لیکن آپ کا قاتل کو مقتول کے ورثاء کے حوالے کر دینا یہ بتانا ہے کہ اس قتل کی ظاہری صورت عمد (جان بوجھ کر قتل کرنے) ہی کی تھی۔ قاتل کی نیت کو تو اللہ تعالیٰ ہی بہتر جانتا ہے۔ گویا ایسی صورت میں بھی مقتول کے ورثاء کو چاہیے کہ وہ قاتل کی جان بخشی کر دیں تاکہ کوئی شخص ناحق قتل نہ ہو۔ اگرچہ قاضی ظاہر حالات کے مطابق ہی فیصلہ کرے گا، تاہم مقتول کے ورثاء یہ رعایت دے سکتے ہیں۔"}],[4723,"وائل حضرمی رضی اللہ عنہ کہتے ہیں کہ اس قاتل کو جس نے قتل کیا تھا، رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، اسے مقتول کا ولی پکڑ کر لایا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم معاف کرو گے؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"کیا قتل کرو گے؟\" اس نے کہا: ہاں، آپ نے فرمایا: \"جاؤ (قتل کرو)\"، جب وہ(قتل کرنے) چلا تو آپ نے اسے بلا کر کہا: \"کیا تم معاف کرو گے؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"کیا دیت لو گے؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"تو کیا قتل کرو گے؟\" اس نے کہا: ہاں، آپ نے فرمایا: \"جاؤ (قتل کرو)\"، جب وہ (قتل کرنے) چلا، تو آپ نے فرمایا: \"اگر تم اسے معاف کر دو تو تمہارا گناہ اور تمہارے (مقتول) آدمی کا گناہ اسی پر ہو گا\" ۱؎، چنانچہ اس نے اسے معاف کر دیا اور اسے چھوڑ دیا، میں نے اسے دیکھا کہ وہ اپنی رسی گھسیٹتا جا رہا تھا ۲؎۔\n§وضاحت\n۱؎: حدیث کا ظاہری مفہوم یہ ہے کہ بلا کچھ لیے دئیے ولی کے معاف کر دینے کی صورت میں ولی اور مقتول دونوں کے گناہ کا حامل قاتل ہو گا، لیکن اس میں اشکال ہے کہ ولی کے گناہ کا حامل کیونکر ہو گا، اس لیے حدیث کے اس ظاہری مفہوم کی توجیہ کچھ اس طرح کی گئی ہے کہ ولی کے معاف کر دینے کے سبب رب العالمین ولی اور مقتول دونوں کو مغفرت سے نوازے گا اور قاتل اس حال میں لوٹے گا کہ مغفرت کے سبب ان دونوں کے گناہ زائل ہو چکے ہوں گے۔ ۲؎: یہ وہی آدمی ہے جس کا تذکرہ پچھلی حدیث میں گزرا۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل حضرمی رضی اللہ تعالٰی عنہ سے روایت ہے کہ قاتل کو رسول اللہ صلی اللہ علیہ وسلم کے پاس پیش کیا گیا۔ اسے مقتول کا وارث لے کر آیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ’’کیا تو اسے معاف کرتا ہے؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’اسے قتل کرے گا؟‘‘ اس نے کہا: ہاں۔ آپ نے فرمایا: ’’جاؤ۔‘‘ جب وہ چل پڑا تو آپ نے اسے بلایا اور فرمایا: ’’کیا تو معاف کرتا ہے؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’تو دیت لے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر تو قتل کرے گا؟‘‘ اس نے کہا: ہاں۔ فرمایا: ’’جاؤ۔‘‘ جب وہ چل پڑا تو آپ نے فرمایا: ’’اگر تو اسے معاف کر دے تو وہ تیرے اور تیرے مقتول کے گناہ کا ذمہ دار ہوگا۔‘‘ اس نے اسے معاف کر دیا اور چھوڑ دیا۔ میں نے قاتل کو دیکھا، وہ اپنی تندی (یا رسی) کو گھسیٹتا ہوا جا رہا تھا۔","f2":"(۱) جج اور حاکم کے لیے مشروع اور جائز ہے کہ وہ مقتول کے ورثاء کو، معاف کرنے کی ترغیب دیں، لیکن انھیں بذات خود کسی مجرم اور قاتل کو معاف کرنے کا کوئی حق نہیں۔ اگر حاکم وقت یا فیصلہ کرنے والا جج از خود کسی قاتل کو، جرم ثابت ہونے کے باوجود معاف کرے گا تو یہ صریح ظلم اور عدل وانصاف کا خون کرنے کے مترادف ہوگا۔ ہمارے ہاں جو یہ رائج ہے کہ تمام قانونی تقاضے پورے ہونے کے بعد اعلیٰ عدالتوں سے سزائے موت پانے والے مجرموں کو معاف کرنے کا اختیار ’’جناب صدر‘‘ کے پاس ہے، یہ قطعاً غلط اور ناجائز ہے۔ (۲) مجرم کو باندھنا جائز ہے بالخصوص جب اس کے فرار ہونے اور بھاگ جانے کا اندیشہ ہو۔ (۳) ’’تیرے اور مقگتول کے گناہ‘‘ یعنی اس معافی کے بدلے میں تیرے اور مقتول کے گناہ معاف ہو جائیں گے اور تم دونوں جنتی بن جاؤ گے۔ مقتول اس لیے کہ وہ ظلماً مارا گیا اور مقتول کا ولی اس لیے کہ اس نے قاتل کی جان بخش دی۔ گویا ایک شخص کو زندگی دی۔ اور یہ بہت بڑی نیکی ہے۔ یہ معنی بھی ہو سکتے ہیں کہ قاتل کو دوگناہ ہوں گے۔ مقتول کو قتل کرنے کا اور تجھے (مقتول کے اولیاء کو) صدمہ اور نقصان پہنچانے کا، لیکن پہلے معنی زیادہ صحیح معلوم ہوتے ہیں۔ واللہ اعلم! (۴) مقتول کے ورثاء کو تین باتوں میں سے صرف ایک کا اختیار ہے۔ پہلی بات تو یہ کہ قاتل کو معاف کر دیں، یہ سب سے بہتر، افضل اور اللہ تعالیٰ کو بہت پسند ہے۔ اگر معاف نہیں کرتے تو پھر دیت، یعنی خون بہا لے لیں اور اسے چھوڑ دیں۔ یہ بھی بہتر ہے لیکن پہلے سے کم درجے کی نیکی ہے۔ اور تیسری اور آخری صورت قصاص میں قتل کرنا ہے۔ اس سے جس قدر بچ جائیں اتنا ہی بہتر ہے۔ اگر پہلی دونوں باتوں پر وہ آمادہ نہ ہوں تو پھر قاتل کو قصاص میں قتل کیا جائے گا اور بس۔ (۵) رسول اللہ صلی اللہ علیہ وسلم کا مقتول کے وارث کو بار بار معاف کرنے کی تلقین کرنا اس بات کی دلیل ہے کہ معافی پسندیدہ اور محبوب عمل ہے، نیز رسول اللہ صلی اللہ علیہ وسلم کے بار بار معافی کا شوق دلانے سے یہ بھی معلوم ہوا کہ شریعت اسلامیہ میں معاف کر دینا قصاص لینے سے بہتر ہے۔ اور مقتول کے اولیاء کو معافی کی رغبت دلانی چاہیے۔"}],[4724,"وائل رضی اللہ عنہ کہتے ہیں کہ جب قاتل کو لایا گیا تو میں رسول اللہ صلی اللہ علیہ وسلم کے پاس موجود تھا، مقتول کا ولی اسے رسی میں کھینچ کر لا رہا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے مقتول کے ولی سے فرمایا: \"کیا تم معاف کرو گے؟\" وہ بولا: نہیں، آپ نے فرمایا: \"کیا دیت لو گے؟\" وہ بولا: نہیں، آپ نے فرمایا: \"تو کیا تم قتل کرو گے؟\" اس نے کہا: ہاں، آپ نے فرمایا: \"لے جاؤ اسے\"، چنانچہ جب وہ لے کر چلا اور رخ پھیرا تو آپ نے اسے بلایا اور فرمایا: \"کیا تم معاف کرو گے؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"کیا دیت لو گے؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"تو قتل ہی کرو گے؟\" اس نے کہا: ہاں، آپ نے فرمایا: \"لے جاؤ اسے\"، اسی وقت رسول اللہ صلی اللہ علیہ وسلم نے یہ بھی فرمایا: \"سنو! اگر اسے معاف کرتے ہو تو وہ اپنا گناہ اور تمہارے (مقتول) آدمی کا گناہ سمیٹ لے گا\" ۱؎، چنانچہ اس نے اسے معاف کر دیا، اور اسے چھوڑ دیا، پھر میں نے اسے دیکھا کہ وہ اپنی رسی گھسیٹ رہا تھا۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ قتل سے پہلے جو گناہ اس کے سر تھا اور قتل کے بعد جس گناہ کا وہ مرتکب ہوا ہے ان دونوں کو وہ سمیٹ لے گا۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: میں موقع پر موجود تھا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک قاتل لایا گیا جسے مقتول کا ولی ایک تندی (چمڑے کی رسی) کے ساتھ کھینچے لا رہا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے مقتول کے ولی سے فرمایا: ’’کیا تو معاف کرے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’کیا تو دیت لے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’قتل کرے گا؟‘‘ اس نے کہا: ہاں۔ آپ نے فرمایا: ’’جا لے جا۔‘‘ جب وہ اس کو لے جانے کے لیے آپ کے پاس سے مڑا تو آپ نے اس کو بلایا اور فرمایا: ’’کیا تو معاف کرے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: کیا دیت لے گا؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر قتل کرے گا؟‘‘ اس نے کہا: ہاں۔ تو آپ نے فرمایا: ’’اسے لے جا۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سنو! اگر تو اسے معاف کر دے تو یہ اپنے اور تیرے مقتول کے گناہوں کا بوجھ اٹھائے گا۔‘‘ اس نے اسے معاف کر کے چھوڑ دیا۔ میں نے اسے دیکھا کہ وہ (قاتل) اپنی تندی کو گھسیٹتے ہوئے جا رہا تھا۔","f2":"’’اپنے اور مقتول کے گناہوں‘‘ یعنی معافی کی صورت میں مقتول کے گناہ بھی اس کے گلے میں ڈال دیے جائیں گے اور وہ جنتی ہو جائے گا، بخلاف اس سے قصاص لینے کے کہ اس طرح قاتل کا گناہ قتل معاف ہو جائے گا جب کہ مقتول کے گناہ معاف ہونے کی کوئی ضمانت نہیں ہوگی۔"}],[4725,"اس سند سے بھی وائل رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے اسی جیسی روایت کرتے ہیں۔ یحیی ۱؎ کہتے ہیں: یہ اس سے بہتر ہے۔\n§وضاحت\n۱؎: \"یحیی\" یعنی القطان :(جو راوی بھی ہیں، اور امام جرح و تعدیل بھی، وہ ) فرماتے ہیں: اس حدیث کی یہ سند پچھلی سند سے بہتر ہے۔","الألباني: صحيح الإسناد",{"u2":"ایک اور سند سے حضرت وائل رضی اللہ تعالٰی عنہ نبی صلی اللہ علیہ وسلم سے اس جیسی روایت بیان کرتے ہیں۔\nیحییٰ نے کہا: یہ روایت اس (سابقہ روایت) سے (سنداً) اچھی ہے۔","f2":"مذکورہ دونوں روایتیں یحییٰ بن سعید بیان کرتے ہیں۔ پہلی روایت وہ عوف بن ابو جمیلہ سے بیان کرتے ہیں: جبکہ دوسری روایت میں ان کے استاد جامع بن مطر حبطی ہیں۔ اس دوسری روایت کے پہلے روایت سے اچھا اور بہتر ہونے کا سبب، واللہ اعلم! یہ ہے کہ یحییٰ بن سعید کا استاد جامع بن مطر حبطی، ان کے استاد عوف بن ابی جمیلہ سے حدیث بیان کرنے میں اچھا ہے۔ عوف بن ابی جمیلہ کے بارے میں حافظ ابن حجر رحمہ اللہ فرماتے ہیں: [قَالَ بُنْدَارٌ… لَقَدْ کَانَ قَدَرِیًّا، رَافِضِیًّا، شَیْطَانًا] ’’بندار (محمد بن بشار) نے کہا:… بلا شبہ وہ (عوف بن ابو جمیلہ) تقدیر کا منکر، شیعہ رافضی اور شیطان تھا۔‘‘ دیکھیے: (تھذیب التھذیب: ۸/ ۱۴۹) امام ابن مبارک رحمہ اللہ فرماتے ہیں کہ عوف ایک بدعت پر راضی نہیں ہوا بلکہ اس میں دو بدعتیں پائی جاتی تھیں۔ ایک تو یہ کہ وہ قدری، یعنی تقدیر کا منکر تھا اور دوسری بدعت یہ تھی کہ وہ شیعہ اور راضی تھا۔ (حوالہ مذکور)"}],[4726,"وائل رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا کہ ایک شخص آیا، اس کی گردن میں رسی پڑی تھی، اور بولا: اللہ کے رسول! یہ اور میرا بھائی دونوں ایک کنویں پر تھے، اسے کھود رہے تھے، اتنے میں اس نے کدال اٹھائی اور اپنے ساتھی یعنی میرے بھائی کے سر پر ماری، جس سے وہ مر گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اسے معاف کر دو\"، اس نے انکار کیا، اور کہا: اللہ کے نبی! یہ اور میرا بھائی ایک کنویں پر تھے، اسے کھود رہے تھے، پھر اس نے کدال اٹھائی، اور اپنے ساتھی کے سر پر ماری، جس سے وہ مر گیا، آپ نے فرمایا: \"اسے معاف کر دو\"، تو اس نے انکار کیا، پھر وہ کھڑا ہوا اور بولا: اللہ کے رسول! یہ اور میرا بھائی ایک کنویں پر تھے، اسے کھود رہے تھے، اس نے کدال اٹھائی، اور اپنے ساتھی کے سر پر ماری، جس سے وہ مر گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے معاف کر دو\"، اس نے انکار کیا، آپ نے فرمایا: \"جاؤ، اگر تم نے اسے قتل کیا تو تم بھی اسی جیسے ہو گے\" ۱؎، وہ اسے لے کر نکل گیا، جب دور نکل گیا تو ہم نے اسے پکارا، کیا تم نہیں سن رہے ہو رسول اللہ صلی اللہ علیہ وسلم کیا فرما رہے ہیں؟ وہ واپس آیا تو آپ نے فرمایا: \"اگر تم نے اسے قتل کیا تو تم بھی اسی جیسے ہو گے\"، اس نے کہا: ہاں، میں اسے معاف کرتا ہوں، چنانچہ وہ نکلا، وہ اپنی رسی گھسیٹ رہا تھا یہاں تک کہ ہماری نظروں سے اوجھل ہو گیا۔\n§وضاحت\n۱؎: یعنی: کسی جان کو مارنے میں تم اور وہ ایک ہی طرح ہو گے، تمہاری اس پر کوئی فضیلت باقی نہیں رہ جائے گی، اور اگر معاف کر دو گے تو فضل و احسان میں تم کو اس پر فضیلت حاصل ہو جائے گی، خاص طور پر جب اس نے یہ قتل جان بوجھ کر نہیں کیا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا کہ ایک شخص آیا جس کی گردن میں رسی تھی (مطلب یہ کہ ایک شخص دوسرے آدمی کو گلے میں تندی ڈال کر لایا)۔ اور (وہی لانے والا شخص) کہنے لگا: یہ اور میر ابھائی ایک کنواں کھود رہے تھے کہ اس نے کدال اٹھائی اور میرے بھائی کے سر پر دے ماری اور اسے مار دیا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اسے معاف کر دے۔‘‘ اس نے انکار کر دیا۔ اور پھر کہنے لگا: اے اللہ کے نبی! یہ اور میرا بھائی ایک کنویں میں کھدائی کر رہے تھے تو اس نے کدال اٹھا کر اپنے ساتھی کے سر پر دے ماری اور اسے قتل کر دیا۔ آپ نے فرمایا: ’’اسے معاف کر دے۔‘‘ اس نے پھر انکار کیا۔ کچھ دیر بعد پھر اٹھا اور کہنے لگا: اے اللہ کے رسول! یہ اور میرا بھائی دونوں ایک کنویں کی کھدائی کر رہے تھے۔ اس نے کدال اٹھائی اور اپنے ساتھی کے سر پر مار دی اور اس کی جان نکال دی۔ آپ نے فرمایا: ’’اسے معاف کر دے۔‘‘ اس نے پھر انکار کیا۔ آپ نے فرمایا: ’’پھر جا (لیکن یاد رکھ کہ) اگر تو نے اسے قتل کر دیا تو تو بھی اس جیسا ہی ہوگا۔‘‘ وہ اسے لے کر چلا گیا حتی کہ کافی دور نکل گیا۔ تو ہم نے اسے آواز دی کہ تو رسول اللہ صلی اللہ علیہ وسلم کی بات نہیں سنتا؟ وہ واپس آیا اور کہنے لگا: اگر میں نے اسے قتل کر دیا تو اس جیسا ہو جاؤں گا؟ آپ نے فرمایا: ’’ہاں، اسے معاف کر دے۔‘‘ پھر (اس نے قاتل کو چھوڑ دیا تو) قاتل اپنی تندی سمیت نکل بھاگا حتیٰ کہ ہماری نگاہوں سے اوجھل ہوگیا۔","f2":"(۱)’’تو اس جیسا ہی ہوگا‘‘ ظاہر مفہوم تو یہ ہے کہ اگر تو نے اسے قتل کر دیا تو تو بھی ناجائز قاتل ہوگا لیکن یہ مفہوم یہاں مراد نہیں کیونکہ قاتل کو قصاص میں قتل کرنا جرم نہیں۔ باقی رہا قاتل کا یہ کہنا کہ میری نیت قتل کرنے کی نہیں تھی۔ اس سے قاتل کو معاف کرنا لازم نہیں آتا کیونکہ نیت تو اللہ تعالیٰ ہی جانتا ہے۔ ظاہراً صورت قتل کی ہی تھی۔ آپ کے فرمان کا مفہوم یہ ہے کہ تجھے اس پر کوئی فضیلت حاصل نہیں ہوگی۔ اس نے بھی غصے میں قتل کیا، تو نے بھی۔ اگرچہ اس نے ناجائز قتل کیا اور تو جائز کرے گا مگر فضیلت تبھی حاصل ہوگی جب تو معاف کر دے۔ دنیا میں بھی تعریف ہوگی، آخرت میں بھی اجر عظیم حاصل ہوگا۔ آپ نے اس جیسا ذو معنی جملہ بول کر اس کے معافی کے جذبات کو ابھارا اور اپنے مقصد میں کامیاب رہے۔ صلی اللہ علیہ وسلم (۲) معلوم ہوا قصاص کی بجائے معافی بہتر ہے خصوصاً جب کہ قاتل یہ عذر بھی پیش کرتا ہو کہ میری نیت قتل کی نہیں تھی، اگرچہ ایسی صورت میں معافی ضروری نہیں تبھی تو آپ نے قاتل مقتول کے ولی کے سپرد کر دیا تھا کہ وہ اسے قتل کر سکتا ہے۔ (مزید تفصیل کے لیے دیکھیے، فوائد ومسائل حدیث: ۴۷۲۶)"}],[4727,"وائل رضی اللہ عنہ سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے، اتنے میں ایک شخص دوسرے کو ایک رسی میں گھسیٹتا ہوا آیا، اور کہا: اللہ کے رسول! اس نے میرے بھائی کو قتل کیا ہے، آپ نے فرمایا: \"کیا تم نے اسے قتل کیا ہے؟\"، اس نے (لانے والے نے) کہا: اللہ کے رسول! اگر یہ اقبال جرم نہیں کرتا تو میں گواہ لاتا ہوں، اس (قاتل) نے کہا: ہاں، اسے میں نے قتل کیا ہے، آپ نے فرمایا: \"اسے تم نے کیسے قتل کیا؟\" اس نے کہا: میں اور وہ ایک درخت سے ایندھن جمع کر رہے تھے، اتنے میں اس نے مجھے گالی دی، مجھے غصہ آیا اور میں نے اس کے سر پر کلہاڑی مار دی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"کیا تمہارے پاس کچھ مال ہے جس سے اپنی جان کے بدلے تم اس کی دیت دے سکو\"، اس نے کہا: میرے پاس سوائے اس کلہاڑی اور کمبل کے کچھ نہیں، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"کیا تم سمجھتے ہو کہ تمہارا قبیلہ تمہیں خرید لے گا (یعنی تمہاری دیت دیدے گا) وہ بولا: میری اہمیت میرے قبیلہ میں اس(مال) سے بھی کمتر ہے، پھر آپ نے رسی اس شخص (ولی) کے سامنے پھینک دی اور فرمایا: \"تمہارا آدمی تمہارے سامنے ہے\"، جب وہ پلٹ کر چلا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اس نے اسے قتل کر دیا تو یہ بھی اسی جیسا ہو گا\"، لوگوں نے اس شخص کو پکڑ کر کہا: تمہارا برا ہو، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"اگر اس نے اسے قتل کر دیا تو یہ بھی اسی جیسا ہو گا\"، یہ سن کر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لوٹ آیا اور بولا: اللہ کے رسول! مجھے بتایا گیا ہے کہ آپ نے فرمایا: \"اگر اس نے اسے قتل کر دیا تو یہ بھی اسی جیسا ہو گا\"، میں نے تو آپ ہی کے حکم سے اسے پکڑا ہے؟ آپ نے فرمایا: \"کیا تم نہیں چاہتے کہ یہ تمہارا گناہ اور تمہارے آدمی کا گناہ سمیٹ لے؟\"، اس نے کہا: کیوں نہیں؟ آپ نے فرمایا: \"تو یہی ہو گا\"، اس نے کہا: تو ایسا ہی سہی (میں اسے چھوڑ دیتا ہوں)۔","الألباني: صحيح",{"u2":"حضرت وائل رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا کہ ایک آدمی ایک دوسرے آدمی کو تندی (چمڑے کی رسی) کے ساتھ کھینچتا ہوا آیا اور کہنے لگا: اللہ کے رسول! اس نے میرے بھائی کو قتل کر دیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس (دوسرے آدمی) سے پوچھا: ’’کیا تو نے اسے قتل کیا ہے؟‘‘ پہلا آدمی کہنے لگا: اے اللہ کے رسول! اگر یہ نہ مانے تو میں گواہ پیش کروں گا۔ دوسرے آدمی نے کہا: ہاں، میں نے اسے قتل کیا ہے۔ آپ نے فرمایا: ’’کیسے قتل کیا؟‘‘ اس نے کہا: میں اور وہ ایک درخت سے ایندھن کے لیے لکڑیاں کاٹ رہے تھے۔ اس نے مجھے گالی دے کر غصہ دلا دیا تو میں نے کلہاڑا اس کے سر کی چوٹی پر دے مارا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا تیرے پاساتنا مال ہے جو تو اپنی جان بچانے کے لیے ادا کرے؟‘‘ اس نے کہا: اے اللہ کے رسول! میرے پاس تو میرے کلہاڑے اور میری چادر کے سوا کچھ نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا خیال ہے تیری قوم تجھے خرید لے گی؟ (تیری دیت دے کر تجھے بچا لے گی؟)‘‘ اس نے کہا: میں اپنی قوم کے نزدیک اس سے کم مرتبہ ہوں۔ آپ نے اس کی رسی پہلے آدمی کی طرف پھینک دی اور فرمایا: ’’لو اپنے قاتل کو سنبھالو۔‘‘ جب وہ پیٹھ پھیر کر چلا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر اس نے اسے قتل کر دیا تو یہ بھی اس جیسا ہی ہوگا۔‘‘ لوگ جا کر اس آدمی کو ملے اور کہا: تجھ پر افسوس! رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’اگر اس نے اسے قتل کر دیا تو وہ اس جیسا ہی ہوگا۔‘‘ وہ آدمی واپس رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اے اللہ کے رسول! مجھے بتایا گیا ہے کہ آپ نے فرمایا ہے: ’’اگر اس (میں) نے اسے قتل کر دیا تو یہ بھی اس جیسا ہی ہوگا۔‘‘ حالانکہ میں نے تو اسے آپ کے فرمان سے پکڑا ہے۔ آپ نے فرمایا: ’’کیا تو نہیں چاہتا کہ یہ شخص تیرا اور تیرے مقتول کا گناہ سمیٹ لے۔ (تمھارے گناہوں کی معافی کا سبب بن جائے؟)‘‘ اس نے کہا: کیوں نہیں، پھر کہا: اگر یہ بات ہے تو میں معاف کر دیتا ہوں۔ آپ نے فرمایا: ’’یہ اسی طرح ہے جس طرح میں نے کہا، یعنی وہ تیرے اور تیرے مقتول کے گناہ اٹھائے گا۔‘‘","f2":"حدیث ۴۷۳۰ میں ہے کہ وہ کنواں کھود رہے تھے جبکہ اس حدیث میں ہے کہ وہ لکڑیاں کاٹ رہے تھے جب اس نے قتل کیا۔ اس میں تطبیق یوں ہو سکتی ہے کہ ان کا اصل کام تو کنواں کھودنا ہو اور اس دوران میں انھیں لکڑیاں حاصل کرنے کی ضرورت پڑ گئی ہو اور لکڑیاں اکٹھی کرتے ہوئے ان کے درمیان جھگڑا ہوگیا ہو اور اس نے کنواں کھودنے والی کدال کے ساتھ اسے قتل کر دیا ہو۔ جب مقتول کے بھائی نے بتایا تو اس نے ان کے اصل کام کا حوالہ دیا اور جب قاتل نے خود بتایا تو جائے وقوعہ کی خبر دی۔ واللہ اعلم"}],[4728,"وائل رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھا ہوا تھا، اتنے میں ایک شخص دوسرے کو گھسیٹتا ہوا آیا، پھر (آگے حدیث) اسی طرح ہے۔","الألباني: صحيح",{"u2":"وائل رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا تھا کہ ایک آدمی ایک دوسرے شخص کو کھینچتا ہوا لایا۔ باقی روایت مذکورہ روایت کے اہم معنی ہے۔"}],[4729,"وائل رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک آدمی لایا گیا، اس نے ایک شخص کو قتل کر دیا تھا، چنانچہ آپ نے اسے قتل کرنے کے لیے مقتول کے ولی کے حوالے کر دیا، پھر آپ نے اپنے ساتھ بیٹھنے والوں سے فرمایا: \"قاتل اور مقتول دونوں جہنم میں جائیں گے\" ۱؎، ایک شخص اس وارث کے پیچھے گیا اور اسے خبر دی، جب اسے یہ معلوم ہوا تو اس نے قاتل کو چھوڑ دیا، جب اس نے قاتل کو چھوڑ دیا تاکہ وہ چلا جائے تو میں نے اسے دیکھا کہ وہ اپنی رسی گھسیٹ رہا ہے۔ میں نے اس کا ذکر حبیب سے کیا تو انہوں نے کہا: مجھ سے سعید بن اشوع نے بیان کیا، وہ کہتے ہیں: انہوں نے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے اس شخص کو معاف کرنے کا حکم دیا تھا۔\n§وضاحت\n۱؎: یہ بات آپ نے خاص ان دونوں کے بارے میں نہیں کہی تھی، کیونکہ اس میں نہ تو مذکورہ مقتول کا کوئی قصور تھا، نہ ہی اس کے ولی کا جو اس کو بدلے میں قتل کرتا بلکہ آپ نے ولی کو معافی پر ابھارنے کے لیے یہ جملہ فرمایا تھا۔","الألباني: صحيح",{"u2":"حضرت وائل رضی اللہ تعالٰی عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک آدمی لایا گیا جس نے ایک آدمی کو قتل کر دیا تھا۔ آپ نے اسے مقتول کے ولی کے سپرد فرمایا دیا کہ (چاہے تو) قتل کر دے۔ پھر نبی کریم صلی اللہ علیہ وسلم نے اپنے ہم نشینوں سے کہا: ’’قاتل مقتول دونوں آگ میں جائیں گے۔‘‘ ایک آدمی اس کے پیچھے گیا اور اسے آپ کے فرمان کی خبر دی۔ جب اس نے اس کو یہ بتایا تو اس نے اسے چھوڑ دیا۔ جب اس نے چھوڑا تو میں نے دیکھا کہ وہ رسی گھسیٹتے ہوئے بھاگا جا رہا تھا۔ [فَذَکَرْتُ ذٰلِکَ لِحَبِیْبٍ فَقَالَ… الخ] میں نے یہ روایت حبیب سے بیان کی تو اس نے کہا: مجھ سے سعید بن اشوع نے بیان کیا کہ نبی صلی اللہ علیہ وسلم نے اس آدمی کو معاف کرنے کا حکم دیا۔","f2":"(۱) [فَذَکَرْتُ…] کے قائل اسماعیل بن سالم ہیں۔ صحیح مسلم میں اس کی تصریح ہے۔ اسی طرح حبیب سے مراد حبیب بن ابی ثابت ہیں۔ اس کی تصریح اور وضاحت بھی صحیح مسلم میں موجود ہے۔ دیکھیے: (صحیح مسلم، القسامۃ والمحاربین، باب صحۃ الاقرار بالقتل وتمکین ولی القتیل من القصاص… الخ، حدیث: ۱۶۸۰) (۲) ’’دونوں آگ میں‘ یہ مطلب نہیں کہ اگر اس نے اسے قتل کر دیا تو دونوں آگ میں جائیں گے۔ یہ معنی مسلمات کے خلاف ہیں کیونکہ قتل کیے جانے کی صورت میں قاتل کا گناہ معاف ہو جائے گا کیونکہ قصاص لینے والا تو اپنا حق وصول کر لے گا۔ وہ آگ میں کیوں؟ بلکہ مطلب یہ ہے کہ اگر قاتل اور مقتول دونوں ایک دوسرے کے قتل کے در پے رہے ہوں تو وہ دونوں آگ میں جائیں گے۔ ضروری نہیں کہ صرف قاتل ہی قصور وار ہو، لہٰذا معاف کر دینا چاہیے۔ اس قسم کے الفاظ سے مقصود معافی کے جذبات کو ابھارنا تھا اور وہ مقصود حاصل ہوگیا۔ واللہ اعلم"}],[4730,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک شخص اپنے آدمی کے قاتل کو لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو آپ نے اس سے فرمایا: \"اسے معاف کر دو\"، اس نے انکار کیا، تو آپ نے فرمایا: \"دیت لے لو\"، اس نے انکار کیا تو آپ نے فرمایا: \"جاؤ، اسے قتل کر دو، تم بھی اسی جیسے ہو جاؤ گے (گناہ میں)\"، جب وہ قتل کرنے چلا تو کوئی اس شخص سے ملا اور اس سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے، \"(اگر) اسے قتل کر دو، تم بھی اسی طرح ہو جاؤ گے\"، چنانچہ اس نے اسے چھوڑ دیا، تو وہ شخص (یعنی قاتل جسے معاف کیا گیا) میرے پاس سے اپنی رسی گھسیٹتے ہوئے گزرا۔","الألباني: صحيح الإسناد",{"u2":"حضرت انس بن مالک رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک شخص اپنے رشتہ دار کے قاتل کو پکڑ کر رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اسے معاف کر دے۔‘‘ اس نے انکار کیا۔ آپ نے فرمایا: ’’دیت لے لو۔‘‘ اس نے پھر انکار کیا۔ آپ نے فرمایا: ’’جا پھر اسے قتل کر دے۔ تو بھی اس جیسا ہی ہے۔‘‘ وہ اسے لے گیا۔ پیچھے سے کوئی آدمی اسے جا کر ملا اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’اسے قتل کر دے تو تو بھی اس جیسا ہی ہوگا۔‘‘ تو اس نے اسے چھوڑ دیا۔ وہ آدمی (قاتل) میرے پاس سے گزرا اس حال میں کہ وہ رسی گھسیٹتا ہوا بھاگا جا رہا تھا۔","f2":"’’رسی گھسیٹتا ہوا‘‘ گویا اس نے رسی کھولنے کا تکلف بھی نہ کیا۔ اسی طرح بھاگ اٹھا۔"}],[4731,"بریدہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا کہ اس شخص نے میرے بھائی کو مار ڈالا، آپ نے فرمایا: \"جاؤ اسے بھی مار ڈالو جیسا کہ اس نے تمہارے بھائی کو مارا ہے\"، اس شخص نے اس سے کہا: اللہ سے ڈرو اور مجھے معاف کر دو، اس میں تمہیں زیادہ ثواب ملے گا اور یہ قیامت کے دن تمہارے لیے اور تمہارے بھائی کے لیے بہتر ہو گا، یہ سن کر اس نے اسے چھوڑ دیا، نبی اکرم صلی اللہ علیہ وسلم کو اس کی خبر ہوئی، آپ نے اس سے پوچھا تو اس نے جو کہا تھا، آپ سے بیان کیا، آپ نے اس سے زور سے فرمایا: \"سنو! یہ تمہارے لیے اس سے بہتر ہے جو وہ قیامت کے دن تمہارے ساتھ معاملہ کرتا، وہ کہے گا(قیامت کے دن) اے میرے رب! اس سے پوچھ اس نے مجھے کس جرم میں قتل کیا\" ۱؎۔\n§وضاحت\n۱؎: یہ واقعہ مذکورہ واقعہ کے علاوہ ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت بریدہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اس آدمی نے میرے بھائی کو قتل کر ڈالا ہے۔ آپ نے فرمایا: ’’جا اسے قتل کر دے، جیسے اس نے تیرے بھائی کو قتل کیا ہے۔‘‘ وہ آدمی (قاتل) کہنے لگا: ’’اللہ تعالیٰ سے ڈرو اور مجھے معاف کر دو۔ اس سے تجھے بہت ثواب ملے گا۔ اور یہ (معافی) تیرے اور تیرے بھائی کے لیے قیامت کے دن بہت اچھی ثابت ہوگی۔ اس نے اسے چھوڑ دیا۔ نبی کریم صلی اللہ علیہ وسلم کو بتایا گیا۔ آپ نے قاتل سے پوچھا تو اس نے مقتول کے وارث سے جو کہا تھا آپ کو اس کی خبر دی۔ تو آپ نے اسے ڈانٹا (اور فرمایا:) ’’تیرا قتل ہو جانا اس سلوک سے بہتر تھا جو مقتول قیامت کے دن تجھ سے کرے گا۔ وہ کہے گا: اے میرے رب اس سے پوچھیے کہ اس نے کس بنا پر مجھے قتل کیا تھا؟‘‘","f2":"(۱) ’’تیرا قتل ہو جانا بہتر تھا‘‘ گویا معافی مقتول اور اس کے ولی کے لیے تو بہتر اور افضل ہے مگر قاتل کے لیے نقصان دہ ہے کیونکہ مقتول اور اس کا ولی تو معافی کی وجہ سے جنت میں چلے جائیں گے مگر قاتل کو حساب دینا ہوگا اور عذاب سہنا ہوگا، بخلاف اس کے کہ اگر معاف نہ کیا جاتا اور قاتل کو قتل کر دیا جاتا تو قاتل کا گناہ تو معاف ہو جاتا، البتہ مقتول اور اس کے ولی کی معافی کی کوئی ضمانت نہ ہوتی۔ (۲) اس حدیث سے معلوم ہوتا ہے کہ عدالت سے سزا ہونے کے بعد بھی قاتل، مقتول کے وارث سے معافی کی درخواست کر سکتا ہے اور وہ چاہے تو معاف کر سکتا ہے کیونکہ یہ خالصتاً اسی کا حق ہے۔ اور یہ صرف قتل کے مسئلے میں ہے۔ چوری وغیرہ کے مسئلے میں عدالت میں کیس آنے سے پہلے تو معاف کر سکتا ہے بعد میں نہیں۔ جیسا کہ دوسری حدیث میں اس کی وضاحت ہے۔ واللہ اعلم"}],[4732,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ قریظہ اور نضیر یہودیوں کے دو قبیلے تھے، بنو نضیر بنو قریظہ سے بڑھ کر تھے، جب بنو قریظہ کا کوئی شخص بنو نضیر کے کسی شخص کو قتل کر دیتا تو وہ اس کے بدلے قتل کر دیا جاتا، اور جب بنو نضیر کا کوئی شخص بنو قریظہ کے کسی شخص کو قتل کرتا تو وہ سو وسق کھجور ادا کر دیتا، لیکن جب نبی اکرم صلی اللہ علیہ وسلم نبی بنا کر بھیجے گئے تو بنو نضیر کے ایک شخص نے بنو قریظہ کے ایک شخص کو قتل کر دیا تو ان لوگوں نے کہا: اسے (قاتل کو) ہمارے حوالے کرو ہم اسے قتل کریں گے، انہوں (بنو نضیر) نے کہا: ہمارے اور تمہارے درمیان ثالث نبی اکرم صلی اللہ علیہ وسلم ہوں گے، چنانچہ وہ لوگ آپ کے پاس آئے تو یہ آیت: «وإن حكمت فاحكم بينهم بالقسط» \"اور اگر تم فیصلہ کرو تو ان کے درمیان انصاف سے فیصلہ کرو\" (المائدہ: ۴۰) نازل ہوئی، «قسط» یعنی انصاف کا مطلب ہے جان کے بدلے جان لی جائے، پھر یہ آیت «أفحكم الجاهلية يبغون» \"کیا یہ لوگ جاہلیت کا انصاف پسند کرتے ہیں\" (المائدہ: ۵۰) نازل ہوئی۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: بنو قریظہ اور بنو نضیر (دو یہودی قبیلے تھے۔) بنو نظیر، بنو قریظہ سے افضل شمار ہوتے تھے۔ اگر بنو قریظہ میں سے کوئی آدمی بنو نضیر کے کسی آدمی کو قتل کر دیتا تو اسے قصاصاً قتل کر دیا جاتا تھا لیکن جب بنو نضیر کا کوئی شخص بنو قریظہ کے کسی آدمی کو قتل کرتا تو وہ سو وسق کھجور دے دیتا تھا۔ جب نبی اکرم صلی اللہ علیہ وسلم مبعوث ہوئے (مدینہ منورہ تشریف لائے) تو بنو نضیر کے ایک آدمی نے بنو قریظہ کے ایک آدمی کو قتل کر دیا۔ بنو قریظہ نے مطالبہ کیا کہ قاتل ہمارے سپرد کرو تاکہ ہم اسے قتل کر دیں۔ (ان کے انکار پر) بنو قریظہ نے کہا: ہمارے اور تمھارے درمیان نبی کریم صلی اللہ علیہ وسلم فیصلہ فرمائیں گے۔ وہ آپ کے پاس آئے تو یہ آیت اتری: {وَ اِنْ حَکَمْتَ فَاحْکُمْ بَیْنَہُمْ بِالْقِسْطِ} ’’اگر آپ فیصلہ فرمائیں تو ان کے درمیان انصاف کے ساتھ فیصلہ فرمائیں۔‘‘ اور انصاف یہی ہے کہ جان کے بدلے جان (مقتول کے بدلے قاتل کیا جائے)۔ پھر یہ آیت اتری: {اَفَحُکْمَ الْجَاہِلِیَّۃِ یَبْغُوْنَ} ’’کیا یہ اب بھی جاہلیت کے فیصلے چاہتے ہیں؟‘‘","f2":"’’ہمارے اور تمھارے درمیان‘‘ ترجمے میں اسے بنو قریظہ کا قول بتلایا گیا ہے مگر یہ بنو نضیر کا قول بھی بن سکتا ہے کہ وہ قاتل سپرد کرنے کے بجائے فیصلہ آپ کے پاس لے آئے۔ ان کا خیال تھا کہ رسول اللہ صلی اللہ علیہ وسلم بھی ہماری روایات کے مطابق فیصلہ فرمائیں گے۔ یہ ترجمہ مابعد الفاظ ’’کیا وہ جاہلیت کا فیصلہ چاہتے ہیں؟‘‘ سے زیادہ مطابقت رکھتا ہے۔ واللہ اعلم"}],[4733,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ مائدہ کی وہ آیات جن میں اللہ تعالی نے فرمایا: «فاحكم بينهم أو أعرض عنهم» سے «المقسطين»، بنو نضیر اور بنو قریظہ کے درمیان ایک دیت کے سلسلے میں نازل ہوئی تھیں، وجہ یہ تھی کہ بنو نضیر کے مقتولین کو برتری حاصل ہونے کی وجہ سے ان کی پوری دیت دے دی جاتی تھی اور بنو قریظہ کو آدھی دیت دی جاتی تھی، اس سلسلے میں انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی طرف رجوع کیا تو اللہ تعالی نے یہ حکم ان کے سلسلے میں نازل فرمایا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اس سلسلہ میں حق کی ترغیب دلائی اور دیت برابر کر دی۔","الألباني: حسن صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ سورئہ مائدہ کی آیات جن میں اللہ عزوجل نے فرمایا ہے:\n{فَاحْکُمْ بَیْنَہُمْ بِالْقِسْطِ اِنَّ اللّٰہَ یُحِبُّ الْمُقْسِطِیْنَ}\n’’آپ ان میں فیصلہ کریں یا نہ، (آپ کی مرضی ہے)… انصاف کرنے والوں کو (ہی پسند کرتا ہے)۔‘‘ یہ آیات بنو نضیر اور بنو قریظہ کے درمیان دیت کے جھگڑے کے بارے میں نازل ہوئیں اور وہ اس طرح کہ بنو نضیر کے مقتولین کو افضل خیال کیا جاتا تھا، اس لیے ان کی مکمل دیت (سو اونٹ) ادا کی جاتی تھی جب کہ بنو قریظہ کے مقتولین کی نصف دیت ادا کی جاتی تھی۔ وہ اس بارے میں رسول اللہ صلی اللہ علیہ وسلم کے پاس فیصلہ لے گئے تو اللہ تعالیٰ نے ان کے بارے میں یہ آیات نازل فرمائیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے ان کو اس بارے میں حق اختیار کرنے پر مجبور کیا اور آپ نے سب کی دیت برابر قرار دی۔","f2":"(۱) اسلامی حکومت کے تحت بسنے والے غیر مسلم ذمی کہلاتے ہیں۔ اپنے ذاتی معاملات تو وہ اپنی روایات کے مطابق خود طے کریں گے مگر جن معاملات کا تعلق عدالت سے ہے، وہ فیصلہ ملکی قانون کے مطابق ہوگا۔ ملکی قانون سے مراد اسلامی شریعت ہے۔ مذہب اور دین ذاتی معاملات میں شمار ہوتے ہیں۔ لوگوں سے لین دین اور جرم وسزا وغیرہ ملکی معاملات کے تحت آتے ہیں۔ (۲)مذکورہ بالا دونوں روایتوں کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین مذکورہ دونوں روایتوں کی بابت لکھتے ہیں کہ یہ دونوں روایتیں مل کر درجہ صحت تک پہنچ جاتی ہیں۔ اور دلائل کے اعتبار سے یہی رائے اقرب الی الصواب معلوم ہوتی ہے۔ واللہ اعلم، مزید تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ، مسند الامام احمد: ۵/ ۴۰۱، وذخیرۃ العقبی شرح سنن النسائی: ۳۶/ ۶-۱۲)"}],[4734,"قیس بن عباد کہتے ہیں کہ میں اور اشتر علی رضی اللہ عنہ کے پاس گئے تو ہم نے کہا: کیا نبی اکرم صلی اللہ علیہ وسلم نے آپ کو کوئی ایسی خاص بات بتائی جو عام لوگوں کو نہیں بتائی؟ انہوں نے کہا: نہیں، سوائے اس کے کہ جو میری اس کتاب میں موجود ہے ۱؎ پھر انہوں نے اپنی تلوار کی نیام سے ایک تحریر نکالی، اس میں لکھا تھا:\"سب مسلمانوں کا خون برابر ہے ۲؎، اور وہ غیروں کے مقابل (باہمی نصرت و معاونت میں) گویا ایک ہاتھ ہیں، اور ان میں کا ایک ادنی آدمی بھی ان سب کی طرف سے عہد و امان کی ذمہ داری لے سکتا ہے ۳؎ آگاہ رہو! کہ کوئی مومن کسی کافر کے بدلے قتل نہیں کیا جائے گا، اور نہ ہی کوئی ذمی معاہد جب تک وہ معاہد ہے قتل کیا جائے گا، اور جو شخص کوئی نئی بات نکالے گا تو اس کی ذمہ داری اسی کے اوپر ہو گی، اور جو نئی بات نکالے گا یا نئی بات نکالنے والے کسی شخص کو پناہ دے گا تو اس پر اللہ کی، فرشتوں کی اور تمام لوگوں کی لعنت ہے۔\n§وضاحت\n۱؎: یعنی اگر میرے لیے کوئی خاص بات ہوتی تو میری اس کتاب میں ضرور ہوتی، جب کہ اس کتاب میں جو کچھ ہے وہ میرے لیے خاص نہیں ہے بلکہ عام ہے، یہ اور بات ہے کہ اوروں کو چھوڑ کر مجھے اسے لکھنے کا حکم دیا گیا۔ ۲؎: اس سے ثابت ہوتا ہے کہ آزاد آدمی اور غلام کے درمیان بھی قصاص کا حکم جاری ہو گا۔۳؎: یعنی کوئی ادنی مسلمان بھی کسی کافر کو پناہ دیدے تو کوئی مسلمان اسے توڑ نہیں سکتا۔","الألباني: صحيح",{"u2":"حضرت قیس بن عباد سے روایت ہے کہ میں اور حضرت قیس بن عباد سے روایت ہے کہ میں اور اشتر نخعی حضرت علی رضی اللہ تعالٰی عنہ کے پاس گئے۔ ہم نے کہا: کیا نبی کریم صلی اللہ علیہ وسلم نے آپ کو کوئی خصوصی وصیت فرمائی ہے جو دوسرے لوگوں کو نہ فرمائی ہو؟ انھوں نے کہا: نہیں، البتہ میری اس تحریر میں کچھ لکھا ہے۔ پھر انھوں نے اپنی تلوار کی میان سے وہ تحریر نکالی تو اس میں لکھا تھا: ’’تمام ایمان والوں کے خون برابر ہیں۔ اور وہ سب اپنے دشمن کے خلاف یکمشت ہیں۔ ان میں سے کم مرتبہ والا عام شخص بھی کسی کو پناہ دے سکتا ہے۔ آگاہ رہو! کسی مومن کو کافر کے بدلے قتل نہ کیا جائے اور نہ کسی ذمی کو جب تک وہ ہماری پناہ میں ہے۔ جو دشمن بغاوت کرے گا، اسے اس کا خمیازہ بھگتنا پڑے گا۔ جو شخص کسی باغی کو پناہ مہیا کرے، اس پر اللہ تعالیٰ، فرشتوں اور سب لوگوں کی لعنت ہے۔‘‘","f2":"(۱) مومن کو کافر کے بدلے کسی صورت میں قتل نہیں کیا جا سکتا، خواہ مقتول ذمی ہی ہو کیونکہ مسلمان اور کافر کے خون برابر نہیں۔ البتہ ذمی کا قتل چونکہ عہد اور پناہ کی خلاف ورزی ہے، لہٰذا اس کی دیت دی جائے گی ورنہ آخرت میں منجانب اللہ سزا ہوگی۔ حکومت بھی تقریباً قید وغیرہ کی سزا دے سکتی ہے۔ واللہ اعلم! احناف ذمی کے بدلے مسلمان کے قتل کے قائل ہیں۔ وہ اس روایت کو حربی کافر، یعنی دشمن ملک کے کافر کے بارے میں قرار دیتے ہیں، حالانکہ دشمن ملک کے کافر کے بدلے تو قتل کا سوا ہی پیدا نہیں ہوتا۔ (۲) اس حدیث سے رافضیوں کی تردید ہوتی ہے جو کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے حضرت علی رضی اللہ تعالٰی عنہ کو کچھ خصوصی وصیتیں کی تھیں، نیز معلوم ہوا کہ جرم کی سزا صرف اور صرف مجرم کو ملے گی کسی دوسرے شخص کو نہیں۔ ہمارے معاشرے میں جو اندھا قانون ہے کہ کرے کوئی بھرے کوئی، تو یہ شرعاً ناجائز اور حرام ہے۔ ارشاد الٰہی ہے: {وَ لَا تَزِرُ وَازِرَۃٌ وِّزْرَ اُخْرٰی} (فاطر ۳۵: ۱۸) ’’کوئی بوجھ اٹھانے والا کسی دوسرے کا (قطعاً) کوئی بوجھ نہیں اٹھائے گا۔ (خواہ وہ اس کا کتنا ہی قرابت دار کیوں نہ ہو)۔‘‘ اللہ کے قانون میں اس کی ذرہ بھر گنجائش نہیں بلکہ ایسا کرنے والا، مجرم اور لائق سزا قرار پاتا ہے۔ (۳) تمام مسلمانوں پر لازم ہے کہ وہ نیکی اور تقویٰ کے کاموں میں ایک دوسرے کے ساتھ تعاون کریں۔ ایک دوسرے کو قوت باہم پہنچائیں، نیز وہ اپنے دشمنوں کے خلاف متحد ہوں۔ (۴) جس طرح جرم کرنا گناہ ہے اسی طرح کسی مجرم کی پشت پناہی کرنا اسے قرار واقعی سزا سے بچانا اور اس کی سفارش وغیرہ کرنا بھی گناہ ہے۔ مزید برآں یہ بھی کہ اگر کوئی شخص باغی اور ایسے خطرناک مجرم کو پناہ اور تحفظ دے تو یہ پناہ اور تحفظ دینے والا شخص ملعون اور لعنتی ہے۔ اس شخص پر لعنت ہے اللہ تعالیٰ کی، اس کے فرشتوں کی اور تمام انسانوں کی۔ اس میں ان حضرات کے لیے لمحہ فکریہ ہے جو مجرموں کو تحفظ دیتے ہیں کہ وہ جھوٹی ناموری کے لیے لعنت اور پھٹکار کے مستحق ٹھہرتے ہیں۔ (۵) ’’خصوصی وصیت‘‘ بعض بے دین لوگوں نے مشہور کر رکھا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت علی رضی اللہ تعالٰی عنہ کو اصل وحی کی تعلیم دی ہے۔ باقی لوگوں کے پاس ناقص وحی ہے۔ حضرت علی رضی اللہ تعالٰی عنہ نے اس کی نفی فرمائی کہ میرے پاس صرف ایک تحریر ہے۔ وہ بھی دیکھ لو تاکہ کوئی شک وشبہ نہ رہے۔ اس تحریر میں ایسے مسائل تھے جو سب لوگوں سے تعلق رکھتے تھے اور لوگوں کو الگ طور سے بھی معلوم تھے۔ (۶) ’’خون برابر ہیں‘‘ اس سے مصنف رحمہ اللہ نے استدلال فرمایا ہے کہ آزاد اور غلام مومن کا خون برابر ہے، لہٰذا انھیں ایک دوسرے کے بدلے قتل کیا جا سکتا ہے۔ یہی موقف سعید بن مسیب، ابراہیم نخعی، قتادہ، سفیان ثوری اور ابوحنیفہM کا ہے۔ شیخ الاسلام ابن تیمیہ رحمہ اللہ نے بھی اسی موقف کو راجح قرار دیا ہے کیونکہ مذکورہ حدیث کے مطابق مسلمانوں کے خون برابر ہیں۔ اس کے برعکس اہل علم کی ایک جماعت کے نزدیک آزاد کو غلام کے بدلے قتل نہیں کیا جائے گا۔ اس میں سرفہرست سیدنا ابوبکر و عمر رضی اللہ عنہ کا نام آتا ہے لیکن ان سے صحیح سند سے ثابت نہیں ہے، نیز اس بارے میں وارد تمام احادیث بھی ضعیف ہیں۔ اس لیے راجح بات یہی ہے کہ آزاد آدمی اگر غلام کو قتل کر دے تو اسے قصاصاً قتل کیا جائے گا الا یہ کہ اس کے ورثاء دیت پر راضی ہو جائیں یا معاف کر دیں۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ، شرح سنن النسائی، للاتبوبي: ۳۶/ ۱۹) (۷) ’’یکمشت ہیں۔‘‘ یعنی مسلمانوں کو کفار کے مقابلے میں یکمشت رہنا چاہیے۔ آپس میں انتشار یا دشمن کی سازش کا شکار نہیں ہونا چاہیے اور نہ کفار کو دوست بنانا چاہیے۔ رسول اللہ صلی اللہ علیہ وسلم نے کیسی بہترین مثال ارشاد فرمائی ہے کہ مومن ایک ہاتھ کی انگلیوں کی طرح ہیں جو ضرورت ہو تو یکجان ہو کر زبردست مکا بن جاتی ہیں۔ (۸) ’’پناہ دے سکتا ہے‘‘ جو دوسرے مسلمانوں کو تسلیم کرنا ہوگی، خواہ پناہ دینے والا عام فوجی یا عام مسلمان ہو۔"}],[4735,"علی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سارے مسلمانوں کا خون برابر ہے وہ غیروں کے مقابل (باہمی نصرت و معاونت میں)گویا ایک ہاتھ ہیں اور ان میں کا ایک ادنی آدمی بھی سب کی طرف سے عہد و امان کی ذمہ داری لے سکتا ہے، کوئی مومن کسی کافر کے بدلے قتل نہیں کیا جائے گا اور نہ کسی ذمی کو جب تک وہ ذمہ میں رہے\"۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’تمام مومنوں کے خون برابر ہیں اور وہ اپنے دشمن کافروں کے خلاف ایک ہاتھ کی طرح ہیں۔ ان میں سے عام شخص بھی پناہ دے سکتا ہے۔ کسی مومن کو کسی کافر کے بدلے میں قتل نہیں کیا جا سکتا۔ نہ کسی ذمی کو قتل کیا جا سکتا ہے، جب تک اس سے معاہدہ قائم ہے۔‘‘"}],[4736,"سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی اپنے غلام کو قتل کر دے گا تو ہم اسے قتل کریں گے اور جو کوئی اس کا عضو کاٹے گا تو ہم اس کا عضو کاٹیں گے اور جو کوئی اپنے غلام کو خصی کرے گا، ہم اسے خصی کریں گے\"۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے غلام کو قتل کرے گا، ہم اسے قتل کر دیں گے۔ جو شخص اپنے غلام کی ناک کان کاٹے گا، ہم اس کی ناک کان کاٹ دیں گے اور جو اپنے غلام کو خصی کرے گا، ہم اسے خصی کر دیں گے۔‘‘"}],[4737,"سمرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے غلام کو قتل کر دے گا ہم اسے قتل کریں گے اور جو اپنے غلام کا عضو کاٹے گا ہم اس کا عضو کاٹیں گے\"۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے غلام کو قتل کرے گا، ہم اسے قتل کر دیں گے اور جو اپنے غلام کے ناک کان کاٹے گا، ہم اس کے ناک کان کاٹ دیں گے۔‘‘"}],[4738,"سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی اپنے غلام کو قتل کر دے گا تو ہم اسے قتل کریں گے اور جو کوئی اس کا عضو کاٹے گا، ہم اس کا عضو کاٹیں گے\"۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے غلام کو قتل کرے گا، ہم اسے قتل کریں گے اور جو شخص اپنے غلام کی ناک کان کاٹے گا، ہم اس کی ناک کان کاٹ دیں گے۔‘‘","f2":"مذکورہ بالا تینوں روایات ضعیف ہیں۔ محقق کا انھیں حسن کہنا محل نظر ہے کیونکہ راجح بات یہ ہے کہ حسن بصری رحمہ اللہ نے حضرت سمرہ رضی اللہ تعالٰی عنہ سے سوائے عقیقہ والی روایت کے کوئی روایت نہیں سنی۔ تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ، مسند الامام احمد: ۳۳/ ۲۹۶، ۲۹۷) تاہم مسئلہ اسی طرح ہے جس طرح مؤلف رحمہ اللہ نے باب قائم کیا ہے کہ آقا اگر اپنے غلام کو قتل کر دے تو اسے قتل کیا جائے گا جیسا کہ حدیث: ۴۷۳۸ کے فوائد میں تفصیل گزر چکی ہے۔"}],[4739,"عبداللہ بن عباس رضی اللہ عنہما عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ انہیں اس سلسلے میں رسول اللہ صلی اللہ علیہ وسلم کے فیصلے کی تلاش تھی، تو حمل بن مالک رضی اللہ عنہ نے کھڑے ہو کر کہا: میں دو عورتوں کے کمروں کے درمیان میں رہتا تھا، ایک نے دوسری کو خیمے کی لکڑی سے مارا اور اسے اور اس کے پیٹ کے بچے کو مار ڈالا، تو نبی اکرم صلی اللہ علیہ وسلم نے بچے کے بدلے ایک غلام یا لونڈی دینے اور اس (عورت) کے بدلے اسے قتل کرنے کا حکم دیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمر رضی اللہ تعالٰی عنہ سے روایت ہے کہ انھوں نے اس (عورت کو عورت) کے بدلے قتل کرنے) کی بابت لوگوں سے رسول اللہ صلی اللہ علیہ وسلم کا فیصلہ پوچھا تو حضرت حمل بن مالک رضی اللہ تعالٰی عنہ اٹھے اور کہا: میں دو عورتوں کے دو کمروں کے درمیان رہتا تھا کہ ایک نے دوسری کو خیمے کی لکڑی مار کر قتل کر دیا، نیز اس کے پیٹ کا بچہ بھی مر گیا۔ نبی اکرم صلی اللہ علیہ وسلم نے پیٹ کے بچے کی دیت میں ایک غلام یا لونڈی دینے کا حکم دیا اور اس عورت کے بدلے قاتل عورت کو قتل کرنے کا حکم دیا۔","f2":"(۱) حضرت عمر رضی اللہ تعالٰی عنہ کے دور میں شاید اسی قسم کا مسئلہ پیش آیا ہوگا کہ عورت بھی ماری گئی اور پیٹ کا بچہ بھی۔ اس لیے پوچھنے کی ضرورت پیش آئی۔ واللہ اعلم! (۲) ’’دو عورتیں‘ یہ دونوں عورتیں آپس میں سوکنیں تھیں۔ سوکنا پے میں ایسا ممکن ہے۔ (۳) ’’پیٹ کے بچے کی دیت‘‘ جبکہ بچے میں روح پھونکی جا چکی ہو، یعنی حمل چار ماہ کا ہو جائے تو اس کے بعد پیدائش تک کسی بھی وقت کسی کی ضرب سے بچہ ضائع ہو جائے تو اس کی دیت غلام یا لونڈی یا قیمت کی صورت میں لاگو ہوگی۔ پیدائش کے بعد کوئی مار دے، خواہ اس نے ایک ہی سانس لیا ہو تو پھر قصاص یا پوری دیت، یعنی سو اونٹ ادا کرنے پڑیں گے۔ (۴) ’’قتل کرنے کا حکم دیا‘‘ گویا قاتل کو قتل کیا جائے گا، خواہ اس نے ڈنڈے سوٹے وغیرہ ہی سے مارا ہو الا یہ کہ مقتول کے اولیاء معاف کر دیں تو پھر دیت ہوگی۔"}],[4740,"انس رضی اللہ عنہ سے روایت ہے کہ ایک یہودی نے زیور کی خاطر ایک لڑکی کو قتل کر دیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس (لڑکی) کے قصاص میں اسے مار ڈالنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک یہودی نے ایک لڑکی کو اس کی بالیاں اتارنے کی خاطر قتل کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس یہودی کو اس لڑکی کے عوض قتل کر دیا۔","f2":"جمہور اہل علم کے نزدیک مرد عورت کو قتل کرے تو اسے قصاصاً قتل کر دیا جائے الا یہ کہ معافی ہو جائے۔ مذکورہ واقعہ چونکہ ’’ڈاکے‘‘ کی تعریف میں آتا ہے، اس لیے آپ نے مقتولہ کے اولیاء سے معافی کا عندیہ معلوم نہیں فرمایا بلکہ اسے خود قتل کرا دیا کیونکہ ڈاکا مع قتل محاربہ کی ذیل میں آتا ہے جس میں معافی نہیں۔"}],[4741,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک یہودی نے ایک لڑکی کا زیور لے لیا، اور پھر اس کا سر دو پتھروں کے درمیان کچل دیا، لوگوں نے اس عورت کو اس حال میں پایا کہ اس میں کچھ جان باقی تھی، وہ اسے لے کر لوگوں کے پاس پہنچے، یہ پوچھتے ہوئے: کیا اس نے مارا ہے، کیا اس نے مارا ہے، وہ بولی: ہاں، تو رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا، پھر اس کا بھی سر دو پتھروں کے درمیان کچل دیا گیا۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک یہودی نے ایک لڑکی کی بالیاں اتار لیں۔ پھر اس کا سر دو پتھروں کے درمیان کچیل دیا۔ لوگوں نے لڑکی کو دیکھا تو اس میں کچھ جان باقی تھی۔ وہ لوگ اس کے سامنے مختلف اشخاص کا نام لے کر پوچھنے لگے: وہ فلاں تھا؟ وہ فلاں تھا؟ آخر (اس یہودی کے نام) پر لڑکی نے ہاں کا اشارہ کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تو اس یہودی کا سر بھی اسی طرح دو پتھروں کے درمیان کچل دیا گیا۔","f2":"تفصیل کے لیے دیکھیے، حدیث: ۴۰۴۹، ۴۰۵۰۔"}],[4742,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ایک لڑکی نکلی وہ زیور ہار پہنے ہوئے تھی، ایک یہودی نے اسے پکڑا اور اس کا سر کچل دیا اور جو زیور وہ پہنے ہوئے تھی اسے لے لیا، پھر وہ پائی گئی، اس کی سانس چل رہی تھی، اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، تو آپ نے پوچھا: \"تمہیں کس نے قتل کیا؟\" کیا فلاں نے؟ اس نے اپنے سر کے اشارے سے کہا: نہیں، آپ نے فرمایا: \"کیا فلاں نے؟\" یہاں تک کہ اس یہودی کا نام آیا، اس نے سر کے اشارے سے کہا: ہاں، تو اسے گرفتار کیا گیا، اس نے اقبال جرم کر لیا، رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا اور دو پتھروں کے درمیان اس کا سر کچل دیا گیا۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: ایک لڑکی گھر سے نکلی۔ اس کے کانوں میں بالیاں تھیں۔ ایک یہودی نے اسے پکڑ لیا اس کا سر کچلا اور زیورات اتار کر لے گیا۔ جب اس لڑکی کو دیکھا گیا تو اس میں کچھ جان باقی تھی۔ اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا تو آپ نے اس سے پوچھا: ’’تجھے کس نے مارا ہے؟ کیا فلاں نے؟‘‘ اس نے سر سے اشارہ کیا، نہیں۔ فرمایا: ’’فلاں نے؟‘‘ حتیٰ کہ آپ نے اس یہودی کا نام لیا تو اس نے سر کے اشارے سے ہاں کہا۔ اس یہودی کو پکڑ کر لیا گیا۔ آخر اس نے تسلیم کرلیا تو رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا اور اس کا سر بھی اسی طرح دو پتھروں کے درمیان کچل دیا گیا۔"}],[4743,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کا قتل جائز نہیں ہے مگر جب تین صورتوں میں سے کوئی ایک صورت ہو ۱؎: شادی شدہ ہو کر زنا کرے تو اسے رجم کیا جائے گا، کوئی شخص کسی مسلمان کو جان بوجھ کر (ناحق) قتل کرے، کوئی اسلام سے نکل جائے اور اللہ اور اس کے رسول کے خلاف محاذ جنگ بناتا پھرے، تو اسے قتل کیا جائے گا، یا سولی پر چڑھایا جائے گا، یا پھر جلا وطن کیا جائے گا\"۔\n§وضاحت\n۱؎: اور ان تین صورتوں میں \" کافر کے بدلے مسلم کو قتل کرنے کی بات نہیں ہے \" اسی سے مؤلف کا باب پر استدلال ہے، جو بہرحال مبہم ہے، لیکن اگلی حدیث اس باب میں بالکل واضح ہے۔ کافر چاہے حربی ہو یا ذمی، یہی جمہور علماء امت کا قول ہے۔ البتہ ذمی کے قتل کا گناہ بہت ہی زیادہ ہے، دیکھئیے اگلی حدیث۔","الألباني: صحيح",{"u2":"ام المومنین حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی مسلمان کو قتل کرنا جائز نہیں الا یہ کہ وہ ان تین جرائم میں سے کوی جرم کرے: شادی شدہ ہو کر زنا کرے تو اسے رجم کیا جائے گا۔ کسی مسلمان شخص کو جان بوجھ کر قتل کر دے۔ یا اسلام سے خارج ہو جائے اور اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم سے جنگ شروع کر دے تو اسے قتل کیا جائے گا یا سولی پر لٹکایا جائے گا یا اپنے علاقے سے جلا وطن کر دیا جائے گا۔‘‘","f2":"مصنف رحمہ اللہ کا استدلال ظاہر الفاظ سے ہے کہ ان تین جرائم کے علاوہ کسی مسلمان کو قتل کرنا جائز نہیں۔ اور ان میں دوسرا جرم کسی مسلامن کو قتل کرنے کا ہے نہ کہ کافر کو۔ اس استدلال کی تائید آئندہ احادیث سے بھی ہو رہی ہے جن میں صراحتاً فرمایا گیا ہے کہ کسی مسلمان کو کافر کے بدلے قتل نہیں کیا جائے گا۔ باقی رہا النفس بالنفس تو یہ عام نہیں کیونکہ حربی کافر کے بدلے کوئی شخص بھی مسلمان کو قتل کرنے کا قائل نہیں۔ جس طرح حربی کا فر مستثنیٰ ہے، اسی طرح ان احادیث کی بنا پر ذمی کافر بھی مستثنیٰ ہے۔ (مزید تفصیل کے لیے دیکھیے، فوائد و مسائل حدیث: ۴۷۳۸)"}],[4745,"ابوجحیفہ کہتے ہیں کہ ہم نے علی رضی اللہ عنہ سے کچھ پوچھا، ہم نے کہا: کیا آپ کے پاس قرآن کے سوا رسول اللہ صلی اللہ علیہ وسلم کی کوئی چیز ہے؟ انہوں نے کہا: نہیں، اس ذات کی قسم، جس نے دانے کو پھاڑا اور جان کو پیدا کیا، سوائے اس کے کہ اللہ تعالی ایک بندے کو جو قرآن کی سمجھ دیدے، یا جو اس صحیفہ میں ہے، میں نے کہا: اس صحیفہ میں کیا ہے؟ انہوں نے کہا: اس میں دیت کے احکام ہیں، قیدیوں کو چھوڑنے کا بیان ہے، اور یہ حکم ہے کہ کوئی مسلمان کافر کے بدلے قتل نہ کیا جائے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ تعالٰی عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے عام لوگوں کے علاوہ مجھے کوئی خصوصی وصیت نہیں فرمائی مگر میری تلوار کی میان میں ایک تحریر ہے۔ لوگ آپ سے اصرار کرتے رہے (کہ آپ وہ تحریر دکھائیں) حتی کہ آپ نے وہ تحریر نکالی۔ اس میں لکھا تھا: ’’تمام اہل ایمان کے خون برابر حیثیت رکھتے ہیں۔ ایک عام مومن بھی کسی شخص کو تمام مسلمانوں کے مقابلے میں ایک ہاتھ کی طرح یکجان ہیں۔ کسی مسلمان کو کسی کافر کے بدلے قتل نہیں کیا جا سکتا اور کسی ذمی کو اس کے ذمی ہوتے ہوئے قتل نہیں کیا جا سکتا۔‘‘"}],[4746,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو چھوڑ کر مجھے کوئی بات نہیں بتائی سوائے اس کے جو میری تلوار کی نیام میں رکھے اس صحیفہ میں ہے، لوگوں نے ان کا پیچھا نہ چھوڑا یہاں تک کہ انہوں نے وہ صحیفہ نکالا، اس میں لکھا تھا: \"سب مسلمانوں کے خون برابر ہیں، ان کا ادنی اور معمولی آدمی بھی کسی کا ذمہ لے سکتا ہے، اور وہ اپنے دشمن کے خلاف ایک ہاتھ کی طرح (متحد) ہیں، کسی کافر کے بدلے کوئی مومن نہیں مارا جائے گا، اور نہ کوئی ذمی جب تک وہ ذمہ میں رہے\"۔","الألباني: صحيح",{"u2":"اشتر نخعی سے روایت ہے کہ انھوں نے حضرت علی رضی اللہ تعالٰی عنہ سے کہا کہ لوگوں میں ایسی باتیں بہت پھیلی ہوئی ہیں جو وہ (ادھر ادھر سے) سنتے ہیں۔ اگر رسول اللہ صلی اللہ علیہ وسلم نے آپ کو کوئی خصوصی علم یا وصیت عطا فرمائی ہے تو ہمیں بیان فرمائیں۔ حضرت علی رضی اللہ تعالٰی عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے کوئی خصوصی علم یا وصیت نہیں فرمائی جو دوسرے لوگوں کو عطا نہ فرمائی ہو۔ البتہ میری تلوار کی میان میں ایک تحریر موجود ہے۔ دیکھا تو اس میں یہ لکھا تھا: ’’تمام اہل ایمان کے خون برابر ہیں۔ ایک عام مسلمان بھی سب مسلمانوں کی طرف سے پناہ دے سکتا ہے۔ کسی مومن کو کسی کافر کے بدلے قتل نہیں کیا جا سکتا اور نہ کسی ذمی کو اس کے ذمی ہوتے ہوئے قتل کیا جا سکتا ہے۔‘‘ یہ روایت مختصر ہے۔"}],[4747,"اشتر کہتے ہیں کہ انہوں نے علی رضی اللہ عنہ سے کہا: لوگوں میں مشہور ہو رہی ہیں جو وہ سن رہے ہیں، لہٰذا اگر رسول اللہ صلی اللہ علیہ وسلم نے آپ سے کوئی بات کہی ہو تو اسے بیان کر دیجئیے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے کوئی بات ایسی نہیں بتائی جو لوگوں کو نہ بتائی ہو، سوائے اس کے جو ایک صحیفہ میری تلوار کی نیام میں ہے، اس میں لکھا ہے: \"مومنوں کا خون برابر ہے، ان کا معمولی آدمی بھی کسی کا ذمہ لے سکتا ہے، کوئی مومن کسی کافر کے بدلے قتل نہیں کیا جائے گا اور نہ کوئی ذمی جب تک وہ عہد پر قائم رہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی ذمی کو ناحق قتل کرے، اللہ تعالیٰ نے اس پر جنت حرام فرما دی ہے۔‘‘","f2":"’’جنت حرام‘‘ یعنی اس شخص پر جنت میں پہلے پہل داخلہ حرام ہے کیونکہ یہ ایسا جرم ہے جس کی سزا ضرور ملے گی، لہٰذا وہ اولین طور پر جنت میں داخل نہیں ہو سکے گا۔ یہ مطلب نہیں کہ وہ کبھی جنت میں نہیں جائے گا کیونکہ یہ بات تو کسی مومن کو قتل کرنے کی صورت میں بھی نہیں کہی جا سکتی۔ شریعت کی واضح نصوص صراحتاً دلالت کرتی ہیں کہ کسی بھی کبیرہ گناہ کا مرتکب ہمیشہ کے لیے جہنمی نہیں ہوگا، آخر کار وہ جنت میں ضرور جائے گا بشرطیکہ وہ کلمہ گو اور موحد ہو۔ قتل بھی گناہ کبیرہ ہی ہے۔ تفصیلی بحث حدیث نمبر ۴۰۰۴ میں گزر چکی ہے۔ (ذمی کے قتل کی بحث کے لیے دیکھیے، فوائد ومسائل حدیث: ۴۷۳۸)"}],[4748,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی ذمی کو بلا وجہ قتل کیا تو اللہ تعالی نے اس کے لیے جنت حرام کر دی ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی اسے «دخول اولیں» نصیب نہیں ہو گا۔\nابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی ذمی کی جان لی جب کہ اس کا خون جائز نہ تھا تو اللہ تعالی نے اس کے لیے جنت کی خوشبو حرام کر دی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے کسی ذمی کو ناحق قتل کیا، اللہ تعالیٰ نے اس پر جنت تو ایک طرف اس کی خوشبو سونگھنا تک حرام کر دیا ہے۔‘‘"}],[4749,"ایک صحابی رسول رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اہل ذمہ میں سے کسی کا قتل کیا تو وہ جنت کی خوشبو نہیں پائے گا، حالانکہ اس کی خوشبو ستر سال کی مسافت کی دوری سے آتی ہے\"۔","الألباني: صحيح",{"u2":"نبی کریم صلی اللہ علیہ وسلم کے ایک صحابی سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی ذمی کو قتل کرے گا وہ جنت کی خوشبو بھی نہیں پائے گا حالانکہ اس کی خوشبو ستر سال کے فاصلے سے آتی ہے۔‘‘","f2":"’’اس کی خوشبو ستر سال کے فاصلے سے آتی ہے‘‘ جنت کی خوشبو محسوس ہونے کی مسافت او فاصلے کی بابت شدید اختلاف ہے۔ اس کی وجہ یہ ہے کہ اس مفہوم کی احادیث کئی ایک ہیں۔ کسی حدیث میں ستر سال کا ذکر ہے تو کسی میں چالیس سال کا۔ مزید برآں یہ کہ کچھ احادیث میں سو سال کا ذکر ہے، کچھ میں پانچ سو سال کا اور بعض میں ہزار سال کا بھی ذکر ہے۔ اس اختلافِ مسافت کی بابت اہل علم محدثین کرام رحمہم نے مختلف توجیہات بیان فرمائی ہیں۔ حافظ ابن حجر رحمہ اللہ فرماتے ہیں کہ میرے نزدیک ان احادیث کے مابین جمع وتطبیق کی صورت یہ ہے کہ موقف (جس جگہ روز قیامت لوگ کھڑے ہوں گے) سے کم از کم فاصلہ جہاں جنت کی خوشبو آسکتی ہے وہ چالیس سال کی مدت کا ہے۔ اس سے زیادہ ستر سال کا فاصلہ ہے۔ یا پھر یہ عدد مبالغے کے لیے استعمال کیے گئے ہیں۔ اسی طرح پانچ سو برس، پھر ان میں سب سے زیادہ فاصلہ جہاں سے جنت کی خوشبو آسکتی ہے، ہزار سال کا ہے۔ حافظ عراقی رحمہ اللہ فرماتے ہیں کہ ان مختلف روایات میں تطبیق اس طرح ہوگی کہ یہ مکتلف لوگوں کے باہمی تفاوت درجات کے اعتبار سے ہے۔ جن کے درجات بلند ہوں گے انھیں زیادہ مسافت سے بھی جنت کی خوشبو آئے گی اور جو درجات ومنازل کے لحاظ سے کم ہوں گے انھیں کم اور تھوڑے فاصلے سے جنت کی خوشبو آئے گی۔ ابن العربی کا کہنا ہے کہ جنت کی خوشبو اپنی طبیعت و عادت کی بنیاد پر نہیں پائی جا سکتی بلکہ اللہ تعالیٰ اپنی مشیت سے بندے کے اندر اس کے ادراک کی صلاحیت پیدا فرما دے گا، جس کی بنا پر مسافت سے جنت کی خوشبو آئے گی، کبھی ستر سال کی مسافت سے خوشبو آئے گی تو کبھی پانچ سو سال کی مسافت سے۔ واللہ اعلم! تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی للاتبوبی: ۳۶/ ۵۰، ۵۱)"}],[4750,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اہل ذمہ میں سے کسی کو قتل کیا، وہ جنت کی خوشبو نہیں پائے گا، حالانکہ اس کی خوشبو چالیس سال کی مسافت سے آتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمروبن رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔جس شخص نے کسی ذمی کو قتل کیا، وہ جنت کی خوشبو تک نہیں پا سکے گا جبکہ اس کی خوشبو تو چالیس سال کے فاصلے سے محسوس ہوتی ہے۔‘‘","f2":"’’چالیس سال‘‘ چالیس سال میں ستر کی نفی نہیں، لہٰذا یہ روایت ساب قہ روایت کے خلاف نہیں۔ اور اگر کثرت کے معنی مراد ہوں تو پھر تو سرے سے کوئی اشکال نہیں۔ مقصد یہ ہے کہ وہ جنت سے بہت دور رہے گا۔ لیکن اس سے مراد ابتدا ہے ورنہ آخر کار ہر مومن جنت میں جائے گا جیسا کہ پیچھے بیان ہو چکا ہے۔"}],[4751,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ غریب لوگوں کے ایک غلام نے امیر لوگوں کے ایک غلام کا کان کاٹ لیا، وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے تو آپ نے انہیں کچھ نہ دلایا۔\n§وضاحت\n۱؎: اس حدیث سے مؤلف کا یہ اپنا استدلال ہے، جب کہ امام ابوداؤد رحمہ اللہ نے اس پر جو باب باندھا ہے وہ اس حدیث کے مفہوم کی صحیح ترجمان ہے ان کے الفاظ ہیں \" فقراء کے غلام کی جنایت کا باب \" تب حدیث کا مطلب ہو گا \" مجرم غلام اگر غریب لوگوں کا ہو گا تو اس سے ساقط ہو جائے گا۔ لیکن مؤلف کا یہ استنباط بہرحال باقی ہے کہ جب یہ جنایت قتل سے کم تر ہو، ورنہ قتل کے بدلے اگر قصاص کا فیصلہ ہو تو بہرحال غلام سے بھی قصاص لیا جائے گا۔ اور دیت کے فیصلے کی صورت میں اگر مالک غریب ہے تو بیت المال سے دیت دی جائے گی اور امام خطابی کے بقول یہاں \" غلام \" بمعنی \" لڑکا ہے نہ کہ غلام بمعنی \" عبد \" یعنی اگر غریبوں کے کسی لڑکے نے قتل سے کم تر جنایت کا ارتکاب کیا تو اس کے غریب سرپرستوں سے دیت ساقط ہو جائے گی۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمران بن حصین رضی اللہ تعالٰی عنہ سے روایت ہے کہ فقیر لوگوں کے ایک غلام نے مالدار لوگوں کے ایک غلام کا کان کاٹ دیا۔ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے تو آپ نے ان کو کوئی معاوضہ نہ دلایا۔","f2":"(۱) مصنف رحمہ اللہ نے یہاں غلام مملوک کے معنی میں لیا ہے جب کہ بعض محققین نے یہاں غلام کے معنی بچہ کیے ہیں۔ عربی میں لفظ غلام دونوں معانی کے لیے استعمال ہوتا ہے۔ ظاہر ہے بچے پر قصاص نہیں۔ البتہ اگر غلام ہی مراد ہو تو یہ خطا کا مقدمہ ہوگا، یعنی اس سے خطا کان کاٹا گیا اور خطا کی صورت میں بھی قصاص نہیں ہوتا۔ دونوں صورتوں میں اس کے اولیاء پر دیت آنی تھی لیکن وہ خود کنگال تھے۔ ان سے کیا وصول ہونا تھا؟ لہٰذا آپ نے صلح کروا دی۔ (۲) محقق کتاب نے اس روایت کی سند کو ضعیف قرار دیا ہے جبکہ دیگر محققین اس روایت کو صحیح الاسناد قرار دیتے ہیں اور دلائل کی رو سے ان کی رائے ہی صحیح ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی للاتبوبي: ۳۶/ ۵۴- ۵۷)"}],[4752,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانت میں قصاص کا فیصلہ فرمایا، اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی کتاب قصاص کا حکم دیتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دانت میں قصاص کا حکم جاری فرمایا اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کا حکم قصاص ہے۔‘‘","f2":"دانت مکمل اکھڑ جائے تو توڑنے والے کا دانت قصاصاً توڑا جا سکتا ہے، البتہ ایسے طریقے سے کہ دوسرے دانتوں کو ضعف نہ پہنچے۔ اور جو دانت اکھڑا ہو، فریق ثانی کا بھی وہی دانت اکھاڑا جائے گا۔ اور اگر مکمل نہ اکھڑے بلکہ اوپر سے ٹوٹ جائے تو فریق ثانی مناسب معاوضہ دے گا۔ اس میں قصاص نہیں ہوگا کیونکہ اتنا ہی دانت توڑنا ممکن نہیں ہوگا اور زیادہ توڑنا جائز نہیں، لہٰذا معاوضہ دیا جائے گا۔ واللہ اعلم"}],[4753,"سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے غلام کو قتل کیا، اسے ہم قتل کریں گے اور جس نے اپنے غلام کا کوئی عضو کاٹا تو اس کا عضو ہم کاٹیں گے\" ۱؎۔\n§وضاحت\n۱؎: اس آخری جملہ کی باب سے مطابقت ہے، لیکن یہ حدیث ضعیف ہے، پچھلی اور اگلی حدیثوں میں ہمارے لیے اس موضوع پر کافی مواد موجود ہے۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے غلام کو قتل کرے گا، ہم اسے قتل کر دیں گے اور جو کوئی اپنے غلام کی ناک یا کان کاٹ دے، ہم اس کی ناک کان کاٹ دیں گے۔‘‘","f2":"جب ناک کان میں قصاص ہو سکتا ہے تو دانت بھی ہو سکتا ہے۔ باب سے مناسبت اسی طرح ہے، تاہم یہ روایت ضعیف ہے جیسا کہ پہلے اس کی وضاحت گزر چکی ہے۔ دیکھیے فوائد ومسائل، حدیث: ۴۷۴۰۔"}],[4754,"سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے غلام کو خصی کیا اسے ہم خصی کریں گے اور جس نے اپنے غلام کا عضو کاٹا ہم اس کا عضو کاٹیں گے\"۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے غلام کو خصی کرے، ہم اسے خصی کر دیں گے اور جو اپنے غلام کی ناک کان کاٹے گا، ہم اس کی ناک کان کاٹیں گے۔‘‘\nیہ الفاظ ابن بشار کے ہیں۔","f2":"یہ روایت امام نسائی رحمہ اللہ نے دو استادوں: محمد بن مثنیٰ اور محمد بن بشار سے سنی ہے۔ مذکورہ الفاظ استاد محمد بن بشار کے ہیں، نیز یہ روایت ضعیف ہے جیسا کہ تفصیل گزشتہ اوراق میں گزر چکی ہے۔"}],[4755,"انس رضی اللہ عنہ سے روایت ہے کہ ربیع کی بہن ام حارثہ رضی اللہ عنہا ۱؎ نے ایک شخص کو زخمی کر دیا، وہ لوگ مقدمہ لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قصاص ہو گا قصاص\"، ام ربیع رضی اللہ عنہا بولیں: اللہ کے رسول! کیا فلاں عورت سے قصاص لیا جائے گا؟ نہیں، اللہ کی قسم! اس سے کبھی بھی قصاص نہ لیا جائے گا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی ذات پاک ہے، ام ربیع! قصاص تو اللہ کی کتاب کا حکم ہے\"، وہ بولیں: نہیں، اس سے ہرگز قصاص نہ لیا جائے گا، وہ کہتی رہیں، یہاں تک کہ انہوں نے دیت قبول کر لی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے بندوں میں سے بعض لوگ ایسے ہیں جو اگر اللہ کے بھروسے پر قسم کھا لیں تو اللہ ان کو (قسم میں) سچا کر دیتا ہے\"۔\n§وضاحت\n۱؎: اس روایت میں زخمی کرنے والی کا نام ربیع بنت نضر کی بہن \" ام حارثہ \" ہے اور اعتراض کرنے والی ربیع ہیں، جب کہ اگلی روایت میں زخمی کرنے کی نسبت خود ربیع بنت نضر کی طرف کی گئی ہے، اور اعتراض کرنے کی نسبت ان کے بھائی انس بن نضر کی طرف کی گئی ہے، حافظ ابن حزم وغیرہ علماء کی تحقیق کے مطابق یہ الگ الگ دو واقعات ہیں، حافظ ابن حجر کا رجحان بھی اسی طرف معلوم ہوتا ہے، :(دیکھئیے کتاب الدیات باب ۱۹ )۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے کہ ربیع کی بہن ام حارثہ نے ایک انسان کو زخمی کر دیا۔ وہ یہ مقدمہ نبی صلی اللہ علیہ وسلم کی خدمت میں لے گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قصاص دینا ہوگا۔‘‘ ربیع کی والدہ کہنے لگیں: رسول اللہ صلی اللہ علیہ وسلم! کیا ام حارثہ سے قصاص لیا جائے گا؟ اللہ کی قسم! ہرگز نہیں۔ اس سے کبھی قصاص نہیں لیا جائے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سبحان اللہ! ام ربیع! قصاص تو اللہ تعالیٰ کا حکم ہے۔‘‘ وہ کہنے لگیں، اللہ کی قسم! نہیں۔ اس سے کبھی قصاص نہیں لیا جائے گا۔ وہ اسی طرح کہتی رہیں حتیٰ کہ فریق ثانی نے دیت قبول کر لی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کے کچھ بندے ایسے بھی ہیں جو اللہ تعالیٰ کے بھروسے پر قسم کھا لیں تو اللہ تعالیٰ انھیں سچا کر دیتا ہے۔‘‘","f2":"(۱) اگر کوئی کسی کا دانت توڑ دے تو اس میں قصاص واجب ہے، یعنی دانت کے بدلے توڑنے والے کا بھی وہی دانت توڑ دیا جائے گا الا یہ کہ ان کی باہمی رضا مندی ہو جائے، معافی مل جائے یا قصاص نہ لیا جائے اور دیت قبول کر لی جائے۔ (۲) اس حدیث کی رو سے قصاص میں معافی کی سفارش کرنا مستحب ہے، البتہ یہ مسئلہ اپنی جگہ اٹل ہے کہ قصاص یا دیت لینے کا اختیار مستحق اور مظلوم ہی کو ہے، چاہے وہ قصاص پر راضی ہو یا دیت لینے پر۔ اسے نہ تو دیت لینے پر مجبور کیا جا سکتا ہے اور نہ اس پر کسی قسم کا دباؤ ہی ڈالا جا سکتا ہے۔ (۳) قصاص وحدود کے احکام عورتوں پر بھی لاگو ہوں گے۔ (۴) اس حدیث مبارکہ سے اولیاء اللہ کی کرامات کا بھی اثبات ہوتا ہے۔ (۵) ’’قصاص نہیں لیا جائے گا۔‘‘ یہ انکار نہیں کیونکہ ان مخلص مومنین کے بارے میں سوچا بھی نہیں جا سکتا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے فرمان اور کتاب اللہ کے حکم کا انکار کریں گے بلکہ یہ ان کے یقین کا اظہار ہے کہ ان شاء اللہ مصالحت کے حالات پیدا ہوجائیں گے اور قصاص کی نوبت نہیں آئے گی۔ اور فی الواقع ایسا ہی ہوا۔ (۶) ’’سچا کر دیتا ہے‘‘ کیونکہ وہ اللہ تعالیٰ کے نزدیک معزز ومکرم ہوتے ہیں اور ان کی قسم بھی اللہ تعالیٰ پر بھروسا اور توکل کا نتیجہ ہوتی ہے، نہ کہ تکبر وانکار کا۔"}],[4756,"انس رضی اللہ عنہ نے ذکر کیا کہ ان کی پھوپھی نے ایک لڑکی کے دانت توڑ دیے، تو نبی اکرم صلی اللہ علیہ وسلم نے قصاص کا فیصلہ کیا، ان کے بھائی انس بن نضر رضی اللہ عنہ نے کہا: کیا فلاں کا دانت توڑا جائے گا؟ نہیں، اس ذات کی قسم جس نے آپ کو حق کے ساتھ مبعوث فرمایا ہے، فلاں کے دانت نہیں توڑے جائیں گے، اور وہ لوگ اس سے پہلے اس کے گھر والوں سے معافی اور دیت کی بات کر چکے تھے، پھر جب ان کے بھائی نے قسم کھائی (وہ انس رضی اللہ عنہ کے چچا تھے، جو احد کے دن شہید ہوئے) تو وہ لوگ معاف کرنے پر راضی ہو گئے، چنانچہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے بعض بندے ایسے ہیں جو اگر اللہ کے بھروسے پر قسم کھا لیں تو اللہ انہیں سچا کر دکھاتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میری پھوپھی نے ایک لڑکی کا سامنے والا دانت توڑ دیا۔ اللہ کے نبی صلی اللہ علیہ وسلم نے قصاص کا حکم دے دیا۔ ان کے بھائی انس بن نضر رضی اللہ تعالٰی عنہ نے کہا: کیا اس کا دانت توڑ دیا جائے گا؟ نہیں، قسم ہے اس ذات کی جس نے آپ کو سچا نبی بنایا ہے! اس کا دانت نہیں توڑا جائے گا۔ اس سے پہلے انھوں نے اس لڑکی کے گھر والوں سے معافی اور دیت کی گزارش کی تھی (مگر وہ نہ مانے تھے)۔ پھر جب ان کے بھائی، جو حضرت انس کے چچا تھے اور جنگ احد میں شہید ہوئے، نے قسم کھا لی تو وہ لوگ معافی پر راضی ہو گئے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ کے کچھ بندے ایسے (بلند مرتبہ) ہوتے ہیں کہ اگر وہ اللہ تعالیٰ پر بھروسا کرتے ہوئے قسم کھا لیں تو اللہ تعالیٰ ان (کی قسم) کو سچا کر دیتا ہے۔‘‘","f2":"یہ روایت سابقہ روایت سے مختلف ہے۔ اس میں ہے کہ دانت توڑنے والی عورت، حضرت انس بن مالک رضی اللہ تعالٰی عنہ کی پھوپھی اور حضرت انس بن مضر رضی اللہ تعالٰی عنہ کی بہن، حضرت ربیع رضی اللہ عنہا خود ہیں جبکہ سابقہ روایت میں ان (ربیع) کی بہن ام حارثہ کو زخمی کرنے والی کہا گیا ہے۔ دوسرا اختلاف یہ ہے کہ اس روایت کے مطابق قسم کھانے والی ام ربیع کو کہا گیا ہے۔ ظاہراً ان دونوں حدیثوں میں تضاد ہے۔ امام ابن حزم رحمہ اللہ نے پورے وثوق سے کہا ہے کہ یہ دو الگ الگ واقعات ہیں، تاہم ایک ہی عورت سے سرزد ہوئے ہیں، یعنی ایک دفعہ انھوں نے کسی کو زخمی کیا تو قسم ان کی والدہ نے اٹھائی اور جب دانت توڑے تو قسم کھانے والے ان کے بھائی تھے۔ امام نووی رحمہ اللہ فرماتے ہیں کہ یہ دو الگ الگ واقعات ہیں۔ ایک ربیع کا اور دوسرا ان کی بہن کا۔ ربیع نے کسی کا دانت توڑا تو قسم ان کے بھائی نے کھائی اور ان کی بہن ام حارثہ نے کسی انسان کو زخمی کیا تو اس وقت قسم کھانے والی ان کی والدہ تھیں۔ امام نووی رحمہ اللہ کی تطبیق ہی راجح معلوم ہوتی ہے کیونکہ احادیث کے ظاہر الفاظ کے قریب تر ہے۔ واللہ اعلم! مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ، شرح سنن النسائی: للاتبوبی: ۳۶/ ۶۰)"}],[4757,"انس رضی اللہ عنہ کہتے ہیں کہ ربیع نے ایک لڑکی کے دانت توڑ دیے، چنانچہ انہوں نے معاف کر دینے کی درخواست کی تو ان لوگوں نے انکار کیا، پھر ان کے سامنے دیت کی پیش کش کی گئی، تو انہوں نے اس کا بھی انکار کیا، چنانچہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، آپ نے انہیں قصاص کا حکم دیا، انس بن نضر رضی اللہ عنہ بولے: اللہ کے رسول! کیا ربیع کے دانت توڑے جائیں گے؟ نہیں، قسم اس ذات کی جس نے آپ کو حق کے ساتھ مبعوث فرمایا ہے، وہ نہیں توڑے جائیں گے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"انس! اللہ کی کتاب میں قصاص کا حکم ہے\"، پھر وہ لوگ راضی ہو گئے اور انہیں معاف کر دیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے بعض بندے ایسے ہیں جو اگر اللہ تعالی پر بھروسہ کر کے قسم کھائیں تو اللہ تعالی انہیں سچا کر دکھاتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: (میری پھوپھی) حضرت ربیع رضی اللہ عنہا نے ایک لڑکی کا سامنے والا دانت توڑ دیا۔ ان کے رشتہ داروں نے لڑکی کے رشتہ داروں سے معافی مانگی۔ انھوں نے انکار کر دیا۔ انھیں دیت کی پیش کش کی گئی تو انھوں نے پھر انکار کر دیا۔ پھر وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آگئے۔ آپ نے قصاص کا حکم جاری فرما دیا۔ حضرت انس بن نضر رضی اللہ تعالٰی عنہ نے کہا: اے اللہ کے رسول! ربیع کا دانت توڑا جائے گا؟ نہیں، قسم اس ذات کی جس نے آپ کو برحق نبی بنایا! ہرگز نہیں توڑا جائے گا۔ آپ نے فرمایا: ’’انس! اللہ تعالیٰ کی کتاب تو قصاص کا حکم دیتی ہے۔‘‘ اتنے میں فریق ثانی راضی ہوگیا اور انھوں نے معافی دے دی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلا شبہ اللہ تعالیٰ کے کچھ بندے ایسے ہیں کہ اگر اللہ تعالیٰ کا نام لے کر قسم کھا لیں تو اللہ تعالیٰ ان کی لاج رکھ لیتا ہے۔‘‘"}],[4758,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نے ایک آدمی کا ہاتھ کاٹ لیا، اس نے اپنا ہاتھ کھینچا، تو اس کا ایک دانت ٹوٹ کر گر گیا (یا دو دانت) اس نے رسول اللہ صلی اللہ علیہ وسلم سے فریاد کی، تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"تم مجھ سے کیا کہنا چاہتے ہو؟ کیا یہ کہ میں اسے حکم دوں کہ وہ اپنا ہاتھ تمہارے منہ میں دئیے رہے تاکہ تم اسے جانور کی طرح چبا ڈالو، اگر تم چاہو تو اپنا ہاتھ اسے دو تاکہ وہ اسے چبائے پھر اگر چاہو تو اسے کھینچ لینا\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے ثابت ہوتا ہے کہ اگر کوئی کسی کا ہاتھ اپنے دانتوں سے کاٹنے لگے اور وہ اپنا ہاتھ زور سے کھینچ لے جس کی وجہ سے اس کے دانت ٹوٹ جائیں تو ان دانتوں کا قصاص :(یا دیت ) ہاتھ کھینچنے والے سے نہیں لیا جائے گا، یہ بات صرف دانت کھینچنے میں ہی نہیں اس جیسے دیگر معاملات میں بھی ہو گی۔ دیکھئیے اسی حدیث پر مولف کا باب باندھنا «الرجل یدفع عن نفسہ» :(حدیث نمبر: ۴۷۶۷ )۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے دوسرے آدمی کے ہاتھ پر کاٹ لیا۔ اس نے اپنا ہاتھ کھینچا تو اس کے سامنے والا ایک دانت اکھڑ گیا۔ اس نے رسول اللہ صلی اللہ علیہ وسلم کی عدالت میں اس کے خلاف دعویٰ دائر کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا: ’’تو کیا چاہتا ہے؟ کیا تو چاہتا ہے کہ میں اسے کہوں کہ وہ اپنا ہاتھ تیرے منہ میں دیے رکھے اور تو اسے چباتا رہے، جیسے اونٹ چباتا ہے؟ اگر تو چاہتا ہے تو اپنا ہاتھ اس کے منہ میں ڈال دے تاکہ وہ اسے چبائے۔ پھر تو چاہے تو اپنا ہاتھ کھینچ لینا۔‘‘","f2":"(۱) مقصد یہ ہے کہ اگر کوئی شخص کسی کو دانت کاٹے اور دوسرا شخص، کاٹنے والے کے منہ سے اپنا ہاتھ کھینچ لے جس کی وجہ سے دانت کاٹنے والے کا دانت ٹوٹ جائے تو اس کا کوئی قصاص نہیں ہوگا۔ اگر اس میں قصاص واجب ہوتا تو رسول اللہ صلی اللہ علیہ وسلم قصاص لے کر دیتے۔ (۲) اس حدیث مبارکہ سے ثابت ہوا کہ فیصلہ کرانے کے لیے حاکم وقت کے پاس مقدمہ پیش کرنا درست ہے، نیز یہ بھی ثابت ہوا کہ انسان خود بخود ہی قصاص لینا شروع نہ کر دے۔ ایسا کرنے سے ظلم وزیادتی اور شر وفساد پھیلنے کا اندیشہ ہے جس سے معاشرے کا امن وامان تباہ ہوگا۔ (۳) بوقت ضرورت آدمی کو جانور کے ساتھ تشبیہ دینا جائز ہے۔ اس کا اصل مقصد ایسے برے فعل سے نفرت دلانا ہوتا ہے جو اس کے شایانِ شان نہ ہو۔ یہی وجہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس شخص کے اس غلط کام کو جانور کے کام کے ساتھ تشبیہ دی ہے۔ (۴)اس حدیث مبارکہ سے یہ بھی ثابت ہوا کہ حملہ آور سے اپنا دفاع کرنا، شرعاً درست اور جائز ہے۔ بالخصوص جب اس کے بغیر خلاصی ناممکن ہو۔ اس دوران حملہ آور کا اگر کوئی عضو ضائع بھی ہو جائے تو دفاع کرنے والے سے قصاص نہیں لیا جائے گا جیسا کہ حدیث میں مذکور ہاتھ چبانے والے شخص کا دانت اکھڑ گیا اور آپ نے اس کی کوئی قیمت نہ لگائی۔"}],[4759,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے دوسرے کا ہاتھ کاٹ لیا، پہلے نے اسے کھینچا تو دوسرے کا دانت نکل پڑا، معاملہ نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچا تو آپ نے اسے کچھ نہ دلایا اور فرمایا: \"کیا چاہتے ہو کہ تم اونٹ کی طرح اپنے بھائی کا گوشت چباؤ\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نے دوسرے کے بازو پر کاٹ کھایا۔ اس نے اپنا بازو کھینچا تو اس (کاٹنے والے) کا سامنے والا دانت گر گیا۔ یہ مقدمہ نبی اکرم صلی اللہ علیہ وسلم کی عدالت میں پیش کیا گیا۔ آپ نے دانت کا کوئی معاوضہ نہیں دلوایا بلکہ فرمایا: ’’تیرا مقصد یہ ہے کہ تو اونٹ کی طرح اپنے بھائی کا گوشت چباتا رہتا؟ (اور وہ کچھ بھی نہ کرتا)۔‘‘"}],[4760,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ یعلی رضی اللہ عنہ کا ایک شخص سے جھگڑا ہو گیا ۱؎، ان میں سے ایک نے دوسرے کو دانت کاٹا، پھر ایک نے اپنا ہاتھ کھینچا تو دوسرے کا دانت نکل پڑا، وہ لوگ جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، آپ نے فرمایا: \"تم میں سے ایک آدمی اونٹ کی طرح اپنے بھائی کے ہاتھ کو کاٹتا ہے (پھر دیت مانگتا ہے) اسے دیت نہیں ملے گی\"۔\n§وضاحت\n۱؎: اس روایت میں صراحت ہے کہ دانت کاٹنے والے یعلی بن امیہ رضی اللہ عنہ تھے اور جس کو دانت کاٹا تھا وہ ان کا مزدور تھا، چونکہ معاملہ خود یعلی رضی اللہ عنہ کا تھا اس لیے اپنی روایتوں میں :(جو آگے آ رہی ہیں ) انہوں نے دانت کاٹنے والے کا نام مبہم کر دیا ہے۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے منقول ہے کہ حضرت یعلی رضی اللہ تعالٰی عنہ کا ایک آدمی سے جھگڑا ہوگیا تو ان میں سے ایک نے دوسرے کو دانت کاٹا۔ اس نے اس کے منہ سے اپنا ہاتھ کھینچا تو کاٹنے والے کا سامنے والا دانت گر گیا۔ وہ دونوں یہ جھگڑا رسول اللہ صلی اللہ علیہ وسلم کے پاس لے آئے تو آپ نے (غصے سے) فرمایا: ’’کیا تم میں سے ایک آدمی اپنے بھائی کو اونٹ کی طرح چباتا ہے؟ جاؤ اس دانت کی کوئی دیت نہیں۔‘‘"}],[4761,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ یعلی رضی اللہ عنہ نے اس شخص کے بارے میں کہا جس نے دانت کاٹ کھایا، تو اس کا دانت اکھڑ گیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے لیے دیت نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے مروی ہے کہ حضرت یعلی رضی اللہ تعالٰی عنہ نے اس آدمی کے بارے میں جس نے دوسرے کو کاٹا تھا جس سے اس کا دانت گر گیا تھا، فرمایا کہ نبی اکرم صلی اللہ علیہ وسلم نے (اس جیسے مقدمے میں) فرمایا تھا: ’’جاؤ تجھے کوئی دیت نہیں ملے گی۔‘‘"}],[4762,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے ایک آدمی کے ہاتھ میں دانت کاٹا تو اس کا دانت اکھڑ گیا، وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا اور آپ سے اس کا ذکر کیا تو آپ نے فرمایا: \"تم چاہتے تھے کہ تم اپنے بھائی کا ہاتھ اونٹ کی طرح چبا ڈالو\" پھر آپ نے اس کی دیت نہیں دلوائی۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے دوسرے آدمی کے بازو پر دانت کاٹا جس کے نتیجے میں اس کا سامنے والا دانت اکھڑ گیا۔ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا اور آپ سے اس کا تذکرہ کیا۔ آپ نے فرمایا: ’’تیرا مقصد یہ ہے کہ تو اپنے بھائی کا بازو اونٹ کی طرح چباتا رہتا۔‘‘ پھر آپ نے اس کا کوئی معاوضہ نہ دلوایا۔"}],[4763,"یعلی بن منیہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص سے ان کا جھگڑا ہو گیا ان میں سے ایک نے دوسرے کو دانت کاٹا، پہلے نے اپنا ہاتھ دوسرے کے منہ سے چھڑایا تو اس کا دانت اکھڑ گیا، معاملہ نبی اکرم صلی اللہ علیہ وسلم تک لایا گیا، تو آپ نے فرمایا: \"کیا تم میں سے کوئی اپنے بھائی کو جوان اونٹ کی طرح کاٹتا ہے\" پھر آپ نے اسے تاوان نہیں دلایا۔","الألباني: صحيح الإسناد",{"u2":"حضرت یعلی ابن منیہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ میں ایک آدمی سے لڑ پڑا۔ ہم میں سے ایک نے دوسرے کو دانت کاٹا تو اس نے اپنا ہاتھ اس کے منہ سے کھینچا اور اس کا دانت اکھیڑ دیا۔ یہ مقدمہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں پیش کیا گیا تو آپ نے فرمایا: ’’تم میں سے ایک آدمی اپنے بھائی کو اس طرح کاٹتا ہے، جیسے اونٹ؟‘‘ پھر آپ نے اسے باطل اور لغو قرار دیا۔ (اس کے دانت کا کوئی معاوضہ نہیں دلوایا۔))","f2":"کسی شخص پر حملہ ہو تو اسے دفاع کا حق ہے۔ دفاعی کارروائی کے دوران میں حملہ آور کا کوئی نقصان ہو جائے حتیٰ کہ وہ مر بھی جائے تو کوئی قصاص، دیت یا معاوضہ یا تاوان نہیں ادا کرنا پڑے گا۔ البتہ اگر وہ دفاع سے بڑھ کرجارحانہ کارروائی کرے تو پھر وہ ذمہ دار ہوگا۔ اور اس بات کا تعین عدالت کرے گی کہ اس نے دفاع کیا یا جارحانہ کارروائی بھی کی۔"}],[4764,"یعلی بن منیہ رضی اللہ عنہ سے روایت ہے کہ بنی تمیم کے ایک آدمی کا ایک شخص سے جھگڑا ہو گیا، تو پہلے نے دوسرے کا ہاتھ کاٹ کھایا، اس نے اسے کھینچا تو اس کا دانت نکل پڑا، وہ دونوں جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، آپ نے فرمایا: \"کیا تم میں سے کوئی اپنے بھائی کو جوان اونٹ کی طرح دانت کاٹتا ہے\"، پھر آپ صلی اللہ علیہ وسلم نے اس کی دیت نہیں دلوائی۔","الألباني: صحيح",{"u2":"حضرت یعلی ابن منیہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ بنو تمیم کے ایک آدمی نے ایک دوسرے شخص سے لڑائی کی اور اس کے ہاتھ پر دانت گاڑ دیے۔ اس نے اپنا ہاتھ کھینچا تو ساتھ ہی اس کا دانت بھی باہر آگیا۔ وہ یہ جھگڑا رسول اللہ صلی اللہ علیہ وسلم کے پاس لے گئے تو آپ نے فرمایا: ’’تم اپنے بھائی کو اس طرح کاٹتے ہو جس طرح اونٹ کاٹتا ہے؟‘‘ پھر آپ نے اسے باطل قرار دیا، یعنی اس کے دانت کا کوئی معاوضہ نہ دلوایا۔"}],[4765,"سلمہ بن امیہ اور یعلی بن امیہ رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ تبوک میں نکلے، ہمارے ساتھ ایک اور ساتھی تھے وہ کسی مسلمان سے لڑ پڑے، اس نے ان کے ہاتھ میں دانت کاٹ لیا، انہوں نے ہاتھ اس کے منہ سے کھینچا تو اس کا دانت اکھڑ گیا، وہ شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس دیت کا مطالبہ کرنے آیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے ایک آدمی اپنے بھائی کے پاس جا کر اونٹ کی طرح اسے دانت کاٹتا ہے، پھر دیت مانگنے آتا ہے، ایسے دانت کی کوئی دیت نہیں\"، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اسے دیت نہیں دلوائی۔","الألباني: صحيح لغيره",{"u2":"امیہ رضی اللہ تعالٰی عنہ کے بیٹوں حضرت سلمہ اور یعلی رضی اللہ عنہا سے روایت ہے، انھوں نے فرمایا: ہم غزوئہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ گئے۔ ہمارے ساتھ ہمارا ایک ساتھ بھی تھا۔ وہ کسی دوسرے مسلمان سے لڑ پڑا۔ اس آدمی نے اس کے بازو پر دانت گاڑ دیے۔ اس نے بازو اس کے منہ سے کھینچا تو ساتھ دانت بھی نکل آیا۔ وہ آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور دیت دلوانے کا مطالبہ کرنے لگا۔ آپ نے فرمایا: ’’تم میں سے کوئی شخص اپنے بھائی کو جا کر اس طرح کاٹتا ہے جیسے اونٹ چباتا ہے۔ پھر آکر دیت مانگنا شروع کر دیتا ہے؟ اس (طرح کے دانتوں) کی کوئی دیت نہیں۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے دانت کا کوئی معاوضہ نہ دلوایا۔"}],[4766,"یعلی رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے دوسرے شخص کا ہاتھ کاٹ کھایا تو پہلے شخص کا دانت اکھڑ گیا، وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، تو آپ نے اسے لغو قرار دیا ۱؎۔\n§وضاحت\n۱؎: یعنی دیت نہیں دلوائی۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت یعلی رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نے دوسرے آدمی کے بازو پر کاٹ کھایا جس سے اس کا سامنے والا دانت اکھڑ گیا۔ وہ آپ کے پاس (دیت لینے کے لیے) آیا تو آپ نے اسے رائیگاں قرار دیا۔ (اس کا کوئی معاوضہ نہیں دلوایا)۔"}],[4767,"یعلی رضی اللہ عنہ سے روایت ہے کہ انہوں نے ایک شخص کو نوکر رکھا، اس کی ایک آدمی سے لڑائی ہو گئی، تو اس نے اس کا ہاتھ کاٹ کھایا، چنانچہ اس کا دانت اکھڑ گیا، وہ اس کے ساتھ جھگڑتے ہوئے نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا تو آپ نے فرمایا: \"کیا وہ اپنا ہاتھ چھوڑ دیتا کہ وہ اسے اونٹ کی طرح چبا جائے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت یعلی رضی اللہ تعالٰی عنہ سے منقول ہے کہ انھوں نے ایک شخص کو نوکر رکھا۔ وہ کسی آدمی سے لڑ پڑا اور اس کا ہاتھ کاٹ کھایا۔ ساتھ ہی دانت بھی اکھڑ گیا۔ وہ یہ مقدمہ نبی صلی اللہ علیہ وسلم کی عدالت میں لے گیا۔ آپ نے فرمایا: ’’کیا وہ اپنا ہاتھ (تیرے منہ میں) چھوڑ دیتا کہ تو اسے اونٹ کی طرح چباتا رہتا؟‘‘"}],[4768,"یعلی رضی اللہ عنہ کہتے ہیں کہ میں غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ گیا، میں نے ایک شخص کو نوکر رکھا، پھر میرے نوکر کی ایک شخص سے لڑائی ہو گئی، تو دوسرے نے اسے دانت کاٹ لیا، چنانچہ اس کا دانت اکھڑ گیا، پھر وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا اور آپ سے اس کا تذکرہ کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے اسے لغو قرار دیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت یعلی رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: میں غزوئہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جنگ کو گیا تو میں نے ایک شخص نوکر رکھ لیا۔ پھر میرا نوکر کسی آدمی سے لڑ پڑا۔ اس آدمی نے اسے کاٹ کھایا حتیٰ کہ اس کا سامنے والا دانت گر گیا۔ وہ شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور آپ کے سامنے یہ بات ذکر کی۔ نبی اکرم صلی اللہ علیہ وسلم نے اسے رائیگاں قرار دیا۔ (اس کا کوئی معاوضہ نہ دلوایا)۔"}],[4769,"یعلی بن امیہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جیش العسرۃ ۱؎ (غزوہ تبوک) میں جہاد کیا، میرے خیال میں یہ میرا بہت اہم کام تھا، میرا ایک نوکر تھا، ایک شخص سے اس کا جھگڑا ہو گیا تو ان میں سے ایک نے دوسرے کی انگلی کاٹ کھائی، پھر پہلے نے اپنی انگلی کھینچی تو دوسرے آدمی کا دانت نکل کر گر پڑا، وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا، آپ نے اس کے دانت کی دیت نہیں دلوائی، اور فرمایا: \"کیا وہ اپنے ہاتھ تیرے منہ میں چھوڑ دیتا کہ تو اسے چباتا رہے؟\"۔\n§وضاحت\n۱؎: یہ اس آیت کریمہ: «الذين اتبعوه في ساعة العسرة» سے ماخوذ ہے اور یہ غزوہ تبوک کا دوسرا نام ہے، اس جنگ میں زاد سفر کی بے انتہا قلت تھی اسی لیے اسے ساعۃ العسرۃ کہا گیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت یعلی بن امیہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تنگی والے لشکر میں گیا اور میرے نزدیک میرا یہ عمل سب سے افضل عمل ہے۔ وہاں میرا ایک نوکر کسی آدمی سے لڑ پڑا۔ ان میں سے کسی ایک نے دوسرے کی انگلی پر دانت گاڑ دیا۔ اس نے جو انگلی کھینچی تو ساتھ ہی دانت بھی اکھڑ آیا۔ دوسرا شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ نے اسے کوئی معاوضہ نہ دلوایا بلکہ فرمایا: ’’کیا وہ اپنا ہاتھ تیرے منہ میں دیے رکھتا کہ تو اسے چبا ڈالتا؟‘‘","f2":"’’تنگی والا لشکر‘، اس سے مراد غزوئہ تبوک کا لشکر ہے کیونکہ یہ وقت تنگی کا تھا۔ موسم سخت گرم تھا۔ پھل اور فصلیں پک چکی تھیں۔ پچھلے پھل اور غلے ختم ہو چکے تھے۔ سفر بھی بہت لمبا تھا۔ دشمن بہت طاقت ور اور کثیر تھا۔ ایسے میں نکلنا بہت دشوار تھا۔ تبھی تو انھوں نے اس سفر کو اپنا سب سے افضل عمل قرار دیا ہے کیونکہ اجر مشقت کے حساب سے ملتا ہے۔"}],[4770,"یعلی رضی اللہ عنہ سے اس جیسے شخص جس نے دانت کاٹا ہو اور اس کا دانت اکھڑ گیا ہو کے بارے میں روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے لیے دیت نہیں ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت یعلی رضی اللہ تعالٰی عنہ سے اس شخص کے بارے میں جس نے ساتھ کو کاٹ کھایا تھا اور اس کا دانت اکھڑ گیا تھا، سابقہ روایت کی طرح بیان ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا تھا: ’’تجھے کوئی دیت نہیں ملے گی۔‘‘"}],[4771,"صفوان بن یعلی بن منیہ (امیہ) سے روایت ہے کہ یعلی بن منیہ (امیہ) رضی اللہ عنہ کے ایک نوکر کو ایک دوسرے شخص نے ہاتھ میں دانت کاٹ لیا، اس (نوکر)نے اپنا ہاتھ اس کے منہ سے کھینچا، یہ معاملہ نبی اکرم صلی اللہ علیہ وسلم کے پاس لے جایا گیا اور حال یہ تھا کہ اس آدمی کا دانت اکھڑ کر گر گیا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے لغو قرار دیا، اور فرمایا: \"کیا وہ تمہارے منہ میں اسے چھوڑ دیتا تاکہ تم اسے اونٹ کی طرح چبا جاؤ\"۔","الألباني: صحيح لغيره",{"u2":"حضرت صفوان بن یعلی ابن منیہ سے روایت ہے کہ میرے والد حضرت یعلی ابن منیہ رضی اللہ تعالٰی عنہ کے ایک نوکر کے بازو پر ایک دوسرے شخص نے دانت گاڑ دیے۔ اس نے اپنا ہاتھ اس کے منہ سے کھینچا تو اس کا دانت گر گیا۔ یہ مقدمہ نبی اکرم صلی اللہ علیہ وسلم کے پاس پیش ہوا تو آپ نے اس دانت کا کوئی معاوضہ نہ دلوایا بلکہ فرمایا: ’’کیا وہ اپنا ہاتھ تیرے منہ میں رکھ چھوڑتا کہ تو اسے اونٹ کی طرح چباتا رہتا۔‘‘"}],[4772,"صفوان بن یعلی سے روایت ہے کہ ان کے والد نے غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جہاد کیا، انہوں نے ایک نوکر رکھ لیا تھا، اس کا ایک شخص سے جھگڑا ہو گیا تو اس آدمی نے اس (نوکر) کے ہاتھ میں دانت کاٹ لیا، جب اسے تکلیف ہوئی تو اس نے اسے زور سے کھینچا، تو اس (آدمی) کا دانت نکل پڑا، یہ معاملہ رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچا، تو آپ نے فرمایا: \"کیا تم میں سے کوئی شخص یہ چاہتا ہے کہ اپنے بھائی کو چبائے جیسے اونٹ چباتا ہے؟\" چنانچہ آپ نے دانت کی دیت نہیں دلوائی۔","الألباني: صحيح",{"u2":"حضرت صفوان بن یعلیٰ سے روایت ہے کہ میرے والد غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ گئے۔ ساتھ ایک نوکر بھی لے گئے۔ وہ کسی آدمی سے لڑ پڑا۔ اس آدمی نے اس کی کلائی پر کاٹ لیا۔ جب اس کو تکلیف ہوئی تو اس نے زور سے ہاتھ کھینچا۔ ساتھ ہی دانت بھی اکھڑ آیا۔ یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پیش کیا گیا تو آپ نے فرمایا: ’’تم میں سے کوئی شخص اپنے بھائی کی طرف بڑھتا ہے اور اس کو اس طرح کاٹ کھاتا ہے جیسے اونٹ چباتا ہے۔‘‘ آپ نے اس کے دانت کا کوئی معاوضہ نہ دلوایا۔","f2":"(۱) مذکورہ روایت مختلف سندوں سے مروی ہے۔ بعض طرق میں لڑنے والے دونوں افراد کے نام مخفی رکھے گئے ہیں۔ بعض میں دانت کاٹنے والے کی صراحت ہے اور بعض میں جسے کاٹا گیا اس کا ذکر ہے۔ امام نووی رحمہ اللہ فرماتے ہیں کہ ممکن ہے یہ دو واقعات ہوں، ایک لڑائی کرنے والے حضرت یعلی اور دوسرا کوئی شخص ہو اور دوسرے میں حضرت یعلی کا نوکر اور دوسرا کوئی شخص ہو۔ لیکن راجح بات یہ معلوم ہوتی ہے کہ یہ ایک ہی واقعہ ہے اور تمام روایات میں تطبیق کی صورت یوں ہے کہ یہ لڑائی حضرت یعلی اور ان کے نوکر کے درمیان ہوئی۔ دانت کاٹنے والے حضرت یعلی خود تھے اور دانت بھی انھی کا ٹوٹا تھا۔ شاید اسی وجہ سے انھوں نے اپنا نام مخفی رکھا۔ حضرت عمران بن حصین نے حضرت یعلی کے نام کی صراحت کی ہے۔ (حدیث: ۴۷۶۴) اور جنھیں کاٹا گیا وہ ان کے نوکر تھے۔ اس طرح رجل من المسلمین، رجلا من بنی تمیم، عض الاخر اور عض الرجل سے مراد حضرت یعلی ہوں گے۔ (۲) بعض روایات میں یعلی بن امیہ ہے اور بعض میں یعلی ابن منیہ۔ اس میں کوئی اختلاف نہیں۔ امیہ حضرت یعلی رضی اللہ تعالٰی عنہ کے باپ کا نام ہے اور منیہ ماں کا اس لیے کبھی ان کی نسبت باپ کی طرف کی گئی اور کبھی ماں کی طرف، لہٰذا اس میں کوئی اشکال نہیں۔ تفصیل کے لیے دیکھیے: (فتح الباري شرح صحیح البخاری: ۱۲/ ۲۷۴، ۲۷۵)"}],[4773,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کچھ تقسیم کر رہے تھے کہ اسی دوران اچانک ایک شخص آپ کے اوپر گر پڑا تو آپ نے اسے ایک لکڑی جو آپ کے ساتھ تھی چبھا دی، وہ شخص نکل گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آؤ اور بدلہ لے لو\" اس نے کہا: اللہ کے رسول! میں نے تو معاف کر دیا۔","الألباني: ضعيف",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کوئی چیز تقسیم فرما رہے تھے کہ ایک آدمی آیا۔ اور (بے صبری میں) آپ پر اوندھا ہی ہوگیا۔ آپ نے اپنے ہاتھ میں پکڑی ہوئی چھڑی کی نوک اس کو مار دی۔ وہ آدمی (حلقہ سے) نکل گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بھائی! ادھر آ اور بدلہ لے لے۔‘‘ اس نے کہا: (نہیں) بلکہ میں نے معاف کر دیا۔"}],[4774,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کچھ تقسیم فرما رہے تھے کہ اسی دوران اچانک ایک شخص آپ پر گر پڑا، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے ایک لکڑی جو آپ کے پاس تھی چبھا دی، وہ شخص چیخ پڑا تو آپ نے اس سے فرمایا: \"آؤ، بدلہ لے لو\" اس نے کہا: اللہ کے رسول! میں نے تو معاف کر دیا۔","الألباني: ضعيف",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کوئی چیز تقسیم فرما رہے تھے کہ ایک آدمی (لینے کے لیے) آپ پر اوندھا ہی ہوگیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ میں پکڑی ہوئی ایک چھڑی سے اسے کچو کا لگایا تو وہ ہائے وائے کرنے لگا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: ’’ادھر آ اور بدلہ لے لے۔‘‘ اس نے کہا: اللہ کے رسول! (نہیں) بلکہ میں نے معاف کر دیا۔","f2":"مذکورہ دونوں روایتیں سنداً ضعیف ہیں، تاہم دیگر دلائل سے معلوم ہوتا ہے کہ آپ کسی پر ظلم نہیں کرتے تھے اور اگر کبھی آپ کسی پر سختی کرتے تو اپنے آپ کو بدلہ دینے کے لیے پیش کر دیتے۔ ایک روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت اسید بن حضیر رضی اللہ تعالٰی عنہ کی کوکھ میں لکڑی چبھوئی تو انھوں نے کہا: مجھے بدلہ دیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لے لو۔‘‘ انھوں نے کہا: آپ کے جسم پر تو قمیص ہے جبکہ مجھ پر قمیص نہیں تھی۔ (یہ بات سن کر) نبی صلی اللہ علیہ وسلم نے اپنی قمیص اوپر کر دی۔ اسید بن حضیر رضی اللہ تعالٰی عنہ نے آپ کو اپنے بازوؤں میں لے لیا اور آپ کے پہلو مبارک پر بوسہ دینے لگے اور کہا: اے اللہ کے رسول! میرا یہی ارادہ تھا۔ دیکھیے: (سنن ابی داود، الادب، باب فی قبلۃ الجسد، حدیث: ۵۲۲۴)"}],[4775,"عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ ایک شخص نے ان کے جاہلیت کے کسی باپ دادا کو برا بھلا کہا تو عباس رضی اللہ عنہ نے اسے تھپڑ مار دیا، اس کے آدمیوں نے آ کر کہا: وہ لوگ بھی انہیں تھپڑ ماریں گے جیسا کہ انہوں نے مارا ہے اور ہتھیار اٹھا لیے۔ یہ بات نبی اکرم صلی اللہ علیہ وسلم تک پہنچی تو آپ منبر پر چڑھے اور فرمایا: \"لوگو! تم جانتے ہو کہ زمین والوں میں اللہ تعالی کے نزدیک سب سے زیادہ باعزت کون ہے؟\" انہوں نے کہا: آپ، آپ نے فرمایا: \"تو عباس میرے ہیں اور میں عباس کا ہوں، تم لوگ ہمارے مردوں کو برا بھلا نہ کہو جس سے ہمارے زندوں کو تکلیف ہو\"، ان لوگوں نے آ کر کہا: اللہ کے رسول! ہم آپ کے غصے سے اللہ کی پناہ مانگتے ہیں، ہمارے لیے مغفرت کی دعا فرمائیے۔","الألباني: ضعيف",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے حضرت عباس کے جاہلی دور کے ایک جد امجد کو برا بھلا کہا۔ حضرت عباس رضی اللہ تعالٰی عنہ نے اسے تھپڑ رسید کر دیا۔ اس آدمی کے قبیلے والے آئے اور کہنے لگے: یہ بھی انھیں تھپڑ مارے گا جس طرح انھوں نے اسے تھپڑ مارا ہے حتیٰ کہ انھوں نے اسلحہ پہن لیا۔ یہ بات نبی اکرم صلی اللہ علیہ وسلم تک پہنچی۔ آپ منبر پر چڑھے اور فرمایا: ’’اے لوگو! تم روئے زمین پر بسنے والے لوگوں میں سے کس شخص کو اللہ تعالیٰ کے نزدیک زیادہ معزز ومحترم سمجھتے ہو؟‘‘ انھوں نے کہا: آپ کو۔ آپ نے فرمایا: ’’پھر سن لو! عباس مجھ سے ہیں اور میں ان سے ہوں۔ ہمارے فوت شدہ آباؤ اجداد کو برا نہ کہو۔ اس طرح تم ہم میں سے زندہ افراد کو تکلیف پہنچاؤ گے۔‘‘ وہ لوگ آپ کے پاس حاضر ہوئے اور کہا: ہم آپ کی ناراضی سے اللہ تعالیٰ کی پناہ مانگتے ہیں۔ (معاف فرما دیجئے اور) اللہ تعالیٰ سے ہمارے لیے بخش کی دعا فرمائیے۔","f2":"مذکورہ حدیث اگرچہ ضعیف ہے، تاہم ایسے معاملات میں قصاص صحیح احادیث سے ثابت ہے۔"}],[4776,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مسجد میں بیٹھا کرتے تھے، جب آپ کھڑے ہوتے، ہم کھڑے ہو جاتے، ایک دن آپ کھڑے ہوئے تو ہم بھی آپ کے ساتھ کھڑے ہوئے یہاں تک کہ جب آپ مسجد کے بیچوں بیچ پہنچے تو ایک شخص نے آپ کو پکڑا اور پیچھے سے آپ کی چادر پکڑ کر کھینچے لگا، وہ چادر بہت کھردری تھی، آپ کی گردن سرخ ہو گئی، وہ بولا: \"اے محمد! میرے لیے میرے ان دو اونٹوں کو لاد دیجئیے، آپ کوئی اپنے مال سے تو کسی کو دیتے نہیں اور نہ اپنے باپ کے مال سے\"، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، میں اللہ تعالی سے مغفرت طلب کرتا ہوں، میں تجھے نہیں دوں گا جب تک تو میری اس گردن کھینچنے کا بدلہ نہیں دے گا\"، اعرابی نے کہا: نہیں، اللہ کی قسم، میں بدلہ نہیں دوں گا، رسول اللہ صلی اللہ علیہ وسلم نے یہ تین بار فرمایا، ہر مرتبہ اس نے کہا: نہیں، اللہ کی قسم میں بدلہ نہیں دوں گا، جب ہم نے اعرابی کی بات سنی تو ہم دوڑ کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ ہماری طرف متوجہ ہوئے اور فرمایا: \"میں قسم دیتا ہوں، تم میں سے جو میری بات سنے اپنی جگہ سے نہ ہٹے، یہاں تک کہ میں اسے اجازت دے دوں\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے قوم کے ایک آدمی سے کہا: \"اے فلاں! اس کے ایک اونٹ پر جَو لاد دو اور ایک اونٹ پر کھجور\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ جا سکتے ہو\"۔","الألباني: ضعيف لكن قصة الأعرابي وجبذه وأمره صلی اللہ علیہ وسلم له بعطاء في ق",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مسجد میں بیٹھا کرتے تھے۔ جب آپ کھڑے ہوتے، ہم بھی آپ کے ساتھ کھڑے ہوتے۔ ایک دن آپ کھڑے ہوئے، ہم بھی آپ کے ساتھ کھڑے ہوئے حتیٰ کہ جب آپ مسجد کے درمیان پہنچے تو ایک آدمی آپ کو ملا۔ اس نے پیچھے سے آپ کی چادر پکڑ کر کھینچی۔ آپ کی چادر کھردری سی تھی، اس لیے آپ کی گردن سرخ ہوگئی۔ وہ شخص کہنے لگا: اے محمد! مجھے یہ دو اونٹ (غلہ) لاد دیجئے۔ آپ کون سا اپنے یا اپنے باپ کے مال سے دیتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں واقعتا اپنے مال سے نہیں دیتا اور میں اللہ تعالیٰ سے بخشش طلب کرتا ہوں (کہ ایسا غلط اعتقاد رکھوں) لیکن میں تجھے کچھ بھی نہیں دوں گا حتیٰ کہ تو مجھے گردن سے چادر کھینچنے کا قصاص دے۔‘‘ اس اعرابی نے کہا: اللہ کی قسم! میں آپ کو قصاص نہیں دوں گا۔ رسول اللہ صلی اللہ علیہ وسلم نے تین مرتبہ ایسے ہی فرمایا۔ وہ (اعرابی) ہر دفعہ یہی کہتا تھا: اللہ کی قسم! میں آپ کو قصاص نہیں دوں گا۔ ہم نے اعرابی کی باتیں سنیں تو ہم تیزی سے اس کی طرف بڑھے۔ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں آتے دیکھا تو فرمایا: ’’جو بھی شخص میری آواز سنتا ہے، میں اسے قسم دیتا ہوں کہ وہ اپنی جگہ سے حرکت نہ کرے حتیٰ کہ میں اسے اجازت دوں۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی سے کہا: ’’ارے! اس کو ایک اونٹ پر جو اور دوسرے اونٹ پر خشک کھجوریں لاد دے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے (دوسرے لوگوں سے) فرمایا: ’’جاؤ۔ چلے جاؤ۔‘‘","f2":"یہ روایت اس سیاق سے سنداً ضعیف ہے، تاہم اعرابی کے سوال کرنے اور چادر گلے میں ڈالنے کا واقعہ حضرت انس رضی اللہ تعالٰی عنہ سے صحیح بخاری میں مروی ہے۔ دیکھیے: (صحیح البخاری، الادب، حدیث: ۶۰۸۸)"}],[4777,"عمر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ اپنی ذات سے بدلا دلاتے تھے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عمر رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم اپنی ذات اقدس سے قصاص دلاتے تھے۔"}],[4778,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ابوجہم بن حذیفہ رضی اللہ عنہ کو زکاۃ لینے کے لیے بھیجا تو ایک شخص اپنے صدقے کے سلسلے میں ان سے لڑ گیا، تو ابوجہم نے اسے مار دیا، ان لوگوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! بدلہ دیجئیے، آپ نے فرمایا: \"اتنا اتنا مال لے لو\"، وہ اس پر راضی نہ ہوئے، تو آپ نے فرمایا: \"(اچھا) اتنا اتنا مال لے لو\"، تو وہ اس پر راضی ہو گئے، پھر آپ نے فرمایا: \"میں لوگوں سے خطاب کروں گا اور انہیں تمہاری رضا مندی کی اطلاع دوں گا\"، ان لوگوں نے کہا: ٹھیک ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے خطاب کیا اور فرمایا: \"یہ لوگ میرے پاس قصاص مانگنے آئے تھے تو میں نے ان پر اتنے اتنے مال کی پیش کش کی ہے اور وہ اس پر راضی ہیں\"، لیکن وہ لوگ بولے: نہیں، تو مہاجرین نے انہیں سزا دینے کا ارادہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں ٹھہر جانے کا حکم دیا، چنانچہ وہ لوگ باز رہے، پھر آپ نے انہیں بلایا اور فرمایا: \"کیا تم رضامند ہو؟\" وہ بولے: جی ہاں، آپ نے فرمایا: \"میں لوگوں سے خطاب کروں گا اور تمہاری رضا مندی کی انہیں اطلاع دوں گا\"، انہوں نے کہا: ٹھیک ہے، چنانچہ آپ نے لوگوں سے خطاب کیا پھر (ان سے) فرمایا:\"کیا تم اس پر راضی ہو؟\" وہ بولے: جی ہاں۔\n§وضاحت\n۱؎: امام ابوداؤد رحمہ اللہ نے اس حدیث پر باب باندھا ہے «العامل یصاب علی یدہ خطأ» یعنی \" عامل کے ذریعہ کسی کو غلطی سے زخم لگ جائے \" اس حدیث سے یہ ثابت ہوتا ہے کہ سرکاری عامل ہونے کی وجہ سے قصاص معاف نہیں ہو گا، ہاں دیت پر راضی ہو جانے کی صورت میں سرکاری بیت المال سے دیت دلوائی جائے گی جیسا کہ آپ صلی اللہ علیہ وسلم نے دلوائی۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے حضرت ابو جہم بن حذیفہ رضی اللہ تعالٰی عنہ کو صدقہ لینے کے لیے بھیجا۔ ایک آدمی نے صدقہ دینے کے بارے میں جھگڑا کیا تو حضرت ابو جہم رضی اللہ تعالٰی عنہ نے اس کو مارا۔ وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اے اللہ کے رسولک! ہمیں قصاص چاہیے۔ آپ نے فرمایا: ’’تمھیں اتنا معاوضہ دیتا ہوں۔‘‘ وہ راضی نہ ہوئے۔ آپ نے فرمایا: ’’اچھا تم اتنا (اور) لے لو۔‘‘ آخر وہ راضی ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں لوگوں کے سامنے خطبہ دے کر انھیں تمھارے راضی ہونے کی خبر دیتا ہوں۔‘‘ انھوں نے کہا: ٹھیک ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے خطبہ ارشاد فرمایا: ’’یہ لوگ میرے پاس قصاص لینے آئے تھے۔ میں نے انھیں اتنے مال کی پیش کش کی تو یہ راضی ہوگئے ہیں۔‘‘ لیکن وہ لوگ کہنے لگے: ہم راضی نہیں۔ مہاجرین نے ان کو سزا دینے کا ارادہ کیا لیکن آپ نے ان کو روک دیا۔ وہ رک گئے۔ آپ نے پھر ان کو بلایا اور فرمایا: ’’کیا تم اب راضی ہو؟‘‘ انھوں نے کہا: جی ہاں۔ آپ نے فرمایا: ’۔میں پھر لوگوں سے خطاب کروں گا اور انھیں بتاؤں گا کہ تم راضی ہوگئے ہو۔‘‘ انھوں نے کہا: ٹھیک ہے۔ آپ نے لوگوں سے سے خطاب فرمایا اور ان سے پوچھا: ’’تم راضی ہو؟‘‘ انھوں نے کہا: جی ہاں۔","f2":"(۱) اگر بادشاہ اور کوئی صاحب اختیار واقتدار حکمران کسی کے ساتھ اس قسم کی زیادتی اور مار کٹائی والا معاملہ کرے جیسا کہ حضرت ابو جہم رضی اللہ تعالٰی عنہ نے کیا تھا تو اس سے قصاص لیا جا سکتا ہے، تاہم فریق ثانی کو کچھ دے دلا کر بھی معاملہ رفع دفع کیا جا سکتا ہے۔ (۲) دیہاتی طبعاً سخت مزاج ہوتے ہیں اور لا علم بھی، اس لیے انھوں نے اس طرح کا رویہ اختیار کیا۔ رسول اکرم صلی اللہ علیہ وسلم نے ان کی جہالت کی وجہ سے ان کے رویے سے درگزر فرمایا جو آپ کی وسعت ظرفی اور حسن اخلاق کی دلیل ہے۔ اس سے معلوم ہوا کہ اہل علم کو عوام الناس کی بے ادیبوں کو صبر اور اخلاق سے برداشت کرنا چاہیے اور اپنی انا کا مسئلہ نہیں بنانا چاہیے۔ (۳) اس روایت کو دیگر محققین نے دیگر شواہد کی بنا پر صحیح کہا ہے۔ تفصیل کے لیے دیکھیے: (سنن ابن ماجہ (مترجم) طبع، دارالسلام، حدیث: ۲۶۳۸)"}],[4779,"انس رضی اللہ عنہ کہتے ہیں کہ ایک یہودی نے ایک لڑکی کو زیور پہنے دیکھا تو اسے پتھر سے مار ڈالا، وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس لائی گئی، اس میں کچھ جان باقی تھی، آپ نے فرمایا: \"کیا تمہیں فلاں نے قتل کیا ہے؟\" (شعبہ نے اپنے سر سے اشارہ کرتے ہوئے بتایا کہ) اس نے کہا: نہیں، آپ نے فرمایا: \"کیا تمہیں فلاں نے قتل کیا ہے؟\" (شعبہ نے اپنے سر سے اشارہ کرتے ہوئے بتایا کہ) اس نے کہا: نہیں، پھر آپ نے فرمایا: \"کیا تمہیں فلاں نے قتل کیا ہے؟\" (پھر شعبہ نے سر کے اشارے سے کہا کہ) اس نے کہا: ہاں، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے بلایا اور دو پتھروں کے درمیان کچل کر اسے مار ڈالا ۱؎۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم نے اس یہودی سے تلوار کی بجائے پتھروں سے اس کا سر کچل کر قصاص لیا، اس سے ثابت ہوا کہ قصاص صرف تلوار ہی سے ضروری نہیں ہے :(جیسا کہ حنفیہ کا قول ہے ) بلکہ یہ تو ارشاد ربانی کے مطابق ہے «وإن عاقبتم فعاقبوا بمثل ما عوقبتم به» :(سورة النحل: 126 ) «فاعتدوا عليه بمثل ما اعتدى عليكم» :(سورة البقرة: 194 ) حنفیہ حدیث «لا قود إلا بالسیف» یعنی: \" قصاص صرف تلوار ہی سے ہے \" سے استدلال کرتے ہیں، حالانکہ یہ حدیث ہر طریقے سے ضعیف ہے، بلکہ بقول امام ابوحاتم \"منکر\" ہے :(کذا فی نیل الا ٔوطار والإرواء رقم ۲۲۲۹ )۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک یہودی نے ایک لڑکی کے کانوں میں بالیاں دیکھیں تو (ان کو حاصل کرنے کے لیے) اس نے لڑکی کو ایک پتھر سے مار ڈالا۔ اس بچی کو نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا تو اس میں کچھ جان باقی تھی۔ آپ نے اس سے پوچھا: ’’تجھے فلاں نے قتل کیا ہے؟‘‘ اس نے سر کے اشارے سے کہا: نہیں۔ آپ نے فرمایا: ’’فلاں نے قتل کیا ہے؟‘‘ اس نے سر کے اشارے سے کہا: نہیں۔ آپ نے پھر (تیسری بار) اس سے پوچھا: ’۔کیا تجھے فلاں نے قتل کیا ہے؟‘‘ اس نے سر کے اشارے سے کہا: جی ہاں۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کو بلا بھیجا اور اسے دو پتھروں کے درمیان قتل کر دیا۔","f2":"معلوم ہوا یہ ضروری نہیں کہ قصاص تلوار سے ہی لیا جائے، قصاص تو بذات کود بھی مماثلت کا تقاضا کرتا ہے، اس لیے اگر قاتل نے مقتول کو دردناک طریقے سے قتل کیا ہو تو اسے بھی دردناک طریقے ہی سے قتل کیا جائے گا۔ رہی حدیث [لَا قَوَدَ اِلَّا بالسَّیْفِ] ’’قصاص تلوار کے بغیر نہیں لیا جائے گا۔‘‘ تو یہ ضعیف ہے۔ یہ بھی ثابت ہوا کہ قتل کسی بھی چیز سے ہو، اگر نیت قتل کی ہو تو قصاص لیا جا سکتا ہے کیونکہ اعتبار نیت کا ہے نہ کہ آلہ قتل کا بلکہ تلوار کے علاوہ تو قتل مزید دردناک ہو جاتا ہے اور ظالمانہ بھی۔ مزید تفصیل احادیث: ۴۰۲۹، ۴۰۵۰، ۴۷۴۳ میں ملاحظہ فرمائیں۔"}],[4780,"قیس بن ابی حازم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ خثعم کے کچھ لوگوں کی طرف (فوج کی) ایک ٹکڑی بھیجی، تو انہوں نے سجدہ کر کے اپنے کو بچانا چاہا، پھر بھی وہ سب قتل کر دئیے گئے، تو رسول اللہ صلی اللہ علیہ وسلم نے ان کی آدھی دیت ادا کی ۱؎ اور فرمایا: \"میں ہر اس مسلمان سے بری الذمہ ہوں جو مشرک کے ساتھ رہے\" ۲؎، پھر آپ نے فرمایا: سنو! (مسلمان اور کافر اس حد تک دور رہیں کہ) ان دونوں کو ایک دوسرے کی آگ نظر نہ آئے ۳؎۔\n§وضاحت\n۱؎: آدھی دیت کا حکم دیا اور باقی آدھی کفار کے ساتھ رہنے سے ساقط ہو گئی کیونکہ کافروں کے ساتھ رہ کر اپنی ذات کو انہوں نے جو فائدہ پہنچایا درحقیقت یہ ایک جرم تھا اور اسی جرم کی پاداش میں آدھی دیت ساقط ہو گئی۔ ۲؎: اس جملہ کی توجیہ میں تین اقوال وارد ہیں۔ ایک مفہوم یہ ہے کہ دونوں کا حکم یکساں نہیں ہو سکتا، دوسرا یہ کہ اللہ تعالی نے دارالاسلام کو دارالکفر سے علاحدہ کر دیا ہے لہٰذا مسلمان کے لیے یہ درست نہیں ہے کہ وہ کافروں کے ملک میں ان کے ساتھ رہے، تیسرا یہ کہ مسلمان مشرک کی خصوصیات اور علامتوں کو نہ اپنائے اور نہ ہی چال ڈھال اور شکل و صورت میں ان کے ساتھ تشبہ اختیار کرے۔ ۳؎: اس حدیث کا اس باب سے کوئی تعلق نہیں، ممکن ہے اس سے پہلے والے باب کی حدیث ہو اور نساخ کے تصرف سے اس باب کے تحت آ گئی ہو، اور اس حدیث کا مصداق ساری دنیا کے مسلمان نہیں ہیں کہ وہ ہر ملک میں کافروں سے الگ سکونت اختیار کریں، اس زمانہ میں تو یہ ممکن ہی نہیں بلکہ محال ہے، اس کا مصداق ایسے علاقے ہیں جہاں اسلامی حکومت ہو، اور سارے حالات و اختیارات مسلمانوں کے ہاتھ میں ہوں، جیسا کہ نبی اکرم صلی اللہ علیہ وسلم اور آپ کے بعد خلفاء راشدین وغیرہ کے عہدوں میں تھا، اور آج سعودیہ اور دیگر مسلم ممالک میں ہے، بعض مسلم ممالک کے اندر بھی موجودہ حالات میں الگ تھلگ رہائش مشکل ہے، «لايكلف الله نفسا إلا وسعها» :(سورة البقرة: ۲۸۶)۔","الألباني: صحيح",{"u2":"حضرت قیس رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خثعم قبیلے کی طرف ایک لشکر بھیجا۔ وہ سجدے میں پڑ گئے تاکہ جان بچا سکیں لیکن وہ بھی مارے گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کی نصف دیت ادا فرمائی اور فرمایا: ’’میں ہر اس مسلمان سے لا تعلق ہوں جو کافروں میں رہتا ہے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! مسلمان اور کافر اتنے دور رہیں کہ انھیں ایک دوسرے کی آگ نظر نہ آئے۔‘‘","f2":"(۱) ’’وہ سجدے میں گر پڑے‘‘ یعنی ان میں سے کچھ لوگ جو مسلمان تھے لیکن کسی کو ان کے اسلام کا علم نہیں تھا، انھوں نے سجدے کو اپنے اسلام کے اظہار کا ذریعہ بنایا مگر جنگ کی بھیڑ بھاڑ میں اس کا پتا نہ چلا اور وہ بھی مارے گئے۔ اس میں مقتولین کا بھی قصور تھا کہ وہ مشرکین میں رہ رہے تھے، اس لیے آپ نے ان کی دیت نصف ادا فرمائی۔ اور پھر تنبیہ فرما دی کہ مسلمانوں اور مشرکین کو اکٹھا نہیں رہنا چاہیے، خصوصاً اس حالت میں کہ جب ان میں امتیز بھی نہ ہو بلکہ مسلمانوں کو مشرکین سے اتنا دور رہنا چاہیے کہ ایک دوسرے کی آگ بھی نظر نہ آئے۔ گویا الگ بستی میں رہنا چاہیے۔ مسلمانوں کی آبادی الگ ہونی چاہیے اور کفار کی الگ تاکہ حملے کی صورت میں امتیاز ہو سکے۔ (۲) اس روایت کا باب سے کوئی تعلق نہیں، البتہ کتاب سے تعلق ہے کہ اگر لا علمی یا خطا میں کوئی مسلمان مارا جائے تو اس کی دیت ادا کرنی ہوگی۔ واللہ اعلم! (۳) جب کوئی شخص اپنے اسلام کا اظہار کر دے تو پھر اسے قتل کرنا حرام ہے، خواہ وہ کافروں ہی میں رہتا ہو۔ (۴) بلا ضرورت دارالحرب میں رہنا درست نہیں۔ بالخصوص وہاں مستقل رہائش اختیار کرنا بالکل جائز نہیں۔ (۵) محقق کتاب نے اگرچہ اس روایت کو سنداً ضعیف قرار دیا ہے لیکن دیگر محققین نے اس پر سیر حاصل بحث کی ہے اور اسے دیگر شواہد کی بنا پر صحیح قرار دیا ہے۔ اور دلائل کی رو سے انھی کا موقف راجح معلوم ہوتا ہے۔ دیکھیے: (ارواء الغلیل: ۵/ ۲۹-۳۳، و ذخیرۃ العقبیٰ شرح سنن النسائی: ۳۶/ ۱۱۴-۱۱۸) (۶) مزید فوائد ومسائل کے لیے ملاحظہ فرمائیں۔ (سنن ابوداود مترجم طبع دارالسلام، حدیث: ۲۶۴۵)"}],[4781,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ بنی اسرائیل میں قصاص کا حکم تھا، ان میں دیت دینے کا حکم نہ تھا، تو اللہ تعالی نے «كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى» \"تم پر قصاص فرض کیا گیا ان لوگوں کا جو مارے جائیں، آزاد کے بدلے آزاد، غلام کے بدلے غلام، عورت کے بدلے عورت\" سے «فمن عفي له من أخيه شىء فاتباع بالمعروف وأداء إليه بإحسان» \"جس کو اس کے بھائی کی طرف سے کچھ معاف کر دیا جائے تو معاف کرنے والا دستور کی پیروی کرے اور جس کو معاف کیا گیا وہ اچھی طرح دیت ادا کرے۔ (تمہارے رب کی طرف سے) یہ تخفیف اور رحمت ہے، اس کے بعد بھی جو سرکشی کرے گا، اسے درد ناک عذاب ہو گا\" (البقرہ: ۱۷۸) تک نازل فرمایا، تو عفو یہ ہے کہ قتل عمد میں دیت قبول کر لے اور اتباع بالمعروف یہ ہے کہ وہ دستور کی پابندی کرے، اور «وأداء إليه بإحسان» یہ ہے کہ وہ اسے اچھی طرح ادا کرے، «ذلك تخفيف من ربكم ورحمة»\"یہ تخفیف ہے تمہارے رب کی طرف سے اور رحمت ہے\" اس لیے کہ تم سے پہلے کے لوگوں پر صرف قصاص فرض تھا، دیت کا حکم نہیں تھا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا کہ بنی اسرائیل میں صرف قصاص تھا۔ دیت نہیں تھی۔ اللہ تعالیٰ نے قرآن مجید میں یہ آیت اتاری: {کُتِبَ عَلَیْکُمُ الْقِصَاصُ فِی الْقَتْلٰی} ’’تم پر مقتولوں کے بارے میں برابر کا بدلہ لینا فرض کیا گیا ہے۔ آزاد کے بدلے وہی آزاد (قاتل) اور غلام کے بدلے وہی غلام (قاتل) اور عورت کے بدلے وہی (قاتل) عورت (قتل کی جائے گیٖ۔ پھر جس شخص کو اس کے بھائی (مقتول کے ولی) کی طرف سے کچھ معافی مل جائے تو (معاف کرنے والے کے لیے) اچھے طریقے سے دیت طلب کرنا اور (قاتل کے لیے) اچھے طریقے سے ادائیگی کرنا ہے۔‘‘ معافی سے مراد یہ ہے کہ قتل عمد کی صورت میں مقتول کا ولی دیت لینا قبول کرے۔ اتباع بالمعروف سے یہ مراد ہے کہ مقتول کا ولی مناسب انداز میں دیت وصول کر لے اور دوسرا فریق اچھے طریقے سے ادائیگی کرے۔ {ذٰلِکَ تَخْفِیْفٌ مِّنْ رَّبِّکُمْ وَ رَحْمَۃٌ} ’’یہ تمھارے رب کی طرف سے آسانی اور رحمت ہے۔‘‘ یعنی اہل کتاب پر نازل کردہ حکم کے مقابلے میں جو کہ صرف قصاص تھا اور دیت (کی گنجائش) نہیں تھی۔","f2":"(۱) ’’برابر کا بدلہ لینا فرض کیا گیا ہے۔‘‘ یعنی قصاص لینا جائز ہے۔ مشروع ہے، واجب اور ضروری نہیں بلکہ عام حالات میں معافی بہتر ہے۔ (۲) ’’آزاد کے بدلے وہی آزاد (قاتل)‘‘ دور جاہلیت میں بعض قوی قبائل اپنے غلام کو دوسروں کے آزاد اور اپنی عورت کو دوسروں کے مردوں کے برابر سمجھتے تھے۔ اپنے ایک آزاد کے بدلے میں وہ دوسروں کے دس، دس آزاد مار دیتے تھے۔ شریعت نے فرمایا: قاتل ہی قتل کیا جائے گا آزاد ہو یا غلام، عورت ہو یا مرد، ایک ہو یا زائد۔ بعض حضرات نے معنی کیے ہیں: ’’آزاد کے بدلے آزاد قتل کیا جائے گا، غلام کے بدلے غلام‘‘ حالانکہ یہ معنی غلط ہیں۔ مقتول کے بدلے میں قاتل کو قتل کیا جائے گا نہ کہ کوئی آزاد ی یا غلام۔ (۳) ’’کچھ معافی‘‘ یعنی قصاص معاف ہو جائے، خواہ سب اولیاء معاف کر دیں یا ایک ولی معاف کر دے۔ ایسی صورت میں قصاص نہیں، دیت ہوگی۔ (۴) ’’اچھے طریقے سے‘‘ جب ولی نے قصاص معاف کیا ہے تو وہ دیت لینے میں بھی احسان کرے کہ قسطوں میں میں لے۔ یکمشت ادائیگی کی ضد نہ کرے الا یہ کہ قاتل آسانی سے یکمشت ادا کر سکتا ہو۔ اسی طرح قاتل کو بھی احسان کی قدر کرتے ہوئے تند ہی سے ادائیگی کرنی چاہیے اور مقتول کے اولیاء کو پریشان نہیں کرنا چاہیے۔"}],[4782,"مجاہد اس آیت کریمہ «كتب عليكم القصاص في القتلى الحر بالحر» \"تم پر قصاص فرض کیا گیا ان لوگوں کا جو مارے جائیں، آزاد کے بدلے آزاد\"کے سلسلہ میں کہتے ہیں: بنی اسرائیل پر صرف قصاص فرض تھا، ان پر دیت نہیں تھی، پھر اللہ تعالی نے دیت کا حکم نازل فرمایا، تو اللہ تعالی نے بنی اسرائیل کے بالمقابل اس امت محمدیہ پر تخفیف کی۔","الألباني: صحيح لغيره",{"u2":"حضرت مجاہد رحمہ اللہ نے آیت کریمہ {کُتِبَ عَلَیْکُمُ الْقِصَاصُ فِی الْقَتْلٰی…} ’’تم پر مقتولوں کے بارے میں قصاص (برابر کا بدلہ) لینا فرض کیا گیا ہے، آزاد کے بدلے وہی آزاد۔‘‘ کے متعلق میں فرمایا: بنو اسرائیل کے لیے صرف قصاص کا حکم تھا، دیت نہیں تھی۔ پھر اللہ تعالیٰ نے دیت کا حکم اتار کر اس امت کے لیے بنی اسرائیل کے مقابلے میں تخفیف فرما دی۔"}],[4783,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس قصاص کا ایک معاملہ آیا تو آپ نے اسے معاف کر دینے کا حکم دیا ۱؎۔\n§وضاحت\n۱؎: یعنی: سفارش کی تاکہ قصاص نہ لے کر دیت پر راضی ہو جائے۔","الألباني: صحيح الإسناد",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے پاس قصاص کا ایک مقدمہ آیا تو آپ نے معاف کرنے کا مشورہ دیا۔","f2":"حدیث میں لفظ ’’امر‘‘ ہے۔ عربی میں اس کے مختلف مفہوم ہیں۔ ان میں سے ایک مشورہ بھی ہے۔ قصاص اولیائے مقتول کا شرعی حق ہے، لہٰذا انھیں قصاص چھوڑنے کا حکم نہیں دیا جا سکتا، اگرچہ معاف کرنا ہی افضل ہے۔ البتہ مشورہ دیا جا سکتا ہے، اس لیے یہاں اس معنی کو ترجیح دی گئی ہے۔"}],[4784,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جب بھی کوئی ایسا معاملہ آیا جس میں قصاص ہو تو آپ نے اسے معاف کر دینے کا حکم دیا۱؎۔\n§وضاحت\n۱؎: یعنی: سفارش کی۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: جب بھی نبی اکرم صلی اللہ علیہ وسلم کے پاس قصاص کا کوئی مقدمہ آیا آپ نے معافی کا مشورہ دیا۔","f2":"معلوم ہوا معاف کرنا افضل ہے بشرطیکہ فریق ثانی عاجزی کے ساتھ معافی کا طلب گار ہو۔ اگر وہ فخر و غرور میں ہو یا زبردستی کی معافی چاہتا ہو تو قصاص اور انتقام افضل ہے۔ پھر معافی کے بعد دیت ضرور ہونی چاہیے تاکہ خون کی اہمیت رہے۔"}],[4785,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کا کوئی آدمی قتل ہو گیا ہو تو اسے اختیار ہے، چاہے تو قصاص لے، چاہے تو دیت لے\" ۱؎۔\n§وضاحت\n۱؎: قتل عمد میں مقتول کے وارثین کے لیے قصاص یا دیت دونوں میں کسی ایک کو اختیار کرنے کا حق ہے :(اس میں قاتل کی مرضی کا کوئی دخل نہیں ) اگر قصاص معاف کر دیتے ہیں تو دیت واجب ہو گی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کا رشتہ دار قتل کر دیا جائے، اسے دو چیزوں میں سے بہتر کا اختیار ہے: قصاص لے لے یا دیت۔‘‘","f2":"عموماً مقتول کے ورثاء قصاص کا مطالبہ کرتے ہیں یا پھر دیت پر راضی ہو جاتے ہیں، اس لیے دو چیزوں کا ذکر فرمایا، تاہم اگر مقتول کے ورثاء درگزر کرتے ہوئے بالکل معاف کر دیں تو بھی قرآن کے عموم کے پیش نظر جائز ہے، نیز یہ بھی معلوم ہوا کہ قصاص، دیت یا معافی کا اختیار مقتول کے ورثاء کو ہے نہ کہ قاتل کو۔"}],[4786,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کا کوئی آدمی قتل ہو گیا ہو تو اسے دو باتوں کا اختیار ہے، چاہے تو قصاص لے اور چاہے تو دیت لے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کا رشتہ دار مارا جائے، اسے دو میں سے بہتر چیز کا اختیار ہے: قصاص لے یا دیت۔"}],[4787,"ابوسلمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کا کوئی شخص قتل کر دیا گیا\" (یعنی وہ چاہے تو قصاص لے، اور چاہے تو دیت لے) (یہ روایت مرسل ہے)۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو سلمہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کا رشتہ دار مارا جائے۔‘‘ یہ روایت مرسل ہے۔","f2":"مرسل کا مطلب یہ ہے کہ اس روایت میں اصل راوی، یعنی صحابی کا نام نہیں لیا گیا بلکہ شاگرد نے خود ہی فرمان بیان کر دیا۔ ’’رشتہ دار‘‘ ہر رشتہ دار مقتول کا وارث نہیں بن سکتا بلکہ اولین حق دار بیٹے، پوتے ہیں۔ پھر باپ دادا، پھر بھائی بھتیجے، پھر چچا وغیرہ۔"}],[4788,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لڑنے والوں پر لازم ہے کہ وہ قصاص لینے سے باز رہیں، پہلے جو (مقتول کے وارثین میں) سب سے قریبی ہو وہ معاف کرے، پھر اس کے بعد والے، خواہ عورت ہی ہو\"۔","الألباني: ضعيف",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(قصاص کے لیے) لڑنے والوں کے لیے مناسب ہے کہ وہ قصاص سے رک جائیں۔ (جلدی نہ کریں)۔ وارثوں میں معاف کرنے کا حق اسے ہے جو ان میں سے زیادہ قریبی ہو، خواہ وہ عورت ہو۔‘‘"}],[4789,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی ہنگامے، یا بلوے اور فساد میں (جہاں قاتل معلوم نہ ہو سکے) کسی پتھر یا کوڑے یا ڈنڈے سے مارا جائے تو اس کی دیت وہی ہو گی جو قتل خطا کی ہے اور جس نے قصداً مارا تو اس پر قصاص ہو گا، جو کوئی قصاص اور قاتل کے درمیان حائل ہو تو اس پر اللہ تعالی، فرشتوں اور تمام لوگوں کی لعنت ہے، نہ اس کا فرض قبول ہو گا نہ نفل\"۔\n§وضاحت\n۱؎: قتل تلوار سے ہو یا ایسے ہتھیار سے جس سے قتل کیا جاتا ہے: اگر قتل کی نیت سے ہو تو قتل عمد :(مقصد و ارادہ اور جان بوجھ کر قتل ) ہے، اس میں قصاص ہے یا معاف کر دینے کی صورت میں دیت ہے، اور اگر قتل غلطی سے ہو خواہ کسی چیز سے بھی ہو تو اس میں دیت ہے، یہی حکم بندوق یا بم کا بھی ہو گا، فساد اور ہنگامے میں قتل خواہ کسی چیز سے ہو وہ \" غلطی سے قتل \" مانا جائے گا اور اس میں دیت ہو گی۔ جس کی تفصیل اس حدیث میں ہے اور یہی دیت مغلظہ ہے۔ اور فی زمانہ موجودہ سرکار مذکورہ دیت کی قیمت موجودہ بھاؤ سے لگا کر دیت مقرر کرے گی جیسا کہ سعودی عربیہ میں ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اندھا دھند لڑائی جھگڑے (بلوے اور ہنگامے) میں مارا جائے جس میں پتھر، کوڑے یا لاٹھی کا عام استعمال ہوا تو اس کی دیت قتل خطا کی دیت ہوگی۔ اور جس شخص کو جان بوجھ کر قتل کیا جائے، اس کا قصاص لیا جائے گا۔ جو شخص قصاص میں رکاوٹ بنے، س پر اللہ تعالیٰ کی فرشتوں کی اور سب لوگوں کی لعنت ہے۔ نہ اس کا فرض قبول نہ نفل۔‘‘","f2":"(۱) یہ حدیث مبارکہ قتل عمد (کسی کا کسی کو جان بوجھ کو قتل کرنا) کا بالکل صریح حکم بیان کرتی ہے کہ اس میں قصاص واجب ہے۔ ہاں اگر مقتول کے ورثاء دیت پر راضی ہو جائیں تو یہ درست ہوگا۔ اس صورت میں قاتل سے قصاص ساقط ہو جائے گا جیسا کہ دیگر احادیث میں اس کی صراحت ہے۔ (۲) جو شخص اللہ تعالیٰ کی مقرر کردہ حدود قائم کرنے میں حائل ہو اور کسی قسم کی رکاوٹ پیدا کرے تو وہ شخص، خواہ صدرِ مملکت ہی ہو، لعنتی ہے۔ اس پر اللہ تعالیٰ کی لعنت ہے، فرشتوں کی اور تمام لوگوں کی بھی لعنت ہے، نیز ایسے شخص کی کوئی عبادت قبول نہیں ہوتی کیونکہ یہ اللہ اور اس کے رسول سے کھلی جنگ ہے۔ مطلب یہ کہ ایسا کرنا حرام اور شرعاً ناجائز ہے۔ (۳) اس حدیث میں ہنگامے اور بلوے کی صورت بیان کی گئی ہے کہ دونوں طرف ازدحام ہے۔ آپس میں لڑ رہے ہیں۔ کوئی پتھر چلا رہا ہے کوئی لکڑی۔ کوئی کوڑا مار رہا ہے، کوئی خالی ہاتھ۔ ایسے بلوے میں قاتل کا تعین نہیں کیا جا سکتا۔ ویسے بھی ایسی لڑائی کا مقصود کسی کو قتل کرنا نہیں ہوتا۔ بالفرض اگر کوئی مارا جائے تو اسے قتل خطا قرار دیا جائے گا اور فریق ثانی دیت بھرے گا۔ البتہ اگر ایسی لڑائی میں اسلحہ استعمال ہو لیکن قاتلین کا تعین نہ ہو تو فریق ثانی سے قتل عمد کی دیت وصول کی جائے گی کیونکہ اسلحہ چلانے سے مقصود قتل کرنا ہی ہوتا ہے اور اگر قاتل کا تعین ہو جائے تو قصاص لیا جائے گا۔ اسی طرح اگر ایک آدمی کا مقصد دوسرے کو قتل کرنا ہی ہے، پھر خواہ وہ تلوار استعمال کرے یا آتشیں اسلحہ یا پتھر یا لکڑی یا ہتھوڑا، ہر حال میں اس سے قصاص لیا جائے گا جیسا کہ اس حدیث میں الگ طور پر ذکر ہے۔ (۴) ’’فرض ونفل‘‘ بعض نے صَرْفٌ کے معنی توبہ اور عَدْلٌ کے معنی فدیہ ومعاوضہ کیے ہیں۔ یہ بھی ممکن ہے۔ واللہ اعلم"}],[4790,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی ہنگامے یا بلوے میں کسی پتھر، کوڑے یا ڈنڈے سے مارا جائے تو اس کی دیت وہی ہے جو قتل خطا کی ہے، اور جس نے جان بوجھ کر مارا تو اس میں قصاص ہے اور جو کوئی اس کے اور اس کے (قصاص اور قاتل) کے درمیان حائل ہو گا تو اس پر اللہ تعالی، فرشتوں اور تمام لوگوں کی لعنت ہے، اس کا نہ فرض قبول ہو گا نہ کوئی نفل\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے مرفوعاً بیان فرمایا کہ جو شخص پتھروں، کوڑوں یا ڈنڈوں کی اندھا دھند لڑائی میں مارا جائے تو اس کی دیت قتل خطا والی ہوگی لیکن جسے جان بوجھ کر مارا گیا، اس کا قصاص لیا جائے گا۔ اور جو شخص قصاص میں رکاوٹ بنے، اس پر اللہ تعالیٰ، فرشتوں اور سب لوگوں کی طرف سے لعنت۔ اللہ تعالیٰ نہ اس کا فرض قبول فرمائے گا نہ نفل۔‘‘","f2":"مرفوعاً سے مراد رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے، کبھی اختصار کی خاطر ایسے کہہ دیا جاتا ہے۔"}],[4791,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"خطا یعنی شبہ عمد کے طور پر جو شخص کوڑے یا ڈنڈے سے مر جائے تو اس کی دیت سو اونٹ ہے، چالیس ان میں سے حاملہ اونٹنیاں ہوں\"۔\n§وضاحت\n۱؎: شبہ عمد: ایسے آلات سے قتل کرنے کو کہتے ہیں جن سے عام طور سے قتل نہیں کیا جاتا، جیسے لاٹھی، کوڑا، اور موٹی سوئی وغیرہ :(گرچہ نیت قتل کی ہو ) اس میں جس دیت کا بیان ہے وہی \" دیت مغلظہ \" ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جو غلطی سے مارا جائے شبہ عمد کی صورت میں، یعنی کوڑے اور ڈنڈے وغیرہ سے، اس کی دیت ایک سو اونٹ ہیں جن میں سے چالیس حاملہ اونٹنیاں ہوں گی۔‘‘","f2":"(۱) قتل کی تین صورتیں ہیں: (ا) قتل خطا: کسی نے تیر وغیرہ چلایا شکار کرنے کے لیے اچانک کوئی شخص آگے آگیا اور مر گیا یا کسی کو جانور یا بے جان چیز سمجھ کر تیر یا کوئی اور اسلحہ چلایا، بعد میں پتا چلا کہ وہ تو انسان تھا۔ (ب) شبہ عمد: لڑائی وغیرہ میں کسی کو قتل کرنے کی نیت نہ ہو اور نہ اسلحہ استعمال کیا گیا ہو۔ ڈنڈے سونٹے وغیرہ چلائے گئے لیکن اس سے کوئی شخص مر گیا۔ (ج) قتل عمد: نیت قتل کی ہو یا اسلحہ استعمال کیا گیا ہو کیونکہ اسلحے کا مقصد ہی قتل کرنا ہوتا ہے، لہٰذا دونوں صورتوں کو قتل عمد ہی کہا جائے گا۔ اگر نیت قتل کی ہو تو خواہ کسی بھی چیز سے قتل کیا گیا ہو، اسے قتل عمد ہی کہا جائے گا۔ احناف نے قتل عمد اور شبہ عمد میں صرف آلے کا فرق کیا ہے، یعنی آلہ قتل استعمال کیا گیا ہو، یعنی اسلحہ وغیرہ تو قتل عمد اور اگر ڈنڈے، سونٹے، پتھر، لوہے (جو نوکدار اور تیز نہ ہو) سے قتل کیا گیا ہو تو شبہ عمد۔ دونوں میں نیت قتل کی ہوتی ہے۔ لیکن ان کی یہ تعریف رسول اللہ صلی اللہ علیہ وسلم کے دور کے بہت سے واقعات کے خلاف پڑتی ہے، لہٰذا معتبر نہیں۔ خیر، قتل خطا کی صورت میں صرف دیت ہوگی اور وہ بوھی ہلکی جیسا کہ آگے آرہا ہے۔ شبہ عمد میں بھی صرف دیت ہوگی لیکن بھاری جیسا کہ اس حدیث میں ہے کہ سو میں سے چالیس حاملہ اونٹنیاں ہوں۔ قتل عمد میں قصاص ہے اور اگر معافی مل جائے تو دیت شبہ عمد والی۔ یاد رہے ہر قسم کی دیت میں تعداد سو اونٹ ہی ہے۔ (۲) اس حدیث میں شبہ عمد کو خطا کہا گیا ہے کیونکہ اس میں بھی مقصد قتل کرنا نہیں ہوتا، صرف لڑائی مقصود ہوتی ہے۔"}],[4792,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے زمین کو کرائے پر اٹھانے سے منع فرمایا۔ زمین کو کرائے پر نہ دینے کے سلسلہ میں (روایت کرنے میں) عبدالملک بن عبدالعزیز بن جریج نے مطر کی موافقت کی ہے۔\nقاسم بن ربیعہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے روز خطبہ دیا۔ یہ روایت مرسل ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت قاسم بن ربیعہ نے مرسل طور پر بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن خطبہ ارشاد فرمایا۔","f2":"مرسل حدیث سے مراد ہے کہ تابعی براہِ راست رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کر دے۔"}],[4793,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! جو شخص قتل خطا میں یعنی شبہ عمد کے طور پر کوڑے، یا ڈنڈے سے مر جائے تو اس کی دیت سو اونٹ ہے، جن میں سے چالیس حاملہ اونٹنیاں ہوں\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آگاہ رہو! جو شخص شبہ عمد والی صورت میں غلطی سے مارا جائے، مثلاً: کوڑے اور ڈنڈے وغیرہ سے، اس کی دیت سو اونٹ ہے جن میں سے چالیس اونٹنیاں حاملہ ہوں گی۔‘‘"}],[4794,"ایک صحابی سے روایت ہے کہ فتح مکہ کے روز نبی اکرم صلی اللہ علیہ وسلم نے خطبہ دیا، اور فرمایا: \"سنو! قتل خطا میں یعنی شبہ عمد کے طور پر کوڑے، ڈنڈے اور پتھر سے مرنے والے کی دیت سو اونٹ ہے، ان میں چالیس «ثنی» سے لے کر «بازلت» ہوں (یعنی چھ برس سے نو برس تک کی ہوں) اور سب بوجھ لادنے کے لائق ہوں\"۔","الألباني: صحيح لغيره",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فتح مکہ کے دن خطبہ ارشاد فرمایا۔ (اس میں) آپ نے فرمایا: ’’آگاہ رہو! شبہ عمد کی صورت میں کوڑے، ڈنڈے یا پتھر کے ساتھ غلطی سے مارے جانے والے شخص کی دیت سو اونٹ ہے جن میں سے چالیس تثنیہ سے بازل عام تک ہوں اور ان میں سے ہر ایک حاملہ ہو۔","f2":"’’ثنیہ‘‘ پانچ سال کی اونٹنی کو کہتے ہیں جو چھٹے سال میں داخل ہو اور ’’بازل‘‘ جو آٹھ سال کی ہو اور نویں میں داخل ہو۔ گویا چالیس اونٹنیاں پانچ سال سے آٹھ سال کی عمر تک ہوں، نیز وہ حاملہ ہوں۔ ظاہر ہے یہ بہت مہنگی ہوں گی۔"}],[4795,"عقبہ بن اوس سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! جو قتل خطا میں یعنی شبہ عمد کے طور پر کوڑے یا ڈنڈے سے مر جائے تو اس کی دیت مغلظہ سو اونٹ ہے، ان میں چالیس حاملہ اونٹنیاں ہوں\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عقبہ بن اوس سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کوڑے یا ڈنڈے سونٹے کے ساتھ غلطی سے مارا جائے، اس کی دیت مغلظہ، یعنی سخت ہوگی، سو اونٹ جن میں سے چالیس اونٹنیاں حاملہ ہوں۔‘‘"}],[4796,"ایک صحابی رسول (رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب فتح مکہ کے دن مکہ میں داخل ہوئے تو فرمایا: \"سنو! ہر مقتول خواہ غلطی سے مارا گیا ہو یا شبہ عمد کے طور پر ہو، وہ کوڑے یا ڈنڈے سے قتل کیے گئے شخص کی طرح ہے (یعنی اس کی دیت بھی وہی ہے جو اس کی ہے) اس میں چالیس حاملہ اونٹنیاں ہوں\"۔","الألباني: صحيح لغيره",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی سے منقول ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے دن مکہ کرمہ میں داخل ہوئے تو آپ نے فرمایا: ’’آگاہ رہو! جو شخص غلطی سے شبہ عمد کی صورت میں مارا جائے کوڑے اور ڈنڈے سونٹے کے ساتھ تو اس کی دیت کے اونٹوں میں چالیس اونٹنیاں ایسی ہوں جن کے پیٹ میں بچے ہوں۔‘‘"}],[4797,"ایک صحابی رسول (رضی اللہ عنہ) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے دن جب مکہ آئے تو فرمایا: \"سنو! خطا سے مقتول ہونے والا کوڑے اور ڈنڈے سے مر جانے والے کی طرح ہے (یعنی اس کی دیت بھی وہی ہے) ان میں چالیس حاملہ اونٹنیاں ہوں\"۔","الألباني: صحيح لغيره",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم جب فتح مکہ کے موقع پر مکہ مکرمہ تشریف لائے تو آپ نے فرمایا: ’’آگاہ رہو! جو مقتول شبہ عمد کی صورت میں غلطی سے کوڑے یا ڈنڈے سونٹے مارا جائے، اس کی دیت کے اونٹوں میں سے چالیس اونٹنیاں ایسی ہوں جن کے پیٹ میں بچے ہوں۔‘‘"}],[4798,"ایک صحابی رسول (رضی اللہ عنہ) بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب فتح مکہ کے سال مکہ میں داخل ہوئے تو فرمایا: \"خطا سے مقتول ہونے والا، کوڑے اور ڈنڈے سے مقتول ہونے والے کی طرح ہے، ان میں چالیس ایسی اونٹنیاں ہوں جو حاملہ ہوں\"۔","الألباني: صحيح لغيره",{"u2":"نبی کریم صلی اللہ علیہ وسلم کے ایک صحابی سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم فتح مکہ کے سال مکہ مکرمہ میں داخل ہوئے تو فرمایا: ’۔خبردار! جو شخص شبہ عمد کی صورت میں کوڑے یا سونٹے کے ساتھ غلطی سے قتل ہو جائے، اس کی دیت میں سے چالیس اونٹنیاں ایسی ہوں جن کے پیٹ میں بچے ہوں۔‘‘"}],[4799,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ فتح مکہ کے دن رسول اللہ صلی اللہ علیہ وسلم کعبے کی سیڑھی پر کھڑے ہوئے، اللہ کی حمد و ثنا بیان کی اور فرمایا: \"شکر ہے اس اللہ کا جس نے اپنا وعدہ سچ کر دکھایا، اپنے بندے کی مدد کی، جماعتوں کو اکیلے ہی شکست دی، سنو! کوڑے اور ڈنڈے سے غلطی سے مر جانے والا شبہ عمد کی طرح ہے، اس میں بھی دیت مغلظہ سو اونٹ ہے، ان میں سے چالیس حاملہ اونٹنیاں ہوں\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے دن کعبہ کی سیڑھی پر کھڑے ہوئے۔ آپ نے اللہ تعالیٰ کی حمد وثنا بیان کی اور فرمایا: ’’سب تعریف اللہ تعالیٰ کے لیے ہے جس نے اپنا وعدہ سچا کر دکھایا اور اپنے بندے (حضرت محمد مصطفی صلی اللہ علیہ وسلم) کی مدد فرمائی، نیز اس اکیلے نے کفار کی تمام جماعتوں کو شکست سے دو چار کیا۔ سنو! جو شخص شبہ عمد کی صورت میں کوڑے یا سونٹے کے ساتھ خطا مارا جائے، اس کی دیت سخت ہوگی۔ (یعنی ایسے) سو اونٹ جن میں سے چالیس اونٹنیاں حاملہ ہوں گی۔‘‘"}],[4800,"قاسم بن ربیعہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ڈنڈے یا کوڑے سے غلطی سے قتل ہو جانا شبہ عمد کی طرح ہے، اس میں سو اونٹ کی دیت ہو گی جن میں چالیس حاملہ اونٹنیاں ہوں\"۔","الألباني: صحيح لغيره",{"u2":"حضرت قاسم بن ربیعہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قتل خطا شبہ عمد کی صورت میں، یعنی جو کوڑے یا سونٹے کے ساتھ ہو، اس میں دیت سو اونٹ ہے جن میں سے چالیس اونٹنیاں حاملہ ہوں۔‘‘","f2":"(۱) مندرجہ بالا بعض روایات میں قتل خطا کے ساتھ عمد کا لفظ آیا ہے۔ اس سے مراد بھی شبہ عمد ہی ہے کیونکہ قتل عمد تو قتل خطا نہیں ہو سکتا۔ یہ تو آپس میں مقابل ہیں، لہٰذا مراد شبہ عمد ہی ہوگا، یعنی جو دیکھنے میں عمد جیسا ہو مگر حقیقتاً خطا ہو کیونکہ قاتل کی نیت قتل کی نہیں تھی بلکہ ویسے مارنے پیٹنے کی تھی۔ خطا (غلطی سے) قتل ہوگیا۔ (۲) قتل شبہ عمد کی دیت میں سے چالیس اونٹنیوں کا بیان تو کر دیا گیا ہے کہ وہ حاملہ ہوں، باقی ساٹھ کا بیان نہیں کیا گیا مگر دیگر احادیث میں ذکر ہے کہ تیس حقے ہوں (تین سالہ اونٹنیاں جو چوتھے میں داخل ہوں) اور تیسجزعے (چار سالہ اونٹنیاں جو پانچویں میں داخل ہوں)۔ قتل عمد میں بھی معافی کی صورت میں دیت ہوگی۔ تیس حقے، تیس جذعے اور چالیس حاملہ (پانچ سے آٹھ سالہ)۔"}],[4801,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص خطا (غلطی) سے مارا جائے اس کی دیت سو اونٹ ہے: تیس اونٹنیاں ہیں جو ایک سال پورے کر کے دوسرے میں لگ گئی ہوں اور تیس اونٹنیاں جو دو سال پورے کر کے تیسرے میں لگ گئی ہوں اور تیس اونٹنیاں وہ جو تین سال پورے کر کے چوتھے سال میں لگ گئی ہوں اور دو دو سال کے دس اونٹ ہیں جو تیسرے سال میں داخل ہو گئے ہوں، اور آپ نے گاؤں والوں پر دیت کی قیمت چار سو دینار لگائی یا اتنی ہی قیمت کی چاندی، یہ قیمت وقت کے حساب سے بدلتی رہتی، اونٹ مہنگے ہوتے تو دیت (کی مالیت) بھی زیادہ ہوتی اور جب سستے ہوتے تو دیت بھی کم ہو جاتی، چنانچہ آپ کے زمانے میں دیت کی قیمت چار سو دینار سے آٹھ سو دینار تک پہنچ گئی یا اسی کے برابر چاندی، آپ صلی اللہ علیہ وسلم نے یہ بھی فیصلہ فرمایا: گائے والوں سے دو سو گائیں اور بکری والوں سے دو ہزار بکریاں (دیت میں) لی جائیں، نیز آپ صلی اللہ علیہ وسلم نے حکم فرمایا: دیت مقتول کے ورثاء کے درمیان ان کے حصوں کے مطابق ترکہ ہے، پھر جو بچ رہے وہ عصبہ کے اوپر ہے، اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عورت کی طرف سے اس کی دیت اس کے عصبہ ادا کریں گے جو بھی ہوں، لیکن وہ (ملنے والی) دیت میں کسی چیز کے وارث نہیں ہوں گے سوائے اس کے جو بچ رہے، اور اگر عورت مقتول ہو تو اس کی دیت اس کے ورثاء میں تقسیم ہو گی اور وہ اس کے قاتل کو قتل کریں گے\"۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص شکطا (غلطی سے) مارا جائے، اس کی دیت سو اونٹ ہے۔ تیس بنت مخاض (ایک سالہ اونٹنی)، تیس بنت لبون (دو سالہ اونٹنی)، تیس حقے (تین سالہ اونٹنی) اور دس ابن لبون (ایک سالہ مذکر)۔‘‘ انھوں (عبداللہ بن عمرو) نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم بستیوں (گاؤں) میں رہنے والے لوگوں پر اس دیت کی قیمت چار سو دینار یا اس کے برابر چاندی مقرر فرماتے تھے اور اونٹوں والوں پر ان کی قیمت وقت کے لحاظ سے عائد فرماتے تھے۔ جب اونٹ مہنگے ہوتے تو قیمت بڑھا دیتے اور اگر سستے ہو جاتے تو قیمت کم لگاتے، جو بھی ہوتی۔ آپ کے دور مبارک میں یہ قیمت چار سو دینار سے آٹھ سو دینار تک رہی یا اس کے برابر چاندی تھی۔ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے یہ فیصلہ بھی فرمایا کہ جو شخص گائیوں سے دیت دینا چاہے تو گائیوں والوں پر دیت دو سو گائے ہوگی اور جو شخص بکریوں سے دینا چاہے تو دیت دو ہزار بکری ہوگی۔ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ دیت بھی وراثت کی طرح مقتول کے ورثاء میں تقسیم ہوگی۔ ان کو ان کے مقررہ حصوں کے مطابق دی جائے گی۔ اگر کوئی مال بچ جائے تو وہ مقتول کے عصبہ کو ملے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا تھا کہ عورت کی طرف سے دیت تو اس کے عصبہ بھریں گے، جو بھی ہوں لیکن وہ اس کی وراثت سے کچھ حاصل نہیں کریں گے الا یہ کہ ورثاء کو ان کے مقررہ حصوں کی ادائیگی کے بعد کچھ بچ جائے۔ (تو وہ بطور عصبہ ان کو ملے گا)۔ اور اگر کوئی عورت قتل کر دی جائے تو اس کی دیت ورثاء میں تقسیم ہوگی اور وہی قاتل کو قتل کریں گے (اگر وہ معاف نہ کریں)۔","f2":"(۱)اس حدیث مبارکہ میں قتل خطا کی دیت کی مقدار کا بیان ہے اور وہ چار قسم کے سو اونٹ ہے، اس کی تفصیل حدیث مذکورہ میں بیان کر دی گئی ہے۔ (۲)یہ حدیث اس بات پر بھی دلالت کرتی ہے کہ اصل دیت اونٹ ہی ہیں، تاہم اونٹ میسر نہ ہونے کی صورت میں سو اونٹوں کی قیمت دیت ہوگی، اگر اونٹ مہنگے ہوں گے تو دیت کی رقم یا زیادہ ہوگی اور اگر اونٹ سستے ہوں گے تو پھر دیت کی رقم بھی کم ہوگی۔ اگر کوئی شخص دیت میں گائے بیل دینا چاہے تو دیت دو سو گائے بیل ہوگی۔ اور اگر دیت بکریوں کی صورت میں ادا کرنا چاہے تو دو ہزار بکریاں دیت ہوگی۔ (۳)قاتل سے قصاص لینا ورثاء کا حق ہے۔ وہ چاہیں تو قصاص لیں اور اگر چاہیں تو معاف کر دیں۔ مقتول کے ورثائ، یعنی ورثائے مال کے علاوہ دیگر عصبات (عزیز واقارب) وغیرہ کو قصاص لینے یا معافی دینے کا کوئی حق نہیں۔ ہاں، اگر مقتول کے ورثاء میں سے کوئی مرد یا عورت نہ ہو تو پھر دیگر عزیز واقارب کو یہ حق مل جائے گا۔ واللہ اعلم! (۴) مقتول کی دیت، اس کے دوسرے مال کی طرح اس کے ورثاء کا حق ہے، یعنی دیت بھی، انھی میں تقسیم ہوگی۔ پہلے اصحاب الفروض (جن کا حصہ شریعت نے مقرر کر دیا ہے) لیں گے، ان سے جو بچ جائے وہ عصبہ لیں گے۔ البتہ اگر کسی شخص سے خطا (غلطی سے) قتل ہو جائے تو اس کے ذمہ عائد ہونے والی دیت اس کے عصبہ ہی ادا کریں گے، عصبہ قرب ترین مذکر کو کہتے ہیں، مثلاً: بیٹے، پوتے، باپ دادا، بھائی، بھتیجے، چچا تایا، ان کی اولاد۔ اور ورثاء سے مراد وہ رشتے دار ہیں جن کا حصہ وراثت میں مقرر کیا گیا ہے۔ (۵) یہ حدیث متعلقہ باب سے کوئی تعلق نہیں رکھتی۔ البتہ آئندہ باب سے اس کا تعلق ہے اور سنن نسائی میں بہت جگہ ایسا ہوا ہے، خصوصاً جب کہ سابقہ باب کے تحت روایات زیادہ ہوں۔"}],[4802,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قتل خطا کی دیت میں بیس اونٹنیاں ایک ایک سال کی جو دوسرے میں لگی ہوں، بیس اونٹ جو ایک ایک سال کے ہوں اور دوسرے میں لگے ہوں، بیس اونٹنیاں دو دو سال کی جو تیسرے میں لگی ہوں، بیس اونٹنیاں چار چار سال کی جو پانچویں میں لگی ہوں اور بیس اونٹنیاں تین تین سال کی جو چوتھے میں لگی ہوں دینے کا حکم کیا ۱؎۔\n§وضاحت\n۱؎: یہ حدیث ضعیف ہے اس لیے پچھلی حدیث پر عمل ہو گا جو صحیح ہے، رسول اللہ صلی اللہ علیہ وسلم نے خیبر کے مقتول :(جس کا ذکر قسامہ کے شروع میں گزرا ) کی دیت میں سو اونٹ ادا کئے تھے جن میں کوئی بھی ابن مخاض نہیں تھا جس کا ذکر اس ضعیف حدیث میں ہے۔","الألباني: ضعيف",{"u2":"حضرت ابن مسعود رضی اللہ تعالٰی عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قتل خطا کی دیت کے بارے میں فیصلہ فرمایا کہ ان میں بیس بنت مخاص (ایک سالہ اونٹنی) بیس ابن مخاض (ایک سالہ مذکر) بیس بنت لبون (دو سالہ اونٹنی) بیس جذعے (چار سالہ اونٹنی) اور بیس حقے (تیس سالہ اونٹنی) ہوں گے۔"}],[4803,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک شخص نے ایک شخص کو قتل کر دیا تو نبی اکرم صلی اللہ علیہ وسلم نے اس کی دیت بارہ ہزار درہم مقرر کی، اور دیت لینے سے متعلق اللہ تعالی کا یہ ارشاد بیان کیا «إلا أن أغناهم اللہ ورسوله من فضله» \"مگر یہ کہ اب اللہ اور اس کے رسول نے ان کو مالدار کر دیا ہے\" (المائدہ: ۵۰)، الفاظ ابوداؤد کے ہیں۔","الألباني: ضعيف",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسو اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ایک آدمی نے دوسرے آدمی کو قتل کر دیا۔ نبی اکرم صلی اللہ علیہ وسلم نے اس کی دیت بارہ ہزار درہم مقرر فرمائی۔ حضرت ابن عباس رضی اللہ عنہ نے فرمایا کہ اللہ تعالیٰ کا فرمان: {وَ مَا نَقَمُوْٓا اِلَّآ اَنْ اَغْنٰہُمُ اللّٰہ…} ’’اور نہیں انتقام لیا انھوں نے مگر اس بات کا کہ اللہ تعالیٰ اور اس کے رسول نے ان کو اپنے فضل سے غنی فرمایا۔‘‘ دیت لینے کے بارے میں ہے۔\nاور (مذکورہ) الفاظ ابوداود حرانی کے ہیں۔","f2":"جبکہ محمد بن مثنیٰ کی حدیث کے الفاظ اس کے ہم معنی ہیں۔"}],[4804,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بارہ ہزار درہم کا فیصلہ کیا یعنی دیت میں۔","الألباني: ضعيف",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دیت بارہ ہزار درہم مقرر فرمائی۔","f2":"(۱) مذکورہ بالا دونوں روایات کی صحت مرفوعاً محل نظر ہے۔ راجح بات یہ ہے کہ یہ روایت مرسل ہے، تاہم بارہ ہزار درہم کے بارے میں یہ بات صحیح سند سے مروی ہے کہ حضرت عمر رضی اللہ تعالٰی عنہ نے اونٹوں کی قیمت کا حساب لگا کر بارہ ہزار درہم مقرر کیے تھے۔ (سنن ابی داود، حدیث: ۴۵۴۲) مزید تفصیل کے لیے دیکھیے: (الاروائ: ۷/ ۳۰۴، ذخیرۃ العقبی شرح سنن النسائی: ۳۶، ۱۸۶) (۲) اصل دیت تو اونٹ ہیں جن کی تفصیل پیچھے بیان ہو چکی ہے۔ اگر سونے چاندی یا سکوں میں دیت دینا ہو تو مذکورہ صفات کے اونٹوں کی قیمت دینا ہوگی جو علاقے اور زمانے کے لحاظ سے بدلتی رہتی ہے۔"}],[4805,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورت کی دیت ایک تہائی دیت تک مرد کی دیت کی طرح ہے\"۔\n§وضاحت\n۱؎: یہ حدیث اصول حدیث کے حساب سے ضعیف ہے، مگر جمہور علماء کا یہی قول ہے، بلکہ بعض لوگوں نے اس پر اجماع نقل کیا ہے، اور یہ کہ ابن خزیمہ نے اس حدیث کی تصحیح کی ہے حدیث کا مطلب یہ ہے کہ مرد کی مکمل دیت سو اونٹ ہے اور عورت کے قتل عمد و شبہ عمد و خطا میں آدھی دیت پچاس اونٹ واجب الاداء ہوں گے، لیکن اگر اعضاء کے تلف کرنے کی دیت ہو تو جیسے ایک انگلی کی دیت دس اونٹ ہیں، مان لیا کہ کسی نے کسی عورت کی چار انگلیاں توڑ دیں تو ان کی دیت چالیس اونٹ ہوئے جو سو کے ثلث :(۳۳ ) سے زیادہ ہو گئے تو اب انگلیاں توڑنے والے پر صرف بیس :(۲۰ ) اونٹ واجب ہوں گے، :(علی ھذا القیاس )۔","الألباني: ضعيف",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’عورت کی دیت مرد کے برابر ہے حتیٰ کہ تہائی کو پہنچ جائے۔‘‘"}],[4806,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ذمیوں کی دیت مسلمانوں کی دیت کی آدھی ہے، اور ذمیوں سے مراد یہود و نصاری ہیں\" ۱؎۔\n§وضاحت\n۱؎: یہ حدیث صحیح ہے، اور اسی پر جمہور کا عمل ہے، حنفیہ کا قول ہے کہ مسلم کافر ذمی سب کی دیت :(خون بہا ) برابر ہے، ان کا استدلال «دیۃ المعاہد دیۃ الحر المسلم» سے ہے جو مرسل اور ضعیف ہے، جب کہ باب کی یہ حدیث صحیح ہے، اور اس کی حکمت یہ ہے کہ مسلم کو کافر پر برتری حاصل ہے جس کے اظہار کا یہ بھی ایک ذریعہ ہے۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ذمی کی دیت مسلمان سے نصف ہے۔ ذمی سے مراد یہود ونصاریٰ ہیں۔‘‘","f2":"’’نصف ہے‘‘ کیونکہ مسلمان اور کافر کی شان برابر نہیں ہو سکتی۔ {اَفَنَجْعَلُ الْمُسْلِمِیْنَ کَالْمُجْرِمِیْنَ} (القلم ۶۸: ۳۵) البتہ ذمی کا قتل معاہدے کی خلاف ورزی ہے، لہٰذا نصف دیت دینی ہوگی۔ احناف مسلم اور ذمی کی دیت برابر سمجھتے ہیں اور اس مفہوم کی ایک مرسل حدیث بیان کرتے ہیں۔ امام شافعی رحمہ اللہ تہائی دیت کے قائل ہیں لیکن دونوں قول صحیح حدیث کے خلاف ہیں۔"}],[4807,"عبداللہ بن عمر رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم سے (اسی طرح کا واقعہ) نقل کرتے ہیں، اور کہتے ہیں کہ انہیں کے سلسلے میں آیت محاربہ نازل ہوئی۔\nابوالزناد سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب ان کے ہاتھ کاٹے جن ہوں نے آپ کی اونٹنیاں چرائی تھیں اور آگ سے ان کی آنکھوں کو پھوڑا تو اللہ تعالی نے اس سلسلے میں آپ کی سرزنش کی ۱؎، چنانچہ اللہ تعالی نے یہ مکمل آیت اتاری «إنما جزاء الذين يحاربون اللہ ورسوله» \"ان لوگوں کا بدلہ جو اللہ اور اس کے رسول سے لڑتے ہیں … الخ\"۔\n§وضاحت\n۱؎: یہ اثر ضعیف ہے اور اس میں یہ بات کہ ابوالزناد نے اللہ تعالی کی جانب سے نبی اکرم صلی اللہ علیہ وسلم کے متعلق عتاب کی جو بات کہی ہے غیر مناسب ہے کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے ان لوگوں کے ساتھ وہی سلوک اپنایا جو انہوں نے آپ صلی اللہ علیہ وسلم کے چروا ہوں کے ساتھ اپنایا تھا۔ اللہ تعالی نے آپ کے سلوک پر صاد کیا، صرف آنکھیں پھوڑنے کی ممانعت کر دی۔\nعبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کافر کی دیت مومن کی دیت کی آدھی ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کافر کی دیت مومن کی دیت سے نصف ہے۔‘‘"}],[4808,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مکاتب کے بارے میں حکم کیا کہ مکاتب غلام اگر قتل ہو جائے تو اس کی دیت اتنے حصے میں جو وہ بدل کتابت کے طور پر ادا کر چکا ہے آزاد کی دیت کے مثل ہو گی۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مکاتب کے بارے میں، جسے قتل کر دیا جائے، فیصلہ فرمایا کہ جس قدر وہ مکاتبت ادا کر چکا ہے، اتنی آزاد کی دیت دی جائے گی۔‘‘","f2":"(۱) محقق کتاب نے اس روایت کی سند کو ضعیف قرار دیا ہے لیکن یہ روایت اور بعد والی روایات: ۴۸۱۳ اور ۴۸۱۴ بھی شواہد ومتابعات کی بنا پر صحیح ہیں۔ اس روایت کی متابعت اور شواہد کے لیے حدیث: ۴۸۱۵، ۴۸۱۶ ملاحظہ کیجئے۔ (۲) اس حدیث سے معلوم ہوتا ہے کہ مکاتب جس قدر مکاتبت کی رقم ادا کر دے، اتنا آزاد تصور ہوگا، باقی غلام، مثلاً: جو غلام نصف رقم ادا کر چکا ہو، وہ نصف آزاد ہوگا، نصف غلام۔ اس حالت میں اگر وہ قتل کر دیا جائے تو آزاد حصے کی دیت پچاس اونٹ ہوگی اور باقی نصف غلام کی دیت دی جائے گی، یعنی پچیس اونٹ۔"}],[4809,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مکاتب غلام کے بارے میں فیصلہ فرمایا: \"اس کی اتنے حصے کی دیت جس قدر وہ آزاد ہو چکا ہو آزاد کی دیت کے مثل ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم نے مکاتب کے بارے میں فیصلہ فرمایا کہ (اگر وہ قتل کر دیا جائے تو) جس قدر وہ آزاد ہو چکا ہے، اتنی دیت آزاد کی دی جائے گی۔"}],[4810,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مکاتب غلام کے بارے میں فیصلہ کیا کہ جس قدر اس نے مکاتبت کا بدل ادا کر دیا ہو، اتنے کی دیت آزاد کی دیت کے مثل ہو گی، اور جس کی ادائیگی باقی ہو اس کی دیت غلام کی دیت کے مثل ہو گی۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مکاتب کے بارے میں فیصلہ فرمایا کہ مکاتب غلام جس قدر مال مکاتبت ادا کر چکا ہے، اس کی اتنی دیت آزاد کے حساب سے دی جائے گی اور باقی غلام کے لحاظ سے۔"}],[4811,"عبداللہ بن عباس رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مکاتب اسی قدر آزاد ہو گا جتنا اس نے بدلِ مکاتبت ادا کر دیا ہو اور اس پر حد بھی اسی قدر نافذ ہو گی جس قدر وہ آزاد ہو چکا ہو، اور وہ وارث بھی اسی قدر ہو گا جس قدر آزاد ہو چکا ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’مکتابت اتنا آزاد ہے جس قدر وہ مکاتبت ادا کر چکا ہے اور وہ جس قدر آزاد ہے، اتنی اس پر حد لگائی جائے گی اور جس قدر وہ آزاد ہے، اتنا وہ وارث بنے گا۔‘‘","f2":"حدیث کا مفہوم بالکل واضح ہے کہ مکاتب جس تناسب سے مکاتبت کی رقم آزاد کر چکا ہے، اتنا وہ آزاد ہے۔ اگر نصف رقم ادا کر چکا ہے تو نصف آزاد ہے۔ اس کے ساتھ نصف آزاد والا سلوک کیا جائے گا، حد میں بھی اور وراثت میں بھی۔ اور باقی نصف غلام سلوک کیا جائے گا جیسا کہ حدیث میں واضح طور پر یہ بات موجود ہے۔ واللہ اعلم"}],[4812,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک مکاتب کا قتل ہو گیا تو آپ نے حکم دیا کہ جتنا وہ بدل مکاتبت ادا کر چکا ہے اسی قدر اس کی دیت آزاد کی دیت کے مثل ہو گی، اور جس قدر آزاد نہیں ہوا ہے اسی کے مطابق اس کی دیت غلام کی دیت کے مثل ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ایک مکاتب کو قتل کر دیا گیا تو آپ نے حکم دیا کہ جس قدر وہ مال مکاتبت ادا کر چکا ہے، اتنے حصے کی دیت آزاد کے حسا ب سے دی جائے اور باقی کی غلام کے لحاظ سے۔","f2":"مکاتب سے مراد وہ غلام ہے جس نے اپنے مالک سے کچھ رقم کی ادائیگی کے عوض اپنی آزادی کا معاہدہ کر رکھا ہو۔ اس معاہدے کو مکاتبت یا کتابت کہتے ہیں اور مقررہ رقم کو مال مکاتبت کہا جاتا ہے۔ تفصیل پیچھے گزر چکی ہے۔"}],[4813,"بریدہ رضی اللہ عنہ سے روایت ہے کہ ایک عورت نے ایک عورت کو پتھر پھینک کر مارا جس سے اس کا حمل ساقط ہو گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے بچے کی (دیت) پچاس بکریاں ۱؎ طے کیں اور اس دن سے آپ نے پتھر پھینکنے سے منع فرما دیا۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) اسے ابونعیم نے مرسلاً روایت کیا ہے۔ (ان کی روایت آگے آ رہی ہے)\n§وضاحت\n۱؎: سنن ابوداؤد میں اسی سند سے اس حدیث کے الفاظ ہیں \" پانچ سو بکریاں \" جیسا کہ اگلی روایت میں ہے \" پانچ سو \" کی طرح یہ لفظ بھی کسی راوی کا وہم معلوم ہوتا ہے، واضح رہے کہ مؤلف کی اگلی روایت کی طرح ابوداؤد کی روایت مرسل نہیں بلکہ مرفوع متصل ہے، :(واللہ اعلم بالصواب )۔","الألباني: صحيح الإسناد",{"u2":"حضرت بریدہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک عورت نے دوسری عورت کو پتھر دے مارا جس سے اس کا حمل ضائع ہوگیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سلسلے میں بچے کی دیت پچاس بکریاں مقرر کیں اور اس دن آپ نے خذف سے بھی منع فرمایا۔\nابو نعیم نے اس روایت کو مرسل بیان کیا","f2":"(۱) اس حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جنین، یعنی پیٹ کے بچے کی دیت پچاس بکریاں مقرر فرمائی جبکہ دیگر صحیح احادیث میں ’’جنین‘‘ (پیٹ کے بچے) کی دیت ’’غُرَّۃ‘‘ (غلام یا لونڈی) مذکور ہے۔ دونوں روایات میں تطبیق یوں ممکن ہے کہ لونڈی کی درمیانی قیمت پچاس بکریوں کے برابر ہو۔ اس طرح ان میں تضاد ختم ہو جاتا ہے۔ دوسرے بوعض علماء نے کہا کہ اس روایت کا متن اصح روایت کے مخالف ہونے کی وجہ سے معلول ہے، لہٰذا اس طرح دونوں روایات کا تضاد ہی نہ رہا۔ (۲) خذف سے مراد کنکریاں پھینکنا ہے۔ شغل کے طور پر چھوٹی چھوٹی کنکریوں سے نشانے لگانا اگرچہ ظاہراً بے ضرر سا کام محسوس ہوتا ہے مگر اس سے کوئی آنکھ ضائع ہو سکتی ہے، دانت ٹوٹ سکتا ہے، کوئی نازک عضو متاثر ہو سکتا ہے، اس لیے اس سے منع فرمایا۔ ویسے بھی یہ بے فائدہ کام ہے۔ اس عورت نے بھی تو دوسری عورت کو پتھر مارا تھا اور خیمے کی چوب، یعنی لکڑی ماری تھی جو دوسری عورت کے پیٹ وغیرہ پر لگی جس سے یہ نقصان ہوگیا۔ آپ نے اسی مناسبت سے خذف کو بھی ممنوع قرار دیا ہے۔ (۳) امام نسائی رحمہ اللہ فرماتے ہیں کہ ابو نعیم (فضل بن دکین) نے مذکورہ روایت مرسل بیان کی ہے۔ انھوں نے اپنی روایت میں کہا ہے: [حَدَّثَنَا یُوسُفُ بْنُ صُھَیْبٍ، قَالَ حَدَّثَنِی عَبْدُاللّٰہِ بْنُ بُرَیْدَۃَ أَنَّ اِمْرَأَۃً… الخ] مطلب یہ کہ ابو نعیم نے عبداللہ کے باپ حضرت بریدہ کا ذکر چھوڑ دیا ہے۔ آئندہ آنے والی روایت ابو نعیم ہی کی ہے جو انھوں نے مرسل بیان کی ہے۔"}],[4814,"عبداللہ بن بریدہ سے روایت ہے کہ ایک عورت نے ایک عورت کو پتھر پھینک کر مارا، پتھر لگی عورت کا حمل گر گیا، چنانچہ مقدمہ نبی اکرم صلی اللہ علیہ وسلم تک پہنچا، تو آپ نے اس بچے کی دیت پانچ سو بکریاں ۱؎ مقرر کیں، اور اس دن سے آپ نے پتھر پھینکنے سے منع فرمایا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ وہم ہے، صحیح سو بکریاں ہیں، (پانچ سو نہیں) اور پتھر پھینکنے کی ممانعت سے متعلق حدیث عبداللہ بن بریدہ ہی کے واسطہ سے: عبداللہ بن مغفل رضی اللہ عنہ سے مروی ہے (جو آگے آ رہی ہے)۔\n§وضاحت\n۱؎: اگلی روایات :(رقم ۴۸۲۰ و ۴۸۲۱ ) میں \" ایک غرہ \" یعنی ایک غلام یا باندی کا ذکر ہے، ہو سکتا ہے اس وقت ایک غلام یا باندی کی قیمت سو بکریوں کے مساوی ہوتی ہو۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عبداللہ بن بریدہ نے بیان کیا کہ ایک عورت نے دوسری عورت کو پتھر دے مارا جس سے اس کا حمل ضائع ہوگیا۔ یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا تو آپ نے اس بچے کی دیت پانچ سو بکریاں مقرر فرمائی، نیز اس دن آپ نے خذف سے روک دیا۔\nامام ابوعبدالرحمن (نسائی رحمہ اللہ) بیان کرتے ہیں: یہ وہم ہے۔ ہو سکتا ہے کہ ان کا ارادہ ایک سو بکریاں کہنے کا ہو (لیکن غلطی سے پانچ سو بکریاں کہہ دیں)۔ اور خذف، یعنی کنکری پھینکنے کی ممانعت تو عبداللہ بن بریدۃ، عن عبداللہ بن مغفل سے مروی ہے۔ (اور وہ اگلی حدیث: ۴۸۱۹ ہی میں ہے۔)","f2":"امام نسائی رحمہ اللہ کی طرح یہی بات امام ابوداؤد رحمہ اللہ نے بھی اپنی سنن میں مذکورہ (پانچ سو بکریوں والی روایت بیان کرنے کے بعد فرمائی ہے۔ دیکھیے: (سنن ابی داود، الدیات، باب دیۃ الجنین، حدیث: ۴۵۷۸) احادیث صحیحہ کے معارض ہونے کے علاوہ مذکورہ حدیث ہے بھی مرسل جیسا کہ پہلے بھی بیان ہو چکا ہے، اس لیے یہ قابل حجت نہیں۔ اصل مسئلہ وہی ہے جس کی وضاحت حدیث: ۴۸۱۷ کے فوائد ومسائل کے تحت ہو چکی ہے۔ واللہ اعلم"}],[4815,"عبداللہ بن بریدہ سے روایت ہے کہ عبداللہ بن مغفل رضی اللہ عنہ نے ایک شخص کو پتھر پھینکتے دیکھا تو کہا: مت پھینکو، اس لیے کہ نبی اکرم صلی اللہ علیہ وسلم پتھر پھینکنے سے منع فرماتے تھے، یا پتھر پھینکنا آپ کو پسند نہ تھا، یہ کہمس کا شک ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مغفل رضی اللہ تعالٰی عنہ نے ایک آدمی کو خذف کرتے دیکھا تو فرمایا: خذف نہ کر کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے خذف سے منع فرمایا ہے یا آپ اسے ناپسند فرماتے تھے۔ کَھْمَس کو شک ہے۔","f2":"مطلب یہ ہے کَھْمَس راوی کو شک ہے کہ ’’نَھٰی عَنِ الْخَذْفِ‘‘ کے الفاظ ہیں یا ’’بَکْرَہُ الْخَذْفَ‘‘ کے، تاہم یہ شک صحت روایت پر اثر انداز نہیں ہوگا۔"}],[4816,"طاؤس سے روایت ہے کہ عمر رضی اللہ عنہ نے لوگوں سے جنین (پیٹ میں موجود بچہ کی دیت) کے سلسلے میں مشورہ طلب کیا، تو حمل بن مالک رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے جنین (پیٹ میں موجود بچہ) میں ایک غرہ (ایک لونڈی یا ایک غلام) کا فیصلہ کیا۔ طاؤس کہتے ہیں: گھوڑا بھی «غرہ» ہے۔","الألباني: صحيح",{"u2":"حضرت طاؤس سے روایت ہے کہ حضرت عمر رضی اللہ تعالٰی عنہ نے پیٹ کے بچے کی دیت کے بارے میں لوگوں سے مشورہ کیا تو حضرت حمل بن مالک رضی اللہ تعالٰی عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے پیٹ کے بچے کی دیت غرہ مقرر فرمائی ہے۔ حضرت طاؤس نے کہا کہ گھوڑا بھی غرہ ہے۔","f2":"احادیث میں غرہ کی تفسیر غلام یا لونڈی سے کی گئی ہے۔ حضرت طاوس نے گھوڑے کو اور بعض لوگوں نے گھوڑے کے ساتھ ساتھ خچر کو بھی شامل کر دیا ہے۔ بعض مرفوع روایات میں گھوڑے اور خچر کا ذکر مدرج اور کسی راوی کا وہم ہے کیونکہ غرہ کی تفسیر جب خود رسول اللہ صلی اللہ علیہ وسلم نے غلام یا لونڈی سے فرما دی ہے تو پھر ادھر ادھر التفات کی ضرورت ہی نہیں رہی۔ رسول اللہ صلی اللہ علیہ وسلم کی بات قول فیصل ہے۔"}],[4817,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بنی لحیان کی عورت کے جنین (پیٹ میں موجود بچہ) کے بارے میں جو مرا ہوا ساقط ہو گیا تھا ایک«غرہ» یعنی ایک غلام یا ایک لونڈی کا فیصلہ کیا، پھر وہ عورت جس پر ایک «غرہ» یعنی ایک غلام یا ایک لونڈی کا حکم ہوا، مر گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی میراث اس کے بیٹوں اور اس کے شوہر کے لیے ہے اور دیت اس کے عصبہ پر ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے بنو لحیان کی ایک عورت کے پیٹ کے بچے کے بارے میں جو (چوٹ کی وجہ سے) ساقط ہو کر مر گیا تھا، فیصلہ فرمایا کہ اس کی دیت غرہ ہوگی، یعنی غلام یا لونڈی۔ پھر جس عورت کے لیے (جس کے بچے کی دیت کی بابت) غرہ کا فیصلہ کیا تھا، وہ مر گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ اس کی وراثت اس کے بیٹوں اور خاوند کو ملے گی۔ اور اس (قاتلہ) کے ذمے واجب الادا دیت اس (قاتلہ) کے عصبہ کے ذمے ہوگی۔","f2":"(۱) اس حدیث میں بھی جنین کی دیت غلام یا لونڈی بیان ہوئی ہے، تاہم اگر جنین زندہ پیٹ سے باہر آیا، پھر اسی لگائی گئی چوٹ کے اثر کی وجہ سے فوت ہوگیا تو اس صورت میں بڑے شخص والی مکمل دیت ادا کری پڑے گی۔ چوٹ جان بوجھ کر لگائی گئی ہو یا غلطی سے لگی ہو، دونوں صورتوں میں مسئلہ اسی طرح ہے جیسے بیان کیا گیا ہے۔ واللہ اعلم تفصیل کے لیے دیکھیے: (ذخیرۃ القبی شرح سنن النسائی لاتبوبی: ۳۶/ ۲۱۹، ۲۲۰) (۲) اس حدیث مبارکہ کے الفاظ [ان المراۃ التی قضی علیھا بالغرۃ توفیت] سے بعض اہل علم کو یہ وہم ہوا ہے کہ اس سے مراد قاتلہ ہے، اس لیے انھوں نے ان الفاظ کے معنی کیے ہیں: ’’پھر جس عورت کے ذمے غرہ (دینے کا فیصلہ کیا گیا تھا، وہ مر گئی۔‘‘ یہ بات درست نہیں بلکہ حقیقت واقعہ کے خلاف ہے۔ اصل بات یہ ہے کہ مرنے والی قاتلہ نہیں بلکہ وہ تھی جس کا جنین گرایا گیا تھا کیونکہ احادیث صحیحہ میں یہ صراحت موجود کہ مرنے والی قاتلہ نہیں بلکہ دوسری تھی جسے پتھر مار کر اس کا جنین گرا دیا گیا تھا اور اسے قتل کر دیا گیا تھا۔ حدیث کے الفاظ ہیں: [اقتتلت امراتان من ھذیل فرمت احداھما الاخری بحجر فقتلتھا وما فی بطنھا] ’’ہذیل قبیلے کی دو عورتیں لڑ پڑیں۔ ان میں سے ایک نے دوسری کو پتھر دے مارا اور اسے قتل کر دیا اور اس بچے کو بھی جو اس کے پیٹ میں تھا۔‘‘ (صحیح البخاری، الدیات، باب جنین المراۃ… حدیث: ۶۹۱۰، وصحیح مسلم، القسامۃ والمحاربین، باب دیۃ الجنین…، حدیث: ۱۶۸۱ (۳۶) التی قصی علیھا بالغرۃ کا مفہوم ہے: التی قضی لھا بالغرۃ۔ مطلب یہ کہ علیھا بمعنیے لھا ہے۔ صحیح بخاری میں یہ الفاظ ہیں: [ثم ان المراۃ التی قضی لھا بالغرۃ توفیت] دیکھیے: (صحیح البخاری، الفرائض، باب میراث المرأۃ والزوج مع الولد وغیرہ، حدیث: ۶۷۴۰) بعض اہل علم کو حدیث مبارکہ کے آخری جملے [قضی رسول اللہ صلی اللہ علیہ وسلم بان میراثھا لبنیھا وزوجھا، وان العقل علی عصبتھا] سے یہ وہم لگا ہے کہ مرنے والی قاتلہ ہی ہے۔ اسی کی وراثت کے حق دار اس کے بیٹے اور اس کا خاوند ہیں اور اس کی دیت اس کے عصبہ کے ذمہ ہے۔ صحیح مسلم کی حدیث سے اس شبہ اور وہم کا کلیتاً ازالہ ہو جاتا ہے۔ اس کے الفاظ اس قدر واضح اور صریح ہیں کہ وہم کا تصور ہی نہیں ہوتا۔ الفاظ یہ ہیں: [فجعل رسول اللہ صلی اللہ علیہ وسلم دیۃ المقتولۃ علی عصبۃ القاتلۃ وغرۃ لما فی بطنھا] ’’پھر رسول اللہ صلی اللہ علیہ وسلم نے مقتولہ کی دیت، قاتلہ کے عصبہ کے ذمے لگائی اور اس (مقتولہ) کے پیٹ کے بچے کی دیت ایک غرہ مقرر فرمائی۔‘‘ (صحیح مسلم، القسامۃ، والمہاربین، باب دیۃ الجنین…، حدیث: ۱۶۸۲) مذکورہ بالا تصریحات سے تمام شبہات ختم ہو جاتے ہیں۔ (۳) قتل خطا شبہ عمد میں دیت قاتل کے ذمے ہوتی ہے لیکن اس کی ادائیگی میں اس کے تمام نسبی رشتہ دار شریک ہوں گے۔ قانونی طور پر ان سب کے ذمے قسط وار رقم مقرر کی جائے گی اور وہ ادا کرنے کے پابند ہوں گے کیونکہ قتل خطا میں قاتل قصور وار نہیں ہوتا یا زیادہ قصور وار نہیں ہوتا۔ البتہ عمد کی صورت میں دیت قاتل کے ذمے ہوگی اور وہی ادائیگی کا ذمہ دار ہے کیونکہ وہ مکمل قصور وار ہوتا ہے، لہٰذا اسے ہی سزا بھگتنا ہوگی۔ واللہ اعلم"}],[4818,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ قبیلہ ہذیل کی دو عورتیں جھگڑ پڑیں، ان میں سے ایک نے دوسری کو پتھر پھینک مارا، اور کوئی ایسی بات کہی جس کا مفہوم یہ تھا کہ وہ عورت مر گئی اور اس کے پیٹ کا بچہ بھی، چنانچہ وہ لوگ جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ صلی اللہ علیہ وسلم نے فیصلہ کیا: اس کے جنین(پیٹ کے بچہ) کی دیت ایک غرہ ہے یعنی ایک غلام یا ایک لونڈی۔ اور (قاتل) عورت کی دیت اس کے کنبے کو لوگوں (عصبہ) سے دلائی اور اس عورت کا وارث اس کے بیٹوں اور دوسرے ورثاء کو قرار دیا، تو حمل بن مالک بن نابغہ ہذلی رضی اللہ عنہ نے کہا: اللہ کے رسول! اس کا تاوان کیسے ادا کروں جس نے نہ پیا نہ کھایا، جو نہ بولا نہ چلایا، ایسا خون تو لغو ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کاہنوں کا بھائی ہے\" (یہ بات آپ نے اس کی اس قافیہ دار بات چیت کی وجہ سے جو اس نے کی)۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: قبیلہ ہذیل کی دو عورتیں آپس میں لڑ پڑیں۔ ایک نے دوسری کو پتھر دے مارا۔ نتیجتاً اسے بھی قتل کر دیا اور اس کے پیٹ کے بچے کو بھی۔ وہ (ورثائ) یہ جھگڑا رسول اللہ صلی اللہ علیہ وسلم کے پاس لے گئے تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ پیٹ کے بچے کی دیت غرہ ہے، یعنی ایک غلام یا لونڈی، نیز اپ نے فیصلہ فرمایا کہ (قاتلہ) عورت کے ذمے واجب الادا دیت اس کے عصبہ بھریں گے۔ اور آپ نے اس (مقتولہ) کی اولاد اور دیگر ورثاء کو اس کا وارث بنایا۔ حضرت حمل بن مالک بن نابغہ ہذلی نے کہا: اے اللہ کے رسول! میں کیسے اس (بچے) کی دیت بھروں جس نے نہ پی نہ کھایا، نہ بولا نہ چلایا؟ اس جیسا (بچہ) تو ضائع اور لغو (بلا دیت) ہوتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ تو کاہنوں میں سے ایک کاہن محسوس ہوتا ہے۔‘‘ (آپ نے یہ بات فرمائی) اس لیے کہ اس نے مسجع کلام کیا تھا۔","f2":"’’کاہن‘‘ دور جاہلیت میں ہر بت کے ساتھ ایک کاہن بھی ہوتا تھا۔ لوگ علاج وغیرہ کے لیے بھی انھی سے رابطہ کرتے تھے۔ یہ بڑے چالاک وعیار لوگ ہوتے تھے۔ جنوں سے روابط رکھتے تھے۔ ذو معنی کلام کیا کرتے تھے۔ پیش گوئیاں بھی کرتے تھے مگر بڑے محتاط انداز میں تاکہ پیش آمدہ حالات میں مشکل پیش نہ آئے۔ بڑی دلآویز کلام کرتے تھے۔ چھوٹے چھوٹے مسجع فقرے بولتے تھے جن کو سن کر لوگ مرعوب ہو جاتے تھے۔ یہی وجہ ہے کہ آپ نے حضرت حمل بن مالک کو کاہن کہا۔"}],[4819,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں قبیلہ ہذیل کی دو عورتوں میں سے ایک نے دوسری کو پتھر پھینک کر مارا۔ جس سے اس کا حمل ساقط ہو گیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس میں ایک «غرہ» یعنی ایک غلام یا ایک لونڈی دینے کا فیصلہ کیا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں قبیلہ ہذیل کی دو عورتوں میں سے ایک نے دوسری کو پتھر دے مارا اور اس کا حمل گرا دیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت غرہ مقرر کی، یعنی ایک غلام یا لونڈی۔"}],[4820,"تابعی سعید بن مسیب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیع محاقلہ اور مزابنہ سے منع فرمایا ہے۔ اسے محمد بن عبدالرحمٰن بن لبیبہ نے سعید بن المسیب سے روایت کیا ہے اور «عن سعد بن أبي وقاص» کہا ہے۔\nسعید بن مسیب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس بچے کی دیت «غرہ» یعنی ایک غلام یا ایک لونڈی دینے کا فیصلہ کیا جو ماں کے پیٹ میں ہی قتل کر دیا جائے، تو وہ شخص جس کے خلاف آپ نے فیصلہ کیا تھا بولا: میں اس کی دیت کیوں کر ادا کروں جس نے نہ پیا، نہ کھایا، جو نہ چیخا اور نہ بولا۔ ایسا خون تو لغو ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تو کاہنوں میں سے (لگتا) ہے\" ۱؎۔\n§وضاحت\n۱؎: اس کے بارے میں آپ نے ایسا اس لیے فرمایا کہ اس نے کاہنوں کی طرح مقفع مسجع جملے استعمال کیے، نہ کہ آپ نے خود اس کو کاہن قرار دیا۔","الألباني: صحيح لغيره",{"u2":"حضرت سعید بن مسیب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پیٹ کے اس بچے کی دیت جسے والدہ کے پیٹ میں قتل کر دیا جائے، ایک غرہ مقرر فرمائی ہے، یعنی غلام یا لونڈی۔ جس شخص کے خلاف آپ نے فیصلہ فرمایا تھا، وہ کہنے لگا: میں اس بچے کی دیت کیسے بھروں جس نے نہ پیا نہ کھایا، نہ چیخا نہ بولا؟ ایسا بچہ تو ضائع اور لغو ہوتا ہے (معاوضے کا حق دار نہیں ہونا چاہیے)۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ تو کاہن لگتا ہے۔‘‘"}],[4821,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ ایک عورت نے اپنی سوکن کو خیمے کی لکڑی (کھونٹی) سے مارا، جس سے وہ مر گئی، وہ حمل سے تھی، چنانچہ معاملہ نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا، تو آپ نے مارنے والی عورت کے عصبہ پر دیت کا اور جنین (پیٹ کے بچہ) کے بدلے ایک «غرہ» (غلام یا ایک لونڈی) دینے کا فیصلہ کیا۔ اس کے خاندان والے بولے: کیا اس کی بھی دیت ادا کی جائے گی، جس نے نہ کھایا، نہ پیا، نہ چیخا اور نہ چلایا۔ ایسا خون تو لغو ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: کیا تم اعراب (دیہاتیوں) کی طرح مسجع کلام کرتے ہو۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ ایک عورت نے اپنی سوکن کو خیمے کی لکڑی دے ماری اور اسے قتل کر دیا جبکہ وہ حاملہ تھی۔ (لہٰذا حمل بھی ضائع ہوگیا)۔ یہ مقدمہ نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ قاتل عورت کے عصبے (مقتولہ کی) دیت بھریں، نیز پیٹ کے بچے کے بدلے غرہ دیں۔ اس عورت کا عصبہ کہنے لگا: کیا میں ایسے بچے کی دیت دوں جس نے پیا نہ کھایا، چیخا نہ چلایا؟ ایسا بچہ تو کسی شمار وقطار میں نہیں ہونا چاہیے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’یہ تو اعرابیوی جیسی تک بندی کرتا ہے۔‘‘","f2":"(۱) ’’ایسا بچہ‘‘ یعنی جو زندہ پیدا نہیں ہوا بلکہ پیدا ہونے سے پہلے فوت ہوگیا۔ (۲) ’’اعرابیوں جیسی‘‘ اعرابی لوگ فصیح وبلیغ زبان بولتے تھے اور اعلیٰ درجے کے شاعر ہوتے تھے، نیز وہ مسجع کلام کیا کرتے تھے۔ (۳) ’’تک بندی‘‘ یعنی مسجع کلام جس کے جملے ہم آہنگ ہوں۔ ہر جملے کے آخر میں ایک جیسے الفاظ آئیں جیسے اشعار میں ہوتا ہے مگر وزن ایک نہیں ہوتا۔ (۴) اس روایت میں ہے کہ اس عورت نے خیمے کی چوب، یعنی لکڑی ماری تھی جبکہ بعض روایات میں ہے کہ اس نے پتھر مارا تھا۔ ان میں تطبیق اس طرح ہے کہ ممکن ہے اس نے دونوں چیزیں ماری ہوں، کسی راوی نے ایک چیز بیان کر دی کسی نے دوسری۔ واللہ اعلم"}],[4822,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ ایک عورت نے اپنی سوکن کو خیمے کی لکڑی کھونٹی سے مارا وہ حمل سے تھی، اور مر گئی، تو رسول اللہ صلی اللہ علیہ وسلم نے مقتول عورت کی دیت اور پیٹ کے بچے کے بدلے ایک «غرہ» (ایک غلام یا لونڈی) قاتل عورت کے خاندان والوں پر مقرر فرمایا۔ تو قاتل عورت کے خاندان کا ایک شخص بولا: کیا ہم اس کی بھی دیت ادا کریں گے جس نے نہ کھایا نہ پیا اور نہ چیخا، ایسا خون تو معاف ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا یہ اعراب(دیہاتیوں) کی طرح سجع کرتا ہے، پھر ان پر دیت لازم ٹھہرائی ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں \" باب \" سے مناسبت اس طرح ہے کہ \" خیمے کی لکڑی \" سے عموماً آدمی کا قتل عمل نہیں آتا اس لیے جب اس کی مار سے وہ عورت مر گئی تو اس قتل کو آپ صلی اللہ علیہ وسلم نے قتل خطا یا قتل شبہ عمد :(غلطی سے قتل ) قرار دے کر اس کی دیت مقرر کی، نیز اس میں باب کے دوسرے جزء سے مناسبت اس طرح ہے کہ مقتول عورت اور جنین :(ساقط حمل ) کی دیت دونوں قاتلہ عورت کے خاندان کے ذمہ لگائی۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: ایک عورت نے اپنی سوکن کو خیمے کا ستون کھینچ مارا جب کہ وہ حاملہ تھی، وہ مر گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے مقتولہ کی دیت قاتلہ کے قریبی نسبی رشتہ داروں پر ڈال دی۔ اور مقتولہ کے پیٹ کے بچے کی دیت میں ایک غرہ لازم کیا۔ قاتلہ کے رشتہ داروں میں سے ایک شخص کہنے لگا: کیا ہم ایسے بچے کی دیت بھریں جس نے کھایا نہ پیا اور نہ چوں کی؟ ایسا بچہ تو ضائع اور لغو ہوتا ہے۔ آپ نے فرمایا: ’’کیا اعرابیوں جیسی مسجع ومقفیٰ کلام بولتے ہو؟‘‘ پھر ان پر دیت لاگو کی۔"}],[4823,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ دو سوکنوں میں سے ایک نے دوسری کو خیمے کی لکڑی سے مارا، تو وہ مر گئی، رسول اللہ صلی اللہ علیہ وسلم نے قاتلہ کے خاندان والوں کی جانب سے دیت ادا کیے جانے کا فیصلہ کیا اور پیٹ کے بچے کے لیے ایک «غرہ» یعنی ایک غلام یا لونڈی دینے کا فیصلہ کیا۔ ایک اعرابی (دیہاتی) نے کہا: آپ مجھ سے ایسی جان کی دیت ادا کروا رہے ہیں جس نے نہ کھایا، نہ پیا، نہ چیخا، نہ چلایا۔ ایسا خون تو لغو ہے۔ آپ نے فرمایا: \"یہ تو جاہلیت کی سجع کی طرح ہے\"، اور پیٹ کے بچے کے لیے ایک «غرہ» یعنی ایک غلام یا لونڈی دینے کا فیصلہ کیا۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ دو سوکنوں میں سے ایک نے دوسری کو خیمہ کی لکڑی دے ماری اور اسے قتل کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے دیت قاتلہ کے نسبی رشتہ داروں پر ڈال دی اور مقتولہ کے پیٹ کے بچے کی دیت غرہ قرار دی۔ اعرابی کہنے لگا: آپ مجھ پر ایسے بچے کی دیت ڈال رہے ہیں جس نے نہ کھایا نہ پیا، نہ چیخا نہ چلایا؟ ایسا بچہ تو ضائع اور لغو ہوتا ہے۔ آپ نے فرمایا: ’’زمانہ جاہلیت جیسی مسجع ومقفیٰ گفتگو ہے۔‘‘ آپ نے پیٹ کے بچے کی دیت غرہ مقرر فرمائی۔"}],[4824,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ بنی لحیان کی ایک عورت نے اپنی سوکن کو خیمے کی لکڑی سے مارا، جس سے وہ مر گئی، مقتولہ حمل سے تھی، تو رسول اللہ صلی اللہ علیہ وسلم نے قاتل عورت کے خاندان والوں پر دیت اور پیٹ کے بچے کے لیے ایک «غرہ» یعنی ایک غلام یا لونڈی دینے کا فیصلہ کیا۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: بنو لحیان کی ایک عورت نے اپنی سوکن کو خیمے کی لکڑی دے ماری اور اسے قتل کر دیا۔ مقتولہ کو حمل تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت قاتلہ کے نسبی رشتہ داروں پر ڈال دی اور اس (مقتولہ) کے پیٹ کے بچے کی دیت غرہ مقرر فرمائی۔"}],[4825,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ دو عورتیں ہذیل کے ایک شخص کے نکاح میں تھیں۔ ایک نے دوسری کو خیمے کا ڈنڈا پھینک کر مارا جس سے اس کا حمل ساقط ہو گیا، فریقین جھگڑا لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے، لوگوں نے کہا: ہم اس کی دیت کیوں کر ادا کریں جو نہ چیخا، نہ چلایا، نہ پیا، نہ کھایا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کیا دیہاتیوں کی طرح سجع کرتا ہے؟\" اور آپ نے عورت کے کنبے والوں پر «غرہ» یعنی ایک غلام یا لونڈی دینے کا فیصلہ کیا۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ بنو ہذیل کے ایک آدمی کے نکاح میں دو عورتیں تھیں۔ ایک نے دوسری کو خیمے کی لکڑی دے ماری اور اس کے پیٹ کا بچہ گرا دیا۔ فریقین جھگڑتے ہوئے نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ قاتل فریق کہنے لگا: ہم اس بچے کی کیسے دیت ادا کریں جس نے پیا نہ کھایا، نہ چیخا نہ چلایا؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’کیا اعرابیوں کی طرح تک بندی کر رہے ہو؟‘‘ پھر آپ نے غرہ (غلام یا لونڈی بطور دیت) قاتل عورت کے نسبی رشتہ داروں کے ذمے ڈال دی۔"}],[4826,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ ہذیل کے ایک شخص کی دو بیویاں تھیں، ان میں سے ایک نے دوسری کو خیمے کی لکڑی سے مارا، جس سے اس کا حمل ساقط ہو گیا، عرض کیا گیا: جس نے نہ کھایا، نہ پیا، جو نہ چیخا نہ چلایا، اس کے بارے میں کیا خیال ہے؟ آپ نے فرمایا: \"یہ تو دیہاتیوں کی سی سجع ہے؟\" پھر آپ نے اس میں ایک «غرہ» یعنی ایک غلام یا ایک لونڈی دینے کا فیصلہ کیا، اور اس کی ذمہ داری (قاتل) عورت کے کنبے والوں پر ٹھہرائی۔ اعمش نے اسے مرسل روایت کیا ہے۔(ان کی روایت آگے آ رہی ہے)","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ بنو ہذیل کے ایک آدمی کی دو بیویاں تھیں۔ ایک نے دوسری کو خیمے کا ستون دے مارا اور اس کا حمل گرا دیا۔ (جب آپ نے بچے کی دیت بیان فرمائی تو) آپ سے کہا گیا: بتائیں تو بھلا جس بچے نے نہ پیا نہ کھایا، نہ چیخا نہ چلایا (کیا اس کی بھی دیت ہوگی؟) آپ نے فرمایا: ’’یہ کیا اعرابیوں جیسی تک بندی ہے۔‘‘ پھر آپ نے اس کی دیت غرہ، یعنی ایک غلام یا لوندی مقرر فرمائی اور اسے عورت کے نسبی رشتہ داروں کے ذمے ڈال دیا۔\nاعمش نے اسے مرسل بیان کیا ہے۔","f2":"مذکورہ حدیث کو بہت سے محدثین نے مرفوع متصل بیان کیا ہے لیکن امام اعمش نے یہ روایت ابراہیم سے مرسل بیان کی ہے یسا کہ آئندہ روایت میں ہے: الاعمش عن ابراھیم، قال ضَربت امراۃ…‘‘"}],[4827,"ابراہیم نخعی کہتے ہیں کہ ایک عورت نے اپنی سوکن کو جو حمل سے تھی پتھر مارا، اور وہ مر گئی، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے پیٹ کے بچے کی دیت ایک«غرہ» (یعنی ایک غلام یا ایک لونڈی) ٹھہرائی اور اس کی دیت اس کے کنبے والوں کے ذمے ڈالی، وہ بولے: کیا ہم اس کی دیت دیں جس نے نہ پیا نہ کھایا اور نہ چلایا اس جیسا خون تو لغو ہوتا ہے۔ آپ نے فرمایا: \"یہ دیہاتیوں کی سی سجع ہے، حکم وہی ہے جو میں تم سے کہہ رہا ہوں\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ابراہیم سے منقول ہے کہ ایک عورت نے اپنی سوکن کو پتھر مارا جبکہ وہ حاملہ تھی جس سے وہ مر گئی تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے پیٹ کے بچے کی دیت غرہ (غلام یا لونڈی) مقرر فرمائی اور مقتولہ کی دیت قاتلہ کے نسبی رشتہ داروں کے ذمے ڈال دی۔ انھوں نے کہا: ہم ایسے بچے کی دیت بھریں جس نے پیا نہ کھایا، نہ چوں چاں کی؟ ایسے بچے کا تو کوئی معاوضہ نہیں ہونا چاہیے۔ آپ نے فرمایا: ’’اعرابیوں کی طرح تک بندی کرتے ہو؟ اصل حکم وہی ہے جو میں کہتا ہوں۔‘‘","f2":"یہ روایت مرسل ہے، تاہم شواہد کی بنا پر صحیح ہے۔"}],[4828,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ دو سوکن عورتیں تھیں، ان کے درمیان جھگڑا ہو گیا، ایک نے دوسری کو پتھر پھینک کر مارا، تو اس کے پیٹ کا بچہ مرا ہوا گر پڑا جس کے سر کے بال اگ آئے تھے اور عورت بھی مر گئی، نبی اکرم صلی اللہ علیہ وسلم نے کنبے والوں پر دیت ادا کرنے کا فیصلہ کیا۔ اس (مقتولہ) کے چچا نے کہا: اللہ کے رسول! اس کا ایک بچہ بھی ساقط ہوا ہے جس کے بال اگ آئے تھے۔ قاتل عورت کے باپ نے کہا: یہ جھوٹا ہے، اللہ کی قسم، نہ تو وہ چیخا، نہ اس نے پیا اور نہ کھایا، ایسا خون تو لغو ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جاہلیت کی سجع اور کہانت سی سجع ہے۔ بچے میں ایک «غرہ» (یعنی ایک غلام یا لونڈی) دینا ہو گا\"۔ ابن عباس رضی اللہ عنہما کہتے ہیں: ان میں سے ایک کا نام ملیکہ اور دوسری کا ام غطیف تھا۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: دو سوکنیں تھیں۔ ان میں جھگڑا ہوگیا۔ ایک نے دوسری کو پتھر دے مارا اور اس کے پیٹ کا بچہ گرا دیا جو مردہ تھا۔ اس کے بال اگ چکے تھے۔ اور عورت بھی مر گئی۔ آپ نے قاتلہ کے نسبی رشتہ داروں پر دیت ڈال دی۔ مقتولہ کے چچا نے کہا: اے اللہ کے رسول! اس نے بچہ بھی ضائع کیا ہے جس کے بال اُگ چکے تھے۔ قاتلہ کے والد نے کہا: یہ جھوٹ بولتا ہے۔ اللہ کی قسم! یہ بچہ نہ چیخا چلایا، نہ اس نے پیا نہ کھایا۔ ایسا تو ضائع اور باطل ہوتا ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’کیا جاہلوں اور کاہنوں جیسی سجع (تک بندی) کر رہا ہے؟ اس بچے میں بھی غرہ آئے گا۔‘‘\nحضرت ابن عباس رضی اللہ عنہ نے فرمایا: ایک عورت کا نام ملیکہ اور دوسری کا ام غطیف تھا۔","f2":"بعض روایات میں اس دوسری عورت کا نام ام عفیف آیا ہے۔"}],[4829,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لکھا: ہر قوم پر اس کی دیت ہے۔ اور کسی غلام کے لیے نہیں کہ وہ اپنے مالک کی اجازت کے بغیر کسی مسلمان کو اپنا ولاء دے ۱؎۔\n§وضاحت\n۱؎: یعنی اسے اپنا مالک کہے اور اپنے کو اس کی طرف منسوب کرے، اور مرنے کے بعد اپنی ولاء کی وراثت اسی کے نام کر دے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے یہ تحریر لکھوائی کہ ہر قبیلے کو اپنے لوگوں پر عائد شدہ دیتیں دینی ہوں گی، نیز کسی آزاد شدہ غلام کے لیے جائز نہیں کہ وہ اپنے مولیٰ کی اجازت کے بغیر کسی اور مسلمان کو مولیٰ بنا لے۔","f2":"(۱) عاقلہ (یعنی نسبی رشتہ دار) پر دیت ادا کرنا لازم ہے۔ (۲)’’عائد شدہ دیتیں‘‘ یعنی قتل خطا اور شبہ عمد کی دیتیں قاتل کے خاندان کو بھرنا پڑیں گی۔ اور باب کا مقصد بھی یہی ہے کہ قتل خطا یا شبہ عمد کی دیت صرف قاتل کے ذمے نہیں بلکہ پورے خاندان کی ذمے داری ہے۔ (۳) ’’اجازت کے بغیر‘‘ یہ قید ڈانٹ کے طور پر ہے ورنہ اجازت لے کر بھی کسی دوسرے کی طرف منسوب نہیں ہو سکتا جیسے کوئی شخص اپنے باپ کے علاوہ کسی دوسرے کو باپ نہیں بنا سکتا، خواہ باپ اجازت دے بھی دے۔ ویسے بھی کوئی سلیم الطبع شخص اپنے باپ کے علاوہ کسی دوسرے کو باپ نہیں بنا سکتا، خواہ باپ اجازت دے بھی دے۔ ویسے بھی کوئی سلیم الطبع شخص نہ تو رشتہ بیچتا ہے، نہ ہبہ کرتا ہے کیونکہ رشتہ بیچنے اور ہبہ کرنے کی چیز نہیں۔ مولیٰ آزاد کردہ غلام کو بھی کہتے ہیں اور آزاد کرنے والے مالک کو بھی اور ان کے مابین تعلق کو ولا کہتے ہیں جو نسبی رشتے کے بعد مضبوط رشتہ ہے جو موت سے بھی ختم نہیں ہوتا حتیٰ کہ نسبی رشتہ دار نہ ہونے کی صورت میں وراثت بھی جاری ہوتی ہے۔ ظاہر ہے کوئی شخص بھی ایسے معظم رشتے کو بدلنے کی اجازت نہیں دے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کی بابت فرمایا: [الولاء لحمۃ کلحمۃ النسب لا یباع ولا یوھب] ’’ولا بھی نسبی رشتہ داری کی طرح ہے، یہ نہ بیچی جا سکتی ہے اور نہ کسی کو ہبہ ہی کی جا سکتی ہے۔‘‘ (المستدرک للحاکم: ۴/ ۳۴۱) مطلب یہ ہوا کہ اگر کوئی اپنے آزاد کردہ غلام کو اجازت دے بھی دے تو بھی یہ تعلق ولا کسی دوسرے مسلمان کی طرف منتقل نہیں ہو سکتا۔ نہ کسی مسلمان کو لائق ہی ہے کہ وہ اسے قبول کرے۔ واللہ اعلم"}],[4830,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو علاج معالجہ کرے، اور اس سے پہلے اس کے بارے میں یہ معلوم نہیں ہے کہ وہ طبیب ہے، تو (کسی گڑبڑی کے وقت) وہ ضامن ہو گا\"۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایسے ہی (تکلفاً) طبیب بن کر علاج کرے، حالانکہ (اس سے قبل) وہ مستند طبیب نہیں تھا تو (اگر کوئی نقصان ہو جائے) وہ ضامن (ذمہ دار) ہوگا۔‘‘","f2":"(۱) محقق کتاب نے اس روایت کو سنداً ضعیف قرار دیا ہے لیکن دیگر محققین نے شواہد کی بنا پر اسے حسن قرار دیا ہے۔ شیخ محمد ناصر الدین البانی رحمہ اللہ مذکورہ حدیث پر بحث کرتے ہوئے فرماتے ہیں: [لکن الحدیث حسن بمجموع الطریقین] یعنی دونوں طریق کی وجہ سے مجموعی طور پر مذکورہ حدیث حسن بن جاتی ہے۔ تفصیل کے لیے دیکھیے: (سلسلۃ الاحادیث الصحیحۃ، حدیث: ۶۳۵) (۲) موجودہ دور میں عطائی قسم کے ڈاکٹر اور طبیب عام ہیں۔ ان طبیبوں اور ڈاکٹروں کی حوصلہ شکنی ضروری ہے۔ حکومت وقت کی یہ شرعی اور اخلاقی ذمہ داری ہے کہ وہ ایسی قانون سازی کرے کہ کوئی اناڑی ڈاکٹر اور طبیب لوگوں کی زندگی اور ان کی صحت سے نہ کھیل سکے۔ عوام کو ایسے لوگوں کی دست برد سے بچنے کی خود بھی کوشش کرنی چاہیے۔ ایسے ڈاکٹروں اور طبیبوں کے ہاتھوں اگر کوئی مر جائے تو ان کے ذمے دیت ہوگی، تاہم مستند معالجین سے دوا لینا شرعاً جائز بلکہ مستحب ہے۔ اس حدیث مبارکہ سے علاج معالجے اور دوا کی مشروعیت ثابت ہوتی ہے بشرطیکہ ڈاکٹر وطبیب مستند اور معروف ہو۔ (۳) اگر کوئی آدمی کسی ڈاکٹر یا طبیب کی بے پروائی یا عدم مہارت کی وجہ سے مر جائے تو اس پر دیت ہوگی جو اس کے نسبی رشتہ دار ادا کریں گے۔ قصاص نہیں ہوگا کیونکہ وہ مکمل طور پر قصور وار نہیں۔ آخر علاج کروانے والے کی رضا مندی ہی سے اس کا علاج ہوا، لہٰذا اناڑی شخص سے علاج کروانے میں متعلقہ شخص بھی مجرم ہے۔ طبیب اکیلا مجرم نہیں۔ (۴) مستند طبیب سے کوئی نقصان ہو جائے تو جب تک اس کی صریح غلطی ثابت نہ ہو جائے، وہ ذمہ دار نہیں ہوگا۔ صریح غلطی کی صورت میں اسے دیت بھرنی ہوگی کیونکہ یہ بھی خطا کی ذیل میں آتا ہے۔ اگر ثابت ہو جائے کہ طبیب نے عمداً نقصان پہنچایا ہے تو قصاص جاری ہوگا۔ واللہ اعلم"}],[4831,"اس سند سے بھی عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے اسی طرح مروی ہے۔","الألباني: صحيح",{"u2":"عمرو بن شعیب کے پردادا سے بالکل ایسی ہی روایت آتی ہے۔","f2":"یہ روایت بھی مجموعی طرق کی بنا پر قابل استدلال ہے۔"}],[4832,"ابورمثہ رضی اللہ عنہ کہتے ہیں کہ میں اپنے والد کے ساتھ نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، تو آپ نے فرمایا: \"یہ تمہارے ساتھ کون ہے؟\" اس نے کہا: یہ میرا بیٹا ہے، میں اس کی گواہی دیتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا قصور اس پر نہیں اور اس کا قصور تم پر نہیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی تم دونوں میں سے کوئی بھی ایک دوسرے کے جرم میں ماخوذ نہیں کیا جائے گا۔","الألباني: صحيح",{"u2":"حضرت ابو رمثہ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: میں نبی اکرم صلی اللہ علیہ وسلم کے پاس اپنے والد کے ساتھ حاضر ہوا۔ آپ نے (میرے والد سے) فرمایا: ’’یہ تیرے ساتھ کون ہے؟‘‘ انھوں نے کہا: میں گواہی دیتا ہوں، یہ میرا بیٹا ہے۔ آپ نے فرمایا: ’’خبردار! تیرے جرم کا یہ ذمہ دار نہیں اور تو اس کے جرم کا ذمہ دار نہیں۔‘‘","f2":"(۱) نبی صلی اللہ علیہ وسلم اس بات کا ہمیشہ التزام فرماتے کہ موقع محل کی مناسبت سے مسئلہ بیان فرمائیں اور کتاب وسنت کے احکام وضاحت سے بیان کر دیں، نیز نبی صلی اللہ علیہ وسلم مسئلہ اس انداز سے واضح فرماتے کہ اس میں کسی قسم کا ابہام باقی نہ رہتا بلکہ ہر شخص بآثانی سمجھ لیتا تھا۔ (۲) یہ حدیث مبارکہ اللہ تعالیٰ کے اس فرمان کی تفسیر کرتی ہے:\n{وَ لَا تَزِرُ وَازِرَۃٌ وِّزْرَ اُخْرٰی} (الفاطر ۳۵: ۱۸)\n’’کوئی بوجھ اٹھانے والا کسی دوسرے کا (قطعاً) کوئی بوجھ نہیں اٹھائے گا۔‘‘ (۳)جاہلیت میں باپ بیٹا تو ایک طرف پورے قبیلے کے افراد کو ایک دوسرے کے جرائم کا ذمہ دار سمجھا جاتا تھا۔ قبیلے کے کسی شخص نے قتل کیا ہوتا تو قبیلے کے کسی بھی شخص کو پکڑ کر قتل کر دیا جاتا اور دعویٰ کیا جاتا کہ ہم نے قصاص لے لیا ہے۔ اسلام نے اس بد رسم کو نہ صرف ختم کیا بلکہ یہ اعلان کیا کہ گناہ گار وہی ہے جس نے جرم کیا۔ سزا بھی اسے ہی دی جا سکتی ہے، کسی اور کو نہیں۔ باقی رہی یہ بات کہ پھر قتل خطا وشبہ عمد کی دیت رشتہ داروں پر کیوں پڑتی ہے؟ تو اس کا جواب یہ ہے کہ دراصل یہ اس کے ساتھ تعاون ہے کیونکہ قتل خطا کی صورت میں تو قاتل بالکل ہی بے گناہ ہوتا ہے۔ زیادہ سے زیادہ بے احتیاطی کا مجرم کہا جا سکتا ہے اور شبہ عمد میں مجرم تو ہوتا ہے کہ اس نے لڑائی کی مگر چونکہ قتل کا تو اسے تصور بھی نہیں تھا، لہٰذا وہ اتنا مجرم نہیں ہوتا کہ اس پر سو قیمتی اونٹنیوں کا بوجھ ڈال دیا جائے لیکن چونکہ کسی مسلمان کا خون رائیگاں نہیں جا سکتا، اس لیے دیت اس پر ڈال دی گئی اور اس کے ساتھ ساتھ اس کے رشتہ داروں کو اس سے تعاون کرنے کا قانونی طور پر پابند بنا دیا گیا تاکہ وہ پاؤں نہ کھینچ سکیں۔ البتہ جب قاتل مکمل قصور وار ہو، مثلاً: قتل عمد میں تو اسے خود ہی قصاص دینا ہوگا۔ اس کے کسی بھائی یا باپ کو کچھ نہیں کہا جائے گا۔ دیت ہو تو وہ بھی خود ہی بھرے گا۔"}],[4833,"ثعلبہ بن زہدم یربوعی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم انصار کے کچھ لوگوں کو خطاب کر رہے تھے، لوگوں نے کہا: اللہ کے رسول! یہ بنی ثعلبہ بن یربوع کے بیٹے ہیں، انہوں نے فلاں کو جاہلیت میں قتل کیا تھا، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اور آپ کی آواز بہت بلند تھی: سنو! کسی جان کا قصور کسی دوسری جان پر نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ثعلبہ بن زہدم یربوعی رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم انصار کے ایک گروہ میں خطاب فرما رہے تھے۔ انصار کہنے لگے: ان بنو ثعلبہ بن یربوع نے جاہلیت میں فلاں شخص کو قتل کر دیا تھا۔ نبی اکرم صلی اللہ علیہ وسلم نے آواز بلند کرتے ہوئے فرمایا: ’’آگاہ رہو! کوئی شخص کسی دوسرے کے جرم کا ذمہ دار نہیں۔‘‘","f2":"جاہلیت میں ایک فرد کے جرم کرنے پر پورے قبیلے کو مجرم سمجھ لیا جاتا تھا۔ اور جو بھی، ہتھے چڑھ جاتا، اس سے انتقام لے لیا جاتا تھا۔ آپ نے انصار کی اس بات سے اسی ذہن کی بو سونگھی کہ انھوں نے اس قبیلے کے ایک شخص کو دیکھ کر قبیلے کے کسی ایک شخص کا جرم ذکر کیا، اس لیے آپ نے واشگاف الفاظ میں تردید فرمائی۔"}],[4834,"ثعلبہ بن زہدم رضی اللہ عنہ کہتے ہیں کہ بنی ثعلبہ کے لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے، آپ خطبہ دے رہے تھے، ایک شخص بولا: اللہ کے رسول! یہ ثعلبہ بن یربوع کے بیٹے ہیں، انہوں نے صحابہ رسول میں سے فلاں کو جاہلیت میں قتل کیا تھا۔ تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کسی نفس کا قصور کسی دوسرے پر نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ثعلبہ بن زہدم رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: بنو ثعلبہ کے کچھ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے جبکہ آپ خطاب فرما رہے تھے۔ ایک دمی نے کہا: اے اللہ کے رسول! ان بنو ثعلبہ بن یربوع نے نبی صلی اللہ علیہ وسلم کے فلاں شخص کے جرم کا کوئی دوسرا شخص ذمہ دار نہیں ہوتا۔‘‘\nبنو ثعلبہ بن یربوع (قبیلے) میں سے ایک شخص سے روایت ہے کہ بنو ثعلبہ کے کچھ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے تو ایک آدمی نے کہا: اے اللہ کے رسول! ان بنو ثعلبہ بن یربوع نے نبی صلی اللہ علیہ وسلم کے فلاں صحابی کو قتل کیا تھا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شخص کسی دوسرے کے جرم کا ذمہ دار نہیں۔‘‘","f2":"آپ کا مقصد یہ تھا کہ قاتل کوئی اور ہیں اور یہ آنے والے لوگ اور ہیں۔ صرف قبیلہ ایک ہونے کی وجہ سے یہ لوگ مجرم نہیں بن سکتے۔"}],[4835,"بنی ثعلبہ بن یربوع کے ایک شخص سے روایت ہے کہ بنی ثعلبہ کے کچھ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے۔ ایک شخص نے کہا: اللہ کے رسول! یہ بنی ثعلبہ بن یربوع ہیں، انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے صحابہ میں سے فلاں کو قتل کیا تھا، آپ نے فرمایا: \"کسی نفس کا قصور کسی دوسرے نفس پر نہیں ہو گا\"۔","الألباني: صحيح"],[4836,"اسود بن ہلال (انہوں نے نبی اکرم صلی اللہ علیہ وسلم کا عہد پایا تھا) بنی ثعلبہ بن یربوع کے ایک شخص سے روایت کرتے ہیں کہ بنو ثعلبہ کے کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے ایک شخص کو ہلاک کر دیا تھا۔ تو ایک صحابی رسول نے کہا: اللہ کے رسول! یہ بنی ثعلبہ ہیں، جنہوں نے فلاں کو قتل کیا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی نفس کا قصور کسی دوسرے پر نہیں ہو گا\"۔ شعبہ کہتے ہیں: یعنی کسی کے بدلے کسی اور سے مواخذہ نہیں کیا جائے گا۔ واللہ اعلم۔","الألباني: صحيح",{"u2":"بنو ثعلبہ بن یربوع کے ایک شخص سے روایت ہے کہ بنو ثعلبہ کے کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے ایک صحابی کو قتل کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم کے ایک صحابی نے کہا: اے اللہ کے رسول! یہ بنو ثعلبہ ہیں۔ انھوں نے فلاں (صحابی) کو قتل کیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی شخص کا جرم کسی دوسرے کے نام نہیں لگ سکتا۔‘‘ (راوی حدیث) شعبہ نے کہا: یعنی کسی کو کسی اور شخص کے جرم میں گرفتار نہیں کیا جا سکتا۔ واللہ اعلم"}],[4837,"بنی ثعلبہ بن یربوع کے ایک شخص کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، آپ گفتگو فرما رہے تھے۔ ایک شخص نے کہا: اللہ کے رسول! یہ بنی ثعلبہ بن یربوع ہیں جنہوں نے فلاں کو قتل کیا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، یعنی کسی کا قصور کسی پر نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"بنو ثعلبہ بن یربوع کے ایک آدمی سے روایت ہے کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوا جبکہ آپ خطاب فرما رہے تھے۔ ایک آدمی نے کہا: اے اللہ کے رسول! ان بنو ثعلبہ بن یربوع نے فلاں شخص (صحابی رسول) کو قتل کیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نہیں۔‘‘ یعنی کسی شخص کا جرم کسی دوسرے پر نہیں ڈالا جا سکتا۔"}],[4838,"بنی یربوع کے ایک شخص کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ لوگوں سے گفتگو فرما رہے تھے، کچھ لوگوں نے آپ کے سامنے کھڑے ہو کر کہا: اللہ کے رسول! یہ بنی فلاں ہیں جنہوں نے فلاں کو قتل کیا تھا، تو آپ نے فرمایا: \"کسی نفس پر کسی کا قصور نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"بنی یربوع کے ایک آدمی نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچے تو آپ لوگوں سے خطاب فرما رہے تھے۔ (ہمیں دیکھ کر) کچھ لوگ کھڑے ہو گئے اور کہنے لگے: اے اللہ کے رسول! یہ فلاں قبیلے کے لوگ ہیں۔ انھوں نے فلاں صحابی کو قتل کیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی ایک شخص کا جرم دوسرے کے ذمے نہیں لگایا جا سکتا۔‘‘"}],[4839,"طارق محاربی رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے کہا: اللہ کے رسول! یہ بنو ثعلبہ ہیں جنہوں نے زمانہ جاہلیت میں فلاں کو قتل کیا تھا، لہٰذا آپ ہمارا بدلہ دلائیے، تو آپ نے اپنے دونوں ہاتھ اٹھائے یہاں تک کہ میں نے آپ کی بغل کی سفیدی دیکھی، آپ فرما رہے تھے: \"کسی ماں کا قصور کسی بیٹے پر نہیں ہو گا\" ایسا آپ نے دو مرتبہ کہا۔","الألباني: صحيح",{"u2":"حضرت طارق محاربی رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک آدمی نے کہا: اے اللہ کے رسول! یہ بنو ثعلبہ ہیں جنھوں نے اپنے دور جاہلیت میں فلاں کو قتل کیا تھا۔ ان سے ہمیں قصاص دلوا دیجئے۔ آپ نے اپنے ہاتھ مبارک اٹھائے حتیٰ کہ میں نے آپ کی بغلوں کی سفیدی دیکھی۔ آپ نے دو دفعہ فرمایا: ’’کسی ماں کا جرم اس کے بیٹے کے گلے نہیں پڑتا۔‘‘","f2":"آپ کا مقصد یہ تھا کہ قاتلین اور تھے اور یہ حاضرین اور ہیں، لہٰذا ان سے قصاص نہیں لیا جا سکتا۔ اگرچہ ان کا قبیلہ ایک ہے۔ شریعت میں ہر مجرم اپنے جرم کا خود جواب دہ ہے نہ کہ اس کے رشتہ دار۔"}],[4840,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس آنکھ کے بارے میں جس سے نظر نہ آتا ہو اور وہ اپنی جگہ پر ہو پھر اگر کوئی اسے پھوڑ دے یا نکال دے تو صحیح سالم آنکھ کی تہائی دیت کا فیصلہ فرمایا، اور شل ہاتھ جب کاٹ دیا جائے تو اس میں صحیح سالم ہاتھ کی دیت کے تہائی کا، اور کالے دانت میں جب وہ اکھاڑ دیا جائے تو صحیح سالم دانت کی تہائی دیت کا فیصلہ فرمایا۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ جو کانی (بے نور) آنکھ اپنی جگہ قائم ہو، اگر پھوڑ دی جائے تو آنکھ کی ایک تہائی دیت دی جائے گی۔ اور بے جان ہاتھ اگر کاٹ دیا جائے تو ہاتھ کی تہائی دیت دے دی جائے گی۔ اور وہ دانت جو سیاہ ہو چکا ہو، اکھاڑ دیا جائے تو دانت کی تہائی دیت ہوگی۔","f2":"واللہ اعلم! شاید ایک تہائی دیت اس لیے دی جا رہی ہے کہ ان اعضا کے پھوڑنے، کاٹنے اور اکھیڑنے سے ظاہری حسن وجمال جاتا رہا ہے۔ یہ اعضاء اگرچہ اپنے اصل مقصد سے خالی ہیں لیکن اپنی جگہ قائم ہونے کی وجہ سے ظاہری زیب وزینت اور حسن وجمال کا فائدہ بہرحال دے رہے ہیں۔ دور سے دیکھنے میں تو وہ شخص بے عیب ہے، لہٰذا ایسے عضو کو ضائع کر دینے سے، شریعت میں اسی عضو کی جتنی دیت مقرر ہے اس کی ایک تہائی دیت دینا ہوگی۔ صحیح آنکھ کی دیت پچاس اونٹ، صحیح ہاتھ کی دیت پچاس اونٹ اور صحیح دانت کی دیت پانچ اونٹ ہے، ان کا تہائی کسر میں آتا ہے۔ لہٰذا کسر کی جگہ قیمت لگائی جائے گی، مثلاً: آنکھ اور بے جن ہاتھ کی دیت سولہ سولہ اونٹ اور باقی دو دو اونٹوں کی کل قیمت کا ایک تہائی حصہ ہوگی۔ دو اونٹوں کی قیمت اگر تین لاکھ روپے ہو تو اس میں سے ایک لاکھ اسے دیا جائے گا۔ واللہ اعلم"}],[4841,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دانتوں میں ہر ایک کی دیت پانچ اونٹ ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دانتوں میں پانچ اونٹ ہیں۔‘‘ یعنی ہر دانت کی دیت پانچ اونٹ ہے۔"}],[4842,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمام دانت برابر ہیں، ہر ایک میں دیت پانچ پانچ اونٹ ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سب دانت (دیت میں) بورابر ہیں۔‘‘ یعنی ہر ایک میں پانچ پانچ اونٹ","f2":"(۱)کسی بھی عضو کے فائدے کا صحیح تعین بہت مشکل کام ہے کیونکہ ایک عضو کئی کام دیتا ہے، مثلاً سامنے کے دانت کاٹنے کے کام بھی آتے ہیں اور مشکل وقت میں پکڑنے کے بھی۔ اسی طرح وہ چہرے کی زینت بھی ہیں، لہٰذا یہ نہیں کہا جا سکتا کہ کھانا کھانے میں ڈاڑھوں کا زیادہ حصہ ہے اور دانتوں کا کم، اس لیے ڈاڑھوں کی دیت زیادہ ہونی چاہیے۔ گویا اعضاء کے پورے فائدے کا تعین اللہ تعالیٰ ہی جانتا ہے، لہٰذا شریعت نے جو دیت مقرر کر دی ہے، وہی صحیح ہے۔ اس میں بحث نہیں کرنی چاہیے۔ (۲)اگر کوئی شخص کسی کے تمام دانت توڑ دے تو اس کی دیت کتنی ہوگی؟ جمہور اہل علم اس بات کے قائل ہیں کہ ہر دانت کی دیت پانچ اونٹ ہوگی اس طرح کہ اگر کوئی شخص بتیس دانت توڑتا ہے تو اسے ایک سو ساٹھ (۱۶۰) اونٹ دیت دینا ہوگی۔ ڈاڑھیں اور دانت اس میں برابر ہیں۔ ان کی دلیل مذکورہ حدیث ہے۔ جبکہ اہل علم کی ایک جماعت اس بات کی قائل ہے کہ بارہ دانتوں میں پانچ پانچ اونٹ ہوں گے اور باقی بیس ڈاڑھوں میں ایک ایک اونٹ ہوگا۔ اور ایک قول یہ ہے کہ باقی ڈاڑھوں میں دو دو اونٹ ہوں گے۔ ان کی دلیل حضرت عمر رضی اللہ تعالٰی عنہ کا ایک فیصلہ ہے کہ انھوں نے ڈاڑھوں میں ایک ایک اونٹ دیت مقرر کی۔ پھر یہ بھی کہ پہلے قول پر عمل کی صورت میں دیت جان کی دیت سے بھی بڑھ جائے گی۔ ابن عبدالبر رحمہ اللہ فرماتے ہیں کہ جہاں تک حضرت عمر رضی اللہ تعالٰی عنہ کے فیصلے کا تعلق ہے تو ان سے یہ بھی مروی ہے کہ دانت اور داڑھیں برابر ہیں، اس لیے ان کا وہ فتویٰ قابل عمل ہوگا جو مرفوع حدیث کے مطابق ہے اور پھر حضرت معاویہ رضی اللہ تعالٰی عنہ سے مروی ہے کہ اگر حضرت عمر رضی اللہ تعالٰی عنہ کو مرفوع حدیث کا علم ہوتا تو وہ بھی ڈاڑھوں میں پانچ پانچ اونٹوں کا فیصلہ فرماتے۔ رہی دوسری بات کہ اس طرح دیت جان کی دیت سے بڑھ جائے گی تو یہ نہ قیاس کے خلاف ہے نہ اصول کے بلکہ اصول کے عین مطابق ہے کہ ڈاڑھوں کو دانتوں پر قیاس کیا جائے، پھر اہل علم کے نزدیک ’’اسنان‘‘ کا اطلاق، اضراس پر بھی ہوتا ہے۔ پھر کئی صورتیں اور بھی ممکن ہیں جن میں دیت جان کی دیت سے بڑھ جاتی ہے، مثلاً: کسی شخص کی آنکھ نکال دی جائے اور دونوں ہاتھ کاٹ دیے۔ جائیں تو دیت جان کی دیت سے بڑھ جائے گی۔ مزید دیکھیے: (الاستذکار، لابن عبدالبر: ۲۵/ ۱۴۶-۱۴۸)ہمارے نزدیک جمہور اہل علم کا موقف ہی راجح ہے۔ واللہ اعلم"}],[4843,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انگلیوں میں دیت دس دس اونٹ ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’انگلیوں میں (ہر انگلی کے) دس دس اونٹ ہیں۔‘‘","f2":"(۱)انگلیاں اگرچہ فائدے کے لحاظ سے مختلف ہیں۔ جو حیثیت انگوٹھے کی ہے، وہ چھنگلی کی نہیں لیکن سب ایک دوسرے کو قوت دیتی ہیں۔ پھر بعض انگلیاں زینت کا سبب ہیں۔ بعض انگلیوں کے خصوصی فائدے ہیں۔ بعض مواقع پر چھنگلی ہی کام دیتی ہے، انگوٹھا وہاں کچھ نہیں کر سکتا۔ گویا ہر انگلی کے صحیح مفاد کا حقیقی تعین ہمارے لیے بہت مشکل ہے، اس لیے اللہ علیم وخیبر اور اس کے رسول اللہ صلی اللہ علیہ وسلم نے سب انگلیوں کو برابر قرار دیا ہے۔ داہنا ہاتھ ہو یا بایاں، ہاتھ کی انگلیاں ہوں یا پاؤں کی اور چھنگلی ہو یا انگوٹھا۔ واللہ اعلم۔ (۲) ’’دس دس اونٹ‘‘ اگر کسی آدمی کے دونوں ہاتھ یا دونوں پاؤں کاٹ دیے جائیں تو وہ میت کے برابر ہے۔ لوگوں کا محتاج بن جائے گا اور اس کی زندگی موت سے بدتر ہو جائے گی، اس لیے دونوں ہاتھوں یا دونوں پاؤں کی دیت سو سو اونٹ رکھی گئی ہے۔ ایک ہاتھ یا ایک پاؤں کی دیت پچاس اونٹ ہوگی، خواہ بایاں ہی ہو کیونکہ بائیں کے بغیر دائیں کی زینت بھی کالعدم ہو جاتی ہے۔ پھر ہاتھ پاؤں میں اصل انگلیاں ہیں۔ انگلیاں نہ ہوں تو ہاتھ پاؤں اپنے اصلی مقصد سے خالی ہو جاتے ہیں، لہٰذا انگلیوں کو پورے عضو کے برابر قرار دیا گیا ہے۔ البتہ اگر پانچوں انگلیاں کاٹ دے، تب بھی دیت پچاس اونٹ، کلائی سے کاٹے تب بھی اور کہنی سے کاٹ دے تب بھی اور کندھے سے کاٹ دے، تب بھی یہی دیت ہوگی۔ واللہ اعلم"}],[4844,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انگلیاں برابر برابر ہیں، ہر ایک میں دیت دس دس اونٹ ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ تعالٰی عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’انگلیاں سب برابر ہیں۔‘‘"}],[4845,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا: \"انگلیاں سب برابر برابر ہیں، ہر ایک میں دیت دس دس اونٹ ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ تعالٰی عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ انگلیاں سب برابر ہیں۔ (ہر ایک کی دیت) دس دس اونٹ ہے۔"}],[4846,"سعید بن مسیب سے روایت ہے کہ انہیں جب وہ کتاب ملی جو عمرو بن حزم کی اولاد کے پاس تھی، جس کے بارے میں ان لوگوں نے بتایا کہ وہ انہیں رسول اللہ صلی اللہ علیہ وسلم نے لکھوائی تھی تو انہوں نے اس میں لکھا ہوا پایا کہ \"انگلیوں میں دیت دس دس اونٹ ہیں\"۔","الألباني: صحيح",{"u2":"حضرت سعید بن مسیب سے روایت ہے کہ جب میں نے وہ دستاویز دیکھی جو عمرو بن حزم رضی اللہ تعالٰی عنہ کی اولاد کے پاس تھی اور جس کے بارے میں ان کا دعویٰ تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ تحریر خود لکھوا کر ان کو دی، اس میں یہ بھی لکھا تھا کہ انگلیوں کی دیت دس دس اونٹ ہے۔"}],[4847,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"یہ اور یہ دیت میں برابر برابر ہیں\"، یعنی انگوٹھا اور چھنگلی ۱؎۔\n§وضاحت\n۱؎: یعنی: انگوٹھا اور چھنگلی دونوں کی دیت برابر :(دس اونٹ ) ہے ان میں بڑائی چھوٹائی کا لحاظ نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’یہ اور یہ برابر ہیں۔‘‘ یعنی انگوٹھا اور چھنگلی۔"}],[4848,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: یہ اور یہ دیت میں برابر برابر ہیں یعنی انگوٹھا اور چھنگلی۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ یہ اور یہ، (یعنی) انگوٹھا اور چھنگلی (دیت کے لحاظ سے) برابر ہیں۔"}],[4849,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: انگلیاں یعنی ان کی دیت دس دس اونٹ ہے۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے فرمایا: ’’سب انگلیوں کی دیت دس دس اونٹ ہے۔"}],[4850,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ فتح کیا تو آپ نے اپنے خطبے میں فرمایا: \"انگلیوں میں دیت دس دس اونٹ ہیں\"۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ مکرمہ فتح کیا تو اپنے خطبے میں ارشاد فرمایا: ’’انگلیوں کی دیت دس دس اونٹ ہے۔‘‘"}],[4851,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے خطبے میں فرمایا اور آپ اپنی پیٹھ کعبے سے ٹیکے ہوئے تھے: \"انگلیاں دیت میں برابر برابر ہیں\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب اپنے باپ سے، وہ (شعیب) اپنے دادا سے بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے خطبے میں فرمایا جب کہ آپ نے کعبہ کے ساتھ اپنی پشت کی ٹیک لگا رکھی تھی: ’’تمام انگلیاں (دیت کے لحاظ سے) برابر ہیں۔‘‘"}],[4852,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کیا تو خطبے میں فرمایا: \"ہر اس زخم میں جس میں ہڈی کھل جائے، دیت پانچ پانچ اونٹ ہیں\" ۱؎۔\n§وضاحت\n۱؎: بشرطیکہ یہ زخم چہرہ اور سر پر ہو، اگر ان کے علاوہ کسی اور جگہ میں ہے تو اس کا حکم دوسرا ہے، اور وہ یہ ہے کہ قاضی یا پنچ اپنی صوابدید سے جو فیصلہ کریں۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ مکرمہ فتح کیا تو اپنے خطبے میں ارشاد فرمایا: ’’ہڈی کو ننگا کر دینے والے زخموں میں دیت پانچ پانچ اونٹ ہے۔‘‘","f2":"اگر چمڑا اور گوشت کٹ کر ہڈی نظر آنے لگے لیکن ہڈی کا نقصان نہ ہوا ہو تو اس زخم کو عربی زبان میں موضحہ کہا جاتا ہے۔ یہ زخم معمولی ہوتا ہے اور جلدی ٹھیک ہو جاتا ہے، اس لیے اس کی دیت بھی معمولی، یعنی صرف پانچ اونٹ رکھی گئی ہے۔ اگر اس سے کم زخم ہو تو عدالت کوئی سی دیت جو پانچ اونٹ سے کم ہو، مقرر کر سکتی ہے۔ دیت انسانی عظمت کے پیش نظر رکھی گئی ہے کہ انسان خصوصاً مسلمان کو معمولی نہ سمجھا جائے۔ اگر اس کو خراش بھی آگئی تب بھی جرمانہ اور تاوان لاگو ہوگا۔ بعض فقہاء نے اس موضحہ میں پانچ اونٹ دیت رکھی ہے جو سر یا چہرے میں ہو۔ باقی جسم میں موضحہ کی دیت عدالت کی صوابدید پر موقوف کی ہے اور کہا ہے کہ وہ پانچ اونٹ سے کم ہوگی کیونکہ چہرہ فضل عضو ہے، اس لیے اس پر مارنا زیادہ جرم ہے۔ لیکن یہ تخصیص کسی حدیث میں نہیں۔"}],[4853,"عمرو بن حزم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل یمن کے لیے ایک کتاب لکھی، اس میں فرائض و سنن اور دیتوں کا ذکر کیا، وہ کتاب عمرو بن حزم کے ساتھ بھیجی، چنانچہ وہ اہل یمن کو پڑھ کر سنائی گئی، اس کا مضمون یہ تھا: نبی محمد صلی اللہ علیہ وسلم کی طرف سے شرحبیل بن عبد کلال، نعیم بن عبد کلال اور حارث بن عبد کلال کے نام جو رعین، معافر اور ہمدان کے والی تھے۔ امابعد، اس کتاب میں لکھا تھا: جو بلا وجہ کسی مومن کو مار ڈالے اور اس کا ثبوت ہو تو اس سے قصاص لیا جائے گا سوائے اس کے کہ مقتول کے اولیاء معاف کر دیں، اور ایک جان کی دیت سو اونٹ ہے۔ ناک پوری کٹ جائے تو پوری دیت ہے، اور زبان میں دیت ہے، دونوں ہونٹوں میں دیت ہے، دونوں فوطوں میں دیت ہے، عضو تناسل میں دیت ہے، پیٹھ میں دیت ہے، آنکھوں میں دیت ہے، ایک پاؤں کی دیت آدھی ہے، جو زخم دماغ تک پہنچے اس میں تہائی دیت ہے۔ جو زخم پیٹ تک پہنچے اس میں تہائی دیت ہے، اور جس زخم سے ہڈی سرک جائے اس میں دیت پندرہ اونٹ ہیں۔ اور ہاتھ پاؤں کی ہر انگلی میں دیت دس اونٹ ہیں۔ دانت میں دیت پانچ اونٹ ہیں، اس زخم میں جس سے ہڈی کھل جائے دیت پانچ اونٹ ہیں، اور مرد عورت کے بدلے قتل کیا جائے اور سونا والے لوگوں پر ہزار دینار ہیں۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) محم بن بکار بن بلال نے اس سے اختلاف کیا ہے ۱؎۔\n§وضاحت\n۱؎: محمد بن بکار نے حکم بن موسی کی مخالفت کرتے ہوئے اسے یحیی سے انہوں نے سلیمان بن ارقم سے روایت کی ہے، اور یہی صحیح ہے۔","الألباني: ضعيف",{"u2":"حضرت عمرو بن حزم رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یمن والوں کی طرف ایک تحریر لکھوا کر بھیجی جس میں فرائض وسنن اور دیت کے مسائل تھے۔ آپ نے وہ تحریر عمرو بن حزم کے ہاتھ بھیجی تھی۔ وہ اہل یمن کو پڑھ کر سنائی گئی۔ اس کی عبارت یوں تھی: ’’یہ تحریر نبی اکرم محمد صلی اللہ علیہ وسلم کی طرف سے شرحبیل بن عبد کلال، نعیم بن عبد کلال اور حارث بن عبد کلال کی طرف ہے، جو ذو رعین، معافر اور ہمدان کے سردار ہیں۔ امابعد! (اس تحریر میں بہت سی باتیں تھیں) اس تحریر میں یہ بات بھی تھی کہ جو شخص کسی مومن کو بے گناہ قتل کر دے اور گواہ موجود ہوں تو اس کو قصاصاً قتل کر دیا جائے گا الایہ کہ مقتول کے ورثاء راضی ہو جائیں۔ اور ہر انسانی جان کی دیت سو اونٹ ہے۔ اگر پوری ناک کاٹ دی جائے تو اس میں مکمل دیت (سو اونٹ) ہوگی۔ زبان پوری کاٹ دی جائے تو اس میں بھی پوری دیت ہوگی۔ دونوں ہونٹ کاٹے جانے کی صورت میں بھی پوری دیت ہو گی۔ خصیتین مکمل کاٹ دیے جائیں تو پوری دیت ہو گی۔ ذکر پورا کاٹ دیا جائے تو پوری دیت ہوگی۔ کمر (ریڑھ) کی ہڈی توڑ دی جائے تو پوری دیت ہوگی۔ دونوں آنکھیں پھوڑ یا نکال دی جائیں تو پوری دیت ہو گی۔ ایک پاؤں کی نصف دیت ہوگی۔ دماغ تک پہنچ جانے والے زخم میں تہائی دیت ہوگی۔ پیٹ کے اندر تک پہنچ جانے والے زخم میں تہائی دیت ہوگی۔ ہڈی کو توڑ دینے والے زخم کی دیت پندرہ اونٹ ہوں گے۔ ہاتھ پاؤں کی انگلیوں میں سے ہر انگلی کی دیت دس اونٹ ہوگی۔ ہر دانت کی دیت پانچ اونٹ ہوگی۔ ہدی کو ننگا کرنے والے زخم کی دیت پانچ اونٹ ہوگی۔ آدمی عورت کو قتل کرے تو اسے قتل کر دیا جائے گا۔ اگر کوئی شخص سونے کی صورت میں دیت دینا چاہے تو دیت ایک ہزار دینار ہوگی۔محمد بن بکار بن بلال نے حکم بن موسیٰ کی مخالفت کی ہے۔","f2":"(۱) محمد بن بکار بن بلال نے حکم بن موسیٰ کی مخالفت کی ہے۔ اور وہ اس طرح کہ حکم بن موسیٰ نے یہ روایت بیان کرتے ہوئے کہا ہے: حدثنا یحي بن حمزۃ عن سلیمان بن داود قال: حدثنی الزھری، جب محمد بن بکار بن بلال نے یہ روایت بیان کی تو کہا: حدثنا یحي قال حدثنا سلیمان بن ارقم قال حدثني الزھري مطلب یہ ہے کہ حکم بن موسیٰ نے یحییٰ بن حمزہ کے استاد سلیمان بن داود سے روایت بیان کی ہے جبکہ محمد بن بکار بن بلال نے یہی روایت یحییٰ کے استاد سلیمان بن ارقم سے بیان کی ہے جیسا کہ درج ذیل روایت میں بیان کیا گیا ہے۔ واللہ اعلم (۲) یہ روایت سنداً ضعیف ہے، تاہم اس کے اکثر مندرجات دیگر صحیح احادیث میں مذکور ہیں، جن میں سے بعض پہلے گزر چکے ہیں، نیز ان سے متعلقہ احکام ومسائل کی تفصیل بھی بیان ہو چکی ہے۔"}],[4854,"عمرو بن حزم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل یمن کو ایک کتاب لکھی جس میں فرائض، سنن اور دیات کا ذکر تھا۔ اسے عمرو بن حزم کے ساتھ بھیجا، چنانچہ وہ اہل یمن کو پڑھ کر سنائی گئی۔ جس کا مضمون یہ تھا۔ پھر انہوں نے اسی طرح بیان کیا، سوائے اس کے کہ انہوں نے کہا: ایک آنکھ میں دیت آدھی ہے۔ ایک ہاتھ میں آدھی دیت ہے اور ایک پاؤں میں دیت آدھی ہے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ روایت زیادہ قرین صواب ہے۔ واللہ اعلم۔ اور سلیمان بن ارقم متروک الحدیث ہیں، اس حدیث کو یونس نے زہری سے مرسلاً روایت کیا ہے ۱؎۔\n§وضاحت\n۱؎: اور یہی زیادہ صحیح ہے، ان کی روایت آگے آ رہی ہے۔","الألباني: ضعيف",{"u2":"حضرت عمرو بن حزم رضی اللہ تعالٰی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یمن والوں کی طرف ایک تحریر لکھ کر بھیجی جس میں فرائض وسنن اور دیت کے مسائل تھے۔ آپ نے یہ تحریر حضرت عمرو بن حزم کے ہاتھ بھیجی تھی اور یہ یمن والوں کو پڑھ کر سنائی گئی۔ یہ اس کا مضمون ہے۔ پھر راوی نے سابقہ روایت کی طرح بیان کیا مگر اس نے کہا: ایک آنکھ میں نصف دیت (پچاس اونٹ) ہے۔ ایک ہاتھ میں نصف دیت ہے اور ایک پاؤں میں نصف دیت ہے۔\nامام ابوعبدالرحمن (نسائی رحمہ اللہ) بیان کرتے ہیں کہ یہ روایت درست ہونے کے زیادہ قریب ہے۔ واللہ اعلم! اور سلیمان بن ارقم متروک الحدیث ہے۔ اور یہی روایت یونس (بن یزید) نے امام زہری رحمہ اللہ سے مرسلاً بیان کی ہے جیسا کہ درج ذیل روایت ہے۔"}],[4855,"محمد بن شہاب زہری کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی وہ کتاب پڑھی جو آپ نے عمرو بن حزم رضی اللہ عنہ کے لیے لکھی جب انہیں نجران کا والی بنا کر بھیجا، کتاب ابوبکر بن حزم کے پاس تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے لکھا تھا: یہ اللہ اور اس کے رسول کی طرف سے بیان ہے: «يا أيها الذين آمنوا أوفوا بالعقود» \"اے ایمان والو! عہد و پیماں پورے کرو\" (المائدہ: ۱) اور اس کے بعد کی آیات لکھیں یہاں تک کہ آپ «إن اللہ سريع الحساب» \"اللہ جلد حساب لینے والا ہے\" (المائدہ: ۴) تک پہنچے۔ پھر لکھا تھا: یہ زخموں کی کتاب ہے، ایک جان کی دیت سو اونٹ ہیں، پھر آگے اسی طرح ہے۔","الألباني: ضعيف",{"u2":"حضرت ابن شہاب (زہری) سے روایت ہے، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کی وہ تحریر پڑھی ہے جو آپ نے حضرت عمرو بن حزم رضی اللہ تعالٰی عنہ کو نجران کا حاکم بناتے وقت لکھ کر دی تھی۔ یہ تحریر حضرت ابوبکر بن حزم کے پاس تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے لکھا تھا کہ یہ اللہ تعالیٰ اور اس کے رسول کی طرف سے (احکام کا) بیان ہے: ’’اے ایمان والو! عہد پورے کرو۔‘‘ پھر آپ نے چند آیات لکھیں۔ حتی کہ یہاں تک پہنچے: {ان اللہ سریع الحساب} ’’بے شک اللہ بہت جلد حساب لینے والا ہے۔‘‘ پھر آپ نے تحریر فرمایا تھا کہ یہ زخموں وغیرہ (کی دیت) کے بارے میں ایک تحریر ہے۔ جان (ختم کر دینے کی صورت) میں دیت سو اونٹ ہوگی۔ باقی روایت حسب سابق ہے۔","f2":"(۱) نجران یمن کا ایک علاقہ تھا۔ سابقہ احادیث میں بھی یمن والوں سے مراد اہل نجران ہی ہیں۔ وہاں تین قبیلوں کے تین سردار تھے جس کی تفصیل حدیث نمبر ۴۸۵۷ میں گزر چکی ہے۔ حضرت عمرو بن حزم رضی اللہ تعالٰی عنہ کو آپ نے نگران اعلیٰ بنا کر بھیجا تھا۔ (۲) ’’چند آیات‘‘ یہ سورئہ مائدہ کی ابتدائی چار آیات ہیں۔ ان میں بھی کچھ شرعی احکام بیان ہوئے ہیں۔ (۳) آپ لکھنا نہیں جانتے تھے۔ یہ قطعی بات ہے، لہٰذا اگر کہیں لکھنے کا ذکر ہے تو مراد لکھوانا ہے۔ آپ ہمیشہ دوسروں سے لکھواتے تھے۔ (۴)یہ روایت مرسل ہے اور مرسل کے بارے میں محدثین کا صحیح موقف یہی ہے کہ یہ ضعیف ہے، تاہم عمرو بن حزم رضی اللہ تعالٰی عنہ کی کتاب قرون اولیٰ میں معروف تھی۔ اور ان کی آل کے پاس بھی رہی۔ پھر اس روایت کے متن کے شواہد بھی صحیح احادیث میں موجود ہیں، اس لیے نفس سند حدیث پر حسن یا صحیح کا حکم تو محل نظر ہے، تاہم اس میں مذکورہ احکام دیگر احادیث کی تائید کی بنا پر قابل استدلال ہیں۔"}],[4856,"زہری کہتے ہیں کہ ابوبکر بن حزم میرے پاس ایک تحریر لے آئے جو چمڑے کے ایک ٹکڑے پر رسول اللہ صلی اللہ علیہ وسلم کی طرف سے لکھی ہوئی تھی: یہ اللہ اور اس کے رسول کی طرف سے بیان ہے: اے ایمان والو! عہد و پیمان پورے کرو، پھر انہوں نے اس میں سے بعض آیات تلاوت کیں، پھر کہا: جان میں دیت سو اونٹ ہیں، آنکھ میں پچاس، ہاتھ میں پچاس، پیر میں پچاس، مغز تک پہنچنے والے زخم میں تہائی دیت، پیٹ کے اندر تک پہنچی چوٹ میں تہائی دیت اور ہڈی سرک جانے میں پندرہ اونٹنیاں ہیں۔ انگلیوں میں دس دس، دانتوں میں پانچ پانچ اور اس زخم میں جس میں ہڈی نظر آئے پانچ پانچ اونٹ ہیں۔","الألباني: ضعيف",{"u2":"حضرت زہری رحمہ اللہ سے روایت ہے، انھوں نے فرمایا: میرے پاس حضرت ابوبکر بن حزم رسول اللہ صلی اللہ علیہ وسلم کی تحریر لے کر آئے جو چمڑے کے ٹکڑے پر لکھی ہوئی تھی کہ یہ اللہ تعالیٰ اور اس کے رسول کی طرف سے (احکام کا) بیان ہے: ’’اے ایمان والو! عہد پورے کرو۔‘‘ پھر اس کے بعد کئی آیتیں پڑھیں۔ پھر کہا: (پھر لکھا تھا) کسی جان کو ختم کر دینے کی صورت میں دیت سو اونٹ ہوگی۔ ایک ہاتھ میں پچاس اونٹ ہیں۔ ایک آنکھ میں (آنکھ کی دیت) پچاس اونٹ ہیں اور ایک پاؤں کی دیت بھی پچاس اونٹ ہیں۔ دماغ تک پہنچ جانے والے زخم میں تہائی دیت ہے۔ اور پیٹ کے اندر تک پہنچ جانے والے زخم کی دیت بھی ایک تہائی ہے۔ ہڈی کو توڑ دینے والے زخم میں پندرہ اونٹ دیت ہے۔ انگلیوں کی دیت دس دس اونٹ ہے۔ دانتوں کی دیت پانچ پانچ اونٹ ہے۔ اور ہڈی کو ننگا کرنے والے زخم میں پانچ اونٹ دیت ہے۔"}],[4857,"محمد بن عمرو بن حزم کہتے ہیں کہ وہ تحریر جس میں رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن حزم رضی اللہ عنہ کے لیے دیتوں کے سلسلے میں لکھی، یہ تھی: جان میں سو اونٹ ہیں، ناک میں جب وہ جڑ سے کاٹ لی گئی ہو، سو اونٹ ہیں، مغز (گودے) تک پہنچنے والے زخم میں جان کی دیت کے اونٹوں کے تہائی ہیں۔ اسی قدر اس زخم میں ہیں جو پیٹ کے اندر تک پہنچ جائے، ہاتھ میں پچاس اونٹ ہیں۔ آنکھ میں پچاس اونٹ ہیں، پیر میں پچاس اونٹ ہیں، اور ہر ایک انگلی میں دس دس اونٹ ہیں۔ دانت میں پانچ اونٹ ہیں، اس زخم میں جس میں ہڈی کھل جائے پانچ اونٹ ہیں۔","الألباني: ضعيف",{"u2":"حضرت ابوبکر بن محمد بن عمرو بن حزم سے روایت ہے کہ وہ تحریر جو رسول اللہ صلی اللہ علیہ وسلم نے دیت کے مسائل کے بارے میں حضرت عمرو بن حزم رضی اللہ تعالٰی عنہ کو لکھ کر دی تھی۔ (یوں ہے کہ) جان (ختم کردینے کی صورت) میں سو اونٹ دیت ہے۔ اور ناک میں، جب وہ جڑ سے کاٹ دی جائے، بھی سو اونٹ دیت ہے۔ اور دماغ تک پہنچ جانے والے زخم میں کل دیت کا ایک تہائی ہے۔ اور پیٹ کے اندر پہنچ جانے والے زخم میں بھی تہائی دیت ہی ہے۔ ایک ہاتھ میں پچاس اونٹ دیت ہے۔ اور ایک آنکھ میں بھی پچاس اونٹ ہیں اور ایک پاؤں میں بھی پچاس اونٹ ہیں۔ اور (ہاتھ پاؤں کی) ہر انگلی میں دس اونٹ دیت ہے۔ ہر دانت میں پانچ اونٹ ہیں اور ہڈی کو ننگا کر دینے والے زخم میں بھی پانچ اونٹ دیت ہے۔","f2":"یہ ابوبکر بن محمد بن عمرو بن حزم وہی ہیں جن کو اوپر والی احادیث میں مختصراً ابوبکر بن حزم کہا گیا ہے،یعنی صحابی رسول حضرت عمرو بن حزم رضی اللہ تعالٰی عنہ کے پوتے جن کا اس تحریر سے اولین واسطہ پڑا تھا۔"}],[4858,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ایک اعرابی (دیہاتی) نبی اکرم صلی اللہ علیہ وسلم کے دروازے پر آیا تو دراز میں آنکھ لگا کر جھانکنے لگا، نبی اکرم صلی اللہ علیہ وسلم نے جب یہ دیکھا تو لوہا یا لکڑی لے کر اس کی آنکھ پھوڑنے کا ارادہ کیا، جب اس کی نظر پڑی تو اس نے اپنی آنکھ ہٹا لی، نبی اکرم صلی اللہ علیہ وسلم نے اس سے فرمایا:\"اگر تم اپنی آنکھ یہیں رکھتے تو میں تمہاری آنکھ پھوڑ دیتا\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے معلوم ہوتا ہے کہ کسی کے گھر کے اندر اس طرح جھانکنے والے کی آنکھ اگر گھر والا پھوڑ دے تو اس پر آنکھ پھوڑنے کی دیت واجب نہیں ہو گی۔ نیز دیکھئیے اگلی حدیث۔","الألباني: صحيح الإسناد",{"u2":"حضرت انس بن مالک رضی اللہ تعالٰی عنہ سے روایت ہے کہ ایک اعرابی نبی اکرم صلی اللہ علیہ وسلم کے دروازے کے پاس آیا اور اس نے اپنی آنکھ دروازے کے سوراخ پر لگا دی۔ نبی اکرم صلی اللہ علیہ وسلم نے اس کو دیکھ لیا اور آپ ایک تیز دھار والی چیز یا ایک (نوک دار) لکڑی لے کر اس کی طرف چلے تاکہ اس کی آنکھ پھوڑ دیں۔ جب اس نے آپ کو (آتے) دیکھا تو آنکھ پیچھے ہٹا لی۔ (پیچھے ہٹ گیا) نبی اکرم صلی اللہ علیہ وسلم نے اسے (غصے کے ساتھ) فرمایا: ’’اگر تو اسی طرح کھڑا رہتا تو میں تیری آنکھ پھوڑ دیتا۔‘‘","f2":"(۱) ’’پھوڑ دیتا‘‘ اس سے استدلال کیا گیا ہے کہ اگر کوئی اس طرح چھپ کر کسی کے گھر دیکھے تو حاکم وقت کو اطلاع کیے بغیر ہی اس کی آنکھ پھوڑی جا سکتی ہے۔ کوئی دیت یا تاوان واجب الاداء نہیں ہو گا۔ امام شافعی اور امام احمدL کا یہی خیال ہے مگر امام مالک اور امام ابوحنیفہL اس کے قائل نہیں۔ ان کا خیال ہے کہ آپ نے یہ کلمات زجراً فرمائے تھے۔ آپ کی نیت اس کی آنکھ پھوڑنے کی نہیں تھی۔ راجح یہی ہے کہ ایسے شخص کی آنکھ پھوڑنا جائز ہے اور پھوڑنے والے پر کوئی تاوان بھی نہیں ہوگا کیونکہ حدیث سے اسی موقف کی تائید ہوتی ہے۔ بے جا تاویلات سے گریز کرنا چاہیے۔ (۲)یہ حدیث اور آئندہ حدیث سابقہ باب سے اس طرح متعلق ہیں کہ ایسی حالت میں اگر آنکھ پھوڑ دی جائے تو کوئی دیت نہیں دینا پڑے گی۔ یا پھر امام صاحب نیا باب قائم کرنا بھول گئے ہیں یا یہ دونوں احادیث آئندہ باب سے متعلق ہیں جیسا کہ سنن نسائی میں کئی مقامات پر ہوا ہے۔ واللہ اعلم"}],[4859,"سہل بن سعد ساعدی رضی اللہ عنہ بیان کرتے ہیں کہ ایک شخص نے ایک سوراخ سے رسول اللہ صلی اللہ علیہ وسلم کے دروازے میں جھانکا، رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک لکڑی تھی جس سے اپنا سر کھجا رہے تھے، جب آپ نے اسے دیکھا تو فرمایا: \"اگر مجھے معلوم ہوتا کہ تو مجھے دیکھ رہا ہے تو میں تیری آنکھ میں یہ لکڑی گھونپ دیتا، نگاہ ہی کے سبب اجازت کا حکم دیا گیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت سہل بن سعد ساعدی رضی اللہ تعالٰی عنہ نے خبر دی کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کے دروازے کے سوراخ سے جھانکنے لگا۔ اور رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک نوکدار لکڑی تھی جس سے آپ اپنے سر کو کھجلی فرما رہے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم نے اس کو دیکھا تو فرمایا: ’’اگر مجھے علم ہوتا کہ تو مجھے دیکھ رہا ہے تو میں یہ لکڑی تیری آنکھ میں مار دیتا۔ اجازت لینے کا حکم تو اسی لیے دیا گیا ہے کہ نظر نہ پڑ سکے۔‘‘"}],[4860,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اجازت کے بغیر کسی کے گھر میں جھانکے، پھر وہ اس کی آنکھ پھوڑ دے، تو جھانکنے والا نہ دیت لے سکے گا نہ بدلہ\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جو شخص کسی کے گھر میں بغیر اجازت لیے جھانکنے لگے اور وہ اس کی آنکھ پھوڑ دیں تو اس کو دیت ملے گی نہ قصاص۔‘‘","f2":"(۱) امام بخاری رحمہ اللہ نے بھی اسی قسم کا باب قائم کیا ہے۔ لیکن صحیح بات یہ ہے کہ جان سے کم کا قصاص لینے کی گنجائش تو ہو سکتی ہے۔ اسی طرح مالی معاملات میں اپنا حق وصول کیا جا سکتا ہے مگر حدود وقصاص حکومت ہی کی ذمہ داری ہے ورنہ خانہ جنگی چھڑ سکتی ہے۔ اگر لوگ خو ہی قتل کرنے لگیں اور ہاتھ پاؤں کاٹنے لگیں تو امن وامان کیسے قائم رہے گا؟ ب اقی رہی یہ حدیث تو یہ صرف مذکورہ صورت کے ساتھ خاص ہوگی، یعنی اگر کوئی کسی کے گھر جھانکتا ہو تو اس کی آنکھ موقع پر پھوڑی جا سکتی ہے، تاہم اگر وہ موقع پر بچ جاتا ہے تو بعد میں اس کی آنکھ نہیں پھوڑی جائے گی۔ (۲) جب دوسرے کے گھر جھانکنا حرام ہے تو ایسے مکانات بنانا کہ ہمسائیوں کے گھر کا پردہ ہی ختم ہو جائے، بالاولیٰ حرام ہوگا۔ دور حاضر میں یہ طریقہ وبا اختیار کر چکا ہے کہ ایک شخص لاکھوں روپے خرچ کر کے مکان بناتا ہے تو دوسرا اس سے بھی اونچا کر کے بناتا ہے کہ پہلا شخص پھر نئی تعمیر پر مجبور ہو جاتا ہے۔ حکومت کو اس کے لیے ضرور قانون سازی کر کے اس پر عمل درآمد کرانا چاہیے۔"}],[4861,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اگر کوئی بلا اجازت تمہارے یہاں جھانکے پھر تم اسے پتھر پھینک کر مارو اور اس کی آنکھ پھوٹ جائے تو تم پر کوئی حرج نہیں ہو گا\"۔ اور ایک بار آپ نے فرمایا: \"کوئی گناہ نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’اگر کوئی شخص تجھے بغیر اجازت جھانکنے لگے اور تو کنکری وغیرہ مار کر اس کی آنکھ پھوڑ دے تو تجھ پر کوئی تاوان وگناہ عائد نہیں ہوگا","f2":"جھانکنے والا تب مجرم ہے اگر وہ بند دروازے سے دیکھنے کی کوشش کرے یا پردہ اٹھا کر دیکھے لیکن اگر دروازہ کھلا ہو اور اس کے سامنے کوئی پردہ نہ ہو تو پھر جھانکنے والا مجرم نہیں بلکہ گھر والے مجرم ہیں۔"}],[4862,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ وہ نماز پڑھ رہے تھے، اچانک مروان کا بیٹا ان کے آگے سے گزر رہا تھا، آپ نے اسے روکا، وہ نہیں لوٹا تو آپ نے اسے مارا، بچہ روتا ہوا نکلا اور مروان کے پاس آیا اور انہیں یہ بات بتائی، مروان نے ابو سعید خدری سے کہا: آپ نے اپنے بھتیجے کو کیوں مارا؟ انہوں نے کہا: میں نے اسے نہیں، بلکہ شیطان کو مارا ہے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"تم میں سے جب کوئی نماز میں ہو اور کوئی انسان سامنے سے گزرنے کا ارادہ کرے تو اسے طاقت بھر روکے، اگر وہ نہ مانے تو اس سے لڑے، اس لیے کہ وہ شیطان ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالٰی عنہ سے روایت ہے کہ وہ نماز پڑھ رہے تھے۔ اتنے میں حضرت مروان کا ایک بیٹا ان کے آگے سے گزرنے لگا۔ انھوں نے اس کو پیچھے دھکیلا لیکن وہ پیچھے نہ ہٹا تو انھوں نے اسے مارا۔ وہ روتا ہوا چلا گیا حتی کہ حضرت مروان کے پاس پہنچ گیا اور جا کر انھیں بتایا۔ حضرت مروان نے حضرت ابو سعید رضی اللہ تعالٰی عنہ سے کہا: آپ نے اپنے بھتیجے (میرے بیٹے) کو کیوں مارا ہے؟ انھوں نے کہا: میں نے اس کو نہیں مارا۔ میں نے تو شیطان کو مارا ہے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’جب تم میں سے کوئی شخص نماز پڑھ رہا ہو اور کوئی دوسرا شخص اس کے آگے سے گزرنا چاہے تو وہ اپنی طاقت کی حد تک اسے روکنے کی کوشش کرے۔ اگر وہ (رکنے سے) انکار کر دے (اور روکنے کے باوجود پھر بھی گزرنے پر مصر رہے) تو اس سے لڑے کیونکہ وہ شیطان ہے۔‘‘","f2":"(۱) ’’اس سے لڑے‘‘ اس کا مطلب یہ ہے کہ ممکن حد تک سامنے سے گزرنے والے شخص کو روکے، لیکن اس حد تک نہ جائے کہ اس کی اپنی نماز ہی باطل ہو جائے کیونکہ نماز کی حفاظت کے لیے تو گزرنے والے کو روک رہا ہے۔ اگر خود ہی نماز خراب کر لی تو اس کو روکنے کا فائدہ؟ اس کی صورت یہ ہوگی کہ سامنے سے گزرنے والے شخص کو ہاتھ سے روکے، اگر گزرنے والا شخص نہ رکے بلکہ سامنے سے گزرنے پر ہی مصر رہے تو اس کے سینے میں دھکا دے، یہ نہیں کہ آستینیں چڑھا کر اس سے کشتی شروع کر دے اور نماز چھوڑ کر مار کٹائی پر اتر آئے کیونکہ اس سے اس کی اپنی نماز باطل ہو جائے گی۔ (۲) امام صاحب نے اس سے استدلال فرمایا ہے کہ وہ خود بھی سزا دے سکتا ہے۔ حاکم کے پاس جانے کی کوئی ضرورت نہیں، حالانکہ کسی کو دھکا دینا یا معمولی چپت رسید کرنا نہ تو سزا کے زمرے میں آتا ہے نہ قصاص کے۔ اس سے باب پر استدلال قوی نہیں۔ ہاں یہ کہا جا سکتا ہے کہ معمولی سی کارروائی از خود بھی کر سکتا ہے جو عدالت کے اختیار میں نہیں آتی لیکن جو امور عدالتی اختیار کے تحت ہیں اور جن پر فوج داری جرم کا اطلاق ہوتا ہے، ان کا اختیار افراد کو نہیں، مثلاً: کسی کو اس طرح مارنا کہ وہ زخمی ہو جائے یا اس کی کوئی ہڈی ٹوٹ جائے یا کوئی عضو ضائع ہو جائے یا -اللہ نہ کرے- وہ مر ہی جائے۔ ایسی صورت میں وہ خود مجرم ہوگا اور سزا پائے گا۔"}],[4863,"سعید بن جبیر کہتے ہیں کہ عبدالرحمٰن بن ابزی نے مجھے حکم دیا کہ میں ابن عباس رضی اللہ عنہما سے ان دو آیتوں «ومن يقتل مؤمنا متعمدا فجزاؤه جهنم» \"جو کسی مومن کو جان بوجھ کر قتل کرے تو اس کی سزا جہنم ہے\" (النساء: ۹۳) «والذين لا يدعون مع اللہ إلها آخر ولا يقتلون النفس التي حرم اللہ إلا بالحق» \"جو لوگ اللہ کے ساتھ کسی دوسرے الٰہ کو نہیں پکارتے اور اللہ کی حرام کردہ جانوں کو ناحق قتل نہیں کرتے\" (الفرقان: ۶۷)کے متعلق سوال کروں، میں نے اس کے بارے میں ابن عباس رضی اللہ عنہما سے پوچھا تو انہوں نے کہا: اسے کسی چیز نے منسوخ نہیں کیا، اور دوسری آیت کے بارے میں انہوں نے کہا کہ یہ مشرکین کے بارے میں نازل ہوئی ۱؎\n§وضاحت\n۱؎: ابن عباس رضی اللہ عنہما کی اس رائے سے متعلق دیکھیں حاشیہ حدیث رقم :(۴۰۰۴ )۔","الألباني: صحيح",{"u2":"حضرت سعید بن جبیر بیان کرتے ہیں کہ مجھے حضرت عبدالرحمن بن ابزی رضی اللہ تعالٰی عنہ نے حکم دیا کہ میں حصرت ابن عباس رضی اللہ عنہ سے ان دو آیات کے بارے میں پوچھوں:{وَ مَنْ یَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا} ’’جو شخص کسی مومن کو جان بوجھ کر قتل کر دے، اس کی سزا جہنم ہے۔‘‘ حضرت ابن عباس رضی اللہ عنہ نے فرمایا: اس آیت کو کسی دوسری آیت نے منسوخ نہیں کیا۔ دوسری آیت یہ تھی: {وَالَّذِیْنَ لَا یَدْعُوْنَ مَعَ اللّٰہِ} ’’اور وہ لوگ جو اللہ تعالیٰ کے ساتھ کسی اور کو معبود نہیں بناتے اور کسی قابل احترام جان کو ناحق قتل نہیں کرتے۔‘‘ انھوں نے فرمایا: ’’یہ مشرکین کے بارے میں اتری ہے۔","f2":"فائدہ: تفصیل کے لیے دیکھیے احادیث: ۳۹۸۹، ۴۰۰۴، ۴۰۱۳۔"}],[4864,"سعید بن جبیر کہتے ہیں کہ اہل کوفہ میں اس آیت: «ومن يقتل مؤمنا متعمدا» کے بارے میں اختلاف ہو گیا، میں ابن عباس رضی اللہ عنہما کے پاس گیا اور ان سے پوچھا تو انہوں نے کہا: یہ آیت تو آخر میں اتری ہے، اور یہ کسی (بھی آیت) سے منسوخ نہیں ہوئی۔","الألباني: صحيح",{"u2":"حضرت سعید بن جبیر سے روایت ہے، انھوں نے فرمایا: کوفے والوں کا اس آیت کے بارے میں اختلاف ہوگیا: {وَ مَنْ یَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا} ’’جو شخص کسی مومن کو جان بوجھ کر قتل کر ے۔‘‘ میں نے حضرت ابن عباس رضی اللہ عنہ کی طرف کوچ کیا اور ان سے یہ مسئلہ پوچھا تو انھوں نے فرمایا: یہ آیت آخری نازل ہونے والی آیات میں شامل ہے۔ اس کو کسی اور آیت نے منسوخ نہیں کیا۔","f2":"(۱) ’’اختلاف ہوگیا‘‘ کہ قاتل عمد کی توبہ قبول ہو سکتی ہے یا نہیں۔ (۲)’’کوچ کیا۔‘‘ کیونکہ وہ مکہ مکرمہ میں رہتے تھے۔ (۳) ’’منسوخ نہیں کیا۔‘‘ کیونکہ یہ آیت مدنی ہے اور توبہ والی آیت مکی ہے، نیز اس میں مشرکین کا ذکر ہے، مسلمانوں کا نہیں۔"}],[4865,"سعید بن جبیر کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما سے کہا: کیا مومن کو جان بوجھ کر قتل کرنے والے کے لیے توبہ ہے؟ انہوں نے کہا: نہیں، میں انہیں سورۃ الفرقان کی یہ آیت «والذين لا يدعون مع اللہ إلها آخر ولا يقتلون النفس التي حرم اللہ إلا بالحق» پڑھ کر سنائی تو انہوں نے کہا: یہ آیت مکی ہے۔ اسے مدینے کی آیت «ومن يقتل مؤمنا متعمدا فجزاؤه جهنم» نے منسوخ کر دیا۔","الألباني: صحيح",{"u2":"حضرت سعید بن جبیر سے روایت ہے کہ میں نے حضرت ابن عباس رضی اللہ عنہ سے پوچھا کہ جو شخص کسی مومن کو جان بوجھ کر قتل کر دے، کیا اس کی توبہ قبول ہو سکتی ہے؟ انھوں نے فرمایا: نہیں۔ میں نے سورئہ فرقان والی آیت پڑھی: {وَالَّذِیْنَ لَا یَدْعُوْنَ مَعَ اللّٰہِ} ’’اور وہ لوگ جو اللہ تعالیٰ کے ساتھ کسی اور کو معبود نہیں بناتے اور کسی قابل احترام جان کو ناحق قتل نہیں کرتے۔‘‘ انھوں نے فرمایا: یہ آیت مکی دور میں اتری۔ اس کو مدینہ منورہ میں اتگرنے والی ایک آیت نے منسوخ کر دیا: {وَ مَنْ یَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا} ’’جو شخص کسی مومن کو جان بوجھ کر قتل کر ے، اس کی سزا جہنم ہے۔‘‘","f2":"’’سورہ فرقان والی آیت‘‘ اصل استدلال اگلی آیت سے ہے جس کا مفہوم یہ ہے کہ جو شخص توبہ کرے، ایمان لائے اور نیک کام شروع کر دے تو اللہ تعالیٰ ایسے لوگوں کی برائیاں نیکیوں میں بدل دیتا ہے اور اس کی توبہ قبول فرماتا ہے۔ مگر حضرت ابن عباس اسے صرف مشرکین سے خاص سمجھتے ہیں۔"}],[4866,"سالم بن ابی الجعد کہتے ہیں کہ ابن عباس رضی اللہ عنہما سے اس شخص کے بارے میں پوچھا گیا جس نے کسی مومن کو جان بوجھ کر قتل کیا پھر توبہ کی، ایمان لایا، عمل صالح کیا اور ہدایت پائی؟ تو انہوں نے کہا: اس کی توبہ کہاں قبول ہو گی؟ میں نے تمہارے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"مقتول (قیامت کے روز)قاتل کو پکڑ کر لائے گا، اس کی رگوں سے خون بہہ رہا ہو گا، وہ کہے گا: اے اللہ! اس سے پوچھ، اس نے کس جرم میں مجھے قتل کیا تھا\"، پھر ابن عباس نے کہا: یہ حکم اللہ تعالی نے نازل فرمایا اور اسے منسوخ نہیں کیا۔","الألباني: صحيح",{"u2":"حضرت سالم بن ابوالجعد رحمہ اللہ سے روایت ہے کہ حضرت ابن عباس رضی اللہ عنہ سے اس شخص کے بارے میں پوچھا گیا جو کسی مومن شخص کو جان بوجھ کر قتل کر دے۔ پھر توبہ کرے، ایمان لے آئے اور نیک عمل شروع کر دے۔ پھر راہ راست پر آجائے۔ (کیا اس کی توبہ قبول ہے؟) حضرت ابن عباس رضی اللہ عنہ نے فرمایا: ’’ اس کے لیے توبہ کی گنجائش کیسے ہو سکتی ہے؟ میں نے تمہارے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’مقتول قاتل کو پکڑ کر لائے گا جب کہ مقتول کی رگوں سے خون بہہ رہا ہوگا اور وہ کہہ رہا ہوگا: یا اللہ! اس سے پوچھ، اس نے مجھے کس بنا پر قتل کیا؟‘‘ پھر فرمایا: اللہ کی قسم! یہ (پچھلی حدیث میں مذکور) آیت اللہ نے اتاری ہے اور اسے منسوخ نہیں فرمایا۔","f2":"’’یہ آیت اللہ تعالیٰ نے اتاری ہے۔‘‘ یعنی سورئہ نساء والی آیت جس میں قاتل کی سزا ابدی جہنم بیان کی گئی ہے۔"}],[4867,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کبائر یہ ہیں: اللہ کے ساتھ غیر کو شریک کرنا، ماں باپ کی نافرمانی کرنا، (ناحق) خون کرنا اور جھوٹ بولنا\"۔\nانس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کبیرہ گناہ یہ ہیں: اللہ تعالی کے ساتھ شرک کرنا، ماں باپ کی نافرمانی کرنا، کسی کو قتل کرنا اور جھوٹ بولنا\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ تعالٰی عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’کبیرہ گناہ یہ ہیں: اللہ تعالیٰ کے ساتھ شریک بنانا، والدین کی نافرمانی کرنا، کسی (بے گناہ) کو قتل کرنا اور جھوٹی بات کرنا۔‘‘"}],[4868,"عبداللہ بن عمرو رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کبائر (بڑے گناہ) یہ ہیں: اللہ کے ساتھ شرک کرنا، ماں باپ کی نافرمانی کرنا، (ناحق) خون کرنا اور جھوٹی قسم کھانا\"۔\nعبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کبیرہ گناہ یہ ہیں: اللہ تعالی کے ساتھ شرک کرنا، ماں باپ کی نافرمانی کرنا، کسی کو قتل کرنا اور جھوٹی قسم کھانا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’بڑے بڑے گناہ یہ ہیں: اللہ تعالیٰ کے ساتھ شریک ٹھہرانا، ماں باپ کی نافرمانی کرنا، کسی بے گناہ جان کو قتل کرنا اور جھوٹی قسم کھانا۔‘‘","f2":"’’جھوٹی قسم‘‘ عربی میں یَمِین غَمُوس کا لفظ استعمال کیا گیا ہے، یعنی ایسی قسم جو قسم کھانے والے کو گناہ میں ڈبو دے۔ ظاہر ہے وہ جھوٹی ہی ہوگی جس کے ساتھ کسی کا مال ناحق حاصل کیا گیا ہو۔ قیامت کے دن ایسی قسم آگ ہی میں ڈبوئے گی۔"}],[4869,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی بندہ مومن رہتے ہوئے زنا نہیں کرتا، نہ مومن رہتے ہوئے شراب پیتا ہے، نہ مومن رہتے ہوئے چوری کرتا ہے، اور نہ ہی مومن رہتے ہوئے قتل کرتا ہے\" ۱؎۔\nكتاب قطع السارق\n§وضاحت\n۱؎: یہ اور اس طرح کی احادیث سے ان برے کاموں کی شناعت کا پتہ چلتا ہے، اور یہ وعید والی احادیث ہیں، جس میں اس طرح کے اعمال سے دور رہنے کی دعوت دی گئی ہے، اور یہ کہ اس طرح کا کام کرنے والا ایمانی کیفیت سے دور رہتا ہے، جس کی بنا پر اس طرح کے برے کام میں ملوث ہو جاتا ہے، گویا حدیث میں مومن سے اس طرح کے کاموں میں ملوث ہونے کے حالت میں ایمان چھین لیا جاتا ہے، اور وہ مومن کامل نہیں رہ پاتا، یا یہاں پر ایمان سے مراد شرم و حیاء ہے کہ اس صفت سے نکل جانے کے بعد آدمی یہ برے کام کرتا ہے، اور یہ معلوم ہے کہ حیاء ایمان ہی کا ایک شعبہ ہے۔ ایک قول یہ بھی ہے کہ مومن سے مراد وہ مومن ہے جو عذاب سے کلی طور پر مامون ہو، یہ بھی کہا گیا ہے کہ مومن سے اس حالت میں ایمان کی نفی کا معنی نہی اور ممانعت ہے، یعنی کسی شخص کا حالت ایمان میں زنا کرنا مناسب نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔جب کوئی بندہ زنا کرتا ہے تو وہ مومن نہیں رہتا۔ جب کوئی شراب پیتا ہے تو شراب پیتے وقت مومن نہیں رہتا۔ جب کوئی چوری کرتا ہے تو مومن نہیں رہتا اور قتل کرتا ہے تو بھی مومن نہیں رہتا۔‘‘","f2":"(۱) یہ حدیث مبارکہ زنا اور بدکاری کی حرمت پر صریح دلالت کرتی ہے، نیز ان امور کی حرمت پر بھی دلالت کرتی ہے جو ایمان کے منافی ہیں اور یہ اس لیے کہ زنا فواحش میں سے ہے۔ اللہ تعالیٰ کا ارشاد گرامی ہے: {وَ لَا تَقْرَبُوا الزِّنٰٓی اِنَّہٗ کَانَ فَاحِشَۃً} (بنی اسرائیل: ۳۲) (۲) اس حدیث مبارکہ سے شراب کی حرمت ثابت ہوتی ہے۔ شراب خبائث کی جڑ ہے۔ یہ رذیل اور گھٹیا حرکات پر ابھارتی ہے، نیز چوری اور قابل احترام جان کو قتل کرنے کی حرمت بھی واضح ہوتی ہے۔ (۳) ’’مومن نہیں رہتا‘‘ مقصد یہ ہے کہ یہ کام ایمان کے منافی ہیں۔ ایمان ان سے روکتا ہے۔ تو جو شخص یہ کام کرتا ہے، وہ ایمان کے تقاضے پر عمل نہیں کرتا۔ گویا۔ مومن نہیں۔ اس کا یہ مطلب ہرگز نہیں کہ وہ کافر بن جاتا ہے کیونکہ اہل سنت کا یہ مسلمہ اصول ہے کہ کسی بھی گناہ، خواہ وہ کبیرہ ہی ہو، کے ارتکاب سے مسلمان کافر نہیں بنتا۔ اور یہ اصول بہت سی آیات واحادیث سے قطعاً ثابت ہے، مثلاً: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: [مَنْ ماَتَ وَھُوَ یَعْلَمُ اِنَّہُ لَا اِلٰہَ اِلاَّ اللّٰہُ دَخَلَ الْجَنَّۃَ] ’’جو شخص اس حالت میں مرا کہ اسے لَا اِلٰہَ اِلاَّ اللّٰہُ کا علم (اس پر یقین) ہے تو وہ جنت میں داخل ہو چکا۔‘‘ (صحیح مسلم، الایمان، باب الدلیل علی ان من مات علی التوحید دخل الجنۃ قطعا، حدیث: ۲۶) اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے یہ بھی فرمایا: [مَا مِنْ عَبْدٍ قَالَ: لَا اِلٰہَ اِلاَّ اللّٰہُ، ثُمَّ مَاتَ عَلٰی ذٰلِکَ اِلَّا دَاخَلَ الْجَنَّۃَ]’’جو بندہ کہہ دے: لَا اِلٰہَ اِلاَّ اللّٰہُ پھر اسی (عقیدے) پر مر جائے تو وہ جنت میں داخل ہوگیا۔‘‘ (صحیح البخاری، اللباس، باب الثیاب البیض، حدیث: ۸۵۲۷) یہ اور اس جیسی دوسری بہت سی احادیث میں صراحت کے ساتھ یہ مذکور ہے کہ جو شخص لَا اِلٰہَ اِلاَّ اللّٰہُ یعنی کلمہ اخلاص وتوحید کی شہادت پر فوت ہو جائے اس پر جنت واجب ہو جاتی ہے۔ اللہ چاہے تو اپنی مشیت کے تحت اسے معاف فرما کر ابتداء ً جنت میں داخل فرما دے اور اگر چاہے تو کچھ مواخذے اور سزا کے بعد جنت میں داخل فرمائے۔ ایسا شخص ابدی جہنمی قطعاً نہیں جیسا کہ کافر و مشرک ہمیشہ ہمیشہ جہنم ہی میں رہیں گے۔ أَعَاذَنَا اللّٰہُ مِنْہُ۔ یا اس حدیث مبارکہ کا مفہوم یہ ہے کہ جب وہ یہ کام کر رہا ہوتا ہے، اس وقت مومن نہیں ہرتا۔ جب وہ باز آتا ہے، پھر ایمان لوٹ آتا ہے۔ یہ مطلب حضرت ابن عباس رضی اللہ عنہ راوی حدیث سے منقول ہے۔ گویا وقتی طور پر مومن نہیں رہتا۔ یا وہ عذاب سے امن میں نہیں رہتا یا مقصود یہ ہے کہ مومن کو یہ کام نہیں کرنے چاہئیں۔ گویا مقصد نہی ہے۔ (۵) ان تین روایات ۴۸۷۱ تا ۴۸۷۳ میں چونکہ قتل کو کبیرہ گناہوں میں ذکر کیا گیا ہے اور قصاص بھی قتل میں ہی ہوتا ہے، لہٰذا یہ احادیث کتاب القصاص میں آسکتی ہیں۔ (۶) قتل کا گناہ قصاص ہی سے معاف ہو سکتا ہے۔ ورثائے مقتول کی معافی سے قتل کا گناہ معاف نہیں ہوتا۔ صرف یہ ہے کہ دنیا میں قتل سے بچ جائے گا۔ آخرت میں قتل کی سزا بھگتنا ہوگی۔ الا یہ کہ مقتول کو اللہ تعالیٰ اپنی رحمت سے راضی فرما دے اور وہ آخرت میں معاف کر دے۔ وَمَا ذٰلِکَ عَلَی اللّٰہِ بِعَزِیزٍ۔"}],[4870,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی شخص ایمان رکھتے ہوئے زنا نہیں کرتا، کوئی شخص ایمان رکھتے ہوئے چوری نہیں کرتا، کوئی شخص ایمان رکھتے ہوئے شراب نہیں پیتا اور نہ ہی وہ ایمان رکھتے ہوئے کوئی ایسی بڑی لوٹ کرتا ہے جس کی طرف لوگوں کی نظریں اٹھتی ہوں\" ۱؎۔\n§وضاحت\n۱؎: دیکھئیے پچھلی حدیث کا حاشیہ :(۴۸۷۳ )۔","الألباني: صحيح",{"u2":"حضرت ابوہرہ رضی اللہ عنہ سے روایت ہے ک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب کوئی شخص چوری کرتا ہے تو وہ صاحب ایمان نہیں ہوتا۔ جب کوئی شخص شراب پیتا ہے تو وہ ایمان سے لاتعلق ہو جاتا ہے۔ اور جب کوئی شخص طاقت وقوت کے زور پر زبردست ڈاکا ڈالتا ہے کہ لوگ بے چارے دیکھتے رہ جاتے ہیں تو وہ بھی ایمان سے خالی ہوتا ہے۔‘‘","f2":"تفصیل کے لیے دیکھیئے، سابقہ حدیث: 4873"}],[4871,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب زنا کرنے والا زنا کرتا ہے تو زنا کے وقت اس کا ایمان نہیں رہتا، جب چوری کرنے والا چوری کرتا ہے تو چوری کے وقت اس کا ایمان نہیں رہتا۔ جب شراب پینے والا شراب پیتا ہے تو پیتے وقت اس کا ایمان نہیں رہتا، اس کے بعد بھی اب تک اس کی توبہ کا دروازہ کھلا ہوا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ زانی جب زنا کرتا ہے تو مو من نہیں ہوتا۔ چور جب چوری کرتا ہے تو مومن نہیں ہوتا۔ اور شرابی جب شراب پیتا ہے تو مومن نہیں ہوتا۔ البتہ توبہ پھر بھی ہو سکتی ہے۔‘‘","f2":"’’ توبہ ‘‘ یہ اشارہ ہے کہ یہاں مطقاً ایمان کی نفی مقصود نہیں بلکہ وقتی طور پر یا ایمان کامل کی نفی مقصود ہے کیونکہ یہ گناہ ہیں، کفر نہیں بشرطیکہ فاعل توبہ کرے اور واپس آجائے۔"}],[4872,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب کوئی زنا کرتا ہے تو زنا کے وقت وہ مومن نہیں رہتا، چوری کرتا ہے تو بھی مومن نہیں رہتا، شراب پیتا ہے تو بھی مومن نہیں رہتا۔ (راوی کہتا ہے) پھر چوتھی چیز بیان کی جو میں بھول گیا، جب وہ یہ سب کرتا ہے تو وہ اپنے گلے سے اسلام کا قلادہ نکال پھینکتا ہے، پھر اگر وہ توبہ کرتا ہے تو اللہ اس کی توبہ قبول کرتا ہے۔","الألباني: منكر",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ جب کوئی شخص زنا کرتا ہے تو وہ مومن نہیں ہوتا۔ اور (جب کوئی شخص) چوری کرتا ہے تو وہ مومن نہیں ہوتا اور (جب) شراب پیتا ہے تو مومن نہیں ہوتا۔ انہوں نے ایک چوتھی چیز کا بھی ذکر فرمایا لیکن میں بھول گیا۔ جو آدمی یہ کام کرتا ہے وہ اسلام کا طوق اپنی گردن سے اتار دیتا ہے لیکن اگر وہ توبہ کرے تو اللہ تعالیٰ اس کی توبہ قبول فرما لیتا ہے۔"}],[4873,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ لوگوں کے درمیان سب سے پہلے خون کا فیصلہ کیا جائے گا۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کی لعنت نازل ہو چوری کرنے والے پر، انڈا چراتا ہے تو اس کا ہاتھ کاٹا جاتا ہے اور رسی چراتا ہے تو اس کا ہاتھ کاٹا جاتا ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی تھوڑے سے مال کے لیے ہاتھ کٹنا قبول کرتا ہے اور اللہ کی دی ہوئی اس نعمت کی قدر نہیں کرتا۔","الألباني: صحيح موقوف وهو في حكم المرفوع",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اللہ تعالیٰ چور پر لعنت کرے وہ انڈا چرلیتا ہے تو اس کا ہاتھ کاٹ دیا جاتا ہے۔ رسی چرا لیتا ہے تو اس کا ہاتھ کاٹ دیا جاتا ہے۔‘‘","f2":"1۔ ’’لعنت کرے ‘‘ کہ وہ معمولی چیزوں کے بدلے اپنے قیمتی ہاتھ جس کا کوئی بدل نہیں کٹوا بیٹھتا ہے۔ دنیا میں اس سے بڑا نقصان کیا ہوگا؟ ہاتھ سے محرومی، زندگی بھر کی معذوری، بدنامی اور رسوائی جو مرتے دم تک جدا نہ ہوگی اور ان سب سے بڑھ کر اللہ تعالیٰ کی ناراضی اور ایمان سے محرومی۔ اور لعنت کیا ہوتی ہے؟ کسی شخص کا نام لے کر اس پر لعنت ڈالنا جائز نہیں، خواہ وہ کافر ہی ہو الا یہ کہ وہ کفر پر مرے یا اس کا کفر قطعی ہو۔ البتہ کسی کبیرہ گناہ کا ذکر کر کے اس کے فاعل پر (بغیر کسی کا نام لیے یا کسی کو معین کیے) لعنت ڈالی جا سکتی ہے جیسا کہ اس حدیث میں ہے۔ لعنت سب سے بڑی بددعا ہے۔ مراد اللہ تعالیٰ کی رحمت سے محرومی ہے، اسی لیے یہ کسی مومن کے بارے میں تو ہو ہی نہیں سکتی۔ کافر بھی ممکن ہے کسی وقت مسلمان ہو جائے، لہذا اس کے لیے بھی مناسب نہیں۔\n2۔ ’’ انڈا، رسی‘‘ کلام میں زور پیدا کرنے کے لیے فرمایا۔ مراد معمولی چیز ہے۔ ظاہر ہے دینا کا مال کتنا بھی قیمتی ہو انسانی ہاتھ اور انسانی شرف کے مقابلے میں معمولی ہی ہے ورنہ انڈا، رسی پر ہاتھ نہیں کاٹا جاسکتا بلکہ ہاتھ کاٹنے کے لیے چوری کی ایک حد مقرر کی گئی ہے جس کی تفصیل آئندہ آئے گی۔ ان شاء اللہ\nبعض حضرات نے بیضہ کے معنی خود کیے ہیں جو لڑائی کے وقت سر پر پہنا جاتا ہے۔ وہ قیمتی ہوتا ہے۔ اس پر ہاتھ کاٹا جاسکتا ہے اور رسی سے مراد کشتی کے رسے لیے ہیں جو بہت موٹے ہوتے ہیں۔ قیمت بھی بہت ہوتی ہے معنی تو یہ بھی بن سکتے ہیں مگر اس سے کلام کی بلاغت ختم ہو جاتی ہے۔ کلام کا مقصد تو چوری کی مذمت ہے نہ کہ ہاتھ کاٹنے کی تفصیل بیان کرنا۔ واللہ اعلم"}],[4874,"نعمان بن بشیر رضی اللہ عنہما سے روایت ہے کہ ان کے پاس قبیلہ کلاع کے کچھ لوگ مقدمہ لائے کہ کچھ بنکروں نے سامان چرا لیا ہے، انہوں نے کچھ دنوں تک ان کو قید میں رکھا پھر چھوڑ دیا، تو وہ لوگ ان کے پاس آئے اور کہا: آپ نے انہیں کوئی تکلیف پہنچائے اور مارے بغیر چھوڑ دیا؟ نعمان رضی اللہ عنہ نے کہا: تم کیا چاہتے ہو؟ کہو تو ان کو ماروں؟ اگر ان کے پاس تمہارا مال نکل آیا تو بہتر ہے ورنہ اسی قدر میں تمہاری پیٹھ پر ماروں گا؟ وہ بولے: کیا یہ آپ کا حکم ہے؟ انہوں نے کہا: یہ اللہ تعالی اور اس کے رسول صلی اللہ علیہ وسلم کا حکم ہے ۱؎۔\n§وضاحت\n۱؎: گویا شک و شبہ اور گمان کی بنیاد پر کچھ دنوں تک مجرم کو قید رکھنا کہ ممکن ہے وہ اعتراف جرم کر لے صحیح ہے، البتہ اعتراف سے پہلے اسے سزا دینا صحیح نہیں۔","الألباني: حسن",{"u2":"حضرت نعمان بن بشر رضی اللہ عنہ سے مروی ہے کہ بنو کلاع کے کچھ لوگوں نے ان کے پاس مقدمہ پیش کیا کہ کپڑا بنانے والے کچھ لوگوں نے ہمارا سامان چرا لیا ہے۔ انہوں نے ان کو چند دن قید میں رکھا، پھر چھوڑ دیا۔ مقدمہ پیش کرنے والے آئے اور کہا: آپ نے ان کو بغیر کسی مارپیٹ اور تحقیق و تفتیش (چھان بین) کے چھوڑ دیا ہے؟ حضرت نعمان نے فرمایا: تم کیا چاہتے ہو؟ اگر تم چاہو تو میں ان کو مار پیٹ کرتا ہوں۔ اگر تمہارا سامان ان سے برآمد ہو گیا تو بہتر ورنہ میں تمہاری پیٹھ پر بھی اتنی ہی مار پیٹ کروں گا۔ انہوں نے کہا: یہ آپ کا فیصلہ ہے؟ انہوں نے فرمایا: یہ اللہ تعالیٰ کا فیصلہ ہے اس کے رسول مکرم صلی اللہ علیہ وسلم کا فیصلہ ہے۔","f2":"1۔ محقق کتاب کا اس روایت کی سند کو ضعیف کہنا درست نہیں۔ ان کے نزدیک وجہ ضعف یہ ہے کہ ازہر بن عبداللہ کے حضرت نعمان بن بشیر سے سماع میں نظر ہے لیکن انہوں نے اس نظر کی کوئی دلیل ذکر نہیں کی اور اصولی بات یہ ہے کہ جب ثقہ یا صدوق راوی ’’ عن‘‘ سے بیان کرے اور وہ متہم بالتدلیس بھی نہ ہو تو اس کی روایت سماع پر محمول ہو گی۔ اور ازہر کو کسی نے مدلس نہیں کہا۔ شاید اسی لیے شیخ البانی اور دیگر محققین نے اس روایت کو حسن کہا ہے۔\n2۔ اس باب میں چور سے مراد وہ شخص ہے جس پر چوری کا الزام ہو مگر کوئی گواہ نہ ہو اور نہ مال مسروقہ اس سے برآمد ہوا ہو۔ ایسے شخص کو جس پر چور ہونے کے قرائن ہوں تحقیق کی غرض سے قید کیا جاسکتا ہے۔ اگر وہ تسلیم کر لے یا اس سے مال مسروقہ برآمد ہو جائے تو اس کو چوری کی سزا لازم ہے۔ اگر کچھ بھی ثابت نہ ہو تو اسے چھوڑ دیا جائے گا جیسا کہ حضرت نعمان بن بشر رضی اللہ عنہ کے طرز عمل سے ثابت ہوتا ہے نیز اسے مارنے کی اجازت نہیں ہوگی کیونکہ مارپیٹ سے تو کسی بھی بے گناہ سے اعتراف کروایا جاسکتا ہے۔ کسی بے گناہ یا مشکوک شخص کو مارنا ظلم ہے۔ ہاں البتہ یہ درست ہے کہ دانائی اور حکمت سے سچ اگلوایا جائے یا دھمیکوں وغیرہ سے مرعوب کر کے حقیقت معلوم کی جائے۔"}],[4875,"بہز بن حکیم کے دادا معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو ایک الزام میں قید میں رکھا۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت بہز بن حکیم اپنے باپ سے وہ (بہز) ان کے دادا (حضرت معاویہ بن حیدہ قشیری رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو ایک الزام میں قید کردیا تھا۔","f2":"تفتیش کے لیے نہ کہ بطور سزا کیونکہ جب تک ملزم کے خلاف الزام ثابت نہ ہو وہ مجرم نہیں بنتا۔ اور تفتیش کے لیے قید کے دوران میں اس پر تشدد نہیں کیا جاسکتا ورنہ تشدد کرنے والے کے خلاف قصاص کی کاروائی کی جائے گی۔"}],[4876,"بہز بن حکیم کے دادا معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو ایک الزام میں قید میں رکھا، پھر اسے رہا کر دیا۔","الألباني: حسن",{"u2":"حضرت بہز بن حکیم کے دادا (حضرت معاویہ بن حیدہ قشیری رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو کسی الزام میں قید کردیا تھا، پھر (الزام ثابت نہ ہونے پر) اسے چھوڑ دیا۔"}],[4877,"ابوامیہ مخزومی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور پکڑ کر لایا گیا جس نے اقبال جرم کر لیا لیکن اس کے پاس کوئی سامان نہیں ملا، تو آپ نے اس سے فرمایا: \"میں نہیں سمجھتا کہ تم نے چوری کی ہے\"، اس نے کہا: نہیں، میں نے چوری کی ہے۔ آپ نے فرمایا: \"اسے لے جاؤ، اس کے ہاتھ کاٹ دو، پھر اسے میرے پاس لے کر آؤ\"، لوگوں نے اس کے ہاتھ کاٹے اور اسے لے کر آپ کے پاس آئے، تو آپ نے اس سے فرمایا: \"کہو، میں اللہ تعالی سے مغفرت طلب کرتا ہوں اور توبہ کرتا ہوں\"، اس نے کہا: میں اللہ تعالی سے مغفرت طلب کرتا ہوں اور توبہ کرتا ہوں، آپ نے فرمایا: \"اے اللہ اس کی توبہ قبول کر\"۔","الألباني: ضعيف",{"u2":"حضرت ابو امیہ مخزومی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا جس نے خود بخود چوری کا اعتراف کیا تھا لیکن اس کے پاس (چوری کا) سامان نہیں ملا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: ’’ میں نہیں سمجھتا کہ تو نے چوری کی ہوگی۔‘‘ اس نے کہا: کیوں نہیں (بلکہ کی ہے۔) آپ نے فرمایا: ’’ اسے لے جاؤ اور اس کا ہاتھ کاٹ کر پھر میرے پاس لے آؤ۔‘‘ وہ اس کا ہاتھ کاٹ کر اسے واپس لائے تو آپ نے اسے فرمایا: ’’ کہہ میں اللہ تعالیٰ سے بخشش طلب کرتا ہوں اور توبہ کرتا ہوں۔‘‘ اس نے یہی الفاظ دہرا دیے۔ آپ نے فرمایا:’’ اے اللہ! اس کی توبہ قبول فرما۔‘‘"}],[4878,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے ان کی چادر چرا لی، وہ اسے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ نے ہاتھ کاٹنے کا حکم دیا، تو وہ بولے: اللہ کے رسول! میں نے اسے معاف کر دیا ہے، آپ نے فرمایا: \"ابو وہب! تم نے اسے ہمارے پاس لانے سے پہلے ہی کیوں نہ معاف کر دیا؟\" چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹ دیا ۱؎۔\n§وضاحت\n۱؎: حدیث کا خلاصہ یہ ہے کہ چور کے معاملہ کو سرکاری انتظامیہ تک پہنچ جانے سے پہلے جس کا مال چوری ہوا ہے اگر وہ معاف کر دیتا ہے تو چور کا گناہ عند اللہ توبہ سے معاف ہو سکتا ہے، اور ہاتھ نہیں کاٹا جائے گا، لیکن اگر معاملہ سرکاری ذمہ داروں :(پولیس اور عدلیہ ) تک پہنچ جاتا ہے تب صاحب مال کو معاف کر دینے کا حق بحق سرکار ختم ہو جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت صفوان بن امیہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے ان کی چادر چرالی۔ وہ اسے (چور کو) نبی کریم صلی اللہ علیہ وسلم کے پاس لے آئے تو آپ نے اس کا ہاتھ کاٹ دینے کا حکم دیا۔ انہوں نے کہا: اے اللہ کے رسول! میں نے اس کو معاف کردیا۔ آپ نے فرمایا: ’’ ابووہب! (معاف ہی کرنا تھا تو) ہمارے پاس لانے سے پہلے کیوں معاف نہ کردیا؟‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹ دیا۔","f2":"1۔قابل حد مسئلہ جب حاکم کے سامنے پیش کردیا جائے تو پھر اس کی معافی نہیں ہو سکتی۔ ہاں البتہ یہ ہوسکتا ہے کہ حاکم کے پاس لانے سے پہلے معاف کردیا جائے، تاہم شریعت نے جس چیز کو مستثنیٰ قرار دیا ہے اس میں حاکم کے پاس لانے کے بعد بھی معافی ہوسکتی ہے جیسے مقتول کے ورثاء قاتل کو بعد میں بھی معاف کرسکتے ہیں۔\n2۔ اسلامی اور شرعی سزائیں وحشیانہ قطعا نہیں بلکہ یہ تو قابل رشک معاشرے کی تشکیل کے لیے ناگزیر اور حیات بخش ہیں۔ شروعی سزاؤں کے نفاذ سے نہ صرف برائیوں کا قلع قمع ہو جاتا ہے بلکہ معاشرہ امن و سکون کا گہوارہ بن جاتا ہے۔\n3۔ ’’ کاٹ دیا‘‘ یعنی کاٹنے کا حکم دے دیا۔"}],[4879,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے ایک چادر چرائی، وہ اسے لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، آپ نے اس کا ہاتھ کاٹنے کا حکم دیا تو وہ بولے: اللہ کے رسول! میں نے اسے معاف کر دیا ہے، آپ نے فرمایا: \"ابو وہب! اسے میرے پاس لانے سے پہلے ہی تم نے کیوں نہ معاف کر دیا؟\" پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹ دیا۔","الألباني: صحيح",{"u2":"حضرت صفوان بن امیہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے (میری) چادر چرالی۔ وہ اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لے گئے۔ آپ نے اس کا ہاتھ کاٹ دینے کا حکم دیا۔ انہوں نے کہا: اے اللہ کے رسول! میں نے اسے معاف کردیا۔ آپ نے فرمایا: ’’ ابو وہب! تو نے یہ کام میرے پاس پیش کرنے سے پہلے کیوں نہ کیا؟ ‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹ دیا۔"}],[4880,"عطا بن ابی رباح کہتے ہیں کہ ایک شخص نے ایک کپڑا چرایا، اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ نے ہاتھ کاٹنے کا حکم دیا (جس کا کپڑا تھا) وہ شخص بولا: اللہ کے رسول! وہ اسی کے لیے ہے ۱؎ آپ نے فرمایا: \"ایسا اس سے پہلے ہی کیوں نہ کیا\"۔\n§وضاحت\n۱؎: یعنی میں نے اسے دے دیا، اب اسے معاف کر دیجئیے۔","الألباني: صحيح لغيره",{"u2":"حضرت عطاء بن ابو رباح سے روایت ہے کہ ایک آدمی نے کپڑا چرالیا۔ اسے پکڑ کر رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا۔ آپ نے اس کا ہاتھ کاٹنے کا حکم دے دیا۔ (کپڑے والے) آدمی نے کہا: اے اللہ کے رسول! یہ کپڑا اس کو معاف ہے۔ آپ نے فرمایا: ’’ اس وقت سے پہلے کیوں نہ (معاف) کیا۔‘‘"}],[4881,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں کہ انہوں نے بیت اللہ کا طواف کیا، پھر نماز پڑھی، پھر اپنی چادر لپیٹ کر سر کے نیچے رکھی اور سو گئے، ایک چور آیا اور ان کے سر کے نیچے سے چادر کھینچی، انہوں نے اسے پکڑ لیا اور نبی اکرم صلی اللہ علیہ وسلم کے پاس لے کر آئے اور بولے: اس نے میری چادر چرائی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے اس سے فرمایا: کیا تم نے ان کی چادر چرائی ہے؟ وہ بولا: ہاں، آپ نے (دو آدمیوں سے) فرمایا: اسے لے جاؤ اور اس کا ہاتھ کاٹ دو۔ صفوان رضی اللہ عنہ نے کہا: میرا مقصد یہ نہ تھا کہ میری چادر کے سلسلے میں اس کا ہاتھ کاٹا جائے، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"یہ کام پہلے ہی کیوں نہ کر لیا\"۔ اشعث نے عبدالملک کے برخلاف (ابن عباس رضی اللہ عنہما کی حدیث سے) اس کو روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت صفوا ن بن امیہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے بیت اللہ کا طواف کیا پھر نماز پڑھی پھر اپنی چادر تہہ کر کے اپنے سر کے نیچے رکھ لی اور سو گئے۔ ایک چور آیا اور اس نے وہ چادر ان کے سر کے نیچے سے کھسکا لی۔ انہوں نے اسے پکڑ لیا اور نبی اکرم صلی اللہ علیہ وسلم کے پاس لے آئے اور کہا: اس نے میری چادر چرائی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے اس سے پوچھا: ’’ تو نے اس کی چادر چرائی ہے؟‘‘ اس نے کہا: جی ہاں۔ آپ نے (دو آدمیوں کو) حکم دیا: ’’ اسے لے جاؤ اور اس کا ہاتھ کاٹ دو۔‘‘ صفوان نے کہا: میرا یہ مقصد نہیں تھا کہ آپ میری چادر کی بنا پر اس کا ہاتھ کاٹ دیں۔ آپ نے فرمایا: ’’ اس سے پہلے کیوں (معاف) نہ کیا۔‘‘\nاشعث بن سوار نے اس کی مخالفت کی ہے۔","f2":"1۔عکرمہ سے یہ روایت بیان کرنے والے دو راوی ہیں: ایک عبدالملک بن ابو بشیر اور دوسرے اشعث بن سوار۔ عبدالملک نے جب یہ روایت بیان کی تو کہا: حدثنی عکرمۃ عن صفوان ابن امیۃ . جب یہی روایت اشعث نے بیان کی تو کہا: عن عکرمۃ عن ابن عباس، یعنی اشعث نے اسے صفوان بن امیہ کے بجائے ابن عباس کی مسند بنایا۔ لیکن یہ یاد رہے کہ اشعث کی مخالفت، عبدالملک کی روایت کے لیے مضر نہیں کیونکہ وہ ثقہ راوی ہے جبکہ اشعث ضعیف ہے جیسا کہ امام نسائی  نے بذات خود اس کی صراحت اگلی یعنی اشعث کی بیان کردہ روایت میں کردی ہے۔ واللہ اعلم\n2۔ باب کا مقصد یہ ہے کہ چور محفوظ چیز اٹھائے تو اس کا ہاتھ کاٹا جائے گا غیر محفوظ چیز اٹھانے سے وہ چور تو بنے گا لیکن اس کا ہاتھ نہیں کاٹا جائے گا۔ بطور تعزیر کوئی اور سزا دی جاسکتی ہے۔ محفوظ سے مراد مثلا: یا تو مالک کے پاس ہو اور اس نے وہ چیز اپنے پاس سنبھال کر رکھی ہو خواہ وہ سویا ہو یا جاگتا ہو یا وہ چیز بند جگہ میں ہو، مثلا: کمرے کا دروازہ بند ہو۔ لیکن اگر کوئی چیز گھر سے باہر پڑی ہو اور مالک بھی پاس نہ ہو تو اسے غیر محفوظ تصور کیا جا ئے گا۔ یا ایسے مقام پر ہو جو سب کے لیے کھلا ہے مثلا: مسجد، دفتر، سکون وغیرہ اور دروازہ بھی کھلا ہو، مالک بھی پاس نہ ہو تو اسے بھی غیر محفوظ تصور کیا جا ئے گا۔ مذکورہ واقعے میں حضرت صفوان نے چادر تہہ کرکے سر کے نیچے رکھی ہوئی تھی۔ ظاہر ہے یہ محفوظ تھی۔ اس نے چرا کر اپنے آپ کو ہاتھ کاٹنے کا سزاوار قرار دے لیا۔"}],[4882,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ صفوان رضی اللہ عنہ مسجد میں سو رہے تھے، ان کی چادر ان کے سر کے نیچے تھی، کسی نے اسے چرایا تو وہ اٹھ گئے، اتنے میں آدمی جا چکا تھا، انہوں نے اسے پا لیا اور اسے پکڑ کر نبی اکرم صلی اللہ علیہ وسلم کے پاس لائے۔ آپ نے اس کے ہاتھ کاٹنے کا حکم دیا، صفوان رضی اللہ عنہ نے کہا: اللہ کے رسول! میری چادر اس قیمت کی نہ تھی کہ کسی شخص کا ہاتھ کاٹا جائے ۱؎۔ آپ نے فرمایا: \"تو ہمارے پاس لانے سے پہلے ہی ایسا کیوں نہ کر لیا\"۔ ابوعبدالرحمٰن نسائی کہتے ہیں: اشعث ضعیف ہیں۔\n§وضاحت\n۱؎: یہ ان کا اپنا ظن و گمان تھا ورنہ چادر کی قیمت چوری کے نصاب کی حد سے متجاوز تھی۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا: حضرت صفوان مسجد میں سوئے ہوئے تھے جبکہ ان کی چادر ان کے (سرکے) نیچے تھی۔ وہ چرا لی گئی۔ ان کو جاگ آئی تو چور جاچکا تھا۔ انہوں نے بھاگ کر اسے پکڑ لیا اور نبی اکرم صلی اللہ علیہ وسلم کے پاس لے آئے۔ آپ نے چور کا ہاتھ کاٹنے کا حکم دے دیا۔ صفوان نے کہا: اے اللہ کے رسول! میری چادر اتنی قیمتی تو نہیں کہ اس کی بنا پر کسی آدمی کا ہاتھ کاٹ دیا جائے؟ آپ نے فرمایا:’’ یہ بات اس کو میرے پاس لانے سے پہلے کیوں نہ سوچی۔‘‘\nابو عبدالرحمن (امام نسائی رحمہ اللہ) نے فرمایا: (اس روایت کا راوی) اشعث ضعیف ہے۔ (مقصد یہ ہے کہ حضرت ابن عباس کا ذکر اس روایت میں صحیح نہیں)","f2":"’’ اتنی قیمتی‘‘ قیمتی تو تھی یعنی چوری کے نصاب کو پہنچ جاتی تھی اسی لیے تو رسول اللہ صلی اللہ علیہ وسلم نے ہاتھ کاٹنے کا حکم دیا مگر ان کا خیال تھا کہ ہاتھ تو بہت قیمتی ہے۔ اس کی دیت پچاس اونٹ ہے۔ اسے تیس درہم کی چوری کے عوض نہیں کاٹنا چاہیے۔ لیکن اصل بات یہ ہے کہ یہ ہاتھ اس وقت قیمتی ہے جب بے گناہ ہو۔ جب اس سے چوری جیسا گناہ کرلیا گیا تو اب یہ قیمتی نہ رہا۔ اب یہ چند درہم کے بدلے کاٹ دیا جائے گا۔ چوری کس قدر ذلیل کام ہے کہ پچاس اونٹ کی قیمت رکھنے والی چیز کو تین یا زیادہ سے زیادہ دس درہم کی بنا دیا۔"}],[4883,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں کہ میں مسجد میں اپنی ایک چادر پر سو رہا تھا، جس کی قیمت تیس درہم تھی، اتنے میں ایک شخص آیا اور مجھ سے چادر اچک لے گیا، پھر وہ آدمی پکڑا گیا اور اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ نے حکم دیا کہ اس کا ہاتھ کاٹا جائے، تو میں نے آپ کے پاس آ کر عرض کیا: کیا آپ اس کا ہاتھ صرف تیس درہم کی وجہ سے کاٹ دیں گے؟ میں چادر اس کے ہاتھ بیچ دیتا ہوں اور اس کی قیمت ادھار کر لیتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا تم نے اسے ہمارے پاس لانے سے پہلے کیوں نہیں کیا\"۔","الألباني: منكر",{"u2":"حضرت صفوان بن امیہ رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا: میں مسجد میں اپنی منقش (دھاری دار) چادر پر سویا ہو اتھا جس کی قیمت تیس درہم تھی۔ ایک ٖآدمی آیا اور اسے کھسکا لے گیا۔ وہ آدمی پکڑا گیا اور نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا۔ آپ نے اس کا ہاتھ کاٹنے کا حکم دے دیا۔ میں آپ کے پاس آیا اور عرض کی: آپ صرف تیس درہم کے بدلے اس کا ہاتھ کاٹ رہے ہیں؟ میں یہ چادر اس کو بیچ دیتا ہوں۔ قیمت اس سے بعد میں لے لوں گا۔ آپ نے فرمایا: ’’ یہ سب کچھ میرے پاس مقدمہ لانے سے پہلے کیوں نہ کیا؟‘‘"}],[4884,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں کہ ایک چادر ان کے سر کے نیچے سے چوری ہو گئی اور وہ مسجد نبوی میں سو رہے تھے، انہوں نے چور پکڑ لیا اور اسے لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، آپ نے اس کا ہاتھ کاٹنے کا حکم دیا تو صفوان رضی اللہ عنہ نے کہا: کیا آپ اس کا ہاتھ کاٹیں گے؟ آپ نے فرمایا: \"تو پھر اسے میرے پاس لانے سے پہلے ہی کیوں نہ چھوڑ دیا\"۔","الألباني: صحيح",{"u2":"حضرت صفوان بن امیہ رضی اللہ عنہ سے روایت ہے کہ میرے سر کے نیچے سے ایک دھاری دار چادر چرا لی گئی جبکہ وہ نبی اکرم صلی اللہ علیہ وسلم کی مسجد میں سوئے ہوئے تھے۔ وہ چور کو پکڑ کر نبی اکرم صلی اللہ علیہ وسلم کے پاس لے آئے۔ آپ نے اس کا ہاتھ کاٹنے کا حکم دے دیا۔ صفوان نے کہا: آپ (اتنی چیز میں) اس کا ہاتھ کاٹ دیں گے؟ (میں اسے معاف کرتا ہوں)۔ آپ نے فرمایا: ’’ تو نے اسے میرے پاس لانے سے پہلے کیوں نہ چھوڑ دیا؟‘‘"}],[4885,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حدود کو میرے پاس آنے سے پہلے معاف کر دیا کرو، کیونکہ جس حد کا مقدمہ میرے پاس آیا، اس میں حد لازم ہو گئی\"۔","الألباني: صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ (ملزموں کو) میرے پاس پیش کرنے سے پہلے حدود معاف کردیا کرو۔ میرے پاس کوئی حد والا مقدمہ آیا تو حد لازماً لگے گی۔‘‘","f2":"1۔یہ حدیث صریح اور واضح دلیل ہے کہ حاکم وقت اور عدالت کے سامنے پیش ہونے اور ملزم کو پیش کرنے سے پہلے باہم حدود میں معاف کرنا مستحب اور پسندیدہ عمل ہے۔ بالخصوص اگر جرم کرنے والا کوئی ایسا عزت دار اور معاشرے کا معزز فرد ہو جو نہ تو عادی مجرم ہو اور نہ اپنے کیے پر فخر کا اظہار کرے بلکہ اپنی غلطی پر نادم اور شرمندہ ہو تو اسے معاف کردینا ہی بہتر اور افضل ہے۔\n2۔ عینی شاہدین یعنی موقع کے گواہوں کے لیے یہ قطعا ضروری نہیں کہ وہ ضرور عدالت میں جاکر جو کچھ انہوں نے دیکھا ہے اس کی بابت گواہی دیں بلکہ ایک مسلمان کے عیب کی پردہ پوشی مستحب اور شرعا پسندیدہ عمل ہے۔ اس کے متعلق بہت سی احادیث موجود ہیں۔ ہاں اگر معاملہ عدالت میں یا حاکم کے پاس چلا جائے تو پھر حق سچ کی گواہی دینا ضروری ہوتا ہے۔ اس صورت میں حق کی گواہی چھپانا کبیرہ گناہ ہے۔\n3۔ ’’ حدود معاف کرو‘‘ مثلا: چور کو عدالت میں پیش کیے بغیر چھوڑ دو یا زانی کے خلاف گواہ عدالت میں نہ جائیں یا شرابی کا کیس عدالت میں نہ لے جایا جائے۔ ان صورتوں میں عدالت زبردستی کیس اپنے ہاتھ میں نہیں لے گی۔ لیکن جو کیس عدالت میں آگیا ملزم نے اعتراف کرلیا یا گواہوں نے گواہی دے دی یعنی جرم ثابت ہو گیا تو پھر عدالت کےلیے حد قائم کرنا لازم ہوگا۔ وہ معاف نہیں کرسکتی۔ عدالت میں جرم کے ثبوت کے بعد متعلقہ اشخصا بھی معافی نہیں دے سکتے۔ البتہ قصاص کا مسئلہ اس ضابطے سے مستثنیٰ ہے۔ قتل کا مقدمہ عدالت میں چلا جائے گواہ بھگت جائیں یا ملزم اعتراف کر لے حتیٰ کہ عدالت سزائے موت بھی سنا دے تب بھی مقتول کے ورثاء معاف کرسکتے ہیں حتیٰ کہ پھانسی کا پھندہ قاتل کے گلے میں پڑا ہو تب بھی اسے معاف کیا جاسکتا ہے۔ لیکن عدالت کسی بھی مرحلے پر یا حاکم وقت کسی بھی اپیل پر قاتل کو معاف نہیں کرسکتا۔"}],[4886,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حدود کو آپس ہی میں معاف کر دو، جب حد کی کوئی چیز میرے پاس پہنچ گئی تو وہ واجب ہو گئی\" ۱؎۔\n§وضاحت\n۱؎: یعنی اسے معاف نہیں کیا جا سکتا۔","الألباني: حسن",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب تک بات تم میں ہے، تم حدود معاف کرسکتے ہو لیکن اگر کوئی حد والا مقدمہ مجھ تک پہنچ گیا تو (میرے لیے) حد لگانا واجب اور لازم ہو جائے گا۔‘‘","f2":"مذکورہ بالا دونوں روایات کو محقق کتاب نے ابن جریج کی تدلیس کی وجہ سے سندا ضعیف قرار دیا ہے جبکہ دیگر محققین نے کہا کہ یہ روایات شواہد کی بنا پر صحیح ہیں۔سلسلہ صحیحہ میں شیخ البانی رحمہ اللہ نے ابن مسعود رضی اللہ عنہ کی روایت ذکر کی ہے جو اسی مفہوم کی ہے۔ دیکھیے: (سلسلۃ الاحادیث الصحیحۃ، حدیث: 1638) اس لیے راجح بات یہی ہے کہ یہ روایات قابل استدلال ہیں۔ واللہ اعلم"}],[4887,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ قبیلہ مخزوم کی ایک عورت لوگوں کا سامان مانگ لیتی تھی، پھر مکر جاتی تھی، تو نبی اکرم صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹنے کا حکم دیا ۱؎۔\n§وضاحت\n۱؎: عاریت :(روزمرہ برتے جانے والے سامانوں کی منگنی ) کے انکار کر دینے پر نبی اکرم صلی اللہ علیہ وسلم نے مخزومیہ عورت کا ہاتھ کاٹ دیا، اس سے بعض علماء عاریت کے انکار کو بھی چوری مانتے ہیں۔ :(اس حدیث کی بعض روایات کے الفاظ سے واضح ہوتا ہے کہ آپ صلی اللہ علیہ وسلم نے اس فعل کو چوری سے تعبیر فرمایا ) اور بعض علماء کہتے ہیں کہ عاریت کے انکار پر آپ نے اس لیے ہاتھ کاٹا کہ ایسا نہ ہو کہ عاریت دینے کا چلن ہی سماج اور معاشرے سے ختم ہو جائے تو لوگ پریشانی میں مبتلا ہو جائیں۔ بہرحال عاریت کے انکار پر ہاتھ کاٹنا ثابت ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ ایک مخزومی عروت لوگوں سے گھریلو ساما ن استعمال کے لیے لیا کرتی تھی پھر بعد میں مکر جاتی تھی۔ نبی صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹ دینے کا حکم دیا۔","f2":"اس حدیث سے معلوم ہوتا ہے کہ اگر کوئی شخص عاریتا کوئی چیز لے کر انکار کردے جب کہ گواہ موجود ہوں تو اسے چور سمجھ کر اس کا ہاتھ کاٹ دیا جائے گا۔ یہ امام احمد اور اسحاق وغیرہ کا موقف ہے کیونکہ یہ بھی چوری کی ایک قسم ہے بلکہ اس کا نقصان معاشرے کے لیے زیادہ ہے کیونکہ اگر اس پر سزا نہ دی جائے تو لوگ عاریتا چیزیں دینے سے انکار کردیں گے جس سے غریب لوگوں کو مشکلات کا سامنا کرنا پڑے گا۔ پھر اس کی چوری کے ساتھ مشابہت ہے کہ یہ بھی حیلے کے ساتھ لوگوں کے مال محفوظ کو اڑانا ہے اور چوری میں بھی یہی کچھ ہوتا ہے، لہذا اس جرم پر بھی چوری والی سزا دی جائے گی۔ اور رسول اللہ صلی اللہ علیہ وسلم شرعا اس بات کے مجاز ہیں کہ شرعی اطلاقات کی وضاحت فرمائیں اس لیے بعض محدثین اس جرم پر بھی ہاتھ کاٹنے کے قائل ہیں جب کہ جمہور اہل علم اس کے قائل نہیں بلکہ صرف چوری پر قطع ید نافذ کرتے ہیں۔ اس حدیث کی تاویل وہ اس طرح کرتے ہیں کہ آپ نے اس جرم پر اس کا ہاتھ نہیں کاٹا تھا بلکہ چوری پر کاٹا تھا جیسا کہ بعض روایات میں وضاحت ہے کہ اس نے چوری کی تھی۔ یہ جرم تو اس کی مزید مذمت کرنے کے لیے ذکر کیا گیا ہے۔ چونکہ دیگر روایات وطرق میں بصراحت چوری پر قطع کا ذکر موجود ہے پھر واقعہ بھی ایک دفعہ ہی پیش آیا ہے اس لیے راجح موقف جمہور ہی کا ہے کہ قطع ید صرف چوری پر ہوگا۔ واللہ اعلم"}],[4888,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ قبیلہ مخزوم کی ایک عورت پڑوسی عورتوں (کی گواہیوں) کے ذریعہ سامان مانگتی، پھر مکر جاتی تھی، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، انہوں نے فرمایا: ایک مخزومی عورت اپنی پروسنوں کی معرفت چیزیں ادھار لے لیا کرتی تھی، پھر بعد میں مکر جایا کرتی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کا ہاتھ کاٹ دینے کا حکم فرمایا۔"}],[4889,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک عورت لوگوں کے زیورات مانگ لیتی پھر اسے رکھ لیتی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس عورت کو اللہ اور اس کے رسول سے توبہ کرنی چاہیئے، اور جو کچھ لیتی ہے اسے لوگوں کو لوٹا دینا چاہیئے\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلال کھڑے ہو اور اس کا ہاتھ پکڑ کر کاٹ دو\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عمر رضی اللہ عنہما سے روایت ہے کہ ایک عورت لوگوں کے زیورات مانگ کر لے جایا کرتی تھی اور پھر واپس کرنے سے انکار کردیتی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ یہ عورت اللہ اور اس کے رسول کے سامنے علانیہ توبہ کرے اور جو کچھ اس نے لوگوں سے لیا ہے ان کو واپس کرے۔‘‘ (لیکن وہ عورت نہ مانی تو) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ بلال! اٹھو اور اس کا ہاتھ کاٹ دو۔‘‘","f2":"’’ واپس کردے‘‘ اس جرم میں گنجائش ہے کہ اگر وہ مجرم بعد میں چیز واپس کردے تو اسے معافی مل جائے گی البتہ چوری میں یہ گنجائش نہیں بلکہ جرم ثابت ہونے کے بعد کسی بھی صورت میں معافی نہیں ہو سکتی اور ہاتھ کاٹا جائے گا۔"}],[4890,"نافع کہتے ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں زیورات مانگ لیتی تھی، چنانچہ اس نے زیور مانگا اور اسے اکٹھا کر کے رکھ لیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس عورت کو توبہ کرنی چاہیئے اور جو کچھ اس کے پاس ہے، اسے ادا کرنا چاہیئے، کئی بار (کہا) لیکن اس نے ایسا نہیں کیا تو آپ نے حکم دیا اور اس کا ہاتھ کاٹ دیا گیا\"۔","الألباني: صحيح",{"u2":"حضرت نافع رحمہ اللہ سے روایت ہے کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں استعمال کے لیے زیورات مانگ لیا کرتی تھی۔ اس طرح اس نے کافی زیورات اکٹھے کرلیے۔ پھر وہ اپنے پاس رکھ لیے (اور واپس کرنے سے مکر گئی) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اس عورت کو چاہیے کہ وہ توبہ کرے اور جو کچھ اس نے لیا ہے واپس کرے۔‘‘ آپ نے کئی دفعہ فرمایا مگر وہ نہ مانی۔ آخر اس کا ہاتھ کاٹ دیا گیا۔"}],[4891,"جابر رضی اللہ عنہ کہتے ہیں کہ بنی مخزوم کی ایک عورت نے چوری کی، چنانچہ اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا، اس نے ام المؤمنین ام سلمہ رضی اللہ عنہا کی پناہ لی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اگر فاطمہ بنت محمد بھی ہوتی تو میں اس کا ہاتھ کاٹ دیتا\"، چنانچہ اس کا ہاتھ کاٹ دیا گیا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ بنو مخزوم کی ایک عورت نے چوری کرلی۔ اے نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا۔ اس نے حضرت ام سلمہ رضی اللہ عنہا کے ہاں پناہ حاصل کرلی۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ اگر (چوری کرنے والی) فاطمہ بنت محمد (صلی اللہ علیہ وسلم) بھی ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘ پھر اس عورت کا ہاتھ کاٹ دیا گیا۔","f2":"۔’’ فاطمہ بنت محمد‘‘ یہ آپ نے کلام میں زور پیدا کرنے کے لیے فرمایا ورنہ کہاں خانوادہ رسول اور کہاں چوری؟ معاذاللہ۔ اتفاقا اس چور عورت کا نام بھی فاطمہ تھا۔ فاطمہ بنت اسود بن عبدالاسد۔\n2۔ ظاہرا تو یہ اور سابقہ روایات ایک ہی واقعہ بیان کرتی ہیں۔ اس صورت میں چوری سے مراد عاریہ کی واپسی سے انکار ہی ہے کیونکہ عاریہ کی واپسی سے انکار کو مجازا چوری کہا جاسکتا ہے مگر چوری کو کسی بھی لحاظ سے عاریہ کی واپسی سے انکار نہیں کہا جاسکتا۔ یا پھر الگ واقعہ ماننا ہوگا مگر یہ مشکل ہے۔ محدثین نے اسے ایک ہی واقعہ قرار دیا ہے۔"}],[4892,"سعید بن مسیب کہتے ہیں کہ بنی مخزوم کی ایک عورت نے کچھ لوگوں (کی گواہیوں) کے ذریعہ زیورات مانگے پھر ان سے مکر گئی، تو نبی اکرم صلی اللہ علیہ وسلم نے حکم دیا اور اس کا ہاتھ کاٹ دیا گیا۔","الألباني: صحيح",{"u2":"حضرت سعید بن مسیب سے مروی ہے کہ بنو مخزوم کی ایک عورت نے دوسرے لوگوں کے واسطے سے زیور استعمال کے لیے لیا، بعد میں مکر گئی تو رسول اللہ صلی اللہ علیہ وسلم کے حکم سے اس کا ہاتھ کاٹ دیا گیا۔"}],[4893,"اس سند سے بھی سعید بن مسیب سے اسی طرح سے مروی ہے۔","الألباني: صحيح",{"u2":"أَخْبَرَنَا مُحَمَّدُ بْنُ الْمُثَنَّی قَالَ حَدَّثَنَا مُعَاذُ بْنُ ہِشَامٍ قَالَ حَدَّثَنِی أَبِی عَنْ قَتَادَۃَ عَنْ سَعِیدِ بْنِ یَزِیدَ عَنْ سَعِیدِ بْنِ الْمُسَیَّبِ أَنَّ امْرَأَۃً مِنْ بَنِی مَخْزُومٍ اسْتَعَارَتْ حُلِیًّا عَلَی لِسَانِ أُنَاسٍ فَجَحَدَتْہَا فَأَمَرَ بِہَا النَّبِیُّ صَلَّی اللَّہُ عَلَیْہِ وَسَلَّمَ فَقُطِعَتْ أَخْبَرَنَا مُحَمَّدُ بْنُ الْمُثَنَّی قَالَ حَدَّثَنَا عَبْدُ الصَّمَدِ قَالَ حَدَّثَنَا ہَمَّامٌ قَالَ حَدَّثَنَا قَتَادَۃُ عَنْ دَاوُدَ بْنِ أَبِی عَاصِمٍ أَنَّ سَعِیدَ بْنَ الْمُسَیَّبِ حَدَّثَہُ نَحْوَہُ"}],[4894,"سفیان بن عیینہ بیان کرتے ہیں کہ ایک مخزومی عورت سامان مانگ لیتی پھر مکر جاتی۔ یہ بات رسول اللہ صلی اللہ علیہ وسلم کو معلوم ہوئی، اس سلسلے میں گفتگو ہوئی تو آپ نے فرمایا: \"اگر فاطمہ بنت محمد ہوتی تو میں اس کا بھی ہاتھ کاٹتا\"۔ سفیان سے کہا گیا: اسے کس نے بیان کیا؟ تو انہوں نے کہا: ایوب بن موسی نے، انہوں نے زہری سے، انہوں نے عروہ سے، عروہ نے عائشہ رضی اللہ عنہا سے روایت کیا۔","الألباني: صحيح",{"u2":"حضرت سفیان سے مروی ہے کہ ایک مخزومی عورت لوگوں سے سامان مانگ کرلے جاتی، پھر (واپس کرنے سے) مکر جایا کرتی تھی۔ اسے رسول اللہ صلی اللہ علیہ وسلم کی عدالت میں پیش کیا گیا، نیز اس کے بارے میں (معافی کی) سفارش بھی کی گئی۔ آپ نے فرمایا: ’’ اگر (میری بیٹی) فاطمہ ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔\nسفیان سے پوچھا گیا: (یہ روایت) کس نے بیان کی ہے؟ انہوں نے کہا: ایوب بن موسیٰ نے زہری سے انہوں نے عروہ سے انہوں نے عائشہ سے۔ ان شاء اللہ عزوجل"}],[4895,"ام المؤمنین عائشہ رضی اللہ عنہا کہتے ہیں کہ ایک عورت نے چوری کی چنانچہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس لائی گئی، لوگوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم سے اسامہ کے سوا کون (اس کی سفارش سے متعلق گفتگو کرنے کی) ہمت کر سکتا ہے؟ چنانچہ اسامہ رضی اللہ عنہ سے لوگوں نے کہا تو انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اس سلسلے میں بات چیت کی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسامہ! بنی اسرائیل صرف اس وجہ سے ہلاک و برباد ہوئے کہ جب ان میں سے کوئی اونچے طبقے کا آدمی کسی حد کا مستحق ہوتا تو اسے چھوڑ دیتے اور اس پر حد نافذ نہیں کرتے اور جب کوئی نچلے طبقے کا آدمی کسی حد کا مستحق ہوتا تو اسے نافذ کرتے، اگر(اس جگہ) فاطمہ بنت محمد بھی ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک عورت نے چوری کرلی۔ اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا۔ لوگوں (عورت کے رشتے داروں) نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے سامنے سفارش کی کون جرات کرسکتا ہے؟ اسامہ شاید کرے۔ انہوں نے حضرت اسامہ رضی اللہ عنہ سے کہا۔ اسامہ نے رسول اللہ صلی اللہ علیہ وسلم سے (اس عورت کی معافی کی) سفارش کر دی۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ اسامہ! بنو اسرائیل اسی لیے ہلاک ہوئے تھے کہ جب ان میں کوئی بلند مرتبہ شخص کوئی حد پھلانگ لیتا تو اسے چھوڑ دیتے اور حد نہ لگاتے۔ اور جب کوئی کم مرتبہ شخص غلطی کر بیٹھتا تو اس پر حد قائم کردیتے۔ اگر اس کی بجائے محمد(صلی اللہ علیہ وسلم) کی بیٹی فاطمہ ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘","f2":"’’ اسامہ شاید کرے‘‘ انہوں نے یہ بات اس وجہ سے کہی کہ حضرت اسامہ رضی اللہ عنہ آپ کے متنبی حضرت زید بن حارثہ رضی اللہ عنہما کے بیٹے تھے، اس لیے آپ کو ان سے شدید محبت تھی لیکن اللہ تعالیٰ کی محبت پر غالب نہ تھی۔ تبھی تو آپ نے ان کی سفارش نہ مانی۔"}],[4896,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا ۱؎ آپ نے اس کا ہاتھ کاٹ دیا، انہوں نے کہا: ہمیں آپ سے ایسی امید نہ تھی، آپ نے فرمایا: \"اگر فاطمہ ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا\"۔\n§وضاحت\n۱؎: مراد وہی مخزومیہ عورت ہے جس کا تذکرہ پچھلی اور اگلی حدیثوں میں ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے انہوں نے فرمایا: نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا۔ آپ نے اس کا ہاتھ کاٹ دیا۔ لوگ کہنے لگے: ہمیں یہ خیال نہ تھا کہ آپ اس کو اس حد تک سزا دیں گے۔ آپ نے فرمایا: ’’ اگر (اس کے بجائے) فاطمہ ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘","f2":"شیخ البانی رحمہ اللہ اور دیگر محققین نے اس روایت کی سند کورزق اللہ کی وجہ سے ضعیف کہا ہے کیونکہ اس کا متن منکر ہے۔ باقی تمام روایات میں مرد کی بجائے عورت کا ذکر ہے اور یہی راجح ہے۔ جو عورت تہی نہ کہ مرد، مرد کا ذکر راوی حدیث رزق اللہ کا وہم ہے۔"}],[4897,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں چوری کی، ان لوگوں نے کہا: اس سلسلے میں ہم آپ سے بات نہیں کر سکتے، آپ سے صرف آپ کے محبوب اسامہ ہی بات کر سکتے۔ چنانچہ انہوں نے آپ سے اس سلسلے میں عرض کیا تو آپ نے فرمایا: \"اسامہ! ٹھہرو، بنی اسرائیل انہی جیسی چیزوں سے ہلاک ہوئے، جب ان میں کوئی اونچے طبقے کا آدمی چوری کرتا تو اسے چھوڑ دیتے اور اگر ان میں کوئی نچلے طبقے کا آدمی چوری کرتا تو اس کا ہاتھ کاٹ دیتے۔ اگر اس جگہ فاطمہ بنت محمد بھی ہوتی تو میں اس کا ہاتھ بھی کاٹ دیتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں چوری کرلی۔ لوگ کہنے لگے: ہم تو اس کے بارے میں آپ سے بات نہیں کرسکتے اور بھی کوئی نہیں کرسکتا مگر اسامہ جو آپ کو بہت پیارے ہیں۔ حضرت اسامہ رضی اللہ عنہ نے آپ سے سفارش کی تو آپ نے فرمایا: اے اسامہ! بنی اسرائیل اس جیسے کاموں کی وجہ سے ہلاک ہوئے۔ جب ان میں سے کوئی بلند مرتبہ شخص چوری کرلیتا تو اس کو چھوڑ دیتے اور اگر کوئی کم مرتبہ شخص ان میں چوری کر بیٹھتا تو اس کا ہاتھ کاٹ دیتے۔ اگر (چوری کرنے والی) محمد (صلی اللہ علیہ وسلم) کی بیٹی فاطمہ ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘","f2":"’’ ہلاک ہوئے‘‘ ہلاکت سے مراد اخروی ہلاکت بھی ہوسکتی ہے اور دنیوی بھی کیونکہ حدود کا نفاذ نہ کرنے سے جرائم بڑھتے ہیں اور جرائم کی کثرت قوموں کی تباہی کا باعث بنتی ہے نیز نافرمانی سے عذاب بھی آتا ہے۔"}],[4898,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک غیر معروف عورت نے کچھ معروف لوگوں (کی گواہی) کے ذریعہ زیورات عاریۃً مانگے، پھر اس نے زیورات بیچ کر اس کی قیمت لے لی، چنانچہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لائی گئی تو اس کے گھر والوں نے اسامہ بن زید رضی اللہ عنہما کے پاس دوڑ بھاگ کی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس سلسلے میں بات کی تو آپ کے چہرے کا رنگ بدل گیا، پھر آپ نے ان سے فرمایا: \"کیا تم مجھ سے اللہ کی حدود میں سے کسی حد کے بارے میں سفارش کرتے ہو؟\" اسامہ نے کہا: اللہ کے رسول! میری بخشش کے لیے اللہ سے دعا کر دیجئیے، پھر رسول اللہ صلی اللہ علیہ وسلم اس شام کھڑے ہوئے اور اللہ کی حمد بیان کی جس کا وہ مستحق ہے پھر اس کے بعد فرمایا: \"تم سے پہلے لوگ صرف اس لیے ہلاک و برباد ہو گئے کہ جب ان میں سے کوئی معزز آدمی چوری کرتا تو اسے چھوڑ دیتے اور جب ان میں سے کوئی کمزور آدمی چوری کرتا تو اس پر حد نافذ کرتے۔ اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے! اگر فاطمہ بنت محمد بھی چوری کرتی تو میں اس کا بھی ہاتھ کاٹ دیتا\"، پھر اس عورت کا ہاتھ کاٹ دیا گیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے انہوں نے فرمایا: ایک عورت نے دوسرے لوگوں کی معرفت کچھ زیورات عارضی طور پر استعمال کے لیے۔ وہ لوگ تو معروف تھے مگر وہ عورت معروف نہیں تھی۔ اس نے وہ زیورات بیچ دیے اور قیمت ہضم کرلی۔ اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا تو اس کے گھر والے (سفارش کے لیے) حضرت اسامہ بن زید رضی اللہ عنہا کی طرف بھاگے۔ حضرت اسامہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کی سفارش کردی۔ رسول اللہ صلی اللہ علیہ وسلم کا چہرہ (غصے سے) سرخ ہو گیا۔ پھر آپ نے فرمایا: ’’ تو میرے پاس اللہ تعالیٰ کی مقرر کردہ حدود میں سے ایک حد نہ لگانے کی سفارش کر رہا ہے؟ ‘‘ اسامہ نے کہا: اے اللہ کے رسول! میرے لیے بخشش کی دعا فرمائیے۔ پھر اسی دن ظہر کے بعد رسول اللہ صلی اللہ علیہ وسلم (خطاب کے لیے) اٹھے۔ اللہ تعالیٰ کی تعریف فرمائی جو اس کی شان کے لائق ہے۔ پھر فرمایا:’’ سن لو! تم سے پہلے لوگ اس بنا پر ہلاک ہوئے کہ جب ان میں سے کوئی بلند مرتبہ شخص چوری کرلیتا تھا تو اسے چھوڑ دیتے اور جب کوئی کمزور شخص چوری کرلیتا تو اسے حد لگا دیتے۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! اگر محمد(صلی اللہ علیہ وسلم) کی بیٹی فاطمہ چوری کرتی تو میں اس کا ہاتھ بھی کاٹ دیتا۔‘‘ پھر آپ نے اس عورت کا ہاتھ کاٹ دیا۔"}],[4899,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ قریش کو اس مخزومی عورت کے معاملے نے فکر میں ڈال دیا جس نے چوری کی تھی۔ ان لوگوں نے کہا کہ اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کون بات چیت کرے گا؟ لوگوں نے کہا: آپ سے بات چیت کی جرات آپ کے محبوب اسامہ کے سوا کون کر سکتا ہے؟ چنانچہ اسامہ رضی اللہ عنہ نے آپ سے عرض کیا تو آپ نے فرمایا: \"کیا تم اللہ کی حدود میں سے کسی حد میں سفارش کرتے ہو؟\" پھر آپ کھڑے ہوئے، خطبہ دیا اور فرمایا:\"تم سے پہلے کے لوگ صرف اس لیے ہلاک و برباد ہو گئے کہ ان کا معزز آدمی چوری کرتا تو اسے چھوڑ دیتے اور جب ان کا کمزور آدمی چوری کرتا تو اس پر حد نافذ کرتے، اللہ کی قسم! اگر فاطمہ بنت محمد بھی چوری کرتی تو میں اس کا ہاتھ کاٹ دیتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک مخزومی عورت جس نے چوری کی تھی، کی وجہ سے قریش بڑے فکر مندہوئے۔ وہ کہنے لگے: اس کی سفارش رسول اللہ صلی اللہ علیہ وسلم سے کون کرے گا؟ پھر (خود ہی) کہنے لگے: اس کی جرات رسول اللہ صلی اللہ علیہ وسلم کے محبوب اسامہ بن زید رضی اللہ عنہما کے سوا کون کرسکتا ہے! حضرت اسامہ نے آپ سے اس کی سفارش کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ تو اللہ تعالیٰ کی مقرر کردہ حدود میں اسے ایک حد (کو نافذ نہ کرنے) کی بابت سفارش کررہا ہے؟‘‘ پھر آپ کھڑے ہوئے اور خطاب کرتے ہوئے فرمایا: ’’ تم لوگوں سے پہلے لوگ اسی بنا پر ہلاک ہوئے کہ جب ان میں سے کوئی بلند مرتبہ شخص چوری کرلیتا تو اسے چھوڑ دیتے تھے اور جب کوئی کمزور شخص چوری کرلیتا تو اس کو حد لگا دیتے۔ اللہ کی قسم! اگر (بالفرض) محمد (صلی اللہ علیہ وسلم) کی بیٹی فاطمہ بھی چوری کرتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘"}],[4900,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ قریش یعنی بنی مخزوم کی ایک عورت نے چوری کی، اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا، کچھ لوگوں نے کہا: آپ سے اس کے بارے میں کون بات چیت کرے گا؟ لوگوں نے جواب دیا: اسامہ بن زید، چنانچہ وہ آپ کے پاس آئے اور عرض کیا تو آپ نے انہیں ڈانٹ دیا اور فرمایا: \"بنی اسرائیل کا جب کوئی معزز آدمی چوری کرتا تو اسے چھوڑ دیتے اور جب کوئی عام آدمی چوری کرتا تو اس کا ہاتھ کاٹ دیتے۔ اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے! اگر فاطمہ بنت محمد نے چوری کی ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے انہوں نے فرمایا: قریش کے ایک قبیلے بنو مخزوم کی ایک عورت نے چوری کرلی۔ اسے پکڑ کر نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا۔ اس کے رشتے دار کہنے لگے کہ کون اس کی سفارش کرسکتا ہے؟ کچھ لوگ کہنے لگے: حضرت اسامہ رضی اللہ عنہ یہ کام کرسکتے ہیں۔ اسامہ آپ کے پاس آئے اور اس عورت کی سفارش کی۔ آپ نے انہیں ڈانٹا اور فرمایا: ’’ بنی اسرائیل کا حال یہ تھا کہ جب ان کا کوئی بلند مرتبہ شخص چوری کرتا تھا تو اسے چھوڑ دیتے۔ (کچھ نہیں کہتے تھے۔) اور جب کوئی کم مرتبہ شخص چوری کرلیتا تھا تو اس کا ہاتھ کاٹ دیتے۔ قسم اس ذات کی جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم) کی جان ہے! اگر (میری بیٹی) فاطمہ بنت محمد چوری کرتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘"}],[4901,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ قریش کو مخزومی عورت کے معاملے نے فکر میں ڈال دیا جس نے چوری کی تھی۔ ان لوگوں نے کہا: اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کون بات کرے گا؟ لوگوں نے کہا: اس کی جرات رسول اللہ صلی اللہ علیہ وسلم کے محبوب اسامہ بن زید کے سوا اور کون کر سکتا ہے؟ چنانچہ اسامہ رضی اللہ عنہ نے آپ سے بات کی تو آپ نے فرمایا: \"تم سے پہلے کے لوگ اس لیے ہلاک ہو گئے کہ جب ان میں کوئی معزز اور باوقار آدمی چوری کرتا تو اسے چھوڑ دیتے اور جب کوئی کمزور اور بے حیثیت آدمی چوری کرتا تو اس پر حد نافذ کرتے، اللہ کی قسم! اگر فاطمہ بنت محمد نے چوری کی ہوتی تو میں اس کا ہاتھ کاٹ دیتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی ا للہ عنہا سے روایت ہے کہ قریش کو ایک مخزومی عورت کے معاملے نے پریشان کر دیا جس نے چوری کرلی تھی۔ وہ کہنے لگے: اس کے بہار میں کون سفارش کرے گا؟ پھر خود ہی کہنے لگے: اس کی جرات رسول اللہ صلی اللہ علیہ وسلم کے محبوب اسامہ بن زید رضی اللہ عنہما کے سوا کون کرسکتا ہے! حضرت اسامہ نے آپ سے سفارش کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ تم سے پہلے لوگ اسی بنا پر ہلاک ہوئے کہ جب ان میں کوئی بڑا (چودھری) چوری کرلیتا تو اسے چھوڑ دیتے تھے اور جب کوئی کم مرتبہ شخص چوری کرلیتا تھا تو اس پر حد لگا دیتے تھے۔ اللہ کی قسم! اگر محمد کی بیٹی فاطمہ چوری کرتی تو میں اس کا ہاتھ بھی کاٹ دیتا۔‘‘"}],[4902,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم کے عہد میں فتح مکہ کے وقت چوری کی، چنانچہ اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا تو اسامہ بن زید رضی اللہ عنہما نے اس کے بارے میں آپ سے بات کی۔ جب انہوں نے آپ سے بات کی تو آپ کے چہرے کا رنگ بدل گیا، آپ نے فرمایا: \"کیا تم اللہ کی حدود میں سے کسی حد کے بارے میں سفارش کرتے ہو؟\" اسامہ رضی اللہ عنہ نے آپ سے کہا: میرے لیے اللہ کے رسول! اللہ سے مغفرت طلب کیجئیے۔ جب شام ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اللہ کی حمد بیان کی جس کا وہ اہل ہے، پھر فرمایا: \"تم سے پہلے کے لوگ صرف اس لیے ہلاک ہوئے کہ جب ان کا معزز اور باحیثیت آدمی چوری کرتا تو اسے چھوڑ دیتے اور جب کوئی کمزور اور بے حیثیت آدمی چوری کرتا تو اس پر حد نافذ کرتے\"، پھر فرمایا: \"اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر فاطمہ بنت محمد نے بھی چوری کی ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں غزوہ فتح مکہ کے موقع پر ایک عورت نے چوری کرلی تو اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا۔ حضرت اسامہ بن زید رضی اللہ عنہما نے اس کے بارے میں آپ سے بات کی۔ (معافی کی سفارش کی۔) جب انہوں نے آپ سے بات کی تو رسول اللہ صلی اللہ علیہ وسلم کا چہرہ انور متغیر (غصے سے سرخ) ہوگیا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ کیا تو اللہ تعالیٰ کی مقرر کردہ حدود میں سے ایک حد(کو ساقط کرنے) کی بابت سفارش کررہا ہے؟‘‘ حضرت اسامہ نے کہا: اے اللہ کے رسول! میرے لیے معافی کی دعا فرمائیے۔ پھر جب ظہر (کی نماز) ہوئی تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے اور اللہ عزوجل کی تعریف کی جو اللہ عزوجل کی شان جلیلہ کے مطابق تھی۔ پھر فرمایا: ’’ سن لو! تم سے پہلے لوگ اسی بنا پر ہلاک ہوئے کہ جب ان میں سے کوئی اونچا (بڑا) آدمی چوری کرلیتا تو اسے چھوڑ دیتے تھے۔ (کچھ نہ کہتے تھے) اور جب کوئی کمزور آدمی چوری کربیٹھتا تھا تو اس پر حد لاگو کر دیتے (اسے سزا دیتے) تھے۔‘‘ پھر فرمایا:’’ قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! اگر فاطمہ بنت محمد بھی چوری کرتی تو میں اس کا ہاتھ بھی کاٹ دیتا۔‘‘"}],[4903,"عروہ بن زبیر کہتے ہیں کہ فتح مکہ کے وقت رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک عورت نے چوری کی (\"فتح مکہ کے وقت\" کا لفظ مرسل ہے) تو اس کے خاندان کے لوگ گھبرا کر سفارش کا مطالبہ کرنے کے لیے اسامہ بن زید رضی اللہ عنہما کے پاس گئے۔ جب اسامہ نے آپ سے اس کے بارے میں بات چیت کی تو رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدل گیا، آپ نے فرمایا: \"تم مجھ سے اللہ کی حدوں میں سے کسی ایک حد کے بارے میں بات کر رہے ہو؟\" اسامہ رضی اللہ عنہ نے کہا: اللہ کے رسول! میرے لیے اللہ سے بخشش طلب کیجئے، جب شام ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم خطبہ دینے کے لیے کھڑے ہوئے، آپ نے اللہ کی حمد و ثنا بیان کی جو اس کے لائق ہے، پھر فرمایا: \"تم سے پہلے کے لوگ اس لیے ہلاک ہو گئے کہ جب ان میں کوئی معزز آدمی چوری کرتا تو اسے چھوڑ دیتے اور جب کوئی کمزور آدمی چوری کرتا تو اس پر حد نافذ کرتے۔ اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے! اگر فاطمہ بنت محمد نے بھی چوری کی ہوتی تو میں اس کا بھی ہاتھ کاٹ دیتا\"۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس عورت کے ہاتھ کاٹنے کا حکم دیا اور اسے کاٹ دیا گیا، پھر اس کے بعد اس نے اچھی طرح سے توبہ کر لی، عائشہ رضی اللہ عنہا کہتی ہیں: وہ اس کے بعد میرے پاس آتی تو میں اس کی ضرورت رسول اللہ صلی اللہ علیہ وسلم تک پہنچا دیتی تھی۔","الألباني: صحيح",{"u2":"حضرت عروہ بن زبیر سے مرسلا روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں فتح مکہ کی جنگ کے وقت ایک عورت نے چوری کرلی۔ اس کی قوم کے لوگ گھبرا کر حضرت اسامہ بن زید رضی اللہ عنہما کے پاس آئے کہ وہ اس کی سفارش فرمادیں۔ جب حضرت اسامہ نے آپ سے اس کی بابت بات چیت کی تو رسول اللہ صلی اللہ علیہ وسلم کے چہرا اقدس کا رنگ بدل گیا۔ آپ نے فرمایا:’’ کیا تو اللہ تعالیٰ کی حدود میں سے ایک حد کے بارے میں سفارش کرتا ہے؟‘‘ اسامہ نے کہا: اے اللہ کے رسول! میرے لیے استغفار فرمائیں۔ ظہر کے بعد رسول اللہ صلی اللہ علیہ وسلم خطبے کے لیے کھڑے ہوئے اور اللہ تعالیٰ کی تعریف فرمائی جو اس کی شان کے لائق ہے۔ پھر فرمایا:’’ اما بعد (اے لوگو!) تم سے پہلے لوگ اس بنا پر تباہ ہوئے کہ جب ان میں کوئی طاقت ور شخص چوری کرتا تو اس کو چھوڑ دیتے۔ اور جب کوئی کمزور شخص چوری کرتا تو اس پر حد نافذ کردیتے۔ قسم اس ذات کی جس کے ہاتھ میں محمد(صلی اللہ علیہ وسلم) کی جان ہے! اگر (بالفرض) فاطمہ بنت محمد (صلی اللہ علیہ وسلم) چوری کرتی تو میں اس کا بھی ہاتھ کاٹ دیتا۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس عورت کا ہاتھ کاٹنے کا حکم دیا۔ اس کا ہاتھ کاٹ دیا گیا۔ لیکن اس کے بعد اس نے بہت اچھی توبہ کرلی۔ حضرت عائشہ رضی اللہ عنہا نے فرمایا: اس کے بعد وہ میرے پاس آیا کرتی تھی اور میں اس کی گزارشات و ضروریات رسول اللہ (صلی اللہ علیہ وسلم) کی میں پیش کیا کرتی تھی۔","f2":"1۔مذکورہ تمام احادیث سے معلوم ہوتا ہے کہ حدود میں سفارش کرنا ممنوع ہے بشرطیکہ معاملہ عدالت یا حکام بالا تک پہنچ چکا ہو۔\n2۔ ان احادیث مبارکہ سے یہ مسئلہ بھی ثابت ہوتا ہے کہ جس طرح چوری کرنے والے مرد کا ہاتھ کاٹا جاسکتا ہے اسی طرح چوری کرنے والی عورت کا ہاتھ بھی کاٹا جاسکتا ہے۔ قرآن کریم نے تو مکمل صراحت کے ساتھ چور مرد اور چور عورت کے ہاتھ کاٹنے کا حکم دیا ہے۔ دیکھیے (المائدۃ 5: 38)\n3۔حضرت اسامہ بن زید رضی اللہ عنہما کی عظیم قدرت و منزلت پر بھی یہ احادیث واضح دلالت کرتی ہیں کہ وہ نہ صرف رسول اللہ صلی اللہ علیہ وسلم کے محبوب تھے بلکہ لوگوں میں بھی محبوب سمجھے جاتے تھے۔\n4۔ مذکورہ احادیث سے معلوم ہوا کہ سیدہ فاطمہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے ہاں بہت زیادہ قدر و منزلت کی حامل تھیں، تاہم یہ بھی واضح ہوتا ہے کہ حدود اللہ کے قائم کرنے میں نہ تو کسی کی محبت کو خاطر میں لایا جاسکتا ہے اور نہ کسی کی سفارش ہی قبول کی جاسکتی ہے۔ واللہ اعلم\n5۔ ’’ آیا کرتی تھی‘‘ گویا وہ ہجرت کرکے مدینہ منورہ آگئی تھی۔ توبہ اور سزا کے بعد گناہ ختم ہو جاتا ہے۔\n6۔ کسی حدیث کی تمام اسانید کو تفصیلا بیان کرنے کا سب سے بڑا فائدہ یہ ہے کہ واقعے کی تمام تفصیلات سامنے آجاتی ہیں، کوئی ابہام باقی نہیں رہتا۔"}],[4904,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک حد کا نافذ ہونا اہل زمین کے لیے تیس دن بارش ہونے سے بہتر ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی بارش عام طور پر رزق میں وسعت اور خوشحالی کا سبب ہوتی ہے، مگر حد کا نفاذ اس بابت زیادہ فائدہ مند ہے اس لیے کہ معاشرہ میں امن و امان کے قیام میں بہت ہی موثر چیز ہے۔","الألباني: حسن بلفظ أربعين",{"u2":"حضرت ابوہرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ زمین میں ایک حد کا لگایا جانا زمین پر رہنے والوں کے لیے اس بات سے بہتر ہے کہ ان پر تیس دن بارش برسے۔‘‘","f2":"۔کچھ سزائیں ’’ حد‘‘ کہلاتی ہیں اور کچھ ’’ تعزیر‘‘۔ حد تو وہ سزا ہوتی ہے جو اللہ تعالیٰ کی طرف سے مقرر کردہ ہو جبکہ تعزیر اس سزا کو کہتے ہیں جو قاضی اور جج یا کوئی بھی ذمہ دار شخص جرم کی نوعیت دیکھ کر مناسبت سے اس جرم کی روک تھام کے لیے اپنی صواب دید کے مطابق دے سکتا ہے۔ مطلب یہ ہے کہ تعزیر اللہ تعالیٰ کی طرف سے مقرر کردہ نہیں ہوتی۔ یہی وجہ ہے کہ اس میں کمی بیشی ہو سکتی ہے۔ البتہ حد اور تعزیر دونوں کے نفاذ کا مقصد لوگوں کو جرائم سے روکنا ہوتا ہے۔ یہ سزائیں اس لیے دی جاتی ہیں کہ مجرم کا حشر دیکھ کر دوسرے لوگ عبرت حاصل کریں اور جرم سے اجتناب کریں۔\n2۔ عام طور پر بارش ہر جگہ اور ہر علاقے کی ضرورت ہوتی ہے لیکن صحرائی علاقوں میں اس کی ضرورت کئی گنا زیادہ ہوتی ہے۔ عرب جو بہت بڑے صحرائی علاقے پر مشتمل ہے وہاں اس کی ضرورت مسلمہ ہے اس لیے اس سے تشبیہ دی۔\n3۔ ’’ بہتر ہے ‘‘ کیونکہ حدود کا نفاذ معاشرے میں امن وامان اور سکون و اطمینان پیدا کرتا ہے نیز لڑائی جھگڑے اور خون ریزی کو ختم کرتا ہے۔ بارش کا فائدہ وقتی ہے مگر حدود کا فائدہ دائمی اور مستقل ہے نیز بارش صرف دنیا میں مفید ہے جب کہ حدود کا نفاذ آخرت میں بھی مفید ہوگا۔ رزق کا کیا فائدہ اگر جان اور مال وعزت ہی محفوظ نہ ہو؟ بلکہ رزق کی کثرت بسا اوقات جان وعوت کے لیے خطرہ بن جاتی ہے جب معاشرے میں امن و امان نہ ہو۔ حدود انسان کے جان و مال اور عزت کو محفوظ کرنے کے لیے نسخہ کیمیا ہیں۔ تجربہ شرط ہے۔\n4۔ ’’ تیس دن‘‘ کثرت مراد ہے جیسا کہ آئندہ حدیث سے معلوم ہوتا ہے نیز یہ ایک فرضی بات ہے ورنہ مسلسل تیس دن بارش برستی رہے تو نقصان کا سبب بن سکتی ہے۔ البتہ پہاڑی علاقوں میں مسلسل بارش بھی مفید رہتی ہے یا وقفے وقفے سے مراد ہوگی، یعنی ضرورت کے مطابق پڑتی رہے۔ بارش کا خصوصی ذکر اس لیے فرمایا کہ بارش کے ساتھ ہی زمینی زندگی کی بقا ہے۔"}],[4905,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ زمین میں ایک حد کا نفاذ زمین والوں کے لیے چالیس دن کی بارش سے زیادہ بہتر ہے۔","الألباني: حسن موقوف في حكم المرفوع",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا: زمین میں ایک حد نافذ کردینا زمین پر بسنے والوں کے لیے چالیس دن کی بارش سے بھی زیادہ مفید ہے۔","f2":"1۔یہ روایت اگرچہ موقوف ہے لیکن حکما مرفوع ہی ہے کیونکہ یہ بات کوئی صحابی اپنی رائے سے نہیں کہہ سکتا۔ واللہ اعلم\n2۔ محقق کتاب نے مذکورہ دونوں روایتوں کو سندا ضعیف قرار دیا ہے لیکن دیگر محققین نے شواہد کی بنا پر ان کو حسن کہا ہے۔ دیکھیے: (الصحیحۃ، حدیث:231، وذخیرۃ العقبی، شرح سنن النسائی 37؍30۔32)"}],[4906,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال کی چوری میں ہاتھ کاٹا، جس کی قیمت پانچ درہم تھی، راوی نے اسی طرح کہا ۱؎۔\n§وضاحت\n۱؎: یعنی یہ راوی کا وہم ہے کہ ڈھال کی قیمت پانچ درہم تھی، صحیح یہ ہے کہ اس کی قیمت تین درہم تھی، جیسا کہ اگلی روایت میں ہے۔","الألباني: صحيح بلفظ ثلاثة",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال کی چوری پر ہاتھ کاٹ دیا تھا جس کی قیمت پانچ درہم تھی۔ (امام صاحب  نے فرمایا:) راوی نے اسی طرح بیان کیا ہے۔ (اسے غلطی لگی ہے۔)"}],[4907,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال (چرانے) میں ہاتھ کاٹا جس کی قیمت تین درہم تھی۔ ابوعبدالرحمٰن (نسائی)کہتے ہیں: یہی روایت صحیح اور درست ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال کی چوری پر ہاتھ کاٹ دیا تھا جس کی قیمت تین درہم تھی۔\nابو عبدالرحمن (امام نسائی رحمہ اللہ) بیان کرتے ہیں کہ یہ روایت درست ہے۔","f2":"1۔کتنی مالیت کی چیز چرانے پر ہاتھ کاٹا جائے گا؟ مذکورہ باب کے تحت بیا ن کی گئی پہلی روایت (4910) میں ڈھال کی قیمت پانچ درہم بیان کی گئی ہے یہ قطعا درست نہیں یہ راوی کا وہم اور اس کی غلطی ہے۔ دیگر صحیح روایات میں ڈھال کی قیمت تین درہم بیان کی گئی ہے جیسا کہ آئندہ روایت میں ہے۔ پانچ درہم والی روایت شاذ (ضعیف) ہے کیونکہ اس کے راوی مخلد نے اپنے سے اوثق واحفظ راویوں کی مخالفت کی ہے۔ انہوں نے حضرت نافع  سے یہ روایت بیان کی تو قیمت تین درہم بیان کی ہے جبکہ یہ پانچ درہم بیان کرتے ہیں۔ اگرچہ ڈھال کی قیمت مختلف ہو سکتی ہے مگر چونکہ یہ ایک ہی روایت کی دو سندیں ہیں لہذا ایک کو راوی کی غلطی کہا جائے گا۔ ویسے اگر دونوں روایات صحیح ہوں تب بھی کوئی فرق نہ پڑتا کیونکہ تین درہم یا اس سے زائد میں ہاتھ کاٹا جاتا ہے۔ اگر کوئی چیز سو درہم کی ہو تو اس میں بھی کاٹا جائے گا، اگر لاکھ درہم کی ہو تب بھی لہذا پانچ درہم میں ہاتھ کاٹنے سے تین درہم میں ہاتھ کاٹنے کی نفی نہیں ہوتی۔ البتہ تین درہم سے کم میں ہاتھ کاٹنے کا کہیں ذکر نہیں، لہذا تین درہم اور ربع دینار میں کوئی فرق نہیں۔ نبی صلی اللہ علیہ وسلم کے دور میں دینار دس، بارہ درہم کا ہوتا تھا۔ بارہ کا چوتھائی تو تین ہی ہے۔ دس کا ربع بھی تین دینار ہی کو کہا جائے گا کیونکہ شریعت کسر پر حکم نہیں لگاتی بلکہ اسے پورا کر دیتی ہے، یعنی ڈھائی درہم کی بجائے تین درہم پر قطع ید کا حکم لگے گا۔ تین درہم اور ربع دینار کی روایات قطعا صحیح اور بخاری ومسلم کی ہیں، اس لیے انہی پر عمل ہوگا۔ احناف نے بعض ضعیف روایات کی بنا پر نصاب مسروقہ دس درہم مقرر کیا ہے۔ یہ بات سراسر اصول کے خلاف ہے کہ صحیح احادیث کے مقابلے میں ضعیف روایت کو ترجیح دی جائے۔ اگرچہ احناف نے اسے احتیاط قرار دیا ہے مگر یہ عجیب احتیاط ہے جس سے شریعت کا صحیح اور صریح حکم کالعدم ہو جائے۔"}],[4908,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال (چرانے) پر ہاتھ کاٹا جس کی قیمت تین درہم تھی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول ا للہ صلی اللہ علیہ وسلم نے ایک ڈھال کی چوری پر ہاتھ کاٹا تھا جس کی قیمت تین درہم تھی۔"}],[4909,"عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک چور کا ہاتھ کاٹا جس نے عورتوں کے چبوترے سے ایک ڈھال چرائی، جس کی قیمت تین درہم تھی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک چور کا ہاتھ کاٹ دیا تھا جس نے عورتوں والے چھپر سے ایک ڈھال چرائی تھی جس کی قیمت تین درہم تھی۔","f2":"’’ عورتوں والے چھپر سے ‘‘ مسجد نبوی میں عورتوں کے لیے ایک سایہ دار جگہ بنا دی گئی تھی، اسے صفۃ النساء (عورتوں کا چھپر) کہا جاتا تھا۔"}],[4910,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک ڈھال (چرانے) پر ہاتھ کاٹا جس کی قیمت تین درہم تھی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک ڈھال کی چوری پر ہاتھ کاٹ دیا تھا جس کی قیمت تین درہم تھی۔"}],[4911,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کون سا گناہ سب سے بڑا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"شرک یعنی یہ کہ تم کسی کو اللہ کے برابر ٹھہراؤ، اپنے پڑوسی کی بیوی سے زنا کرو، اور فقر و فاقہ کے ڈر سے کہ بچہ تمہارے ساتھ کھائے گا تم اپنے بچے کو قتل کر دو\"، پھر عبداللہ بن مسعود رضی اللہ عنہ نے یہ آیت پڑھی «والذين لا يدعون مع اللہ إلها آخر» \"اور جو لوگ اللہ کے ساتھ کسی دوسرے معبود کو نہیں پکارتے ہیں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اس حدیث کی سند میں غلطی ہے، اس سے پہلے والی سند صحیح ہے، یزید کی اس سند میں غلطی ہے (کہ واصل کی بجائے عاصم ہے) صحیح«واصل» ہے۔\nانس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ڈھال (چرانے) پر ہاتھ کاٹا۔ ابوعبدالرحمٰن کہتے ہیں: یہ غلط ہے ۱؎۔\n§وضاحت\n۱؎: یعنی اس سند سے اس حدیث کی مرفوع روایت خطا ہے، اور صحیح موقوف ہے، جیسا کہ حدیث رقم :(۴۹۱۶ ) سے واضح ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے ایک ڈھال چرانے پر ہاتھ کاٹ دیا تھا۔\nابو عبدالرحمن (امام نسائی رحمہ اللہ) نے فرمایا: یہ غلط ہے۔","f2":"امام نسائی رحمہ اللہ کا مقصد یہ بیان کرنا ہے کہ ہشام دستوائی نے قتادہ سے انہوں نے حضرت انس رضی اللہ عنہ سے جو مرفوعا بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ڈھال چرانے پر ہاتھ کاٹا تھا، یہ روایت مرفوعا بیان کرنا درست نہیں بلکہ درست یہ ہے کہ یہ روایت موقوف، یعنی حضرت ابوبکر صدیق رضی اللہ عنہ کا فعل ہے۔ امام حدیث شعبہ رضی اللہ عنہ نے قتادہ رضی اللہ عنہ سے انہوں نے انس رضی اللہ عنہ سے موقوفا ہی بیان کیا ہے جیسا کہ اگلی روایت (4916) میں صراحت ہے اور اس موقوف روایت کو امام نسائی رحمہ اللہ نے صحیح اور درست قرار دیا ہے۔"}],[4912,"انس رضی اللہ عنہ کہتے ہیں کہ ابوبکر رضی اللہ عنہ نے ایک ڈھال (چرانے) پر (چور کا) ہاتھ کاٹا جس کی قیمت پانچ درہم تھی ۱؎۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:)یہی روایت صحیح ہے ۲؎۔\n§وضاحت\n۱؎: یہ ایک واقعہ ہے جس میں پانچ درہم مال کی چوری ہوئی تھی، اگر کم کی ہوئی ہوتی :(تین تک ) تو بھی ابوبکر رضی اللہ عنہ ہاتھ کاٹتے، یا ان کو پچھلی حدیث نہیں پہنچی تھی۔ ۲؎: یعنی انس رضی اللہ عنہ کی اس روایت کا موقوف ہونا ہی صحیح ہے۔","الألباني: حسن صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا: حضرت ابوبکر رضی اللہ عنہ نے ایک ڈھال کی چوری پر ہاتھ کاٹ دیا تھا جس کی قیمت پانچ درہم تھی۔ یہ درست ہے۔","f2":"مقصد یہ ہے کہ حضرت انس رضی اللہ عنہ کی حضرت ابوبکر رضی اللہ عنہ سے بیان کردہ یہ روایت درست ہے یعنی موقوفا درست ہے مرفوعا نہیں۔"}],[4913,"انس رضی اللہ عنہ کہتے ہیں کہ ابوبکر رضی اللہ عنہ کے عہد میں ایک شخص نے ایک ڈھال چرائی، اس کی قیمت پانچ درہم لگائی گئی، تو اس کا ہاتھ کاٹا گیا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ نے فرمایا: ایک آدنی نے حضرت ابوبکر رضی اللہ عنہ کے دور مبارک میں ایک ڈھال چرا لی۔ اس کی قیمت پانچ درہم تھی تو انہوں نے اس کا ہاتھ کاٹ دیا۔","f2":"پانچ درہم پر ہاتھ کاٹنے سے تین درہم پر ہاتھ کاٹنے کی نفی نہیں ہوتی۔ (دیکھیئے‘روایت:4911)"}],[4914,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کی اونٹنیوں کو لوٹا تو آپ نے انہیں گرفتار کیا اور ان کے ہاتھ اور پاؤں کاٹ دیے اور ان کی آنکھیں پھوڑ دیں۔\nام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک چوتھائی دینار میں (چور کا) ہاتھ کاٹا ۱؎۔\n§وضاحت\n۱؎: معلوم ہوا کہ چوتھائی دینار یعنی تین درہم یا اس سے زیادہ کی مالیت کا سامان اگر کوئی چوری کرتا ہے تو اس کے بدلے ہاتھ کاٹا جائے گا۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک چوتھائی دینار چوری کرنے پر ہاتھ کاٹا ہے۔","f2":"دیکھیے حدیث:4911"}],[4915,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کی اونٹنیاں لوٹ لیں، انہیں نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا تو آپ صلی اللہ علیہ وسلم نے ان کے ہاتھ اور پاؤں کاٹ دیے، اور ان کی آنکھیں پھوڑ دیں۔\nام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ڈھال کی قیمت میں ہاتھ کاٹا جائے\" یعنی ایک تہائی دینار، یا آدھے دینار اور اس سے زیادہ میں۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(چور کا) ہاتھ نہیں کاٹا جائے گا مگر ایک ڈھال کی قیمت میں (یعنی) تہائی دینار یا نصف دینار یا اس سے زائد میں۔‘‘","f2":"’’ اس روایت میں‘‘ تہائی دینار یا نصف دینار ‘‘ کے الفاظ ہیں۔ ان الفاظ کے ساتھ یہ روایت درست نہیں، اس لیے کہ اولا تہائی دینار نصف دینار میں راوی کو تردد ہے جبکہ صحیح ترین روایات میں بلا تردد ڈھال کی قیمت چوتھائی دینار ہی بیان کی گئی ہے۔ ثانیا: مذکورہ روایت منکر (ضعیف) ہے کیونکہ یہ الفاظ یونس بن یزید سے قاسم بن مبرور بیان کرتا ہے، جو کہ ضعیف ہے۔ اس کے مقابلے میں یونس بن یزید بن عبداللہ بن مبارک اور ابن وہب، جو کہ پائے کے ثقہ ہیں جو بیان کرتے ہیں تو چوتھائی دینار ہی ڈھال کی قیمت بتاتے ہیں۔ دیکھیے: (صحیح البخاری، الحدود، حدیث: 6790، وصحیح مسلم، الحدود، باب حدالسرقۃ ونصابہا، حدیث: 1684) ’’ چوتھائی دینار‘‘ والے الفاظ ہی درست ہیں جبکہ ’’ تہائی دینار یا نصف دینار‘‘ والے الفاظ منکر ہیں۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی لانیوبی: 37؍48) پھر محقق کتاب کا اس روایت کے بارے میں علی الاطلاق کہنا کہ اسے بخاری اور مسلم نے روایت کیا ہے، غلط ہے بلکہ اس روایت میں تو بخاری و مسلم کی روایت کی مخالفت ہے اس لیے ایک منظر روایت کو بخاری و مسلم کی طرف منسوب کرنا کسی صورت درست نہیں۔"}],[4916,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ چوتھائی دینار میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ چوتھائی دینار کی چوری پر کاٹ دیا جائے گا۔‘‘"}],[4917,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ چوتھائی دینار پر یا اس سے زائد کی چوری پر کاٹ دیا جائے گا۔‘‘"}],[4918,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا کا بیان ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری پر کاٹ دیا جائے گا۔‘‘"}],[4919,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری پر کاٹ دیا جائے گا۔‘‘"}],[4920,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ \"چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح موقوف",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری میں کاٹا جائے گا۔"}],[4921,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم چوتھائی دینار اور اس سے زیادہ میں ہاتھ کاٹتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم چوتھائی دینار یا اس سے زائد کی چوری میں (چور کا ہاتھ) کاٹ دیا کرتے تھے۔"}],[4922,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ ایک چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری میں کاٹا جائے گا۔‘‘ (کم میں نہیں)"}],[4923,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ ایک چوتھائی دینار اور اس سے زیادہ میں ہاتھ کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری میں کاٹا جائے گا۔‘‘"}],[4924,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ چوتھائی دینار اور اس سے زیادہ میں (چور کا ہاتھ) کاٹا جائے گا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یحیی کی (مرفوع)روایت سے یہ (یعنی موقوف روایت) زیادہ صحیح ہے۔","الألباني: صحيح موقوف ولا ينافي المرفوع",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی تھیں: چوتھائی دینار یا اس سے زائد کی چوری میں ہاتھ کاٹا جائے گا۔\nابو عبدالرحمن (امام نسائی رحمہ اللہ) نے فرمایا: یحییٰ کی حدیث سے یہ درست ہے۔","f2":": امام نسائی کا مطلب یہ ہے کہ یحیٰ کی بیان کردہ مرفوع حدیث کے مقابلے میں ان کی بیان کردہ حضرت عائشہ رضی اللہ عنہا پر موقوف روایت صحیح ہے۔ اور موقوف حدیث کے صحیح ہونے کی وجہ یہ ہے کہ اکثر رواۃ جو یحییٰ سے بیان کرتے ہیں انہوں نے اسے موقوف بیان کیا ہے۔ عبداللہ بن مبارک، عبداللہ بن ادریس، سفیان بن عیینہ اور امام مالک رحمہ اللہ اس کے موقوف ہونے پر متفق ہیں۔ تفصیل کے لیے دیکھیے: (ذخیرۃ النقبیٰ شرح سنن النسائی، الانیوبی: 37؍58) تاہم یہ اصحیت صرف یحییٰ کی روایت کے بارے میں ہے، دیگر طرق کے اعتبار سے نہیں کیونکہ دیگر طرق سے یہ روایت مرفوعا ثابت ہے۔"}],[4925,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا۔","الألباني: صحيح موقوف",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری میں کاٹ دیا جائے گا"}],[4926,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہاتھ کاٹنا چوتھائی دینار اور اس سے زیادہ میں ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ہاتھ کاٹنے کا حکم چوتھائی دینار یا اس سے زائد کی چوری میں لاگو ہوتا ہے۔"}],[4927,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: نہ بہت عرصہ گزرا اور نہ میں بھولی ہوں کہ ہاتھ کاٹنا چوتھائی دینار اور اس سے زیادہ میں ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: زیادہ عرصہ نہیں گزرا اور نہ میں بھولی ہوں کہ ہاتھ کاٹنے کا حکم چوتھائی دینار یا اس سے زائد کی چوری پر لاگو ہوتا تھا۔"}],[4928,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری کے بغیر نہیں کاٹا جائے گا۔‘‘"}],[4929,"عروہ بن زبیر کہتے ہیں کہ قبیلہ عرینہ کے کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کی اونٹنیاں لوٹ لیں، انہیں ہانک لے گئے اور آپ کے غلام کو قتل کر دیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان کے پیچھے کچھ لوگ روانہ کیے، وہ سب گرفتار کر لیے گئے، تو آپ نے ان کے ہاتھ اور پاؤں کاٹ دیے اور ان کی آنکھیں پھوڑ دیں۔\nاس سند سے بھی عائشہ رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے پہلی جیسی حدیث روایت کی ہے۔","الألباني: صحيح لغيره"],[4930,"عمرہ کہتی ہیں کہ عائشہ رضی اللہ عنہا نے کہا: ہاتھ کاٹنا چوتھائی دینار اور اس سے زیادہ میں ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: ہاتھ کاٹنے کا حکم چوتھائی دینار یا اس سے زائد کی چوری میں نافذ ہوگا۔"}],[4931,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ ڈھال کی قیمت میں کاٹا جائے گا اور ڈھال کی قیمت چوتھائی دینار ہے\"۔","الألباني: حسن صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ چور کا ہاتھ ڈھال کی قیمت کے برابر چوری پر کاٹ دیا جائے گا (اس وقت) ڈھال کی قیمت چوتھائی دینار تھی۔‘‘","f2":"’’ وثمن المجن ربع دینار‘‘ بظاہر لگتا ہے کہ یہ وضاحت رسول اللہ صلی اللہ علیہ وسلم نے فرمائی ہے حالانکہ درحقیقت یہ وضاحت حضرت عائشہ رضی اللہ عنہا کی ہے جیسا کہ حدیث:(4939) میں اس کی صراحت ہے۔"}],[4932,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم چوتھائی دینار اور اس سے زیادہ میں ہاتھ کاٹتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہانے فرمایا: رسول اللہ صلی اللہ علیہ وسلم چوتھائی دینار یا اس سے زائد کی چوری میں (چور کا) ہاتھ کاٹا کرتے تھے۔"}],[4933,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چور کا ہاتھ چوتھائی دینار میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ چوتھائی دینار سے کم کی چوری میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4934,"ام المؤمنین عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ڈھال (چوری کی قیمت) میں ہاتھ کاٹا جائے گا\"۔","الألباني: صحيح لغيره",{"u2":"ام المومنین حضرت عائشہ رضی اللہ عنہا نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: ’’ ڈھال کی چوری میں ہاتھ کاٹا جائے گا۔‘‘"}],[4935,"عمرہ بنت عبدالرحمٰن بیان کرتی ہیں کہ میں نے عائشہ رضی اللہ عنہا کو کہتے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ڈھال سے کم قیمت کی چیز میں ہاتھ نہیں کاٹا جائے گا\"، عائشہ سے کہا گیا: ڈھال کی قیمت کتنی ہے؟ کہا: چوتھائی دینار۔","الألباني: صحيح لغيره",{"u2":"حضرت عائشہ رضی اللہ عنہا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ ڈھال سے کم کی چوری میں چور کا ہاتھ نہیں کاٹا جائے گا۔‘‘ حضرت عائشہ رضی اللہ عنہا سے پوچھا گیا: ڈھال کی قیمت کتنی تھی؟ انہوں نے فرمایا: چوتھائی دینار"}],[4936,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"چور کا ہاتھ چوتھائی دینار اور اس سے زیادہ میں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ چور کا ہاتھ چوتھائی دینار یا اس سے زائد کی چوری کے علاوہ (کم میں) نہیں کاٹا جائے گا۔‘‘"}],[4937,"ام المؤمنین عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہاتھ اسی وقت کاٹا جائے گا جب وہ ڈھال یا اس کی قیمت کے برابر ہو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان فرماتی تھیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ ڈھال یا اس کی قیمت سے کم کی چوری میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4938,"ام المؤمنین عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہاتھ صرف ڈھال یا اس کی قیمت میں کاٹا جائے گا\"۔ راوی عثمان بن ابی الولید بیان کرتے ہیں کہ عروہ نے کہا: ڈھال چار درہم کی ہوتی ہے۔ عثمان کہتے ہیں: میں نے سلیمان بن یسار کو بیان کرتے ہوئے سنا کہ انہوں نے عمرہ کو کہتے ہوئے سنا کہ میں نے عائشہ کو بیان کرتے ہوئے سنا ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا کہ ہاتھ صرف چوتھائی دینار یا اس سے زیادہ میں کاٹا جائے گا۔","الألباني: صحيح"],[4939,"سلیمان بن یسار کہتے ہیں کہ پانچ انگلیوں یعنی ہاتھ کو نہیں کاٹا جائے گا مگر پانچ درہم میں۔ ہمام کہتے ہیں: میں عبداللہ داناج سے ملا، انہوں نے سلیمان بن یسار سے روایت کرتے ہوئے بیان کیا کہ انہوں نے کہا: پانچ کو پانچ میں ہی کاٹا جائے گا۔ یعنی ہاتھ پانچ درہم میں کاٹا جائے گا۔","الألباني: سكت عنه الشيخ"],[4941,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ حجفہ یا ترس یعنی ڈھال سے کم میں ہاتھ نہیں کاٹا جائے گا۔ ان میں سے ہر ایک چیز قیمت والی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: ڈھال سے کم قیمت کی چیز میں چور کا ہاتھ نہیں کاٹا جائے گا۔ اور (ہر قسم کی) ڈھال کافی قیمت کی ہوتی تھی۔","f2":"ظاہر ہے اس دور کے لحاظ سے تین درہم کافی قیمت تھی۔ حدیث کا مطلب یہ ہے کہ معمولی چیز کی چوری میں ہاتھ کاٹا جاسکتا ہے۔"}],[4942,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پانچ درہم کی قیمت (والی چیز) میں ہاتھ کاٹا۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پانچ درہم قیمت رکھنے والی چیز (کی چوری) میں ہاتھ کاٹا ہے۔"}],[4943,"ایمن کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے کسی چور کا ہاتھ نہیں کاٹا مگر ایسی چیز میں جو ڈھال کی قیمت کے برابر ہو اور اس وقت ڈھال کی قیمت ایک دینار تھی۔","الألباني: منكر",{"u2":"حضرت ایمن سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے چور کا ہاتھ ڈھال کی قیمت سے کم میں نہیں کاٹا۔ اور ڈھال کی قیمت ان دنوں ایک دینار (دس درہم) ہوتی تھی۔","f2":"یہ روایت مرسل ہونے کے ساتھ صحیح روایات کے معارض ہونے کی وجہ سے منکر بھی ہے۔"}],[4944,"ایمن کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ڈھال کی قیمت پر ہاتھ کاٹ دیا جاتا تھا اور اس وقت اس کی قیمت ایک دینار تھی۔","الألباني: منكر",{"u2":"حضرت ایمن سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ڈھال کی قیمت سے کم چیز کی چوری پر ہاتھ نہیں کاٹا جاتا تھا۔ اور ڈھال کی قیمت ان دنوں ایک دینار تھی۔"}],[4945,"ایمن کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہاتھ نہیں کاٹا گیا مگر ڈھال کی قیمت پر اور ڈھال کی قیمت اس وقت ایک دینار تھی۔","الألباني: منكر",{"u2":"حضرت ایمن سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانہ مبارک میں ڈھال کی قیمت سے کم میں ہاتھ نہیں کاٹا گیا۔ اور ڈھال کی قیمت ان دنوں ایک دینار تھی۔"}],[4946,"ایمن کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک ڈھال کی قیمت میں ہاتھ کاٹا گیا، اس وقت اس کی قیمت ایک دینار تھی۔","الألباني: منكر",{"u2":"حضرت ایمن سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مسعود میں ڈھال کی قیمت سے کم میں ہاتھ نہیں کاٹا گیا۔ اور اس کی قیمت ان دنوں ایک دینار تھی۔"}],[4947,"ایمن کہتے ہیں کہ چور کا ہاتھ ڈھال کی قیمت میں کاٹا جائے گا اور ڈھال کی قیمت رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک دینار یا دس درہم تھی۔","الألباني: منكر",{"u2":"حضرت ایمن نے فرمایا: چور کا ہاتھ ڈھال کی قیمت کے برابر چوری میں کاٹا جائے گا۔ اور ڈھال کی قیمت کے برابر چوری میں کاٹا جائے گا۔ اور ڈھال کی قیمت رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ایک دینار یا دس درہم تھی۔"}],[4948,"ایمن بن ام ایمن سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہاتھ ڈھال کی قیمت میں کاٹا جائے\" اور اس وقت اس کی قیمت ایک دینار تھی۔","الألباني: منكر",{"u2":"حضرت عطاء اور مجاہد سے روایت ہے کہ حضرت ایمن بن ام ایمن نے مرفوعا (رسول اللہ صلی اللہ علیہ وسلم کا فرمان) بیان فرمایا کہ چور کا ہاتھ ڈھال کی قیمت سے کم میں نہیں کاٹا جائے گا۔ اور ڈھال کی قیمت ان دنوں ایک دینار تھی۔","f2":"اس روایت سے معلوم ہوتا ہے کہ حدیث کے راوی حضرت ایمن صحابی ہیں۔ اور حضرت اسامہ رضی اللہ عنہ کے ماں کی طرف سے بھائی ہیں۔ لیکن یہ راوی کی غلطی ہے۔ درست بات یہ ہے کہ ایمن حبشی مکی ہیں جو تابعی تھے۔ کہا گیا ہے کہ انہیں حضرت زبیر یا ابن زبیر نے آزاد کیا تھا، اس لیے یہ روایت تابعی کی مرسل ہونے کی وجہ سے ضعیف ہو گی، نیز یہ صحیح روایات کے معارض ہونے کی وجہ سے بھی ناقابل حجت ہے، اس لیے محقق کتاب کا اسے صحیح کہنا درست نہیں۔ بالفرض اگر یہ ایمن واقعتا صحابی ایمن ہی مراد ہوں تو پھر بھی یہ روایت منقطع ہے کیونکہ حضرت عطاء اور مجاہد کی حضرت ایمن جو کہ صحابی ہیں سے ملاقات ہی نہیں۔ یہ دونوں بعد کے دور کے ہیں اور اس روایت (دینار یا دس درہم) کو بیان کرنے والے یہی دو بزرگ ہیں لہذا اگر ایمن تابعی ہیں تب بھی اور اگر صحابی ہیں تب بھی دونوں صورتوں میں سند منقطع ہے اور غیر معتبر، خصوصا جب کہ اس سے کم قیمت تین درہم یا چوتھائی دینار پر ہاتھ کاٹنا صحابہ کرام رضی اللہ عنہم سے بلاشبہ ثابت ہے۔"}],[4949,"ایمن کہتے ہیں: ڈھال سے کم قیمت کی چیز میں چور کا ہاتھ نہیں کاٹا جائے گا۔","الألباني: ضعيف",{"u2":"حضرت ایمن نے فرمایا: چور کا ہاتھ ڈھال کی قیمت سے کم میں نہیں کاٹا جائے گا۔\nحضرت عبداللہ بن عباس رضی اللہ عنہما نے فرمایا: ڈھال کی قیمت ان دنوں دس درہم تھی۔"}],[4950,"عطا بن ابی رباح بیان کرتے ہیں کہ عبداللہ بن عباس رضی اللہ عنہما کہا کرتے تھے: اس وقت اس (ڈھال) کی قیمت دس درہم تھی۔","الألباني: شاذ"],[4951,"عبداللہ بن عباس رضی اللہ عنہما سے اسی جیسی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ڈھال کی قیمت دس درہم لگائی جاتی تھی۔","الألباني: شاذ",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے کہ ڈھال کی قیمت رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں دس درہم لگائی جاتی تھی۔","f2":"ابن عباس رضی اللہ عنہما سے مروی مذکورہ دونوں روایات احادیث صحیحہ کے مخالف ہونے کی وجہ سے شاذ ہیں کیونکہ صحیح ترین روایات میں ڈھال کی قیمت تین درہم یا ربع دینار ہے۔"}],[4952,"اس سند سے عطاء سے مرسلاً روایت ہے۔","الألباني: سكت عنه الشيخ",{"u2":"یہ روایت حضرت عطاء سے مرسل بھی آتی ہے۔ (صحابی کے ذکر کے بغیر۔)","f2":"حضرت عطاء کا یہ امر مرسل اور مرفوع حدیث کے مخالف ہونے کی وجہ سے ناقابل استدلال ہے۔"}],[4953,"عطاء کہتے ہیں: کم سے کم جس میں ہاتھ کاٹا جائے گا ڈھال کی قیمت ہے، اور ڈھال کی قیمت اس وقت دس درہم تھی۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ایمن جن کی حدیث ہم نے اوپر ذکر کی ہے، میں نہیں سمجھتا کہ وہ صحابی تھے، ان سے ایک حدیث اور مروی ہے جو ہمارے خیال کی تائید کرتی ہے، (جو آگے آ رہی ہے)۔","الألباني: ضعيف مقطوع مخالف للمرفوع",{"u2":"حضرت عطاء نے فرمایا: کم از کم مقدار جس کی چوری میں ہاتھ کاٹا جاتا ہے ڈھال کی قیمت ہے۔ اور ڈھال کی قیمت ان دنوں دس درہم تھی۔\nابو عبدالرحمن (امام نسائی) نے فرمایا: وہ حضرت ایمن جن کی حدیث ہم اس سے پہلے (اس باب میں) ذکر کر چکے ہیں میرے خیال کے مطابق وہ صحابی نہیں۔ ان سے ایک اور حدیث مروی ہے جو ہماری بات کی دلیل ہے۔ (اور وہ حدیث یہ ہے، یعنی 4957)\nحضرت عطاء نے حضرت ایمن مولیٰ ابن زبیر یا مولیٰ زبیر سے بیان کیا وہ روایت کرتے ہیں حضرت تبیع سے اور وہ بیان کرتے ہیں حضرت کعب سے انہوں نے فرمایا: جو شخص وضو کرے اور اچھی طرح وضو کرے پھر عشاء کی نماز (باجماعت) پڑھے، پھر اس کے بعد چار رکعتیں پڑھے ان میں رکوع سجدہ پورا پورا کرے اور جو کچھ پڑھے، سوچ سمجھ کر پڑھے تو یہ چار رکعات اس کے لیے (ثواب کے لحاظ سے) لیلۃ القدر کی طرح بن جائیں گی۔","f2":"حضرت عطاء نے فرمایا: کم از کم مقدار جس کی چوری میں ہاتھ کاٹا جاتا ہے ڈھال کی قیمت ہے۔ اور ڈھال کی قیمت ان دنوں دس درہم تھی۔\nابو عبدالرحمن (امام نسائی) نے فرمایا: وہ حضرت ایمن جن کی حدیث ہم اس سے پہلے (اس باب میں) ذکر کر چکے ہیں میرے خیال کے مطابق وہ صحابی نہیں۔ ان سے ایک اور حدیث مروی ہے جو ہماری بات کی دلیل ہے۔ (اور وہ حدیث یہ ہے، یعنی 4957)\nامام نسائی رحمہ اللہ کا مقصد بالکل واضح ہے کہ حضرت عطاء کے استاد حضرت ایمن تابعی ہیں جو کبار تابعین سے بیان فرماتے ہیں، جیسے وہ اس روایت میں حضرت تبیع تابعی سے بیان کر رہے ہیں۔ اگر وہ صحابی ہوتے تو کسی صحابی سے یا رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے۔ باقی رہے صحابی رسول حضرت ایمن بن ام ایمن تو ان سے حضرت عطاء کی ملاقات ہی نہیں۔ آئندہ حدیث بھی اسی بات کی تائید کے لیے ذکر فرما رہے ہیں۔"}],[4954,"کعب الاحبار کہتے ہیں کہ جس نے وضو کیا اور خوب اچھی طرح وضو کیا پھر نماز ادا کی، (عبدالرحمٰن کی روایت میں ہے، پھر نماز عشاء کی جماعت میں شریک ہوا)، پھر اس کے بعد چار رکعتیں رکوع اور سجدہ کے اتمام کے ساتھ اور پڑھیں، اور جو کچھ قرأت کیا اسے سمجھا بھی تو یہ سب اس کے لیے شب قدر کے مثل باعث اجر ہوں گی۔","الألباني: مقطوع موقوف"],[4955,"کعب الاحبار کہتے ہیں کہ جس نے وضو کیا اور اچھی طرح وضو کیا پھر عشاء جماعت کے ساتھ پڑھی، پھر اسی جیسی چار رکعتیں قرأت اور رکوع، سجدہ کے اتمام کے ساتھ پڑھیں، تو اسے شب قدر جیسا اجر ملے گا۔","الألباني: مقطوع موقوف",{"u2":"حضرت ایمن مولیٰ ابن عمر حضرت تبیع سے اور وہ حضرت کعب سے روایت کرتے ہیں انہوں نے فرمایا: جو شخص وضو کرے اور اور اچھی طرح وضو کرے، پھر عشاء کی نماز با جماعت پڑھے پھر بعد میں اس جیسی چار رکعتیں اور پڑھے ان میں (توجہ کے ساتھ) قراءت کرے اور رکوع سجدے مکمل کرے، اسے لیلۃ القدر کی عبادت کے برابر ثواب ملے گا۔\nحضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہما) بیان کرتے ہیں کہ ڈھال کی قیمت رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں دس درہم تھی۔","f2":"حضرت ایمن کے بارے میں اختلاف ہے کہ حضرت زبیر کے مولیٰ تھے یا ابن زبیر کے یا ابن عمر کے، بہر حال یہ تابعی تھے، حبشی تھے، مکی تھے۔(تفصیل کے لیے دیکھیے: 4951، 4957) نیز مذکورہ بالا دونوں روایات کی سند اگرچہ حسن ہے لیکن یہ مقطوع ہیں، یعنی تابعی کا قول ہے جو قطعا حدیث رسول کی حیثیت اختیار نہیں کرسکتا۔\nمحقق کتاب کا اس روایت کو علی الاطلاق حسن کہنا درست نہیں کیونکہ صحیح احادیث کی مخالفت کی وجہ سے یہ روایت شاذ ہے۔ صحیح روایات میں ڈھال کی قیمت تین درہم مذکور ہے۔"}],[4956,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ ڈھال کی قیمت رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں دس درہم تھی۔","الألباني: شاذ"],[4957,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: ہاتھ کتنے میں کاٹا جائے گا؟ آپ نے فرمایا: \"درخت پر لگے پھل میں نہیں کاٹا جائے گا، لیکن جب وہ کھلیان میں پہنچا دیا جائے تو ڈھال کی قیمت میں ہاتھ کاٹا جائے گا، اور نہ پہاڑ پر چرنے والے جانوروں میں کاٹا جائے گا البتہ جب وہ اپنے رہنے کی جگہ میں آ جائیں تو ڈھال کی قیمت میں کاٹا جائے گا\" ۱؎۔\n§وضاحت\n۱؎: درخت پر لگے پھلوں اور میدان میں چرتے جانوروں کی چوری پر ہاتھ اس لیے نہیں کاٹا جائے گا کہ یہ سب \" حرز \" :(محفوظ مقام ) میں نہیں ہوتے، کھلیان اور باڑہ حرز :(محفوظ مقام ) ہوتے ہیں، یہاں سے چوری پر ہاتھ کاٹا جائے گا۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا (عبداللہ بن عمرو رضی اللہ عنہما) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ ہاتھ کتنے (مال) میں کاٹا جائے گا؟ آپ نے فرمایا: ’’ درخت پر لگے ہوئے پھل توڑنے سے ہاتھ نہیں کاٹا جائے گا، البتہ جب پھل توڑ کر ڈھیر لگا دیا گیا ہو تو ڈھال کی قیمت کے برابر چوری کرنے سے ہاتھ کاٹا جائے گا۔ (اسی طرح) پہاڑ پر چرتی بکری چرانے سے ہاتھ نہیں کاٹا جائے گا، البتہ بکری باڑے میں آجائے تو پھر اسے چرانے میں ہاتھ کاٹا جائے گا بشرطیکہ اس کی قیمت ڈھال سے کم نہ ہو۔","f2":"حدیث کا مطلب یہ ہے کہ غیر محفوظ چیز چرانے پر قطع ید کی سزا نافذ نہیں ہوگی، البتہ کوئی اور سزا دی جاسکتی ہے جو حاکم وقت کی صوابدید پر موقوف ہے۔ درخت پر لگا ہوا پھل محفوظ تصور نہیں کیا جاتا، اسی طرح چرتا ہوا جانور، خواہ مملوکہ زمین میں ہی چر رہا ہو۔ ہاں، پھل توڑنے کے بعد کھلیان میں لگا دیا جائے تو وہ محفوظ ہو جاتا ہے۔ اب اس کو چرانے پر ہاتھ کاٹ دیا جائے گا۔ یہ ضابطہ ہے قطع ید کا کہ کسی غیر محفوظ چیز کو چرانے پر ہاتھ نہیں کاٹا جاسکتا، البتہ مالک پاس ہو تو چیز کو محفوظ تصور کیا جائے گا، خواہ وہ کھلے میدان یا کھیتوں میں پڑی ہو۔ (مزید دیکھیے حدیث: 4885)"}],[4958,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے درخت پر لٹکے ہوئے پھلوں کے متعلق سوال کیا گیا تو آپ نے فرمایا:\"جس ضرورت مند نے اسے کھا لیا اور جمع کر کے نہیں رکھا تو اس پر کوئی گناہ نہیں اور جو اس میں سے کچھ لے جائے تو اس پر اس کا دوگنا تاوان اور سزا ہے، اور جو اسے کھلیان میں جمع کیے جانے کے بعد چرائے اور وہ ڈھال کی قیمت کو پہنچ رہا ہو تو پھر اس کا ہاتھ کاٹا جائے گا\"۔","الألباني: حسن",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے درخت پر لگے ہوئے پھل کو توڑنے کے بارے میں پوچھا گیا تو آپ نے فرمایا:\n’’ اگر تو کوئی حاجت مند پھل توڑ کر کھا لے، ساتھ نہ لے جائے تو اسے کچھ نہیں کہا جائے گا۔ اور اگر وہ پھل ساتھ بھی لے جائے تو اس سے دگنی قیمت وصول کی جائے گی اور سزا بھی دی جائے گی۔ اور اگر کھلیان میں رکھنے کے بعد کسی شخص نے کوئی پھل اٹھا لیا اور اس کی قیمت ڈھال کی قیمت کے برابر یا زائد ہو تو اس کا ہاتھ کاٹ دیا جائے گا۔ اور اگر ڈھال کی قیمت سے کم چرایا تو اس سے دگنی قیمت لے لی جائے گی اور اسے سزا بھی ملے گی۔‘‘","f2":"1۔ ’’ حاجت مند‘‘ اس سے مراد وہ شخص ہے جس کے پاس کھانے کی کوئی چیز نہ ہو۔ اتنی رقم بھی نہ ہو کہ کچھ خرید سکے۔ بھوک بھی شدید ہو۔ اس کے لیے پھل توڑ کر کھانا جائز ہے کیونکہ جان بچانا ضروری ہے۔ البتہ اگر مالک پاس ہو تو اس سے اجازت حاصل کرے۔ وہ اجازت نہ دے تو ایسا لاچار شخص بلااجازت بھی پھل توڑ کر کھا سکتا ہے۔ لیکن وہ صرف بھوک دور کرنے پر اکتفا کرے۔ ساتھ نہ لے کر جائے، نہ کپڑے میں ڈال کر نہ ہاتھ میں پکڑ کر۔ خبنہ میں یہ دونوں صورتیں داخل ہیں۔\n2۔ ’’ دگنی قیمت‘‘ اصل قیمت تو خریدنے والے کو بھی دینا پڑتی ہے۔ اگر اس کو بھی اصل قیمت ہی ڈالیں تو پھر دونوں میں فرق کیا ہوا؟\n3۔ ’’ سزا بھی ‘‘ یعنی جسمانی سزا اور جرمانہ دونوں عائد کیے جائیں گے، اس لیے کہ بعض لوگ جسمانی سزا سے بہت بچتے ہیں، جرمانے کی پروا نہیں کرتے اور بعض لوگ کنجوس۔ ’’ دمڑی نہ جائے ‘ چاہے چمڑی جائے ‘‘ کا مصداق ہوتے ہیں، اس لیے دونوں قسم کی سزا جاری فرمائی گئی تاکہ ہر قسم کے لوگ عبرت حاصل کریں۔ کھلیان سے پھل اٹھانا ضرورت کے لیے بھی جائز نہیں کیونکہ وہ حقیقتاً چوری ہے۔ اگر وہ مقرر حد تک پہنچ گیا تو ہاتھ کاٹ دیا جائے گا۔\nکم ہو گا تو دگنی قیمت اور سزا دونوں بھگتنی پڑیں گی۔"}],[4959,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ مزینہ کے ایک آدمی نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! پہاڑ پر چرنے والے جانوروں کے(چوری ہونے کے) بارے میں آپ کا کیا خیال ہے؟ آپ نے فرمایا: (اگر کوئی ایسا جانور چوری کرے) تو اسے وہ جانور اور اس کے مثل ایک اور جانور دینا ہو گا اور سزا الگ ہو گی، لیکن چرنے والے جانوروں میں ہاتھ نہیں کاٹا جائے گا سوائے اس صورت میں کہ جانور اپنے رہنے کی جگہ میں لوٹ آئے اور اس کی قیمت ڈھال کی قیمت کے برابر ہو تو اس میں ہاتھ کاٹا جائے گا۔ اور جس کی قیمت ڈھال کی قیمت کو نہ پہنچی ہو تو اس میں دوگنا تاوان ہو گا اور سزا کے کوڑے الگ ہوں گے۔ وہ بولا: اللہ کے رسول! درخت میں لگے پھلوں کے بارے میں آپ کا کیا خیال ہے؟ آپ نے فرمایا: (اس کی چوری کرنے پر) وہ پھل اور اس کے ساتھ اتنا ہی اور پھل دینا ہو گا اور سزا الگ ہو گی۔ لیکن درخت پر لگے پھلوں میں ہاتھ نہیں کاٹا جائے گا سوائے اس صورت میں کہ وہ کھلیان تک لایا جا چکا ہو۔ لہٰذا جو کچھ وہ کھلیان سے لے اور اس کی قیمت ڈھال کی قیمت کے برابر ہو تو اس میں ہاتھ کاٹا جائے گا اور جس کی قیمت ڈھال کی قیمت کے برابر نہ ہو تو اس میں دوگنا تاوان ہو گا اور سزا کے کوڑے الگ ہوں گے ۱؎۔\n§وضاحت\n۱؎: اس لیے کہ درخت کی کھجوریں اور گابے \" حرز \" میں نہیں ہوتے۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ مزینہ قبیلے کا ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہا: اے اللہ کے رسول! پہاڑ پر چرنے والی بکری (یا کسی اور جانور) کے بارے میں آپ کا کیا خیال ہے؟ آپ نے فرمایا: ’’ دگنی قیمت اور جسمانی سزا۔ جانور کی چوری میں ہاتھ نہیں کاٹا جائے گا، الا یہ کہ وہ جانور باڑے میں ہو اور اس کی قیمت ڈھال کے برابر یا اس سے زائد ہو تو پھر اس کی چوری پر ہاتھ کاٹ دیا جائے گا اور اگر اس کی قیمت اس سے کم ہو تو دگنی قیمت لی جائے گی اور بطور سزا کوڑے لگائے جائیں گے۔‘‘ اس آدمی نے کہا: اے اللہ کے رسول! درخت پر لگے ہوئے پھل کے بارے میں آپ کا کیا خیال ہے؟ آپ نے فرمایا: ’’ اس میں بھی دگنی قیمت اور جسمانی سزا۔ درخت پر لگے ہوئے پھل کی چوری میں ہاتھ نہیں کاٹا جائے گا۔ البتہ اگر پھل کھلیان میں لگا دیا جائے، اس کے بعد چوری ہو اور اس کی قیمت ڈھال کے برابر یا زائد ہو تو ہاتھ کاٹا جائے گا۔ اگر پھل ڈھال کی قیمت سے کم ہو تو چور سے دگنی قیمت لی جائے گی اور جسمانی سزا کے طور پر کوڑے بھی لگائے جائیں گے۔‘‘","f2":"معلوم ہوا کہ چوری بہرصورت جرم ہے۔ اتنی بات ہے کہ اگر معمولی ہو تو ہاتھ نہ کٹے گا مگر مالی اور جسمانی سزا نافذ ہو گی۔ اور اگر نصاب کو پہنچ جائے تو ہاتھ کاٹ دیا جائے گا بشرطیکہ چیز محفوظ ہو۔ غیر محفوظ چیز کی صورت میں بھی مالی اور جسمانی سزا ہوگی، البتہ محتاج آدمی مستثنیٰ ہے جیسا کہ سابقہ حدیث میں صراحت کے ساتھ بیان ہوا ہے۔"}],[4960,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"نہ پھلوں کے چرانے میں ہاتھ کاٹا جائے گا اور نہ کھجور کے گابے کے چرانے میں\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ پھل اور گری (کھجور کے مغز) میں ہاتھ نہیں کاٹا جائے گا۔‘‘","f2":"1۔ پھل سے مراد وہ پھل ہے جو درخت پر لگا ہو جیسا کہ پہلے وضاحت گزر چکی ہے۔\n2۔ اس قسم کے پھل میں ہاتھ نہ کٹنے کا یہ مطلب نہیں کہ اسے کوئی اور سزا بھی نہیں دی جائے گی، بلکہ دگنی قیمت اور جسمانی سزا عائد کی جائے گی۔\n3۔ ’’ کثر‘‘ سے مراد کھجور کی وہ نرم گری اور مغز ہے جو اس کے تنے کے اوپر کنارے میں ہوتا ہے۔"}],[4961,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"نہ پھل میں ہاتھ کاٹا جائے گا اور نہ کھجور کے گابے کے چرانے میں\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ پھل اور گابھے (گودے) میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4962,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ ہم زمین میں بٹائی کا معاملہ کیا کرتے تھے، ہم اسے تہائی اور چوتھائی اور غلہ کی مقررہ مقدار کے بدلے کرائیے پر دیتے تھے۔ سعید نے بھی اسے یعلی بن حکیم سے روایت کیا ہے۔\nرافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"نہ پھل کے چرانے میں ہاتھ کاٹا جائے گا، اور نہ گابے کے چرانے میں\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ پھل اور گابھے (کی چوری) میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4963,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں بٹائی کا معاملہ کرتے تھے، پھر کہتے ہیں کہ ان کے ایک چچا ان کے پاس آئے اور بولے: مجھے رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسی چیز سے روک دیا ہے جو ہمارے لیے نفع بخش اور مفید تھی لیکن اللہ اور اس کے رسول کی اطاعت ہمارے لیے زیادہ نفع بخش اور مفید ہے۔ ہم نے کہا: وہ کیا چیز ہے؟ کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جس کی کوئی زمین ہو تو وہ اس میں کھیتی کرے یا اسے اپنے بھائی کو کھیتی کرنے کے لیے (بلا کرایہ) دیدے، لیکن اسے تہائی، چوتھائی اور معینہ مقدار غلہ کے بدلے کرائے پر نہ دے\"۔ اسے حنظلہ بن قیس نے بھی رافع رضی اللہ عنہ سے روایت کیا ہے اور (حنظلہ سے روایت کرنے والے) ربیعہ کے تلامذہ نے ربیعہ سے روایت کرنے میں اختلاف کیا ہے۔\nرافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پھل کے چرانے میں ہاتھ کاٹا جائے گا نہ گابے کے چرانے میں\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ پھل اور گابھے (کی چوری) میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4964,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میرے چچا نے مجھ سے بیان کیا کہ وہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اس کے بدلے زمین کو بٹائی پر دیتے تھے جو پانی کی کیاریوں پر پیدا ہوتا تھا اور تھوڑی سی اس پیداوار کے بدلے جو زمین کا مالک مستثنی (الگ) کر لیتا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس سے روک دیا۔ میں نے رافع رضی اللہ عنہ سے کہا: تو دینار اور درہم سے کرائے پر دینا کیسا تھا؟ رافع رضی اللہ عنہ نے کہا: دینار اور درہم کے بدلے دینے میں کوئی حرج نہیں۔ اوزاعی نے لیث کی مخالفت کی ہے، (ان کی روایت آگے آ رہی ہے جس میں \"چچا\" کا ذکر نہیں ہے)۔\nصحابی رسول عمیر رضی اللہ عنہ بیان کرتے ہیں کہ ایک شخص نے عرض کیا: اللہ کے رسول! کبائر کیا ہیں؟ آپ نے فرمایا: \"وہ سات ہیں: ان میں سب سے بڑا گناہ اللہ کے ساتھ غیر کو شریک کرنا، ناحق کسی کو قتل کرنا اور دشمن سے مقابلے کے دن میدان جنگ چھوڑ کر بھاگ جانا ہے\"، یہ حدیث مختصر ہے۔\nرافع بن خدیج رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"نہ پھل کے چرانے میں اور نہ گابے کے چرانے میں ہاتھ کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ پھل اور گابھے میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4965,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہ پھل کے چرانے میں، اور نہ ہی گابے کے چرانے میں ہاتھ کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ پھل اور گابھے میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4966,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہ پھل چرانے میں اور نہ گابا چرانے میں ہاتھ کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ پھل اور گابھے (کی چوری) میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4967,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"نہ پھل چرانے میں اور نہ «کثر» چرانے میں ہاتھ کاٹا جائے گا\"، اور «کثر» کھجور کے گابا (خوشہ) کو کہتے ہیں۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ پھل اور گابھے (کی چوری) میں ہاتھ نہیں کاٹا جائے گا۔‘‘ اور گھابھا کھجور کے مغز کو کہتے ہیں۔"}],[4968,"رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پھل چرانے میں، اور نہ ہی گابا چرانے میں ہاتھ کاٹا جائے گا\"۔ ابوعبدالرحمٰن(نسائی) کہتے ہیں: یہ غلط ہے، میں ابومیمون کو نہیں جانتا ۱؎۔\n§وضاحت\n۱؎: یعنی ابو میمون مجہول راوی ہیں۔","الألباني: صحيح لغيره",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ پھل اور گابھے (گودے) میں ہاتھ نہیں کاٹا جائے گا۔‘‘\nابو عبدالرحمن (امام نسائی رحمہ اللہ) بیان کرتے ہیں کہ یہ غلط ہے۔ ابو میمون کو میں نہیں پہچانتا۔","f2":"امام نسائی رحمہ اللہ کے کلام کا مطلب یہ ہے کہ ’’ ابو میمن‘‘ مجہول ہے۔ میں نہیں جانتا کہ یہ کو ن ہے، لہذا یہ خطا ہے کیونکہ معروف روایت کی سند جو کہ حفاظ محدثین، مثلا: لیث اور سفیان ثوری کی ہے، اس طرح ہے: عن محمد بن يحي بن حبان عن عمه واسع عن رافع بن خديج اور: عن يحي بن سعيد عن محمد بن يحي بن حبان عن عمه أن رافع بن خديج .......، جیسا کہ مذکورہ روایت سے پہلے والی دو روایتیں ہیں۔ ابو میمون والی سند میں خطا اور غلطی ہے۔ واللہ اعلم، تاہم متن حدیث صحیح ہے کیونکہ دوسری صحیح اسناد سے بھی اسی طرح مروی ہے۔"}],[4969,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"نہ پھل چرانے میں ہاتھ کاٹا جائے گا، نہ گابا چرانے میں\"۔","الألباني: صحيح",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’ پھل اور گابھے میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4970,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ کو فرماتے سنا: \"نہ تو پھل چرانے میں ہاتھ کاٹا جائے گا، اور نہ ہی گابا چرانے میں\"۔","الألباني: صحيح لغيره",{"u2":"حضرت رافع بن خدیج رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’ پھل اور گابھے (کی چوری) میں ہاتھ نہیں کاٹا جائے گا۔‘‘"}],[4971,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"امانت میں خیانت کرنے والے، علانیہ لوٹ کر لے جانے اور اچک لینے والے کا ہاتھ نہیں کاٹا جائے گا\" ۱؎۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) اسے سفیان نے ابو الزبیر سے نہیں سنا۔ (اس کی دلیل اگلی سند ہے)\n§وضاحت\n۱؎: خیانت، اچک لینے اور چھین لینے میں اسی لیے ہاتھ کاٹنا نہیں ہے کہ ان سب کے اندر یہ ممکن ہے کہ ان کو انجام دینے والوں پر آسانی سے اور جلد قابو پایا جا سکتا ہے اور گواہی قائم کی جا سکتی ہے، برخلاف چوری کے، اس لیے کہ چوری کا جرم زیادہ سنگین ہے۔","الألباني: صحيح لم يسمعه سفيان من أبي الزبير",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ خیانت کرنے والے، لوٹنے والے اور جھپٹ کر چھین لینے والے کا ہاتھ نہیں کاٹا جائے گا۔‘‘\nسفیان (ثوری) نے ابو الزبیر سے نہیں سنا۔","f2":"1۔ امام نسائی رحمہ اللہ یہ بتانا چاہتے ہیں کہ یہ سند منقطع ہے کیونکہ سفیان ثوری نے ابو الزبیر سے براہ راست نہیں سنا بلکہ سفیان ثوری اور ابو الزبیر کے درمیان ابن جریج کا واسطہ ہے جیسا کہ اگلی روایت میں ہے۔\n2۔ امام نسائی رحمہ اللہ نے اس روایت اور اس کے بعد والی روایت کی سند کو اگرچہ منقطع کہا ہے لیکن یہ دونوں روایتیں صحیح ہیں۔ شیخ البانی رحمہ اللہ نے ابن جریج کے ابوالزبیر سے مذکورہ حدیث کے سماع کی بابت بہت عمدہ اور نفیس محققانہ بحث کی ہے۔ اس تحقیق سے ضعف والی وجہ ہی ختم ہو جاتی ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی اللانیوبی: 37؍99۔101)۔\n3۔ کسی کے پاس امانت رکھی ہو اور وہ اسے دبا جائے تو اسے خائن کہتے ہیں۔ زبردستی جاگتی آنکھوں کے سامنے مال اٹھانے والے کو منتھب (ڈاکو) کہتے ہیں اور چالاکی کے ساتھ ہاتھوں سے جھپٹ کر بھاگ جانے والے کو مختلس کہتے ہیں۔ ایسا کام کرنے والے پر چور کی تعریف صادق نہیں آتی، اس لیے ان پر چوری والی حد نہیں لگے گی۔ واللہ اعلم\n4۔ ان صورتوں میں کسی کا مال حاصل کیا جاتا ہے مگر اس میں چوری کا وصف نہیں پایا جاتا۔ چوری یہ ہے کہ کسی کا محفوظ مال چپکے سے اٹھالیا جائے اور اسے پتا نہ چلے۔ چونکہ اس صورت میں چور کا پتا نہیں چلتا، لہذا اس کا نقصان معاشرے میں زیادہ ہے، لہذا اس پر ہاتھ کاٹنے کی سزا مشروع کی گی بخلاف پہلی صورتوں کے کہ ان میں فریق ثانی کا علم ہوتا ہے اور کسی حکومتی ادارے کی مدد سے مال واپس لیا جاسکتا ہے، لہذا ان کا حکم مختلف ہے لیکن اس کا یہ مطلب نہیں کہ انہیں کوئی سزا نہیں دی جائے گی بلکہ کوئی اور سزا جو حاکم مناسب سمجھے، نافذ کرے گا، چاہے وہ ہاتھ کاٹنے سے سخت ہی ہو، مثلاً: ڈاکو چونکہ مسلح ہو کر ڈاکا ڈلتا ہے اس میں بے گناہ لوگوں کی جان جانے کا خطرہ ہوتا ہے اس لیے اسے سزائے موت بھی دی جاسکتی ہے جیسا کہ آیت محاربہ میں بیان ہوا۔ (تفصیل کے لیے دیکھیے، حدیث: 4028 اور 4029 کے فوائد)"}],[4972,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"امانت میں خیانت کرنے والے، لوٹ لے جانے اور اچک لینے والے کا ہاتھ نہیں کاٹا جائے گا\"۔ (ابوعبدالرحمٰن نسائی کہتے ہیں:) اسے ابن جریج نے بھی ابو الزبیر سے نہیں سنا، (اس کے متعلق مؤلف کی وضاحت آگے آ رہی ہے)۔","الألباني: صحيح ولم يسمعه أيضا ابن جريج من أبي الزبير",{"u2":"حضرت جابر رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خیانت کرنے والے،لوٹ ڈالنے والے اور جھپٹنے والے کا ہاتھ نہیں کاٹا جائے گا۔،،\nابن جریج نے بھی ابو لزبیر سے نہیں سنا۔"}],[4973,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اچک کر لے جانے والے کا ہاتھ نہیں کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سےمروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:’’جھپٹ مار کر چھین لے جانے والے کاہاتھ نہیں کا ٹا جائے گا۔،،"}],[4974,"جابر رضی اللہ عنہ کہتے ہیں کہ کسی خیانت کرنے والے کا ہاتھ نہیں کاٹا جائے گا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اس حدیث کو ابن جریج سے: عیسی بن یونس، فضل بن موسی، ابن وہب، محمد بن ربیعہ، مخلد بن یزید اور سلمہ بن سعید، یہ بصری ہیں اور ثقہ ہیں، نے روایت کیا ہے۔ ابن ابی صفوان کہتے ہیں - اور یہ سب اپنے زمانے کے سب سے بہتر آدمی تھے: ان میں سے کسی نے «حدثنی ابوالزبیر» یعنی \"مجھ سے ابوالزبیر نے بیان کیا\" نہیں کہا۔ اور میرا خیال ہے ان میں سے کسی نے ابوالزبیر سے اسے سنا بھی نہیں ہے، واللہ اعلم ۱؎۔\n§وضاحت\n۱؎: لیکن اگلی سند کے \" مغیرہ بن مسلم \" کا ابوالزبیر سے سماع ثابت ہے، نیز اس حدیث کے دیگر صحیح شواہد بھی ہیں۔","الألباني: ضعيف والصحيح مرفوع",{"u2":"حضرت جابر رضی اللہ عنہ نے فرمایا: خیانت کرنے والے کا ہاتھ نہیں کاٹا جائے گا۔\nابو عبد الرحمٰن (امام نسائی رحمہ اللہ) نے فرمایا: عیسیٰ بن یونس، فضل بن موسیٰ، ابن وہب، محمد بن ربیعہ، مخلد بن یزید اور سلمہ بن سعید جو کہ بصری اور ثقہ ہیں (اور جن کے بارےمیں محمد بن عثمان)ابن ابو صفوان نے کہا ہےکہ وہ (سلمہ بن سعید)اپنے زمانے کے بہترین شخص تھے، ان سب نےابن جریج سےیہ (مذکورہ) روایت بیان کی ہے لیکن ان (چھ جلیل القدر اور ثقہ اہل علم میں سے کسی ایک نے بھی ’’حدثنی ابو الزبیر،،نہیں کہا۔اور میرا نہیں خیال کہ اس (ابن جریج) نے ابو الزبیر سے سنا ہو۔واللہ اعلم .","f2":"امام نسائی رحمہ اللہ کے کلام کا ما حاصل یہ ہے کہ یہ روایت سندا منقطع ہے۔ انھوں نے ابو الزبیر سےابن جریج کے، یہ روایت سننے کی نفی کی ہے۔ امام نسائی کا کہنا ہے کہ مذکورہ چھ جید اہل علم نے ابن جریج سے یہ روایت تو بیان کی ہے لیکن ان میں سےکسی نے بھی ابو الزبیر سے ان کے سماع (سننے) کی تصریح نہیں کی، اس لیے یہ روایت منقطع، یعنی ضغیف ہے۔یہ ہے امام نسائی رحمہ اللہ کا رجحان لیکن مذکورہ چھ اہل علم کا ابن جریج کے ابو الزبیر سے مذکورہ حدیث کے سماع کی تصریح سے ان محدثین کےاثبات تصریح کی نفی نہیں سکتی جنھوں نے ابن جریج کے ابو الزبیر سے، مذکورہ حدیث سننے کی تصریح کی ہے۔ ویسے بھی اثبات کرنے والا نفی کرنے والے سےمقدم ہوتا ہے کیو نکہ جس شخص کو بات یا د ہوتی ہےوہاس شخص کے مقابلے میں حجت ہوتا ہےجسے بات یاد نہیں ہوتی۔یہ مسلمہ اصول ہے۔ محقق العصر شیخ ناصر الدین البانی رحمہ اللہ نے صحیح سند سے ابن جریج کے ابو الزبیر سےسماع کی تصریح کی ہے جیسا کہ پہلے بھی ارشاد کیا گیا ہے۔ تفصیل کے لیے ملاحظہ فرمائیں: (ذخیرۃ العقبیٰ شرح سنن النسائی للا تیوبی: 37/99۔101،والمصنف لعبد الرزاق: 10/206) مصنف عبد الرزاق کے الفاظ توسماع میں بالکل اور دوٹوک ہیں جو یہ ہیں: عن ابن جریج، قال:قال لی ابو الزبیر، یعنی ابن جریج نے کہا ہےکہ مجھے ابو الزبیر نے کہا، پھر مذکورہ روایت بیان کی، لہذا جب صحیح طور پر تحدیث وسماع کی صراحت موجود ہے تو یقینا اسے ہی تر جیح حاصل ہو گی۔"}],[4975,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہ تو اچک کر لے جانے والے کا، نہ کسی لوٹنے والے کا، اور نہ ہی کسی خائن کا ہاتھ کاٹا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:’’جھپٹ مار کر چھپنٹے والے،لوٹ ڈالنے والے (ڈاکو) اورخیانت کرنے والے کا ہاتھ نہیں کاٹا جائے گا۔،،"}],[4976,"جابر رضی اللہ عنہ کہتے ہیں کہ کسی خائن کا ہاتھ نہیں کاٹا جائے گا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اشعث بن سوار ضعیف ہیں۔","الألباني: ضعيف والصحيح مرفوع",{"u2":"حضرت جابر رضی اللہ عنہ سےمروی ہے کہ خیانت کرنے والے کو ہاتھ کاٹنے کی سزا نہیں دی جاسکتی۔\nابو عبدالرحمٰن (امام نسائی) رحمہ اللہ نے فرمایا: اشعث بن سوار ضعیف ہے۔","f2":"امام نسائی رحمہ اللہ یہ کہنا چاہتے ہیں کہ اشعث بن سوار کی حضرت جابر سے بیان کر دہ موقوف روایت ضعیف ہے۔ اس کی ایک وجہ تو یہ ہے کہ اشعث بن سوار خود ضعیف راوی ہے۔ محدثین عظام اس کی روایت کو قابل حجت نہیں سمجھتے۔دوسری وجہ یہ ہے کہ اشعث نے اس روایت کو،ثقات کی مخالفت کرتے ہوئے موقوف بیان کیا ہے جبکہ دیگر ثقہ راوی اسے مرفوع بیان کرتے ہیں،لہذا مخالفت ثقات کی وجہ سے یہ روایت منکر (ضعیف)ٹھہری۔واللہ اعلم .یہ مسئلہ سند کی حد تک ہے، تاہم اس سند کے ضعیف ہونےکے باوجود مسئلہ بعنیہ اسی طرح ہے جس طرح دیگر صحیح احادیث میں بیان ہوا کہ خائن،لیڑے اورجھپٹا مار کر چیز چھیننے والے کا ہاتھ نہیں کاٹا جائے گا۔"}],[4977,"حارث بن حاطب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا تو آپ نے فرمایا: \"اسے قتل کر دو\"، لوگوں نے کہا: اللہ کے رسول! اس نے تو چوری کی ہے؟ آپ نے فرمایا: \"اسے قتل کر دو\"۔ لوگوں نے کہا: اللہ کے رسول! اس نے تو چوری کی ہے، آپ نے فرمایا: \"اس کا ہاتھ کاٹ دو\"۔ اس نے پھر چوری کی تو اس کا پاؤں کاٹ دیا گیا، پھر اس نے ابوبکر رضی اللہ عنہ کے عہد میں چوری کی یہاں تک کہ چاروں ہاتھ پاؤں کاٹ دیے گئے، اس نے پھر پانچویں بار چوری کی تو ابوبکر رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہی اسے اچھی طرح جانتے تھے کہ انہوں نے اسے قتل کرنے کا حکم دیا تھا، پھر انہوں نے اسے قریش کے چند نوجوانوں کے حوالے کر دیا تاکہ وہ اسے قتل کر دیں۔ ان میں عبداللہ بن زبیر رضی اللہ عنہما بھی تھے، وہ سرداری چاہتے تھے، انہوں نے کہا: مجھے اپنا امیر بنا لو، تو ان لوگوں نے انہیں اپنا امیر بنا لیا، چنانچہ جب چور کو انہوں نے مارا تو سبھوں نے مارا یہاں تک کہ اسے مار ڈالا ۱؎۔\n§وضاحت\n۱؎: ابوہریرہ اور جابر رضی اللہ عنہم سے بھی اس طرح کی حدیث مروی ہے، لیکن کسی بھی امام کے نزدیک اس پر عمل نہیں ہے، وجہ اس کا منسوخ ہو جانا ہے جیسا کہ امام شافعی نے کہا ہے۔","الألباني: منكر",{"u2":"حضرت حارث بن حاطب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا۔ آپ فرمایا:’’اسے قتل کردو،، لوگوں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم اس نے تو چور ی کی ہے؟آپ نے فرمایا: ’’اسے قتل کردو۔،، لوگوں نے پھر کہا:اللہ کے رسول! اس نے تو صرف چوری کی ہے؟ آپ نے فرمایا:’’ ا س کا ہاتھی کاٹ دو۔،، اس نے پھر چوری کر لی۔ پھر اس کا پاؤں کاٹ دیا گیا۔ پھر اس نے حضرت ابو بکر رضی اللہ عنہ کے دور میں چوری کر لی حتیٰ کہ ایک ایک کر کے اس کے چاروں ہاتھ پاؤں کاٹ دیے گئے۔پھر اس نے پانچویں دفعہ چوری کرلی۔ حضرت ابو بکر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کواس (کی حثییت کا خوف علم تھا۔تبھی تو آپ نے (پہلی دفعہ ہی فرما یا تھا:’’اسے قتل کردو۔،،پھر حضرت ابوبکر رضی اللہ عنہ نے اسے چند قریشی نوجوانوں کے سپرد کردیا اسے قتل کردیں۔ان نوجوانوں میں حضرت عبد اللہ بن زبیر رضی اللہ عنہ بھی شامل تھے۔ وہ حکومت کے بڑے شائق تھے۔ وہ کہنے لگے: تم مجھےاپنا (وقتی) امیر بنا لو۔ انھوں نے ان کوامیر بنا لیا۔ جب وہ اسے مارتے تھے، تب دوسرے مارتے تھے حتیٰ کہ اس طرح انھوں نے اس چور کوقتل کر دیا۔","f2":"(1)’’اسے قتل کردو،، آپ کامقصود قتل کاحکم نہ تھا بلکہ یہ آپ کی پیش گوئی تھی کہ اس کانجام کار قتل ہو گا، جو اس کے حق میں پوری ہوئی۔یہ بھی ممکن ہے کہ آپ کو بذریعہ وحی بتایا گیا ہو کہ یہ شخص باز نہیں آئے گا اور بالآخر اسے قتل کرنا پڑے گا،اس لیے آپ نے پہلی بار ہی قتل کاحکم دیا۔ صحابہ کرام رضی اللہ عنہم نے آپ کے حکم کی تعمیل میں تردد اس لیے کیا کہ آپ صلی اللہ علیہ وسلم نے خود چور کی سزا ہاتھ کاٹنا بتائی تھی۔وہ سمجھے کہ آپ کو اس کے کا جرم صحیح اندازہ نہیں ہوا، اس لیے صحابہ نے جب اس کے جرم کی دوبارہ وضاحت کی تو آپ نے اس کا ہاتھ کاٹنے کا حکم دیا۔\n(2)’’پاؤں کاٹ دیا گیا،، قرآن مجید میں چوری کی سزا میں صرف ہاتھ کاٹنے کا ذکر ہے،اس لیے بعض لوگ چوری کی سزا میں پاؤں کاٹنے کے قائل نہیں لیکن جمہور اہل علم پاؤں کاٹنے کے قائل ہیں کہ دوسری چوری پر بایا ں پاؤں کاٹ دیا جائے۔پھر چوری کرلے تو بایاں ہاتھ اور پھر چوری کرے تو دایاں پاؤں۔ اگر پانچویں دفعہ چوری کرے تو اسے جیل میں ڈال دیاجائے۔بعض پانچویں دفعہ چوری پر قتل کے قائل ہیں جیسا کہ اس حدیث میں ہے۔ بعض اہل عمل ایک ہاتھ اور ایک پاؤں کے بعد قطع کے قائل نہیں کیونکہ اس طرح وہ بالکل اپاہج ہو جائے گا اور اپنے کام کاج کے قابل نہیں رہے گا۔ نہ کھا پی سکے گا، نہ استنجا کرسکے گا اور نہ دوسرے کام ہی کر سکے گا۔آخر یہ کام کو ں کرےگا؟جمہور اہل علم کی دلیل آیت محاربہ بھی ہے۔ اس میں فسادی لوگوں کے لیے ہاتھ پاؤن کاٹنےکا صریح ذکر ہے۔(او تقطع ایدیھم وارجلھم من خلاف) (المائدۃ5:33) عقلا بھی ہاتھ پاؤں کا حکم ایک ہے،لہذا جمہور کامسلک ہی صحیح ہے۔"}],[4978,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ایک چور رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ نے فرمایا: \"اسے مار ڈالو\"، لوگوں نے کہا: اس نے صرف چوری کی ہے؟ اللہ کے رسول! آپ نے فرمایا: \"(اس کا دایاں ہاتھ) کاٹ دو\"، تو کاٹ دیا گیا، پھر وہ دوسری بار لایا گیا تو آپ نے فرمایا: \"اسے مار ڈالو\"، لوگوں نے کہا: اللہ کے رسول! اس نے صرف چوری کی ہے؟ آپ نے فرمایا: \"(اس کا بایاں پاؤں) کاٹ دو\"، چنانچہ کاٹ دیا گیا، پھر وہ تیسری بار لایا گیا تو آپ نے فرمایا: \"اسے مار ڈالو\"، لوگوں نے کہا: اللہ کے رسول! اس نے صرف چوری کی ہے، آپ نے فرمایا: \"(اس کا دایاں پاؤں) کاٹ دو\"، پھر وہ چوتھی بار لایا گیا۔ آپ نے فرمایا:\"اسے مار ڈالو\"، لوگوں نے کہا: اللہ کے رسول! اس نے صرف چوری کی ہے، آپ نے فرمایا: \"(اس کا بایاں پاؤں) کاٹ دو\"، وہ پھر پانچویں بار لایا گیا تو آپ نے فرمایا: \"اسے مار ڈالو\"، جابر رضی اللہ عنہ کہتے ہیں: تو ہم اسے «مربد نعم» (جانور باندھنے کی جگہ) کی جانب لے کر چلے اور اسے لادا، تو وہ چت ہو کر لیٹ گیا پھر وہ اپنے ہاتھوں اور پاؤں کے بل بھاگا تو اونٹ بدک گئے، لوگوں نے اسے دوبارہ لادا اس نے پھر ایسا ہی کیا پھر تیسری بار لادا پھر ہم نے اسے پتھر مارے اور اسے قتل کر دیا، اور ایک کنویں میں ڈال دیا پھر اوپر سے اس پر پتھر مارے۔ ابوعبدالرحمٰن کہتے ہیں: یہ حدیث منکر ہے، مصعب بن ثابت حدیث میں زیادہ قوی نہیں ہیں ۱؎۔\n§وضاحت\n۱؎: لیکن شواہد سے تقویت پاکر یہ حدیث حسن ہے، لیکن منسوخ ہے۔","الألباني: حسن الإسناد",{"u2":"\"حضرت جابر رضی اللہ عنہ سے روایت ہے،انھوں نےفرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا۔ آپ نے فرمایا:’’اسے قتل کردو۔،، لوگوں نے کہا: اے اللہ کے رسول! اس نے صرف چوری کی ہے۔آپ نےفرمایا،’’ (اس کا دایا ں ہاتھ)کاٹ دو۔،، اس کا ہاتھ کاٹ دیا گیا۔پھر اسےدوبارہ (چوری کرنے پر)لا یا گیا۔آپ نے فرمایا:’’اسےقتل کردو۔،،لوگوں نے کہا: اے اللہ کے رسول! اس نے صرف چوری کی ہے۔ آپ نے فرمایا: ’’اس کا بایاں پاؤں کاٹ دو۔،،اسکا پاؤں کاٹ دیا گیا۔ تیسری مرتبہ پھر اسے لایا گیا۔آپ نے فرمایا:’’اسے قتل کردو۔،، لوگوں نے کہا: اے اللہ کے رسول! اس نے تو صرف چوری کی ہے۔آپ نے فرمایا:’’اس کو قتل کر دو۔،، لوگوں نے کہا:اے اللہ کے رسول! اس نے صرف چوری کی ہے۔ آپ نے فرمایا:اس کا (دایاں پاؤں)کاٹ دو۔ پانچویں بار پھر اسے لایا گیا تو آپ نے فرمایا:’’ اسے قتل کردو۔،، حضرت جابر رضی اللہ عنہ نے فرمایا:ہم اسے اٹھاکر اونٹوں کے ایک باڑے میں لےگئے تووہ چت لیٹ گیا۔ پھر اچانک اپنے (کٹے ہوئے) ہاتھوں اور پاؤں پربھاگ اٹھا۔ اونٹ۔(ڈرکر) بدکنے لگے۔ لوگوں نے بھاگ کر دوبارہ اس کو پکڑ لیا۔ اس نے پھی اسی طرح کیا۔پھر تیسری دفعہ اس کو پکڑ اتو ہم نے اس کو پتھر مار مار کر قتل کر دیا۔ پھر ہم نے اسے ایک کنوں میں ڈال دیا اور اوپر سے پتھر پھینک دیے۔\nالو عبد الرحمٰن (امام نسائی) رحمہ اللہ فرماتے ہیں کہ یہ حدیث منکر ہے۔اور مصعب بن ثابت حدیث میں قوی (اور مضبوط (نہیں۔\"","f2":"\"(1)’’ یہ حدیث منکر ہے،، یعنی اس کاروای ضعیف ہونےکےباوجود ثقہ راویوں کی مخالفت کرتا ہے۔\n(2) ’’ ہاتھوں اور پاؤں پر،، یعنی جانوروں کی طرح۔\n(3) محقق کتاب اور شیخ البانی رحمہ اللہ نےمذکورہ روایت کو دیگر شواہد کی بنا پر صحیح قرار دیا ہے۔\""}],[4979,"بسر بن ابی ارطاۃ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"سفر میں (چور کے) ہاتھ نہیں کاٹے جائیں گے\" ۱؎۔\n§وضاحت\n۱؎: ترمذی اور مسند احمد میں «السفر» کی جگہ «الغزو» :(یعنی: «غزوہ» ) ہے، لہٰذا اس حدیث میں بھی «سفر» سے مراد «غزو» ہو گا، اور«غزو» مراد لینے کی وجہ سے اس میں اور عبادہ بن صامت رضی اللہ عنہ کی مرفوع روایت «أقیموا الحدود فی السفر والحضر» میں کوئی تعارض باقی نہیں رہے گا۔ یعنی \" عبادہ رضی اللہ عنہ میں وارد لفظ «سفر» سے عام سفر مراد ہے \"۔","الألباني: صحيح",{"u2":"حضرت بسر بن ابی ارطاۃ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتےسنا:’’سفر میں چور کے ہاتھ نہ کا ٹے جائیں۔،،","f2":"(1)اس روایت میں سفر سےمراد جنگ کا سفر ہے۔جب دشمن کا علاقہ قریب ہو اور خطرہ کہ ہاتھ کاٹنے سے مشتعل ہو کہ کفار کے علاقے میں بھاگ جائے اور ان کے ساتھ مل کر مرتد ہو جائے گا۔مطلق سفر مراد نہیں کیونکہ حضرت عبادہ بن صامت سے روایت ہے کہ ’’ سفر وحضر میں حدود قائم کرو۔،، (مسنداحمد:5/316، الصحیحۃ للالبانی، حدیث:1972)نیز سفر میں حد نہ لگانے کو ئی وجہ نہیں۔شریعت کہ حد بالکل ساقط کر دی جائے بلکہ جب سفر سے واپسی ہوگی تو حد لگائی جائےگی کیونکہ شریعت کی مقررہ حدود ساقط نہیں ہو سکتیں۔\n(3)حدیث سےمعلوم ہوا کہ حدود کے نفاذ میں انتہائی دو اندیشی اور احتیاط لازم ہے۔ مگر حد کےنفاذ سے نقصان عظیم کا خطرہ ہوتو وقتی طور پر اسے مؤخر کیا جا سکتا ہے۔"}],[4980,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام چوری کرے تو اسے بیچ دو چاہے اس کی قیمت آدھا درہم ہی کیوں نہ ہو\"۱؎۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: عمر بن ابی سلمہ حدیث میں قوی نہیں ہیں۔\n§وضاحت\n۱؎: یہ حدیث نہ تو صحیح ہے اور نہ ہی باب سے اس کا کوئی ظاہری مناسبت ہے۔","الألباني: ضعيف",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ جب کوئی غلام چوری کر لے تو اسے بیچ دو اگر چہ نصف قیمت پر بکے۔،،\nابو عبدالرحمٰن (امام نسائی)رحمہ اللہ بیان کرتے ہیں کہ (حدیث کا روای) عمر بن ابو سلمہ حدیث میں قوی نہیں۔","f2":"(1)’’چوری کرلے،، یعنی مالک کی چوری کرے چونکہ کسی دوسرے کی چوری کرےگا تواس کا ہاتھ کاٹا جائے گا۔مالک کی چوری میں ہاتھ کاٹنا جائز نہیں کیو نکہ وہ بھی گھر میں رہتا ہے۔ گویا کہ وہ گھر کا ایک فرد ہے او رگھر کے افراد پر گھر سے چوری کی بنا پرحد نہیں لگائی جاتی۔ اس حدیث کی باب سےمناسبت بھی یہی ہے کہ جس طرح گھر کےفرد یاغلام پر چوری کی بنا پر حد نافذ نہیں ہوتی،اسی طرح سرحدی علاقے کے سفر کے دوران میں بھی چوری کی حد نہیں لگائی جائے گی، یعنی یہ بھی اس کی ایک نظیر ہے اگرچہ فرق بھی ہے کہ سفر سے واپسی پرتو حد لگائی جائے گی مگر غلام پر گھر کی چوری میں بالکل حد نہیں لگائی جائے گی۔البتہ اسے کوئی اور سزا دی جائے گی،مثلا:کوڑے لگائے جائیں یا قید وغیرہ کیا جائے۔\n(2)’’بیچ دو،، کیونکہ اس کوچوری کی عادت پڑ گئی ہے،لہذا اس کا گھر میں رہنا اب ٹھیک نہیں۔ یہ مسئلہ بار بار پیدا ہو گا۔ بیج دینا ہی بہتر ہے۔ممکن ہے دوسرے گھر کے حالات اس کی یہ عادت چھڑا دی لیکن بیچتے وقت اس کایہ عیب خریدنے والے کو صاف بتایا جائے تاکہ وہ دھوکے میں نہ رہے ورنہ گناہ ہو گا، نیز سودا واپس بھی ہو سکتا ہے۔\n(3)’’نصف قیمت،، عربی میں لفظ ’’نش،، استعمال کیا گیا ہے جس کے معنی نصف اوقیہ ہوتے ہیں اور مطلق نصف بھی۔ نصف اوقیہ تو بیس درہم کا ہوتاہے۔مطلق نصف سے مراد نصف درہم بھی ہو سکتا ہے اور نصف قیمت بھی۔ تینون معانی ممکن ہیں۔ واللہ اعلم .\n(4) بیچنے کا حکم ضروری نہیں بلکہ بہتر ہے کیو نکہ کسی کوا س کا غلام بیچنے پر مجبور نہیں کیا جا سکتا۔ یہ اس کی اپنی مرضی پر موقوف ہے۔"}],[4981,"عطیہ قرظی رضی اللہ عنہ کہتے ہیں کہ میں بنو قریظہ کے قیدیوں میں تھا، وہ لوگ دیکھتے جس کے زیر ناف کے بال اگ آئے ہوتے، اسے قتل کر دیا جاتا، اور جس کے بال نہ اگے ہوتے، اسے چھوڑ دیا جاتا اور قتل نہ کیا جاتا۔","الألباني: صحيح",{"u2":"حضرت عطیہ رضی اللہ عنہ سے روایت ہے،انھوں نے کہا کہ میں بنو قریظہ کے قید یوں میں شامل تھا۔ (فیصلے کے مطابق)دیکھا جاتا تھا کہ جس قیدی کے زیر ناف بال اگے ہوتےتھے،اس قتل کردیا جاتا تھا اور جسکے زیر ناف بال نہیں اگے ہوتے تھے،اسے زندہ چھوڑ دیا جاتا تھا اور قتل نہیں کیا جاتا تھا۔","f2":"(1)مقصد یہ ہے کہ لڑکا یا لڑکی کس عمر میں بالغ ہوتے ہیں .؟اس کی ضرورت اس لیے پیش آئی کہ شرعی حدیث اور سزائں کسی مجرم پر اس وقت نافذ ہوتی ہیں جب انسان بالغ ہو جائے۔جب تک کوئی شخص بالغ نہیں ہو جاتا اس وقت تک اس پر حد نہیں لگ سکتی۔باقی رہا یہ مسئلہ کہ اگر کوئی نابالغ بچہ ایسا جرم کر بیٹھے جس پر شرعی حد لاگو ہوتی ہو تواس وقت کیا جائے؟ مسئلہ بالکل یہی ہے کہ نابالغ بچے پر شرعی حدنہیں لگ سکتی،تاہم قابل حد جرم سرزد ہونےکی صورت میں قاضی اور جج یا حاکم وقت،ادب سکھانے کی خاطر اسے کوئی مناسب سزادے سکتا ہے۔واللہ اعلم.\n(2)شریعت مطہرہ نے کچھ علامات بتائی ہیں جب ان میں سے کوئی ایک علامت کسی لڑکے یا لڑکی میں پائی جائے تو وہ بالغ ہوتاہے۔ مردوں کے لیے تین علامتیں ہیں، وہ تینوں ہوں یا ان میں سے کوئی ایک ہوتو مرد بالغ سمجھا جائے گا: احتلام ہو نا، زیرناف سخت با ل اگنا یاعمر پندرہ سال ہونا۔ البتہ عورت کے لیے مذکورہ تین علامتوں کے علاوہ،جو کہ مرد اور عورت دونوں میں مشتر ک ہیں، دواور بھی ہیں جو صرف عورتوں کے ساتھ خاص ہیں اور وہ ہیں:حیض آنا کسی عور ت کاحاملہ ہونا۔\n(3)’’بنو قریظہ کے قیدی،، بنو قریظہ مدینہ میں رہنےوالے یہو دیوں کا ایک قبیلہ تھا جنہوں نے جنگ خندق میں مسلمانوں سے بغاوت کرکے حملہ کرنے والے دشمن کا ساتھ دیا،لہذا جنگ خندق ختم ہونے کے بعد انھوں نے اپنا فیصلہ اپنے حلیف قبیلے کے سردار حضرت سعد بن معاذ رضی اللہ عنہ کے سپرد کر دیا۔ انھوں نے فیصلہ دیا کہ ان کے بالغ مرد قتل کردیے جائیں اور عورتیں بچے قید کرلیے جائیں،لہذا ان کےفیصلے کے مطابق عمل ہو ا۔\n(4) میاں بیوی کےسوا کسی کے لیے یہ جائز اور حلا ل نہیں کہ وہ کسی کی شرم گاھ دیکھے، تاہم حقیقی شرعی عذر اس اصول سے مستثنیٰ ہے، مثلا: کسی کی جان بچانے کا مسئلہ در پیش ہو اور آپریشن ناگزیر ہوتو معالج مریض کو ضرورت کے مطابق،بے لباس کرسکتاہے۔ اور پھر ضرورت حتم ہوتے ہی شرم گا ہ کو ڈھانپنا ضروری ہے۔\n(5)’’جس قیدی،،یعنی نوعمر قیدی جس کی بلوعت میں شک ہوتا تھا ورنہ بڑی عمر کے آدمی کے بال دیکھنے کی ضرورت ہی نہیں۔\n(6)’’زندہ چھوڑ دیا جاتا،، یعنی اسے قیدی (غلام)بنالیا جاتا تھا۔ یہ عطیہ بھی ان میں شامل تھے اور بعد میں مسلمان ہو گئے۔ رضی اللہ عنہ۔"}],[4982,"ابن محیریز کہتے ہیں کہ میں نے فضالہ بن عبید رضی اللہ عنہ سے چور کا ہاتھ کاٹ کر اس کی گردن میں لٹکانے کے بارے میں پوچھا تو انہوں نے کہا: یہ سنت ہے، رسول اللہ صلی اللہ علیہ وسلم نے ایک چور کا ہاتھ کاٹا اور اسے اس کی گردن میں لٹکا دیا۔","الألباني: ضعيف",{"u2":"حضرت ابن محیریز سے روایت ہے،انھوں نے کہا کہ میں نے حضرت فضالہ بن عبید رضی اللہ عنہ سے چور کا ہاتھ اسکی گردن میں لٹکانے کے بارے میں پوچھا تو انھوں نے فرمایا (یہ) سنت ہے۔رسول اللہ صلی اللہ علیہ وسلم نے ایک چور کاہاتھ کاٹ کر اس کی گردن میں لٹکا دیا تھا۔"}],[4983,"عبدالرحمٰن بن محیریز کہتے ہیں کہ میں نے فضالہ بن عبید رضی اللہ عنہ سے کہا: کیا چور کا ہاتھ کاٹ کر اس کی گردن میں لٹکانا سنت ہے؟ انہوں نے کہا: ہاں، رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا، تو آپ نے اس کا ہاتھ کاٹا اور اس کی گردن میں لٹکا دیا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: حجاج بن ارطاۃ ضعیف ہیں، ان کی حدیث لائق حجت نہیں ہے۔","الألباني: ضعيف",{"u2":"حضرت عبد الرحمٰن بن محیریز بیان کرتے ہیں کہ میں نے حضرت فضالہ بن عبید رضی اللہ عنہ سے پوچھا فرمائیں کیا چور کا ہاتھ اس کے گلے میں لٹکا نا سنت ہے؟ انہوں نےفرمایا:ہاں۔رسول اللہ صلی اللہ علیہ وسلم نے پاس ایک چور لایا گیا۔آپ نے اس کا ہاتھ کاٹ کر اس کے گلے میں لٹکا دیا۔\nابو عبد الرحمٰن (امام نسائی رح) نے فرمایا:(اس حدیث(اور سابقہ حدیث کا راوی)حجاج بن ارطاۃ ضعیف ہے۔ اس کی حدیث قابل حجت نہیں ہوتی۔"}],[4984,"عبدالرحمٰن بن عوف رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب حد قائم ہو جائے تو چوری کرنے والے پر تاوان لازم نہ ہو گا\"۱؎۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ مرسل (یعنی منقطع) ہے اور صحیح نہیں ہے۔\n§وضاحت\n۱؎: امام ابوحنیفہ کا قول اسی حدیث کے مطابق ہے، لیکن یہ حدیث منقطع ہونے کی وجہ سے ضعیف ہے، جمہور کے نزدیک حد قائم ہونے کے باوجود مسروقہ مال کا تاوان لیا جائے گا کیونکہ ایک مسلم کا مال دوسرے مسلم پر بغیر جائز اسباب کے حرام ہے :(جائز اسباب یعنی: خرید، ہدیہ و ہبہ، وراثت، مشاہرہ وغیرہ ) اس لیے چور سے لے کر چوری کا مال صاحب مال کو واپس کرنا ضروری ہے، اگر موجود ہے تو ٹھیک ہے، ورنہ تاوان لیا جائے گا۔","الألباني: ضعيف",{"u2":"حضرت عبد الرحمٰن بن عوف رضی اللہ عنہ سےروایت ہے کہ رسول اللہ صلی اللہ علیہ وسلمنے فرمایا:’’جب چور پرحد نافذ کر دی جائے تواس پر چور ی کاتاوان نہ ڈالا جائے گا۔،،\nابو عبدالرحمٰن (امام نسائی رح) نے کہا:یہ (حدیث) مرسل ہے اور ثابت نہیں ہے"}],[4985,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: سب سے بہتر عمل کون سا ہے؟ آپ نے فرمایا: \"اللہ اور اس کے رسول پر ایمان لانا\" ۱؎۔\nكتاب الإيمان وشرائعه\n§وضاحت\n۱؎: ایمان کے لغوی معنی تصدیق کے ہیں اور شرع کی اصطلاح میں ایمان یہ ہے: زبان سے اقرار، دل سے تصدیق اور اعضاء و جوارح سے عمل کرنا، نیز ایمان کا طاعت و فرمانبرداری سے بڑھنا اور عصیان و نافرمانی سے گھٹنا سلف کا عقیدہ ہے۔ اور ایمان سب سے بہتر عمل اس لیے ہے کہ تمام اچھے اور نیک اعمال و افعال کا دارومدار ایمان ہی پر ہے، اگر ایمان نہیں ہے تو کوئی بھی نیک عمل مقبول نہیں ہو گا، بہت سی احادیث میں مختلف اعمال کو «أفضل عمل» \" سب سے اچھا کام ) بتایا گیا ہے، تو :(ایمان کے بعد ) پوچھنے والے یا پوچھے جانے کے وقت کے خاص حالات اور پس منظر کے لحاظ سے جواب دیا گیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا:کون سا عمل افضل ہے؟ آپ نے فرمایا:’’اللہ عزوجل اور اس کے رسول پر ایمان لانا،،","f2":"(1)’’ایمان لانا،، یہ عمل ایمان کی جڑ ہےجس کے بغیر ایمان واسلام کے درخت کا تصور بھی نہیں کا جا سکتا۔ اور اس کے بغیر کوئی نیک عمل فائدہ نہیں دیتا۔ جب یہ ایمان موجود ہوتو دخول جنت قطعی ہے، خواہ اولا یا سزا بھگتنے کے بعد۔ اس حدیث میں ایمان کو ایک عمل قرار دیا گیا ہے۔اس سے محد ثین کی تائید ہوتی ہے جو اعمال کو ایمان کا جز قرار دیتے ہیں۔\n(2) قرآنی آیات میں ایمان اور عمل صالح کوالگ الگ ذکر کرنا عمل کی اہمیت کی وجہ سے ہے، جیسے نماز عصر کی اہمیت کے پیش نظر الگ سے بھی اس کی محافظت کا حکم ہے:(حافظوا علی الصلوٰات والصلاۃ الو سطیٰ) (ابقرۃ 2: 238)"}],[4986,"عبداللہ بن حبشی خثعمی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا: کون سا عمل سب سے بہتر ہے؟ آپ نے فرمایا: \"ایسا ایمان جس میں کوئی شک نہ ہو، اور ایسا جہاد جس میں چوری نہ ہو، اور حج مبرور\"۔\n§وضاحت\n۱؎: مقبول حج جس کی نشانی یہ ہے کہ اس کے بعد گناہوں سے بچا جائے۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن حبشی خثعمی رضی اللہ عنہ سے روایت ہے کہ نبی اکر م صلی اللہ علیہ وسلم سے پوچھا گیا:کون سا عمل افضل ہے؟ آپ نے فرمایا:’’ ایسا ایمان جس میں ذرہ بھر شک نہ ہو، وہ جہاد جس میں کسی قسم کی خیانت نہ ہو اور نیک وپاک حج۔","f2":"(1)گویا اصل فضیلت خلوص کو حاصل ہے جس میں بھی ہو۔ ایمان میں ہو یا جہاد میں یا حج میں۔\n(2) افضل عمل کے سوال کے جوابات میں مختلف احادیث آئی ہیں۔تطبیق یہ ہے کہ آپ نے حالات اور سائل کے لحاظ سے جوابات دیے ہیں۔ کسی حالت میں کوئی عمل افضل ہے، کسی میں کوئی۔کسی کے لیے جہاد افضل ہے،کسی کے لیےذکر اور کسی کے لیےحج۔اور کسی کے لیے کو ئی اور عمل افضل ہے۔ یہ بڑی واضح بات ہے۔\n(3)’’نیک وپاک حج،، او رو ہ یہ ہے جس میں کو ئی شہوانی قول وفعل نہ کیا گیا ہو۔کسی فرض کا ترک اور کسی کبیرہ گنا ہ کاارتکاب نہ کیا گیا ہو۔ اور ساتھیوں کے ساتھ لڑائی جھگڑا نہ کیا گیا ہو۔(لا رفث ولا فسوق ولا جدال فی الحج) بعض نے اس کے معنی ’’حج مقبول،، بھی کیے ہیں۔ظاہر حج مقبول بھی توایسا ہی ہوگا، لہذا کوئی فرق نہیں۔"}],[4987,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین چیزیں جس میں ہوں گی، وہ ایمان کی مٹھاس اور اس کا مزہ پائے گا، ایک یہ ہے کہ اللہ اور اس کے رسول اس کے نزدیک سب سے زیادہ محبوب و پسندیدہ ہوں، دوسرے یہ کہ آدمی محبت کرے تو اللہ کے لیے اور نفرت کرے تو اللہ کے لیے، تیسرے یہ کہ اگر بڑی آگ بھڑکائی جائے تو اس میں گرنا اس کے نزدیک زیادہ محبوب ہو بہ نسبت اس کے کہ وہ اللہ تعالی کے ساتھ کسی کو شریک کرے\" ۱؎۔\n§وضاحت\n۱؎: کسی روایت میں \" ایمان کی مٹھاس \" ہے اور کسی میں \" اسلام کی مٹھاس \" ایسی جگہوں میں \" ایمان \" اور \" اسلام \" دونوں کا معنی مطلب ایک ہے یعنی دین اسلام، اور جہاں دونوں لفظ ایک سیاق میں آئیں تو دونوں کا معنی الگ الگ ہوتا ہے۔ :(جیسے حدیث نمبر ۴۹۹۳ میں )۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تین چیزیں ایسی ہیں کہ جس شخص میں بھی پائی جائیں،ایمان اس کو لذیذ معلوم ہوتا ہے۔ (اسےایمان میں مزہ آنے لگتاہے۔)اللہ عزوجل اور اس کا رسول صلی اللہ علیہ وسلم اسے ہر چیز سے زیادہ پیارے ہوں۔ اس کی محبت اور نارضی خالص اللہ تعالی کے لیے ہو۔ عظیم بھڑکتی آگ میں گر پڑنا اسے اللہ تعالی کے ساتھ کسی کو شریک ٹھہرانے سے زیادہ پسند ہو۔،،","f2":"(1)’’ایمان کا مزہ،،یہ تجرباتی چیز ہے کہ جب انسان ایمان میں کھب جائے تو اسے ایمان کے کاموں میں اسی طرح لذت محسوس ہوتی ہے،جیسے عوام الناس کو کھانے،پینے اور نازونعمت کی دیگر چیزوں میں لذت محسوس ہوتی ہے اور وہ ایمان کی وجہ سے اپنے آپ کو اس طرح خوش نصیب تصور کرتا ہے جس طر ح ما لدار شخص اپنے مال کی وجہ سے اپنے آپکوخوش قسمت ستجھتا ہے۔لیکن یہ اس سے کہیں زیادہ اونچا مرتبہ ہے۔ اگر چہ نسبت خاک رابا عالم پاک!\n(2) ’’ پیارے ہوں،، یعنی ان کو ہر چیز پر ترجیح دے مال اور حتیٰ کہ اپنی جان اور خواہش پر بھی۔نتیجہ یہ ہوگا کہ وہ اللہ اور اسکے رسول صلی اللہ علیہ وسلم کی اطاعت کے مقابلے میں ہر چیز کو رج کر دے گا حتی ٰ کہ اپنی ہواہش سے بھی دستبردار ہو جائے گا۔\n(3)’’اللہ تعالی کے لیے ہو،، یعنی اس کے پیش نظر اپنا مفاد ونقصان نہ ہو بلکہ محبت اس لیے کہ اللہ تعالی اور اس کارسول صلی اللہ علیہ وسلم سے پسند کرتے ہیں اور ناراضی اس لیے کہ اللہ اور اس کا رسول اس کو ناپسند کرتے ہیں۔\n(4)’’بھڑکتی آگ،، یعنی شرک سے اسے شدید نفرت ہو جائے حتی کہ جان جانے کا خطرہ ہو تب بھی شرک نہ کر ے۔\n(5) یہ تینوں کام بڑے مشکل ہیں۔ کوئی صاحب ایمان ہی ان پر کار بندرہ سکتا ہے۔اللھم اجعلنا منھم ."}],[4988,"انس بن مالک روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین چیزیں جس میں ہوں گی وہ ایمان کی مٹھاس پائے گا، ایک یہ کہ جو کسی آدمی سے محبت کرے تو صرف اللہ کے لیے کرے، دوسرے یہ کہ اس کے نزدیک اللہ اور اس کے رسول ہر ایک سے زیادہ محبوب و پسندیدہ ہوں اور تیسرے یہ کہ آگ میں گرنا اس کے لیے زیادہ محبوب ہو بہ نسبت اس کے کہ وہ کفر کی طرف لوٹے جب کہ اللہ تعالی نے اسے اس سے نجات دے دی\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ نے بیان فرمایا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص میں یہ تین چیزیں پائی جائیں،وہ ایمان کی مٹھاس محسوس کرتا ہے: جو شخص کسی آدمی سے محبت کرتا ہے کسی مفاد کے لیے نہیں بلکہ صرف اللہ تعالیٰ کی رضا کے لیے۔ جسے اللہ تعالیٰ اور اس کا رسو ل ہر چیز سے زیادہ پیارے ہوں۔ جس شخص کو آگ میں کو د جانا کفر کی طرف لوٹ جانے سے زیادہ پسند ہو جب کہ اللہ تعالیٰ نے اس کو کفر سے نکال لیا ہے۔،،","f2":"’’ایمان کی مٹھاس،، مطلب یہ ہے کہ ایمان میٹھی چیز کی طرح لذیذ ہے۔میٹھے میں لذت محسوس کرنا انسان کی فطرت ہے۔ اسی طرح جو شخص صحیح فطرت انسانی پر قائم ہو، وہ ایمان میں لذت محسوس کرےگا۔ تفصیل بیان ہوچکی ہے۔"}],[4989,"انس رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین چیزیں جس میں پائی جائیں گی وہ اسلام کی مٹھاس پائے گا، ایک یہ کہ جس کے نزدیک اللہ اور اس کے رسول سب سے زیادہ محبوب و پسندیدہ ہوں۔ دوسرے یہ کہ جو آدمی صرف اللہ تعالی کے لیے محبت کرے، تیسرے یہ کہ کفر کی طرف لوٹنا اس طرح ناپسند کرے جس طرح آگ میں گرنا ناپسند کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ نبی اکر م صلی اللہ علیہ وسلم نے فرمایا:’’ تین اوصاف جس سخص میں پائے جائیں،وہ (ان کی برکت سے) اسلام کی مٹھاس محسوس کرےگا۔ وہ شخص جس کو اللہ تعالی ٰ اوراس کا رسول صلی اللہ علیہ وسلم ہر چیز سے زیادہ پیارے ہوں:جوکسی شخص سے صرف اللہ تعالی ٰ کی رضا کے لیے محبت کرے۔ جس شخص کو کفر کی طرف لوٹنا اتنا ناپسند ہو جتنا آگ میں پھنک دیا جانا۔،،","f2":"ایمان کی تشریح میں بیان ہو چکا ہے کہ شرعا اسلام وایمان میں کوئی فرق نہیں۔ یہ حدیث بھی اس کی تائید کرتی ہے۔سابقہ حدیث میں جن اوصاف کو ایمان کی مٹھاس کا دارومدار قرار دیا گیا ہے، اس روایت میں انھی اوصاف کواسلام کی مٹھاس کا سبب بتلایا کیا ہے، گویا ایمان واسلام ایک ہی چیز ہیں۔"}],[4990,"عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ ایک دن ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے، اتنے میں ایک شخص آیا، جس کے کپڑے بہت سفید اور بال بہت کالے تھے، اس پر سفر کے آثار بھی نہیں دکھائی دے رہے تھے اور ہم میں سے کوئی اسے جانتا بھی نہیں تھا، وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر بیٹھا اور اپنے گھٹنے کو آپ کے گھٹنے سے لگا لیا، اپنی ہتھیلیاں آپ کی رانوں پر رکھی، پھر کہا: محمد! مجھے اسلام کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا:\"گواہی دینا کہ اللہ کے سوا کوئی لائق عبادت نہیں اور محمد اللہ کے رسول ہیں، اور نماز قائم کرنا، زکاۃ دینی، رمضان کے روزے رکھنا، اور اگر طاقت ہو تو بیت اللہ کا حج کرنا\"، وہ بولا: آپ نے سچ فرمایا، ہمیں اس پر تعجب ہوا کہ خود ہی آپ سے سوال کرتا ہے اور پھر خود ہی اس کی تصدیق بھی کرتا ہے۔ پھر بولا: مجھے ایمان کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر، اس کے رسولوں پر، آخرت کے دن پر، اور ہر اچھی بری تقدیر پر ایمان لانا\"۱؎۔ وہ بولا: آپ نے سچ فرمایا۔ اس نے کہا: مجھے احسان کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو، اور اگر تم اسے نہیں دیکھ رہے ہو تو وہ تو تمہیں دیکھ رہا ہے\" ۲؎۔ وہ بولا: اب مجھے قیامت کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس سے سوال کیا جا رہا ہے وہ سوال کرنے والے سے زیادہ نہیں جانتا\"۔ اس نے کہا: اچھا تو مجھے اس کی نشانی بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک یہ کہ لونڈی اپنی مالکن کو جنے گی ۳؎۔ دوسرے یہ کہ تم دیکھو گے کہ ننگے پاؤں، ننگے بدن، مفلس اور بکریاں چرانے والے بڑے بڑے محل تعمیر کریں گے\"۔ عمر رضی اللہ عنہ کہتے ہیں: میں تین (دن) تک ٹھہرا رہا ۴؎، پھر مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عمر! تم جانتے ہو پوچھنے والا کون تھا؟\" میں نے عرض کیا: اللہ اور اس کے رسول زیادہ بہتر جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ جبرائیل علیہ السلام تھے، وہ تمہیں تمہارے دین کے معاملات سکھانے آئے تھے\"۔\n§وضاحت\n۱؎: یعنی اس نے ہر اس چیز کا اندازہ مقرر فرما دیا ہے اب ہر چیز اسی اندازے کے مطابق اس کے پیدا کرنے سے ہو رہی ہے کوئی چیز اس کے ارادے کے بغیر نہیں ہوتی۔ ۲؎: یعنی: اگر یہ کیفیت طاری نہ ہو سکے کہ تم اسے دیکھ رہے ہو تو یہ تو یقین جانو کہ وہ تم کو دیکھ رہا ہے، اس لیے اسی کیفیت میں عبادت کرو۔ ۳؎: اس کے کئی معنی بیان کیے گئے ہیں ایک یہ کہ چھوٹے بڑے کا فرق مٹ جائے گا، اولاد اپنے ماں باپ کے ساتھ غلاموں جیسا برتاؤ کرنے لگے گی۔ ۴؎: تین دن، تین ساعت یا تین رات یا چند لمحے۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ نے فرمایا:ایک دن ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر تھے کہ ایک آدمی ہمیں اچانک نظر پڑا۔ اس کے کپڑے انتہائی سفید تھے اور سر کے بال انتہائی سیاہ۔ نہ تو اس پر سفر کے نشانات نظر آتے تھے اور نہ اسے کوئی پہچانتا تھا حتی ٰ کہوہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آکربیٹھ گیا اور اس نے اپنے گھٹنے رسول اللہ صلی اللہ علیہ وسلم کے کھٹنوں کے ساتھ لگادیے۔ اور اپنی ہتھیلیاں آپ کی رانوں پررکھ لیں پھر کہا: اے محمد! مجھے اسلام کے بارےمیں بتلائیں؟ آپنےفرمایا: ’’یہ کہ تو گواہی دے کہ اللہ تعالیٰ کے سوا کوئی عبادت کے لائق نہیں اور حضرت محمد (صلی اللہ علیہ وسلم) اللہ تعالیٰ کے رسول ہیں۔ اور تونماز کی پابندی کرے،زکاۃ ادا کرے، رمضان المبارک کے روزے رکھے اور اگر تو طاقت رکھے تو بیت اللہ کا حج کرے۔،، اس نے کہا: آپ سچ فرماتے ہیں۔ اس پر حیرانی ہوئی کہ یہ آپ سے پوچھتا بھی ہے اور تصدیث بھی کرتا ہے۔ پھر اس نے کہا:آپ مجھے ایمان کے بارےمیں بتلائیں؟ آپ نے فرمایا:’’یہ کہ تو اللہ تعالیٰ پر، اس کے فرشتوں،اس کی کتابوں،اس کے رسولوں،یوم آخرت اور ہر اچھی بری تقدیر پر ایمان رکھے۔،، اس نے کہا: آپ سچ فرماتے ہیں۔ مجھے احسان کے بارےمیں بتلائیں؟ آپ نے فرمایا:’’ یہ کہ تو اللہ تعالیٰ کی عبادت اس طرح کرے گوتواسے دیکھ رہا ہے،پھر اگر تو اسے نہیں دیکھتا تو وہ تجھے دیکھ رہا ہے۔،، اس نے کہا: مجھے قیامت کے بارے میں خبر دیجیے؟ آپ نے فرمایا:’’جس سے پوچھا گیا ہے،وہ پوچھنے والے سے قیامت کا زیادہ علم نہیں رکھتا۔،، اس نے کہا: پھرمجھے اس کی نشانیاں بتلا دیجیے؟ آپ نےفرمایا:’’ (ایک نشانی یہ ہے) کہ لونڈی اپنی مالکہ کو جنے گی اور (دوسری)یہ کہ تو ننگے پاؤں پھر نے والے، ننگے جسم رہنے والے، بکر یوں کے کنگال چرواہوں کو دیکھے گا کہ وہ ایک دوسرے کے مقابلے میں فخریہ انداز میں اونچی عمارتیں بنانے لگے ہیں۔،، (پھر وہ چلا گیا) حضرت عمر رضی اللہ عنہ نے فرمایا: تین دن میں اسی طرح (ششدر) ٹھہرا رہا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ’’عمر!جانتے ہو وہ سائل کو ن تھا؟،، میں نے کہا: اللہ اوراس کارسول ہی خوب جانتے ہیں۔ آپ نے فرمایا: ’’جبریل علیہ السلام تھے۔ تمھیں تمھارے دینی معاملات سکھانے آئے تھے۔،،","f2":"1۔اس حدیث مبارکہ سے یہ مسئلہ ثابت ہوتاہے کہ فرشتہ،انبیاء علیہم السلام کے علاوہ دوسرے لوگوں کے سامنے بھی انسانی شکل وصورت میں آسکتا ہے، لوگ اسے دیکھ سکتے ہیں، وہ ان کی موجودگی میں باتیں کر سکتا ہے اور وہ اس کی باتیں سن بھی سکتے ہیں۔\n(2) یہ شرعا پسندیدہ عمل ہے کہ بن سنور کر،نہا دھو کر اور صاف ستھرے لباس میں ملبوس ہوکر علماء اورملوک وسلاطین کی مجالس میں جایا جائے۔ جبریل امین علیہ السلام رسول اللہ صلی اللہ علیہ وسلم کی خدمت اقدس میں لوگوں کو ان کا دین سکھلانے او ر تعلیم دینے کے لیے ہی آئے تھے اور وہ تعلیم انھوں نےاپنے حال ومقال کے ساتھ دی ہے۔ وہ بہترین اور صاف ستھرے لباس میں ملبوس تھے۔ ان پر تھکاوٹ اور میل کچیل کے کوئی نشان نہیں تھے۔\n(3) اہل علم کی مجلس میں حاضر ہونے والے شخص کے لیے یہ بھی مناسب ہے کہ لوگوں کو کسی مسئلے کی ضرورت ہے اور پوچھ نہیں رہے تو وہ خود پوچھتے تاکہ سب لوگوں کو مسئلے کا علم ہو جائے اور اس طرح ان کی دینی ضرورت پوری ہو۔\n(4) ’’اچانک نظر پڑا،، یعنی دور سے آتا نظر نہیں آتا۔ قریب ہی دیکھا۔ پھر بالوں اور کپڑوں سے اندازہ ہوتا تھا کہ ابھی گھر سےنہا دھو کر نکلا ہےمگر اسے پہچا نتا کو ئی بھی نہیں تھا۔ گویا وہ مسافر تھا۔\n(5) ’’ اپنے گھٹنے،، بے تکلفی کے انداز میں یا شاگردوں کی طرح دو زانو ہو کر بیٹھا۔\n(6)’’آپ کی رانو ں پر،، یعنی رسول اللہ صلی اللہ علیہ وسلم کی رانوں پر جیسا کہ اگلی روایت میں اس کی تصریح ہے۔ اس صورت میں گویا اس نے اپنے آپ کواجڈ بدوی ظاہر کیا کیونکہ یہ انداز ادب کے خلاف ہے۔\n(7)اس حدیث میں اسلام اورایمان کی تعریف مختلف کی گئی ہے۔ گویا لغوی مناسب کا لحاظ فرمایا - اسلام ظاہری کو کہا گیاہے اورا ایما قلبی تصدیق کو۔ ظاہر ہے لغۃ تو ان میں کچھ فرق ہے، البتہ شرعا کوئی فرق نہیں۔\n(7)’’حیرانی ہوئی،، کیونکہ پوچھنا دلیل ہے کہ وہ ناو اقف ہے مگر تصدیق کرنا اسے عالم ظاہر کرتا ہے۔ دراصل اس نےاپنے ہر کام میں ابہام رکھا جس سے حیرانی رہی۔\n(9)’’وہ تجھے دیکھ رہا ہے،، یعنی تیرے اس کو دیکھنے کا بھی یہی مقصود کہ وہ تجھے دیکھتا ہے کیو نکہ جب انسان کو یقین ہو کہ اللہ تعالیٰ مجھے دیکھ رہا ہے تو وہ انتہائی خشوع وحضوع سے عبادت کرے گا۔ اگر اللہ تعالیٰ بندے کو نہ دیکھتا ہو تو اللہ تعالیٰ کو دیکھنے کے تصورسے اتنا خشوع پیدا نہیں ہوگا۔ بعض لوگوں نے یہ مطلب بیان کیاہے کہ احسان کے دو مطلب ہیں: پہلا اور اعلی ٰ تویہ ہے کہ تو عبادت میں یوں سمجھے کہ میں اللہ تعالیٰ کو دیکھ رہا ہوں۔اگر یہ درجہ حاصل نہ ہو سک تودوسرے او ر ادنی ٰ درجہ یہ ہے کہ تو یہ سمجھے کہ اللہ تعالیٰ تجھے دیکھ رہا ہے۔واللہ اعلم .\n(10) ان الفاظ سے یہ بھی معلوم ہوا کہ کوئی شخص دنیوی زندگی میں اللہ تعالیٰ کو نہیں دیکھ سکتا ورنہ ’’گویا کہ،، کہنےکی ضرورت نہیں تھی۔\n(11) ’’زیادہ علم نہیں رکھتا،، یعنی میں تجھ سے قیامت کا زیا علم نہیں رکھتا یا کوئی مسئول کسی سائل سے قیامت کا علم زیادہ نہیں رکھتا۔ مطلب یہ کہ نزول قیامت کے وقت کو کوئی نہیں جانتا۔\n(12) ’’لونڈ ی مالک کو جنے،، بہت سے مطلب بیان کیے گئے ہیں۔ زیادہ مناسب مطلب یہ ہے کہ اولاد نافرمان ہو جائےگی اورماؤں سے لونڈیوں جیسا سلوک کیا جائے گا۔ گویا وہ اولاد نہیں، مالک ہیں۔واللہ اعلم.\n(13) ’’اونچی اونچی عمارتیں،، یعنی غریب لوگ بہت امیر ہو جائیں گے۔ مال عام ہو جائےگا۔تنگ ظرفی کی وجہ سے مال سنبھال نہ سکیں گے۔ عمارتیں بنانے میں ضائع کر دیں گے۔\n(14) ’’ششدر رہا،، کیو نکہ جس طرح وہ اچانک آیا تھا، اسی طرح اچانک غائب ہو گیا۔ لوگوں نےبہت تلاش کیا مگر وہ ملا۔\n(15) اس حدیث کو ’’جدیث جبریل،،کہتے ہیں۔"}],[4991,"ابوہریرہ اور ابوذر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم صحابہ کے درمیان اس طرح بیٹھتے تھے کہ اجنبی آتا تو آپ کو پہچان نہیں پاتا جب تک پوچھ نہ لیتا، ہم نے رسول اللہ صلی اللہ علیہ وسلم سے خواہش ظاہر کی کہ ہم آپ کے بیٹھنے کی جگہ بنا دیں تاکہ جب کوئی اجنبی شخص آئے تو آپ کو پہچان لے، چنانچہ ہم نے آپ کے لیے مٹی کا ایک چبوترہ بنایا جس پر آپ بیٹھتے تھے۔ ایک دن ہم بیٹھے ہوئے تھے اور رسول اللہ صلی اللہ علیہ وسلم اپنی جگہ پر بیٹھے تھے، اتنے میں ایک شخص آیا، جس کا چہرہ سب لوگوں سے اچھا تھا، جس کے بدن کی خوشبو سب لوگوں سے بہتر تھی، گویا کپڑوں میں میل لگا ہی نہ تھا، اس نے فرش کے کنارے سے سلام کیا اور کہا:\"السلام علیک یا محمد\" اے محمد! آپ پر سلام ہو، آپ نے سلام کا جواب دیا، وہ بولا: اے محمد! کیا میں نزدیک آؤں؟ آپ نے فرمایا: آؤ، وہ کئی بار کہتا رہا: کیا میں نزدیک آؤں؟ اور آپ صلی اللہ علیہ وسلم اس سے فرماتے رہے: آؤ، آؤ، یہاں تک کہ اس نے اپنا ہاتھ آپ کے دونوں گھٹنوں کے اوپر رکھا۔ وہ بولا: اے محمد! مجھے بتائیے، اسلام کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسلام یہ ہے کہ تم اللہ کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ ٹھہراؤ، نماز ادا کرو، زکاۃ دو، بیت اللہ کا حج کرو اور رمضان کے روزے رکھو\"۔ وہ بولا: جب میں ایسا کرنے لگوں تو کیا میں مسلمان ہو گیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"، اس نے کہا: آپ نے سچ کہا۔ جب ہم نے اس شخص کی یہ بات سنی کہ \"آپ نے سچ کہا\" تو ہمیں عجیب لگا (خود ہی سوال بھی کرتا ہے اور جواب کی تصدیق بھی)۔ وہ بولا: محمد! مجھے بتائیے، ایمان کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ پر، اس کے فرشتوں پر، کتاب پر، نبیوں پر ایمان رکھنا اور تقدیر پر ایمان لانا\"، وہ بولا: کیا اگر میں نے یہ سب کر لیا تو میں مومن ہو گیا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"، وہ بولا: آپ نے سچ کہا۔ پھر بولا: محمد! مجھے بتائیے، احسان کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"یہ کہ تم اللہ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو، اور اگر تم اسے نہیں دیکھ رہے ہو تو وہ تمہیں دیکھ رہا ہے\"۔ وہ بولا: آپ نے سچ کہا۔ پھر بولا: محمد! مجھے بتائیے کہ قیامت کب آئے گی؟ یہ سن کر آپ نے اپنا سر جھکا لیا اور اسے کوئی جواب نہیں دیا۔ اس نے سوال دہرایا تو آپ نے اسے کوئی جواب نہ دیا، اس نے پھر سوال دہرایا تو آپ نے اسے کوئی جواب نہ دیا پھر آپ صلی اللہ علیہ وسلم نے اپنا سر اٹھایا اور فرمایا: \"جس سے سوال کیا جا رہا ہے وہ قیامت کے آنے کے متعلق سوال کرنے والے سے زیادہ نہیں جانتا۔ البتہ اس کی کچھ نشانیاں ہیں جن سے تم جان سکتے ہو: جب تم دیکھو کہ جانوروں کو چرانے والے بڑی بڑی عمارتیں بنا رہے ہیں اور دیکھو کہ ننگے پاؤں، ننگے بدن پھرنے والے زمین کے بادشاہ ہو رہے ہیں، اور دیکھو کہ غلام عورت اپنے مالک کو جنم دے رہی ہے (تو سمجھ لو کہ قیامت نزدیک ہے)، پانچ چیزیں ایسی ہیں جنہیں اللہ کے سوا کوئی نہیں جانتا، پھر آپ نے «إن اللہ عنده علم الساعة» \"اللہ ہی کے پاس قیامت کا علم ہے\" (سورة لقمان: 34) سے لے کر «إن اللہ عليم خبير» \"اللہ علیم (ہر چیز کا جاننے والا) اور خبیر (ہر چیز کی خبر رکھنے والا) ہے\" کی تلاوت کی، پھر فرمایا: نہیں، اس ذات کی قسم! جس نے محمد کو حق کے ساتھ ہادی و بشارت دینے والا بنا کر بھیجا، میں اس کو تم میں سے کسی شخص سے زیادہ نہیں جانتا، وہ جبرائیل علیہ السلام تھے جو دحیہ کلبی کی شکل میں آئے تھے۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ اور حضرت ابو در رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ میں اس طرح تشریف فرماہوتےتھے کہ کوئی اجنبی آدمی آتا تووہ نہیں پہچان سکتا تھا کہ آپ کون سے ہیں حتی ٰ کہ وہ (آپ کی بابت) پوچھتا، اس لیے ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اجازت طلب کی ہم آپ کے بیٹھنے کے لیے مخصوص جگہ بنا دیں تاکہ اجنبی آدمی آئے تو وہ بھی آپ کو پہچان سکے۔ اجازت ملنے پر ہم نے آپ کے لیے مٹی ایک تھڑا بنا دیا۔ آپ اس پر تشریف فرماتے ہوتے تھے۔ ایک دفعہ ہم بیٹھے تھے اور رسول اللہ صلی اللہ علیہ وسلم بھی اپنے مخصوص مقام پر تشریف فرماتھے کہ ایک انتہائی خوب صورت اور خوشبو میں بسا ہو ا ایک آدمی آیا۔ اس کے کپڑوں کو ہلکاسا میل کچیل بھی نہیں لگا تھا حتیٰ کہ اس نے نیچے بچھی ہوئی چٹائی کے کنارے کےپاس آکر سلام کہا اور کہا: اے محمد!السلام علیکم! آپ علیہ السلام نے اسے جواب دیا۔ اس نے کہا: اے محمد! میں قریب آسکتا ہوں؟ آپ نے فرمایا:’’قریب آجاؤ۔،، وہ بار بار اسی طرح کہتا رہا: اور قریب آجاؤں؟ اور آپ نے فرماتے رہے: ’’قریب آجاؤ۔،، حتی ٰ کہ اس نے اپنا ہاتھ رسول اللہ صلی اللہ علیہ وسلم کے مبارک گھٹنوں پر رکھ دیا اور کہا: اے محمد!مجھے بتائیے: اسلام کیا ہے؟ آپ نے فرمایا،’’اسلام یہ ہے کہ تو خالص اللہ تعالی کی عبادت کر اور اس کے ساتھ کسی چیز کو شریک نہ سمجھے،نماز قائم کر ے، اور زکاۃ اداکرے، بیت اللہ کا حج کرے اور رمضان المبارک کے روزے رکھے۔،، اس نے کہا: جب میں یہ کام کرلوں تو کیا میں مسلمان ہوگیا؟ آپ نے فرمایا:’’ہاں۔،، اسنے کہا: آپ نے سچ فرمایا۔جب ہم نے اس شخص کی یہ بات سنی تو ہم نے اس پر تعجب کیا (پوچھتا بھی ہے اور تصدیق بھی کرتا ہے۔) پھر اس نے کہا: اے محمد فرمائے ایمان کیا ہے؟ آپ نے فرمایا: ’’ ایمان یہ ہے کہ تو اللہ تعالی، اس کے فرشتوں،کتابوں، نبیوں اور تقدیر کو دل وجان سے تسلیم کرے لے۔،،اس نے کہا: جب میں یہ کام کرلوں گا تو کیامیں مومن ہ کیا؟ آپنے فرمایا: ’’ہاں۔،، اسنے کہا: آپ نے سچ فرمایا۔ پھر کہنے لگا: اے محمد! بتلائیے: احسان کیا ہے؟ آپنے فرمایا: ’’احسان یہ ہے کہ تو اللہ تعالی کی عبادت اس طرح کرے گویا تواللہ تعالیٰ کو دیکھ رہا ہے۔ اگر تو اسے نہیں دیکھتا تو وہ تجھے دیکھ رہا ہے۔اگر تو اسے نہیں دیکھتا تو وہ تجھے دیکھ رہا ہے۔،، وہ کہنے لگا: آپ نے سچ فرمایا۔ پھر وہ کہنے لگا:اے محمد! مجھے بتائیے:قیامت کب آئے گی؟ آپ نے سرجھکا لیا اور اسے کچھ جواب نہ دیا۔ اس نے دوبارہ پھر وہی سوال کیا۔ آپ نے پھر کوئی جواب نہ دیا۔ اس نے تیسری دفعہ پھر وہی سوال کیا۔ آپ نے پھر بھی کوئی جواب نہ دیا۔پھر آپ نے اپنا سر مبارک اٹھایا اور فرمایا: ’’جس شخص سے قیامت کے بارے میں پوچھا گیا ہے، وہ پوچھنے والے سے زیادہ نہیں جانتا۔ لیکن قیامت کی کچھ علامات ہیں جن کے ساتھ اس کا پنا چل جائے گا، مثلا: جب تو دیکھے کہ بکر یوں بھیڑوں کے چرواہے عمارتیں بنانے میں ایک دوسرے کا فخریہ انداز میں مقابلہ کر رہے ہیں اور ننگے پاؤں چلنے والے اور ننگے جسم رہنے والے کو زمین کا بادشاہ بنے دیکھے اور دیکھے کہ عورتیں اپنےمالک جننے لگی ہیں (تو پھر قیامت کاانتظار کر)۔ پانچ چیزیں ایسی ہیں جن کا الل تعالیٰ کے سوا کوئی نہیں جانتا۔پھر آپنے یہ آبیت پڑھی (ان اللہ عندہ علم الساعۃ.....) ’’اللہ ہی کو قیامت کا علم ہے .............،، پھر فرمایا:’’ قسم اس ذات کی جس نے محمد (صلی اللہ علیہ وسلم) کو سچا نبی بنایا جو رہنمائی کرنے والا اور خوش خبری دینے والا ہے! تمھاری طرح میں بھی اس آدمی کو پہچان نہیں سکا تھا۔(پھر معلوم ہو اکہ)وہ جبر یل علیہ السلام تھے جو دحیہ کلبی کی صورت میں آئے تھے۔،،","f2":"(1)’’گھٹنوں پر رکھ دیا،، بطور احترام آپ کے گھٹنے چھوئے۔ اور اس میں کوئی حرج نہیں۔\n(2) ’’بھیڑ بکریوں کے چرواہے،، عرب ماحول میں بھیڑ بکریوں کے چرواہوں کو فقیر اور ذلیل خیا ل کیا جاتا ہے، البتہ اونٹوں والوں کو معزز سمجھتے تھے۔یا اس لیے کہ چرواہے عام طور پر غلام اور نوکر ہوتے تھے۔ عربی میں لفظ الرعاء البھم استعمال فرمایا گیا ہے۔ اس کےکئی اور معنی بھی کیے گئے ہیں، مثلا:کالے رنگ کے چرواہے یا غیر معروف چرواہے یا قلاش چرواہے وغیرہ۔\n(3) ’’پہچان نہی سکا تھا،، آنے والے کا انداز ہی ایسا حیران کن تھا کہ آخر وقت تک رسول اللہ صلی اللہ علیہ وسلم کو بھی اندازہ نہ ہوسکا۔ وہ تواس کے غائب ہو جانے سے معلوم ہواکہ یہ تو فرشتہ تھا۔\n(4) ’’دحیہ کلبی کی صورت میں،، یہ الفاظ شاذ ہیں اور سیاق حدیث کے خلاف ہیں۔اصل الفاظ وہی ہیں جو حضرت عمر رضی اللہ عنہ کی روایت میں ہیں لا یعرفہ منا احد کہ اسے ہم میں سے کوئی بھی پہچانتا نہیں تھا۔ اس وضاحت سے معلوم ہو اکہ یہ الفاظ ’’جو دحیہ کلبی کی صورت میں آئے تھے،، درست نہیں کیونکہ اگر وہ حضرت دحیہ رضی اللہ عنہ کی صورت میں آئے ہوتے، پھر تو پہچانے جاتے۔ دیکھیے:ذخیرۃ العقبی ٰ شرح سنن النسائی:37/229)"}],[4992,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے کچھ لوگوں کو عطیہ دیا اور ان میں سے ایک شخص کو کچھ نہیں دیا، سعد رضی اللہ عنہ نے کہا: اللہ کے رسول! آپ نے فلاں فلاں کو دیا اور فلاں کو کچھ نہیں دیا حالانکہ وہ مومن ہے؟ تو نبی آپ نے فرمایا: \"بلکہ وہ مسلم ہے\" ۱؎، سعد رضی اللہ عنہ نے تین بار دہرایا (یعنی وہ مومن ہے) اور نبی اکرم صلی اللہ علیہ وسلم (ہر بار) کہتے رہے: \"وہ مسلم ہے\"، پھر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں بعض لوگوں کو عطیہ دیتا ہوں اور بعض ایسے لوگوں کو محروم کر دیتا ہوں جو مجھے ان سے زیادہ محبوب ہیں، میں اسے اس اندیشے سے انہیں دیتا ہوں کہ کہیں وہ اپنے چہروں کے بل جہنم میں نہ ڈال دیئے جائیں\" ۲؎۔\n§وضاحت\n۱؎: چونکہ ایمان کی جگہ دل ہے اور وہ کسی دوسرے پر ظاہر نہیں ہو سکتا ہے اس لیے کسی کے بارے میں یقینی طور پر یہ دعوی کرنا کہ وہ صحیح معنوں میں مومن ہے \" جائز نہیں اس کو صرف اللہ عالم الغیوب ہی جانتا ہے، اور \" اسلام \" چونکہ ظاہری ارکان پر عمل کا نام ہے اس لیے کسی آدمی کو \" مسلم \" کہا جا سکتا ہے، اس لیے آپ صلی اللہ علیہ وسلم نے سعد رضی اللہ عنہ کو \" مومن \" کی بجائے \" مسلم \" کہنے کی تلقین کی۔ ۲؎: یعنی: جن کو نہیں دیتا ہوں ان کے بارے میں یہ یقین سے جانتا ہوں کہ دینے نہ دینے سے ان کے ایمان میں کچھ فرق پڑنے والا نہیں ہے، اور جن کو دیتا ہوں ان کے بارے میں اندیشہ ہوتا ہے کہ اگر :(تالیف قلب کے طور پر ) نہ دوں تو ایمان سے پھر کر جہنم میں جا سکتے ہیں۔","الألباني: صحيح",{"u2":"حضرت سعد بن ابی وقاص رضی اللہ عنہ نے فرمایا: نبی صلی اللہ علیہ وسلم نے کچھ لوگوں کو مال دیا لیکن ان میں سے ایک آدمی کو کچھ نہ دیا۔ سعد نے کہا: اے اللہ کے رسول! آپ نے فلاں فلاں کو تو مال دیا ہے لیکن فلاں کو کچھ نہیں دیا، حالانکہ وہ بھی صاحب ایمان ہے۔ نبی اکر م صلی اللہ علیہ وسلم نے فرمایا:’’ (بلکہ وہ) مسلمان ہے۔،، سعد نے اپنی بات تین دفعہ دہرائی۔ نبی اکر م صلی اللہ علیہ وسلم ہر دفعہ یہی فرماتے تھے:’’(بلکہ وہ) مسلمان ہے۔،،پھر لوگوں کو مال دیتا ہوں جب کہ ان لوگوں کو چھوڑدیتا ہوں جو مجھے زیا دہ پیارے ہوتے ہیں۔ میں انھیں کچھ نہیں دیتا۔ (دیتا ہوں) اس خوف سے کہ کہیں وہ جہنم میں اوندھے من نہ گرائے جائیں۔،،","f2":"(1)اس حدیث مبارکہ سے معلوم ہوتا ہے کہ ایمان اوراسلام کی حقیقت الگ الگ ہے، یعنی اسلام ظاہری انقیاد واعمال کا نام ہے جبکہ ایمان یقین قلب اور تصدیق لسان کے ساتھ ساتھ کما حقہ ان کے تقاضے پورے کرنے کا نام ہے۔ مطلب یہ ہے کہ ایمان،اسلام سے اعلیٰ وارفع درجہ ہوتا ہے اور اس کا تعلق ظاہری انقیاد کے مقابلے میں ایقان قلب سے زیادہ ہوتا ہے۔\n(2)یہ حدیث مبارکہ اس اہم مسئلے کی طرف بھی رہنمائی کرتی ہے کہ حتمی طور پر کسی شخص کے کامل مومن ہونے کی تصدیق اس وقت تک نہیں کرنی چاہیے جب تک اس پر شارع علیہ السلام کی طرف سے واضح نص نہ ہو۔\n(3) اس حدیث سے مرجئہ گمراہ فرقے کا بھی صریح طور پر رد ہوتا ہے جو یہ عقیدہ رکھتے ہیں کہ صرف زبان سے ایمان کا اقرار کرنے سے انسان جنت میں چلا جائے گا،عمل کرنے کی چنداں ضرورت نہیں۔\n(4) شرعی حاکم کے لیے یہ جائز ہے کہ وہ سرکاری مال میں اپنی صوابدید کے مطابق تصرف کرے، کسی کو دے کسی نہ دے اور کسی کو کم دے کسی کو زیادہ دے، نیز ظاہر ا اہم آدمی کو چھوڑ دے،اس کی نسبت غیر اہم کو دے دے۔ شرعی مصلحت کی بنیاد پر یہ سب کچھ کیا جا سکتا ہے، خواہ رعایا اورعوام الناس پر یہ معاملہ مخفی ہی ہو۔\n(5) حاکم کے ہاں سفارش کرنا درست ہے بشرطیکہ وہ سفارش جائز ہو۔ اسی طرح مقام ومرتبے کے لحاظ سے کم تر شخص،اپنے سے برتر شخص کو مشورہ دے سکتا ہے، تاہم نصیحت اور خیر خواہی کا جذبہ ہو، نیز کسی کے روبرو کہنے کے بجائے تنہائی میں ہو، زیادہ مؤثر ہوتی ہے الا یہ کہ حالات کا تقاضا علانیہ بات کرت کا ہو۔\n(6) ’’(بلکہ وہ)مسلمان ہے،، یعنی تم کسی شخص کی ظاہری حالت ہی کو دیکھتے ہو، لہذا تم ظاہر کی گواہی دو۔ باطن کی اللہ جانے۔بعض نےمعنی کیے ہیں ’’بلکہ مسلمان کہو،، یہ معنی بھی کیے گئے ہیں کہ صرف مومن نہ کہو بلکہ یوں کہو’’وہ مومن یامسلمان ہے۔،، اس صورت میں او عاطفہ ہوگا اور اسے عطف تلقینی کہتے ہیں کہ تم یہ بھی کہو۔ تینوں معانی ٹھیک ہیں۔\n(7)’’خوف سے،، اس کا تعلق شروع جملہ کے ساتھ ہے، یعنی میں کچھ لوگوں کو اس لیے دیتا ہوں کہ ان کا ایمان ابھی کمزور ہے۔ خطرہ ہے کہ مرتد نہ جائیں اور مرتد اوندھے منہ آگ میں گرنے کے مترادف ہے جبکہ پختہ ایمان والے شخص کے بارےمیں کوئی خطرہ نہیں ہوتا،لہذا کبھی اس کو نہیں بھی دیتا تووہ محسوس نہیں کرتا ہے۔ مومن کو مال کی طمع نہیں ہوتی۔مل گیا خیر،نہ ملا تب بھی خیر۔"}],[4993,"سعد رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مال تقسیم کیا تو کچھ لوگوں کو دیا اور کچھ لوگوں کو نہیں دیا، میں نے عرض کیا: اللہ کے رسول! آپ نے فلاں فلاں کو دیا اور فلاں کو نہیں دیا حالانکہ وہ مومن ہے۔ آپ نے فرمایا: \"مومن نہ کہو، مسلم کہو\"۔ ابن شہاب زہری نے یہ آیت پڑھی: «قالت الأعراب آمنا»۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ عنہ سے ر وایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مال تقسیم فرمایا، کچھ لوگوں کو دیا، کچھ کونہ دیا۔ میں کہا: اے اللہ کے رسول! آپ نے فلاں فلاں کو دیا، اور فلاں کونہیں دیا، حالانکہ وہ بھی مومن ہے۔ آپ نے فرمایا: مومن نہ کہو،مسلمان کہو۔،،ابن شہاب (زہری) نے پھر آیت تلاوت کی: (قالت الاعراب اٰ منا) ’’دیہاتی کہتے ہیں ہم ایمان لائے۔،،"}],[4994,"بشر بن سحیم رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ ایام تشریق (۱۰، ۱۱، ۱۲، ۱۳ ذی الحجہ) میں اعلان کر دیں کہ جنت میں مومن کے سوا کوئی نہیں داخل ہو گا ۱؎، اور یہ کہ یہ کھانے پینے کے دن ہیں ۲؎۔\n§وضاحت\n۱؎: یعنی: جنت میں پہلی مرتبہ ہی داخل ہونے کا شرف کامل ایمان والوں کو ہی حاصل ہو گا۔ ۲؎: سال کے سارے ہی دن کھانے پینے کے دن ہوں یہاں مراد یہ ہے کہ خاص طور سے کھانے پینے کے دن ہیں، یعنی ایام تشریق، قربانی کے دن ہیں۔","الألباني: صحيح",{"u2":"حضرت بشربن سحیم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں ایام تشریق میں یہ اعلان کرنے کا حکم دیا کہ جنت میں صرف مومن ہی داخل ہو گا، نیز یہ دن کھانے پینے کے ہیں۔","f2":"(1)’’ایام تشریق،، ذوالحجہ کی 11،12، 13 تاریخ کو کہتے ہیں۔ گویا یہ اعلان حجۃ الوداع کے موقع پرکیا گیا۔\n(2)’’صرف مومن ہی،، جس کا ایمان زبان سے آگے گز کر دل تک پہنچ گیا۔ وہی جنت کامستحق ہے اور گناہ گار مومن کسی نہ کسی وقت جنت میں ضرور جائے گا،البتہ کافر جنت میں نہیں جاسکے گا۔\n(3)’’کھانے پینے کے دن ہیں،،لہذا ان دنوں میں روزہ رکھا جائے۔"}],[4995,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان وہ ہے، جس کی زبان اور ہاتھ سے لوگ محفوظ ہوں، اور مومن وہ ہے جس سے لوگ اپنی جان و مال کے بارے میں اطمینان رکھیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی: کامل مسلم وہ ہے جس کے شر و فساد سے دوسرے مسلمان محفوظ رہیں، یہاں باب ہے \" مومن کی صفات \" اور حدیث میں \" مسلم \" کا لفظ ہے، مطلب یہ ہے کہ اسلام اگر حقیقی ہو گا تو وہ ایمان ہی کا مظہر ہو گا۔","الألباني: حسن صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’اصل مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ ہوں۔ اور اصل مومن وہ ہے جس سے لوگوں کو اپنی جان ومال کے بارے میں کوئی خطرہ نہ ہو،،","f2":"(1)اس حدیث سےمعلوم ہوا کہ مسلمانوں کے مختلف درجے ہیں۔ ان میں سے کچھ تو درجہ کمال کو پہنچے ہوئے ہیں اور کچھ اس کمال تک نہیں پہنچ پائے بلکہ اس سے کسی قدر نیچے ہیں۔\n(2)جانی اور مالی حقوق میں اصل حرمت ہے، یعنی انھیں بغیر کسی شرعی وجہ کے پامال نہیں کیا جاسکتا، تاہم جب جان ومال کے ذریعے سے شرعی تقاضے مجروح کیے جائیں یا انسان اس کا سبب بن رہا ہو تو پھر اس کی حرمت بھی جاتی رہتی ہے،مثلا:اگر کوئی شخص کسی کا ہاتھ کاٹ دے تو قصاص میں ہاتھ کاٹنے والے کا ہاتھ کاٹ دیا جائے گا یا پھر اسے پچاس اونٹ دیت لی جائے گی۔ اس کے بر عکس اگر کوئی شخص ایک ڈھال چرا لے یاتین درہم چرائے تو چور کا ہاتھ کاٹ دیا جائے گا اور وہ بھی دایا ں ہاتھ۔اب ایک ہاتھ کی قیمت توپچاس اونٹ لگی ہے جبکہ دوسرا صرف تین درہم میں کٹ گیا ہے۔ اس کی وجہ یہی ہے کہ پہلا ہاتھ جس کی قیمت پچاس اونٹ لگی ہے وہ معصوم تھا جبکہ دوسرا گناہ گارتھا۔اس نے شرعی تقاضے مجروح کیے، اس کی حرمت خود بخود پامال ہو گئ۔وعلیٰ ھذالقیاس .\n(3) یہاں مسلمان اور مومن سے کامل مسلمان اور کامل مومن مراد ہے ورنہ جس شخص میں یہ اوصاف نہ پائے جائیں، اسے بھی مسلمان اور مومن کہا جائے گا۔دراصل آپ نے لفظی معانی کی طرف تو جہ دلائی ہے۔ اسلام سلامتی سے اور ایمان امن سے ہے،لہذا ہر مسلمان اور مومن کو سلامتی اور امن کا پیکر ہونا چاہیئے۔"}],[4996,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"(حقیقی اور کامل) مسلمان وہ ہے جس کی زبان اور جس کے ہاتھ سے مسلمان محفوظ رہیں، اور (حقیقی) مہاجر وہ ہے جو اللہ تعالی کی منع کی ہوئی چیزوں کو چھوڑ دے\"۔","الألباني: صحيح",{"u2":"۔حضرت عبد اللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ میں نےرسول اللہ صلی اللہ علیہ وسلم کوفرماتے سنا:’’اصل مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ ہوں اور اصل مہاجر وہ ہے جوا ن چیزوں کو چھوڑ دے جن سے اللہ تعالیٰ نے منع فرمایاہے۔،،","f2":"(1)یہ حدیث اس بات کا شوق دلاتی ہے کہ ایک مسلمان شخص کو ہر حال میں یہ کوشش کرنی چاہیے کہ وہ دوسرے مسلمان کو کسی قسم کی ایذا اور تکلیف نہ پہنچائے بلکہ اسے دوسرے مسلمان کے لیے مفید ثابت ہو نا چاہیئے،مضر اور موذی نہیں۔\n(2) امام حسن بصری رح سے ’’ابرار،، نیک وپارس شخص کی تعریف پوچھی گئی تو انھوں نے فرمایا:ھم الذین لا یوذون الذر ولا یرضون الشر، یعنی ابرار وہ لوگ ہوتے ہیں جو چیونٹی تک کو ایذا نہیں پہنچاتے اور معمولی شر اور برائی کو پسند نہیں کرتے۔\n(3) اس حدیث مبارکہ سے مرجئہ گمراہ فرقے کا بھی رد ہوتا ہے جن کا عقیدہ کہ کلمہ پڑھنے کے بعد سب کا اسلام کامل ہی ہوتا ہے،کسی کا نا قص نہیں ہوتا۔\n(4) ’’مہاجر،،ہجرت سےمقصود دین کی حفاظت ہوتی ہے۔ اگر کوئی اپنا گھر بار چھوڑ دے لیکن اللہ تعالی ٰ کی نافرما نی نہ چھوڑے، اس کی ہجرت بے مقصد ہے۔ البتہ جو شخص اللہ تعالی کی نافرمانی چھوڑ دیتا ہے، خواہ وہ اپنے گھر میں ہی رہے، اس نے ہجر ت کا مقصد پورا کر لیا۔ اور اصل مہاجر وہ ہو ا نہ کہ صرف گھر چھوڑنے والا۔"}],[4997,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو ہمارے جیسی نماز پڑھے، ہمارے قبلے کی طرف رخ کرے اور ہمارا ذبیحہ کھائے تو وہ مسلمان ہے\" ۱؎۔\n§وضاحت\n۱؎: یہ اعمال اسلام کے مظاہر اور شرائط ہیں۔ یہ حقیقی بھی ہو سکتے ہیں اور بناوٹی بھی، اگر حقیقی ہوں گے تو یہ ایمان کامل کے مظاہر ہوں گے، اور اگر بناوٹی ہوں گے تو نفاقاً ہو گا، اس حدیث کا یہ مطلب ہرگز نہ لیا جائے کہ جو صرف ان چند متعین اور خاص اعمال کو انجام دے لے وہ مسلمان ہو گیا، یہ باتیں خاص طور پر اس وقت کے یہود و نصاری کے تناظر میں کہی گئی ہیں کیونکہ وہ مسلمانوں کی طرح نماز نہیں پڑھتے تھے، مسلمانوں کے قبلے کی طرف نماز نہیں پڑھتے تھے، اور نہ ہی مسلمانوں کا ذبیحہ کھاتے تھے۔ آج کل کی دیگر غیر مسلم قومیں بھی ایسا نہیں کرتیں، اور بعض نام نہاد مسلمان ان سب اعمال کو انجام دے کر بھی شرک میں مبتلا ہیں تو یہ بھی مسلم نہیں ہیں۔ مگر ان کے ساتھ حرب و مقاطعہ جیسے معاملات سو فیصد اس طرح نہیں کیے جائیں گے جس طرح کھلم کھلا کفار و مشرکین کے ساتھ کیے جاتے ہیں، ان کے لیے دعوت الی الحق اور وعظ و نصیحت ہو گی جب کہ یہود و نصاری اور ہنود و مشرکین کے ساتھ جہاد و قتال ہو گا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ہماری طرح نماز پڑھے اور ہمارے قبلے کی طرف منہ کرے اور ہمار ذبح کیا ہوا جانور کھائے، وہ مسلمان ہے۔،،","f2":"یہ مسلمان کے ظاہری اوصاف ہیں۔ شہادتین کی ادائیگی کے بعد عبادات میں سے نماز ہی ایسی عبادت ہے جو اسلام کی علامت بن سکتی ہے کیو نکہ روزہ مخفی چیز ہے جبکہ زکاۃ ہر کسی پر فرض نہیں۔ ویسے بھی وہ سال میں ایک دفعہ لاگو ہوتی ہے۔ حج تو ہے ہی زندگی میں ایک بار اور وہ بھی ہر ایک پر فرض نہیں۔ پھر نماز چونکہ تمام ادیان میں موجود ہے، اس لیے مسلمانوں کی نماز کا امتیاز قبلے سے ہوگا کیو نکہ ہر دین کا لگ قبلہ ہوتا ہے۔ عبادات کے بعد معاملات اور معاشرت کا درجہ ہے۔کفار کےنزدیک حلال وحرام کا کوئی تصور نہیں تھا، نیز ان کے نزدیک ذبیحہ اور میتہ میں کوئی فرق نہیں تھا۔اللہ تعالیٰ کے نام پر ذبح کرنامسلمان کی خصوصیت ہے،لہذا وہ مسلمان ہے جو اللہ تعالی کے نام پر ذبح شدہ جانور کھائے،خود ذبح کرے یا کوئی اور کرے۔ یہ مسلمانوں کی معاشرتی علامت ہے اور ظاہر ہے۔ باقی علامات مخفی ہیں،اس لیے ان کا ذکر نہیں فرمایا۔واللہ اعلم."}],[4998,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی بندہ اسلام قبول کر لے اور اچھی طرح مسلمان ہو جائے تو اللہ تعالی اس کی ہر نیکی لکھ لیتا ہے جو اس نے کی ہو اور اس کی ہر برائی مٹا دی جاتی ہے جو اس نے کی ہو، پھر اس کے بعد یوں ہوتا ہے کہ بھلائی کا بدلہ اس کے دس گنا سے لے کر سات سو گنا تک ہوتا ہے، اور برائی کا بدلہ اتنا ہی ہوتا ہے\" (جتنی اس نے کی) سوائے اس کے کہ اللہ معاف ہی کر دے (تو کچھ بھی نہیں ہوتا)۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب کوئی شخص مسلمان ہو جائے اور اچھا مسلمان بن جائے تو اللہ تعالیٰ اسکی ہر وہ نیکی (اس کے مامہ اعمال میں)لکھ دیتا ہے جو اس نے اپنے دور جاہلیت میں کی ہوتی ہے۔اور اس کا ہر وہ گناہ معاف کردیا جاتا ہے جو اس نے اس سے پہلے کیا ہو تاہے۔پھر اس کے بعد (اس کو اس کے اعمال کا)بدلہ ملےگا۔ نیکی کا ثواب دس گناہ سے سات سو گنا تک ہو گا اور برائی کا بدلہ برائی کے برابر ہی ہوگا۔ ہاں! اللہ عزوجل چاہے تو اسے بھی معاف فرمادے۔،،","f2":"(1)’’اچھا مسلمان بن جائے،، یعنی اس کا دل بھی اس کی زبان سے موافق ہے جائے اور اس کا اسلام زبان سے گزر کر دل اورتمام جسمانی اعضاء تک پہنچ جائے۔ وہ کھرا،سچا اور سچا مسلمان بن جائے، ظاہر ا بھی اور باطنا بھی،یعنی نہ و ہ منافق رہے اور نہ فاسق۔\n(6)’’لکھ دیتا ہے،،گویا کافر کی نیکیاں تب ضائع ہوتی ہیں جب وہ کفر پر مرتا ہے۔اگر اسے ہدایت مل جائے تواللہ تعالی اسے کی گزشتہ نیکیاں باقی رکھتا ہے۔ یہ اللہ تعالی کا احسان اور فضل وکرم ہے ورنہ نیکی کی قبولیت کے لیے شرط ہے کہ وہ ایمان کی حالت میں ہو،مگر تفضل اور احسان کے لیے کوئی شرط نہیں ہوتی۔ جس طرح نیکی کا بدلہ سات سو گنا تک ملنا بھی اللہ تعالی کا فضل واحسان ہی ہے ورنہ عقل تو اس باب کا تقاضا نہیں کرتی۔\n(3)’’جزاو سزا،، یعنی اسلام لانے سے پہلے کے گناہ تو معاف ہو جاتے ہیں لیکن اسلام لانے کے بعد والے گناہوں کا بدلہ ملےگا، الایہ کہ اللہ تعالی معاف فرمادے تو اس کا فضل ہوگا۔ (لا یسئل عما یفعل وھم یسئلون) (الانبیاء21:23) اور اللہ تعالی کے فضل ہی کی امید رکھنی چاہیے۔"}],[4999,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! کون سا اسلام بہتر ہے؟ آپ نے فرمایا: \"جس کی زبان اور جس کے ہاتھ سے مسلمان محفوظ رہیں\" ۲؎۔\n§وضاحت\n۱؎: یعنی: \" کون سا مسلمان سب سے اچھا ہے ؟ \" یا \" اسلام والا کون آدمی سب سے اچھا ہے \"۔ ۲؎: یہ کئی بار گزر چکا ہے کہ نبی اکرم صلی اللہ علیہ وسلم ہر سائل کے اپنے خاص احوال، یا سوال کے خاص تناظر میں اسی کے حساب سے جواب دیا کرتے تھے، کسی کے لیے کسی عمل پر تنبیہ مقصود تھی تو کسی کے لیے کسی اور عمل کی۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے کہا: اے اللہ کے رسول! کو ن سا اسلام افضل ہے؟ آپنے فرمایا: ’’جس شخص کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں۔،،","f2":"اس باب سے مصنف رح کا مقصود یہ ہے کہ سب مسلمان اسلام وایمان میں برابر نہیں ہو تے بلکہ کسی کا اسلام وایمان زیادہ ہوتا ہے،کسی کا کم۔اور یہ کمی بیشی اعمال کے لحاظ سے بھی ہوتی ہے اور قلبی کیفیت کے لحاظ سے بھی۔’’کو ن سا اسلام افضل ہے،، مطلب یہ ہے کہ اہل اسلام میں سے کون افضل ہے۔"}],[5000,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کون سا اسلام سب سے اچھا ہے؟ آپ نے فرمایا: \"کھانا کھلانا، سلام کرنا ہر شخص کو خواہ جان پہچان کا ہو یا نہ ہو\"۔\n§وضاحت\n۱؎: یعنی: اسلام کا کون سا عمل بہتر اعمال میں سے ہے۔","الألباني: صحيح",{"u2":"حضرت عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کون سا اسلام بہتر ہے؟آپ نے فرمایا:’’تو کھانا کھلائے اور ہر ایک کو سلام کہے،خواہ پہچا نتا ہو یا نہ پہچانتا ہو۔،،","f2":"(1)’’کون سا اسلام بہتر ہے،، یعنی امور اسلام میں سے کو ن سا کام زیا دہ بہتر اور افضل ہے۔\n(2) اس میں جہاں بھوکوں کو کھانا کھلانے کی ترغیب دی گئی ہے وہاں محتاج اور ضرورت مند لوگوں کی دلجوئی کی طرف بھی رہنمائی کی گئی ہے۔ کھانا کھلانے اور دل جوئی کرنا لوگوں کو اپنا گرویدہ بنانے کا ایک تیر بہدف نسخہ ہے۔دیث دار لوگوں،با لخصوص علماء کو اس اہم نکتے کی طرف بھر پور توجہ دینی چاہیے۔\n(3)اس حدیث مبارکہ سے اسلام کی اہمیت واضح ہو تی ہے۔ لوگوں کے دل موہنے اور انھیں اپنے قریب کرنے کے لیے یہ بہت مفید اور مجرب چیز ہے۔سلام کرنے کےلیے چند لوگوں کو خاص نہ کیا جائے جیساکہ متکبر اور جابر قسم کے لوگوں کا طریقہ ہے بلکہ ہر خاص وعام کو سلام کیا جائے کیونکہ تمام اہل ایمان آپس میں بھائی بھائی ہیں، تاہم کسی کافر مشرک اور یہودی وعیسائی کو سلام کرنے میں پہل نہ کی جائے اور نہ کسی فاسق وفاجر کو پہلے سلام کیا جائے،البتہ جس شخص کی اصل حقیقت حال معلوم نہ ہو تواسے مسلمان سمجھتے ہوئے سلام کہنے میں پہل کی جاسکتی ہے۔واللہ اعلم .\n(4)افضل عمل کےمتعلق مختلف روایا ت آئی ہیں۔ یہ اختلاف اشخاص واحوال کے لحاظ سے ہے، لہذا اسے تضاد نہیں کیا جائے گا۔(تفصیل کے لیے دیکھیے حدیث:4989)"}],[5001,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے ان سے کہا: کیا آپ جہاد نہیں کریں گے؟ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"اسلام کی بنیاد پانچ چیزوں پر ہے: یہ گواہی دینا کہ اللہ کے سوا کوئی حقیقی معبود نہیں، اور نماز قائم کرنا، زکاۃ دینی، حج کرنا، اور رمضان کے روزے رکھنا\" ۱؎۔\n§وضاحت\n۱؎: عبداللہ بن عمر رضی اللہ عنہما کا مطلب یہ تھا کہ بنیادی باتوں کو میں تسلیم کر چکا ہوں اور جہاد ان میں سے نہیں ہے، جہاد اسباب و مصالح کی بنیاد پر کسی کسی پر فرض عین ہوتا ہے اور ہر ایک پر فرض نہیں ہوتا۔ یہ نہیں سمجھنا چاہیئے کہ عبداللہ بن عمر رضی اللہ عنہما نعوذ باللہ جہاد فی سبیل اللہ کے منکر تھے، بلکہ آپ تو اپنی زندگی میں دسیوں غزوات میں شریک ہوتے تھے، آپ نے مذکورہ بالا جواب: :(۱ ) ارکان اسلام کو بیان کرنے کے لیے اور :(۲ ) سائل کے سوال کی کیفیت کو سامنے رکھ کر دیا تھا، واللہ اعلم بالصواب۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نےان سے کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سناہے: ’’اسلام کی بنیاد پانچ چیز یں ہیں:گواہی دینا کہ اللہ تعالیٰ کے سوا کے کوئی معبو د نہیں (اور حضرت محمد صلی اللہ علیہ وسلم اللہ تعالیٰ کے رسو ل ہیں۔)نماز پابندی کے ساتھ پڑھنا،زکاۃ اداکر نا،حج کرنا اور رمضان المبارک کے روزے رکھنا۔،،","f2":"(1)باب کامقصد اسلام کے وہ ستون اور ارکان بیان کرنا ہے جن پر اسلام کی ساری عمارت قائم ہے۔ اور وہ صرف پانچ ہیں: ان میں سے پہلا اور سب سے افضل ستون کلمہ تو حید کی شہادت دینا ہے۔ یہ سب سے افضل اس لیے ہے کہ جب تک کافر اس کی شہادت نہ دے تو وہ کافر ہی رہتاہے،مسلمان نہیں بن سکتا۔ مسلمان ہونے کے لیے ضروری ہے کہ زبان سے کلمہ شہادت کا اقرار کرے۔ پھر دوسرے نمبر پر نماز ہے۔ یہ ہر امیر وغریب مردوعورت پر فرض ہے۔\n(2)جواب کا مفاد یہ ہے کہ جہاد فرائض عینیہ میں شامل نہیں بلکہ فرض کفایہ ہے جس کی ادائیگی حکومت وقت کا کام ہے۔وہ جتنے افراد کو مناسب سمجھے، اس کام پر لگائے۔جب ضرورت کے مطابق افراد اس کا م پر مامور ہوں اور وہ ملکی دفاع کا فریضہ سرانجام دے رہے ہوں تو عوام الناس کے لیے جہاد میں جانا ضروری نہیں۔ وہ اپنے دوسرے کام کریں۔ ہاں! یہ ایک فضیلت ہے۔اگر کوئی شخص اپنے فرائض کی ادایگی کے بعد حکومت وقت اور متعلقہ افراد خانہ کی اجازت ورضامندی سے جہاد میں شرکت کرے تو اسے فضیلت ہو گی۔\n(3) یہ پانچ ارکان اسلام ہیں، یعنی فرض عین ہیں۔ شہادتین کی ادائیگی کے بغیر تو کوئی شخص اسلام میں داخل ہی نہیں ہوسکتا۔نماز بھی ہر بالغ وعاقل پر تا حیات فرض ہے،اس سے کسی کو مفرنہیں۔ زکاۃ ہر مالدار شخص پر فرض ہے جس کے پاس اس کی ضرورت سے زائد مال ہو۔(تفصیل پیچھے گزر چکی ہے)\nحج ہر اس شخص پر فرض ہے جو آسانی کے ساتھ بیت اللہ پہنچ سکتا ہو اوراس کے پاس حج سے واپسی تک کے اخراجات موجود ہوں۔رمضان المبارک کے روزے ہر عاقل وبالغ پر فرض ہیں۔ کوئی عذر ہو تو قضا واجب ہوگی اور اگررکھنے کی نہ ہوتو فدیہ واجب ہو گا۔\n(4) رمضان کے روزے کا ذکر آخر میں اس لیے ہے کہ یہ ترکی عبادت ہے (اس میں کچھ کرنا نہیں پڑتا) ورنہ اہمیت کے لحاظ سے اس کا درجہ نماز کے بعد ہے۔ویسے بھی نماز کی طرح بدنی عبادت ہے۔\n(5)تر جمہ میں تو سین والی عبارت اسی حدیث کی دیگر اسانید سے صراحتا مذکورہے۔اس کے بغیر کلمہ شہادت معتبر نہیں۔"}],[5002,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ ہم لوگ ایک مجلس میں نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے تو آپ نے فرمایا: \"تم لوگ مجھ سے اس بات پر بیعت کرو کہ اللہ تعالی کے ساتھ کسی کو شریک نہ کرو گے، نہ چوری کرو گے، نہ زنا کرو گے\"، پھر آپ نے سورۃ الممتحنہ کی آیت پڑھی ۱؎ پھر فرمایا: \"تم میں سے جو اپنے اقرار کو پورا کرے گا تو اس کا ثواب اللہ تعالی کے پاس ہے، اور جو ان میں سے کوئی کام کرے گا پھر اللہ تعالی اسے چھپا لے تو اب یہ اللہ تعالی پر ہے کہ چاہے تو سزا دے اور چاہے تو معاف کر دے\"۔\n§وضاحت\n۱؎: وہ آیت یہ ہے: «يا أيها النبي إذا جائك المؤمنات يبايعنك» :(سورة الممتحنة: 12 )","الألباني: صحيح",{"u2":"حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت ہے،انھوں نے فرمایا: ہم نبی اکرم صلی اللہ علیہ وسلم سے کے پاس ایک مجلس میں موجو د تھے۔ آپ نے فرمایا:’’ مجھ سے بیعت کرو کہ اللہ تعالی ٰ کے ساتھ کسی کو شریک نہیں بناؤ گے، چوری نہیں کرو گے،زنا نہیں کروگے، آپ نے پوری آیت تلاوت فرمائی۔(پھر فرمایا)’’جو شخص اس عہد کو پورا کر ے گا، اس کا اجر وثواب اللہ تعالیٰ کے ذمے ہے۔ اور جس شخص نے ان (مذکورہ کاموں) میں سے کسی کام کا ارتکاب کیا،پھر اللہ تعالیٰ نے اس پر پردہ ڈال دیا تو وہ اللہ تعالیٰ کی مرضی پر موقوف ہوگا۔چاہے اسے عذاب دے، چاہے معاف کرے۔،،","f2":"(1)یہ روایت پیچھے گزر چکی ہے اور ضروری تفصیل بیان ہو چکی ہے۔بعیت سے مراد عہد ہے۔ نیکی کے کاموں پر بیعت رسول اللہ صلی اللہ علیہ وسلم کے بعد صحابہ وتابعین نے کسی ہاتھ پر بھی نہیں کی حتیٰ کہ خلفائے راشدین کے ہاتھ پر بھی نہیں کی،لہذا اس بعیت کی اب ضرورت نہیں۔ اگر چہ عقلی وشرعی طور پر اس میں کو ئی قباحت معلوم نہیں ہوتی مگر صحابہ وتابعین کا اسے مطلقا چھوڑ دینا بھی تو مظبوط دلیل ہے۔\n(2)’’پوری آیت پڑھی،، اس آیت سے سورہ ممتحنہ کی آیت مراد ہے جو عورتوں کی بیعت کے بارے میں اتر ی تھی۔شاید آپنے مؤنث کے صغیے مذکر سے بدل لیے ہوں گے کیو نکہ آپ قرآن تو نہیں پڑھ رہے تھے، عہد لے رہے تھے،لہذا الفاظ میں تبدیلی پر کوئی اعتراض نہیں ہو سکتا۔"}],[5003,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں کفار و مشرکین سے اس وقت تک جنگ کروں جب تک کہ وہ گواہی نہ دیں کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں، پھر جب وہ گواہی دے دیں کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں اور وہ ہماری نماز کی طرح نماز پڑھنے لگیں، ہمارے قبلے کی طرف رخ کریں اور ہمارے ذبیحے کھانے لگیں تو اب ان کے خون اور ان کے مال ہمارے اوپر حرام ہو گئے الا یہ کہ (جان و مال کے) کسی حق کے بدلے میں ہو\" (تو اور بات ہے) ۱؎۔\n§وضاحت\n۱؎: یعنی اگر وہ کسی کا مال لے لیں تو اس کے بدلہ میں ان کا مال لیا جائے گا یا کسی کا خون کر دیں تو اس کے بدلے ان کا خون کیا جائے گا یا شادی شدہ زانی ہو تو اس کو رجم :(پتھر مار کر ہلاک ) کیا جائے گا۔ اس حدیث اور اس مضمون کی آنے والی تمام احادیث :(نمبر ۳۹۸۸ ) کے متعلق یہ واضح رہے کہ ان میں مذکورہ حکم نبوی خاص اس وقت کے جزیرۃ العرب اور اس وقت کے ماحول سے متعلق ہے۔ یہ حکم اتنا عام نہیں ہے کہ ہر مسلمان ہر عہد اور ہر ملک میں اس پر عمل کرنے لگے۔ یا موجودہ دور میں پائی جانے والی کوئی مسلمان نام کی حکومت اس پر عمل کرنے لگے۔ ان احادیث کا صحیح :(پس منظر ) نہ معلوم ہونے کے سبب ہی اس حکم نبوی کے خلاف واویلا مچایا جاتا ہے، «فافھم وتدبر»۔ مؤلف نے اس کتاب و باب میں اس حدیث کو اس مقصد سے ذکر کیا کہ اگر کوئی شہادتوں کے ساتھ ساتھ مذکورہ شعائر اسلام کو بجا لاتا ہو تو اس کا خون دوسرے مسلمان پر حرام ہے، مگر مذکورہ تین صورتوں میں ایسے آدمی کا خون بھی مباح ہے۔\nانس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک جنگ کروں جب تک کہ وہ گواہی نہ دیں کہ اللہ کے سوا کوئی حقیقی معبود نہیں، اور یہ کہ محمد اللہ کے رسول ہیں۔ پھر جب وہ گواہی دیں کہ اللہ کے سوا کوئی حقیقی معبود نہیں اور یہ کہ محمد اللہ کے رسول ہیں اور ہمارے قبلے کی طرف رخ کریں اور ہمارا ذبیحہ کھائیں اور ہماری نماز پڑھیں تو ان کے خون اور ان کے مال ہم پر حرام ہو گئے مگر (جان و مال کے) کسی حق کے بدلے، ان کے لیے وہ سب کچھ ہے جو مسلمانوں کے لیے ہے، اور ان پر وہ سب (کچھ واجب) ہے جو مسلمانوں پر ہے\"۔\nمیمون بن سیاہ نے انس بن مالک رضی اللہ عنہ سے پوچھا: ابوحمزہ! کس چیز سے مسلمان کی جان، اور اس کا مال حرام ہو جاتے ہیں؟ کہا: جو گواہی دے کہ اللہ کے سوا کوئی حقیقی معبود نہیں اور محمد اللہ کے رسول ہیں، اور ہمارے قبلے کی طرف رخ کرے، ہماری طرح نماز پڑھے اور ہمارا ذبیحہ کھائے تو وہ مسلمان ہے، اسے وہ سارے حقوق ملیں گے جو مسلمانوں کے ہیں اور اس پر ہر وہ چیز لازم ہو گی جو مسلمانوں پر ہوتی ہے۔\nانس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے جنگ کروں یہاں تک کہ وہ گواہی دیں کہ اللہ کے سوا کوئی معبود برحق نہیں اور یہ کہ محمد اللہ کے رسول ہیں، پھر جب وہ گواہی دیں کہ اللہ تعالی کے سوا کوئی معبود برحق نہیں اور یہ کہ محمد اللہ کے رسول ہیں اور ہمارے قبلے کی طرف رخ کریں، ہمارا ذبیحہ کھائیں اور ہماری نماز پڑھیں تو ان کے خون اور ان کے مال ہم پر حرام ہو گئے مگر کسی حق کے بدلے، ان کے لیے وہ سب ہے جو مسلمانوں کے لیے ہے اور ان پر وہ سب ہے جو مسلمانوں پر ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’مجھے کفار سے لڑنے کا حکم دیا گیاہے حتی ٰ کہ وہ یہ گواہی دیں کہ اللہ تعالیٰ کے سوا کو ئی معبود نہیں اور حضرت محمد صلی اللہ علیہ وسلم اللہ تعالی کے رسول ہیں اور ہمارے قبلے کی طرف منہ (کر کے نماز قائم)کریں، ہمارا ذبح شدہ جانور کھائیں،ہماری طرح نماز پڑھیں تو ان کے جان ومال ہم پر حرام ہیں،الا یہ کہ ان پر کوئی حق بنتا ہو۔ ان کے وہی حقوق ہوں گے جو مسلمانوں کے ہیں اور ان پر وہ فرائض عائد ہوں گے جو مسلمانوں پر عائد ہوتے ہیں۔،،","f2":"تفصیل کے لیے دیکھسے،احادیث:3971،3972،5000."}],[5004,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ایمان کی ستر سے زائد شاخیں ہیں، حیاء (شرم) بھی ایمان کی ایک شاخ ہے\" ۱؎۔\n§وضاحت\n۱؎: ستر کا عدد عربوں میں غیر متعین کثیر تعداد کے لیے بولا جاتا تھا، اس سے خاص متعین \" ستر کا عدد \" مراد نہیں ہے، اور «بضع» کا لفظ \" تین سے نو \" تک کے لیے بولا جاتا ہے، اور ایمان کی ان شاخوں میں خاص طور پر حیاء کا تذکرہ اس کی اہمیت جتانے کے لیے کیا ہے کہ حیاء ان ستر اعمال پر ابھارنے کا ایک اہم ذریعہ ہے اور اس حیاء سے بھی مراد وہی حیاء ہے جو نیک کاموں پر ابھارے، نہ کہ وہ حیاء جو حق بات کہنے اور اس پر عمل کرنے سے روکے، وہ شرعی حیاء ہے ہی نہیں۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ایمان کی ستر سے زائد شاخیں ہیں اور حیا بھی ایمان کی ایک اہم شاخ ہے۔،،","f2":"(1)یہ حدیث مبارکہ اس بات پر دلالت کرتی ہے کہ اعمال بھی مسمی ’’ایمان،، میں داخل ہیں۔ یہ اہل السنۃ والجماعۃ کا عقیدہ ہے۔ اور یہی حق ہے جبکہ بعض لوگ اس کے قائل نہیں۔\n(2)اس حدیث مبارکہ سے یہ مسئلہ بھی معلوم ہو ا کہ حیا ایمان کی ایک شاخ ہے کیونکہ حیا سے انسان کے اندر نیکی کا جذبہ اور اعمال صالحہ کا داعیہ پیدا ہوتا ہے،ایمان کے منافی امور سے انسان بچتا اور اعلیٰ اخلاق وکردار کاحامل بنتا ہے۔\n(3)ایمان کو درخت سے تشبیہ دی گئی ہے جو کہ جڑ،تنے،ٹہنیوں،شاخوں،پتوں، پھلوں اور پھولوں کے مجموعے کا نام ہے۔ اسی طرح ایمان بھی بہت سے عقائد واعمال اور اخلاق کے مجموعے کانام ہے۔عقیدے کی حیثیت جڑ کی ہے۔ارکان کی حیثیت تنے اور ٹہنیوں کی ہے۔ دیگر اعمال شاخوں اور پتوں کی حیثیت رکھتے ہیں اور اخلاق کی حیثیت پھولوں اور پھلوں کی ہے۔ عقیدے کی خرابی کا اثر اعمال واخلاق میں ظاہر ہوتا ہے جس طرح بیج اور جڑ کی خرابی پودے کی ہر چیز پر اثر انداز ہوتی ہے،اور اعمال کی کمی بیشی درخت کو ناقص بنا دیتی ہے اور اخلاق کی خرابی درخت کی زینت پر اثر ڈالتی ہے۔\n(2)’’ستر سے زائد،،گویا ایمان بہت سے اعمال کے مجموعے کانام ہے۔ ستر کا لفظ کثرت کے لیے بھی بو لا جاتاہے۔زائد کہہ کر مزید کثرت کی طرف اشارہ ہے۔ممکن معین عدد مراد ہو۔ زائد تر جمہ ہے بضع کا جو تین سے نو تک کے عدد پر بولا جاتا ہے۔"}],[5005,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایمان کی ستر سے زائد شاخیں ہیں، ان میں سب سے سب سے بہتر لا الٰہ الا اللہ اور سب سے کم تر راستے سے تکلیف دہ چیز ہٹانا ہے، اور حیاء (شرم) بھی ایمان کی ایک شاخ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ ایمان کی ستر سے زائد شاخین ہیں۔ ان میں سے افضل کلمہ تو حید (ورسالت)کی ادائیگی ہ۔اور ان میں سے کم مرتبہ راستے سے تکلیف دہ چیز کو دور کرنا ہے۔اور حیا بھی ایمان کی ایک (اہم)شاخ ہے۔،،","f2":"(1)’’شاخوں،،سےمراد عقائد واعمال اور اخلاق ہیں\n(2)’’افضل،، کیونکہ اس ک بغیر ایمان معتبر ہی نہیں ہوتا۔\n(3)’’کم مر تبہ،،یعنی درجے اور ثواب کے لحاظ سے یا محبت اور مشقت کے لحاظ سے یا حصول وجود کے لحاظ سے۔\n(4)’’تکلیف دہ،،جسمانی طور پر، جیسے روڑ یے اور کانٹے وغیرہ یا روحانی طور پر جیسے نجاست اور بدبووغیر ہ۔واللہ اعلم."}],[5006,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حیاء (شرم) ایمان کی ایک شاخ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’حیا ایمان کا اہم حصہ ہے۔،،","f2":"حیا و خصلت ہے جو انسان کو قبیح باتوں اور کاموں سے روکتی ہے تا کہ رسوائی نہ ہو۔ لیکن حیا شریعت کے مطابق ہونی چاہئیے،مثلا: طلب علم، حق گوئی اور نیک کام میں حیا نہیں ہونی چاہیئے۔اس حدیث میں حیا کا خصوصی ذکر ہے اس لیے ہے کہ حیا ہرنیکی کرنے اور برائی سے اجتناب کا سبب بنتی ہے جیسا کہ ایک دوسری روایت میں ہے کہ حیا جس چیز میں بھی ہو،ا سے مزین اور خوب صورت بنا دیتی ہے اور جس چیز سےنکل جائے وہ قبیح بن جاتی ہے۔(مسند احمد:3/165،وسنن ابن ماجہ،الزھد،حدیث:4185)"}],[5007,"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عمار کا ایمان ہڈیوں کے پوروں تک بھر گیا ہے\" ۱؎۔\n§وضاحت\n۱؎: اس سے معلوم ہوا کہ عمار رضی اللہ عنہ کا ایمان بعض لوگوں سے زیادہ تھا، اس سے ایک دوسرے کا ایمان میں کم و بیش ہونا ثابت ہوا، سلف کا یہی عقیدہ ہے کہ ایمان میں کمی زیادتی خود ہر آدمی کے حساب سے بھی ہوتی ہے، نیز ایک دوسرے کے مقابلے میں بھی۔","الألباني: صحيح",{"u2":"نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’عمار (رضی اللہ عنہ) کناروں تک ایمان سے لبالب بھرا ہو اہے۔،،","f2":"(1)یہ اٹل حقیقت ہے ک ایمان میں سب مومن ایک جیسے نہیں ہوتے،اس لیے ان کا در جہ اور مرتبہ بھی ایک جیسا نہیں ہوسکتا۔ باب کامقصد بھی یہی ہے کہ ایمان کم وبیش ہوسکتا ہے، نیز جو لوگ ایمانی کایمان جبریل ’’ میرا ایمان حضرت جبر یل علیہ السلام کے ایمان جیسا ہے،، کے قائل ہیں، وہ درست نہیں کہتے۔ ایمان میں کمی بیشی قطعی امر ہے۔ (ایمان کی تفسیر کے لیے دیکھیے،کتا ب الایمان)\n(2) ’’کنا روں تک،، عربی میں لفظ مشاش استعمال کیا گیا ہے جس کے معنی ہڈیوں کے آخر ی کنار ے ہیں،مثلا: کہنیا ں،گھٹنے،ٹخنے،کندھے وغیر ہ۔ اس میں حضرت عمار رضی اللہ عنہ کی عظیم فضلیت ہے کہ خود رسول اللہ صلی اللہ علیہ وسلم ان کےایمان کی تعریف فرمارہے ہیں۔ رضی اللہ عن وارضاہ"}],[5008,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ نے فرمایا: \"تم میں سے کوئی جب بری بات دیکھے تو چاہیئے کہ اسے اپنے ہاتھ کے ذریعہ دور کر دے، اگر اس کی طاقت نہ ہو تو اپنی زبان سے اور اگر اس کی طاقت نہ ہو تو اپنے دل کے ذریعہ اس کو دور کر دے، یہ ایمان کا سب سے کمتر درجہ ہے\"۱؎۔\n§وضاحت\n۱؎: اسی ٹکڑے میں باب سے مطابقت ہے یعنی جو دل کے ذریعہ برائی کو ختم کرے گا وہ ہاتھ اور زبان کے ذریعہ برائی کو دور کرنے والے سے ایمان میں کم ہو گا اور دل کے ذریعہ ختم کرنے کا مطلب یہ ہے کہ اس کو برا جانے اور اس سے دور رہے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسو ل اللہ صلی اللہ علیہ وسلمکو فرماتے سنا: ’’ جو شخص براکام ہوتا دیکھے،وہ اسے اپنے ہاتھ سے ختم کردے اور اگر طاقت نہ ہو تو زبان کے ساتھ روکے اور اگراس کی بھی طاقت نہ رکھتا ہوتو اپنے دل سے برا جانے۔ اور یہ (آخری درجہ) کمزور ترین ایمان ہے۔","f2":"(1)یہ حدیث مبارکہ اس بات کی دلیل ہے کہ امر بالمعروف اور نہی عن المنکر کا فریضہ سرانجام دینا ضروری ہے۔ رسو ل اللہ صلی اللہ علیہ وسلم کا یہ فرمان فلیغیرہ ’’اسے مٹاڈال،، اس کا بین ثبوت ہے۔ لیکن یہ فرضیت فرض کفایہ کے طور پر ہے جیسا کہ اللہ تعالیٰ کا فرمان ہے (ولتکن منکم امۃ یدعون الی الخیر ویامرون بالمعروف وینھون عن المنکر)(آل عمران 3:104)’’تم میں سے ایک جماعت ایسی ہونی چاہیے جو خیر وبھلائی کیطرف بلائے اور وہ نیکی کاحکم دے اور برائی سےروکنے۔،،\n(2)امر بالمعروف اور نہی عن المنکر کافریضہ سر انجام دینے والے کے لیے دوشرطین ہیں:ایک یہ کہ اسے علم ہو کہ جس بات کاوہ حکم دے رہا ہے وہ شرعا ’’ معروف،، یعنی نیکی ہی ہے اور جس بات سے وہ روک رہا ہے، شریعت میں وہ واقعی ’’منکر،، یعنی ناروا اور جائز کام ہے۔ اس سے معلوم ہوا کہ کوئی جاہل یہ فریضہ انجام نہیں دے سکتا۔\n(3)امر بالمعروف اور نہی عن المنکر کے کچھ مراتب ودرجات ہیں:پہلا درجہ یہ کہ برائی کو ہاتھ سے روکا جائے۔ زبان سے روکنا دوسرا درجہ ہے۔ کم زور ترین اور آخری درجہ یہ ہے کہ صرف دل میں برا سمجھے۔ اگر یہ بھی نہیں ہےتو پھر اس کے پلے میں کچھ بھی نہیں۔ایسا شخص ایمان سے خالی ہے، تاہم اس کے لیے حکمت عملی سےکام لینا ضروری ہے۔ لڑائی جھگڑا سے اجتناب ضروری ہے کیونکہ اس کے نقصانات،فوائد سے زیادہ ہیں۔\n(4) ’’اپنے ہاتھ سےختم کرے،، کاطلب ہے کہ اگر وہ صاحب اقتدار ہو کیونکہ عام آدمی قانون ہاتھ میں لینے کی اجازت نہیں ورنہ اس یے انار کی اور بدامنی پیدا ہوگی۔ حدود کانفاذ بھی حکومت وقت کی ذمہ داری ہے۔ افراد انھیں نافذ نہیں کر سکتے اور نہ وہ اس کے مکلف ہیں۔ تبھی نبی اکرم صلی اللہ علیہ وسلم نے استطاعت اور طاقت کی شرط لگائی ہے۔\n(5)’’زبان کے ساتھ،، یہ ہر شخص کی ذمے داری ہے کیونکہ زبان کا استعمال تو ہر شخص کے اختیار میں ہے،الا یہ کہ مرتبہ کم ہو، مثلا اولاد ماں باپ ک سامنے،شاگرد استاد کے سامنے،محکوم حاکم کے سامنے اور غلام آقا کے سامنے بولنے کی طاقت نہیں رکھتے۔یا جب جان جانے کا خطرہ ہو جیسا کہ آگے حدیث میں آرہا ہے۔\n(6)’’کم زور ترین ایمان،، معلوم ہوا ایمان قوی اور کمزور ہو سکتاہے۔یہی باب کامقصد ہے۔ آخری درجے کو کمزور ترین کہنا برائی کے خاتمے کے لحاظ سے ہے، یعنی اس سے برائی ختم ہونے کا امکان بہت کم ہے۔باقی رہا ثواب کے لحاظ سے تو وہ دوسروں کے برابر ہو سکتاہے کیونکہ ہر شخص اپنے مرتبے اورفرائض کے حساب ہی جواب دہ ہے (لا یکلف اللہ نفسا الا وسعھا) (البقرۃ2:286)"}],[5009,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس کسی نے برائی دیکھی پھر اسے اپنے ہاتھ سے دور کر دیا تو وہ بری ہو گیا، اور جس میں ہاتھ سے دور کرنے کی طاقت نہ ہو اور اس نے زبان سے دور کر دی ہو تو وہ بھی بری ہو گیا، اور جس میں اسے زبان سے بھی دور کرنے کی طاقت نہ ہو اور اس نے اسے دل سے دور کیا ۱؎ تو وہ بھی بری ہو گیا اور یہ ایمان کا سب سے ادنی درجہ ہے\"۔\n§وضاحت\n۱؎: یعنی اسے برا سمجھا، اور اس سے دور رہا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص برائی ہوتی دیکھے او راپنے ہاتھ سے روک دے، وہ (گناہ سے)بری ہو گیا۔ جو ہاتھ سے روکنے کی طاقت نہ رکھے اورزبان سے روک دے، وہ بھی (گناہ سے) بری ہوگیا۔اور جو شخص زبان سے روکنے کی طاقت نہ رکھے لیکن دل سے برا سمجھے،وہ بھی (گناہ سے)بری ہے۔ اور یہ کم زور ترین ایمان ہے۔،،","f2":"’’گناہ سے بری ہے،،معلوم ہو ا گناہ ہوتا دیکھنا بھی گناہ ہے الا، یہ کہ اپنا شرعی فریضہ اداکردے۔"}],[5010,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی کا دنیاوی حق کے سلسلے میں جھگڑا اس جھگڑے سے زیادہ سخت نہیں جو مومن اپنے رب سے اپنے ان بھائیوں کے سلسلے میں کریں گے جو جہنم میں داخل کر دیے گئے ہوں گے، وہ کہیں گے: ہمارے رب! ہمارے بھائی ہمارے ساتھ نماز ادا کرتے تھے، ہمارے ساتھ روزے رکھتے تھے، ہمارے ساتھ حج کرتے تھے پھر بھی تو نے انہیں جہنم میں ڈال دیا۔ وہ کہے گا: جاؤ اور ان میں سے جنہیں تم جانتے ہو نکال لو، چنانچہ وہ ان کے پاس آئیں گے اور انہیں ان کی شکلوں سے پہچان لیں گے، ان میں سے بعض ایسے ہوں گے جو آدھی پنڈلی تک جلے ہوئے ہوں گے اور بعض ایسے کہ ٹخنوں تک جلے ہوں گے، چنانچہ وہ انہیں نکالیں گے تو وہ کہیں گے: ہمارے رب! جنہیں نکالنے کا تو نے ہمیں حکم دیا تھا ہم نے انہیں نکال لیا، وہ کہے گا: جس کے دل میں ایک دینار برابر ایمان ہو اسے بھی نکال لو، پھر کہے گا: جس کے دل میں آدھا دینار برابر ایمان ہو یہاں تک کہ کہے گا: جس کے دل میں ذرے کے وزن بھر ایمان ہو\"۔ ابو سعید خدری کہتے ہیں: جسے یقین نہ ہو تو وہ یہ آیت: «إن اللہ لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشائ» سے«عظيما» \"یقیناً اللہ تعالی اپنے ساتھ شریک کئے جانے کو نہیں بخشتا اور اس کے علاوہ جسے چاہے بخش دیتا ہے، اور جو اللہ تعالی کے ساتھ شریک مقرر کرے اس نے بہت بڑا گناہ اور بہتان باندھا\" (النساء: ۴۸) تک پڑھے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ نے فرمایا کہ میں رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:’’تم دنیا میں اپنے حق کی خاطر اتنا نہیں جھگڑتے جتنا جھگڑا مومن اپنے رب تعالی سے اپنے ان مسلمان بھائیوں کے بارے میں کریں گے جوآگ میں داخل کیے جائیں گے۔ وہ (مومن کہیں گے: اے ہمارے رب!یہ ہمارے وہ مسلمان بھائی ہیں جو ہمارے ساتھ نمازیں پڑھتے تھے، روزے رکھتے تھے اور حج کرتے تھے۔تو نے ان کو آگ میں ڈال دیا ہے؟ اللہ تعالی فرمائے گا: جاؤ جنھیں تم پہچانتے ہو، ان کو نکال لاؤ۔ وہ جائیں گے اور ان کی صورتو ں سے پہچانیں گے۔ ان میں سے کسی کو نصف پنڈلیوں تک آگ لگی ہوگی اور کسی کو ٹخنوں تک۔وہ ان کو نکال لائیں گے اور کہیں گے:اے ہمارے رب!جن کے بارےمیں تو نے فرمایا تھا،وہ تو ہم نے نکال لیے۔ اللہ تعالیٰ فرمائے گا: ان کو بھی نکالو جن کے دل میں ایک دینار کے برابر بھی ایمان ہے۔ پھر فرمائے گا: (ان کو بھی نکالو) جن کے دل میں نصف دینار کے برابر ایمان ہے حتی کہ فرائے گا: (ان کو بھی نکالو) جن کے دل میں ذرہ بھر بھی ایمان ہے۔،، حضرت ابو سعید خدری نے فرمایا: جو شخص اس حدیث کی تصدیق میں متد بذب ہو،وہ یہ آیت پڑھ لے (ان اللہ لا یغفر ان یشرک بہ........) ’’یقینا اللہ تعالی ٰ یہ تو معاف نہیں فرمائے گا کہ اس کے ساتھ شریک ٹھہرایا جائے،البتہ اس سے کم دوسرے گناہ جس کو چاہے گا،معاف فرمائے گا......،،آخر آیت تک۔","f2":"(1)اس حدیث مبارکہ سے ثابت ہوا کہ اہل ایمان،یعنی مومن سفارش کریں گے۔ ان کی شفاعت برحق ہے، نیز ان کی سفارش قبول ہوگی۔\n(2)اس حدیث سے باہم محبت کرنے کی فضیلت بھی ثابت ہوتی ہے کہ مومن،اس دن جس مال واولاد کو ئی فائدہ نہیں دیں گے، اپنے مسلمان بھائیوں کے لیے بارگاہ الہٰی میں جھگڑیں گے۔ اس پر انھیں آمادہ کرنے والی چیز باہمی محبت ہوگی جواللہ تعالی کی رضا کے لیے ایک دوسرے سے کیا کرتے تھے۔\n(3)گناہوں اور بداعمالیوں کے تفاوت اور فرق کی بنا پر جہنمیوں کے مابین بھی فرق ہوگا۔کوئی جہنم کے سخت تر ین طبقے میں اور کوئی اس سے کم تر درجے میں، کچھ لوگوں کو نصف پنڈلیوں تک آگ لگی ہوگی اور کچھ کو ٹخنوں تک۔\n(4)اس حدیث سے یہ بھی معلوم ہوتاہے کہ شرک تمام گناہوں سے بڑا گنا ہ ہے۔اس سے بڑاگنا ہ کوئی نہیں۔یہی وجہ ہے کہ شرک کسی صورت معاف نہیں ہوگا۔ اس کے علاوہ جتنے کبیرہ گناہ ہیں ان کی معافی ممکن ہے۔مرنے کے بعد شرک کی معافی ہی نہیں،اس لیے مشرک وکافر ہمیشہ جہنم میں رہیں گے۔ جمہور اہل علم نےاسی آیت کریمہ سے استدلال کیا ہے کہ قاتل کی معافی بھی ممکن ہے۔دیگر کبیرہ گناہوں کی طرح وہ بھی اللہ تعالی کی مشیت کے تحت ہے، اگروہ چاہے تو ناحق قتل کرنے والے قاتل کو بھی معاف فرمادے۔یہی حق ہے جبکہ حضرت عبد اللہ رضی اللہ عنہ ایسے قاتل کی معافی کے قائل نہیں۔کہا جاتا ہے کہ انھوں نے اس سے رجوع کرلیا تھا لیکن تحقیق کی روشنی میں ان کے رجوع کا اثبات مشکال ہے۔واللہ اعلم.\n(6) ’’پہچانیں گے،،گویا آگ ان کے چہر وں کو نہیں لگے گی جیسا کہ آئندہ کلام سے معلوم ہورہا ہے کیونکہ چہرہ تو سجدے کا مقام ہے۔وہ نمازی ہو ں گے۔آگ نماز کے مقامات کو نہیں چھوئے گی یا ان میں بگاڑ پیدانہیں کر سکے گی۔\n(7)’’ہم نے نکال لیے،، مقصد یہ ہے کہ ابھی بہت سے اور مومن بھی آگ میں جل رہے ہیں۔ ان کو بھی نکالنے کاحکم صادر فرمایا جائے۔\n(8)اما م صاحب کامقصد ایمان میں کمی بیشی ثابت کرنا ہے جوحدیث سے واضح ہے۔(دینار کے برابر،نصف دینار کے برابر ذرہ برابر۔)جو لوگ ایمان میں کمی بیشی کے قائل نہیں،وہ یہ کمی بیشی اعمال کی طرف منسوب کرتے ہیں، حالانکہ وہ خوایمان کو دل ہی سے خالص سمجھتے ہیں۔اعمال کا اثر تو اعضاء پر ہوگا۔\n(9)’’دینار،،سونے کاایک سکہ تھا جس کا وزن موجودہ دور کے مطابق چار ماشے چار رتی اور گرام کے حساب 4.374گر ام بنتا ہے۔\n10۔ذرہ سے مراد غبار کا ذرہ ہے۔بعض نے چیونٹی کا معنیٰ بھی کیا ہے۔واللہ اعلم"}],[5011,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک مرتبہ میں سو رہا تھا کہ اسی دوران میں نے خواب دیکھا کہ لوگ مجھ پر پیش کئے جا رہے ہیں اور وہ قمیص پہنے ہوئے ہیں، بعض کی قمیص چھاتی تک ہے، بعض کی اس سے نیچے ہے اور میرے سامنے عمر بن خطاب کو پیش کیا گیا، وہ ایسی قمیص پہنے ہوئے تھے جسے وہ گھسیٹ رہے تھے\"۔ لوگوں نے عرض کیا: اللہ کے رسول! اس کی تعبیر کیا ہے؟ آپ نے فرمایا: \"دین\" ۱؎۔\n§وضاحت\n۱؎: یعنی ان کا ایمان ان کے جسم میں کامل شکل میں رچا بسا ہوا ہے، یہی نہیں بلکہ ان کا ایمان اوروں کی نسبت سے زیادہ پختہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:میں ایک دفعہ سویا ہوا تھا کہ(خواب میں)دیکھا لوگ مجھ پر پیش کیے جا رہے ہیں۔ انہوں نے قمیصیں پہن رکھی ہیں۔بعض(تو اتنی چھوٹی ہیں کہ)پستانوں تک ہی پہنچتی ہیں اور کچھ ان سے نیچی\nہیں۔عمر بن خطاب مجھ پر پیش کیے گئے تو ان پر اتنی لمبی قمیص تھی کہ زمیں پر گھسٹ رہی تھی‘‘صحابہ نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم!آپ نے اس کی کیا تعبیر فرمائی ہے؟ٖپ تے فرمایا:’’دین‘‘","f2":"(1)ایک کام عالم بیداری میں مذموم ہوتو خواب میں وہی کام محمود اور پسند ہو سکتا ہے،مثلا: قمیص نیچے تک گھسیٹنا۔جاگتے ہوئے یہ کام شرعا مذموم اور ناجائز ہے جبکہ نیند میں اسے محمود وپسند یدہ قرار دیا گیا ہے۔یہی وجہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےا س کی تعبیر کمال دین فرمائی ہے۔\n(2)اس حدیث مبارکہ سے خواب کی تعبیر کی مشروعیت ثابت ہوتی ہے،نیز صحیح معبر سے خواب کی تعبیر پوچھی جاسکتی ہے۔\n(3)کی فاضل اور دین دار شخص کی تعریف سامعین کے سامنے کی جاسکتی ہے بشرطیکہ اس فاضل شخصیت کے عجب وتکبر میں مبتلا ہونے کااندیشہ نہ ہو جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت عمر فاروق رضی اللہ عنہ کےمتعلق سامعین کو بتلادیا،نیز اس سے سیدنا عمر بن خطاب رضی اللہ عنہ کی فضیلت بھی ثابت ہوتی ہے۔\n(4)قمیص انسانی بدن کے عیوب ونقائص اور قبائح کی پردہ پوشی کرتی ہے اور انسان کو زینت بخشتی ہے دین بھی انسان کے اخلاقی عیوب کو ختم کرتاہے اور انسان کو مہذب بناتاہے،اس لیے آپ نے قمیص سے دین مراد لیا۔\n(5)محدثین کے نزدیک دین، ایمان اور اسلام ایک ہی چیز کانام ہے،لہذا ایمان کی کمی بیشی کے باب میں دین کا ذکر درست ہے۔اور اس حدیث میں دین کی کمی بیشی صاف ثابت ہورہی ہے۔"}],[5012,"طارق بن شہاب کہتے ہیں کہ یہود کا ایک یہودی عمر بن خطاب رضی اللہ عنہ کے پاس آ کر بولا: امیر المؤمنین! آپ کی کتاب (قرآن) میں ایک آیت ہے، اگر وہ ہم یہودیوں پر اترتی تو (جس روز اترتی) ہم اسے عید کا دن بنا لیتے، کہا: کون سی آیت؟ یہودی بولا: «اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينا» \"آج کے دن میں نے تمہارا دین پورا کر دیا، تم پر اپنی نعمت پوری کر دی اور تمہارے لیے دین اسلام کو پسند کیا\"(المائدہ: ۳)۔ عمر رضی اللہ عنہ نے کہا: مجھے وہ مقام جہاں یہ اتری وہ مقام معلوم ہے، وہ دن معلوم ہے جب یہ نازل ہوئی، یہ جمعہ کے دن عرفات میں رسول اللہ صلی اللہ علیہ وسلم پر نازل ہوئی۔\n§وضاحت\nیہ آیت بھی ایمان کے گھٹنے اور بڑھنے پر دلالت کرتی ہے، اس طرح کہ دین اسلام دیگر ادیان کے مقابلے میں کامل ہے، اور کامل کا ضد ناقص ہوتا ہے، تو اہل اسلام کا ایمان اگلی امتوں سے زیادہ ہوا۔","الألباني: صحيح",{"u2":"حضرت طارق بن شہاب رحمہ اللہ سے مروی ہے کہ ایک یہودی شخص حضرت عمر بن خطاب رضی اللہ عنہ کے پاس آیا اور کہا:اے امیر المومنین!تمھاری کتا ب (قرآن مجید)میں ایک آیت ہے جسے تم پڑ ھتے ہو اگر وہ ہم یہودیوں پر نازل ہوئی تو ہم اس (کے نزول)کے دن کے تہوار بنا لیتے۔حضرت عمر رضی اللہ عنہ نے فرمایا: کون سی آیت؟اس نے کہا(الیوم اکملت لکم دینکم .....)’’آج میں نے تمھارے لیے تمھارا دین مکمل کردیا اور اپنا احسان تم پر پورا کر دیا اور تمھارے لیے اسلام کو دین کے طور پر پسند فرمایا۔،،حضرت عمر رضی اللہ عنہ نے فرمایا: میں اس جگہ کو بھی جانتا ہوں جس میں یہ آیت اتری ہے اور اس دن کو بھی۔ یہ آیت رسول اللہ صلی اللہ علیہ وسلم پر بہ مقام عرفات جمعۃ المبارک کے دن اتری۔","f2":"(1)’’تہوار بنالتیے،، کیونکہ کسی امت کے لیے تکمیل دین ایک بہت بڑا اعزاز وانعام ہے جو امت محمد یہ کو نصیب ہوا۔\n(2)’’جانتا ہوں،، یعنی ہمارے ہاں وہ دن ہی تہوار نہیں بلکہ مقام نزول بھی قیامت تک کے لیے عید گاہ بن چکا ہے۔یقینا ہر سال اس مقام پر اس دن اتنا بڑا اجتماع کسی اور قوم کے تصور میں بھی نہیں آسکتا۔والحمد للہ علی ذلک.\n(3)’’مکمل فرمایا،، گویا پہلے ناقص تھا۔اور دین کی کمی بیشی ایمان کی کمی بیشی کو مستلزم ہے کیونکہ دین کے ہر حصے پر ایمان لانا ضروری ہے۔"}],[5013,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی مومن نہیں ہو سکتا جب تک کہ میں اس کے اپنے بال بچوں، اس کے ماں باپ اور تمام لوگوں سے زیادہ اسے محبوب نہ ہو جاؤں\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں اور باب کی دیگر حدیثوں میں جن جن اعمال کا بطور ایمان کی نشانی ذکر کیا گیا ہے وہ سب دل میں بیٹھے پختہ ایمان کا ہی نتیجہ ہیں اس لیے ان کو \" ایمان کی نشانی \" کہا گیا ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم میں سے کوئی شخص صاحب ایمان نہیں ہوسکتا حتیٰ کہ میں اسے اس کی اولاد،ماں باپ اور سب لوگوں سے زیادہ پیارا نہ ہوجاؤں۔،","f2":"(1)امام نسائی رحمہ اللہ نے جو عنوان قائم کیا ہے اس کا مقصد یہ بیان کرنا ہے کہ رسول کریم صلی اللہ علیہ وسلم کے ساتھ سب سے زیادہ بڑھ کرمحبت کرنا آدمی کے کمال ایمان کی علامت اور دلیل ہے۔\n(2)’’زیادہ پیارا،،یہاں محبت سے عقلی محبت مراد ہے جس کا دوسرا نام اطاعت ہے۔ویسے بھی محبت کا علم اطاعت کے ذریعے ہی ہوتا ہے۔ محبت تو مخفی چیز ہے جس کا جھوٹا دعوی ٰ بھی کیا جاسکتا ہے۔محبت کی تصدیق اطاعت ہی سے ہوتی ہے۔ارشاد باری تعالی ہے ({ قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي [آل عمران:،3 31)مطلب یہ ہے کہ اگر رسول اللہ صلی اللہ علیہ وسلم کے فرمان اور اپنی اولاد یا اپنی دلی خواہش کےمابین تصادم پیدا ہو تو بہر صورت رسول اللہ صلی اللہ علیہ وسلم کے فرمان ہی کو ترجیح دی جائے۔فداہ ابی ونفسی وروحی صلی اللہ علیہ وسلم)"}],[5014,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی مومن نہیں ہو سکتا جب تک کہ میں اس کے بیوی بچوں، اس کے مال اور تمام لوگوں سے زیادہ اسے محبوب نہ ہو جاؤں\"۔","الألباني: صحيح",{"u2":"حضرت انس صلی اللہ علیہ وسلم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تم میں سے کوئی شخص مومن نہیں بن سکتا حتی کہ میں اسے اس ہل وعیال اور مال ومنال اور سب لوگوں سے بڑھ کر محبوب نہ ہو جاؤں۔،،"}],[5015,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس ذات کی قسم، جس کے ہاتھ میں میری جان ہے! تم میں سے کوئی مومن نہیں ہو سکتا جب تک کہ میں اس کے بال بچے اور اس کے ماں باپ سے زیادہ اسے محبوب نہ ہو جاؤں\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے:’’قسم اس ذا ت کی جس کے ہاتھ میں میری جان ہے!تم میں سے کوئی شخص مومن نہیں ہوسکتا جب تک اس کے نزدیک اس کی اولاد اور والدین سےبڑھ کر محبوب نہ بن جاؤں۔،،"}],[5016,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی مومن نہیں ہو سکتا جب تک کہ وہ اپنے بھائی کے لیے وہی پسند نہ کرے جو اپنے لیے پسند کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سےمروی ہےکہ اللہ کے نبی صلی اللہ علیہ وسلم کا فرمان مبارک ہے:’’تم میں سے کوئی شخص سچا مومن بن سکتا حتی کہ وہ اپنے بھائی کے لیے وہی چیز پسندکرےجو وہ اپنے لیےکرتا ہے","f2":"(1)اس حدیث مبارکہ سےیہ معلوم ہوا کہ ایسا کرنے والا شخص متواضع ہوتاہے۔جب کوئی شخص اپنے مسلمان بھائی نیکی اور اچھائی کے وہی جذبات واحساسات رکھتا ہو جو وہ اپنے لیے رکھتا ہےاور اپنے مسلمان بھائی کےلیے بھی وہی کچھ پسند کرتا ہو جواپنےلیے کرتا ہے تو یہ عمل اور جذبہ اس بات کی دلیل ہے کہ ایسا کرنے والا شخص نہ متکبر ہے اور نہ کینہ پرورہی۔ایسے شخص کے دل میں کسی کے لیے نہ حسد اور بغض کی بیماریاں پل رہی ہوتی ہیں اور نہ اس کے دل میں کسی قسم کا کوئی کھوٹ اور منفی جذبہ ہی ہوتا ہے۔ یہ شخص تمام مذموم اور گھٹیا خصائل سے کوسوں دور اور خصائل حمیدہ کا پیکر ہوتا ہے۔ایسے شخص کے اخلاق انتہائی کریمانہ ہوتے ہیں۔اللہ تعالیٰ ہمیں بھی ایسی صفات جلیلہ کاحامل دل عطا فرمائے۔آمین.\n(2)’’وہی چیز،،یعنی اس جیسی کیونکہ وہی چیزتو ہر وقت نہیں دی جاسکتی اور ٹہ یہ ممکن ہے۔\n(3)سابقہ احادیث میں رسول اللہ صلی اللہ علیہ وسلم کی محبت کوایمان کی نشانی بتلایا گیا تھا اور یہاں خلوص اور خیر خواہی کو۔گویا یہ دونوں نشانیاں ہیں۔آگے مزید بھی آرہی ہیں۔ ان میں کوئی تناقض نہیں۔ یہ سب ایمان کے ثمرات ہیں،نیز یادرہے کہ کمال ایمان کے لیے ہیں۔"}]]);
